/*
 * MLX91219 Hall-Effect Current Sensor Reader for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MLX91219 analog output -> ADS1115 AIN0
 *   - ADS1115 ADDR -> GND (I2C address 0x48)
 *   - ADS1115 SDA -> GPIO2 (BCM)
 *   - ADS1115 SCL -> GPIO3 (BCM)
 *
 * Build: gcc -O2 -Wall -o mlx91219_reader mlx91219_reader.c -ladl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   0x8000  /* Begin single conversion */
#define ADS1115_CFG_MUX_AIN0   0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096 0x0200  /* ±4.096 V range */
#define ADS1115_CFG_MODE_SS   0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128    0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

#define SAMPLE_INTERVAL_US   500000  /* 500 ms */
#define ADC_MAX_VALUE        32767.0 /* 16-bit signed positive max */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */
/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio i2cWriteWordData sends the data as [low_byte, high_byte],
 * which is correct for the ADS1115.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio i2cReadWordData returns the data as [low_byte, high_byte],
 * which is correct for the ADS1115.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error selecting ADS1115 register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success and stores the signed 16-bit value in *out;
 * returns -1 on I2C or conversion error.
 */
static int ads1115_read_ain0(int handle, int16_t *out)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    /* Convert to signed 16-bit two's complement */
    if (raw & 0x8000)
        *out = (int16_t)(raw | 0xFFFF);
    else
        *out = (int16_t)raw;

    return 0;
}

/* --------------------------- Sensor reading ----------------------------- */
static float read_current(int handle)
{
    int16_t raw;
    if (ads1115_read_ain0(handle, &raw) != 0) {
        fprintf(stderr, "Failed to read ADS1115 conversion.\n");
        return -1.0f;
    }

    /* Convert raw ADC value to current (V -> A) */
    float voltage = (float)raw / ADC_MAX_VALUE * 4.096f;
    float current = voltage / 0.001f;  /* MLX91219: ~0.001 V/A */

    return current;
}

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("MLX91219 Hall-Effect Current Sensor Reader\n");
    printf("ADS1115 on I2C bus %d, address 0x%02X, AIN0\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        float current = read_current(g_i2c_handle);

        if (current >= 0.0f) {
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

