#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define TEMPERATURE_THRESHOLD 60.0f
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error reading flame sensor on GPIO%d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return level;
}

static int read_temperature(void) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    float voltage = (raw * 4.096f) / 32768.0f;
    float temperature = (voltage - 0.5f) * 100.0f;

    if (temperature < -40.0f || temperature > 125.0f) {
        fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
        return -1;
    }

    return (int)temperature;
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(BUZZER_DURATION_MS * 1000);
    gpioWrite(BUZZER_GPIO, 0);
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting flame sensor GPIO%d as input\n", FLAME_SENSOR_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting buzzer GPIO%d as output\n", BUZZER_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing buzzer GPIO%d to LOW\n", BUZZER_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file fire_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_level = read_flame_sensor();
        int temperature = read_temperature();

        if (flame_level < 0 || temperature < 0) {
            log_event("Error reading sensor data");
        } else {
            if (flame_level == 1 && temperature > TEMPERATURE_THRESHOLD) {
                log_event("Flame detected!");
                activate_buzzer();
            } else if (flame_level == 1) {
                log_event("Flame detected!");
            } else if (temperature > TEMPERATURE_THRESHOLD) {
                log_event("Temperature exceeds threshold!");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

