/*
 * MLX91219 Current Sensor Monitor with MCP3008 ADC and Fan Control
 * Board: Raspberry Pi 5
 * SPI:   spidev0.0 (CE0), 1 MHz, mode 0, 8-bit words
 * ADC:   MCP3008 on SPI0 CE0, channel 0
 * Fan:   GPIO18 (BCM), active HIGH
 *
 * Build: gcc -O2 -Wall -o current_monitor current_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023

#define FAN_GPIO_CHIP   "gpiochip4"   /* Pi 5 main GPIO controller */
#define FAN_GPIO_LINE   18

#define CURRENT_THRESHOLD 10.0f
#define LOG_FILE         "current_log.txt"
#define SAMPLE_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/*
 * Convert ADC value to current in milliamperes.
 * MLX91219: 0–1023 counts -> -40–125 °C.
 */
static float adc_to_current_ma(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return -40.0f + ((float)adc_value / (float)ADC_MAX_VALUE) * 165.0f;
}

static void log_current(float current_ma)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Current: %.2f mA\n", timestamp, current_ma);
    fclose(fp);
}

static int control_fan(struct gpiod_line *fan_line, float current_ma)
{
    int target = (current_ma > CURRENT_THRESHOLD) ? 1 : 0;

    if (gpiod_line_set_value(fan_line, target) < 0) {
        fprintf(stderr, "Failed to set fan GPIO value: %s\n", strerror(errno));
        return -1;
    }

    printf("Fan %s (current %.2f mA)\n",
           target ? "ON" : "OFF", current_ma);
    return 0;
}

int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device '%s': %s\n",
                SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

