#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define CO_RAW_MIN 0
#define CO_RAW_MAX 32767
#define CO_PPM_MIN 0.0
#define CO_PPM_MAX 1000.0
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115_raw(int handle, int16_t *raw_out) {
    char config[3];
    char buf[2];
    int16_t value;

    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }

    value = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_out = value;
    return 0;
}

static double raw_to_ppm(int16_t raw) {
    double ratio = (double)raw / (double)(CO_RAW_MAX - CO_RAW_MIN);
    double log_ratio = log10(ratio);
    double ppm = CO_PPM_MIN + (log_ratio - 0.0) * (CO_PPM_MAX - CO_PPM_MIN) / 4.0;
    return ppm;
}

static int log_data(double ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (read_ads1115_raw(i2c_handle, &raw) != 0) {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n",
                    SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        double ppm = raw_to_ppm(raw);

        if (log_data(ppm) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("CO: %.2f ppm\n", ppm);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

