        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, flame_presence, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
