#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MICS4514_ADDR 0x5A
#define CO_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(void);
int read_mics4514_data(uint16_t *co_value, uint16_t *no2_value);
float convert_ox_to_co_ppm(uint16_t ox_value);
void log_co_data(float co_ppm);
void check_threshold_and_log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from MICS-4514 sensor
int read_mics4514_data(uint16_t *co_value, uint16_t *no2_value) {
    char buffer[4];
    int result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes for CO (bytes 0 and 1)
    *co_value = ((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1];

    // Combine the two bytes for NO2 (bytes 2 and 3)
    *no2_value = ((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3];

    return 0;
}

// Convert OX value to CO concentration in ppm
float convert_ox_to_co_ppm(uint16_t ox_value) {
    // Example conversion formula (adjust based on datasheet)
    return (float)ox_value * 0.01f;
}

// Log CO data to file
void log_co_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, CO: %.2f ppm\n", timestamp, co_ppm);
    fclose(fp);
}

// Check threshold and log alert
void check_threshold_and_log_alert(float co_ppm) {
    if (co_ppm > CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening alert log file: %s\n", strerror(errno));
            return;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        fprintf(fp, "%s, CO ALERT: %.2f ppm\n", timestamp, co_ppm);
        fclose(fp);

        printf("CO ALERT: %.2f ppm\n", co_ppm);
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t co_value, no2_value;

        if (read_mics4514_data(&co_value, &no2_value) == 0) {
            float co_ppm = convert_ox_to_co_ppm(co_value);
            log_co_data(co_ppm);
            check_threshold_and_log_alert(co_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", READ_INTERVAL_SEC);
        }

        // Wait for the specified interval
        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
    }

    // Cleanup
    cleanup();
    printf("Air quality monitoring stopped.\n");

    return 0;
}

