/*
 * Raspberry Pi 4 Model B – Dual IMP23ABSU MEMS Microphone Logger
 *
 * Wiring:
 *   IMP23ABSU OUT1 -> GPIO2 (BCM2)
 *   IMP23ABSU OUT2 -> GPIO3 (BCM3)
 *   I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 *
 * Build: gcc -O2 -Wall -o audio_logger audio_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "audio_log.txt"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define MAX_RETRIES    3

/* IMP23ABSU register addresses */
#define REG_OUT1_MSB   0x00
#define REG_OUT1_LSB   0x01
#define REG_OUT2_MSB   0x02
#define REG_OUT2_LSB   0x03

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian value from two consecutive registers.
 * Returns 0 on success, -1 on error.
 */
static int read_audio_sample(int fd, uint8_t reg_msb, uint8_t reg_lsb, int16_t *out)
{
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg_msb, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_msb, strerror(errno));
        return -1;
    }

    /* Read two bytes */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg_msb, strerror(errno));
        return -1;
    }

    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_db(int16_t sample)
{
    /*
     * IMP23ABSU OUT1: 0–3.3 V, 16-bit signed, 0.001 V/LSB.
     * OUT2: 0–3.3 V, 16-bit signed, 0.001 V/LSB.
     *
     * Convert to decibels:
     *   db = 20 log10(abs(sample) / 3.3)
     */
    double abs_sample = (double)abs(sample);
    double db = 20.0 * log10(abs_sample / 3.3);
    return db;
}

static int log_data(double avg_db)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, avg_db) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * IMP23ABSU requires a device-specific initialization sequence.
     * The datasheet provides a simplified example; in a real implementation
     * the device would be addressed via a slave address register (0x00).
     */
    if (ioctl(fd, I2C_SLAVE, 0x00) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x00: %s\n",
                strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int16_t sample1 = 0, sample2 = 0;
        int ok1 = 0, ok2 = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_audio_sample(fd, REG_OUT1_MSB, REG_OUT1_LSB, &sample1) == 0) {
                ok1 = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok1) {
            fprintf(stderr, "Failed to read sample from OUT1 after %d attempts.\n",
                    MAX_RETRIES);
            sample1 = -999;
        }

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_audio_sample(fd, REG_OUT2_MSB, REG_OUT2_LSB, &sample2) == 0) {
                ok2 = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok2) {
            fprintf(stderr, "Failed to read sample from OUT2 after %d attempts.\n",
                    MAX_RETRIES);
            sample2 = -999;
        }

        double avg_db = (ok1 && ok2) ? (calculate_db(sample1) + calculate_db(sample2)) / 2.0 : -999.0;

        if (log_data(avg_db) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

