    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, avg_db) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * IMP23ABSU requires a device-specific initialization sequence.
     * The datasheet provides a simplified example; in a real implementation
     * the device would be addressed via a slave address register (0x00).
     */
    if (ioctl(fd, I2C_SLAVE, 0x00) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x00: %s\n",
                strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int16_t sample1 = 0, sample2 = 0;
        int ok1 = 0, ok2 = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_audio_sample(fd, REG_OUT1_MSB, REG_OUT1_LSB, &sample1) == 0) {
                ok1 = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok1) {
            fprintf(stderr, "Failed to read sample from OUT1 after %d attempts.\n",
                    MAX_RETRIES);
            sample1 = -999;
        }

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_audio_sample(fd, REG_OUT2_MSB, REG_OUT2_LSB, &sample2) == 0) {
                ok2 = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok2) {
            fprintf(stderr, "Failed to read sample from OUT2 after %d attempts.\n",
                    MAX_RETRIES);
            sample2 = -999;
        }

        double avg_db = (ok1 && ok2) ? (calculate_db(sample1) + calculate_db(sample2)) / 2.0 : -999.0;

        if (log_data(avg_db) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

