#include <math.h>
#include <pigpio.h>

#define LED_PIN 27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_CHANNELS 2
#define SAMPLE_RATE 1000
#define WINDOW_SIZE_MS 100
#define THRESHOLD_RMS 100.0
#define LED_ON_TIME_MS 500
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE)
#define WINDOW_SAMPLES (WINDOW_SIZE_MS * SAMPLE_RATE / 1000)

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double val = (double)samples[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / num_samples);
}

static void log_event(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file);
}

static void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > THRESHOLD_RMS || mic2_rms > THRESHOLD_RMS) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(LED_ON_TIME_MS * 1000);
        gpioWrite(LED_PIN, 0);
    }
}

