    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open audio_events.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int mic1_samples[WINDOW_SAMPLES];
    int mic2_samples[WINDOW_SAMPLES];
    int mic1_index = 0;
    int mic2_index = 0;

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(1);

        if (sample1 < 0 || sample2 < 0) {
            fprintf(stderr, "Error reading ADC samples, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        mic1_samples[mic1_index] = sample1;
        mic2_samples[mic2_index] = sample2;

        mic1_index = (mic1_index + 1) % WINDOW_SAMPLES;
        mic2_index = (mic2_index + 1) % WINDOW_SAMPLES;

        if (mic1_index == 0) {
            double mic1_rms = calculate_rms(mic1_samples, WINDOW_SAMPLES);
            double mic2_rms = calculate_rms(mic2_samples, WINDOW_SAMPLES);
            log_event(mic1_rms, mic2_rms);
            control_led(mic1_rms, mic2_rms);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

