#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define CURRENT_THRESHOLD 50.0f

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static float current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_ads1115(int16_t *raw_value);
static float convert_to_current(int16_t raw_value);
static void add_to_buffer(float current);
static float calculate_average(void);
static void check_threshold(float average_current);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* Initialize I2C communication */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

/* Read raw value from ADS1115 */
static int read_ads1115(int16_t *raw_value) {
    char config[3];
    char reg_config[1] = {ADS1115_REG_CONFIG};
    char reg_conversion[1] = {ADS1115_REG_CONVERSION};

    /* Write config register to start a single conversion */
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    /* Wait for conversion to complete (128 SPS -> ~8ms) */
    gpioDelay(10000);

    /* Read conversion register */
    if (i2cWriteDevice(i2c_handle, reg_conversion, 1) != 0) {
        fprintf(stderr, "Error selecting conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    *raw_value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* Convert raw ADC value to current (Vref = 4.096V) */
static float convert_to_current(int16_t raw_value) {
    return (float)raw_value * 4.096f / 32768.0f;
}

/* Add current to circular buffer */
static void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Calculate average current from circular buffer */
static float calculate_average(void) {
    if (buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

/* Check if average current exceeds threshold */
static void check_threshold(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        printf("Warning: Average current %.2f A exceeds threshold %.2f A\n",
               average_current, CURRENT_THRESHOLD);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED GPIO as output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(current);
            float average_current = calculate_average();
            check_threshold(average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

