        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED GPIO as output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(current);
            float average_current = calculate_average();
            check_threshold(average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

