#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#include <gpiod.h>

/* ---- TCS34725 register addresses ---- */
#define TCS34725_ADDRESS          0x29
#define TCS34725_COMMAND_BIT      0x80
#define TCS34725_ENABLE           0x00
#define TCS34725_ATIME            0x01
#define TCS34725_ID               0x12
#define TCS34725_CDATAL           0x14
#define TCS34725_CDATAH           0x15
#define TCS34725_RDATAL           0x16
#define TCS34725_RDATAH           0x17
#define TCS34725_GDATAL           0x18
#define TCS34725_GDATAH           0x19
#define TCS34725_BDATAL           0x1A
#define TCS34725_BDATAH           0x1B

/* ---- Expected ID ---- */
#define TCS34725_ID_VALUE         0x44

/* ---- Enable bits ---- */
#define TCS34725_ENABLE_PON       0x01
#define TCS34725_ENABLE_AEN       0x02

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- TCS34725 driver ---- */
static int tcs34725_init(int fd)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (i2c_read_block(fd, TCS34725_ID, &id, 1) < 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 not detected (ID=0x%02X, expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    usleep(3000); /* 3 ms power-on settling */

    /* Enable RGBC */
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red,
                            uint16_t *green, uint16_t *blue)
{
    uint8_t buf[8];

    if (i2c_read_block(fd, TCS34725_CDATAL, buf, 8) < 0)
        return -1;

    *clear = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);

    return 0;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open color_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(g_log_file);
    }

    printf("TCS34725 logging started. Press Ctrl+C to stop.\n");

    /* Main loop: read every second */
    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_data(g_i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Sensor read failed; continuing after delay.\n");
            sleep(1);
            continue;
        }

        if (log_data(g_log_file, clear, red, green, blue) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

