#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define CURRENT_THRESHOLD 10.0f
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    motor_shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_shutdown_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(motor_shutdown_line, "mlx91211_motor_shutdown", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        motor_shutdown_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float convert_adc_to_current(int adc_value) {
    // MLX91211: 10-bit ADC, 0.001 V/A, 10 mV/A/LSB
    return (float)adc_value * 0.001f;
}

static int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.4f\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void motor_shutdown(int enable) {
    if (motor_shutdown_line) {
        gpiod_line_set_value(motor_shutdown_line, enable ? 0 : 1);
    }
}

static void cleanup(void) {
    if (motor_shutdown_line) {
        gpiod_line_set_value(motor_shutdown_line, 1);
        gpiod_line_release(motor_shutdown_line);
        motor_shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
        fflush(log_file);
    }

    motor_shutdown(1); // Ensure motor is off initially

    printf("MLX91211 Current Sensor Monitoring Started\n");
    printf("SPI: %s, MCP3008 Channel: %d, Motor Shutdown: GPIO%d\n", SPI_DEVICE, MCP3008_CHANNEL, MOTOR_SHUTDOWN_PIN);
    printf("Threshold: %.1f A, Logging to: %s\n", CURRENT_THRESHOLD, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && program_running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries. Skipping sample.\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = convert_adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed. Continuing...\n");
        }

        printf("Current: %.4f A\n", current);

        if (current > CURRENT_THRESHOLD) {
            printf("Over-current detected! Shutting down motor.\n");
            motor_shutdown(0); // Enable motor

            time_t overcurrent_start_time = time(NULL);
            while (program_running && (time(NULL) - overcurrent_start_time) < 1) {
                sleep(1);
            }

            if (program_running) {
                printf("Re-enabling motor.\n");
                motor_shutdown(1); // Disable motor
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

