/*
 * MLX90817 Absolute Pressure Sensor Logger for Raspberry Pi Zero W
 *
 * Reads the MLX90817 once per second, logs the timestamp and pressure
 * to pressure_log.csv, and exits cleanly on SIGINT or SIGTERM.
 *
 * Build:  gcc -O2 -Wall -o mlx90817_logger mlx90817_logger.c -lm
 * Run:    ./mlx90817_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define I2C_ADDR         0x5A          /* MLX90817 default I2C address */
#define LOG_FILE         "pressure_log.csv"
#define SAMPLE_PERIOD_US 1000000       /* 1 second in microseconds */
#define MAX_RETRIES      3

/* ---- MLX90817 register addresses ---- */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB     0x02
#define REG_TEMP_LSB     0x03
#define REG_CONFIG       0x04
#define REG_STATUS       0x05

/* ---- Globals for signal handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- Function prototypes ---- */
static int  init_i2c(void);
static int  read_pressure(float *pressure_kpa);
static int  log_data(float pressure_kpa);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the I2C bus and open the log file once at startup       */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X, err=%d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Verify sensor presence by reading the configuration register */
    int cfg = i2cReadByteData(g_i2c_handle, REG_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "Error: cannot read configuration register (err=%d).\n", cfg);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kpa\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure from the MLX90817. Returns 0 on success, -1 on error.    */
/* ------------------------------------------------------------------ */
static int read_pressure(float *pressure_kpa)
{
