#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_MUX_AIN0_GND 0x4000
#define ADS1115_MUX_AIN1_GND 0x5000
#define ADS1115_MUX_AIN0_AIN1 0x4400
#define ADS1115_MUX_AIN0_AIN3 0x4500
#define ADS1115_MUX_AIN1_AIN3 0x5500
#define ADS1115_MUX_AIN2_AIN3 0x6500
#define ADS1115_MUX_AIN3_GND 0x7000

#define ADS1115_PGA_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_CQUE_NONE 0x0003

#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f
#define I2C_BUS 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion register.\n");
        return -1;
    }
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float ads1115_to_pressure(int16_t raw) {
    return (raw * 4.096f) / 32768.0f;
}

static float ads1115_to_temperature(int16_t raw) {
    float v = (raw * 4.096f) / 32768.0f;
    float r = 10000.0f * (10.0f - v) / v;
    float t = 1.0f / (logf(r / 10000.0f) / 0.0039083f + 0.0087579f);
    return t - 273.15f;
}

static int read_sensor(int mux, float *pressure, float *temperature) {
    uint16_t config = ADS1115_MUX_AIN0_GND | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (mux == 1) config = ADS1115_MUX_AIN1_GND | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (mux == 2) config = ADS1115_MUX_AIN0_AIN1 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (mux == 3) config = ADS1115_MUX_AIN0_AIN3 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (mux == 4) config = ADS1115_MUX_AIN1_AIN3 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (mux == 5) config = ADS1115_MUX_AIN2_AIN3 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (mux == 6) config = ADS1115_MUX_AIN3_GND | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE;

    if (ads1115_write_config(config) != 0) {
        return -1;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int16_t raw;
        if (ads1115_read_conversion(&raw) == 0) {
            *pressure = ads1115_to_pressure(raw);
            *temperature = ads1115_to_temperature(raw);
            return 0;
        }
        fprintf(stderr, "Warning: ADS1115 read attempt %d/%d failed.\n", attempt + 1, MAX_RETRIES);
        gpioDelay(10000);
    }
    fprintf(stderr, "Error: ADS1115 read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure & Temperature Sensor Reader\n");
    printf("ADS1115 I2C Address: 0x%02X | Pressure Threshold: %.1f kPa | LED GPIO: %d\n", ADS1115_ADDR, PRESSURE_THRESHOLD, LED_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        float pressure = 0.0f, temperature = 0.0f;
        int success = 0;

        if (read_sensor(0, &pressure, &temperature) == 0) {
            success = 1;
        } else if (read_sensor(1, &pressure, &temperature) == 0) {
            success = 1;
        } else if (read_sensor(2, &pressure, &temperature) == 0) {
            success = 1;
        } else if (read_sensor(3, &pressure, &temperature) == 0) {
            success = 1;
        } else if (read_sensor(4, &pressure, &temperature) == 0) {
            success = 1;
        } else if (read_sensor(5, &pressure, &temperature) == 0) {
            success = 1;
        } else if (read_sensor(6, &pressure, &temperature) == 0) {
            success = 1;
        } else {
            fprintf(stderr, "Error: All sensor read attempts failed.\n");
        }

        if (success) {
            printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temperature);
            if (pressure > PRESSURE_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(1000000);
    }

    printf("\nExiting gracefully...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

