/*
 * Raspberry Pi 3 Model B+ — MLX91209 Hall-effect current sensor reader
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 = GPIO8, SCLK = GPIO11, MOSI = GPIO10, MISO = GPIO9)
 *   - MLX91209 analog output -> MCP3008 CH0
 *   - Shutdown button on GPIO27 (BCM) — assert HIGH to shut down motor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define MCP3008_CHANNEL  0          /* MLX91209 on CH0 */

#define CURRENT_THRESHOLD 10.0f     /* Amps — shut down when exceeded */
#define OVERCURRENT_PIN   27         /* BCM pin for shutdown control */

#define SAMPLE_PERIOD_US 100000     /* 100 ms between samples */
#define LOG_FILE         "current_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes --------------------------- */
static int  initialize_gpio(void);
static int  initialize_spi(void);
static int  read_mcp3008(int channel);
static float calculate_current(int adc_value);
static void log_current(float current);
static void log_overcurrent(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- GPIO ----------------------------------- */
static int initialize_gpio(void)
{
    if (gpioSetMode(OVERCURRENT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", OVERCURRENT_PIN);
        return -1;
    }
    if (gpioWrite(OVERCURRENT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW\n", OVERCURRENT_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------- SPI ------------------------------------ */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=0x%02X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------- Current --------------------------------- */
static float calculate_current(int adc_value)
{
    /*
     * MLX91209: 10-bit ADC, 0–3.3 V output.
     * 10-bit resolution: 1024 counts = 3.3 V.
     * Current (A) = (adc_value / 1024.0f) * 3.3f
     */
    return ((float)adc_value / 1024.0f) * 3.3f;
}

/* ------------------------------- Logging --------------------------------- */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    } else {
        fflush(g_log_file);
    }
}

static void log_overcurrent(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, OVERCURRENT DETECTED!\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write overcurrent event to log file\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure motor is off before releasing resources */
    if (OVERCURRENT_PIN >= 0) {
        gpioWrite(OVERCURRENT_PIN, 0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");
    printf("Threshold: %.1f A | Shutdown pin: GPIO%d\n", CURRENT_THRESHOLD, OVERCURRENT_PIN);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, retrying in 100 ms...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = calculate_current(adc_value);

        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            printf("OVERCURRENT DETECTED! Current: %.2f A\n", current);
            log_overcurrent();

            /* Shut down motor */
            if (gpioWrite(OVERCURRENT_PIN, 1) != 0) {
                fprintf(stderr, "Warning: failed to assert shutdown pin HIGH\n");
            }

            /* Wait for motor to stop before exiting */
            while (g_running) {
                gpioDelay(100000); /* 100 ms */
            }

            /* Ensure motor is off on exit */
            gpioWrite(OVERCURRENT_PIN, 0);

            break; /* Exit loop after shutdown */
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

