#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* Mode 0, active-low CE */
#define ALARM_GPIO     4
#define CO_THRESHOLD   2.5f     /* Volts */
#define LOG_FILE       "co_log.txt"
#define SAMPLE_PERIOD  1.0      /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call any pigpio API.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.                         */
/* Returns 0–1023 on success, -1 on SPI transfer failure.             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to voltage (Vref = 3.3 V).                         */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / 1023.0f) * 3.3f;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped CO reading to the log file.                       */
/* ------------------------------------------------------------------ */
static void log_co_reading(float voltage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s,Voltage: %.2f V\n", timestamp, voltage) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Control the alarm based on the CO threshold.                         */
/* ------------------------------------------------------------------ */
static void control_alarm(float voltage)
{
    int alarm_state = (voltage > CO_THRESHOLD) ? 1 : 0;

    if (gpioWrite(ALARM_GPIO, alarm_state) != 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n",
                ALARM_GPIO, alarm_state);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure alarm is off before terminating pigpio */
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO as output, initially LOW */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n",
                ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
