    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize ADS1115 ADC
int initialize_ads1115(void) {
    // Write config register: OS=1, MUX=AIN0, PGA=4.096V, MODE=Single, DR=128SPS, CQUE=None
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V |
