#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3208 channel connected to HIH-4602-A
#define HUMIDITY_THRESHOLD 80.0f // Humidity threshold in percentage
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_MESSAGE "Humidity exceeds threshold!\n"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float convert_to_humidity(int adc_value);
float convert_to_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from the MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3208 SPI command format: Start bit (1), Single-ended mode (1), Channel select (3 bits), Don't care (1 bit)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 12-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to humidity percentage
float convert_to_humidity(int adc_value) {
    // HIH-4602-A: Humidity = (adc_value / 4095.0) * 100.0
    return (float)adc_value / 4095.0f * 100.0f;
}

// Function to convert ADC value to temperature in Celsius
float convert_to_temperature(int adc_value) {
    // HIH-4602-A: Temperature = (adc_value / 4095.0) * 165.0 - 40.0
    return (float)adc_value / 4095.0f * 165.0f - 40.0f;
}

// Function to log data to a file
int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to send an email alert
int send_email_alert(float humidity) {
    char command[512];
    snprintf(command, sizeof(command), "echo '%s' | ssmtp %s", EMAIL_MESSAGE, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to execute ssmtp command\n");
        return -1;
    } else if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "Error: ssmtp exited with status %d\n", WEXITSTATUS(result));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from the specified channel
        int adc_value = read_mcp3208(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to humidity and temperature
        float humidity = convert_to_humidity(adc_value);
        float temperature = convert_to_temperature(adc_value);

        // Log the data
        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Send email alert if humidity exceeds threshold
        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Error: Failed to send email alert\n");
            }
        }

        // Wait 1 second before next reading
        gpioDelay(1000000);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Humidity monitoring stopped.\n");
    return 0;
}

