/*
 * ADXL335 Impact Detector for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - ADXL335 analog accelerometer on SPI0 (CE0, GPIO8)
 *   - MCP3008 10-bit ADC on SPI0 (CE0, GPIO8)
 *
 * Wiring:
 *   ADXL335 VCC -> 3.3V (Pin 1)
 *   ADXL335 GND -> GND  (Pin 6)
 *   ADXL335 XOUT -> MCP3008 CH0
 *   ADXL335 YOUT -> MCP3008 CH1
 *   ADXL335 ZOUT -> MCP3008 CH2
 *   MCP3008 VDD -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *
 * Build:
 *   gcc -O2 -Wall -o impact_detector impact_detector.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SPI_DELAY_USEC  0

#define MCP3008_CHANNEL_X 0
#define MCP3008_CHANNEL_Y 1
#define MCP3008_CHANNEL_Z 2

#define IMPACT_THRESHOLD 100.0f
#define SAMPLE_RATE_HZ   100
#define LOG_FILE_NAME    "impact_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n",
                strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n",
                strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (don't care)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .delay_usecs   = SPI_DELAY_USEC,
        .bits_per_word = SPI_BITS,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void log_impact(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d,IMPACT DETECTED\n",
                timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL335 Impact Detector started. Logging to %s\n",
           LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int x = mcp3008_read(MCP3008_CHANNEL_X);
        int y = mcp3008_read(MCP3008_CHANNEL_Y);
        int z = mcp3008_read(MCP3008_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values, skipping sample\n");
            usleep(100000);
            continue;
        }

        /* Validate ADC values (10-bit ADC: 0-1023) */
        if (x < 0 || x > 1023 ||
            y < 0 || y > 1023 ||
            z < 0 || z > 1023) {
            fprintf(stderr, "Warning: ADC value out of range (%d, %d, %d)\n",
                    x, y, z);
        }

        log_data(x, y, z);

        if (fabsf((float)x) > IMPACT_THRESHOLD ||
            fabsf((float)y) > IMPACT_THRESHOLD ||
            fabsf((float)z) > IMPACT_THRESHOLD) {
            log_impact(x, y, z);
            printf("Impact detected! X=%d Y=%d Z=%d\n", x, y, z);
        }

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

