        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .delay_usecs   = SPI_DELAY_USEC,
        .bits_per_word = SPI_BITS,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void log_impact(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d,IMPACT DETECTED\n",
                timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL335 Impact Detector started. Logging to %s\n",
           LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int x = mcp3008_read(MCP3008_CHANNEL_X);
        int y = mcp3008_read(MCP3008_CHANNEL_Y);
        int z = mcp3008_read(MCP3008_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values, skipping sample\n");
            usleep(100000);
            continue;
        }

        /* Validate ADC values (10-bit ADC: 0-1023) */
        if (x < 0 || x > 1023 ||
            y < 0 || y > 1023 ||
            z < 0 || z > 1023) {
            fprintf(stderr, "Warning: ADC value out of range (%d, %d, %d)\n",
                    x, y, z);
        }

        log_data(x, y, z);

        if (fabsf((float)x) > IMPACT_THRESHOLD ||
            fabsf((float)y) > IMPACT_THRESHOLD ||
            fabsf((float)z) > IMPACT_THRESHOLD) {
            log_impact(x, y, z);
            printf("Impact detected! X=%d Y=%d Z=%d\n", x, y, z);
        }

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

