/*
 * Si1172‑A30‑GMR Heart Rate & SpO₂ Sensor Reader for Raspberry Pi Zero W
 *
 * Reads HR and SpO₂ from a Silicon Labs Si1172‑A30‑GMR optical heart rate
 * sensor on I2C bus 1.  Logs each sample to biometric_log.csv with a header
 * row and flushes after every write.  Handles I2C errors and sensor
 * uninitialization.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw PPG
 * samples to true HR and SpO₂.  This program logs raw 16-bit IR and RED ADC
 * values as proxy values for HR and SpO₂.  The application must
 * implement a proper HR/SpO₂ algorithm based on the Si1172 datasheet.
 *
 * Build: gcc -O2 -Wall -o si1172_hr si1172_hr.c -lsi1172
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <si1172.h>

#define I2C_BUS        1
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */

/* Si1172 register addresses */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_IRQ_ENABLE 0x0F
#define REG_IRQ_STATUS 0x10
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_IR_DATA0  0x24
#define REG_ALS_IR_DATA1  0x25
#define REG_ALS_RED_DATA0 0x26
#define REG_ALS_RED_DATA1 0x27

/* Expected part ID for Si1172 */
#define SI1172_PART_ID 0x72

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register                            */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = si1172_write_reg8(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] si1172_write_reg8(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1172 register                            */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = si1172_read_reg8(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] si1172_read_reg8(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers       */
/* ------------------------------------------------------------------ */
static int si1172_read_reg16(int handle, uint8_t reg_low, uint16_t *value)
{
    uint8_t lo, hi;

    if (si1172_read_reg(handle, reg_low, &lo) < 0)
        return -1;
    if (si1172_read_reg(handle, reg_low + 1, &hi) < 0)
        return -1;

    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172 sensor                                       */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    uint8_t part_id = 0;

    /* Verify part ID */
    if (si1172_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read Si1172 PART_ID — sensor absent or uninitialized.\n");
        return -1;
    }
    if (part_id != SI1172_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X).  Wrong sensor?\n",
                part_id, SI1172_PART_ID);
        return -1;
    }

    /* Write HW_KEY to enable the device */
    if (si1172_write_reg(handle, REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Set measurement rate to 1 sample per second (0x00 = 1 Hz) */
    if (si1172_write_reg(handle, REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (si1172_write_reg(handle, REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    /* Enable ALS_VIS, ALS_IR, and RED channels */
    if (si1172_write_reg(handle, REG_IRQ_ENABLE, 0x07) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read HR and SpO₂ from the Si1172 sensor                          */
/* ------------------------------------------------------------------ */
static int si1172_read_hr_spo2(int handle, uint16_t *hr, uint16_t *spo2)
{
    uint8_t irq_status = 0;

    /* Check for measurement completion */
    if (si1172_read_reg(handle, REG_IRQ_STATUS, &irq_status) < 0)
        return -1;

    if ((irq_status & 0x07) == 0) {
        /* No new data available yet */
        return 1;
    }

    /* Clear interrupt by writing to IRQ_STATUS */
    if (si1172_write_reg(handle, REG_IRQ_STATUS, irq_status) < 0)
        return -1;

    /* Read raw ALS_VIS (IR) and RED ADC values */
    if (si1172_read_reg16(handle, REG_ALS_IR_DATA0, ir) < 0)
        return -1;
    if (si1172_read_reg16(handle, REG_ALS_RED_DATA0, spo2) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a sample to the CSV file                                        */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, uint16_t ir, uint16_t red, int hr_ok, int spo2_ok)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *tstruct = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (tstruct == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        snprintf(timestamp, sizeof(timestamp), "1970-01-01 00:00:00");
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);
    }

    fprintf(fp, "%s,%u,%u,%d,%d\n",
            timestamp, ir, red, hr_ok, spo2_ok);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        si1172_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    si1172_terminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize the Si1172 driver library */
    if (si1172_init() < 0) {
        fprintf(stderr, "[ERROR] Si1172 initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_handle = si1172_open(I2C_BUS);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] si1172_open(bus=%d) failed: %s\n",
                I2C_BUS, strerror(errno));
        si1172_terminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the header row if the file is empty */
    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "timestamp,ir_raw,red_raw,hr_ok,spo2_ok\n");
        fflush(g_log_file);
    }

    printf("Si1172 HR & SpO₂ logging started.  Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int hr_ok = 0, spo2_ok = 0;

        int rc = si1172_read_hr_spo2(g_i2c_handle, &ir, &red);

        if (rc == 0) {
            hr_ok = 1;
            spo2_ok = 1;
        } else if (rc == 1) {
            /* No new data available yet — log as OK */
            hr_ok = 1;
            spo2_ok = 1;
        } else {
            /* I2C error — log with error flag */
            hr_ok = 0;
            spo2_ok = 0;
        }

        log_sample(g_log_file, ir, red, hr_ok, spo2_ok);

        /* Sleep for the sample period, checking g_running every second */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

