#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x50
#define MEASURE_CMD    0x24
#define CONV_DELAY_US  10000   /* 10 ms for high-precision conversion */
#define SAMPLE_PERIOD  5       /* seconds between samples */
#define LOG_FILE       "environmental_data.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in a signal handler  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the ICP-10125                          */
/* ------------------------------------------------------------------ */
static int icp10125_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the ICP-10125                          */
/* ------------------------------------------------------------------ */
static int icp10125_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[ERROR] I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and pressure from the ICP-10125                       */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int icp10125_read_data(int fd, float *temperature, float *pressure)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];

    /* Issue measurement command */
    if (icp10125_write_cmd(fd, cmd) != 0)
        return -1;

    /* Wait for conversion to complete */
    usleep(CONV_DELAY_US);

    /* Read 6 bytes: pressure MSB, pressure LSB, temp MSB, temp LSB, CRC */
    if (icp10125_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* Combine bytes (big-endian) into 16-bit values */
    uint16_t raw_pressure = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temperature = ((uint16_t)data[2] << 8) | data[3];

    /*
     * ICP-10125 calibration formulas (from datasheet):
     *   Temperature (°C) = (raw_temp / 65536.0) * 165.0 - 40.0
     *   Pressure (Pa)    = (raw_pressure / 65536.0) * 100.0
     */
    *temperature = ((float)raw_temperature / 65536.0f) * 165.0f - 40.0f;
    *pressure    = ((float)raw_pressure / 65536.0f) * 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log file                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temperature, float pressure)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[64];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Display a reading on the console                                  */
/* ------------------------------------------------------------------ */
static void display_data(float temperature, float pressure)
{
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire ICP-10125 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ICP10125_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature(C),Pressure(Pa)\n");
        fflush(g_log_fp);
    }

    printf("ICP-10125 environmental monitor started. Logging to %s\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temperature, pressure;

        if (icp10125_read_data(g_i2c_fd, &temperature, &pressure) == 0) {
            if (log_data(g_log_fp, temperature, pressure) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; retrying in %d s.\n",
                    SAMPLE_PERIOD);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

