#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NUM_CHANNELS 2
#define SAMPLE_RATE 44100
#define NUM_SAMPLES (SAMPLE_RATE * 2)
#define MAX_GAIN 100

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int process_audio(int *audio_data, int num_channels, int gain) {
    for (int i = 0; i < num_channels; i++) {
        int sample = audio_data[i];
        if (sample < 0) sample = 0;
        if (sample > 32767) sample = 32767;
        audio_data[i] = (sample * gain) / MAX_GAIN;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != NUM_CHANNELS + 1) {
        fprintf(stderr, "Usage: %s <gain_channel1> <gain_channel2> ...\n", argv[0]);
        return 1;
    }

    int gains[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gains[i] = atoi(argv[i + 1]);
        if (gains[i] < 0 || gains[i] > MAX_GAIN) {
            fprintf(stderr, "Invalid gain value for channel %d: %d\n", i + 1, gains[i]);
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    int audio_data[NUM_CHANNELS];
    int16_t audio_buffer[NUM_CHANNELS][NUM_SAMPLES];
    int buffer_index = 0;

    printf("Audio sampling started. Press Ctrl+C to stop.\n");

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sample = read_mcp3008(i);
            if (sample < 0) {
                fprintf(stderr, "Error reading channel %d, exiting.\n", i + 1);
                running = 0;
                break;
            }
            audio_buffer[i][buffer_index] = (int16_t)sample;
        }

        if (!running) break;

        process_audio(audio_buffer[0], NUM_CHANNELS, gains[0]);
        process_audio(audio_buffer[1], NUM_CHANNELS, gains[1]);

        printf("%d,%d\n", audio_buffer[0][buffer_index], audio_buffer[1][buffer_index]);
        fflush(stdout);

        buffer_index++;
        if (buffer_index >= NUM_SAMPLES) {
            buffer_index = 0;
        }

        usleep(10000);
    }

    printf("\nAudio sampling stopped.\n");

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    return 0;
}

