/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 Soil Moisture Sensor
 * ADC: MCP3008 (SPI0 CE0, 10-bit, channel 0)
 * Library: pigpio (modern, actively maintained)
 *
 * Build: gcc -Wall -Wextra -O2 -o moisture_logger moisture_logger.c -lpigpio -lrt
 * Run:   sudo ./moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "moisture_log.txt"
#define SAMPLE_PERIOD  60         /* seconds between samples */
#define ADC_MAX        1023       /* 10-bit ADC */
#define ADC_MIN        0

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended sample from the MCP3008                       */
/* Returns 0–1023 on success, -1 on SPI transfer failure              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0–7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = undefined
     *   rx[1] = bits 9–2 in upper nibble
     *   rx[2] = bits 1–0 in lower nibble
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped CSV line to the log file                       */
/* Returns 0 on success, -1 on failure                               */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, int adc_value)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting current time");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("Error converting time to UTC");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, adc_value) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper – release resources                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed – skipping sample\n");
        } else if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
            fprintf(stderr, "Warning: ADC value %d out of range [%d, %d] – skipping\n",
                    adc_value, ADC_MIN, ADC_MAX);
        } else {
            if (log_data(LOG_FILE, adc_value) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            } else {
                printf("ADC: %4d  (raw: %4d)\n", adc_value, adc_value);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

