/*
 * Raspberry Pi 3 Model B+ - Gravity Analog Water Level Sensor
 *
 * Reads an analog value from a DFRobot Gravity Analog Water Level Sensor
 * (channel 0 of an MCP3008 10-bit ADC) via SPI0 CE0 (GPIO 8),
 * controls an LED on GPIO 17 (BCM) via the pigpio library,
 * and logs JSON objects to water_levels.json every 5 seconds.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO 11 (BCM, Pin 23)
 *   MCP3008 DOUT -> GPIO 9  (BCM, Pin 21)
 *   MCP3008 DIN  -> GPIO 10 (BCM, Pin 19)
 *   MCP3008 CS   -> GPIO 8  (BCM, Pin 24)
 *   MCP3008 CH0  -> DFRobot Gravity Sensor analog output
 *   LED Anode   -> GPIO 17 (BCM, Pin 11) through 330 Ω resistor
 *   LED Cathode -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o water_level water_level.c -lpigpio -lrt
 * Run:   sudo ./water_level
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on GPIO 8 (BCM) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define LED_GPIO         17         /* BCM 17 - LED anode */

#define WATER_LEVEL_THRESHOLD_HIGH  75.0f
#define WATER_LEVEL_THRESHOLD_LOW   70.0f

#define SAMPLE_INTERVAL_SEC 5
#define SAMPLE_DELAY_US     100000    /* 100 ms between samples */

#define JSON_FILENAME      "water_levels.json"

/* ------------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_fp = NULL;

/* --------------------------- Function prototypes --------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel);
static float calculate_water_level(int adc_value);
static int  control_led(float water_level);
static int  log_data(float water_level);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI init ---------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------- MCP3008 read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------- Water level ------------------------------- */
static float calculate_water_level(int adc_value)
{
    /*
     * DFRobot Gravity Analog Water Level Sensor:
     *   0 V  -> 0 %
     *   3.3 V -> 100 %
     *
     * 10-bit ADC: 0..1023.
     */
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    float voltage = (float)adc_value / 1023.0f * 3.3f;
    float water_level = (voltage / 3.3f) * 100.0f;

    if (water_level < 0.0f)   water_level = 0.0f;
    if (water_level > 100.0f) water_level = 100.0f;

    return water_level;
}

/* ------------------------------- LED control -------------------------------- */
static int control_led(float water_level)
{
    int level = (water_level > WATER_LEVEL_THRESHOLD_HIGH) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed.\n", LED_GPIO, level);
        return -1;
    }
    return 0;
}

/* ------------------------------- JSON logging -------------------------------- */
static int log_data(float water_level)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    int ms = (int)(ts.tv_nsec / 1000000);

    if (fprintf(g_json_fp, "{\"timestamp\": \"%s.%03d\", \"water_level\": %.2f}\n",
                timestamp, ms, water_level) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(g_json_fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_json_fp != NULL) {
        fflush(g_json_fp);
        fclose(g_json_fp);
        g_json_fp = NULL;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open JSON file for appending */
    g_json_fp = fopen(JSON_FILENAME, "a");
    if (g_json_fp == NULL) {
        perror("fopen");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write JSON array opening */
    if (fprintf(g_json_fp, "[\n") < 0) {
        perror("fprintf");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_json_fp);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: SPI read error, skipping sample.\n");
        } else {
            float water_level = calculate_water_level(adc_value);
            if (control_led(water_level) != 0) {
                fprintf(stderr, "Warning: LED control failed.\n");
            }
            if (log_data(water_level) != 0) {
                fprintf(stderr, "Warning: JSON logging failed.\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(SAMPLE_DELAY_US);
        }
    }

    /* Write JSON array closing */
    if (fprintf(g_json_fp, "]\n") < 0) {
        perror("fprintf");
    }
    fflush(g_json_fp);

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

