#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION 0
#define DEFAULT_MAX_CALIBRATION 1023
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtprc"
#define DEFAULT_LOG_FILE "plant_data.txt"
#define DEFAULT_ERROR_LOG_FILE "error_log.txt"
#define DEFAULT_READ_INTERVAL 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, don't care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    if (max_calibration <= min_calibration) {
        fprintf(stderr, "Error: Invalid calibration values (min=%d, max=%d)\n", min_calibration, max_calibration);
        return -1.0;
    }
    return ((double)(adc_value - min_calibration) / (double)(max_calibration - min_calibration)) * 100.0;
}

static int log_data(double moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

static int send_email_alert(double moisture_percentage, double threshold, const char *recipient, const char *msmtp_config_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char email_body[512];
    char command[512];
    FILE *fp;
    int status;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    snprintf(email_body, sizeof(email_body),
             "Subject: Plant Moisture Alert\n\n"
             "Plant moisture level: %.2f%%\n"
             "Threshold: %.2f%%\n"
             "Timestamp: %s\n",
             moisture_percentage, threshold, timestamp);

    snprintf(command, sizeof(command),
             "msmtp -t -f %s %s < %s",
             msmtp_config_file, recipient, email_body);

    fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: popen() failed: %s\n", strerror(errno));
        return -1;
    }

    status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose() failed: %s\n", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_calibration = DEFAULT_MIN_CALIBRATION;
    int max_calibration = DEFAULT_MAX_CALIBRATION;
    double moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_interval = DEFAULT_LOGGING_INTERVAL;
    const char *recipient = DEFAULT_EMAIL_RECIPIENT;
    const char *msmtp_config_file = DEFAULT_MSMTP_CONFIG_FILE;
    const char *log_file_path = DEFAULT_LOG_FILE;
    const char *error_log_file_path = DEFAULT_ERROR_LOG_FILE;
    int read_interval_us = DEFAULT_READ_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:t:i:r:s:e:h")) != -1) {
        switch (opt) {
            case 'c':
                spi_channel = atoi(optarg);
                break;
            case 'a':
                adc_channel = atoi(optarg);
                break;
            case 'm':
                min_calibration = atoi(optarg);
                break;
            case 't':
                max_calibration = atoi(optarg);
                break;
            case 'i':
                logging_interval = atoi(optarg);
                if (logging_interval <= 0) {
                    fprintf(stderr, "Error: Logging interval must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'r':
                recipient = optarg;
                break;
            case 's':
                msmtp_config_file = optarg;
                break;
            case 'e':
                error_log_file_path = optarg;
                break;
            case 'h':
            default:
                fprintf(stderr,
                        "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-t max_calibration] [-i logging_interval] [-r recipient] [-s msmtp_config_file] [-e error_log_file]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d): %d\n", spi_channel, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", log_file_path, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    error_log_file = fopen(error_log_file_path, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open error log file '%s': %s\n", error_log_file_path, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Plant moisture monitoring started.\n");
    printf("SPI channel: %d, ADC channel: %d, Min calibration: %d, Max calibration: %d\n",
           spi_channel, adc_channel, min_calibration, max_calibration);
    printf("Moisture threshold: %.2f%%, Logging interval: %d seconds, Email recipient: %s\n",
           moisture_threshold, logging_interval, recipient);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(error_log_file, "Error: Failed to read ADC value on channel %d\n", adc_channel);
            fflush(error_log_file);
            gpioDelay(read_interval_us);
            continue;
        }

        double moisture_percentage = calculate_moisture_percentage(adc_value, min_calibration, max_calibration);
        if (moisture_percentage < 0.0) {
            fprintf(error_log_file, "Error: Invalid moisture percentage calculation\n");
            fflush(error_log_file);
            gpioDelay(read_interval_us);
            continue;
        }

        if (log_data(moisture_percentage) != 0) {
            fprintf(error_log_file, "Error: Failed to log data\n");
            fflush(error_log_file);
        }

        if (moisture_percentage < moisture_threshold) {
            printf("Moisture level below threshold (%.2f%% < %.2f%%). Sending email alert...\n",
                   moisture_percentage, moisture_threshold);
            if (send_email_alert(moisture_percentage, moisture_threshold, recipient, msmtp_config_file) != 0) {
                fprintf(error_log_file, "Error: Failed to send email alert\n");
                fflush(error_log_file);
            }
        }

        gpioDelay(logging_interval * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

