    const char *error_log_file_path = DEFAULT_ERROR_LOG_FILE;
    int read_interval_us = DEFAULT_READ_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:t:i:r:s:e:h")) != -1) {
        switch (opt) {
            case 'c':
                spi_channel = atoi(optarg);
                break;
            case 'a':
                adc_channel = atoi(optarg);
                break;
            case 'm':
                min_calibration = atoi(optarg);
                break;
            case 't':
                max_calibration = atoi(optarg);
                break;
            case 'i':
                logging_interval = atoi(optarg);
                if (logging_interval <= 0) {
                    fprintf(stderr, "Error: Logging interval must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'r':
                recipient = optarg;
                break;
            case 's':
                msmtp_config_file = optarg;
                break;
            case 'e':
                error_log_file_path = optarg;
                break;
            case 'h':
            default:
                fprintf(stderr,
                        "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-t max_calibration] [-i logging_interval] [-r recipient] [-s msmtp_config_file] [-e error_log_file]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d): %d\n", spi_channel, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", log_file_path, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    error_log_file = fopen(error_log_file_path, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open error log file '%s': %s\n", error_log_file_path, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Plant moisture monitoring started.\n");
    printf("SPI channel: %d, ADC channel: %d, Min calibration: %d, Max calibration: %d\n",
           spi_channel, adc_channel, min_calibration, max_calibration);
    printf("Moisture threshold: %.2f%%, Logging interval: %d seconds, Email recipient: %s\n",
           moisture_threshold, logging_interval, recipient);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(error_log_file, "Error: Failed to read ADC value on channel %d\n", adc_channel);
            fflush(error_log_file);
            gpioDelay(read_interval_us);
            continue;
        }

        double moisture_percentage = calculate_moisture_percentage(adc_value, min_calibration, max_calibration);
        if (moisture_percentage < 0.0) {
            fprintf(error_log_file, "Error: Invalid moisture percentage calculation\n");
            fflush(error_log_file);
            gpioDelay(read_interval_us);
            continue;
        }

        if (log_data(moisture_percentage) != 0) {
            fprintf(error_log_file, "Error: Failed to log data\n");
            fflush(error_log_file);
        }

        if (moisture_percentage < moisture_threshold) {
            printf("Moisture level below threshold (%.2f%% < %.2f%%). Sending email alert...\n",
                   moisture_percentage, moisture_threshold);
            if (send_email_alert(moisture_percentage, moisture_threshold, recipient, msmtp_config_file) != 0) {
                fprintf(error_log_file, "Error: Failed to send email alert\n");
                fflush(error_log_file);
            }
        }

        gpioDelay(logging_interval * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

