#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define VREF 3.3
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define READ_INTERVAL_SEC 1
#define ADC_STUCK_THRESHOLD 100
#define ADC_STUCK_TIMEOUT_SEC 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

static double adc_to_pressure(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    double voltage = (double)adc_value / (double)ADC_MAX_VALUE * VREF;
    double pressure = (voltage / VREF) * PRESSURE_MAX;

    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
        fprintf(stderr, "Error: Pressure out of range: %.2f Pa\n", pressure);
        return -1.0;
    }

    return pressure;
}

static void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(stdout);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        double pressure = adc_to_pressure(adc_value);
        if (pressure < 0) {
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        log_pressure(pressure);

        int stuck_count = 0;
        while (running && stuck_count < ADC_STUCK_TIMEOUT_SEC) {
            int adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value during stuck check\n");
                break;
            }

            if (adc_value == adc_value) {
                stuck_count++;
            } else {
                stuck_count = 0;
            }

            sleep(1);
        }

        if (stuck_count >= ADC_STUCK_TIMEOUT_SEC) {
            fprintf(stderr, "Warning: ADC stuck at %d for %d seconds, sensor may be absent or disconnected\n", adc_value, ADC_STUCK_TIMEOUT_SEC);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

