#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

