#define PUMP_GPIO_LINE  17          /* BCM 17 – relay control */

#define MOISTURE_LOW    300         /* Hysteresis threshold */
#define MOISTURE_HIGH   600         /* Hysteresis threshold */

#define BUFFER_SIZE     20          /* Circular buffer entries */
#define SAMPLE_PERIOD_S 5           /* Timer interval (seconds) */

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;

