static void buffer_init(CircularBuffer *cb);
static void buffer_add(CircularBuffer *cb, time_t ts, int moisture, bool pump);
static void buffer_print(const CircularBuffer *cb);
static int  read_mcp3008(int channel);
static void control_pump(int moisture);
static void cleanup(void);
static void signal_handler(int sig);
static void timer_callback(void);

/* ----------------------------- Implementation ----------------------------- */

static void buffer_init(CircularBuffer *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void buffer_add(CircularBuffer *cb, time_t ts, int moisture, bool pump)
{
    cb->buffer[cb->head].timestamp  = ts;
    cb->buffer[cb->head].moisture   = moisture;
    cb->buffer[cb->head].pump_on    = pump;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void buffer_print(const CircularBuffer *cb)
{
    printf("\n--- Circular Buffer (%d entries) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&cb->buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Moisture: %4d  Pump: %s\n",
               ts, cb->buffer[idx].moisture,
               cb->buffer[idx].pump_on ? "ON" : "OFF");
    }
    printf("-------------------------------------\n\n");
