    buffer_init(&g_buffer);

    /* Open GPIO chip and request pump line as output, initial value LOW */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_pump_line = gpiod_chip_get_line(g_chip, PUMP_GPIO_LINE);
    if (!g_pump_line) {
        fprintf(stderr, "Error: failed to get GPIO line %d: %s\n",
                PUMP_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_pump_line, "soil_moisture_pump", 0) < 0) {
        fprintf(stderr, "Error: failed to request pump GPIO as output: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: failed to open %s: %s\n",
                SPI_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: failed to set SPI bits per word: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the timer using the gpiod timer subsystem */
    struct gpiod_line_event event;
    struct gpiod_line_event_buffer buffer;
    struct gpiod_line_request_config config = {
        .consumer     = "soil_moisture_timer",
        .request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE,
        .flags        = 0,
    };

    if (gpiod_line_request(g_pump_line, &config, 0) < 0) {
        fprintf(stderr, "Error: failed to request pump GPIO events: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_buffer_init(&buffer) < 0) {
        fprintf(stderr, "Error: failed to initialize event buffer: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line_event_wait_result wait_result;
    int ret;

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        ret = gpiod_line_event_wait(g_pump_line, &buffer, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "Error: gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
            break;
        }
        if (ret == 0)
            continue; /* Timeout – no event */

        for (int i = 0; i < ret; i++) {
            if (gpiod_line_event_buffer_get_event(&buffer, i, &event) < 0) {
                fprintf(stderr, "Error: failed to read event: %s\n",
                        strerror(errno));
                continue;
            }
            /* Only act on rising edge (pump ON) */
            if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
                continue;

            timer_callback();
        }
    }

    /* Cleanup */
    gpiod_line_event_buffer_release(&buffer);
    cleanup();

    printf("Soil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

