#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "health_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */

/* MAX30102 register addresses */
#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR   0x02
#define REG_OVF_COUNTER   0x03
#define REG_FIFO_RD_PTR   0x04
#define REG_FIFO_DATA     0x05
#define REG_FIFO_CONFIG   0x06
#define REG_MODE_CONFIG   0x07
#define REG_SPO2_CONFIG   0x08
#define REG_LED1_PA       0x09
#define REG_LED2_PA       0x0A
#define REG_TEMP_INTR_STATUS 0x0B
#define REG_TEMP_INTR_ENABLE 0x0C
#define REG_TEMP_FIFO_WR_PTR 0x0D
#define REG_TEMP_OVF_COUNTER 0x0E
#define REG_TEMP_FIFO_RD_PTR 0x0F
#define REG_TEMP_FIFO_DATA 0x10
#define REG_TEMP_CONFIG 0x11
#define REG_PART_ID      0xFF

/* Expected Part ID for MAX30102 */
#define MAX30102_PART_ID 0x15

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in a signal handler  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a MAX30102 register                          */
/* ------------------------------------------------------------------ */
static int max30102_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a MAX30102 register                         */
/* ------------------------------------------------------------------ */
static int max30102_read_reg(uint8_t reg, uint8_t *value)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read multiple bytes starting at a register                          */
/* ------------------------------------------------------------------ */
static int max30102_read_burst(uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(g_i2c_fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MAX30102 sensor                                     */
/* ------------------------------------------------------------------ */
static int max30102_init(void)
{
    uint8_t part_id = 0;

    /* Verify sensor presence by reading Part ID */
    if (max30102_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "MAX30102 not responding on I2C bus.\n");
        return -1;
    }

    if (part_id != MAX30102_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X).\n",
                part_id, MAX30102_PART_ID);
        return -1;
    }

    printf("MAX30102 detected (Part ID: 0x%02X).\n", part_id);

    /* Reset the device */
    if (max30102_write_reg(REG_MODE_CONFIG, 0x40) != 0)
        return -1;
    usleep(10000); /* 10 ms settle time after reset */

