    if (max30102_write_reg(REG_FIFO_CONFIG, 0x4F) != 0)
        return -1;

    /* Configure LED pulse amplitudes */
    if (max30102_write_reg(REG_LED1_PA, 0x24) != 0)
        return -1;
    if (max30102_write_reg(REG_LED2_PA, 0x24) != 0)
        return -1;

    /* Configure SpO2 mode: 4096 samples/second, 16-bit resolution */
    if (max30102_write_reg(REG_SPO2_CONFIG, 0x27) != 0)
        return -1;

    /* Configure mode: SpO2 mode */
    if (max30102_write_reg(REG_MODE_CONFIG, 0x03) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit sample from the FIFO                                  */
/* ------------------------------------------------------------------ */
static int max30102_read_sample(uint16_t *sample)
{
    uint8_t buf[2];

    /* Check if FIFO is full (bit 0 of FIFO_RD_PTR) */
    uint8_t rd_ptr = 0;
    if (max30102_read_reg(REG_FIFO_RD_PTR, &rd_ptr) != 0)
        return -1;

    if ((rd_ptr & 0x01) == 0) {
        /* FIFO not full — no sample available */
        return 1;
    }

    /* Read 2 bytes of data */
    if (max30102_read_burst(REG_FIFO_DATA, buf, sizeof(buf)) != 0)
        return -1;

    *sample = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to file with ISO-8601 timestamp                             */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t spo2, uint16_t hr)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, SpO2: %u%%, Heart Rate: %u BPM\n",
            ts, spo2, hr);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put device into standby mode before closing */
        (void)max30102_write_reg(REG_MODE_CONFIG, 0x40);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address 0x57 (MAX30102 default) */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x57) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x57: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (max30102_init() != 0) {
        fprintf(stderr, "MAX30102 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t spo2 = 0;
        uint16_t hr = 0;

        int rc = max30102_read_sample(&spo2);
        if (rc == 0) {
            /* Read heart rate (optional — not used here) */
            (void)max30102_read_sample(&hr);
        } else if (rc == 1) {
            /* FIFO not full — no sample available */
            usleep(100000); /* 100 ms */
            continue;
        } else {
            /* I2C error — log and continue */
            fprintf(stderr, "I2C read error — continuing.\n");
            log_data(0, 0);
            usleep(100000);
            continue;
        }

        /* Log data */
        log_data(spo2, hr);

        /* Sleep for the sample period */
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

