    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char ts_buf[32];
    strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld: %s\n", ts_buf, ts.tv_nsec / 1000000L, msg);
    fclose(fp);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return -1;
    }

    g_relay_line = gpiod_chip_get_line(g_chip, RELAY_GPIO_LINE);
    if (!g_relay_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", RELAY_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_relay_line, "door_lock", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(relay): %s\n", strerror(errno));
        g_relay_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    g_door_line = gpiod_chip_get_line(g_chip, DOOR_SENSOR_GPIO_LINE);
    if (!g_door_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", DOOR_SENSOR_GPIO_LINE, strerror(errno));
        gpiod_line_release(g_relay_line);
        g_relay_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input_flags(g_door_line, "door_lock",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "gpiod_line_request_input_flags(door): %s\n", strerror(errno));
        g_door_line = NULL;
        gpiod_line_release(g_relay_line);
        g_relay_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

static int read_ads1115(int16_t *distance_mm)
{
    uint16_t config = 0x8483; /* AIN0 single-ended, PGA ±4.096V, 128 SPS, continuous */
    if (i2c_write16(g_i2c_fd, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (i2c_read16(g_i2c_fd, ADS1115_REG_CONV, &raw) < 0)
        return -1;

    /* Convert to signed 16-bit, left-justified */
    int16_t signed_raw = (int16_t)raw;
    if (signed_raw & 0x8000)
        signed_raw |= 0xF000;

    *distance_mm = (int16_t)signed_raw;
    return 0;
}

static void control_relay(int on)
{
    if (g_relay_line)
        gpiod_line_set_value(g_relay_line, on ? 1 : 0);
}

static void cleanup(void)
{
    control_relay(0);

    if (g_relay_line) {
        gpiod_line_release(g_relay_line);
        g_relay_line = NULL;
    }
    if (g_door_line) {
        gpiod_line_release(g_door_line);
        g_door_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0)
        return EXIT_FAILURE;

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Door lock system started");

    int calibration_ok = 0;
    int16_t baseline = 0;
    int calibration_samples = 0;

    while (g_running) {
        int16_t distance_mm = 0;
        if (read_ads1115(&distance_mm) < 0) {
            log_event("I2C read error — sensor absent or bus error");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (!calibration_ok) {
            baseline += distance_mm;
            calibration_samples++;
            if (calibration_samples >= CALIBRATION_SAMPLES) {
                baseline /= CALIBRATION_SAMPLES;
                calibration_ok = 1;
                log_event("Calibration complete — baseline distance: "
                          (int)baseline);
            }
            usleep(CALIBRATION_DELAY_MS * 1000);
            continue;
        }

        if (distance_mm < THRESHOLD_DISTANCE_MM) {
            log_event("Distance below threshold — activating relay");
            control_relay(1);
            usleep(RELAY_PULSE_MS * 1000);
            control_relay(0);

            int reed_state = gpiod_line_get_value(g_door_line);
            if (reed_state < 0) {
                log_event("Failed to read reed sensor — logging anyway");
            } else if (reed_state == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    log_event("Shutting down door lock system");
    cleanup();
    return EXIT_SUCCESS;
}

