#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30.0f
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }

    return -1;
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3f / 1023.0f;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void control_pump(int duration_seconds) {
    if (gpioWrite(PUMP_GPIO, 1) < 0) {
        fprintf(stderr, "Error activating pump on GPIO %d\n", PUMP_GPIO);
        log_event("Error: Failed to activate pump");
        return;
    }

