    if (write(fd, &value, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *value)
{
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_sigint_handler() != 0) {
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Dummy read to discard the previous conversion result.
     * The PCF8591 returns the result of the previous conversion
     * when the previous conversion is complete.
     */
    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) != 0) {
        goto cleanup;
    }

    while (g_running) {
        uint8_t value;
        if (i2c_read_byte(fd, &value) != 0) {
            goto cleanup;
        }

        printf("AIN0: %3u\n", value);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

