/*
 * Raspberry Pi 3 Model B+ — Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor -> ADS1115 AIN0
 *   - ADS1115 on I2C bus 1, address 0x48
 *   - Motor shutdown indicator on GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lsyslog
 *
 * Run:
 *   sudo ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0, +/-4.096 V, 128 SPS, continuous */
#define ADS1115_CFG_BASE       0x8000  /* OS bit */
#define ADS1115_CFG_MUX_AIN0   0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096  0x0200  /* +/-4.096 V */
#define ADS1115_CFG_MODE_CONT  0x0100  /* Continuous mode */
#define ADS1115_CFG_DR_128SPS 0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  0x0003  /* Disable comparator */

#define GPIO_CHIP_NAME      "gpiochip0"
#define MOTOR_SHUTDOWN_PIN  27

#define SAMPLE_PERIOD_US    1000000  /* 1 second */
#define BUFFER_SIZE         10
#define THRESHOLD_GAUSS     500.0f
#define VREF               3.3f
#define ADC_MAX_VALUE      32767.0f

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* --------------------------- Circular buffer ----------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    memset(cb, 0, sizeof(*cb));
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

/* --------------------------- ADS1115 helpers ----------------------------- */
static int ads1115_write_reg(uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(g_i2c_fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write to reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(uint8_t reg, uint16_t *value) {
    if (write(g_i2c_fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(g_i2c_fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(void) {
    /* Power down first to avoid undefined config */
    if (ads1115_write_reg(ADS1115_REG_CONFIG, 0x0000) < 0) return -1;
    usleep(10000);

    /* Write config: single-shot, AIN0, +/-4.096 V, 128 SPS, continuous */
    uint16_t cfg = ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 | ADS1115_CFG_PGA_4_096 |
                   ADS1115_CFG_MODE_CONT | ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;
    if (ads1115_write_reg(ADS1115_REG_CONFIG, cfg) < 0) return -1;

    /* Wait for first conversion to complete (128 SPS -> ~7.8 ms) */
    usleep(8000);
    return 0;
}

static int ads1115_read_voltage(float *voltage) {
    uint16_t raw;
    if (ads1115_read_reg(ADS1115_REG_CONVERSION, &raw) < 0) return -1;

    /* Convert 16-bit signed to 16-bit unsigned */
    int16_t signed_raw = (int16_t)raw;
    if (signed_raw & 0x8000) signed_raw |= 0xF000;

    *voltage = ((float)signed_raw / ADC_MAX_VALUE) * VREF;
    return 0;
}

/* --------------------------- Motor shutdown ----------------------------- */
static void motor_shutdown(void) {
    if (g_line) {
        if (gpiod_line_set_value(g_line, 1) < 0) {
            syslog(LOG_ERR, "Failed to set motor shutdown pin HIGH: %s", strerror(errno));
        } else {
            syslog(LOG_INFO, "Motor shutdown triggered (GPIO27 HIGH).");
        }
    }
}

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ----------------------------------- */
static void cleanup(void) {
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    closelog();
}

/* ------------------------------- Main ----------------------------------- */
int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() < 0) {
        syslog(LOG_ERR, "ADS1115 initialization failed. Check wiring and sensor presence.");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO for motor shutdown */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        syslog(LOG_ERR, "Failed to open %s: %s", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, MOTOR_SHUTDOWN_PIN);
    if (!g_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_line, "hall_monitor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d as output: %s", MOTOR_SHUTDOWN_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Hall-effect monitor started. Threshold: %.1f Gauss", THRESHOLD_GAUSS);

    CircularBuffer buffer;
    cb_init(&buffer);

    while (g_running) {
        float voltage;
        if (ads1115_read_voltage(&voltage) < 0) {
            syslog(LOG_WARNING, "ADC read failed; skipping sample.");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_WARNING, "Voltage out of range: %.3f V (ADC raw=%u)", voltage, (uint16_t)voltage);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        cb_add(&buffer, voltage);
        float avg = cb_average(&buffer);

        syslog(LOG_INFO, "Voltage: %.3f V, Avg: %.3f V, Threshold: %.1f Gauss",
               voltage, avg, THRESHOLD_GAUSS);

        if (avg > THRESHOLD_GAUSS) {
            motor_shutdown();
        }

        usleep(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    cleanup();
    return EXIT_SUCCESS;
}

