#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */
#define PUMP_GPIO        18       /* BCM 18 */
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10      /* seconds */
#define SAMPLE_INTERVAL  60       /* seconds */
#define ADC_MAX_VALUE    1023     /* 10-bit ADC */
#define ADC_CHANNEL      0
#define LOG_FILE         "watering_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pump_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call blocking functions.    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.                         */
/* Returns 0–1023 on success, -1 on SPI transfer failure, -2 on invalid  */
/* channel.                                                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -2;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2].
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Activate the water pump for WATERING_DURATION seconds.             */
/* Returns 0 on success, -1 on GPIO write failure.                      */
/* ------------------------------------------------------------------ */
static int activate_pump(void)
{
    if (gpioWrite(PUMP_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate pump on GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    g_pump_state = 1;
    printf("Pump activated for %d seconds\n", WATERING_DURATION);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate the pump and ensure it is off.                         */
/* ------------------------------------------------------------------ */
static void deactivate_pump(void)
{
    if (g_pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
        printf("Pump deactivated\n");
    }
}

/* ------------------------------------------------------------------ */
/* Log a watering event with a timestamp to the log file.             */
/* ------------------------------------------------------------------ */
static void log_watering_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
