/*
 * Raspberry Pi 4 Model B – YL-83 Rain Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)  [Note: CE0 = GPIO8 on RPi 4]
 *   MCP3008 CH0  -> YL-83 analog output
 *
 * Build: gcc -O2 -Wall -o rain_sensor rain_sensor.c -lpigpio -lrt
 * Run:   sudo ./rain_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE handled by pigpio */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           3.3        /* MCP3008 reference voltage */
#define SAMPLE_PERIOD  1          /* seconds between samples */

/* ------------------------------- Globals --------------------------------- */
