static int g_spi_handle = -1;

/* --------------------------- Function Prototypes --------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *adc_value);
static float calculate_rainfall_intensity(int adc_value);
static void log_data(int adc_value, float intensity);
static void signal_handler(int signal);
static void cleanup(void);

/* ------------------------------- Initialization ------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 *
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   Byte 0: 0x01                       (Start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel, padded)
 *   Byte 2: 0x00                       (Don't care, clocks out low 2 bits)
 *
 * Response:
 *   rx[0] = undefined
 *   rx[1] = bits 9..2 in upper nibble
 *   rx[2] = bits 1..0 in lower nibble
 *
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    int bytes_transferred = spiXfer(g_spi_handle, tx_buf, rx_buf, 3);
    if (bytes_transferred != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", bytes_transferred);
        return -1;
    }

    int adc_value_raw = ((rx_buf[1] & 0x03) << 8) | (uint8_t)rx_buf[2];
    *adc_value = adc_value_raw;
    return 0;
}

/*
 * Map the ADC value to a rainfall intensity level.
 * YL-83 output: ~0–100% = ~0–1023 ADC counts.
 * We map 0–1023 to 0–100%.
 */
static float calculate_rainfall_intensity(int adc_value)
{
    if (adc_value < 0) {
        adc_value = 0;
    }
    if (adc_value > ADC_MAX) {
        adc_value = ADC_MAX;
    }
    return (float)adc_value / (float)ADC_MAX * 100.0f;
}

