/*
 * Raspberry Pi – MCP3008 ADC + PWM Motor Speed Controller
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 = GPIO8, SCLK = GPIO11, MOSI = GPIO10, MISO = GPIO9)
 *   - Motor driver PWM on GPIO18 (BCM, 1 kHz, 0-1023 duty cycle)
 *
 * Behavior:
 *   Reads the ADC channel 0 every 100 ms, sets the motor speed
 *   based on the 10-bit ADC value, and prints both the raw ADC value
 *   and the PWM duty cycle to stdout.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_speed motor_speed.c -lpigpio -lrt
 *   (pigpio requires root for SPI access on CE0)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define MOTOR_PIN      18         /* BCM GPIO18 – PWM output */
#define PWM_FREQUENCY  1000       /* 1 kHz – typical for motor control */
#define PWM_RANGE      1023       /* 0–1023 duty cycle */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  100000     /* 100 ms between samples */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal Handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- SPI Initialization ----------------------------- */

/*
 * Open the SPI device.
 * Returns a valid SPI handle (>= 0) on success, or -1 on failure.
 */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return g_spi_handle;
}

/* --------------------------- MCP3008 Read ----------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns the 10-bit ADC value (0–1023) on success, or -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9..b2]
     *   rx[2] = [b1..b0]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* --------------------------- Motor Control ----------------------------- */

/*
 * Set the motor speed using PWM.
 * duty_cycle is 0–PWM_RANGE.
 */
static void set_motor_speed(int duty_cycle)
{
    if (duty_cycle < 0)   duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(MOTOR_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed for duty cycle %d.\n", duty_cycle);
    }
}

/* --------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Stop PWM output first */
    gpioPWM(MOTOR_PIN, 0);

    /* Close SPI handle */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pin as output */
    if (gpioSetMode(MOTOR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", MOTOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM on motor pin */
    if (gpioSetPWMfrequency(MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO %d.\n", MOTOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO %d.\n", MOTOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 ADC + PWM Motor Speed Controller\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 channel %d, PWM on GPIO%d\n",
           SPI_SPEED, ADC_CHANNEL, MOTOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed; skipping sample.\n");
        } else {
            int duty_cycle = (int)((float)adc_value / 1023.0f * PWM_RANGE);
            set_motor_speed(duty_cycle);
            printf("ADC: %4d  PWM: %4d\n", adc_value, duty_cycle);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_PERIOD / 10);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

