#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_PUMP "pump_control"
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define SAMPLE_INTERVAL_SEC 60
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "SPI transfer failed (returned %d): %s", ret, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d: %s", PUMP_GPIO, strerror(errno));
    } else {
        pump_state = state;
        syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC_PUMP, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s: %s", MQTT_TOPIC_PUMP, mosquitto_strerror(result));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC_PUMP);
        }
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    syslog(LOG_INFO, "Disconnected from MQTT broker (code %d)", result);
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (payload) {
            memcpy(payload, message->payload, message->payloadlen);
            payload[message->payloadlen] = '\0';

            syslog(LOG_INFO, "Received message on %s: %s", message->topic, payload);

            if (strcmp(message->topic, MQTT_TOPIC_PUMP) == 0) {
                if (strcmp(payload, "pump_on") == 0) {
                    control_pump(1);
                } else if (strcmp(payload, "pump_off") == 0) {
                    control_pump(0);
                } else {
                    syslog(LOG_WARNING, "Unknown pump command: %s", payload);
                }
            }

            free(payload);
        } else {
            syslog(LOG_ERR, "Failed to allocate memory for payload");
        }
    } else {
        syslog(LOG_WARNING, "Empty message received on %s", message->topic);
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    if (pump_state) {
        control_pump(0);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_pump", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed (channel %d, speed %d): %s", SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Soil moisture monitoring started");

    while (running) {
        int moisture = read_mcp3008(ADC_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            syslog(LOG_INFO, "Moisture level: %d%%", moisture);

            if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                control_pump(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                control_pump(0);
            }
        }

        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

