        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed (channel %d, speed %d): %s", SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Soil moisture monitoring started");

    while (running) {
        int moisture = read_mcp3008(ADC_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            syslog(LOG_INFO, "Moisture level: %d%%", moisture);

            if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                control_pump(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                control_pump(0);
            }
        }

        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

