    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 ADC reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (read_mcp3008(spi_fd, ADC_CHANNEL, &raw) < 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = ((float)raw / 1023.0f) * VREF;
        printf("Raw: %u, Voltage: %.3f V\n", raw, voltage);

        usleep(SAMPLE_PERIOD_US);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

