        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "ADC read error, skipping iteration\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        set_motor_speed(MOTOR1_PIN, noise_level > NOISE_THRESHOLD ? 255 : 0);
        set_motor_speed(MOTOR2_PIN, noise_level > NOISE_THRESHOLD ? 255 : 0);

        if (noise_level > NOISE_THRESHOLD) {
