#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int fd, uint8_t channel) {
    if (channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_light_level(int fd) {
    if (write(fd, 0x10, 1) != 1) {
        fprintf(stderr, "BH1750 write command failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void log_data(FILE *fp, int sound_level, int light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, 0x29) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x29: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    fflush(log_file);

    printf("Tamper detection system started. Logging to %s every %d seconds.\n", CSV_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        int sound_level = read_mcp3008(spi_fd, 0);
        int light_level = read_light_level(i2c_fd);
        int error_code = 0;

        if (sound_level < 0) {
            error_code = 1;
        } else if (light_level < 0) {
            error_code = 2;
        }

        log_data(log_file, sound_level, light_level, error_code);
        printf("Sound: %d dB, Light: %d lux, Error: %d\n", sound_level, light_level, error_code);

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

