/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 Soil Moisture Sensor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0), SPI channel 0, 1 MHz, 3-wire SPI
 *   - Vegetronix VH400 on MCP3008 CH0
 *   - Relay on BCM GPIO17 (active-high)
 *
 * Behavior:
 *   - Reads moisture level every 60 seconds.
 *   - Logs timestamped readings to the console.
 *   - Activates the relay when moisture level falls below 30%.
 *   - Handles SIGINT/SIGTERM for graceful shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define MCP3008_CHANNEL  0          /* Vegetronix VH400 on CH0 */

#define PUMP_GPIO        17         /* BCM GPIO17 – relay control */

#define MOISTURE_THRESHOLD 30.0f   /* % – below this = water needed */
#define SAMPLE_INTERVAL_S  60
#define MAX_RETRIES       3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function Prototypes --------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel);
static float calculate_moisture_level(int adc_value);
static void control_pump(float moisture_level);
static void log_data(float moisture_level);
static void signal_handler(int signal);
static void cleanup(void);

/* ------------------------------- SPI Initialization ----------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------- MCP3008 Read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (don't care, clocks out low 2 bits)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2].
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes_transferred = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes_transferred != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", bytes_transferred);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------- Moisture Calculation ------------------------ */
static float calculate_moisture_level(int adc_value)
{
    /*
     * VH400: 0–3.3 V output.
     * 10-bit ADC: 0–1023.
     * 0%  = 0 V, 3.3 V = 1023 V.
     *
     * Percentage = (adc_value / 1023.0f) * 100.0f
     */
    return ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------- Pump Control ------------------------------- */
static void control_pump(float moisture_level)
{
    if (moisture_level < MOISTURE_THRESHOLD) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            printf("Pump ON  (moisture: %.1f%% < %.1f%%)\n", moisture_level, MOISTURE_THRESHOLD);
        } else {
            fprintf(stderr, "Error: gpioWrite(PUMP_GPIO, 1) failed.\n");
        }
    } else {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            printf("Pump OFF (moisture: %.1f%% >= %.1f%%)\n", moisture_level, MOISTURE_THRESHOLD);
        } else {
            fprintf(stderr, "Error: gpioWrite(PUMP_GPIO, 0) failed.\n");
        }
    }
}

/* ------------------------------- Data Logging ------------------------------- */
static void log_data(float moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    printf("[%s] Moisture: %.1f%%\n", timestamp, moisture_level);
    fflush(stdout);
}

/* ------------------------------- Signal Handling ----------------------------- */
static void signal_handler(int signal)
{
    (void)signal;
    g_running = 0;
}

/* ------------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output, initially low */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(PUMP_GPIO, PI_OUTPUT) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(PUMP_GPIO, 0) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    printf("SPI channel %d, MCP3008 CH%d, pump on BCM GPIO%d, threshold %.1f%%\n",
           SPI_CHANNEL, MCP3008_CHANNEL, PUMP_GPIO, MOISTURE_THRESHOLD);
    printf("Logging every %d seconds. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (g_running) {
