#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define CONFIG_FILE "theremin_config.txt"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_PERIOD_NS 1000000000L
#define PWM_RANGE 1000
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 100000
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static int pwm_enabled = 0;
static int last_valid_distance = 0;
static int last_valid_volume = 0;
static float distance_min = 2.0;
static float distance_max = 400.0;
static float volume_min = 0.0;
static float volume_max = 100.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE_0;
    unsigned int bits = 8;
    unsigned int speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!trig_line || !echo_line || !pwm_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(pwm_line, "theremin", 0) < 0) {
        fprintf(stderr, "Failed to request PWM line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int pwm_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    int period_fd = open(path, O_WRONLY);
    if (period_fd < 0) {
        fprintf(stderr, "Failed to open PWM period file: %s\n", strerror(errno));
        return -1;
    }
    if (write(period_fd, "1000000000", 12) != 12) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        close(period_fd);
        return -1;
    }
    close(period_fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    int duty_fd = open(path, O_WRONLY);
    if (duty_fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle file: %s\n", strerror(errno));
        return -1;
    }
    if (write(duty_fd, "0", 1) != 1) {
        fprintf(stderr, "Failed to set PWM duty cycle to 0: %s\n", strerror(errno));
        close(duty_fd);
        return -1;
    }
    close(duty_fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    int enable_fd = open(path, O_WRONLY);
    if (enable_fd < 0) {
        fprintf(stderr, "Failed to open PWM enable file: %s\n", strerror(errno));
        return -1;
    }
    if (write(enable_fd, "1", 1) != 1) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(enable_fd);
        return -1;
    }
    close(enable_fd);

    pwm_enabled = 1;
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_distance(int adc_value) {
    if (adc_value < 0) return -1.0;
    float distance = (float)adc_value * MAX_DISTANCE / 1023.0;
    if (distance < distance_min) distance = distance_min;
    if (distance > distance_max) distance = distance_max;
    return distance;
}

static int calculate_volume(float distance) {
    if (distance < 0) return -1;
    float volume = (distance - distance_min) / (distance_max - distance_min) * (volume_max - volume_min) + volume_min;
    if (volume < 0) volume = 0;
    if (volume > volume_max) volume = volume_max;
    return (int)volume;
}

static void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    int duty_fd = open(path, O_WRONLY);
    if (duty_fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle file: %s\n", strerror(errno));
        return;
    }
    char duty_str[16];
    snprintf(duty_str, sizeof(duty_str), "%d", duty_cycle);
    if (write(duty_fd, duty_str, strlen(duty_str)) != (ssize_t)strlen(duty_str)) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
    close(duty_fd);
}

static void play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) return;
    long period_ns = 1000000000L / frequency;
    if (period_ns < 1000000L) period_ns = 1000000L;
    long half_period_ns = period_ns / 2;

    long start_ns = 0;
    long end_ns = 0;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    start_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;
    end_ns = start_ns + (long)duration_ms * 1000000L;

    while (running && end_ns > start_ns) {
        set_pwm_duty_cycle(PWM_RANGE / 2);
        usleep(half_period_ns / 1000);
        set_pwm_duty_cycle(0);
        usleep(half_period_ns / 1000);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        start_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;
    }
}

static void cleanup(void) {
    if (pwm_enabled) {
        set_pwm_duty_cycle(0);
        pwm_enabled = 0;
    }
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (pwm_line) gpiod_line_release(pwm_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

static int load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found, using defaults.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;

        if (strcmp(key, "distance_min") == 0) distance_min = atof(value);
        else if (strcmp(key, "distance_max") == 0) distance_max = atof(value);
        else if (strcmp(key, "volume_min") == 0) volume_min = atof(value);
        else if (strcmp(key, "volume_max") == 0) volume_max = atof(value);
    }
    fclose(fp);
    printf("Config loaded: distance_min=%.2f, distance_max=%.2f, volume_min=%.2f, volume_max=%.2f\n",
           distance_min, distance_max, volume_min, volume_max);
    return 0;
}

static int save_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open config file for writing: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "distance_min=%.2f\n", distance_min);
    fprintf(fp, "distance_max=%.2f\n", distance_max);
    fprintf(fp, "volume_min=%.2f\n", volume_min);
    fprintf(fp, "volume_max=%.2f\n", volume_max);
    fclose(fp);
    printf("Config saved.\n");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }
    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }
    if (pwm_init() < 0) {
        cleanup();
        return 1;
    }

    if (load_config() < 0) {
        distance_min = 2.0;
        distance_max = 400.0;
        volume_min = 0.0;
        volume_max = 100.0;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, using last valid reading.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float distance = calculate_distance(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Invalid distance, using last valid reading.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int volume = calculate_volume(distance);
        if (volume < 0) {
            fprintf(stderr, "Invalid volume, using last valid reading.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        last_valid_distance = (int)distance;
        last_valid_volume = volume;

        int frequency = (int)(volume * 100.0);
        if (frequency < 1) frequency = 1;

        play_tone(frequency, 100);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    save_config();
    return 0;
}

