    pwm_enabled = 1;
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_distance(int adc_value) {
    if (adc_value < 0) return -1.0;
    float distance = (float)adc_value * MAX_DISTANCE / 1023.0;
    if (distance < distance_min) distance = distance_min;
    if (distance > distance_max) distance = distance_max;
    return distance;
}

static int calculate_volume(float distance) {
    if (distance < 0) return -1;
    float volume = (distance - distance_min) / (distance_max - distance_min) * (volume_max - volume_min) + volume_min;
    if (volume < 0) volume = 0;
    if (volume > volume_max) volume = volume_max;
    return (int)volume;
}

static void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    int duty_fd = open(path, O_WRONLY);
    if (duty_fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle file: %s\n", strerror(errno));
        return;
    }
    char duty_str[16];
    snprintf(duty_str, sizeof(duty_str), "%d", duty_cycle);
    if (write(duty_fd, duty_str, strlen(duty_str)) != (ssize_t)strlen(duty_str)) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
    close(duty_fd);
}

static void play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) return;
    long period_ns = 1000000000L / frequency;
    if (period_ns < 1000000L) period_ns = 1000000L;
    long half_period_ns = period_ns / 2;

    long start_ns = 0;
    long end_ns = 0;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    start_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;
    end_ns = start_ns + (long)duration_ms * 1000000L;

    while (running && end_ns > start_ns) {
        set_pwm_duty_cycle(PWM_RANGE / 2);
        usleep(half_period_ns / 1000);
        set_pwm_duty_cycle(0);
        usleep(half_period_ns / 1000);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        start_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;
    }
}

static void cleanup(void) {
    if (pwm_enabled) {
        set_pwm_duty_cycle(0);
        pwm_enabled = 0;
    }
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (pwm_line) gpiod_line_release(pwm_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

static int load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found, using defaults.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;

        if (strcmp(key, "distance_min") == 0) distance_min = atof(value);
        else if (strcmp(key, "distance_max") == 0) distance_max = atof(value);
        else if (strcmp(key, "volume_min") == 0) volume_min = atof(value);
        else if (strcmp(key, "volume_max") == 0) volume_max = atof(value);
    }
    fclose(fp);
    printf("Config loaded: distance_min=%.2f, distance_max=%.2f, volume_min=%.2f, volume_max=%.2f\n",
           distance_min, distance_max, volume_min, volume_max);
    return 0;
}

static int save_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open config file for writing: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "distance_min=%.2f\n", distance_min);
    fprintf(fp, "distance_max=%.2f\n", distance_max);
    fprintf(fp, "volume_min=%.2f\n", volume_min);
    fprintf(fp, "volume_max=%.2f\n", volume_max);
    fclose(fp);
    printf("Config saved.\n");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }
    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }
    if (pwm_init() < 0) {
        cleanup();
        return 1;
    }

    if (load_config() < 0) {
        distance_min = 2.0;
        distance_max = 400.0;
        volume_min = 0.0;
        volume_max = 100.0;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, using last valid reading.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float distance = calculate_distance(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Invalid distance, using last valid reading.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int volume = calculate_volume(distance);
        if (volume < 0) {
            fprintf(stderr, "Invalid volume, using last valid reading.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        last_valid_distance = (int)distance;
        last_valid_volume = volume;

        int frequency = (int)(volume * 100.0);
        if (frequency < 1) frequency = 1;

        play_tone(frequency, 100);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    save_config();
    return 0;
}

