#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL_SEC 60

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    tx_buffer[0] = 0x01;
    tx_buffer[1] = (0x08 | channel) << 4;
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to pump GPIO %d\n", PUMP_GPIO);
    }
}

static void log_data(int moisture_value, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Moisture: %d, Pump: %s\n",
                timestamp, moisture_value, pump_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture_value = read_mcp3008(0);
        if (moisture_value < 0) {
            fprintf(stderr, "Error: Failed to read moisture sensor\n");
            log_data(-1, -1);
        } else {
            int pump_state = (moisture_value < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);
            log_data(moisture_value, pump_state);
            printf("Moisture: %d, Pump: %s\n", moisture_value, pump_state ? "ON" : "OFF");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Irrigation system stopped.\n");
    return EXIT_SUCCESS;
}

