#include <signal.h>
#include <pigpio.h>

// GPIO pin definitions
#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIRECTION 23
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0, active-low CE

// Motor speed range (0-255)
#define MIN_SPEED 0
#define MAX_SPEED 255

// Acceleration and deceleration time in seconds
#define ACCELERATION_TIME 2.0
#define DECELERATION_TIME 2.0
#define CONSTANT_SPEED_TIME 2.0
#define REVERSE_TIME 5.0

// Global variables for cleanup
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_to_speed(int adc_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    // Stop motors
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    // Terminate pigpio
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: Start bit (1), Single-ended mode (1), Channel select (3 bits), Don't care (1 bit)
    unsigned char tx_buffer[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to motor speed
int map_to_speed(int adc_value) {
    // Linear mapping: 0 ADC = MIN_SPEED, 1023 ADC = MAX_SPEED
    return MIN_SPEED + (int)(((float)adc_value / 1023.0) * (MAX_SPEED - MIN_SPEED));
}

