#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define NOISE_SAMPLES 50
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise(int *noise_level) {
    int sum = 0;
    int valid_samples = 0;

    printf("Calibrating noise level... Please keep the microphone quiet.\n");
    for (int i = 0; i < NOISE_SAMPLES; i++) {
        int val = read_mcp3008(MCP3008_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "Error reading noise sample %d\n", i);
            return -1;
        }
        sum += val;
        valid_samples++;
        usleep(SAMPLE_DELAY_US);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid noise samples collected.\n");
        return -1;
    }

    *noise_level = sum / valid_samples;
    printf("Noise level calibrated: %d\n", *noise_level);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int noise_level = 0;
    if (calibrate_noise(&noise_level) != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error reading sample. Retrying...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        int sound_level = sample - noise_level;
        if (sound_level > 0) {
            gpioWrite(LED_GPIO, 1);
            usleep(DEBOUNCE_DELAY_US);
            gpioWrite(LED_GPIO, 0);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

