#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define GPIO_CHIP       "gpiochip0"
#define GPIO_CS         8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_PERIOD_NS 1000000L  /* 1 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, GPIO_CS);
    if (!g_cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_CS, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "audio_logger", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_CS, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_cs_line = NULL;
        return -1;
    }

    return 0;
}

static int log_init(void) {
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mcp3008(uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(uint32_t timestamp_ns, int raw_adc_value) {
    if (fprintf(g_log_fp, "%u|%d\n", timestamp_ns, raw_adc_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    if (log_init() < 0) {
        gpiod_line_release(g_cs_line);
        gpiod_chip_close(g_chip);
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    struct timespec sleep_time = { 0, SAMPLE_PERIOD_NS };
    struct timespec remaining_time;

    while (g_running) {
        int raw_adc_value = read_mcp3008(0);
        if (raw_adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            nanosleep(&sleep_time, &remaining_time);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            nanosleep(&sleep_time, &remaining_time);
            continue;
        }

        uint32_t timestamp_ns = (uint32_t)ts.tv_sec * 1000000000UL + (uint32_t)ts.tv_nsec;

        if (log_data(timestamp_ns, raw_adc_value) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        nanosleep(&sleep_time, &remaining_time);
    }

    cleanup();
    return 0;
}

