#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define VREF 3.3
#define ADC_MAX 1023
#define MIN_FIELD_MT -100.0
#define MAX_FIELD_MT 100.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a digital logic state from a GPIO pin.
 * Returns 0 or 1 on success, or -1 on error.
 */
static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (pigpio error %d)\n", pin, value);
        return -1;
    }
    return value;
}

/*
 * Convert a digital logic state to a magnetic field strength in millitesla.
 * Returns 0 on success, or -1 on error.
 */
static int convert_to_field(int digital_value, float *field_mt) {
    float voltage = (float)digital_value * VREF / (float)ADC_MAX;
    if (voltage < 0.0f || voltage > VREF) {
        fprintf(stderr, "Warning: voltage %.3f V out of range for pin %d\n", voltage, digital_value);
        return -1;
    }
    *field_mt = (voltage / VREF) * 1000.0f;
    return 0;
}

/*
 * Log the three magnetic field strength values to a file.
 * Returns 0 on success, or -1 on error.
 */
static int log_data(float field1, float field2, float field3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", field1, field2, field3);
    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as inputs */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering signal handler");
        gpioTerminate();
        return EXIT_FAILURE;
