#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO        17
#define SPI_CHANNEL      0
#define SPI_SPEED        500000
#define SPI_FLAGS        0
#define MOISTURE_THRESHOLD 30.0f
#define LOG_FILE         "watering.log"
#define SAMPLE_INTERVAL  60

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, don't care */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_level(int adc_value)
{
    /*
     * MCP3008 Vref = 3.3 V, 10-bit ADC.
     * 0 V  -> 0 ADC counts
     * 3.3 V -> 1023 ADC counts
     * 100 % moisture -> 0 ADC counts
     * 0 % moisture -> 1023 ADC counts
     */
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    float moisture_level = 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
    if (moisture_level < 0.0f) moisture_level = 0.0f;
    if (moisture_level > 100.0f) moisture_level = 100.0f;
    return moisture_level;
}

static void control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", PUMP_GPIO);
    }
}

static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    fclose(fp);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output, initially low */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    /* Open SPI channel */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    log_event("Program started");

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value");
        } else {
            float moisture_level = calculate_moisture_level(adc_value);
            char log_message[128];
            snprintf(log_message, sizeof(log_message),
                     "Moisture level: %.2f%% (ADC: %d)",
                     moisture_level, adc_value);
            log_event(log_message);

            if (moisture_level < MOISTURE_THRESHOLD) {
                control_pump(1);
                log_event("Pump turned ON");
            } else {
                control_pump(0);
                log_event("Pump turned OFF");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown */
    control_pump(0);
    log_event("Program terminated");

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

