        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(uint16_t ch0, uint16_t ch1, uint16_t ch2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%u,%u,%u\n", ch0, ch1, ch2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    printf("Logging MCP3008 channel data to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        uint16_t ch0 = 0, ch1 = 0, ch2 = 0;

        if (read_mcp3008(0, &ch0) < 0) {
            fprintf(stderr, "Error reading channel 0\n");
            break;
        }
        if (read_mcp3008(1, &ch1) < 0) {
            fprintf(stderr, "Error reading channel 1\n");
            break;
        }
        if (read_mcp3008(2, &ch2) < 0) {
            fprintf(stderr, "Error reading channel 2\n");
            break;
        }

        if (log_data(ch0, ch1, ch2) < 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* Clean shutdown */
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

