/*
 * Raspberry Pi 4 Model B – MQTT LED Controller
 *
 * Subscribes to mqtt.eclipseprojects.io:1883 on the topic
 *   home/led_control
 * with client ID rpi_led_control and QoS 0.
 *
 * Parses JSON payloads of the form:
 *   { "led_state": true }
 *   { "led_state": false }
 * and drives an LED on GPIO17 (BCM) HIGH when true, LOW when false.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o led_control led_control.c -lpaho-mqtt3c
 *
 * Run:
 *   ./led_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS  "mqtt.eclipseprojects.io"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID     "rpi_led_control"
#define MQTT_TOPIC         "home/led_control"
#define MQTT_QOS           0
#define MQTT_KEEPALIVE     60

#define LED_GPIO           17
#define LED_ON             1
#define LED_OFF            0

#define MAX_RECONNECT_DELAY 60
#define MAX_PAYLOAD_LEN    256

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static MQTTClient g_client = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                     */
/* ------------------------------------------------------------------ */

static void on_connect(void *context, MQTTClient_successData *sd)
{
    (void)context;
    (void)sd;
    fprintf(stdout, "Connected to MQTT broker.\n");
}

static void on_disconnect(void *context, MQTTClient_successData *sd)
{
    (void)context;
    (void)sd;
    fprintf(stdout, "Disconnected from MQTT broker.\n");
}

static void on_message(void *context, MQTTClient_message *message)
{
    (void)context;

    if (message == NULL) {
        fprintf(stderr, "Received NULL message.\n");
        return;
    }

    if (message->payloadlen > MAX_PAYLOAD_LEN) {
        fprintf(stderr, "Payload too long (%d bytes).\n", message->payloadlen);
        MQTTClient_freeMessage(&message);
        MQTTClient_free(message->payload);
        return;
    }

    char *payload = malloc(message->payloadlen + 1);
    if (payload == NULL) {
        fprintf(stderr, "Memory allocation failed for payload.\n");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(message->payload);
        return;
    }

    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    fprintf(stdout, "Received message on topic %s: %s\n",
            message->topicName, payload);

    /* Parse JSON: { "led_state": true } or { "led_state": false } */
    JSON_Value *root = json_parse(payload);
    if (root == NULL) {
        fprintf(stderr, "JSON parse error: %s\n", json_error_string(json_get_error(root)));
        free(payload);
        MQTTClient_freeMessage(&message);
        MQTTClient_free(message->payload);
        return;
    }

    JSON_Value *led_state = json_object_get_value(root, "led_state");
    if (led_state == NULL) {
        fprintf(stderr, "Missing 'led_state' key in JSON.\n");
        json_value_free(root);
        free(payload);
        MQTTClient_freeMessage(&message);
        MQTTClient_free(message->payload);
        return;
    }

    if (!json_is_boolean(led_state)) {
        fprintf(stderr, "'led_state' is not a boolean.\n");
        json_value_free(root);
        free(payload);
        MQTTClient_freeMessage(&message);
        MQTTClient_free(message->payload);
        return;
    }

    bool led_on = json_boolean_value(led_state);

    if (gpioWrite(LED_GPIO, led_on ? LED_ON : LED_OFF) != 0) {
        fprintf(stderr, "Failed to write LED GPIO %d.\n", LED_GPIO);
    }

    json_value_free(root);
    free(payload);
    MQTTClient_freeMessage(&message);
    MQTTClient_free(message->payload);
}

static void on_error(void *context, MQTTClient_errorData *error)
{
    (void)context;
    fprintf(stderr, "MQTT error: %s\n", error->message);
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */

static int mqtt_connect(void)
{
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = MQTT_KEEPALIVE;
    conn_opts.cleansession = 1;
    conn_opts.onSuccess = on_connect;
    conn_opts.onFailure = on_error;
    conn_opts.onDisconnect = on_disconnect;

    int rc = MQTTClient_connect(g_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_connect failed: %s\n",
                MQTTClient_strerror(rc));
        return -1;
    }

    rc = MQTTClient_subscribe(g_client, MQTT_TOPIC, MQTT_QOS);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_subscribe failed: %s\n",
                MQTTClient_strerror(rc));
        MQTTClient_disconnect(g_client, 1000);
        return -1;
    }

    return 0;
}

static void mqtt_disconnect(void)
{
    if (g_client != NULL) {
        MQTTClient_disconnect(g_client, 1000);
        g_client = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_GPIO, LED_OFF) != 0) {
        fprintf(stderr, "Failed to initialise LED GPIO %d to OFF.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    gpioWrite(LED_GPIO, LED_OFF);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    install_signal_handlers();

    if (gpio_init() != 0) {
        return EXIT_FAILURE;
    }

    MQTTClient_create(&g_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                       MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (g_client == NULL) {
        fprintf(stderr, "MQTTClient_create failed.\n");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    int rc = mqtt_connect();
    if (rc != 0) {
        fprintf(stderr, "MQTT connection failed. Exiting.\n");
        mqtt_disconnect();
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Listening for messages on topic %s...\n", MQTT_TOPIC);

    while (g_running) {
        rc = MQTTClient_yield(g_client, 1000);
        if (rc == MQTTCLIENT_SUCCESS) {
            continue;
        }
        if (rc == MQTTCLIENT_DISCONNECTED) {
            fprintf(stderr, "MQTT disconnected. Attempting reconnection...\n");
            mqtt_disconnect();
            rc = mqtt_connect();
            if (rc != 0) {
                fprintf(stderr, "Reconnection failed. Exiting.\n");
                break;
            }
            continue;
        }
        fprintf(stderr, "MQTT yield error: %s\n", MQTTClient_strerror(rc));
        break;
    }

    fprintf(stdout, "Shutting down...\n");
    mqtt_disconnect();
    gpio_cleanup();
    return EXIT_SUCCESS;
}

