#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define CHIP_NAME "gpiochip4"
#define POLL_INTERVAL_MS 100
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *alarm_line = NULL;
    int ret;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (GPIO17) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("Failed to get sound sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the alarm LED line (GPIO18) */
    alarm_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_line) {
        perror("Failed to get alarm LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the sound sensor line as input */
    ret = gpiod_line_request_input(sound_line, "sound-sensor");
    if (ret < 0) {
        perror("Failed to request sound sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the alarm LED line as output, initially low */
    ret = gpiod_line_request_output(alarm_line, "alarm-led", 0);
    if (ret < 0) {
        perror("Failed to request alarm LED line as output");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("Failed to read sound sensor value");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        /* KY‑038 DO pin goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");

            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                perror("Failed to turn on alarm LED");
                break;
            }

            /* Wait for alarm duration */
            usleep(ALARM_DURATION_MS * 1000);

            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                perror("Failed to turn off alarm LED");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up GPIO resources */
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

