#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/gpiochip.h>
#include <linux/gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL  "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (chip_fd < 0) {
        perror("open(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip_fd, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER_LABEL) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);

    while (program_running) {
        struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
        int ret = gpiod_line_event_wait(line, &ts);

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }

        if (ret == 0) {
            continue; /* timeout, no event */
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        printf("Vibration detected on GPIO%d!\n", GPIO_LINE_OFFSET);

        char message[128];
        snprintf(message, sizeof(message),
                 "Vibration detected on GPIO%d! Shutting down system...",
                 GPIO_LINE_OFFSET);

        if (log_event(message) != 0) {
            fprintf(stderr, "Warning: failed to log event.\n");
        }

        if (system("sudo shutdown -h now") != 0) {
            perror("system(\"sudo shutdown -h now\")");
        }

        break;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip_fd);

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

