#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BMP280_I2C_BUS        1
#define BMP280_I2C_ADDR       0x76
#define BMP280_CHIP_ID_REG   0xD0
#define BMP280_CHIP_ID       0x60
#define BMP280_RESET_REG     0xE0
#define BMP280_RESET_CMD     0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG    0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG  0xFA
#define BMP280_CALIB_REG     0x88

#define LOG_FILE_NAME        "altitude_log.txt"
#define SAMPLE_INTERVAL_SEC  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_data;

static bmp280_calib_data g_calib;
static int32_t g_t_fine;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read error (reg 0x%02X, expected %u, got %d): %s\n",
                reg, len, rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration_data(int handle) {
    uint8_t buf[24];
    if (i2c_read_burst(handle, BMP280_CALIB_REG, buf, sizeof(buf)) < 0)
        return -1;

    g_calib.dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    g_calib.dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    g_calib.dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    g_calib.dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    g_calib.dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    g_calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    g_calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    g_calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    g_calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    g_calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    g_calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    g_calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));

    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)g_calib.dig_T1 << 1))) * ((int32_t)g_calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)g_calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)g_calib.dig_T1))) >> 12) *
            ((int32_t)g_calib.dig_T3)) >> 14;
    g_t_fine = var1 + var2;
    return (g_t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int64_t var1, var2, p;
    var1 = ((int64_t)g_t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)g_calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)g_calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)g_calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)g_calib.dig_P3) >> 8) + ((var1 * (int64_t)g_calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)g_calib.dig_P1) >> 33;
    if (var1 == 0)
        return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)g_calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)g_calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)g_calib.dig_P7) << 4);
    return (uint32_t)(p >> 8);
}

static float calculate_altitude(uint32_t pressure_pa) {
    float altitude = 44330.0f * (1.0f - powf((float)pressure_pa / 101325.0f, 0.1903f));
    return altitude;
}

static int log_altitude(float altitude) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(BMP280_I2C_BUS, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                BMP280_I2C_BUS, BMP280_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t chip_id;
    if (i2c_read_reg8(g_i2c_handle, BMP280_CHIP_ID_REG, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X). Sensor not present?\n",
                chip_id, BMP280_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_handle, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Failed to reset BMP280\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(2000);

    if (read_calibration_data(g_i2c_handle) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Failed to configure BMP280 ctrl_meas\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_handle, BMP280_CONFIG_REG, 0xA0) < 0) {
        fprintf(stderr, "Failed to configure BMP280 config\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 initialized. Logging altitude to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint8_t data[6];
        if (i2c_read_burst(g_i2c_handle, BMP280_PRESS_MSB_REG, data, sizeof(data)) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        int32_t adc_P = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
        int32_t adc_T = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));

        int32_t t_centi = compensate_temperature(adc_T) / 100;
        uint32_t p_pa = compensate_pressure(adc_P);

        float altitude = calculate_altitude(p_pa);

        if (log_altitude(altitude) < 0) {
            fprintf(stderr, "Failed to log altitude\n");
            break;
        }

        printf("Altitude: %.2f m (T=%d C, P=%u Pa)\n", altitude, t_centi, p_pa);

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

