static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_light_level(int fd, float *lux) {
    if (i2c_write_cmd(fd, BH1750_CMD_CONTINUOUS) < 0) {
        return -1;
    }
    usleep(BH1750_CONV_TIME_US);

    uint8_t buf[2];
    if (i2c_read_data(fd, buf, 2) < 0) {
        return -1;
