#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CHANNEL 0
#define DAC_ADDRESS 0x48
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000 // 0.5 seconds
#define MAX_RETRIES 3

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int write_dac(int dac_value);
int log_data(int adc_value, float temperature, int dac_value);
void signal_handler(int signal);
int initialize_spi();
int initialize_i2c();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx_buffer;
    transfer.rx_buf = (unsigned long)rx_buffer;
    transfer.len = 3;
    transfer.speed_hz = 500000; // 500 kHz
    transfer.bits_per_word = 8;
    transfer.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error: SPI transfer failed");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    // TMP36: 10-bit ADC, 0-3.3V range, 10mV/°C
    // Assuming 3.3V reference voltage
    float voltage = (adc_value * 3.3f) / 1023.0f;
    float temperature = voltage * 100.0f;
    return temperature;
}

// Function to write to MCP4725 DAC
int write_dac(int dac_value) {
    if (dac_value < 0 || dac_value > 4095) {
        fprintf(stderr, "Error: Invalid DAC value: %d\n", dac_value);
        return -1;
    }

    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    // Construct I2C message for MCP4725
    tx_buffer[0] = 0x40; // Write to DAC register
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    tx_buffer[2] = dac_value & 0x0F; // Lower 4 bits

    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data ioctl_data;

    msgs[0].addr = DAC_ADDRESS;
    msgs[0].flags = 0; // Write
    msgs[0].len = 3;
    msgs[0].buf = (unsigned long)tx_buffer;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("Error: I2C write failed");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(int adc_value, float temperature, int dac_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %d\n", timestamp, adc_value, temperature, dac_value) < 0) {
        perror("Error: Failed to write to log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Error: Failed to flush log file");
        return -1;
    }

    return 0;
}

// Function to initialize SPI interface
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error: Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error: Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error: Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = 500000; // 500 kHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error: Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Function to initialize I2C interface
int initialize_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, DAC_ADDRESS) < 0) {
        perror("Error: Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Error: SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = -1;
        int retries = 0;

        // Retry loop for ADC read
        while (retries < MAX_RETRIES && program_running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Error: ADC read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                usleep(100000); // 100ms delay before retry
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed after %d retries. Skipping sample.\n", MAX_RETRIES);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Write DAC value based on temperature
        int dac_value = (int)(temperature / 10.0f); // Assuming 10mV/°C
        if (write_dac(dac_value) != 0) {
            fprintf(stderr, "Error: Failed to write DAC value.\n");
        }

        // Log data
        if (log_data(adc_value, temperature, dac_value) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        // Print data to console
        printf("ADC: %d, Temperature: %.2f C, DAC: %d\n", adc_value, temperature, dac_value);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

