#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL_SEC 60

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, don't care */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static int log_data(int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int sensor_values[NUM_SENSORS];
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping cycle\n", i + 1);
                continue;
            }
        }

        if (log_data(sensor_values[0], sensor_values[1], sensor_values[2]) != 0) {
            fprintf(stderr, "Error logging data, continuing\n");
        }

        printf("Sensor 1: %d, Sensor 2: %d, Sensor 3: %d\n",
               sensor_values[0], sensor_values[1], sensor_values[2]);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

