#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for relays (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define number of relays
#define NUM_RELAYS 4

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void deactivate_all_relays(void);
void signal_handler(int signal);

// Initialize GPIO pins using pigpio library
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set relay pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially inactive (LOW, assuming active-high relays)
    deactivate_all_relays();

    return 0;
}

// Activate a relay by setting its GPIO pin HIGH
void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate relay on GPIO %d\n", relay_pin);
    }
}

// Deactivate a relay by setting its GPIO pin LOW
void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate relay on GPIO %d\n", relay_pin);
    }
}

// Deactivate all relays
void deactivate_all_relays(void) {
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(void) {
    // Install signal handlers for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    // Main loop: activate relays one by one, deactivate, wait
    while (program_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            activate_relay(RELAY1_PIN + i);
            printf("Relay %d activated\n", i + 1);
            sleep(1);
            deactivate_relay(RELAY1_PIN + i);
            printf("Relay %d deactivated\n", i + 1);
            if (program_running) {
                sleep(1);
            }
        }
    }

    // Cleanup: deactivate all relays and terminate pigpio
    deactivate_all_relays();
    gpioTerminate();

    printf("Light sequencer stopped.\n");
    return EXIT_SUCCESS;
}

