#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_PWM_PIN 27
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150
#define MOTOR_RUN_TIME_SEC 3
#define POLL_INTERVAL_SEC 1
#define LOG_FILE "rain_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_rain_level(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void motor_forward(void) {
    if (gpioWrite(MOTOR_FORWARD_PIN, 1) < 0) {
        fprintf(stderr, "Error writing to motor forward pin\n");
        return;
    }
    if (gpioWrite(MOTOR_REVERSE_PIN, 0) < 0) {
        fprintf(stderr, "Error writing to motor reverse pin\n");
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        fprintf(stderr, "Error setting motor PWM duty\n");
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_REVERSE_PIN, 0);
        return;
    }
}

static void motor_reverse(void) {
    if (gpioWrite(MOTOR_FORWARD_PIN, 0) < 0) {
        fprintf(stderr, "Error writing to motor forward pin\n");
        return;
    }
    if (gpioWrite(MOTOR_REVERSE_PIN, 1) < 0) {
        fprintf(stderr, "Error writing to motor reverse pin\n");
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        fprintf(stderr, "Error setting motor PWM duty\n");
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_REVERSE_PIN, 0);
        return;
    }
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_REVERSE_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

static void cleanup(void) {
    motor_stop();
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor forward pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_REVERSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor reverse pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor PWM pin mode\n");
        cleanup();
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    int window_open = 1;

    while (running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain level, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (log_rain_level(rain_level) < 0) {
            fprintf(stderr, "Error logging rain level, continuing...\n");
        }

        if (rain_level > RAIN_THRESHOLD && window_open) {
            printf("Rain detected! Closing window...\n");
            motor_forward();
            sleep(MOTOR_RUN_TIME_SEC);
            motor_stop();
            window_open = 0;
        } else if (rain_level <= RAIN_THRESHOLD && !window_open) {
            printf("Rain stopped! Opening window...\n");
            motor_reverse();
            sleep(MOTOR_RUN_TIME_SEC);
            motor_stop();
            window_open = 1;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

