/*
 * MAX9814 Electret Microphone Clap Detector for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MAX9814 electret microphone amplifier -> ADC input (BCM GPIO26)
 *   - LED indicator -> BCM GPIO16
 *
 * Behavior:
 *   - Reads the analog value from the ADC every 10 ms.
 *   - Detects a rising edge on the ADC output (clap) with a 50 ms debounce.
 *   - Turns on the LED for 500 ms and prints a timestamped detection message.
 *   - Handles SIGINT for graceful shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o clap_detector clap_detector.c -lpigpio -lrt
 *   sudo ./clap_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_PIN      26          /* BCM GPIO26 - MAX9814 ADC input */
#define LED_PIN      16          /* BCM GPIO16 - LED indicator */
#define DEBOUNCE_US  50000       /* 50 ms debounce window in microseconds */
#define LED_ON_US    500000      /* 500 ms LED on duration in microseconds */
#define SAMPLE_US    10000       /* 10 ms sampling interval in microseconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                            */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
