        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        spiClose(spi_handle);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
        } else {
            float field_mt = adc_to_mt(adc_value);
            log_reading(field_mt);
            control_led(field_mt);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
