/*
 * MLX91211 Current Sensor Logger for Raspberry Pi Zero W
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0=GPIO8, MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11)
 *   - MLX91211 current sensor output -> MCP3008 CH0
 *   - MCP3008 VDD/VREF -> Pi 5V rail
 *   - MLX91211 VDD -> Pi 5V pin
 *
 * Build:
 *   gcc -O2 -Wall -o current_logger current_logger.c -lmcp3008
 *
 * Run:
 *   ./current_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <mcp3008.h>

#define SPI_CHANNEL      0          /* CE0 on GPIO8 */
#define SPI_SPEED_HZ     1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 CH0 */
#define VREF             5.0        /* Pi 5V rail */
#define CURRENT_MIN      0.0        /* MLX91211 minimum output (A) */
#define CURRENT_MAX      5.0        /* MLX91211 maximum output (A) */
#define SAMPLE_PERIOD_US 100000     /* 100 ms */
#define LOG_FILE         "current_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    mcp3008_close();
}

/* ------------------------------------------------------------------ */
/* Read current from MCP3008 channel (0-7)                             */
/* Returns 0 on success and stores current in *out_current_a;        */
/* returns -1 on SPI transfer error;                                 */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel, float *out_current_a)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    int ret = mcp3008_read(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    float voltage = ((float)adc_value / 1023.0f) * VREF;

    /*
     * MLX91211: Vout = I * R_load (R_load = 100 kΩ for typical module).
     * Current = Vout / R_load.
     */
    float current = voltage / 100.0f;

    if (current < CURRENT_MIN || current > CURRENT_MAX) {
        fprintf(stderr,
                "Warning: voltage %.3f V out of range [%.1f, %.1f] A\n",
                voltage, CURRENT_MIN, CURRENT_MAX);
        return -1;
    }

    *out_current_a = current;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append current reading to log file                                  */
/* Returns 0 on success; returns -1 on file write error.             */
/* ------------------------------------------------------------------ */
static int log_current(float current_a)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s %.2f A\n", timestamp, current_a) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize MCP3008 library */
    if (mcp3008_init() != 0) {
        fprintf(stderr, "Error: mcp3008_init failed (library initialization failed)\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        mcp3008_close();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current sensor logger started.\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 CH0, logging to '%s'.\n",
           SPI_SPEED_HZ, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float current_a;

        if (read_mcp3008(ADC_CHANNEL, &current_a) == 0) {
            if (log_current(current_a) != 0) {
                fprintf(stderr, "Error: failed to log current reading.\n");
            }
        } else {
            fprintf(stderr, "Error: failed to read current from MCP3008.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(SAMPLE_PERIOD_US / 10);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

