#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpioRead(gpio);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(val));
            return -1;
        }
        sum += val;
        if (i < DEBOUNCE_SAMPLES - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (sum >= (DEBOUNCE_SAMPLES / 2)) ? 0 : 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        int object_present = (s1 == 0 || s2 == 0);
        int both_objects = (s1 == 0 && s2 == 0);

        printf("Sensor1: %d, Sensor2: %d, Object Present: %d, Both Objects: %d\n",
               s1, s2, object_present, both_objects);

        if (both_objects) {
            printf("ALERT: Both sensors detect object\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

