/*
 * security_cam.c — Raspberry Pi 4 Model B
 *
 * Monitors an HC-SR501 PIR sensor on GPIO17 (BCM) with a pull-down
 * resistor.  Polls every 50 ms, applies a 200 ms debounce delay, then
 * re-reads to confirm motion, then launches libcamera-still to
 * capture a JPEG snapshot with a timestamped filename into
 * /home/pi/security_cam.
 *
 * Build:  gcc -O2 -Wall -Wextra -o security_cam security_cam.c -lgpiod
 * Run:    sudo ./security_cam
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#include <syslog.h>

#define GPIO_CHIP_NAME      "gpiochip4"   /* BCM GPIO on Pi 4 */
#define PIR_PIN             17
#define DEBOUNCE_MS         200
#define POLL_INTERVAL_MS    50
#define CAPTURE_DIR         "/home/pi/security_cam"
#define MAX_FILENAME_LEN    256
#define MAX_CMD_LEN         512

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "%s exists but is not a directory", path);
        return -1;
    }

    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat(%s): %s", path, strerror(errno));
        return -1;
    }

    if (mkdir(path, 0755) == -1) {
        syslog(LOG_ERR, "mkdir(%s): %s", path, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Created directory: %s", path);
    return 0;
}

static int generate_filename(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        syslog(LOG_ERR, "localtime_r failed: %s", strerror(errno));
        return -1;
    }

    if (strftime(buf, len, "%Y%m%d_%H%M%S.jpg", &timeinfo) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return -1;
    }
    return 0;
}

static int launch_camera_capture(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null so the parent
         * doesn't block waiting for the child to finish. */
        int devnull = open("/dev/null", O_WRONLY);
        if (devnull < 0) {
            syslog(LOG_ERR, "open(/dev/null): %s", strerror(errno));
            _exit(EXIT_FAILURE);
        }

        if (dup2(devnull, STDOUT_FILENO) < 0) {
            syslog(LOG_ERR, "dup2(stdout): %s", strerror(errno));
            _exit(EXIT_FAILURE);
        }
        if (dup2(devnull, STDERR_FILENO) < 0) {
            syslog(LOG_ERR, "dup2(stderr): %s", strerror(errno));
            _exit(EXIT_FAILURE);
        }

        /* Close the original descriptors so the child doesn't block. */
        close(devnull);

        /*
         * execvp("libcamera-still") — never returns on success,
         * only on failure.
         */
        char *const argv[] = {
            "libcamera-still",
            "-o", filename,
            "--nopreview",
            NULL
        };

        execvp("libcamera-still", argv);

        /* If execvp returns, it failed. */
        syslog(LOG_ERR, "execvp(libcamera-still): %s", strerror(errno));
        _exit(EXIT_FAILURE);
    }

    /* Parent: wait for the child to finish. */
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "libcamera-still captured: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (exit status %d)",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize the GPIO chip and request the PIR pin as input. */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (pir_line == NULL) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s",
               PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(pir_line, "security_cam",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_input_flags: %s",
               strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started on GPIO%d (libcamera-still)",
           PIR_PIN);

    /* Ensure the capture directory exists. */
    if (ensure_directory(CAPTURE_DIR) != 0) {
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    bool last_state = false;
    int consecutive_errors = 0;

    while (g_running) {
        int value = gpiod_line_get_value(pir_line);
        if (value < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value: %s", strerror(errno));
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                syslog(LOG_ERR, "Too many consecutive GPIO errors; aborting");
                break;
            }
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        consecutive_errors = 0;

        bool current_state = (value == 1);

        if (current_state && !last_state) {
            syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_PIN);

            char filename[MAX_FILENAME_LEN];
            if (generate_filename(filename, sizeof(filename)) != 0) {
                syslog(LOG_ERR, "Failed to generate filename");
                usleep(POLL_INTERVAL_MS * 1000);
                continue;
            }

            if (launch_camera_capture(filename) != 0) {
                syslog(LOG_ERR, "Failed to launch camera capture");
            }
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean shutdown: stop the main loop, release resources, and close
     * syslog. */
    syslog(LOG_INFO, "Shutting down...");
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

