#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define NUM_BUFFERS 4
#define MAX_PACKET_SIZE 65000
#define MAX_FRAMES 100

typedef struct {
    unsigned char *start;
    size_t length;
} buffer_t;

typedef struct {
    int frame_index;
    int fragment_index;
    int total_fragments;
    int payload_size;
} frame_header_t;

static volatile sig_atomic_t stop_flag = 0;
static int fd = -1;
static buffer_t *buffers = NULL;
static unsigned int n_buffers = 0;
static int sockfd = -1;
static struct sockaddr_in servaddr;

static void signal_handler(int signum) {
    (void)signum;
    stop_flag = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_device(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        fd = -1;
        return -1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(fd);
        fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Error: Unsupported pixel format: %c%c%c%c\n",
                (fmt.fmt.pix.pixelformat & 0xFF),
                (fmt.fmt.pix.pixelformat >> 8) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 16) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 24) & 0xFF);
        close(fd);
        fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.width != 640 || fmt.fmt.pix.height != 480) {
        fprintf(stderr, "Warning: Image size not supported: %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(fd);
        fd = -1;
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        close(fd);
        fd = -1;
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Error allocating buffer memory");
        close(fd);
        fd = -1;
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            close(fd);
            fd = -1;
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            fd = -1;
            return -1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            close(fd);
            fd = -1;
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

static int capture_frame(void) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Error: Buffer index out of range\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error re-queuing buffer");
        return -1;
    }

    return 0;
}

static int send_packet(const unsigned char *data, size_t size) {
    frame_header_t header;
    header.frame_index = 0;
    header.fragment_index = 0;
    header.total_fragments = 1;
    header.payload_size = (int)size;

    size_t total_size = sizeof(header) + size;
    size_t sent = 0;

    while (sent < total_size) {
        ssize_t n = sendto(sockfd, data + sent, total_size - sent, 0,
                          (const struct sockaddr *)&servaddr, sizeof(servaddr));
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error sending packet");
            return -1;
        }
        sent += n;
    }

    return 0;
}

static void cleanup(void) {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);

        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }

        if (buffers) {
            free(buffers);
            buffers = NULL;
        }

        close(fd);
        fd = -1;
    }

    if (sockfd != -1) {
        close(sockfd);
        sockfd = -1;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <library's API call> <the library's API call>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "v4l2_open") == 0) {
        if (init_device() != 0) {
            return EXIT_FAILURE;
        }
    } else if (strcmp(argv[1], "v4l2_close") == 0) {
        cleanup();
        return EXIT_SUCCESS;
    } else {
        fprintf(stderr, "Error: Invalid API call '%s'\n", argv[1]);
        return EXIT_FAILURE;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Error creating socket");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(5000);

    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        perror("Error converting address");
        close(sockfd);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting SIGINT handler");
        close(sockfd);
        cleanup();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting SIGTERM handler");
        close(sockfd);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting video streaming to 127.0.0.1:5000...\n");

    while (!stop_flag) {
        if (capture_frame() == 0) {
            if (send_packet(buffers[0].start, buffers[0].length) != 0) {
                fprintf(stderr, "Error sending frame\n");
            }
        } else {
            fprintf(stderr, "Error capturing frame\n");
        }
        usleep(10000);
    }

    printf("\nExiting...\n");
    cleanup();
    return EXIT_SUCCESS;
}

