#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define WIDTH 192
#define HEIGHT 192
#define NUM_BUFFERS 4

static volatile sig_atomic_t stop_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_requested = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    void *buffers[NUM_BUFFERS];
    unsigned int n_buffers = 0;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_streamparm parm;
    enum v4l2_buf_type type;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    ret = xioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    if (cap.capabilities & V4L2_CAP_DEVICE_CAPS) {
        if (cap.device_caps & V4L2_DEVICE_CAP_MMAP) {
            printf("Device supports memory-mapped I/O\n");
        } else {
            printf("Device does not support memory-mapped I/O\n");
        }
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = xioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        goto cleanup;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Warning: device did not accept requested resolution (%dx%d), got %dx%d\n",
                WIDTH, HEIGHT, fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = xioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    n_buffers = req.count;

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = xioctl(fd, VIDIOC_QUERYBUF, &buf);
        if (ret == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = xioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = xioctl(fd, VIDIOC_STREAMON, &type);
    if (ret == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    printf("Streaming started. Capturing MJPEG frame...\n");

    while (!stop_requested) {
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            goto cleanup;
        }
        if (ret == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        ret = xioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }

        if (buf.bytesused > 0) {
            FILE *fp = fopen(IMAGE_FILE, "wb");
            if (!fp) {
                perror("fopen(" IMAGE_FILE ")");
                goto cleanup;
            }

            size_t written = fwrite(buffers[buf.index], 1, buf.bytesused, fp);
            if (written != buf.bytesused) {
                fprintf(stderr, "Short write to %s: %zu of %u bytes\n", IMAGE_FILE, written, buf.bytesused);
                fclose(fp);
                goto cleanup;
            }

            if (fclose(fp) != 0) {
                perror("fclose(" IMAGE_FILE ")");
                goto cleanup;
            }

            printf("Image saved to %s (%zu bytes)\n", IMAGE_FILE, buf.bytesused);
        } else {
            fprintf(stderr, "Zero-length frame received\n");
        }

        ret = xioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = xioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret == -1) {
        perror("VIDIOC_STREAMOFF");
        goto cleanup;
    }

    printf("Streaming stopped.\n");

cleanup:
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (buffers[i] != MAP_FAILED) {
            munmap(buffers[i], fmt.fmt.pix.width * fmt.fmt.pix.height * 2);
        }
    }

    if (fd != -1) {
        close(fd);
    }

    return EXIT_SUCCESS;
}

