#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN  8
#define PAN_RIGHT_BUTTON_PIN 9

#define PWM_FREQUENCY      50
#define PWM_RANGE          1000
#define PWM_DUTY_MIN       1000   /* 1 ms  */
#define PWM_DUTY_MAX       2000   /* 2 ms  */
#define PWM_DUTY_MID       1500   /* 1.5 ms */

#define PAN_MIN_POS        25
#define PAN_MAX_POS        125
#define TILT_MIN_POS       25
#define TILT_MAX_POS       125

#define POLL_DELAY_US      50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Generate a 50 Hz PWM wave on the given GPIO pin.
 * duty_us is a value between 0 and PWM_RANGE.
