    *blurred_size = blurred_size_padded;

    unsigned char *blurred_ptr = (unsigned char *)*blurred;
    const unsigned char *rgb24_ptr = (const unsigned char *)rgb24;

    for (size_t i = 0; i < height; i++) {
        for (size_t j = 0; j < width; j++) {
            size_t r0 = i * width + j;
            size_t r1 = (i + 1) * width + j;
