#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define QUALITY 75
#define TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: driver did not accept YUYV format, got %c%c%c%c\n",
                (fmt.fmt.pix.pixelformat >> 0) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 8) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 16) & 0xFF,
                (fmt.fmt.pix.pixelformat >> 24) & 0xFF);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    void *start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 1;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        munmap(start, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        munmap(start, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 2;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        munmap(start, buf.length);
        munmap(start + buf.length, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        munmap(start, buf.length);
        munmap(start + buf.length, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 3;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        munmap(start, buf.length);
        munmap(start + buf.length, buf.length);
        munmap(start + 2 * buf.length, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        munmap(start, buf.length);
        munmap(start + buf.length, buf.length);
        munmap(start + 2 * buf.length, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        munmap(start, buf.length);
        munmap(start + buf.length, buf.length);
        munmap(start + 2 * buf.length, buf.length);
        munmap(start + 3 * buf.length, buf.length);
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, void **frame_data, size_t *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(*fd, &fds);

    struct timeval tv;
    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) return 1;
        fprintf(stderr, "Error selecting frame: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index != 0 && buf.index != 1 && buf.index != 2 && buf.index != 3) {
        fprintf(stderr, "Invalid buffer index: %d\n", buf.index);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    *frame_data = start + buf.m.offset;
    *frame_size = buf.bytesused;

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int convert_yuyv_to_rgb24(const void *yuyv, size_t size, void **rgb24, size_t *rgb24_size) {
    if (size % 4 != 0) {
        fprintf(stderr, "YUYV size not multiple of 4\n");
        return -1;
    }

    size_t width_padded = (size + 1) & ~1;
    size_t height_padded = (size + 3) & ~3;
    size_t rgb24_size_padded = width_padded * height_padded * 3;

    *rgb24 = malloc(rgb24_size_padded);
    if (!*rgb24) {
        fprintf(stderr, "Error allocating RGB24 buffer: %s\n", strerror(errno));
        return -1;
    }
    *rgb24_size = rgb24_size_padded;

    unsigned char *rgb24_ptr = (unsigned char *)*rgb24;
    const unsigned char *yuyv_ptr = (const unsigned char *)yuyv;

    for (size_t i = 0; i < height_padded; i++) {
        for (size_t j = 0; j < width_padded; j += 2) {
            size_t y0 = i * width_padded + j;
            size_t y1 = i * width_padded + j + 1;
            size_t r0 = y0 * 2;
            size_t g0 = y0 * 2 + 1;
            size_t b0 = y0 * 2 + 2;
            size_t r1 = y1 * 2;
            size_t g1 = y1 * 2 + 1;
            size_t b1 = y1 * 2 + 2;

            unsigned char y0_c = yuyv_ptr[y0 * 4];
            unsigned char u0_c = yuyv_ptr[y0 * 4 + 1];
            unsigned char y1_c = yuyv_ptr[y1 * 4];
            unsigned char u1_c = yuyv_ptr[y1 * 4 + 1];

            int r0_int = (int)(y0_c + 1.402 * (u0_c - 128));
            int g0_int = (int)(y0_c - 0.344 * (u0_c - 128) - 0.714 * (v0_c - 128));
            int b0_int = (int)(y0_c + 1.772 * (v0_c - 128));
            int r1_int = (int)(y1_c + 1.402 * (u1_c - 128));
            int g1_int = (int)(y1_c - 0.344 * (u1_c - 128) - 0.714 * (v1_c - 128));
            int b1_int = (int)(y1_c + 1.772 * (v1_c - 128));

            if (r0_int < 0) r0_int = 0;
            if (r0_int > 255) r0_int = 255;
            if (g0_int < 0) g0_int = 0;
            if (g0_int > 255) g0_int = 255;
            if (b0_int < 0) b0_int = 0;
            if (b0_int > 255) b0_int = 255;
            if (r1_int < 0) r1_int = 0;
            if (r1_int > 255) r1_int = 255;
            if (g1_int < 0) g1_int = 0;
            if (g1_int > 255) g1_int = 255;
            if (b1_int < 0) b1_int = 0;
            if (b1_int > 255) b1_int = 255;

            rgb24_ptr[r0 * 3] = (unsigned char)r0_int;
            rgb24_ptr[g0 * 3] = (unsigned char)g0_int;
            rgb24_ptr[b0 * 3] = (unsigned char)b0_int;
            rgb24_ptr[r1 * 3] = (unsigned char)r1_int;
            rgb24_ptr[g1 * 3] = (unsigned char)g1_int;
            rgb24_ptr[b1 * 3] = (unsigned char)b1_int;
        }
    }

    return 0;
}

static int blur_rgb24(const void *rgb24, size_t size, void **blurred, size_t *blurred_size) {
    if (size % 3 != 0) {
        fprintf(stderr, "RGB24 size not multiple of 3\n");
        return -1;
    }

    size_t width = size / 3;
    size_t height = size / width;
    size_t blurred_size_padded = width * height * 3;

    *blurred = malloc(blurred_size_padded);
