            size_t r8 = (i + 8) * width + j;

            int r0_int = rgb24_ptr[r0 * 3];
            int r1_int = rgb24_ptr[r1 * 3];
            int r2_int = rgb24_ptr[r2 * 3];
            int r3_int = rgb24_ptr[r3 * 3];
