            int r6_int = rgb24_ptr[r6 * 3];
            int r7_int = rgb24_ptr[r7 * 3];
            int r8_int = rgb24_ptr[r8 * 3];

            int sum = r0_int + r1_int + r2_int + r3_int + r4_int + r5_int + r6_int + r7_int + r8_int;
            int avg = sum / 9;

            blurred_ptr[r0 * 3] = (unsigned char)avg;
            blurred_ptr[r1 * 3] = (unsigned char)avg;
            blurred_ptr[r2 * 3] = (unsigned char)avg;
            blurred_ptr[r3 * 3] = (unsigned char)avg;
            blurred_ptr[r4 * 3] = (unsigned char)avg;
            blurred_ptr[r5 * 3] = (unsigned char)avg;
            blurred_ptr[r6 * 3] = (unsigned char)avg;
            blurred_ptr[r7 * 3] = (unsigned char)avg;
            blurred_ptr[r8 * 3] = (unsigned char)avg;
        }
    }

    return 0;
}

