/*
 * csi_camera_info.c — Print a summary of the CSI camera capabilities on a
 * Raspberry Pi running a 32-bit or 64-bit kernel with the V4L2 subsystem
 * active.
 *
 * Build:  gcc -O2 -Wall -Wextra -o csi_camera_info csi_camera_info.c
 * Run:    ./csi_camera_info
 */

#include <errno.h>
#include <fcntl.h>
#include <linux/videodev2.h>
#include <stdio.h>
