/*
 * Raspberry Pi Pan-Tilt Camera Controller
 *
 * Hardware:
 *   - Pan servo:  GPIO4 (BCM)  -> hobby servo driver PWM0
 *   - Tilt servo: GPIO5 (BCM)  -> hobby servo driver PWM1
 *   - UP button:  GPIO6 (BCM)  -> active-low push button
 *   - DOWN button: GPIO7 (BCM)  -> active-low push button
 *   - LEFT button: GPIO8 (BCM)  -> active-low push button
 *   - RIGHT button: GPIO9 (BCM) -> active-low push button
 *
 * Build:
 *   gcc -O2 -Wall -o pantilt pantilt.c -lpigpio -lrt
 * Run:
 *   sudo ./pantilt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5

#define UP_BUTTON_PIN      6
#define DOWN_BUTTON_PIN    7
#define LEFT_BUTTON_PIN    8
#define RIGHT_BUTTON_PIN   9

#define MIN_PULSE_WIDTH    1000   /* µs  - servo minimum */
#define MAX_PULSE_WIDTH    2000   /* µs  - servo maximum */
#define CENTER_PULSE_WIDTH 1500   /* µs  - center position */
#define STEP_SIZE         10     /* µs  - pulse width change per iteration */
#define LOOP_DELAY_US     50000  /* µs  - 50 ms between iterations */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown (SIGINT, SIGTERM)                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure the four button pins as inputs       */
/* with internal pull-ups. Returns 0 on success, -1 on failure.        */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", UP_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", UP_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Set a servo pulse width (µs) using the pigpio hardware PWM API.    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int set_servo_pulse_width(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    }
    if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed on GPIO%d (pulse=%d µs).\n",
                pin, pulse_width);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a button: returns 1 if pressed (active-low), 0 if released,     */
/* -1 on read error.                                                  */
/* ------------------------------------------------------------------ */
static int read_button(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", pin);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Adjust the servo pulse width based on a button press.               */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int adjust_servo_position(int pin, int *pulse_width)
{
    int direction = 0;

    if (read_button(UP_BUTTON_PIN) == 1) {
        direction = 1;
    } else if (read_button(DOWN_BUTTON_PIN) == 1) {
        direction = -1;
    } else if (read_button(LEFT_BUTTON_PIN) == 1) {
        direction = -1;
    } else if (read_button(RIGHT_BUTTON_PIN) == 1) {
        direction = 1;
    }

    if (direction != 0) {
        *pulse_width += direction * STEP_SIZE;
        if (*pulse_width < MIN_PULSE_WIDTH) {
            *pulse_width = MIN_PULSE_WIDTH;
        } else if (*pulse_width > MAX_PULSE_WIDTH) {
            *pulse_width = MAX_PULSE_WIDTH;
        }
        if (set_servo_pulse_width(pin, *pulse_width) != 0) {
            return -1;
        }
        printf("Servo on GPIO%d adjusted to pulse width: %d µs\n",
               pin, *pulse_width);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Clean shutdown: stop PWM on both servo pins and release pigpio.     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM on both servo pins */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();
    printf("\npigpio terminated. Exiting.\n");
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pulse_width = CENTER_PULSE_WIDTH;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Camera Controller\n");
    printf("=========================\n");
    printf("Pan servo: GPIO%d (PWM0)\n", PAN_SERVO_PIN);
    printf("Tilt servo: GPIO%d (PWM1)\n", TILT_SERVO_PIN);
    printf("Buttons: GPIO%d, GPIO%d, GPIO%d, GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center position: %d µs\n", CENTER_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main control loop */
    while (g_running) {
        if (adjust_servo_position(PAN_SERVO_PIN, &pulse_width) != 0) {
            break;
        }
        if (adjust_servo_position(TILT_SERVO_PIN, &pulse_width) != 0) {
            break;
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

