#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>
#include <httplib.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_HTTP_RESPONSE_LEN 1024
#define HTTP_PORT 80
#define HTTP_TIMEOUT_SEC 10
#define QUALITY 85
#define IMAGE_DIR "motion_captures"

static volatile sig_atomic_t running = 1;
static int pigpio_initialized = 0;
static struct http_client *http_client = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", PIR_GPIO);
        return -1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d.\n", PIR_GPIO);
        return -1;
    }

    return 0;
}

static int initialize_http(const char *ip_address, int port) {
    http_client = curl_easy_init();
    if (!http_client) {
        fprintf(stderr, "Error: curl_easy_init() failed.\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed.\n");
        curl_easy_cleanup(http_client);
        http_client = NULL;
        return -1;
    }

    curl_easy_setopt(http_client, CURLOPT_URL, "http://");
    curl_easy_setopt(http_client, CURLOPT_PORT, port);
    curl_easy_setopt(http_client, CURLOPT_POST, 1L);
    curl_easy_setopt(http_client, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(http_client, CURLOPT_TIMEOUT, HTTP_TIMEOUT_SEC);
    curl_easy_setopt(http_client, CURLOPT_CONNECTTIMEOUT, HTTP_TIMEOUT_SEC);
    curl_easy_setopt(http_client, CURLOPT_POSTFIELDS, "");
    curl_easy_setopt(http_client, CURLOPT_POSTFIELDSIZE, (long)0);

    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command), "raspistill -o %s -q %d", filename, QUALITY);

    int ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error: system() failed to execute raspistill.\n");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "Error: raspistill exited with status %d.\n", WEXITSTATUS(ret));
        return -1;
    }
    return 0;
}

static int send_image_to_server(const char *filename, const char *ip_address, int port) {
    if (!http_client) {
        fprintf(stderr, "Error: HTTP client not initialized.\n");
        return -1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    char json_string[MAX_JSON_LEN];
    json_t *root = json_object();
    if (!root) {
        fprintf(stderr, "Error: json_object() failed.\n");
        return -1;
    }

    json_object_set_new(root, "filename", json_string(filename));
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "motion_detected", json_true());
    json_object_set_new(root, "gpio_pin", json_integer(PIR_GPIO));

    char *json_string_ptr = json_dumps(root, JSON_INDENT(4));
    if (!json_string_ptr) {
        fprintf(stderr, "Error: json_dumps() failed.\n");
        json_decref(root);
        return -1;
    }

    json_decref(root);

    curl_easy_setopt(http_client, CURLOPT_POSTFIELDS, json_string_ptr);
    curl_easy_setopt(http_client, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string_ptr));

    CURLcode res = curl_easy_perform(http_client);
    free(json_string_ptr);

    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    char response[MAX_HTTP_RESPONSE_LEN];
    long response_size = 0;
    curl_easy_getinfo(http_client, CURLINFO_RESPONSE_CODE, &response_size);
    if (response_size > 0) {
        response_size = (response_size < MAX_HTTP_RESPONSE_LEN - 1) ? response_size : MAX_HTTP_RESPONSE_LEN - 1;
        curl_easy_getinfo(http_client, CURLINFO_RESPONSE_CODE, response);
        fprintf(stderr, "HTTP response: %s\n", response);
    }

    return 0;
}

static void cleanup(void) {
    if (http_client) {
        curl_easy_cleanup(http_client);
        http_client = NULL;
    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (http_global_init(CURL_GLOBAL_ALL) == CURLE_OK) {
        curl_global_cleanup();
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <ip_address> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip_address = argv[1];
    int port = atoi(argv[2]);

    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_http(ip_address, port) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Motion detection system started. Monitoring GPIO%d for motion.\n", PIR_GPIO);
    printf("IP address: %s, Port: %d\n", ip_address, port);
    printf("Press Ctrl+C to exit.\n");

    int last_motion_detected = 0;
    time_t last_motion_time = 0;

    while (running) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "Error: Failed to read GPIO%d.\n", PIR_GPIO);
            break;
        }

        if (motion_detected && !last_motion_detected) {
            time_t current_time = time(NULL);
            if (current_time - last_motion_time >= DEBOUNCE_SEC) {
                last_motion_time = current_time;
                last_motion_detected = 1;

                char filename[MAX_FILENAME_LEN];
                snprintf(filename, sizeof(filename), "%s/motion_%ld.jpg", IMAGE_DIR, (long)current_time);

                if (capture_image(filename) == 0) {
                    printf("Motion detected! Captured image: %s\n", filename);
                    if (send_image_to_server(filename, ip_address, port) != 0) {
                        fprintf(stderr, "Error: Failed to send image to server.\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to capture image.\n");
                }
            }
        } else if (!motion_detected && last_motion_detected) {
            last_motion_detected = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Motion detection system stopped.\n");

    return EXIT_SUCCESS;
}

