#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT_MS 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                      "raspistill -o %s -w 640 -h 480 -q 85 --timeout %d --nopreview",
                      filename, CAPTURE_TIMEOUT_MS);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        log_message("Error: command buffer too small for capture");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        log_message("Error: system() failed to execute capture command");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "Error: capture command exited with status %d", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        log_message(msg);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_message("Error: failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message("Error: failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    log_message("Motion detection system started");

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_message("Error: failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_message("Error: failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion_detector") < 0) {
        log_message("Error: failed to request falling edge events on GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("Monitoring for motion...");

    while (running) {
        struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            log_message("Error: gpiod_line_event_wait failed");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            log_message("Error: gpiod_line_event_read failed");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (timeinfo) {
            strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
        } else {
            snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "%s/%s_%03d.jpg", IMAGE_DIR, timestamp, event.ts.tv_nsec / 1000000);

        log_message("Motion detected at timestamp: ");
        printf("%s\n", timestamp);

        if (capture_image(filename) == 0) {
            log_message("Image captured successfully");
        } else {
            log_message("Error: image capture failed");
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_message("Motion detection system stopped");
    return EXIT_SUCCESS;
}

