#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_RANGE 255
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle %d out of range for pin %d (0-180)\n", angle, pin);
        return -1;
    }
    int pulse_width = (int)(((float)angle / 180.0f) * PWM_RANGE);
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(PAN_SERVO_PIN, 90) != 0 || set_servo_angle(TILT_SERVO_PIN, 90) != 0) {
        fprintf(stderr, "Error: Failed to initialize servos to neutral position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo control started. Press arrow keys to move, 'q' to quit.\n");

    while (running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }

        if (c == 'q') {
            printf("\nExiting...\n");
            break;
        }

        int pan_angle = 90;
        int tilt_angle = 90;

        switch (c) {
            case 'w':
                tilt_angle += STEP_SIZE;
                break;
            case 's':
                tilt_angle -= STEP_SIZE;
                break;
            case 'a':
                pan_angle -= STEP_SIZE;
                break;
            case 'd':
                pan_angle += STEP_SIZE;
                break;
            default:
                printf("Invalid key: %c\n", c);
                break;
        }

        if (pan_angle < 0) pan_angle = 0;
        if (pan_angle > 180) pan_angle = 180;
        if (tilt_angle < 0) tilt_angle = 0;
        if (tilt_angle > 180) tilt_angle = 180;

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
            fprintf(stderr, "Error: Failed to set pan servo angle\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error: Failed to set tilt servo angle\n");
        }

        printf("Pan: %3d, Tilt: %3d\n", pan_angle, tilt_angle);
        usleep(DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

