static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int oled_init(int fd) {
    uint8_t init_cmds[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
        0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12,
        0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6,
        0xAF
    };
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (i2c_write_byte(fd, init_cmds[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

static int oled_clear(int fd) {
    uint8_t clear_cmd = 0x21;
    if (i2c_write_byte(fd, clear_cmd) < 0) return -1;
    if (i2c_write_byte(fd, 0, 0) < 0) return -1;
    if (i2c_write_byte(fd, OLED_WIDTH - 1, 0) < 0) return -1;
    if (i2c_write_byte(fd, clear_cmd) < 0) return -1;
    if (i2c_write_byte(fd, 0, 0) < 0) return -1;
    if (i2c_write_byte(fd, OLED_HEIGHT - 1, 0) < 0) return -1;
    return 0;
}

static int oled_set_cursor(int fd, int col, int row) {
    uint8_t cmd = 0xB0 + (row / 8);
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    uint8_t col_cmd = 0x00 + (col & 0x0F);
    if (i2c_write_byte(fd, col_cmd) < 0) return -1;
    uint8_t col_cmd_high = 0x10 + ((col >> 4) & 0x0F);
    if (i2c_write_byte(fd, col_cmd_high) < 0) return -1;
    return 0;
}

static int oled_print_char(int fd, int col, int row, char c) {
    if (c < 32 || c > 126) return -1;
    uint8_t char_data[8];
    for (int i = 0; i < 8; i++) {
        char_data[i] = font5x7[(c - 32) * 8 + i];
    }
    for (int i = 0; i < 8; i++) {
        if (oled_set_cursor(fd, col, row + i) < 0) return -1;
        for (int j = 0; j < 8; j++) {
            if (i2c_write_byte(fd, char_data[i] & (1 << (7 - j))) < 0) return -1;
        }
    }
    return 0;
}

static int oled_print_string(int fd, int col, int row, const char *str) {
    while (*str) {
        if (oled_print_char(fd, col, row, *str) < 0) return -1;
        col += 6;
        str++;
    }
    return 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    int temp;
