#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

int initialize_i2c() {
    int handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        return -1;
    }
    return handle;
}

void lcd_send_byte(int handle, int bits, int mode) {
    int high_bits = (bits & 0xF0) | mode;
    int low_bits = ((bits << 4) & 0xF0) | mode;
    i2cWriteByte(handle, high_bits);
    i2cWriteByte(handle, low_bits);
}

void lcd_init(int handle) {
    lcd_send_byte(handle, 0x33, LCD_CMD);
    lcd_send_byte(handle, 0x32, LCD_CMD);
    lcd_send_byte(handle, 0x28, LCD_CMD);
    lcd_send_byte(handle, 0x0C, LCD_CMD);
    lcd_send_byte(handle, 0x06, LCD_CMD);
    lcd_send_byte(handle, 0x01, LCD_CMD);
    gpioDelay(2000);
}

void lcd_set_cursor(int handle, int row, int col) {
    int row_offsets[] = {0x00, 0x40};
    lcd_send_byte(handle, row_offsets[row] + col, LCD_CMD);
}

void lcd_print(int handle, const char *message) {
    for (int i = 0; message[i] != '\0'; i++) {
        lcd_send_byte(handle, message[i], LCD_CHR);
    }
}

float read_flow_rate() {
    static uint32_t last_tick = 0;
    static float total_volume = 0.0;
    uint32_t current_tick = gpioTick();
    uint32_t pulse_duration = current_tick - last_tick;
    last_tick = current_tick;
    if (pulse_duration > 0) {
        float flow_rate = 1000000.0 / (float)pulse_duration;
        total_volume += flow_rate * (float)pulse_duration / 1000000.0;
        return flow_rate;
    }
    return 0.0;
}

void display_flow_rate(float flow_rate) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f", flow_rate);
    lcd_set_cursor(I2C_BUS, 0, 0);
    lcd_print(I2C_BUS, buffer);
}

void display_total_volume(float total_volume) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Total Volume: %.2f", total_volume);
    lcd_set_cursor(I2C_BUS, 1, 0);
    lcd_print(I2C_BUS, buffer);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        return 1;
    }

    int i2c_handle = initialize_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    lcd_init(i2c_handle);

    while (program_running) {
        float flow_rate = read_flow_rate();
        display_flow_rate(flow_rate);
        display_total_volume(total_volume);
        gpioDelay(1000000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

