/*
 * Raspberry Pi 4 Model B – Anemometer Pulse Counter with LCD Display
 *
 * Hardware:
 *   - Anemometer pulse output -> GPIO17 (BCM)
 *   - MCP3008 ADC on SPI0/CE0 (mode 0, 1 MHz)
 *   - PCF8574 backpack on I2C bus 1, address 0x70
 *
 * Build:
 *   gcc -O2 -Wall -o anemometer_lcd anemometer_lcd.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./anemometer_lcd
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define ANEMOMETER_GPIO        17
#define SPI_DEVICE             "/dev/spidev0.0"
#define I2C_DEVICE             "/dev/i2c-1"
#define PCF8574_ADDR           0x70
#define LCD_WIDTH              16
#define SAMPLE_WINDOW_MS       500
#define POLL_INTERVAL_US       10000   /* 10 ms between pulses */
#define ADC_MAX_VALUE          1023
#define ADC_STUCK_THRESHOLD    5
#define ADC_READ_RETRIES       3
#define LCD_BACKLIGHT_ON       0x08
#define LCD_BACKLIGHT_OFF      0x00
#define LCD_ENABLE_BIT         0x04
#define LCD_RS_BIT             0x01
#define LCD_RW_BIT             0x02

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_i2c_fd = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  spi_init(void);
static int  i2c_init(void);
static int  lcd_init(void);
static int  lcd_send_byte(uint8_t data, uint8_t mode);
static int  lcd_set_cursor(uint8_t row, uint8_t col);
static int  lcd_clear(void);
static int  lcd_print(const char *text);
static int  read_anemometer_pulse(void);
static int  read_mcp3008(int channel);
static int  calculate_wind_speed(int pulses, int sample_window_ms);
static int  calculate_wind_direction(int adc_value);
static void display_data(int wind_speed, int wind_direction);
static void cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI Initialization ----------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- I2C Initialization ----------------------------- */
static int i2c_init(void)
{
    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n",
                I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                PCF8574_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Initialize backpack: enable display, cursor off, blink off */
    uint8_t init_seq[] = {
        LCD_BACKLIGHT_ON,
        0x00,  /* Display off */
        0x00,  /* Cursor off */
        0x00   /* Blink off */
    };
    if (write(g_i2c_fd, init_seq, sizeof(init_seq)) != (ssize_t)sizeof(init_seq)) {
        fprintf(stderr, "Error initializing PCF8574: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- LCD Initialization ----------------------------- */
static int lcd_init(void)
{
    /* Wait for LCD to power up (max 50 ms) */
    gpioDelay(100000);

    /* Send initialization sequence */
    if (lcd_send_byte(0x33, 0) < 0) return -1;
    gpioDelay(5000);
    if (lcd_send_byte(0x32, 0) < 0) return -1;
    gpioDelay(150);
    if (lcd_send_byte(0x28, 0) < 0) return -1; /* 4-bit, 2 lines, 5x8 font */
    gpioDelay(150);
    if (lcd_send_byte(0x0C, 0) < 0) return -1; /* Display on, cursor off */
    gpioDelay(150);
    if (lcd_send_byte(0x06, 0) < 0) return -1; /* Entry mode: increment, no shift */
    gpioDelay(150);
    if (lcd_clear() < 0) return -1;
    gpioDelay(2000);

    return 0;
}

/* ----------------------------- LCD Send Byte ----------------------------- */
static int lcd_send_byte(uint8_t data, uint8_t mode)
{
    uint8_t buf[2];
    buf[0] = (mode & LCD_RS_BIT) ? 0x80 : 0x00; /* RS = 1 for data, 0 for command */
    buf[1] = data;

    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to LCD: %s\n", strerror(errno));
        return -1;
    }

    /* Enable pulse: 1 us high, then low to reset */
    if (write(g_i2c_fd, &LCD_ENABLE_BIT, 1) != 1) {
        fprintf(stderr, "Error enabling LCD: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1);
    if (write(g_i2c_fd, &LCD_BACKLIGHT_OFF, 1) != 1) {
        fprintf(stderr, "Error disabling LCD: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(50);

    return 0;
}

/* ----------------------------- LCD Set Cursor ----------------------------- */
static int lcd_set_cursor(uint8_t row, uint8_t col)
{
    uint8_t addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else if (row == 1) {
        addr = 0x40 + col;
    } else {
        fprintf(stderr, "Invalid LCD row %u\n", row);
        return -1;
    }
    return lcd_send_byte(addr, 0);
}

/* ----------------------------- LCD Clear ---------------------------------- */
static int lcd_clear(void)
{
    return lcd_send_byte(0x01, 0);
}

/* ----------------------------- LCD Print ---------------------------------- */
static int lcd_print(const char *text)
{
    for (size_t i = 0; text[i] != '\0'; i++) {
        if (lcd_send_byte((uint8_t)text[i], 1) < 0) {
            return -1;
        }
    }
    return 0;
}

/* ----------------------------- Anemometer Pulse Counter --------------------- */
static int read_anemometer_pulse(void)
{
    static int pulse_count = 0;
    static uint32_t last_tick = 0;

    uint32_t now = gpioTick();
    uint32_t elapsed = now - last_tick;

    if (elapsed >= (uint32_t)(SAMPLE_WINDOW_MS * 1000)) {
        pulse_count = 0;
        last_tick = now;
    }

    if (gpioRead(ANEMOMETER_GPIO) == 1) {
        pulse_count++;
        last_tick = now;
    }

    return pulse_count;
}

/* ----------------------------- MCP3008 ADC ---------------------------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   Byte 0: 0x01 (start bit)
     *   Byte 1: (0x08 | channel) << 4 (single-ended + channel select)
     *   Byte 2: 0x00 (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = bits 9..2 in upper nibble, bits 1..0 in lower nibble
     *   rx[2] = bits 7..0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error reading MCP3008 channel %d: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- Wind Speed Calculation ------------------------ */
static int calculate_wind_speed(int pulses, int sample_window_ms)
{
    if (sample_window_ms <= 0) {
        return 0;
    }
    return (int)(((float)pulses / (float)sample_window_ms) * 60.0f);
}

/* ----------------------------- Wind Direction Calculation ---------------------- */
static int calculate_wind_direction(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    /*
     * MCP3008 VREF = 3.3 V, 10-bit ADC.
     * 0 -> 0 V -> 0 degrees
     * 1023 -> 3.3 V -> 360 degrees
     */
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * 3.3f;
    int direction = (int)(voltage * 180.0f / 3.3f);

    if (direction < 0) direction += 360;
    if (direction >= 360) direction -= 360;

    return direction;
}

/* ----------------------------- Display Data --------------------------------- */
static void display_data(int wind_speed, int wind_direction)
{
    char buffer[LCD_WIDTH + 1];
    int len = snprintf(buffer, sizeof(buffer), "WS: %d m/s  Dir: %d deg",
                       wind_speed, wind_direction);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting LCD data\n");
        return;
    }

    /* Clear the display and write the new data */
    if (lcd_clear() < 0) {
        fprintf(stderr, "Error clearing LCD\n");
        return;
    }
    if (lcd_set_cursor(0, 0) < 0) {
        fprintf(stderr, "Error setting LCD cursor\n");
        return;
    }
    if (lcd_print(buffer) < 0) {
        fprintf(stderr, "Error printing to LCD\n");
    }
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Turn off backpack display */
        uint8_t off_seq[] = { LCD_BACKLIGHT_OFF, 0x00, 0x00, 0x00 };
        write(g_i2c_fd, off_seq, sizeof(off_seq));
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure anemometer GPIO */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ANEMOMETER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (i2c_init() < 0) {
        spiClose(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LCD */
    if (lcd_init() < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Anemometer and LCD monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int pulses = read_anemometer_pulse();

        /* Read ADC with retries on transient failures */
        int adc_value = -1;
        for (int attempt = 0; attempt < ADC_READ_RETRIES; attempt++) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
