        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d). "
                            "Check sensor wiring and power.\n", adc_value);
        }

        int wind_speed = calculate_wind_speed(pulses, SAMPLE_WINDOW_MS);
        int wind_direction = calculate_wind_direction(adc_value);

        display_data(wind_speed, wind_direction);

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

