#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define PULSE_PIN 17
#define SAMPLE_INTERVAL_SEC 1
#define PULSES_PER_LITER 6.0
#define SENSOR_TIMEOUT_SEC 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_send_byte(uint8_t value, uint8_t mode) {
    uint8_t high_nibble = (value & 0xF0) | mode | LCD_BACKLIGHT;
    uint8_t low_nibble = ((value << 4) & 0xF0) | mode | LCD_BACKLIGHT;

    if (i2cWriteByteData(i2c_handle, LCD_CMD, high_nibble) < 0) {
        fprintf(stderr, "Error writing high nibble to LCD: %s\n", strerror(errno));
        return;
    }
    if (i2cWriteByteData(i2c_handle, LCD_CMD, low_nibble) < 0) {
        fprintf(stderr, "Error writing low nibble to LCD: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1000);
}

static void lcd_send_string(const char *string) {
    while (*string) {
        lcd_send_byte((uint8_t)*string, LCD_CHR);
        string++;
    }
}

static void lcd_clear(void) {
    lcd_send_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_send_byte(0x33, LCD_CMD);
    gpioDelay(5000);
    lcd_send_byte(0x32, LCD_CMD);
    gpioDelay(150);
    lcd_send_byte(0x28, LCD_CMD);
    gpioDelay(150);
    lcd_send_byte(0x0C, LCD_CMD);
    gpioDelay(150);
    lcd_send_byte(0x06, LCD_CMD);
    gpioDelay(150);
    lcd_clear();
}

static void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    lcd_send_byte(addr, LCD_CMD);
}

static void lcd_display_flow_rate(float flow_rate) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_send_string(buffer);
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        static uint32_t last_tick = 0;
        uint32_t diff = tick - last_tick;
        if (diff > 0) {
            static uint32_t pulse_count = 0;
            pulse_count++;
            last_tick = tick;
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, LCD_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    lcd_init();

    if (gpioSetMode(PULSE_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input: %s\n", PULSE_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetAlertFunc(PULSE_PIN, pulse_callback) < 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d: %s\n", PULSE_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t start_tick = gpioTick();
        uint32_t pulse_count = 0;
        int timeout = 0;

        while (running && (gpioTick() - start_tick) < (SAMPLE_INTERVAL_SEC * 1000000)) {
            if (pulse_count > 0) {
                break;
            }
            gpioDelay(10000);
            timeout++;
            if (timeout > SENSOR_TIMEOUT_SEC * 10) {
                fprintf(stderr, "Warning: No pulses detected for %d seconds. Sensor may be absent or disconnected.\n", SENSOR_TIMEOUT_SEC);
                break;
            }
        }

        if (!running) {
            break;
        }

        if (pulse_count == 0) {
            fprintf(stderr, "Error: No pulses detected within %d seconds. Sensor may be absent or disconnected.\n", SENSOR_TIMEOUT_SEC);
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_send_string("Sensor Error");
            gpioDelay(5000000);
            continue;
        }

        float flow_rate = (float)pulse_count / PULSES_PER_LITER * 60.0f;
        lcd_display_flow_rate(flow_rate);
        printf("Flow Rate: %.2f L/min\n", flow_rate);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

