#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8

#define ROW_PINS  {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS  {5, 6, 12, 13, 19, 16, 26, 20}

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(ROW_PINS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d as output.\n", ROW_PINS[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(ROW_PINS[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialize row pin %d LOW.\n", ROW_PINS[i]);
            gpioTerminate();
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(COL_PINS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set column pin %d as output.\n", COL_PINS[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(COL_PINS[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize column pin %d HIGH.\n", COL_PINS[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(ROW_PINS[i], 0);
        gpioSetMode(ROW_PINS[i], PI_INPUT);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(COL_PINS[i], 1);
        gpioSetMode(COL_PINS[i], PI_INPUT);
    }
    gpioTerminate();
}

static void set_row(int row, int value) {
    if (row < 0 || row >= NUM_ROWS) {
        fprintf(stderr, "Error: invalid row index %d.\n", row);
        return;
    }
    if (gpioWrite(ROW_PINS[row], value) != 0) {
        fprintf(stderr, "Error: failed to write row pin %d.\n", ROW_PINS[row]);
    }
}

static void set_column(int col, int value) {
    if (col < 0 || col >= NUM_COLS) {
        fprintf(stderr, "Error: invalid column index %d.\n", col);
        return;
    }
    if (gpioWrite(COL_PINS[col], value) != 0) {
        fprintf(stderr, "Error: failed to write column pin %d.\n", COL_PINS[col]);
    }
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(i, 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        set_column(i, 1);
    }
}

static void draw_wave_left_to_right(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(i, 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        set_column(i, 1);
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(i, 1);
        set_column(i, 0);
        gpioDelay(800);
    }
}

static void draw_wave_right_to_left(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(i, 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        set_column(i, 1);
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(i, 1);
        set_column(NUM_COLS - 1 - i, 0);
        gpioDelay(800);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("LED matrix animation started. Press Ctrl+C to exit.\n");

    while (running) {
        draw_wave_left_to_right();
        if (!running) break;
        draw_wave_right_to_left();
    }

    clear_matrix();
    cleanup_gpio();
    printf("LED matrix animation stopped.\n");
    return EXIT_SUCCESS;
}

