/*
 * Si1145 Proximity/Ambient Light Logger for Raspberry Pi Zero W
 *
 * Reads proximity and ambient light data from a Si1145 sensor on I2C bus 1
 * every 500 ms, logs it to biometric_log.txt with an ISO-8601 timestamp,
 * and exits cleanly on SIGINT.
 *
 * Build: gcc -O2 -Wall -o si1145_logger si1145_logger.c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x46
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000   /* 500 ms */

/* Si1145 register addresses */
#define REG_PART_ID    0x00
#define REG_REV_ID     0x01
#define REG_SEQ_ID     0x02
#define REG_INT_CFG    0x03
#define REG_IRQ_ENABLE 0x04
#define REG_IRQ_MODE1  0x05
#define REG_IRQ_MODE2  0x06
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_RATE   0x0A
#define REG_PS_RATE    0x0B
#define REG_PS1_DATA0  0x0C
#define REG_PS1_DATA1  0x0D
#define REG_PS2_DATA0  0x0E
#define REG_PS2_DATA1  0x0F
#define REG_PS3_DATA0  0x10
#define REG_PS3_DATA1  0x11
#define REG_ALS_DATA0  0x12
#define REG_ALS_DATA1  0x13
#define REG_ALS_DATA2  0x14
#define REG_ALS_DATA3  0x15
#define REG_PS_LED21   0x17
#define REG_PS_LED3    0x18
#define REG_ALS_VIS_DATA0 0x19
#define REG_ALS_VIS_DATA1 0x1A
#define REG_ALS_IR_DATA0  0x1B
#define REG_ALS_IR_DATA1  0x1C
#define REG_ALS_UV_DATA0  0x1D
#define REG_ALS_UV_DATA1  0x1E
#define REG_ALS_UV_DATA2  0x1F
#define REG_ALS_UV_DATA3  0x20
#define REG_COMMAND     0x30

/* Si1145 command codes */
#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x05
#define CMD_ALS_FORCE   0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: set flag only                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1145 register                             */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1145 register                            */
/* ------------------------------------------------------------------ */
static int si1145_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers      */
/* ------------------------------------------------------------------ */
static int si1145_read_reg16(uint8_t reg_low, uint16_t *value)
{
    uint8_t lo, hi;
    if (si1145_read_reg(reg_low, &lo) < 0)
        return -1;
    if (si1145_read_reg(reg_low + 1, &hi) < 0)
        return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1145 sensor                                       */
/* ------------------------------------------------------------------ */
static int si1145_init(void)
{
    uint8_t part_id = 0;

    /* Verify device identity */
    if (si1145_read_reg(REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x45). "
                        "Sensor not present or wrong device.\n", part_id);
        return -1;
    }

    /* Reset the sensor */
    if (si1145_write_reg(REG_COMMAND, CMD_RESET) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms reset settling time */

    /* Write HW_KEY to enable the device */
    if (si1145_write_reg(REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Configure measurement rates */
    if (si1145_write_reg(REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (si1145_write_reg(REG_MEAS_RATE1, 0x00) < 0)
        return -1;
    if (si1145_write_reg(REG_ALS_RATE, 0x00) < 0)
        return -1;
    if (si1145_write_reg(REG_PS_RATE, 0x00) < 0)
        return -1;

    /* Configure interrupt settings */
    if (si1145_write_reg(REG_INT_CFG, 0x00) < 0)
        return -1;
    if (si1145_write_reg(REG_IRQ_ENABLE, 0x00) < 0)
        return -1;
    if (si1145_write_reg(REG_IRQ_MODE1, 0x00) < 0)
        return -1;
    if (si1145_write_reg(REG_IRQ_MODE2, 0x00) < 0)
        return -1;

    /* Enable PS1, ALS_VIS, ALS_IR, ALS_UV channels */
    if (si1145_write_reg(REG_COMMAND, CMD_PS_FORCE) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms for first measurement */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data and log it to file                                 */
/* ------------------------------------------------------------------ */
static int read_and_log(void)
{
    uint16_t proximity = 0, ambient_light = 0;
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    /* Read proximity and ambient light data */
    if (si1145_read_reg16(REG_PS1_DATA0, &proximity) < 0)
        return -1;
    if (si1145_read_reg16(REG_ALS_VIS_DATA0, &ambient_light) < 0)
        return -1;

    /* Get current timestamp */
    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    /* Write data to log file */
    if (fprintf(g_log_file, "%s,Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush() on log file failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if init() failed                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Best-effort: try to disable interrupts before closing */
        (void)i2cWriteByteData(g_i2c_handle, REG_COMMAND, CMD_RESET);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1145_init() < 0) {
        fprintf(stderr, "[FATAL] Si1145 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Si1145 logger started. Logging to '%s' every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        if (read_and_log() < 0) {
            fprintf(stderr, "[WARN] Logging failed; continuing.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Si1145 logger stopped.\n");
    return EXIT_SUCCESS;
}

