/*
 * E18-D50NK IR proximity sensor reader for Raspberry Pi 5.
 *
 * Wiring:
 *   E18-D50NK VCC  -> 3.3 V (Pin 1)
 *   E18-D50NK GND  -> GND  (Pin 9)
 *   E18-D50NK OUT -> GPIO4 (BCM, Pin 7)
 *   LED anode     -> GPIO17 (BCM, Pin 11) via 330 Ω resistor
 *
 * Behavior:
 *   Polls GPIO4 every 100 ms.  When the line reads LOW (object detected),
 *   detects a falling edge from HIGH to LOW, and writes a timestamped
 *   entry to proximity.log.  Blinks LED17 on detection for 100 ms.
 *   Handles SIGINT / SIGTERM cleanly and releases GPIO resources.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o proximity proximity.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* RP1 on Pi 5 */
#define GPIO_LINE_OFFSET 4            /* BCM 4 */
#define LED_LINE_OFFSET  17           /* BCM 17 */
#define POLL_INTERVAL_US 100000      /* 100 ms */
#define LED_ON_US        100000      /* 100 ms */
#define LOG_FILE         "proximity.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_detection(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* LED blink                                                           */
/* ------------------------------------------------------------------ */
static int blink_led(struct gpiod_line *led_line, int duration_us)
{
    if (gpiod_line_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Failed to set LED on: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_us);

    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_us);

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        /* Fallback: try opening with the library’s default chip name. */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* ---- Get sensor line ---- */
    sensor_line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* ---- Get LED line ---- */
    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                LED_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* ---- Request sensor line as input ---- */
    if (gpiod_line_request_input(sensor_line, "proximity-sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request LED line as output, initial value LOW ---- */
    if (gpiod_line_request_output(led_line, "proximity-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Proximity sensor monitoring started.  Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            fprintf(stderr, "Error reading sensor line: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        /* E18-D50NK OUT is active-LOW: LOW = object detected */
        if (val == 0) {
            printf("Object detected!\n");

            if (log_detection() != 0) {
                fprintf(stderr, "Warning: failed to log detection.\n");
            }

            if (blink_led(led_line, LED_ON_US) != 0) {
                fprintf(stderr, "Warning: failed to blink LED.\n");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines ---- */
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

