#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x46
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_PS_LED21 0x0F
#define SI1145_REG_PS_LED3 0x10
#define SI1145_REG_PS_ADC_GAIN 0x11
#define SI1145_REG_PS_ADC_MISC 0x12
#define SI1145_REG_ALS_VIS_ADC_GAIN 0x13
#define SI1145_REG_ALS_VIS_ADC_MISC 0x14
#define SI1145_REG_ALS_IR_ADC_GAIN 0x15
#define SI1145_REG_ALS_IR_ADC_MISC 0x16
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0 0x24
#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27
#define SI1145_REG_PS2_DATA0 0x28
#define SI1145_REG_PS2_DATA1 0x29
#define SI1145_REG_PS3_DATA0 0x2A
#define SI1145_REG_PS3_DATA1 0x2B
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_RESPONSE 0x20

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY) < 0) {
        return -1;
    }

    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        return -1;
    }

    if (write_reg(SI1145_REG_PS_LED21, 0x0F) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_PS_LED3, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_PS_ADC_GAIN, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_PS_ADC_MISC, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_ALS_VIS_ADC_GAIN, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_ALS_VIS_ADC_MISC, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_ALS_IR_ADC_GAIN, 0x00) < 0) {
        return -1;
    }
    if (write_reg(SI1145_REG_ALS_IR_ADC_MISC, 0x00) < 0) {
        return -1;
    }

    if (write_reg(SI1145_REG_COMMAND, 0x00) < 0) {
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int read_proximity(uint16_t *proximity) {
    uint8_t data[2];
    if (read_reg16(SI1145_REG_PS1_DATA0, data) < 0) {
        return -1;
    }
    *proximity = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static int read_ambient_light(uint16_t *ambient_light) {
    uint8_t data[2];
    if (read_reg16(SI1145_REG_ALS_VIS_DATA0, data) < 0) {
        return -1;
    }
    *ambient_light = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static int log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition...\n");

    while (!terminate) {
        uint16_t proximity, ambient_light;

        if (read_proximity(&proximity) < 0) {
            fprintf(stderr, "Error reading proximity data\n");
        } else if (read_ambient_light(&ambient_light) < 0) {
            fprintf(stderr, "Error reading ambient light data\n");
        } else {
            if (log_data(proximity, ambient_light) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Data acquisition stopped.\n");

    return EXIT_SUCCESS;
}

