#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x52
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C
#define APDS9960_POFFSET 0x9D
#define APDS9960_PROX_THRESH_LOW 0x5D
#define APDS9960_PROX_THRESH_HIGH 0x5E
#define APDS9960_ID_VALUE 0x99
#define PROXIMITY_THRESHOLD 200
#define I2C_BUS 1
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int apds9960_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int apds9960_read_reg(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
    } else {
        *value = (uint8_t)result;
    }
    return result;
}

static int apds9960_init(void) {
    uint8_t id = 0;
    if (apds9960_read_reg(APDS9960_ID, &id) < 0) {
        return -1;
    }
    if (id != APDS9960_ID_VALUE) {
        fprintf(stderr, "Unexpected ID: 0x%02X (expected 0x%02X)\n", id, APDS9960_ID_VALUE);
        return -1;
    }

    if (apds9960_write_reg(APDS9960_ENABLE, 0x00) < 0) return -1;
    if (apds9960_write_reg(APDS9960_ATIME, 0xFF) < 0) return -1;
    if (apds9960_write_reg(APDS9960_WTIME, 0xFF) < 0) return -1;
    if (apds9960_write_reg(APDS9960_PPULSE, 0x01) < 0) return -1;
    if (apds9960_write_reg(APDS9960_CONTROL, 0x03) < 0) return -1;
    if (apds9960_write_reg(APDS9960_PROX_THRESH_LOW, 0x00) < 0) return -1;
    if (apds9960_write_reg(APDS9960_PROX_THRESH_HIGH, 0xFF) < 0) return -1;
    if (apds9960_write_reg(APDS9960_ENABLE, 0x0F) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *proximity) {
    uint8_t status = 0;
    if (apds9960_read_reg(APDS9960_STATUS, &status) < 0) {
        return -1;
    }
    if (!(status & 0x01)) {
        return 0;
    }
    uint8_t lsb = 0, msb = 0;
    if (apds9960_read_reg(APDS9960_PDATA, &lsb) < 0) {
        return -1;
    }
    if (apds9960_read_reg(APDS9960_PDATA + 1, &msb) < 0) {
        return -1;
    }
    *proximity = (uint16_t)((msb << 8) | lsb);
    if (apds9960_write_reg(APDS9960_STATUS, 0x01) < 0) {
        return -1;
    }
    return 1;
}

static int read_color_data(uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t lsb = 0, msb = 0;
