    if (apds9960_read_reg(APDS9960_BDATAL, &lsb) < 0) return -1;
    if (apds9960_read_reg(APDS9960_BDATAH, &msb) < 0) return -1;
    *blue = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static void log_data(uint16_t proximity, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
