static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X) write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X) read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si1182_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1182_REG_HW_KEY, SI1182_HW_KEY_EXPECTED) < 0) {
        return -1;
    }

    /* Measurement rate: 0x00 = 100 ms */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x00) < 0) {
        return -1;
    }
    /* Measurement rate: 0x00 = 100 ms */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0) {
        return -1;
    }

    /* PS LED1: 100 mA, PS LED2: 100 mA */
    if (i2c_write_reg8(fd, SI1182_REG_PS_LED21, 0x0A) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, SI1182_REG_PS_LED3, 0x0A) < 0) {
        return -1;
    }

    /* ADC gain: 1x */
    if (i2c_write_reg8(fd, SI1182_REG_PS_ADC_GAIN, 0x01) < 0) {
        return -1;
    }

    /* ADC misc: enable all 128 channels */
    if (i2c_write_reg8(fd, SI1182_REG_PS_ADC_MISC, 0xFF) < 0) {
        return -1;
    }

    return 0;
}

static int si1182_read_proximity(int fd, uint16_t *proximity) {
    uint8_t buf[2];
    if (i2c_read_reg8(fd, SI1182_REG_PS_ADC_MISC127, &buf[0]) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1182_REG_PS_ADC_MISC128, &buf[1]) < 0) {
        return -1;
    }
    *proximity = ((uint16_t)buf[1] << 8) | buf[0];
    return 0;
}

static double calculate_bpm(uint16_t proximity) {
    /*
     * Simplified linear model:
     *   bpm = 60.0 * (proximity / 65535.0)
     *
     * The sensor outputs 0 when no object is detected, and
     * 65535 when the object is at its maximum distance.
     * We map this to a range of 0 to 200 bpm.
     */
    double bpm = 60.0 * (proximity / 65535.0);
    if (bpm < 0.0) bpm = 0.0;
    if (bpm > 200.0) bpm = 200.0;
    return bpm;
}

