#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x52
#define TRIGGER_CMD    0x01
#define READ_CMD       0x02
#define MEASURE_US     50000   /* 50 ms */
#define SAMPLE_US      200000  /* 200 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the CH101                            */
/* ------------------------------------------------------------------ */
static int ch101_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n",
                cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit distance value from the CH101                          */
/* Returns distance in mm on success, or -1 on error                    */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int handle)
{
    int rc = i2cReadWordData(handle, READ_CMD);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData failed: %d\n", rc);
        return -1;
    }
    /* CH101 returns distance in mm; pigpio returns 16-bit value */
    return rc;
}

/* ------------------------------------------------------------------ */
/* Format current local time as YYYY-MM-DD HH:MM:SS                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Log a distance reading with timestamp to file and stdout            */
/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, const char *timestamp, int distance)
{
    fprintf(fp, "%s, %d\n", timestamp, distance);
    fflush(fp);
    printf("%s, %d\n", timestamp, distance);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("CH101 distance measurement started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Trigger measurement */
        if (ch101_write_cmd(g_i2c_handle, TRIGGER_CMD) != 0) {
            fprintf(stderr, "[WARN] Trigger command failed; skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Wait for measurement to complete */
        gpioDelay(MEASURE_US);

        /* Read distance */
        int distance = ch101_read_distance(g_i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "[WARN] Distance read failed; skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Get timestamp */
        get_timestamp(timestamp, sizeof(timestamp));

        /* Log and print */
        log_distance(g_log_file, timestamp, distance);

        /* Wait before next sample */
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

