/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 Ultrasonic ToF Sensor Monitor
 *
 * Reads distance measurements from an ICU-20201 on I2C bus 1 at 50 ms
 * polling interval, lights an LED on GPIO 17 when distance < threshold,
 * logs each reading with a timestamp to tof_log.txt, and exits cleanly
 * on SIGINT.
 *
 * Build:  gcc -O2 -Wall -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    sudo ./tof_monitor [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ICU-20201 I2C address (7-bit) ---- */
#define ICU20201_ADDR        0x60

/* ---- ICU-20201 register addresses ---- */
#define REG_WHO_AM_I         0x00
#define REG_DISTANCE_MM      0x02
#define REG_THRESHOLD_MM     0x04
#define REG_CONFIG           0x06
#define REG_INT_STATUS       0x08
#define REG_INT_CLEAR        0x0A

/* ---- Expected WHO_AM_I value ---- */
#define ICU20201_WHO_AM_I     0x20201

/* ---- Default threshold (mm) ---- */
#define DEFAULT_THRESHOLD_MM  100

/* ---- GPIO pin for LED (BCM) ---- */
#define LED_GPIO             17

/* ---- I2C bus on Raspberry Pi 4 ---- */
#define I2C_BUS              1

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ICU-20201 register                        */
/* ------------------------------------------------------------------ */
static int icu20201_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);

    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ICU-20201 register                        */
/* ------------------------------------------------------------------ */
static int icu20201_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    int rc = i2cWriteDevice(handle, reg_buf, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }

    rc = i2cReadDevice(handle, data_buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) short read: %d\n",
                reg, rc);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ICU-20201 sensor                                     */
/* ------------------------------------------------------------------ */
static int icu20201_init(int handle)
{
    uint16_t who_am_i = 0;

    /* Verify sensor identity */
    if (icu20201_read_reg16(handle, REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I – sensor absent or bus error.\n");
        return -1;
    }

    if (who_am_i != ICU20201_WHO_AM_I) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%04X, expected 0x%04X.\n",
                who_am_i, ICU20201_WHO_AM_I);
        return -1;
    }

    /* Configure threshold to default value */
    if (icu20201_write_reg16(handle, REG_THRESHOLD_MM, DEFAULT_THRESHOLD_MM) != 0) {
        fprintf(stderr, "[ERROR] Failed to write default threshold.\n");
        return -1;
    }

    /* Clear any pending interrupts */
    if (icu20201_write_reg16(handle, REG_INT_CLEAR, 0x0001) != 0) {
        fprintf(stderr, "[WARN] Failed to clear interrupt status.\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres from the ICU-20201                     */
/* ------------------------------------------------------------------ */
static int icu20201_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t raw = 0;

    if (icu20201_read_reg16(handle, REG_DISTANCE_MM, &raw) != 0) {
        return -1;
    }

    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with a timestamp to a file                             */
/* ------------------------------------------------------------------ */
static void log_reading(uint16_t distance_mm)
{
    FILE *fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        perror("[ERROR] fopen(tof_log.txt)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Distance: %u mm\n", timestamp, distance_mm);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Ensure LED is off */
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold_mm = DEFAULT_THRESHOLD_MM;

    /* Parse command-line threshold (optional) */
    if (argc > 1) {
        threshold_mm = atoi(argv[1]);
        if (threshold_mm <= 0) {
            fprintf(stderr, "[ERROR] Threshold must be a positive integer.\n");
            return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (icu20201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] ICU-20201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ICU-20201 ToF Monitor started.\n");
    printf("  Threshold: %d mm\n", threshold_mm);
    printf("  LED GPIO:   %d\n", LED_GPIO);
    printf("  I2C bus:    %d, addr: 0x%02X\n", I2C_BUS, ICU20201_ADDR);
    printf("  Logging to:  tof_log.txt\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (icu20201_read_distance(g_i2c_handle, &distance_mm) == 0) {
            printf("Distance: %u mm\n", distance_mm);

            if (distance_mm < threshold_mm) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }

            log_reading(distance_mm);
        } else {
            fprintf(stderr, "[WARN] Failed to read distance.\n");
        }

        /* Sleep 50 ms (microseconds) */
        gpioDelay(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

