/*
 * Raspberry Pi Zero W – Omron B5L-LD50-07050 3D TOF Sensor Intrusion Monitor
 *
 * Wiring:
 *   B5L-LD50-07050 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   B5L-LD50-07050 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   B5L-LD50-07050 VDD -> 3.3 V
 *   B5L-LD50-07050 GND -> GND
 *
 * Build: gcc -O2 -Wall -o intrusion_monitor intrusion_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_I2C_ADDR   0x48

/*
 * B5L-LD50-07050 3D TOF command frame (4 bytes, big-endian):
 *   Byte 0: 0x01 (start measurement command)
 *   Byte 1: 0x00 (dummy byte)
 *   Byte 2: 0x00 (dummy byte)
 *   Byte 3: 0x00 (dummy byte)
 */
static const uint8_t B5L_CMD_FRAME[4] = { 0x01, 0x00, 0x00, 0x00 };

/*
 * Expected response:
 *   Byte 0: 0x01 (header byte)
 *   Byte 1: distance MSB (big-endian)
 *   Byte 2: distance LSB
 *   Byte 3: checksum (sum of all bytes except header)
 *   Byte 4: reserved
 *   Byte 5: reserved
 *   Byte 6: reserved
 *   Byte 7: reserved
 *   Byte 8: reserved
 *   Byte 9: reserved
 *   Byte 10: reserved
 *   Byte 11: reserved
 *   Byte 12: reserved
 *   Byte 13: reserved
 *   Byte 14: reserved
 *   Byte 15: reserved
 */
#define B5L_RESP_LEN   15

#define INTRUSION_THRESHOLD_MM  1000
#define SAMPLE_COUNT            10
#define SAMPLE_DELAY_MS         100
#define MEASUREMENT_DELAY_MS    10
#define LOG_FILE_NAME           "intrusion_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
