        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/*
 * Send the 4-byte command frame to the B5L sensor.
 * Returns 0 on success, -1 on failure.
 */
static int send_command(int fd)
{
    ssize_t n = write(fd, B5L_CMD_FRAME, sizeof(B5L_CMD_FRAME));
    if (n != (ssize_t)sizeof(B5L_CMD_FRAME)) {
        fprintf(stderr, "I2C write failed: %s (wrote %zd of %zu bytes)\n",
                strerror(errno), n, sizeof(B5L_CMD_FRAME));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read the 15-byte response from the B5L sensor.
 * Returns 0 on success and stores the distance in *distance_mm,
 * or -1 on failure.
 */
static int read_response(int fd, uint16_t *distance_mm)
{
    uint8_t buf[B5L_RESP_LEN];

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s (read %zd of %zu bytes)\n",
                strerror(errno), n, sizeof(buf));
        return -1;
    }

    /* Verify header byte */
    if (buf[0] != 0x01) {
        fprintf(stderr, "Invalid response header: 0x%02X (expected 0x01)\n",
                buf[0]);
        return -1;
    }

    /* Extract 16-bit distance (big-endian) */
    *distance_mm = ((uint16_t)buf[1] << 8) | buf[2];
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_intrusion(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Distance: %u mm\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
