/*
 * VL53L0X Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Uses the standard Linux I2C-dev interface (no wiringPi).
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO2 (pin 3, I2C bus 1)
 *   VL53L0X SCL -> GPIO3 (pin 5, I2C bus 1)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *
 * Build: gcc -O2 -Wall -o vl53l0x_reader vl53l0x_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- VL53L0X I2C address (7-bit) ---- */
#define VL53L0X_ADDR 0x29

/* ---- VL53L0X register addresses ---- */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID          0x010F
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR          0x0046
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS          0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS              0x0089
#define VL53L0X_REG_RESULT_DISTANCE                  0x0096
#define VL53L0X_REG_SYSTEM_START                     0x0000

/* ---- Expected model ID ---- */
#define VL53L0X_MODEL_ID 0xEA

/* ---- I2C bus device path ---- */
#define I2C_BUS "/dev/i2c-1"

/* ---- Polling timeout for RESULT_INTERRUPT_STATUS ---- */
#define POLL_TIMEOUT_MS 100

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a VL53L0X register                          */
/* ------------------------------------------------------------------ */
static int vl53l0x_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a VL53L0X register                          */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_reg8(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                          */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_reg16(int fd, uint16_t reg, uint16_t *value)
{
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L0X sensor                                     */
/* ------------------------------------------------------------------ */
static int vl53l0x_init(int fd)
{
    uint8_t model_id = 0;

    /* Verify sensor presence by reading the model ID register */
    if (vl53l0x_read_reg8(fd, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X).\n",
                model_id, VL53L0X_MODEL_ID);
        fprintf(stderr, "Sensor not detected or wrong device.\n");
        return -1;
    }

    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);

    /* Clear any pending interrupt so we can start a new measurement */
    if (vl53l0x_write_reg8(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt status.\n");
    }

    /* Start continuous ranging (bit 0 = STREAM_START) */
    if (vl53l0x_write_reg8(fd, VL53L0X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a distance measurement from the VL53L0X                          */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_distance(int fd, uint16_t *distance)
{
    uint8_t status = 0;
    int timeout = 0;

    /* Poll RESULT_INTERRUPT_STATUS for data ready (bit 0 = DATA_READY) */
    do {
        if (vl53l0x_read_reg8(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        usleep(1000); /* 1 ms */
        timeout++;
        if (timeout > POLL_TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for data ready.\n");
            return -1;
        }
    } while (1);

    /* Read the 16-bit distance value */
    if (vl53l0x_read_reg16(fd, VL53L0X_REG_RESULT_DISTANCE, distance) != 0) {
        return -1;
    }

    /* Clear the interrupt so the next measurement can be triggered */
    if (vl53l0x_write_reg8(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt status.\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Format the current timestamp into YYYY-MM-DD HH:MM:SS               */
/* ------------------------------------------------------------------ */
static void format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access at 0x%02X: %s\n",
                VL53L0X_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the VL53L0X sensor */
    if (vl53l0x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L0X initialized. Reading distance every 500 ms...\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;
        char timestamp[32];

        if (vl53l0x_read_distance(g_i2c_fd, &distance) == 0) {
            format_timestamp(timestamp, sizeof(timestamp));
            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        /* Sleep 500 ms, checking g_running every 100 ms for responsive shutdown */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        (void)vl53l0x_write_reg8(g_i2c_fd, VL53L0X_REG_SYSTEM_START, 0x00);
        close(g_i2c_fd);
    }

    return EXIT_SUCCESS;
}

