/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA -> GPIO2 (pin 3)
 *   Si1182 SCL -> GPIO3 (pin 5)
 *   Si1182 VDD -> 3.3 V
 *   Si1182 GND -> GND
 *
 * Build: gcc -O2 -Wall -o si1182_reader si1182_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1182_ADDR    0x46
#define PROX_REG       0x22
#define POLL_DELAY_US  500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

