/*
 * MLX75030 Distance Sensor Reader for Raspberry Pi 4 Model B
 * Uses the Linux i2c-dev character device interface (no wiringPi).
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   MLX75030 SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   MLX75030 VDD -> 3.3 V
 *   MLX75030 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mlx75030_reader mlx75030_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x52          /* Default 7-bit I2C address */

/*
 * MLX75030 register addresses (16-bit, big-endian on the bus).
 * The sensor sends 16-bit addresses, but the 7-bit address is
 * pre-sent in the first byte of the 16-bit read.
 */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_CONFIG       0x02
#define REG_STATUS       0x03

/*
 * Configuration register bits (0x02).
 *   Bit 0: 0 = continuous measurement, 1 = one-shot
 *   Bit 1: 0 = no interrupt, 1 = interrupt on new sample
 *   Bits 2-3: 00 = 16-bit resolution, 01 = 12-bit resolution
 *   Bit 4: 0 = no auto-increment, 1 = auto-increment
 *   Bits 5-6: 00 = no averaging, 01 = average 2 samples
 *   Bit 7: 0 = no interrupt, 1 = interrupt on new sample
 */
#define CONFIG_CONTINUOUS 0x00
#define CONFIG_ONE_SHOT   0x01
#define CONFIG_16BIT      0x00
#define CONFIG_12BIT      0x04
#define CONFIG_AUTO_INC   0x00
#define CONFIG_AVG_2      0x00
#define CONFIG_INT_ON     0x00

/*
 * Status register bits (0x03).
 *   Bit 0: 0 = data not ready, 1 = data ready
 *   Bit 1: 0 = no new sample, 1 = new sample available
 *   Bit 2: 0 = no interrupt, 1 = interrupt pending
 */
#define STATUS_DATA_RDY   0x01
#define STATUS_NEW_SAMPLE 0x02
#define STATUS_INT_PEND   0x04

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian register pair.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t msb_reg, uint16_t *out)
{
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, msb_reg, &msb) < 0)
        return -1;
    if (i2c_read_reg8(fd, msb_reg + 1, &lsb) < 0)
        return -1;
    *out = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/*
 * Initialize the MLX75030 sensor.
 * Returns 0 on success, -1 on error.
 */
static int init_sensor(int fd)
{
    /*
     * Set continuous measurement mode, 16-bit resolution,
     * no averaging, no interrupt.
     */
    uint8_t config = CONFIG_CONTINUOUS | CONFIG_16BIT |
                     CONFIG_AUTO_INC | CONFIG_AVG_2 | CONFIG_INT_ON;
    if (i2c_write_reg8(fd, REG_CONFIG, config) < 0)
        return -1;

    /* Allow the first conversion to complete (typ 10 ms). */
    usleep(10000);

    return 0;
}

/*
 * Read the distance measurement from the sensor.
 * Returns 0 on success and stores the distance in mm in *distance,
 * -1 on error.
 */
static int read_distance(int fd, uint16_t *distance)
{
    uint8_t status;

    /* Poll STATUS register until data is ready (bit 0). */
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg8(fd, REG_STATUS, &status) < 0)
            return -1;
        if (status & STATUS_DATA_RDY)
            break;
        usleep(1000); /* 1 ms */
        if (!g_running)
            return -1;
    }

    if (!(status & STATUS_DATA_RDY)) {
        fprintf(stderr, "Distance measurement not ready after 100 ms\n");
        return -1;
    }

    if (i2c_read_reg16(fd, REG_DISTANCE_MSB, distance) < 0)
        return -1;

    /* Clear the data-ready bit so the next measurement can be triggered. */
    if (i2c_write_reg8(fd, REG_STATUS, STATUS_DATA_RDY) < 0)
        return -1;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MLX75030 slave address. */
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify the device is present by reading the status register. */
    uint8_t status;
    if (i2c_read_reg8(fd, REG_STATUS, &status) < 0) {
        fprintf(stderr, "MLX75030 not responding at address 0x%02X\n",
                MLX75030_ADDR);
        goto cleanup;
    }

    /* Initialize the sensor. */
    if (init_sensor(fd) < 0) {
        fprintf(stderr, "Failed to initialize MLX75030 sensor\n");
        goto cleanup;
    }

    printf("MLX75030 distance sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop: read distance every 500 ms. */
    while (g_running) {
        uint16_t distance;
        if (read_distance(fd, &distance) < 0) {
            if (!g_running)
                break;
            fprintf(stderr, "Error reading distance, retrying...\n");
        } else {
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        }

        /* Sleep 500 ms using nanosleep so signals are caught promptly. */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 500000000L };
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR && g_running) {
            /* Retry if interrupted by a signal. */
        }
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

