/*
 * OPT3101 Time-of-Flight Sensor Reader for Raspberry Pi Zero W
 *
 * Reads distance from channel 0 and ambient light from the OPT3101
 * on I2C bus 1. Logs to the console every 500 ms.
 *
 * Wiring:
 *   OPT3101 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   OPT3101 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   OPT3101 VDD -> 3.3 V
 *   OPT3101 GND -> GND
 *
 * Build: gcc -O2 -Wall -o opt3101_reader opt3101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3101_ADDR   0x48

/* OPT3101 register addresses */
#define REG_STATUS     0x00
#define REG_DISTANCE   0x02
#define REG_LIGHT      0x04
#define REG_ERROR      0x06

/* OPT3101 command codes */
#define CMD_RESET      0x01
#define CMD_START      0x02
#define CMD_STOP       0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an OPT3101 register */
static int opt3101_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
