/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 VCC  -> Pi 3.3V (Pin 1)
 *   HC-SR04 GND  -> Pi GND  (Pin 9)
 *   HC-SR04 TRIG -> Pi GPIO17 (BCM, Pin 11)
 *   HC-SR04 ECHO -> Pi GPIO18 (BCM, Pin 12)
 *
 * NOTE: The HC-SR04 requires a 1 kΩ resistor between the echo pin and GND.
 *       This library provides microsecond precision, so a 1 kΩ resistor
 *       is not required.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000   /* 200 ms max echo wait */
#define LOOP_DELAY_US    1000000 /* 1 second between readings */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres using the HC-SR04 library.
 * Returns distance on success, or -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = 0;
    int level;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: Failed to read echo pin\n");
            return -1.0f;
        }
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo rising edge timeout\n");
            return -1.0f;
        }
    } while (level == 0);
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: Failed to read echo pin\n");
            return -1.0f;
        }
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo falling edge timeout\n");
            return -1.0f;
        }
    } while (level == 1);
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    /* HC-SR04 max range: 2 cm (20 µs / 0.0343 cm/µs) */
    if (pulse_us < 20 || pulse_us > 38000) {
        fprintf(stderr, "Error: Invalid pulse duration %u µs\n", pulse_us);
        return -1.0f;
    }

    return (float)pulse_us * 0.0343f;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Ultrasonic Distance Sensor Reader\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Loop: 1 s\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance >= 0.0f) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("[%s] Distance: %.2f cm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: Distance measurement failed, skipping cycle\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Ensure trigger is low on exit */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

