/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 Ultrasonic Distance Logger
 *
 * Wiring:
 *   I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *   Chirp ICU-20201 SDA -> GPIO2
 *   Chirp ICU-20201 SCL -> GPIO3
 *   Chirp ICU-20201 VDD -> 3.3 V
 *   Chirp ICU-20201 GND -> GND
 *   Alert LED + 330 Ω resistor -> GPIO17 (BCM 17)
 *
 * Build: gcc -O2 -Wall -o distance_logger distance_logger.c -lpigpio -lrt
 * Run:   sudo ./distance_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x22
#define GPIO_ALERT     17
#define DISTANCE_THRESHOLD_CM 10.0f
#define LOG_FILE       "distance_log.txt"
#define POLL_DELAY_US  100000   /* 100 ms */

/* Chirp ICU-20201 register addresses */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_STATUS       0x02
#define REG_CONFIG       0x03
#define REG_MODE         0x04

/* Status bits */
#define STATUS_READY     0x01

/* Configuration bits */
#define CONFIG_AUTO_START 0x01

/* Mode bits */
#define MODE_ACTIVE      0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *value)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    uint8_t status = 0;

    /* Verify sensor presence by reading STATUS register */
    if (i2c_read_reg8(handle, REG_STATUS, &status) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X\n", I2C_ADDR);
        return -1;
    }

    /* Start continuous measurement mode */
    if (i2c_write_reg8(handle, REG_MODE, MODE_ACTIVE) != 0)
        return -1;

    /* Allow first measurement to complete */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (cm)                                                 */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, float *distance_cm)
{
    uint8_t status = 0;
    uint8_t msb = 0, lsb = 0;

    /* Check status to confirm measurement is ready */
    if (i2c_read_reg8(handle, REG_STATUS, &status) != 0)
        return -1;

    if (!(status & STATUS_READY)) {
        fprintf(stderr, "[WARN] Distance measurement not ready (status=0x%02X)\n", status);
        return -1;
    }

    /* Read MSB and LSB */
    if (i2c_read_reg8(handle, REG_DISTANCE_MSB, &msb) != 0)
        return -1;
    if (i2c_read_reg8(handle, REG_DISTANCE_LSB, &lsb) != 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;

    /* Convert raw to cm (example conversion, replace with datasheet formula) */
    *distance_cm = (float)raw / 10.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log distance with timestamp                                          */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f cm\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush log file failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GPIO_ALERT, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure alert pin as output and ensure it starts LOW */
    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_ALERT);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_ALERT, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Distance monitoring started. Threshold: %.1f cm. Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD_CM);

    /* Main polling loop */
    while (g_running) {
        float distance_cm = 0.0f;

        if (read_distance(g_i2c_handle, &distance_cm) == 0) {
            printf("Distance: %.2f cm\n", distance_cm);

            if (log_distance(g_log_file, distance_cm) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing\n");
            }

            if (distance_cm < DISTANCE_THRESHOLD_CM) {
                printf("[ALERT] Distance below threshold (%.1f cm) – activating alert\n",
                       DISTANCE_THRESHOLD_CM);
                gpioWrite(GPIO_ALERT, 1);
            } else {
                gpioWrite(GPIO_ALERT, 0);
            }
        } else {
            fprintf(stderr, "[ERROR] Failed to read distance; retrying in 100 ms\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

