/*
 * Parking Assistance System using VL53L1X Time-of-Flight Sensor
 * Board: Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: STMicroelectronics VL53L1X (I2C address 0x29)
 *
 * Build: gcc -O2 -Wall -o parking_assistance parking_assistance.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- VL53L1X I2C address ---- */
#define VL53L1X_ADDR 0x29

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_SYSTEM_START     0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

/* ---- Application constants ---- */
#define I2C_BUS          1
#define LOG_FILE         "distance_log.csv"
#define POLL_DELAY_US    100000   /* 100 ms */
#define DISTANCE_THRESHOLD_STOP  300
#define DISTANCE_THRESHOLD_APPROACH 300
#define DISTANCE_THRESHOLD_SLOW  600
#define DISTANCE_THRESHOLD_CLEAR  1200

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- Function prototypes ---- */
static int  vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (big-endian on the VL53L1X)               */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian on the VL53L1X)               */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor                                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Start ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the distance from the VL53L1X sensor                         */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;

    /* Poll for data ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "[ERROR] VL53L1X data-ready timeout\n");
        return -1;
    }

    /* Read distance (16-bit big-endian) */
    uint8_t dist_buf[2];
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt by writing 0x01 to SYSTEM_START */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed on bus %d addr 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (create if missing) */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Parking Assistance System started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            fprintf(g_log_file, "%s,%u\n", timestamp, distance);
            fflush(g_log_file);

            printf("[%s] Distance: %u mm\n", timestamp, distance);

            if (distance < DISTANCE_THRESHOLD_STOP) {
                printf("STOP: Parking is too close!\n");
            } else if (distance < DISTANCE_THRESHOLD_APPROACH) {
                printf("APPROACH: Parking is close!\n");
            } else if (distance < DISTANCE_THRESHOLD_SLOW) {
                printf("SLOW: Parking is slow!\n");
            } else {
                printf("CLEAR: Parking is clear!\n");
