/*
 * Raspberry Pi 4 Model B – CH201 Ultrasonic Distance Sensor Reader
 *
 * Reads distance from a TDK InvenSense CH201 ultrasonic Time-of-Flight sensor
 * on I2C bus 1 (GPIO2/3), logs timestamped distances and LED blink
 * frequencies to stdout, and drives an LED on GPIO18 (BCM) through a
 * 330 Ω current-limiting resistor to 3.3 V so that the LED blinks
 * faster as the distance decreases.
 *
 * Build:  gcc -O2 -Wall -o ch201_reader ch201_reader.c -lgpiod
 * Run:    sudo ./ch201_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- CH201 I2C ---- */
#define I2C_BUS        "/dev/i2c-1"
#define CH201_ADDR     0x62          /* CH201 default I2C address */

/* CH201 register addresses */
#define REG_DISTANCE   0x00          /* Distance (mm) */
#define REG_LED_FREQ   0x01          /* LED frequency (Hz) */
#define REG_MODE       0x02          /* Operating mode */
#define REG_CONFIG     0x03          /* Configuration */

/* CH201 operating modes */
#define MODE_STOP      0x00
#define MODE_CONTINUOUS 0x01

/* CH201 configuration bits */
#define CONFIG_LED_ON  0x01          /* LED on when distance > 0 */

/* ---- LED ---- */
#define LED_PIN        18            /* BCM GPIO18 */
#define LED_CONSUMER   "ch201-led"

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000      /* 100 ms */
#define BLINK_HALF_US    50000       /* 50 ms half-cycle */
#define MAX_RETRIES      3
#define RETRY_DELAY_US   10000       /* 10 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_led_line = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a CH201 register with retry.                 */
static int ch201_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;

        fprintf(stderr, "[WARN] I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_US);
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a CH201 register with retry.                */
static int ch201_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "[WARN] I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_US);
            continue;
        }

        if (read(fd, value, 1) == 1)
            return 0;

        fprintf(stderr, "[WARN] I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_US);
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Read distance from CH201. Returns 0 on success, -1 on failure.     */
static int ch201_read_distance(int fd, uint16_t *distance)
{
    uint8_t value;

    if (ch201_read_reg(fd, REG_DISTANCE, &value) != 0)
        return -1;

    *distance = (uint16_t)((value << 8) | value);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Set LED frequency (Hz). Returns 0 on success, -1 on failure.        */
static int ch201_set_led_freq(int fd, uint16_t freq)
{
    if (freq == 0)
        return ch201_write_reg(fd, REG_LED_FREQ, 0x00);

    /* CH201 LED frequency is 1/freq Hz; 0x00 = 0 Hz, 0x01 = 1 Hz, ... */
    uint8_t val = (uint8_t)(freq - 1);
    return ch201_write_reg(fd, REG_LED_FREQ, val);
}

/* ------------------------------------------------------------------ */
/* Initialize the CH201 sensor. Returns 0 on success, -1 on failure.    */
static int ch201_init(int fd)
{
    /* Stop mode first to allow configuration changes */
    if (ch201_write_reg(fd, REG_MODE, MODE_STOP) != 0)
        return -1;

    /* Configure LED: on when distance > 0 */
    if (ch201_write_reg(fd, REG_CONFIG, CONFIG_LED_ON) != 0)
        return -1;

    /* Start continuous measurement mode */
    if (ch201_write_reg(fd, REG_MODE, MODE_CONTINUOUS) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);   /* LED off */
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH201_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                CH201_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (ch201_init(g_i2c_fd) != 0) {
        fprintf(stderr, "[ERROR] CH201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");   /* BCM GPIO on Pi 4 */
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name("gpiochip0");   /* BCM on Pi 3/5 */
    }
    if (!g_chip) {
        fprintf(stderr, "[ERROR] Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led_line = gpiod_chip_get_line(g_chip, LED_PIN);
    if (!g_led_line) {
        fprintf(stderr, "[ERROR] Cannot get GPIO line %d: %s\n",
                LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led_line, LED_CONSUMER, 0) < 0) {
        fprintf(stderr, "[ERROR] Cannot request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH201 distance sensor reader started. Press Ctrl+C to exit.\n");
    printf("I2C bus: %s, address: 0x%02X, LED pin: BCM %d\n",
           I2C_BUS, CH201_ADDR, LED_PIN);
    printf("Logging every 100 ms. Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t distance;

        if (ch201_read_distance(g_i2c_fd, &distance) != 0) {
            fprintf(stderr, "[ERROR] Failed to read distance after %d retries.\n",
                    MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* LED frequency = 1 / distance (Hz) */
        uint16_t freq = (distance > 0) ? (uint16_t)(1000000 / distance) : 0;

        if (ch201_set_led_freq(g_i2c_fd, freq) != 0) {
            fprintf(stderr, "[WARN] Failed to set LED frequency.\n");
        }

        /* Blink LED half-cycle */
        if (gpiod_line_set_value(g_led_line, 1) < 0) {
            fprintf(stderr, "[WARN] Failed to set LED high: %s\n", strerror(errno));
        }
        usleep(BLINK_HALF_US);

        if (gpiod_line_set_value(g_led_line, 0) < 0) {
            fprintf(stderr, "[WARN] Failed to set LED low: %s\n", strerror(errno));
        }
        usleep(BLINK_HALF_US);

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] Distance: %u mm, LED Freq: %u Hz\n", ts, distance, freq);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

