    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);   /* LED off */
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH201_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                CH201_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (ch201_init(g_i2c_fd) != 0) {
        fprintf(stderr, "[ERROR] CH201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");   /* BCM GPIO on Pi 4 */
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name("gpiochip0");   /* BCM on Pi 3/5 */
    }
    if (!g_chip) {
        fprintf(stderr, "[ERROR] Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led_line = gpiod_chip_get_line(g_chip, LED_PIN);
    if (!g_led_line) {
        fprintf(stderr, "[ERROR] Cannot get GPIO line %d: %s\n",
                LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led_line, LED_CONSUMER, 0) < 0) {
        fprintf(stderr, "[ERROR] Cannot request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH201 distance sensor reader started. Press Ctrl+C to exit.\n");
    printf("I2C bus: %s, address: 0x%02X, LED pin: BCM %d\n",
           I2C_BUS, CH201_ADDR, LED_PIN);
    printf("Logging every 100 ms. Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t distance;

        if (ch201_read_distance(g_i2c_fd, &distance) != 0) {
            fprintf(stderr, "[ERROR] Failed to read distance after %d retries.\n",
                    MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* LED frequency = 1 / distance (Hz) */
        uint16_t freq = (distance > 0) ? (uint16_t)(1000000 / distance) : 0;

        if (ch201_set_led_freq(g_i2c_fd, freq) != 0) {
            fprintf(stderr, "[WARN] Failed to set LED frequency.\n");
        }

        /* Blink LED half-cycle */
        if (gpiod_line_set_value(g_led_line, 1) < 0) {
            fprintf(stderr, "[WARN] Failed to set LED high: %s\n", strerror(errno));
        }
        usleep(BLINK_HALF_US);

        if (gpiod_line_set_value(g_led_line, 0) < 0) {
            fprintf(stderr, "[WARN] Failed to set LED low: %s\n", strerror(errno));
        }
        usleep(BLINK_HALF_US);

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] Distance: %u mm, LED Freq: %u Hz\n", ts, distance, freq);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

