#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x5A
#define TRIGGER_CMD 0x01
#define READ_DELAY_US 100000
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define LOG_FILE "distance_log.csv"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MLX75030_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int trigger_measurement(void) {
    char cmd = TRIGGER_CMD;
    int result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: expected 2 bytes, got %d: %s\n",
                result, result < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_data(uint16_t distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (trigger_measurement() == 0) {
                gpioDelay(READ_DELAY_US);
                if (read_distance(&distance) == 0) {
                    success = 1;
                    break;
                }
            }
            fprintf(stderr, "Attempt %d/%d failed, retrying...\n", attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }

        if (success) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Failed to log data\n");
            } else {
                printf("Distance: %u cm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

