/*
 * TCRT5000 IR Obstacle Avoidance Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11, BCM)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13, BCM)
 *   VCC         -> 3.3 V (pin 1)
 *   GND         -> GND  (pin 9)
 *
 * The TCRT5000 module outputs HIGH when an obstacle is detected, LOW when clear.
 * This program polls the sensors every 10 ms, applies a 50 ms debounce, and
 * logs state transitions to proximity_log.txt with an ISO 8601 UTC timestamp.
 *
 * Build: gcc -O2 -Wall -Wextra -o proximity_logger proximity_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE_NAME "proximity_log.txt"
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define DEBOUNCE_US     50000    /* 50 ms */
#define MAX_RETRIES     3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call blocking syscalls.    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Release all resources in reverse order of acquisition.             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
        sensor1_line = NULL;
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
        sensor2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Initialize GPIO lines using libgpiod.                                */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR_1_GPIO);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                SENSOR_1_GPIO, strerror(errno));
        return -1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR_2_GPIO);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                SENSOR_2_GPIO, strerror(errno));
        return -1;
    }

    /* Request both lines as inputs with pull-up disabled (TCRT5000 drives
       the line HIGH when clear, LOW when obstacle). */
    if (gpiod_line_request_input(sensor1_line, "tcrt5000-sensor1") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                SENSOR_1_GPIO, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(sensor2_line, "tcrt5000-sensor2") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                SENSOR_2_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor value with retries.                                   */
/* Returns 0 (HIGH) or 1 (LOW) on success, -1 on failure.            */
/* ------------------------------------------------------------------ */
static int read_sensor(struct gpiod_line *line, int sensor_id)
{
    int value;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d (sensor %d): %s\n",
                    line->offset, sensor_id, strerror(errno));
            retries++;
            usleep(10000); /* 10 ms backoff before retry */
            continue;
        }
        return value;
    }

    fprintf(stderr, "Failed to read GPIO %d (sensor %d) after %d retries\n",
            line->offset, sensor_id, MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a state transition with an ISO 8601 UTC timestamp.             */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_event(int sensor_id, const char *event_type)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id,
                event_type) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev_state1 = 1;   /* assume no obstacle at startup */
    int prev_state2 = 1;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor logger started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int state1 = read_sensor(sensor1_line, 1);
        int state2 = read_sensor(sensor2_line, 2);

        if (state1 < 0 || state2 < 0) {
            /* Sensor read error — log and continue */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Debounce: ignore transitions within DEBOUNCE_US of the last one */
        if (state1 == 0 && prev_state1 == 1) {
            usleep(DEBOUNCE_US);
            state1 = read_sensor(sensor1_line, 1);
            if (state1 < 0) {
                usleep(POLL_INTERVAL_US);
                continue;
            }
            if (state1 == 0) {
                if (log_event(1, "DETECTED") < 0) {
                    fprintf(stderr, "Failed to log event for sensor 1\n");
                }
            }
        }
        if (state2 == 0 && prev_state2 == 1) {
            usleep(DEBOUNCE_US);
            state2 = read_sensor(sensor2_line, 2);
            if (state2 < 0) {
                usleep(POLL_INTERVAL_US);
                continue;
            }
            if (state2 == 0) {
                if (log_event(2, "DETECTED") < 0) {
                    fprintf(stderr, "Failed to log event for sensor 2\n");
                }
            }
        }

        if (state1 == 1 && prev_state1 == 0) {
            if (log_event(1, "CLEARED") < 0) {
                fprintf(stderr, "Failed to log event for sensor 1\n");
            }
        }
        if (state2 == 1 && prev_state2 == 0) {
            if (log_event(2, "CLEARED") < 0) {
                fprintf(stderr, "Failed to log event for sensor 2\n");
            }
        }

        prev_state1 = state1;
        prev_state2 = state2;

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

