/*
 * Raspberry Pi 5 – TDK CH-101 Time-of-Flight Distance Sensor Logger
 *
 * Wiring:
 *   CH-101 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   CH-101 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   CH-101 VDD  -> 3.3 V
 *   CH-101 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ch101_logger ch101_logger.c
 *
 * Run:
 *   ./ch101_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- CH-101 register map ---- */
#define CH101_I2C_ADDR        0x48
#define CH101_REG_MEAS_STATUS  0x00
#define CH101_REG_DISTANCE     0x01

/* ---- Timing constants (microseconds) ---- */
#define MEAS_TIMEOUT_US       50000   /* 50 ms */
#define SAMPLE_INTERVAL_US    500000  /* 500 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call blocking syscalls.    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a CH-101 register.                            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int ch101_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a CH-101 register.                           */
/* Returns 0 on success and stores the value in *out, -1 on error.     */
/* ------------------------------------------------------------------ */
static int ch101_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the distance measurement from the CH-101.                       */
/* Returns 0 on success and stores the distance in mm in *distance_mm. */
/* Returns -1 on timeout or error.                                    */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};
    int elapsed = 0;

    /* Poll MEAS_STATUS until data is ready or timeout */
    while (elapsed < MEAS_TIMEOUT_US) {
        if (ch101_read_reg(fd, CH101_REG_MEAS_STATUS, &status) != 0)
            return -1;

        if (status & 0x01)
            break;

        usleep(100);
        elapsed += 100;
    }

    if (elapsed >= MEAS_TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for CH-101 data ready\n");
        return -1;
    }

    /* Read 16-bit distance value (big-endian) */
    if (ch101_read_reg(fd, CH101_REG_DISTANCE, data) != 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped distance reading to the CSV file.                 */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the CH-101 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the CSV log file in append mode */
    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open distance_log.csv: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("CH-101 distance logger started. Logging to distance_log.csv\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_read_distance(g_i2c_fd, &distance_mm) == 0) {
            if (log_distance(g_log_file, distance_mm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Distance: %u mm\n", distance_mm);
            }
        } else {
            fprintf(stderr, "Distance read failed; skipping sample.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

