/*
 * MLX75030 Time-of-Flight Distance Sensor Reader for Raspberry Pi Zero W
 *
 * Reads distance measurements from a Melexis MLX75030 sensor on I2C bus 1.
 * Sampling interval: 100 ms.
 *
 * Build: gcc -O2 -Wall -o mlx75030_reader mlx75030_reader.c -lm
 * Run:   sudo ./mlx75030_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x52          /* MLX75030 default I2C address */
#define SAMPLE_US      100000        /* 100 ms sampling interval */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000         /* 10 ms between retries */

/* ---- MLX75030 Register Addresses ---- */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_CONFIG       0x02
#define REG_STATUS       0x03

/* ---- Global State ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal Handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C Helpers ---- */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadDevice(handle, (char *)value, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %s\n",
                reg, len, strerror(errno));
    }
    return rc;
}

/* ---- Sensor Initialization ---- */
static int init_sensor(int handle)
{
    /*
     * Configuration register (0x02):
     *   Bit 7: 0  -> Continuous measurement mode
     *   Bit 6: 0  -> No averaging
     *   Bit 5: 0  -> No interrupt
     *   Bit 4: 0  -> No interrupt
     *   Bit 3: 0  -> No interrupt
     *   Bit 2: 0  -> No interrupt
     *   Bit 1: 0  -> No interrupt
     *   Bit 0: 0  -> No interrupt
     * Value: 0x00
     */
    if (i2c_write_reg(handle, REG_CONFIG, 0x00) < 0) {
        return -1;
    }

    /*
     * Status register (0x03):
     *   Bit 7: 0  -> No measurement in progress
     *   Bit 6: 0  -> No new data available
     *   Bit 5: 0  -> No new data available
     *   Bit 4: 0  -> No new data available
     *   Bit 3: 0  -> No new data available
     *   Bit 2: 0  -> No new data available
     *   Bit 1: 0  -> No new data available
     *   Bit 0: 0  -> No new data available
     * Value: 0x00
     */
    if (i2c_write_reg(handle, REG_STATUS, 0x00) < 0) {
        return -1;
    }

    return 0;
}

/* ---- Read Distance (Retry Logic) ---- */
static int read_distance(int handle, uint16_t *distance)
{
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_block(handle, REG_DISTANCE_MSB, buf, 2) == 2) {
            *distance = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }

    return -1;
}

