int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    printf("MLX75030 Distance Sensor Reader\n");
    printf("Sampling every %d ms. Press Ctrl+C to exit.\n\n", SAMPLE_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            /* Calculate millisecond timestamp */
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long ms = (ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);

            printf("[%ld ms] Distance: %u mm\n", ms, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "[ERROR] Failed to read distance after %d retries.\n",
                    MAX_RETRIES);
        }

        gpioDelay(SAMPLE_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

