/*
 * VL53L4CX Time-of-Flight Distance Sensor Reader for Raspberry Pi Zero W
 * Uses the VL53L4CX driver library (libvlc_i2c) for I2C communication.
 *
 * Wiring:
 *   VL53L4CX SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L4CX SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L4CX VDD -> 3.3V
 *   VL53L4CX GND -> GND
 *
 * Build: gcc -O2 -Wall -o vl53l4cx_reader vl53l4cx_reader.c -lvlc_i2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <vlc_i2c.h>

/* VL53L4CX I2C address (7-bit) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses */
#define VL53L4CX_REG_SOFT_RESET              0x0000
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CONFIG 0x0001
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR  0x0002
#define VL53L4CX_REG_RESULT_INTERRUPT_STATUS 0x0004
#define VL53L4CX_REG_RESULT_RANGE_STATUS     0x0006
#define VL53L4CX_REG_RESULT_DISTANCE         0x0008

/* Expected soft reset value */
#define VL53L4CX_SOFT_RESET_VALUE 0x00

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS "/dev/i2c-1"

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 500000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for SIGINT and SIGTERM */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to a 16-bit register address using the driver API.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l4cx_write_reg16(vlc_i2c_t *i2c, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (vlc_i2c_write_block(i2c, buf, 4) != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from a 16-bit register address using the driver API.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l4cx_read_reg16(vlc_i2c_t *i2c, uint16_t reg, uint16_t *value) {
    uint8_t reg_buf[2];
    uint8_t data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (vlc_i2c_write_block(i2c, reg_buf, 2) != 0) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (vlc_i2c_read_block(i2c, data_buf, 2) != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)data_buf[0] << 8) | data_buf[1];
    return 0;
}

/*
 * Initialize the VL53L4CX sensor.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l4cx_init(vlc_i2c_t *i2c) {
    uint16_t soft_reset_value;

    /* Soft reset */
    if (vl53l4cx_write_reg16(i2c, VL53L4CX_REG_SOFT_RESET, VL53L4CX_SOFT_RESET_VALUE) != 0) {
        return -1;
    }
    usleep(10000); /* 10 ms wait for reset to complete */

    /* Clear any pending interrupts */
    if (vl53l4cx_write_reg16(i2c, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    /* Configure interrupt to clear on any new measurement */
    if (vl53l4cx_write_reg16(i2c, VL53L4CX_REG_SYSTEM_INTERRUPT_CONFIG, 0x01) != 0) {
        return -1;
    }

    /* Read back the soft reset value to verify the sensor is responding */
    if (vl53l4cx_read_reg16(i2c, VL53L4CX_REG_SOFT_RESET, &soft_reset_value) != 0) {
        return -1;
    }

    if (soft_reset_value != VL53L4CX_SOFT_RESET_VALUE) {
        fprintf(stderr, "Error: Soft reset value mismatch (expected 0x%02X, got 0x%02X)\n",
                VL53L4CX_SOFT_RESET_VALUE, soft_reset_value);
        return -1;
    }

    printf("VL53L4CX sensor initialized successfully.\n");
    return 0;
}

/*
 * Read distance data from the VL53L4CX sensor.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l4cx_read_distance(vlc_i2c_t *i2c, uint16_t *distance) {
    uint16_t interrupt_status;
    uint16_t range_status;

    /* Poll interrupt status to check for new data */
    if (vl53l4cx_read_reg16(i2c, VL53L4CX_REG_RESULT_INTERRUPT_STATUS, &interrupt_status) != 0) {
        return -1;
    }

    if ((interrupt_status & 0x01) == 0) {
        /* No new data available yet */
        return 1;
    }

    /* Read the range status to confirm the measurement is valid */
    if (vl53l4cx_read_reg16(i2c, VL53L4CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        return -1;
    }

    if ((range_status & 0x01) == 0) {
        /* Measurement not valid */
        return 1;
    }

    /* Read the distance value */
    if (vl53l4cx_read_reg16(i2c, VL53L4CX_REG_RESULT_DISTANCE, distance) != 0) {
        return -1;
    }

    /* Clear the interrupt to allow the next measurement */
    if (vl53l4cx_write_reg16(i2c, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return 0;
}

/*
 * Format the current timestamp as "YYYY-MM-DD HH:MM:SS.uuuuuu".
 * Returns 0 on success, -1 on failure.
 */
static int format_timestamp(char *timestamp, size_t timestamp_size) {
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time\n");
        return -1;
    }

    if (strftime(timestamp, timestamp_size, "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    size_t len = strlen(timestamp);
    if (len + 10 > timestamp_size) {
        fprintf(stderr, "Timestamp buffer too small\n");
        return -1;
    }

    snprintf(timestamp + len, timestamp_size - len, ".%06ld", ts.tv_nsec / 1000);

    return 0;
}

int main(void) {
    vlc_i2c_t *i2c = NULL;
    char timestamp[40];
    uint16_t distance;
    int ret;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    i2c = vlc_i2c_open(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c == NULL) {
        fprintf(stderr, "Error opening I2C bus %s at address 0x%02X: %s\n",
                I2C_BUS, VL53L4CX_ADDR, strerror(errno));
        return 1;
    }

    /* Initialize the sensor */
    if (vl53l4cx_init(i2c) != 0) {
        fprintf(stderr, "Error initializing VL53L4CX sensor.\n");
        vlc_i2c_close(i2c);
        return 1;
    }

    printf("VL53L4CX distance sensor reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        ret = vl53l4cx_read_distance(i2c, &distance);

        if (ret == 0) {
            if (format_timestamp(timestamp, sizeof(timestamp)) == 0) {
                printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error formatting timestamp.\n");
            }
        } else if (ret == 1) {
            /* No new data available yet */
        } else {
            fprintf(stderr, "Error reading distance data.\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up resources */
    printf("\nShutting down...\n");
    vlc_i2c_close(i2c);

    return 0;
}

