/*
 * Returns distance in cm on success, or -1.0f on timeout / error.
 * Uses pigpio's gpioDelay() for precise timing.
 */
static int read_distance_cm(float *distance_out)
{
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;
    int      level;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low during read.\n");
        return -1.0f;
    }
    gpioDelay(2);  /* 2 µs settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object) */
    timeout_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read ECHO_PIN.\n");
            return -1.0f;
        }
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0f;  /* timeout waiting for echo rising edge */
        }
    } while (level == 0);
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if object too far) */
    timeout_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read ECHO_PIN.\n");
            return -1.0f;
        }
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0f;  /* timeout waiting for echo falling edge */
        }
    } while (level == 1);
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;  /* out of range — sensor error */
