            }
        } else {
            fprintf(stderr, "Warning: failed to read distance.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000);  /* 10 ms */
        }
    }

    /* Ensure servo is stopped before releasing pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nParking Assist System stopped.\n");
