    addr_buf[1] = reg & 0xFF;
    if (write(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) burst failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(handle, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%04X failed: %s\n", reg, strerror(errno));
