#define VL53L1X_REG_SYSTEM_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static mqd_t mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (write(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(handle, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_burst(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    uint8_t addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (write(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) burst failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(handle, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

