/*
 * Parking sensor using HC-SR04 ultrasonic sensor on Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO27 (BCM)
 *   Buzzer      -> GPIO22 (BCM)
 *
 * Build: gcc -O2 -Wall -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:   sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* 343 m/s / 1e6 us = 0.0343 cm/us */
#define MIN_DISTANCE_CM   2.0f
#define MAX_DISTANCE_CM   400.0f
#define BUZZER_THRESHOLD_CM 30.0f
#define ECHO_TIMEOUT_US   300000     /* 300 ms max echo wait */
#define LOOP_DELAY_US     100000     /* 100 ms between measurements */
#define TRIGGER_PULSE_US  10

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile bool     g_echo_received = false;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo interrupt callback — fires on every edge of the echo pin       */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_received = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_echo_received = true;
    }
}

/* ------------------------------------------------------------------ */
/* Measure distance in centimeters. Returns true on success, false on   */
/* timeout or invalid reading.                                        */
/* ------------------------------------------------------------------ */
static bool measure_distance(float *distance_cm)
{
    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin LOW\n");
        return false;
    }
    gpioDelay(2);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin HIGH\n");
        return false;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin LOW\n");
        return false;
    }

    /* Wait for echo to arrive or timeout */
    uint32_t start_wait = gpioTick();
    while (!g_echo_received) {
        if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo timeout (no echo received)\n");
            return false;
        }
        gpioDelay(10);
    }

    /* Compute pulse width in microseconds */
    uint32_t pulse_width = g_end_tick - g_start_tick;

    /* Distance = (pulse_width * speed_of_sound) / 2 */
    *distance_cm = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    /* Sanity range check */
    if (*distance_cm < MIN_DISTANCE_CM || *distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                *distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Activate buzzer for BUZZER_DURATION_US microseconds                */
/* ------------------------------------------------------------------ */
static void activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin HIGH\n");
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin LOW\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — turn off buzzer and release pigpio resources            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize buzzer pin LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo interrupt callback */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to register alert function on ECHO_PIN %d\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.0f cm | Buzzer duration: %d us\n",
           BUZZER_THRESHOLD_CM, BUZZER_DURATION_US);

    /* Main measurement loop */
    while (g_running) {
        float distance;

        if (measure_distance(&distance)) {
            printf("Distance: %.2f cm\n", distance);

            if (distance < BUZZER_THRESHOLD_CM) {
                activate_buzzer();
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error: measurement failed, skipping buzzer update\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Parking sensor stopped.\n");
    return EXIT_SUCCESS;
}

