            fprintf(stderr, "Error: echo timeout (no echo received)\n");
            return false;
        }
        gpioDelay(10);
    }

    /* Compute pulse width in microseconds */
    uint32_t pulse_width = g_end_tick - g_start_tick;

    /* Distance = (pulse_width * speed_of_sound) / 2 */
    *distance_cm = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    /* Sanity range check */
    if (*distance_cm < MIN_DISTANCE_CM || *distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                *distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Activate buzzer for BUZZER_DURATION_US microseconds                */
/* ------------------------------------------------------------------ */
static void activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin HIGH\n");
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin LOW\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — turn off buzzer and release pigpio resources            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize buzzer pin LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo interrupt callback */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to register alert function on ECHO_PIN %d\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.0f cm | Buzzer duration: %d us\n",
           BUZZER_THRESHOLD_CM, BUZZER_DURATION_US);

    /* Main measurement loop */
    while (g_running) {
        float distance;

        if (measure_distance(&distance)) {
            printf("Distance: %.2f cm\n", distance);

            if (distance < BUZZER_THRESHOLD_CM) {
                activate_buzzer();
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error: measurement failed, skipping buzzer update\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Parking sensor stopped.\n");
    return EXIT_SUCCESS;
}

