/*
 * HC-SR04 Ultrasonic Distance Measurement with Raspberry Pi 4 Model B
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 23 (physical pin 16, BCM, output)
 *   HC-SR04 ECHO -> GPIO 24 (physical pin 18, BCM, input, pull-down)
 *   ECHO line is 5 V; must be level-shifted or divided for Pi 3.3 V tolerance.
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 200000   /* 200 ms -> 5 Hz sampling */
#define ECHO_TIMEOUT_US  30000    /* 30 ms max echo wait */
#define ECHO_MIN_US      100      /* 100 µs min valid pulse */
#define ECHO_MAX_US      30000    /* 30 ms max valid pulse */
#define TRIGGER_WARN_US  60000    /* 60 ms warn if no echo within 60 ms */

#define LOG_FILE_NAME    "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_trig_line = NULL;
static struct gpiod_line *g_echo_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_trig_line) {
        gpiod_line_set_value(g_trig_line, 0);
        gpiod_line_release(g_trig_line);
        g_trig_line = NULL;
    }
    if (g_echo_line) {
        gpiod_line_release(g_echo_line);
        g_echo_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* ISO-8601 timestamp helper                                         */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in the driver thread)                    */
/* ------------------------------------------------------------------ */
static void echo_callback(struct gpiod_line *line,
                         unsigned int offset,
                         enum gpiod_line_event event,
                         void *userdata)
{
    (void)offset;
    (void)userdata;

    static uint32_t last_tick = 0;
    static uint32_t pulse_start = 0;
    static bool     pulse_seen = false;

    uint32_t now = gpiod_line_get_value_tick(line);

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        pulse_start = now;
        pulse_seen = false;
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        uint32_t duration = now - pulse_start;   /* handles 32-bit wraparound */

        if (duration >= ECHO_MIN_US && duration <= ECHO_MAX_US) {
            pulse_seen = true;
            last_tick = now;
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr,
                    "[WARN] Echo pulse %u µs out of range [%u, %u] on GPIO %u\n",
                    duration, ECHO_MIN_US, ECHO_MAX_US, offset);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 µs pulse on the TRIG pin                                */
/* ------------------------------------------------------------------ */
static int trigger_sensor(void)
{
    if (gpiod_line_set_value(g_trig_line, 1) < 0) {
        fprintf(stderr, "[ERROR] Failed to set TRIG high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(g_trig_line, 0) < 0) {
        fprintf(stderr, "[ERROR] Failed to set TRIG low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in cm; returns -1.0 on error                          */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    uint32_t start_tick = gpiod_line_get_value_tick(g_echo_line);
    if (start_tick == 0) {
        /* No echo yet — warn and return 0.0 */
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr,
                "[WARN] No echo received on GPIO %u within %u µs — sensor absent or wiring fault\n",
                ECHO_PIN, ECHO_TIMEOUT_US);
        return 0.0f;
    }

    /* Wait for falling edge (timeout if no echo) */
    uint32_t waited = 0;
    while (gpiod_line_get_value(g_echo_line) == 1) {
        if (waited >= ECHO_TIMEOUT_US) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr,
                    "[WARN] Echo timeout on GPIO %u — no object within %u µs\n",
                    ECHO_PIN, ECHO_TIMEOUT_US);
            return 0.0f;
        }
        usleep(100);
        waited += 100;
    }

    uint32_t end_tick = gpiod_line_get_value_tick(g_echo_line);
    if (end_tick == 0) {
        /* Line went low unexpectedly — treat as timeout */
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr,
                "[WARN] Echo line went low unexpectedly on GPIO %u — sensor absent or wiring fault\n",
                ECHO_PIN);
        return 0.0f;
    }

    uint32_t duration = end_tick - start_tick;   /* handles 32-bit wraparound */

    if (duration < ECHO_MIN_US || duration > ECHO_MAX_US) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr,
                "[WARN] Echo pulse %u µs out of range [%u, %u] on GPIO %u\n",
                duration, ECHO_MIN_US, ECHO_MAX_US, ECHO_PIN);
        return 0.0f;
    }

    float distance = (float)duration / 58.0f;   /* speed of sound ~343 m/s */
    return distance;
}

/* ------------------------------------------------------------------ */
/* Log distance with timestamp to both stdout and file                 */
/* ------------------------------------------------------------------ */
static void log_distance(float distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    printf("%s Distance: %.2f cm\n", ts, distance);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s Distance: %.2f cm\n", ts, distance);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (gpiochip0 on Pi 4) */
    g_chip = gpiod_chip_open_by_number(0);
    if (!g_chip) {
        fprintf(stderr, "[ERROR] Cannot open gpiochip0: %s\n", strerror(errno));
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    /* Get trigger line */
    g_trig_line = gpiod_chip_get_line(g_chip, TRIGGER_PIN);
    if (!g_trig_line) {
        fprintf(stderr, "[ERROR] Cannot get GPIO %u: %s\n",
                TRIGGER_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request trigger line as output, initial value LOW */
    if (gpiod_line_request_output(g_trig_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "[ERROR] Cannot request GPIO %u as output: %s\n",
                TRIGGER_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Get echo line */
    g_echo_line = gpiod_chip_get_line(g_chip, ECHO_PIN);
    if (!g_echo_line) {
        fprintf(stderr, "[ERROR] Cannot get GPIO %u: %s\n",
                ECHO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request echo line as input with pull-down */
    if (gpiod_line_request_input_flags(g_echo_line, "hcsr04-echo",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "[ERROR] Cannot request GPIO %u as input: %s\n",
                ECHO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo alert callback */
    if (gpiod_line_event_subscribe(g_echo_line, echo_callback, NULL) < 0) {
        fprintf(stderr, "[ERROR] Cannot register echo callback: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] Cannot install SIGINT handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] Cannot install SIGTERM handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %u | Echo: GPIO %u | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        if (trigger_sensor() < 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float distance = read_distance();
        if (distance > 0.0f) {
            log_distance(distance);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

