    printf("Trigger: GPIO %u | Echo: GPIO %u | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        if (trigger_sensor() < 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float distance = read_distance();
        if (distance > 0.0f) {
            log_distance(distance);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

