#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* Configuration */
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define DISTANCE_THRESHOLD_OPEN 50
#define DISTANCE_THRESHOLD_CLOSE 60
#define LOG_FILE "parking_log.txt"
#define POLL_DELAY_US 100000

/* VL53L1X Registers */
#define VL53L1X_SOFT_RESET 0x0000
#define VL53L1X_SYSTEM_START 0x0001
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096
#define VL53L1X_MODEL_ID 0x010F

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value);
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value);
static int vl53l1x_init(int handle);
static int vl53l1x_read_distance(int handle, uint16_t *distance);
static void set_servo_angle(int angle);
static void log_event(const char *event, int distance);
static void signal_handler(int signal);
static void cleanup(void);

/* Write a 16-bit register (little-endian) */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (little-endian) */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the VL53L1X sensor */
static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;

    /* Check model ID */
    if (vl53l1x_read_reg16(handle, VL53L1X_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x00) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset */

    /* Start ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_START, 0x01) != 0) {
        return -1;
    }

    return 0;
}

/* Read distance from the VL53L1X sensor */
static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 100; /* 100 * 10 ms = 1 second timeout */

    /* Poll for data ready */
    do {
        if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(10000); /* 10 ms */
        timeout--;
    } while (timeout > 0);

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    /* Read distance */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE, distance) != 0) {
        return -1;
    }

    /* Clear interrupt */
    if (vl53l1x_write_reg16(handle, VL53L1X_RESULT_INTERRUPT_STATUS, 0x01) != 0) {
        return -1;
    }

    return 0;
}

/* Set servo angle using hardware PWM */
static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)angle / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

/* Log event to file */
static void log_event(const char *event, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - %s - Distance: %d cm\n", timestamp, event, distance);
    fflush(log_file);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0); /* Stop servo PWM */
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize VL53L1X sensor */
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    /* Set servo pin as output */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    int gate_state = 0; /* 0 = closed, 1 = open */

    while (program_running) {
        uint16_t distance = 0;

        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            int distance_cm = (int)distance;

            if (distance_cm > 0) {
                printf("Distance: %d cm\n", distance_cm);

                if (distance_cm < DISTANCE_THRESHOLD_OPEN && gate_state == 0) {
                    set_servo_angle(90);
                    gate_state = 1;
                    log_event("Gate Opened", distance_cm);
                } else if (distance_cm > DISTANCE_THRESHOLD_CLOSE && gate_state == 1) {
                    set_servo_angle(0);
                    gate_state = 0;
                    log_event("Gate Closed", distance_cm);
                }
            } else {
                fprintf(stderr, "Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

