/*
 * Raspberry Pi 4 Model B - VL53L1X Distance Sensor & DC Motor Controller
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3V
 *   VL53L1X GND -> GND
 *   Motor Forward -> GPIO17
 *   Motor Backward -> GPIO18
 *   Distance Sensor Trigger -> GPIO24 (BCM)
 *
 * Build: gcc -Wall -O2 -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define MOTOR_FORWARD_PIN    17
#define MOTOR_BACKWARD_PIN   18
#define DISTANCE_SENSOR_PIN  24
#define DISTANCE_THRESHOLD_LOW  100
#define DISTANCE_THRESHOLD_HIGH 300
#define POLL_TIMEOUT_MS      1000
#define POLL_INTERVAL_US     10000   /* 10 ms */
#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_US   100000  /* 100 ms */

/* ---- VL53L1X Registers ---- */
#define VL53L1X_SOFT_RESET_REG       0x0000
#define VL53L1X_SYSTEM_START_REG     0x0001
#define VL53L1X_RESULT_RANGE_STATUS  0x0089
#define VL53L1X_RESULT_DISTANCE      0x0096

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Function Prototypes ---- */
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *value);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void distance_sensor_isr(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- I2C helpers with retry ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X), attempt %d/%d: %d\n",
                reg, value, attempt + 1, I2C_RETRY_COUNT, rc);
        if (attempt < I2C_RETRY_COUNT - 1) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc != 0) {
            fprintf(stderr, "I2C write (reg select 0x%04X) failed, attempt %d/%d: %d\n",
                    reg, attempt + 1, I2C_RETRY_COUNT, rc);
            if (attempt < I2C_RETRY_COUNT - 1) {
                gpioDelay(I2C_RETRY_DELAY_US);
            }
            continue;
        }

        rc = i2cReadDevice(handle, (char *)value, 1);
        if (rc == 1) {
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg 0x%04X), attempt %d/%d: %d\n",
                reg, attempt + 1, I2C_RETRY_COUNT, rc);
        if (attempt < I2C_RETRY_COUNT - 1) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

/* ---- VL53L1X Initialization ---- */
static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET_REG, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_START_REG, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start ranging write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    return 0;
}

/* ---- Read distance from VL53L1X ---- */
static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;

    /* Poll data-ready bit */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read range status\n");
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for data-ready\n");
        return -1;
    }

    /* Read 16-bit distance */
    uint8_t data[2];
    if (i2c_read_reg16(handle, VL53L1X_RESULT_DISTANCE, data) != 0) {
        fprintf(stderr, "Failed to read distance data\n");
        return -1;
    }
    *distance = (data[0] << 8) | data[1];

    /* Clear interrupt by writing 0x01 to the status register */
    if (i2c_write_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, 0x01) != 0) {
        fprintf(stderr, "Failed to clear range status\n");
        return -1;
    }

    return 0;
}

/* ---- Motor Control ---- */
static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Forward\n");
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: Backward\n");
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Stop\n");
}

/* ---- ISR for distance sensor trigger ---- */
static void distance_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Failed to read distance, stopping motor\n");
            motor_stop();
        }
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    printf("\nCleaning up...\n");

    /* Stop motor */
    motor_stop();

    /* Close I2C handle */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n",
                VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    motor_stop();

    /* Configure distance sensor pin as input with pull-up */
    gpioSetMode(DISTANCE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_SENSOR_PIN, PI_PUD_UP);

    /* Register ISR for rising edge on distance sensor pin */
    if (gpioSetISRFuncEx(DISTANCE_SENSOR_PIN, RISING_EDGE, 0, distance_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for distance sensor pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

