/*
 * Raspberry Pi 4 Model B - VL53L1X Distance Sensor & DC Motor Controller
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3V
 *   VL53L1X GND -> GND
 *   Motor Forward -> GPIO17
 *   Motor Backward -> GPIO18
 *   Distance Sensor Trigger -> GPIO24 (BCM)
 *
 * Build: gcc -Wall -O2 -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define MOTOR_FORWARD_PIN    17
#define MOTOR_BACKWARD_PIN   18
#define DISTANCE_SENSOR_PIN  24
#define DISTANCE_THRESHOLD_LOW  100
#define DISTANCE_THRESHOLD_HIGH 300
#define POLL_TIMEOUT_MS      1000
#define POLL_INTERVAL_US     10000   /* 10 ms */
#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_US   100000  /* 100 ms */

/* ---- VL53L1X Registers ---- */
#define VL53L1X_SOFT_RESET_REG       0x0000
#define VL53L1X_SYSTEM_START_REG     0x0001
#define VL53L1X_RESULT_RANGE_STATUS  0x0089
#define VL53L1X_RESULT_DISTANCE      0x0096

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Function Prototypes ---- */
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *value);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void distance_sensor_isr(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- I2C helpers with retry ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X), attempt %d/%d: %d\n",
                reg, value, attempt + 1, I2C_RETRY_COUNT, rc);
        if (attempt < I2C_RETRY_COUNT - 1) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc != 0) {
            fprintf(stderr, "I2C write (reg select 0x%04X) failed, attempt %d/%d: %d\n",
                    reg, attempt + 1, I2C_RETRY_COUNT, rc);
            if (attempt < I2C_RETRY_COUNT - 1) {
                gpioDelay(I2C_RETRY_DELAY_US);
            }
            continue;
        }

        rc = i2cReadDevice(handle, (char *)value, 1);
        if (rc == 1) {
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg 0x%04X), attempt %d/%d: %d\n",
                reg, attempt + 1, I2C_RETRY_COUNT, rc);
        if (attempt < I2C_RETRY_COUNT - 1) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

/* ---- VL53L1X Initialization ---- */
static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET_REG, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_START_REG, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start ranging write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    return 0;
}

/* ---- Read distance from VL53L1X ---- */
static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;

    /* Poll data-ready bit */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read range status\n");
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for data-ready\n");
        return -1;
    }

    /* Read 16-bit distance */
    uint8_t data[2];
    if (i2c_read_reg16(handle, VL53L1X_RESULT_DISTANCE, data) != 0) {
        fprintf(stderr, "Failed to read distance data\n");
        return -1;
    }
    *distance = (data[0] << 8) | data[1];

    /* Clear interrupt by writing 0x01 to the status register */
    if (i2c_write_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, 0x01) != 0) {
        fprintf(stderr, "Failed to clear range status\n");
        return -1;
    }

    return 0;
}

/* ---- Motor Control ---- */
static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Forward\n");
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: Backward\n");
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Stop\n");
}

/* ---- ISR for distance sensor trigger ---- */
static void distance_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Failed to read distance, stopping motor\n");
            motor_stop();
        }
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    printf("\nCleaning up...\n");

    /* Stop motor */
    motor_stop();

    /* Close I2C handle */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n",
                VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    motor_stop();

    /* Configure distance sensor pin as input with pull-up */
    gpioSetMode(DISTANCE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_SENSOR_PIN, PI_PUD_UP);

    /* Register ISR for rising edge on distance sensor pin */
    if (gpioSetISRFuncEx(DISTANCE_SENSOR_PIN, RISING_EDGE, 0, distance_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for distance sensor pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Proximity-based interactive art installation using an MPR121 capacitive
 * touch sensor on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   MPR121 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MPR121 VDD -> 3.3 V
 *   MPR121 GND -> GND
 *   LEDs:
 *     Bit 0 -> GPIO 17
 *     Bit 1 -> GPIO 18
 *     Bit 2 -> GPIO 27
 *     Bit 3 -> GPIO 22
 *
 * Build: gcc -O2 -Wall -o mpr121_art mpr121_art.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- MPR121 register definitions ---- */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_CFG  0x5E
#define MPR121_SOFTRESET     0x80
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E

#define MPR121_I2C_ADDR      0x5C
#define MPR121_I2C_BUS       "/dev/i2c-1"

#define NUM_ELECTRODES       12
#define POLL_INTERVAL_US    50000   /* 50 ms */
#define LED_PIN_OFFSET      17
#define NUM_LED_PINS        4

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_led_lines[NUM_LED_PINS];

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- MPR121 initialization ---- */
static int mpr121_init(int fd)
{
    uint8_t whoami;

    /* Verify sensor presence by reading back the MHDR register */
    if (i2c_read_reg(fd, MPR121_MHDR, &whoami) < 0) {
        fprintf(stderr, "MPR121 not responding on bus.\n");
        return -1;
    }
    if (whoami != 0x00) {
        fprintf(stderr, "Unexpected MHDR value: 0x%02X (expected 0x00).\n", whoami);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(1000);  /* 1 ms settle */

    /* Baseline tracking */
    if (i2c_write_reg(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLF, 0x0E) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLT, 0x0E) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2c_write_reg(fd, MPR121_E0TTH + (i * 2), 0x0C) < 0) return -1;
        if (i2c_write_reg(fd, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 samples for release */
    if (i2c_write_reg(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* Config1: 16 uA charge current, 16 uA discharge current */
    if (i2c_write_reg(fd, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* Config2: 16 uA charge current, 16 uA discharge current */
    if (i2c_write_reg(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, baseline tracking */
    if (i2c_write_reg(fd, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

/* ---- LED pattern mapping ---- */
static const uint8_t led_patterns[16] = {
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
    0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F
};

/* ---- LED control ---- */
static void led_set(int pin, uint8_t pattern)
{
    if (pin < 0 || pin >= NUM_LED_PINS)
        return;
    if (gpiod_line_set_value(g_led_lines[pin], led_patterns[pattern]) < 0)
        fprintf(stderr, "Failed to set LED on GPIO %d: %s\n",
                pin, strerror(errno));
}

static void led_off(int pin)
{
    if (pin < 0 || pin >= NUM_LED_PINS)
        return;
    if (gpiod_line_set_value(g_led_lines[pin], 0) < 0)
        fprintf(stderr, "Failed to turn off LED on GPIO %d: %s\n",
                pin, strerror(errno));
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    for (int i = 0; i < NUM_LED_PINS; i++) {
        if (g_led_lines[i]) {
            led_off(i);
            gpiod_line_release(g_led_lines[i]);
            g_led_lines[i] = NULL;
        }
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Open I2C bus */
    g_i2c_fd = open(MPR121_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", MPR121_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED lines as outputs */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LED_PINS; i++) {
        g_led_lines[i] = gpiod_chip_get_line(g_chip, LED_PIN_OFFSET + i);
        if (!g_led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO %d: %s\n",
                    LED_PIN_OFFSET + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(g_led_lines[i], "mpr121_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                    LED_PIN_OFFSET + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Open log file */
    g_log_fp = fopen("mpr121_art.log", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 proximity art installation started. Press Ctrl+C to exit.\n");

    uint8_t touch_status[2];
    int prev_touch_state = 0;

    while (g_running) {
        if (i2c_read_block(g_i2c_fd, MPR121_TOUCHSTATUS_L, touch_status, 2) < 0) {
            fprintf(stderr, "Failed to read touch status. Retrying...\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int touch_state = (touch_status[1] << 8) | touch_status[0];

        /* Detect proximity on any electrode */
        bool proximity_detected = false;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
