/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM, output)
 *   HC-SR04 ECHO -> GPIO18 (BCM, input)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c
 *
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define SPEED_OF_SOUND_CM_PER_S 343.0f
#define MIN_DISTANCE_CM       2.0f
#define MAX_DISTANCE_CM       400.0f
#define TRIGGER_PULSE_US      10
#define ECHO_TIMEOUT_US       30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US         1000000 /* 1 s between readings */
#define LOG_FILE_NAME        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int safe_write(int pin, int level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n",
                pin, level, strerror(errno));
        return -1;
    }
    return 0;
}

static int safe_read(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, strerror(errno));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 timing                                                      */
/* ------------------------------------------------------------------ */
static uint32_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return 0;
    }
    return (uint32_t)(ts.tv_sec * 1000000ULL + ts.tv_nsec / 1000ULL);
}

/*
 * Wait for the echo pin to reach the given level (1 = rising edge).
 * Returns 0 on success, -1 on timeout.
 */
static int wait_for_level(int pin, int level, uint32_t timeout_us)
{
    uint32_t start = now_us();
    while (g_running) {
        int v = safe_read(pin);
        if (v < 0)
            return -1;
        if (v == level)
            return 0;
        if (now_us() - start > timeout_us)
            return -1;
    }
    return -1;
}

/*
 * Measure echo pulse width in microseconds.
 * Returns pulse width on success, 0 on timeout, -1 on error.
 */
static int measure_echo_pulse(int pin)
{
    /* Wait for echo rising edge */
    if (wait_for_level(pin, 1, ECHO_TIMEOUT_US) != 0)
        return 0;

    uint32_t rise_us = now_us();

    /* Wait for echo falling edge */
    if (wait_for_level(pin, 0, ECHO_TIMEOUT_US) != 0)
        return 0;

    uint32_t fall_us = now_us();
    return (int)(fall_us - rise_us);
}

/* ------------------------------------------------------------------ */
/* Distance calculation                                                */
/* ------------------------------------------------------------------ */
static float calculate_distance(int pulse_us)
{
    if (pulse_us <= 0)
        return -1.0f;
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (safe_write(TRIGGER_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        /* --- Issue 10 µs trigger pulse --- */
        if (safe_write(TRIGGER_PIN, 1) != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (safe_write(TRIGGER_PIN, 0) != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* --- Measure echo pulse --- */
        int pulse_us = measure_echo_pulse(ECHO_PIN);

        if (pulse_us == 0) {
            fprintf(stderr, "Error: Echo pulse timeout (sensor absent or no object)\n");
            log_distance(-1.0f);
        } else if (pulse_us < 0) {
            fprintf(stderr, "Error: GPIO read error during measurement\n");
            log_distance(-1.0f);
        } else {
            float distance = calculate_distance(pulse_us);
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: Distance %.2f cm out of range [%.0f, %.0f]\n",
                        distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
                log_distance(-1.0f);
            } else {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            }
        }

        /* --- Wait before next measurement --- */
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

