/*
 * HC-SR04 Ultrasonic Distance Measurement with Interrupt-Driven Echo
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod (modern GPIO character-device API)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (keep Pi input ~3.3V)
 *
 * Build:
 *   gcc -O2 -Wall -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_US 1000000   /* 1 second */
#define ECHO_TIMEOUT_US  30000     /* 30 ms max echo wait */
#define MIN_DISTANCE_M   0.01f     /* 1 cm */
#define MAX_DISTANCE_M   4.0f      /* 4 cm */

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                          */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_start_tick = 0;
static volatile uint32_t     g_end_tick   = 0;
static volatile bool         g_echo_seen  = false;

static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback (runs in libgpiod thread)                               */
/* ------------------------------------------------------------------ */

static void echo_callback(struct gpiod_line *line,
                          struct gpiod_line_event *event,
                          void *userdata)
{
    (void)line;
    (void)userdata;

    if (event->event_type != GPIOD_LINE_EVENT_BOTH_EDGES)
        return;

    uint32_t now = gpiod_line_event_get_tick(event);

    if (g_echo_seen) {
        /* Tick wrap-around detected: subtract 2^32 to get correct delta */
        uint32_t delta = now - g_end_tick;
        if (delta > (uint32_t)(SAMPLE_PERIOD_US / 2)) {
            /* Reset to avoid spurious readings */
            g_start_tick = 0;
            g_end_tick   = 0;
            g_echo_seen  = false;
            return;
        }
    } else {
        g_start_tick = now;
    }

    g_end_tick   = now;
    g_echo_seen  = true;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Disable ISR before closing the line */
    struct gpiod_line_event_callback cb;
    memset(&cb, 0, sizeof(cb));
    cb.event_type = GPIOD_LINE_EVENT_BOTH_EDGES;
    cb.callback   = NULL;
    gpiod_line_event_callback_unreg(gpiod_line_get_event_consumer(g_echo_line), &cb);

    /* Release the line */
    gpiod_line_release(g_echo_line);
    g_echo_line = NULL;

    /* Close the log file */
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Cleanup libgpiod */
    gpiod_chip_close(g_chip);
    g_chip = NULL;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line_event_callback cb;
    int ret;

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get trigger line ---- */
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n",
                TRIGGER_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Get echo line ---- */
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n",
                ECHO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Request trigger line as output, initial value LOW ---- */
    ret = gpiod_line_request_output(trigger_line, "hcsr04-trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Request echo line as input ---- */
    ret = gpiod_line_request_input(echo_line, "hcsr04-echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register echo event callback ---- */
    memset(&cb, 0, sizeof(cb));
    cb.event_type = GPIOD_LINE_EVENT_BOTH_EDGES;
    cb.callback   = echo_callback;
    ret = gpiod_line_event_callback_register(echo_line, &cb);
    if (ret < 0) {
        fprintf(stderr, "Failed to register echo callback: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");
    printf("Logging to '%s'.\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state for next measurement */
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen  = false;

        /* 10 µs trigger pulse */
        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger HIGH: %s\n",
                    strerror(errno));
            break;
        }
        usleep(10);
        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger LOW: %s\n",
                    strerror(errno));
            break;
        }

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            usleep(100);
            waited += 100;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: Echo timeout (no pulse received within %u µs).\n",
                    ECHO_TIMEOUT_US);
            continue;
        }

        /* Calculate pulse width (microseconds) */
        uint32_t pulse_width = g_end_tick - g_start_tick;

        /* Sanity check: HC-SR04 range is 58 µs to 25 µs */
        if (pulse_width < 58 || pulse_width > 25000) {
            fprintf(stderr, "Warning: Invalid pulse width %u µs (out of range).\n",
                    pulse_width);
            continue;
        }

        /* Convert pulse width to distance (meters) */
        float distance = (float)pulse_width * 0.01715f;

        /* Validate distance range */
        if (distance < MIN_DISTANCE_M || distance > MAX_DISTANCE_M) {
            fprintf(stderr, "Warning: Distance %.2f m out of range [%.1f, %.1f].\n",
                    distance, MIN_DISTANCE_M, MAX_DISTANCE_M);
            continue;
        }

        /* Get current timestamp */
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        localtime_r(&rawtime, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        /* Append to log file */
        if (fprintf(g_log_fp, "%s, Distance: %.2f m\n", timestamp, distance) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n",
                    strerror(errno));
            break;
        }
        fflush(g_log_fp);

        printf("%s, Distance: %.2f m\n", timestamp, distance);

        /* Wait for next sample interval */
        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

