#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define I2C_BUS 1
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_vl53l1x(int handle) {
    uint8_t xshut_val = 1;
    if (i2cWriteByteData(handle, 0x00, xshut_val) < 0) {
        syslog(LOG_ERR, "Failed to write XSHUT pin (0x00)");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByteData(handle, 0x00, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write XSHUT pin (0x00)");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t data[2];
    if (i2cReadI2CBlockData(handle, 0x14, (char *)data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }
    *distance = (data[0] << 8) | data[1];
    return 0;
}

static void log_data(uint16_t distance, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (status == 0) {
        syslog(LOG_INFO, "%s - Distance: %u mm", timestamp, distance);
    } else {
        syslog(LOG_ERR, "%s - Error reading distance: %d", timestamp, status);
    }
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at address 0x%02X: %d", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
