#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define GATE_PIN 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0002
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int read_reg16_u16(int handle, uint16_t reg, uint16_t *value) {
    uint8_t msb, lsb;
    if (read_reg16(handle, reg, &msb) != 0) {
        return -1;
    }
    if (read_reg16(handle, reg + 1, &lsb) != 0) {
        return -1;
    }
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int init_vl53l1x(int handle) {
    uint8_t mode;
    if (read_reg16(handle, VL53L1X_REG_SYSTEM_MODE, &mode) != 0) {
        fprintf(stderr, "Error: Failed to read system mode register\n");
        return -1;
    }
    if (mode != 0x00) {
        if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
            fprintf(stderr, "Error: Failed to reset VL53L1X\n");
            return -1;
        }
        gpioDelay(10000);
        if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) {
            fprintf(stderr, "Error: Failed to start VL53L1X\n");
            return -1;
        }
        gpioDelay(10000);
    }
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set system mode\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance_mm(int handle, uint16_t *distance_mm) {
    if (write_reg16(handle, VL53L1X_REG_RANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }
    gpioDelay(10000);
    uint8_t status;
    for (int i = 0; i < 100; i++) {
        if (read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read range status\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        gpioDelay(1000);
    }
    if ((status & 0x01) != 0) {
        fprintf(stderr, "Error: Ranging timeout\n");
        return -1;
    }
    if (read_reg16_u16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) != 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void control_gate(int distance_cm) {
    int gate_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(GATE_PIN, gate_state) != 0) {
        fprintf(stderr, "Error: Failed to write to gate pin\n");
        log_event("Error: Failed to write to gate pin");
    } else {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Gate state set to %s", gate_state ? "OPEN" : "CLOSED");
        log_event(log_msg);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }
    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, 0);
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_event("Program started");
    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance_mm(i2c_handle, &distance_mm) == 0) {
            float distance_cm = distance_mm / 10.0f;
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Distance: %.2f cm", distance_cm);
            log_event(log_msg);
            control_gate(distance_cm);
        } else {
            log_event("Error: Failed to read distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    log_event("Program terminated");
    gpioWrite(GATE_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

