/*
 * HC-SR04 Ultrasonic Distance Measurement with Servo Tracking
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (interrupt-driven echo callback, API servo control)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   SG90 servo   -> GPIO18 (BCM, hardware PWM capable)
 *
 * Build:  gcc -O2 -Wall -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* 343 m/s / 1e6 us = 0.0343 cm/us */
#define MIN_DISTANCE_CM   2.0f
#define MAX_DISTANCE_CM   400.0f
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MIN_ANGLE   0
#define SERVO_MAX_ANGLE   180
#define SERVO_CENTER_ANGLE 90

#define SAMPLE_PERIOD_US  100000   /* 100 ms between measurements */
#define ECHO_TIMEOUT_US   30000    /* 30 ms echo timeout */
#define MOVING_AVG_SIZE   5

/* ----------------------------- Globals ---------------------------------- */
static volatile uint32_t g_pulse_width = 0;
static volatile bool     g_new_pulse    = false;
static volatile sig_atomic_t g_running = 1;

static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata);
static float calculate_distance(uint32_t pulse_width_us);
static int  set_servo_angle(int angle);
static int  log_data(float distance, int angle);
static void cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Echo Callback ----------------------------- */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_pulse_width = 0;
        g_new_pulse    = true;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        if (g_new_pulse) {
            g_pulse_width = tick;
            g_new_pulse    = false;
        }
    }
}

/* ----------------------------- Distance Calculation ------------------------ */
static float calculate_distance(uint32_t pulse_width_us)
{
    if (pulse_width_us == 0)
        return -1.0f;

    float distance = (float)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM)
        return -1.0f;

    return distance;
}

/* ----------------------------- Servo Control ----------------------------- */
static int set_servo_angle(int angle)
{
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }

    int pulse_us = SERVO_MIN_PULSE_US +
                   (int)((float)angle / 180.0f *
                          (float)(SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }

    return 0;
}

/* ----------------------------- Data Logging ----------------------------- */
static int log_data(float distance, int angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, angle) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }

    return 0;
}

/* ----------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Stop servo PWM signal */
    gpioServo(SERVO_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open distance_log.csv for writing\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Distance_CM,Servo_Angle_Deg\n");
        fflush(g_log_file);
    }

    /* Configure trigger pin as output and ensure it starts low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 0);

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pin as output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set SERVO_PIN %d as output\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo callback for rising and falling edges */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot set alert function for ECHO_PIN %d\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    /* Initialize servo to center position */
    if (set_servo_angle(SERVO_CENTER_ANGLE) != 0) {
        fprintf(stderr, "Error: could not initialize servo to center position\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* Moving average buffer */
    float distance_buffer[MOVING_AVG_SIZE];
    int   buffer_index = 0;
    int   buffer_count = 0;
    float sum = 0.0f;

    /* Main measurement loop */
    while (g_running) {
        /* Reset timeout counter */
        uint32_t timeout_start = gpioTick();

        /* Wait for echo with timeout */
        while (!g_new_pulse && g_running) {
            if ((int32_t)(gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
                fprintf(stderr, "Error: echo timeout (no echo received)\n");
                break;
            }
            gpioDelay(100); /* 100 µs poll interval */
        }

        if (!g_running)
            break;

        /* Read and clear pulse width */
        uint32_t pulse_width = g_pulse_width;
        g_pulse_width = 0;
        g_new_pulse    = false;

        /* Calculate distance */
        float distance = calculate_distance(pulse_width);

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: invalid distance reading (%u us), logging -1.0\n",
                    pulse_width);
            distance = -1.0f;
        }

        /* Update moving average */
        sum -= distance_buffer[buffer_index];
        distance_buffer[buffer_index] = distance;
        sum += distance;
        buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
        if (buffer_count < MOVING_AVG_SIZE)
            buffer_count++;

        float average_distance = (buffer_count > 0) ? (sum / buffer_count) : 0.0f;

        /* Set servo angle based on moving average */
        int angle = (int)(average_distance / 10.0f);
        if (angle < SERVO_MIN_ANGLE)
            angle = SERVO_MIN_ANGLE;
        if (angle > SERVO_MAX_ANGLE)
            angle = SERVO_MAX_ANGLE;

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error: could not set servo angle\n");
        }

        /* Log data */
        if (log_data(average_distance, angle) != 0) {
            fprintf(stderr, "Error: could not log data\n");
        }

        /* Wait for next measurement interval */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

