/*
 * Raspberry Pi Zero W — HC-SR04 ultrasonic distance reader with theremin-like audio.
 *
 * Hardware:
 *   - HC-SR04 trigger  -> GPIO23 (BCM)
 *   - HC-SR04 echo    -> GPIO24 (BCM)
 *   - 8-ohm speaker   -> PWM0 (GPIO18, BCM)
 *
 * Behavior:
 *   - Reads distance every 100 ms.
 *   - Maps distance [2 cm, 200 cm] to frequency [200 Hz, 2000 Hz] using a logarithmic scale.
 *   - Pulses the trigger line for 10 µs, then reads the echo line with a 200 ms timeout.
 *   - Drives PWM0 on GPIO18 with a 50 % duty cycle for the duration of the echo pulse.
 *   - Handles SIGINT/SIGTERM for clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f
#define PWM_DUTY_CYCLE   128   /* 50 % of 255 */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000 /* 200 ms */
#define LOOP_DELAY_US    100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimeters using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;
    int level;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read echo pin\n");
            return -1.0f;
        }
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo timeout (no object detected)\n");
            return -1.0f;
        }
    } while (level == 0);
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if object too far) */
    timeout_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read echo pin\n");
            return -1.0f;
        }
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo timeout (object too far)\n");
            return -1.0f;
        }
    } while (level == 1);
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f; /* speed of sound: 343 m/s = 0.0343 cm/µs */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/*
 * Map distance [MIN_DISTANCE_CM, MAX_DISTANCE_CM] to frequency [MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ].
 * Returns frequency in Hz, or -1.0 on error.
 */
static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }

    float log_distance = log10f(distance / MIN_DISTANCE_CM);
    float log_range = log10f(MAX_DISTANCE_CM / MIN_DISTANCE_CM);
    float frequency = MIN_FREQUENCY_HZ * powf(10.0f, log_distance / log_range);

    if (frequency < MIN_FREQUENCY_HZ || frequency > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Warning: frequency %.2f Hz out of range [%.0f, %.0f]\n",
                frequency, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
        return -1.0f;
    }

    return frequency;
}

/*
 * Set PWM frequency on PWM_PIN.
 * Returns 0 on success, -1 on error.
 */
static int set_pwm_frequency(float frequency)
{
    if (frequency <= 0.0f) {
        fprintf(stderr, "Error: invalid frequency %.2f Hz\n", frequency);
        return -1;
    }

    int period_us = 1000000 / (int)frequency; /* pigpio expects period in microseconds */
    if (gpioSetPWMfrequency(PWM_PIN, period_us) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency to %.2f Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO%d\n", PWM_PIN);
        return -1;
    }
    return 0;
}

/*
 * Stop PWM on PWM_PIN.
 */
static void stop_pwm(void)
{
    gpioPWM(PWM_PIN, 0);
}

int main(void)
{
    float previous_frequency = -1.0f;
    float current_frequency = -1.0f;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Error already reported; keep previous frequency */
        } else {
            current_frequency = map_distance_to_frequency(distance);

            if (current_frequency < 0.0f) {
                /* Error already reported; keep previous frequency */
            } else if (current_frequency != previous_frequency) {
                if (set_pwm_frequency(current_frequency) < 0) {
                    fprintf(stderr, "Error: failed to set PWM frequency to %.2f Hz\n", current_frequency);
                } else {
                    previous_frequency = current_frequency;
                    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, current_frequency);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    stop_pwm();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

