#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 5.0
#define MAX_DISTANCE_CM 50.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define ECHO_TIMEOUT_US 100000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set ECHO_PIN %d pull-down.\n", ECHO_PIN);
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }
    gpioDelay(50000);

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
        return -1;
    }
    return 0;
}

static long measure_echo_pulse_us(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or no object).\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout (sensor stuck high).\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance_cm(long pulse_us) {
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static int map_distance_to_frequency(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;
    return (int)(MIN_FREQUENCY_HZ + (distance_cm - MIN_DISTANCE_CM) *
                  (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
}

static int set_buzzer_frequency(int frequency_hz) {
    if (frequency_hz < MIN_FREQUENCY_HZ) frequency_hz = MIN_FREQUENCY_HZ;
    if (frequency_hz > MAX_FREQUENCY_HZ) frequency_hz = MAX_FREQUENCY_HZ;

    int period_us = 1000000 / frequency_hz;
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency_hz) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency %d Hz.\n", frequency_hz);
        return -1;
    }
    if (gpioSetPWMrange(BUZZER_PIN, period_us) != 0) {
        fprintf(stderr, "Error: failed to set PWM range %d us.\n", period_us);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, period_us / 2) != 0) {
        fprintf(stderr, "Error: failed to start PWM on BUZZER_PIN.\n");
        return -1;
    }
    return 0;
}

static void stop_buzzer(void) {
    gpioPWM(BUZZER_PIN, 0);
}

static void cleanup(void) {
    stop_buzzer();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse_us = measure_echo_pulse_us();
        if (pulse_us < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance_cm = calculate_distance_cm(pulse_us);
        int frequency_hz = map_distance_to_frequency(distance_cm);

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance_cm, frequency_hz);

        if (set_buzzer_frequency(frequency_hz) != 0) {
            fprintf(stderr, "Warning: failed to set buzzer frequency.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

