/*
 * Si1175 Proximity & Ambient Light Logger for Raspberry Pi 4 Model B
 * Uses standard POSIX I2C API (no wiringPi dependency).
 *
 * Wiring:
 *   Si1175 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   Si1175 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * Build: gcc -O2 -Wall -o si1175_logger si1175_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR        0x46
#define SI1175_REG_PART_ID     0x00
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_PS1_DATA0   0x24
#define SI1175_REG_COMMAND     0x30
#define SI1175_REG_RESPONSE    0x20

#define SI1175_CMD_RESET       0x01
#define SI1175_CMD_PS_FORCE    0x05
#define SI1175_CMD_ALS_FORCE   0x06

#define SI1175_EXPECTED_PART_ID 0x75

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1175_reset(int fd)
{
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0)
        return -1;
    usleep(10000); /* 10 ms reset settling */
    return 0;
}

static int si1175_init(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1175_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1175_EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X). Sensor not present?\n",
                part_id, SI1175_EXPECTED_PART_ID);
        return -1;
    }

    if (si1175_reset(fd) < 0)
        return -1;

    /*
     * Enable PS1 and ALS_VIS channels.
     * PS1: 0x01 = PS1_ADC_EN | PS1_ADC_GAIN | PS1_ADC_MISC
     * ALS_VIS: 0x01 = ALS_VIS_ADC_EN | ALS_VIS_ADC_GAIN | ALS_VIS_ADC_MISC
     */
    if (i2c_write_reg8(fd, 0x01, 0x01) < 0)
        return -1;
    if (i2c_write_reg8(fd, 0x02, 0x01) < 0)
        return -1;

    return 0;
}

static int si1175_read_proximity(int fd, uint16_t *proximity)
{
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, SI1175_CMD_PS_FORCE) < 0)
        return -1;
    usleep(10000); /* 10 ms for PS measurement */

    uint8_t response;
    if (i2c_read_reg8(fd, SI1175_REG_RESPONSE, &response) < 0)
        return -1;
    if (response != 0x00) {
        fprintf(stderr, "PS measurement failed (response=0x%02X)\n", response);
        return -1;
    }

    return i2c_read_reg16(fd, SI1175_REG_PS1_DATA0, proximity);
}

static int si1175_read_ambient_light(int fd, uint16_t *ambient_light)
{
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000); /* 10 ms for ALS_VIS measurement */

    uint8_t response;
    if (i2c_read_reg8(fd, SI1175_REG_RESPONSE, &response) < 0)
        return -1;
    if (response != 0x00) {
        fprintf(stderr, "ALS_VIS measurement failed (response=0x%02X)\n", response);
        return -1;
    }

    return i2c_read_reg16(fd, SI1175_REG_ALS_VIS_DATA0, ambient_light);
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, ambient_light) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1175_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (si1175_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("proximity_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open proximity_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,als_visible\n");
        fflush(g_log_file);
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t proximity = 0;
        uint16_t ambient_light = 0;

        if (si1175_read_proximity(g_i2c_fd, &proximity) < 0) {
            fprintf(stderr, "Failed to read proximity data.\n");
        } else if (si1175_read_ambient_light(g_i2c_fd, &ambient_light) < 0) {
            fprintf(stderr, "Failed to read ambient light data.\n");
        } else {
            if (log_data(g_log_file, proximity, ambient_light) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        /* Sleep 5 seconds, checking g_running every second for responsive shutdown */
        for (int i = 0; i < 5 && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

