/*
 * Si1120 Ambient Light & Proximity Logger for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si1120 SDA -> GPIO2 (I2C bus 1 SDA)
 *   Si1120 SCL -> GPIO3 (I2C bus 1 SCL)
 *   Si1120 VDD -> 3.3V
 *   Si1120 GND -> GND
 *
 * Build: gcc -o si1120_logger si1120_logger.c -lpigpio -lrt
 * Run:   sudo ./si1120_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1120 I2C address (default) */
#define SI1120_ADDR 0x46

/* Si1120 register addresses */
#define SI1120_REG_PART_ID       0x00
#define SI1120_REG_HW_KEY        0x07
#define SI1120_REG_MEAS_RATE0    0x08
#define SI1120_REG_ALS_RATE0     0x09
#define SI1120_REG_PS_RATE0      0x0A
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_IR_DATA0  0x24
#define SI1120_REG_PS1_DATA0     0x26
#define SI1120_REG_PS2_DATA0     0x28
#define SI1120_REG_COMMAND      0x30

/* Si1120 command values */
#define SI1120_CMD_RESET         0x01
#define SI1120_CMD_ALS_FORCE     0x06
#define SI1120_CMD_PS_FORCE      0x05

/* Expected part ID */
#define SI1120_PART_ID          0x20

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000  /* 10 ms */
#define SAMPLE_INTERVAL_US 500000 /* 500 ms */

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Write a byte to a Si1120 register */
static int si1120_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

/* Read a byte from a Si1120 register */
static int si1120_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* Initialize the Si1120 sensor */
static int si1120_init(int handle) {
    uint8_t part_id = 0;

    /* Verify part ID */
    if (si1120_read_reg(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Error: Unexpected part ID 0x%02X (expected 0x%02X). Sensor not present?\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    /* Reset the sensor */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset to complete */

    /* Write HW_KEY to enable the sensor */
    if (si1120_write_reg(handle, SI1120_REG_HW_KEY, 0x17) != 0) {
        return -1;
    }

    /* Configure measurement rates */
    if (si1120_write_reg(handle, SI1120_REG_MEAS_RATE0, 0x0A) != 0) {
        return -1;
    }
    if (si1120_write_reg(handle, SI1120_REG_ALS_RATE0, 0x0A) != 0) {
        return -1;
    }
    if (si1120_write_reg(handle, SI1120_REG_PS_RATE0, 0x0A) != 0) {
        return -1;
    }

    return 0;
}

/* Read ambient light and proximity data from the Si1120 sensor */
static int si1120_read_data(int handle, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_vis_data0 = 0, als_ir_data0 = 0, ps1_data0 = 0, ps2_data0 = 0;
    int retries = 0;

    /* Trigger ALS force measurement */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for measurement */

    /* Read ALS VIS data */
    if (si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA0, &als_vis_data0) != 0) {
        return -1;
    }

    /* Read ALS IR data */
    if (si1120_read_reg(handle, SI1120_REG_ALS_IR_DATA0, &als_ir_data0) != 0) {
        return -1;
    }

    /* Read PS1 data */
    if (si1120_read_reg(handle, SI1120_REG_PS1_DATA0, &ps1_data0) != 0) {
        return -1;
    }

    /* Read PS2 data */
    if (si1120_read_reg(handle, SI1120_REG_PS2_DATA0, &ps2_data0) != 0) {
        return -1;
    }

