    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1120 address */
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1120 sensor */
    if (si1120_init(i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 data logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t ambient_light = 0, proximity = 0;
        int success = 0;

        /* Retry loop for I2C operations */
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            if (si1120_read_data(i2c_handle, &ambient_light, &proximity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "I2C read failed, retry %d/%d\n", retry + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
        }

