#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define DISTANCE_THRESHOLD_CM 20.0f
#define TRIGGER_PULSE_US      10
#define ECHO_TIMEOUT_US       300000  /* 300 ms max echo wait */
#define LOOP_DELAY_US         1000000 /* 1 second */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_ready  = 0;
static volatile int      g_running     = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio alert callback for echo pin.
 * level == 1  -> rising edge  (echo pulse starts)
 * level == 0  -> falling edge (echo pulse ends)
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_ready  = 0;
    } else if (level == 0) {
        g_end_tick   = tick;
        g_echo_ready  = 1;
    }
}

/*
 * Measure distance in centimetres.
 * Returns -1.0f on timeout / error.
 */
static float measure_distance(void)
{
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(2);  /* settle */

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo to go high (start of pulse) */
    uint32_t waited = 0;
    while (!g_echo_ready && waited < ECHO_TIMEOUT_US) {
        gpioDelay(10);
        waited += 10;
    }
    if (!g_echo_ready) {
        fprintf(stderr, "Error: echo start timeout (sensor absent or out of range)\n");
        return -1.0f;
    }

    /* Wait for echo to go low (end of pulse) */
    waited = 0;
    while (g_echo_ready && waited < ECHO_TIMEOUT_US) {
        gpioDelay(10);
        waited += 10;
    }
    if (!g_echo_ready) {
        fprintf(stderr, "Error: echo end timeout (sensor absent or out of range)\n");
        return -1.0f;
    }

    uint32_t pulse_us = g_end_tick - g_start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f;
    return distance;
}

static void control_buzzer(float distance)
{
    int buzzer_state = (distance < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(BUZZER_PIN, buzzer_state) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d\n", BUZZER_PIN);
    }
}

int main(void)
{
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin %d low\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(2000);  /* 2 ms settle */

    /* Register echo alert callback */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ultrasonic distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm | Pulse: %d us | Timeout: %d us\n",
           DISTANCE_THRESHOLD_CM, TRIGGER_PULSE_US, ECHO_TIMEOUT_US);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Warning: distance measurement failed, skipping buzzer control\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);  /* unregister callback */
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

