/*
 * HC-SR04 Ultrasonic Distance Measurement with Servo Control
 * Board:  Raspberry Pi 4 Model B
 * Trigger: GPIO23 (BCM)  Echo: GPIO24 (BCM)
 * Servo:   GPIO18 (BCM)  VCC: 5V, GND: GND
 *
 * Build:  gcc -O2 -Wall -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* 343 m/s / 1e6 us = 0.0343 cm/us */
#define MIN_DISTANCE_CM   2.0f
#define MAX_DISTANCE_CM   400.0f
#define MIN_ANGLE_DEG    0
#define MAX_ANGLE_DEG    180
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000      /* 50 ms max wait for echo */
#define LOOP_DELAY_US     100000     /* 100 ms between measurements */
#define SERVO_MIN_US      500
#define SERVO_MAX_US      2500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm.
 * Returns >= 0 on success, -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(2);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising edge timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling edge timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }
    return distance;
}

/*
 * Map distance (cm) to angle (degrees).
 * Returns -1.0 on invalid input.
 */
static float distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float angle = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                 (float)(MAX_ANGLE_DEG - MIN_ANGLE_DEG) +
                 (float)MIN_ANGLE_DEG;

    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;

    return angle;
}

/*
 * Set servo angle (0-180 degrees).
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %.2f degrees out of range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    int pulse_width = (int)((angle / (float)(MAX_ANGLE_DEG - MIN_ANGLE_DEG)) *
                            (float)(SERVO_MAX_US - SERVO_MIN_US) +
                            (float)SERVO_MIN_US);

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

/*
 * Stop servo by sending 0-degree command.
 */
static void stop_servo(void)
{
    gpioServo(SERVO_PIN, 0);
}

int main(void)
{
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with servo stopped */
    stop_servo();

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: measurement failed, skipping cycle\n");
        } else {
            float angle = distance_to_angle(distance);
            printf("Distance: %.2f cm  Angle: %.2f degrees\n", distance, angle);

            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error: failed to set servo angle\n");
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    stop_servo();
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

