#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x44
#define CONFIG_REG 0xF5
#define READ_REG 0xE0
#define CONVERSION_DELAY_US 10000
#define LOOP_DELAY_US 2000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (error %d)\n",
                SI7005_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(float *temperature, float *humidity) {
    char config_buf[2] = {CONFIG_REG, 0x01};
    char read_buf[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register (error %d)\n", result);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    result = i2cWriteDevice(i2c_handle, (char *)&SI7005_ADDR, 1);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write read register address (error %d)\n", result);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read sensor data (expected 2 bytes, got %d)\n", result);
        return -1;
    }

    uint16_t raw_humidity = ((uint16_t)(read_buf[0] & 0xFC) << 8) | (uint8_t)read_buf[1];
    uint16_t raw_temperature = ((uint16_t)(read_buf[0] & 0x03) << 10) | ((uint16_t)(read_buf[1] & 0xFC) << 2);

    *humidity = -6.0f + 125.0f * (float)raw_humidity / 65536.0f;
    *temperature = -46.85f + 175.72f * (float)raw_temperature / 65536.0f;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

