    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    printf("Si7005 sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
