            fprintf(stderr, "Error: Failed to read sensor data. Attempting recovery...\n");
            cleanup();
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Error: Failed to re-initialize I2C. Exiting.\n");
                return EXIT_FAILURE;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

