code:
/*
 * MPU-6050 accelerometer/gyroscope reader for Raspberry Pi 3 Model B+
 * Uses the standard Linux i2c-dev API (no wiringPi dependency).
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MPU-6050 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MPU-6050 VDD -> 3.3 V
 *   MPU-6050 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mpu6050_reader mpu6050_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 register addresses ---- */
#define MPU6050_ADDR          0x68
#define MPU6050_WHO_AM_I      0x75
#define MPU6050_PWR_MGMT_1    0x6B
#define MPU6050_ACCEL_XOUT_H  0x3B
#define MPU6050_GYRO_XOUT_H   0x43

/* Expected device ID for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL  0x68

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd of %zu)\n",
                reg, strerror(errno), n, sizeof(buf));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at a 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: verify device ID, wake up, set sample rate. */
static int mpu6050_init(int fd)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, MPU6050_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    printf("MPU-6050 detected (WHO_AM_I = 0x%02X).\n", who_am_i);

    /* Wake up the device (clear sleep bit) */
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050.\n");
        return -1;
    }
    usleep(100000); /* allow oscillator to stabilize */

    /* Sample rate divider = 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x07) != 0) {
        fprintf(stderr, "Failed to set sample rate divider.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 14 bytes of raw sensor data (accel + temp + gyro). */
static int mpu6050_read_raw(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *t, int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];

    if (i2c_read_block(fd, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) != 0) {
        return -1;
    }

    /* MPU-6050 data is big-endian: [ax_h, ax_l, ay_h, ay_l, az_h, az_l, t_h, t_l, gx_h, gx_l, gy_h, gy_l, gz_h, gz_l] */
    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    *t  = (int16_t)((buf[6]  << 8) | buf[7]);
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Logging data every 100 ms (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az, t, gx, gy, gz;

        if (mpu6050_read_raw(g_i2c_fd, &ax, &ay, &az, &t, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Temp: %6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, t, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Put the MPU-6050 into sleep mode before closing */
        (void)i2c_write_reg8(g_i2c_fd, MPU6050_PWR_MGMT_1, 0x40);
        close(g_i2c_fd);
    }

    return EXIT_SUCCESS;
}

