/*
 * SHT40 Temperature & Humidity Sensor Reader for Raspberry Pi 4 Model B
 * Uses the Adafruit SHT40 I2C address (0x44) and high repeatability measurement.
 *
 * Wiring:
 *   SHT40 VCC  -> Pi 3.3V (Pin 1)
 *   SHT40 GND  -> Pi GND  (Pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o sht40_reader sht40_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR             0x44
#define I2C_BUS                "/dev/i2c-1"
#define MEASUREMENT_DELAY_US   10000   /* 10 ms high repeatability measurement */
#define READ_INTERVAL_S        5
#define MAX_RETRIES            3

/* SHT40 command: start high repeatability measurement, clock stretching disabled */
static const uint8_t CMD_MEASURE_HIGH_REP[2] = {0x2C, 0x06};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t n = write(fd, cmd, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C write short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHT40 measurement                                                  */
/* ------------------------------------------------------------------ */
static int sht40_measure(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, CMD_MEASURE_HIGH_REP, sizeof(CMD_MEASURE_HIGH_REP)) < 0)
        return -1;

    usleep(MEASUREMENT_DELAY_US);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRCs */
    if (!crc8_check(&data[0], 2, data[2])) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&data[3], 2, data[5])) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, SHT40_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("SHT40 reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        bool success = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sht40_measure(g_i2c_fd, &temperature, &humidity) == 0) {
                success = true;
                break;
            }
            fprintf(stderr, "Measurement attempt %d failed.\n", attempt + 1);
            if (attempt < MAX_RETRIES - 1)
                sleep(1);
        }

        if (success) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL &&
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n",
                       ts, temperature, humidity);
            } else {
                printf("[unknown time] Temperature: %.2f C, Humidity: %.2f %%\n",
                       temperature, humidity);
            }
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read SHT40 after %d attempts. Re-opening I2C bus.\n",
                    MAX_RETRIES);
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);

            g_i2c_fd = i2c_open(I2C_BUS, SHT40_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                return EXIT_FAILURE;
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* Graceful cleanup */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

