#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_temperature(int fd, float *ambient, float *object) {
    uint16_t raw_ambient, raw_object;

    if (i2c_read_reg16(fd, 0x00, &raw_ambient) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, 0x02, &raw_object) < 0) {
        return -1;
    }

    *ambient = -45.0f + (175.0f * (float)raw_ambient / 65535.0f);
    *object = -45.0f + (175.0f * (float)raw_object / 65535.0f);

    return 0;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to write to sensor configuration register\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting temperature logging. Press Ctrl+C to stop.\n");

    while (program_running) {
        float ambient, object;

        if (read_temperature(i2c_fd, &ambient, &object) == 0) {
            if (log_temperature(log_file, ambient, object) < 0) {
                fprintf(stderr, "Failed to log temperature data\n");
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        } else {
            fprintf(stderr, "Failed to read temperature data\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nCleaning up and exiting...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

