/*
 * SDP31 differential pressure & temperature logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP31 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   SDP31 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   SDP31 VDD  -> 3.3 V
 *   SDP31 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o sdp31_logger sdp31_logger.c -lsensirion_i2c
 *
 * Run:
 *   ./sdp31_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <sensirion_i2c.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x48
#define LOG_FILE       "airflow.log"
#define SAMPLE_MS      100
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        sensirion_i2c_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    sensirion_i2c_cleanup();
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = sensirion_i2c_write_byte(handle, cmd);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[I2C] write_byte(0x%02X) failed (attempt %d/%d): %s\n",
                cmd, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = sensirion_i2c_read_bytes(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "[I2C] read_bytes(%zu) failed (attempt %d/%d): got %d, expected %zu\n",
                len, attempt + 1, MAX_RETRIES, rc, len);
        usleep(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* SDP31 measurement                                                  */
/* ------------------------------------------------------------------ */
static int sdp31_read(int handle, float *pressure_pa, float *temperature_c)
{
    uint8_t cmd = 0x36;   /* continuous measurement, no averaging */
    uint8_t buf[6];

    if (i2c_write_cmd(handle, cmd) != 0)
        return -1;

    usleep(1000);          /* 1 ms conversion time */

    if (i2c_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC check: bytes 2-3, bytes 4-5 */
    uint16_t crc_p = (uint16_t)((buf[2] << 8) | buf[3]);
    uint16_t crc_t = (uint16_t)((buf[4] << 8) | buf[5]);
    uint16_t calc_p = sensirion_crc16(buf, 2);
    uint16_t calc_t = sensirion_crc16(buf + 3, 2);

    if (crc_p != calc_p || crc_t != calc_t) {
        fprintf(stderr, "[SDP31] CRC mismatch: p=0x%04X calc=0x%04X, t=0x%04X calc=0x%04X\n",
                crc_p, calc_p, crc_t, calc_t);
        return -1;
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure_pa    = (float)raw_p * 0.1f;   /* Pa */
    *temperature_c = (float)raw_t * 0.02f - 45.0f; /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[LOG] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[LOG] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[LOG] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "[LOG] fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (sensirion_i2c_init() != 0) {
        fprintf(stderr, "sensirion_i2c_init() failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = sensirion_i2c_open(I2C_BUS, SDP31_ADDR);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "sensirion_i2c_open(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SDP31_ADDR, strerror(errno));
        sensirion_i2c_cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP31 logger started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        float pressure_pa = 0.0f;
        float temperature_c = 0.0f;

        if (sdp31_read(g_i2c_handle, &pressure_pa, &temperature_c) == 0) {
            if (log_data(g_log_file, pressure_pa, temperature_c) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                       pressure_pa, temperature_c);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 100)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

