#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x44
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUMID_HOLD 0xE5
#define MEASURE_READY_TIMEOUT_US 20000
#define SAMPLE_INTERVAL_US 5000000
#define LOG_FILE "sensor_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_measurement(uint8_t cmd, uint16_t *raw) {
    int result;
    uint8_t buf[2];

    result = i2cWriteByte(i2c_handle, cmd);
    if (result < 0) {
        fprintf(stderr, "Error writing measurement command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }

    gpioDelay(MEASURE_READY_TIMEOUT_US);

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading measurement data: expected 2 bytes, got %d: %s\n", result, strerror(errno));
        return -1;
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(float *temperature) {
    uint16_t raw;
    if (read_measurement(MEASURE_TEMP_HOLD, &raw) != 0) {
        return -1;
    }
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static int read_humidity(float *humidity) {
    uint16_t raw;
    if (read_measurement(MEASURE_HUMID_HOLD, &raw) != 0) {
        return -1;
    }
    *humidity = 100.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", buf, temperature, humidity);
    fflush(log_file);
    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", buf, temperature, humidity);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying in 5 seconds...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

