#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REP 0x2C
#define LOG_FILE "sht40_log.txt"
#define I2C_BUS "/dev/i2c-1"
#define MEASUREMENT_DELAY_MS 10
#define POLL_INTERVAL_SEC 5

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REP;
    uint8_t buf[6];

    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + (175.0f * temp_raw / 65535.0f);
    *humidity = 100.0f * hum_raw / 65535.0f;

    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f%%\n", *humidity);
        return -1;
    }

    return 0;
}

static void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Error: Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Smart Greenhouse Monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_sht40(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

