    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("SDP800 ventilation monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;

        if (read_sdp800(&pressure, &temperature) == 0) {
