#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x44
#define FAN_GPIO       18
#define TEMP_THRESHOLD 28.0f
#define TEMP_HYSTERESIS 27.0f
#define BUFFER_SIZE    60
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000
#define FAN_ON_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float temperature;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char cmd = 0x24;
    char data[2];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(18000);
            result = i2cReadDevice(i2c_handle, data, 2);
            if (result == 2) {
                uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
                *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
                return 0;
            }
        }
        fprintf(stderr, "I2C write/read error (attempt %d/%d): %d\n",
                attempt + 1, RETRY_COUNT, result);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static void add_reading(float temperature) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Temperature Readings ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *tm_info = localtime(&buffer[idx].timestamp);
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Temperature: %.2f °C\n", time_str, buffer[idx].temperature);
    }
    printf("--- End of Readings ---\n\n");
}

static void control_fan(float temperature) {
    static bool fan_on = false;

    if (temperature > TEMP_THRESHOLD && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan turned ON (temperature: %.2f °C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_HYSTERESIS && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan turned OFF (temperature: %.2f °C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %d\n",
                SI7021_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 temperature monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(&temperature) == 0) {
            add_reading(temperature);
            printf("Temperature: %.2f °C\n", temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
            if (fan_on) {
                gpioWrite(FAN_GPIO, 0);
                fan_on = false;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    print_buffer();
    return EXIT_SUCCESS;
}

