/*
 * SCD40 CO2 sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SCD40 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   SCD40 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   SCD40 VDD -> 3.3 V
 *   SCD40 GND -> GND
 *
 * Build: gcc -Wall -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run:   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SCD40_ADDR     0x60
#define LOG_FILE       "air_quality.log"
#define SAMPLE_INTERVAL_S 5
#define MEASUREMENT_DELAY_S 1
#define MAX_RETRIES     3

/* SCD40 commands (16-bit, MSB first) */
#define CMD_START_PERIODIC_MEASUREMENT 0x2406
#define CMD_STOP_PERIODIC_MEASUREMENT 0x2405
#define CMD_READ_MEASUREMENT_DATA     0x2408

/* SCD40 register addresses (16-bit, MSB first) */
#define REG_MEASUREMENT_STATUS 0x0000
#define REG_CO2_VALUE         0x0002
#define REG_TEMP_VALUE        0x0004
#define REG_HUMIDITY_VALUE     0x0006

/* SCD40 measurement status bits */
#define MEASUREMENT_READY_BIT 0x01

/* SCD40 CRC-8 parameters (polynomial 0x31, init 0xFF) */
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion: poly 0x31, init 0xFF, no final XOR)     */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SCD40                                 */
/* ------------------------------------------------------------------ */
static int scd40_write_command(uint16_t cmd)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);

    int rc = i2cWriteDevice(g_i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the SCD40                               */
/* ------------------------------------------------------------------ */
static int scd40_read_register(uint16_t reg, uint16_t *value)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);

    int rc = i2cWriteDevice(g_i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg 0x%04X) failed: %d\n", reg, rc);
        return -1;
    }

    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg 0x%04X) failed: %d\n", reg, rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg 0x%04X) short read: %d\n", reg, rc);
        return -1;
    }

    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read measurement data (9 bytes: CO2, T, RH, CRC3, CRC4, CRC5)          */
/* ------------------------------------------------------------------ */
static int scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *rh)
{
    uint8_t buf[9];

    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(measurement) failed: %d\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice(measurement) short read: %d\n", rc);
        return -1;
    }

    /* Verify CRCs for each 2-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    *co2  = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = (uint16_t)((buf[3] << 8) | buf[4]);
    *rh   = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a CSV line with a timestamp                                    */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t co2, float temp, float rh)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Initialize the SCD40 sensor                                         */
/* ------------------------------------------------------------------ */
static int scd40_init(void)
{
    /* Send Start Periodic Measurement command */
    if (scd40_write_command(CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;

    /* Wait for the first measurement to be ready */
    for (int i = 0; i < 100; i++) {
        uint16_t status = 0;
        if (scd40_read_register(REG_MEASUREMENT_STATUS, &status) != 0)
            return -1;
        if (status & MEASUREMENT_READY_BIT)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if (!(status & MEASUREMENT_READY_BIT)) {
        fprintf(stderr, "[ERROR] SCD40 measurement not ready after 100 ms\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Send Stop Periodic Measurement command */
        (void)scd40_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (scd40_init() != 0) {
        fprintf(stderr, "[FATAL] SCD40 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,CO2_ppm,Temperature_C,Humidity_pct\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("SCD40 air quality monitor started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        uint16_t co2 = 0, temp = 0, rh = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (scd40_read_measurement(&co2, &temp, &rh) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] Measurement read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (ok) {
            float temp_c = -45.0f + 175.0f * (float)temp / 65535.0f;
            float rh_pct  = 100.0f * (float)rh / 65535.0f;

            printf("CO2: %u ppm  Temp: %.2f C  RH: %.2f %%\n", co2, temp_c, rh_pct);
            log_data(co2, temp_c, rh_pct);
        } else {
            fprintf(stderr, "[ERROR] Failed to read measurement after %d attempts\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

