/*
 * SCD40 CO2 Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA -> GPIO2 (I2C bus 1 SDA)
 *   SCD40 SCL -> GPIO3 (I2C bus 1 SCL)
 *   SCD40 VDD -> 3.3 V
 *   SCD40 GND -> GND
 *   LED anode -> GPIO17 (BCM), cathode -> GND
 *
 * Build: gcc -O2 -Wall -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run:   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SCD40_ADDR     0x60
#define LED_GPIO       17
#define CO2_THRESHOLD  1000
#define BUFFER_SIZE    20
#define SAMPLE_PERIOD  5          /* seconds */

/* SCD40 commands (16-bit, MSB first) */
#define CMD_START_MEASUREMENT 0x2602
#define CMD_READ_MEASUREMENT  0x2400
#define CMD_RESET            0x3003

/* SCD40 register addresses (16-bit, MSB first) */
#define REG_MEAS_CONFIG     0x0001
#define REG_MEAS_DATA      0x0002
#define REG_MEAS_CRC       0x0003
#define REG_MEAS_STATUS    0x0004
#define REG_MEAS_DATA_CRC  0x0005

/* Measurement configuration: 0x0000 = continuous measurement, 0x0001 = one-shot */
#define MEAS_CONFIG_CONTINUOUS 0x0000

/* Measurement status bits */
#define MEAS_STATUS_MEAS_READY 0x0001

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer entry */
typedef struct {
    time_t timestamp;
    int    co2;
    float  temperature;
    float  humidity;
} sensor_data_t;

static sensor_data_t g_buffer[BUFFER_SIZE];
static int g_buffer_index = 0;
static int g_buffer_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion polynomial 0x31, init 0xFF)            */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SCD40                                 */
/* ------------------------------------------------------------------ */
static int scd40_write_command(uint16_t cmd)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the SCD40                              */
/* ------------------------------------------------------------------ */
static int scd40_read_register(uint16_t reg, uint16_t *value)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%04X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read (reg 0x%04X) failed\n", reg);
        return -1;
    }

    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 24-bit measurement word from the SCD40                       */
/* ------------------------------------------------------------------ */
static int scd40_read_measurement(uint32_t *co2, float *temperature, float *humidity)
{
    uint16_t raw_co2, raw_temp, raw_hum;

    if (scd40_read_register(REG_MEAS_DATA, &raw_co2) != 0)
        return -1;
    if (scd40_read_register(REG_MEAS_DATA + 1, &raw_temp) != 0)
        return -1;
    if (scd40_read_register(REG_MEAS_DATA + 2, &raw_hum) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    if (crc8((uint8_t *)&raw_co2, 2) != (uint8_t)(raw_co2 >> 8)) {
        fprintf(stderr, "[ERROR] CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8((uint8_t *)&raw_temp, 2) != (uint8_t)(raw_temp >> 8)) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8((uint8_t *)&raw_hum, 2) != (uint8_t)(raw_hum >> 8)) {
        fprintf(stderr, "[ERROR] CRC mismatch on humidity word\n");
        return -1;
    }

    *co2      = (uint32_t)raw_co2;
    *temperature = (float)raw_temp / 10.0f;
    *humidity    = (float)raw_hum / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the SCD40 sensor                                        */
/* ------------------------------------------------------------------ */
static int scd40_init(void)
{
    /* Reset the sensor */
    if (scd40_write_command(CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms reset delay */

    /* Start continuous measurement */
    if (scd40_write_command(CMD_START_MEASUREMENT) != 0)
        return -1;

    /* Wait for the first measurement to be ready */
    uint16_t status;
    for (int i = 0; i < 100; i++) {
        if (scd40_read_register(REG_MEAS_STATUS, &status) != 0)
            return -1;
        if (status & MEAS_STATUS_MEAS_READY)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if (!(status & MEAS_STATUS_MEAS_READY)) {
        fprintf(stderr, "[ERROR] SCD40 measurement not ready after reset\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Store a reading in the circular buffer                             */
/* ------------------------------------------------------------------ */
static void store_reading(int co2, float temperature, float humidity)
{
    time(&g_buffer[g_buffer_index].timestamp);
    g_buffer[g_buffer_index].co2      = co2;
    g_buffer[g_buffer_index].temperature = temperature;
    g_buffer[g_buffer_index].humidity    = humidity;

    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;
}

/* ------------------------------------------------------------------ */
/* Print a reading to stdout                                           */
/* ------------------------------------------------------------------ */
static void print_reading(int co2, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char time_str[32];

    localtime_r(&now, &tm_info);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s] CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n",
           time_str, co2, temperature, humidity);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_write_command(CMD_STOP_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed on bus %d addr 0x%02X (err=%d)\n",
                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (scd40_init() != 0) {
        fprintf(stderr, "[FATAL] SCD40 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 CO2 Monitor started. Press Ctrl+C to exit.\n");
    printf("Threshold: %d ppm, LED on GPIO%d\n", CO2_THRESHOLD, LED_GPIO);

    /* Main sampling loop */
    while (g_running) {
        uint32_t co2;
        float temperature, humidity;

        if (scd40_read_measurement(&co2, &temperature, &humidity) == 0) {
            store_reading((int)co2, temperature, humidity);
            print_reading((int)co2, temperature, humidity);

            if (co2 > CO2_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
                printf("[ALERT] CO2 level above threshold (%d ppm)!\n", CO2_THRESHOLD);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing...\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

