#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000
#define TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_error(const char *message) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

static int log_temperature(float temperature) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file);
    return 0;
}

static int log_malfunction(void) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s SENSOR MALFUNCTION\n", timestamp);
    fflush(log_file);
    return 0;
}

static int read_temperature(float *temperature) {
    uint32_t start_tick, end_tick;
    int level;

    /* Wait for the sensor to go HIGH (start of PWM cycle) */
    level = gpioRead(GPIO_PIN);
    if (level < 0) {
        log_error("Failed to read GPIO level");
        return -1;
    }
    if (level == 0) {
        gpioDelay(TIMEOUT_US);
        level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_error("Failed to read GPIO level after timeout");
            return -1;
        }
        if (level == 0) {
            log_error("Sensor not responding (LOW at start)");
            return -1;
        }
    }

    start_tick = gpioTick();
    while (running) {
        level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_error("Failed to read GPIO level during pulse");
            return -1;
        }
        if (level == 1) break;
        end_tick = gpioTick();
        if ((end_tick - start_tick) > TIMEOUT_US) {
            log_error("Timeout waiting for HIGH pulse");
            return -1;
        }
        gpioDelay(100);
    }

    if (!running) return -1;

    /* Measure HIGH pulse width */
    start_tick = gpioTick();
    while (running) {
        level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_error("Failed to read GPIO level during pulse");
            return -1;
        }
        if (level == 0) break;
        end_tick = gpioTick();
        if ((end_tick - start_tick) > TIMEOUT_US) {
            log_error("Timeout waiting for LOW pulse");
            return -1;
        }
        gpioDelay(100);
    }

    if (!running) return -1;

    end_tick = gpioTick();
    uint32_t pulse_width = end_tick - start_tick;

    /* Convert pulse width to temperature (TMP05 datasheet: 0.01 °C/µs) */
    *temperature = (float)pulse_width * 0.01f;

    /* Validate temperature range */
    if (*temperature < -40.0f || *temperature > 150.0f) {
        log_error("Temperature out of range");
        return -1;
    }

    return 0;
}

int main(void) {
    float temperature;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin as input */
    gpioSetMode(GPIO_PIN, PI_INPUT);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(&temperature) == 0) {
            consecutive_errors = 0;
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_malfunction();
                consecutive_errors = 0;
            }
        }

        /* Sleep in small increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

