/*
 * SDP810-125Pa Differential Pressure Sensor Logger for Raspberry Pi 3 Model B+
 * Uses the standard Linux I2C ioctl interface (no wiringPi dependency).
 *
 * Wiring:
 *   SDP810 SDA -> GPIO2 (I2C bus 1 SDA)
 *   SDP810 SCL -> GPIO3 (I2C bus 1 SCL)
 *   SDP810 VDD -> 3.3 V
 *   SDP810 GND -> GND
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x48
#define LOG_FILE       "airflow.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_DELAY_US  45000      /* 45 ms conversion time */

/* SDP810 continuous measurement command (no clock stretching) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x20};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t n = write(fd, cmd, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s (wrote %zd of %zu bytes)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s (read %zd of %zu bytes)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp810(int fd, float *pressure, float *temperature)
{
    uint8_t data[9];

    /* Send continuous measurement command */
    if (i2c_write_cmd(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) < 0)
        return -1;

    /* Wait for conversion to complete */
    usleep(CONV_DELAY_US);

    /* Read 9 bytes: pressure(2) + CRC, temperature(2) + CRC, scale(1) + CRC */
    if (i2c_read_block(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRCs */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 1) != data[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    /* Parse raw values (big-endian) */
    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    uint8_t scale_factor = data[6];

    /* Convert to physical units (sensor-specified formulas) */
    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
            if (log_data(pressure, temperature) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

