/*
 * SHT35-DIS-B Temperature & Humidity Logger for Raspberry Pi Zero W
 *
 * Reads temperature and humidity from a Sensirion SHT35-DIS-B sensor
 * on I2C bus 1 (GPIO2=SDA, GPIO3=SCL) using the single-shot, high-repeatability
 * measurement command with clock stretching disabled.  Sampling every 5 s.
 *
 * Build:  gcc -O2 -Wall -o sht35_logger sht35_logger.c -lsht35
 * Run:    sudo ./sht35_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44          /* SHT35-DIS-B default I2C address */
#define MEASURE_CMD    0x2406        /* Single-shot, high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 15000       /* 15 ms max conversion time */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHT35-DIS-B                       */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC at byte 2) */
    if (sht35_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC at byte 5) */
    if (sht35_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

