    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("SHT35-DIS-B logger started.  Bus=%d, addr=0x%02X, interval=%d s\n",
           I2C_BUS, SHT35_ADDR, SAMPLE_INTERVAL_S);
    printf("Logging to %s.  Press Ctrl+C to stop.\n", CSV_FILENAME);

