/*
 * Si7021 Greenhouse Monitor — Raspberry Pi Zero W
 *
 * Reads temperature and humidity from an Adafruit Si7021 sensor on I2C bus 1
 * (GPIO2/3), polls each measurement until data is available or a 100 ms
 * timeout expires, reads three bytes (MSB, LSB, CRC) for each value, and
 * verifies the CRC-8 checksum with the documented polynomial and initial
 * value.  Logs a CSV line every 5 seconds to environment.log with a
 * header "timestamp,temperature_C,humidity_percent".  Handles I2C errors,
 * sensor absent, and sensor reset, and exits gracefully on SIGINT/SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c
 * Run:    sudo ./greenhouse
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x44          /* Si7021 default I2C address */
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

/* Si7021 commands */
#define CMD_MEASURE_TEMP_HOLD  0xE3
#define CMD_MEASURE_HUM_HOLD   0xE5
#define CMD_RESET             0xFE

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00, no final XOR) — Si7021 spec      */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[ERROR] I2C read failed: got %zd of %zu bytes (%s)\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int si7021_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);  /* 15 ms reset settling time */
    return 0;
}

static int si7021_read_measurement(int fd, uint16_t *raw_out)
{
    uint8_t buf[3];

    /* Trigger measurement */
    if (i2c_write_cmd(fd, CMD_MEASURE_TEMP_HOLD) < 0)
        return -1;
    if (i2c_write_cmd(fd, CMD_MEASURE_HUM_HOLD) < 0)
        return -1;

    /* Poll until data is ready (max ~12.5 ms for humidity, ~18.75 ms for temp) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;
        if (crc8(buf, 2) == buf[2])
            break;
        usleep(1000);
    }
    if (i >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "[ERROR] Measurement timeout (no data ready)\n");
        return -1;
    }

    *raw_out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int si7021_read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (si7021_read_measurement(fd, &raw) < 0)
        return -1;
    *temp_c = -45.0f + 175.0f * (float)raw / 65536.0f;
    return 0;
}

static int si7021_read_humidity(int fd, float *hum_pct)
{
    uint16_t raw;
    if (si7021_read_measurement(fd, &raw) < 0)
        return -1;
    *hum_pct = 100.0f * (float)raw / 65536.0f;
    if (*hum_pct < 0.0f)   *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temp_c, float hum_pct)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct) < 0) {
        fprintf(stderr, "[ERROR] fprintf to %s failed: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose on %s failed: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Reset sensor */
    if (si7021_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "[ERROR] Si7021 reset failed — sensor may be absent or bus error\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    FILE *check = fopen(LOG_FILE, "r");
    if (!check) {
        check = fopen(LOG_FILE, "w");
        if (check) {
            fprintf(check, "timestamp,temperature_C,humidity_percent\n");
            fclose(check);
        }
    } else {
        fclose(check);
    }

    printf("Greenhouse monitor started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c = 0.0f, hum_pct = 0.0f;
        int ok = 1;

        if (si7021_read_temperature(g_i2c_fd, &temp_c) < 0) {
            fprintf(stderr, "[WARN] Temperature read failed — resetting sensor\n");
            if (si7021_reset(g_i2c_fd) < 0)
                fprintf(stderr, "[ERROR] Sensor reset failed; will retry next cycle\n");
            ok = 0;
        }

        if (ok && si7021_read_humidity(g_i2c_fd, &hum_pct) < 0) {
            fprintf(stderr, "[WARN] Humidity read failed — resetting sensor\n");
            if (si7021_reset(g_i2c_fd) < 0)
                fprintf(stderr, "[ERROR] Sensor reset failed; will retry next cycle\n");
            ok = 0;
        }

        if (ok) {
            if (log_data(LOG_FILE, temp_c, hum_pct) < 0)
                fprintf(stderr, "[WARN] Logging failed — will retry next cycle\n");
            else
                printf("Logged: T=%.2f C  H=%.2f %%\n", temp_c, hum_pct);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

