#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x48
#define MEASURE_CMD_MSB 0x14
#define MEASURE_CMD_LSB 0x00
#define CONVERSION_DELAY_US 100000
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "airflow.dat"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SDP810_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C device\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading sensor data: expected 9 bytes, got %d\n", bytes_read);
        return -1;
    }
    return 0;
}

static int validate_crc(const uint8_t *data, int len) {
    uint8_t calculated_crc = crc8(data, len - 1);
    if (calculated_crc != data[len - 1]) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", calculated_crc, data[len - 1]);
        return -1;
    }
    return 0;
}

static float convert_pressure(const uint8_t *data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    return (float)raw_pressure * 0.0625f;
}

static float convert_temperature(const uint8_t *data) {
    int16_t raw_temperature = (data[3] << 8) | data[4];
    return (float)raw_temperature * 0.0625f - 40.0f;
}

static int log_data(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing pressure to log file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing temperature to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP810-500Pa airflow monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint8_t data[9];
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor read failed, retrying in 1 second...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "CRC validation failed, retrying in 1 second...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float pressure = convert_pressure(data);
        float temperature = convert_temperature(data);

        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

