/*
 * Raspberry Pi 3 Model B+ - Sensirion SDP800-500Pa Differential Pressure Sensor
 *
 * Reads differential pressure from the SDP800-500Pa sensor over I2C bus 1
 * using the documented continuous measurement command, waits for the
 * conversion time, then reads the 9-byte response (3 data words each
 * followed by a CRC-8 byte), validates each CRC-8, and logs the
 * pressure reading with a timestamp to pressure_log.txt every 5 seconds.
 *
 * Wiring:
 *   SDP800 SDA -> GPIO2 (I2C bus 1 SDA)
 *   SDP800 SCL -> GPIO3 (I2C bus 1 SCL)
 *   SDP800 VDD -> 3.3V
 *   SDP800 GND -> GND
 *
 * Build: gcc -O2 -Wall -o sdp800_logger sdp800_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x48
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_TIME_US   45000      /* 45 ms conversion time (datasheet) */

/* Continuous measurement command (0x06) */
static const uint8_t CMD_CONT_MEAS[2] = {0x06, 0x00};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion polynomial 0x31, init 0xFF)            */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read pressure from the SDP800 sensor                                */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_sdp800(float *pressure)
{
    uint8_t buf[9];
    int16_t raw_pressure;
    int16_t raw_temperature;
    int16_t raw_humidity;

    /* Send continuous measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to send continuous measurement command: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_TIME_US);

    /* Read 9 bytes: 3 pressure words + 3 temperature words + 3 humidity words */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] Failed to read 9 bytes from SDP800: %s\n",
                strerror(errno));
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /* Combine bytes into signed 16-bit integers */
    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    raw_humidity    = (int16_t)((buf[6] << 8) | buf[7]);

    /* Convert raw values to physical units (datasheet formulas) */
    *pressure = (float)raw_pressure * 0.001f;   /* Pa */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log pressure reading with timestamp to file                          */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, %.2f Pa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "[ERROR] Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to SDP800 */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, SDP800_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("SDP800 logger started. Logging to '%s' every %d seconds.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float pressure;

        if (read_sdp800(&pressure) == 0) {
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("SDP800 logger stopped.\n");

    return EXIT_SUCCESS;
}

