#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LPS33HW_ADDR 0x5D
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lps33hw(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1 (0x20).\n");
        return -1;
    }
    if (i2cWriteByteData(handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG2 (0x21).\n");
        return -1;
    }
    return 0;
}

static int read_pressure_temperature(int handle, float *pressure, float *temperature) {
    char buffer[6];
    int16_t raw_pressure, raw_temperature;

    if (i2cReadI2CBlockData(handle, PRESS_OUT_XL, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read pressure and temperature data.\n");
        return -1;
    }

    raw_pressure = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_temperature = (int16_t)((buffer[3] << 8) | buffer[2]);

    *pressure = (float)raw_pressure / 4096.0f;
    *temperature = (float)raw_temperature / 4096.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, pressure, temperature);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n",
                LPS33HW_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lps33hw(i2c_handle) < 0) {
        fprintf(stderr, "Error: LPS33HW initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
