#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STLM75_ADDR    0x48
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from STLM75.                                     */
/* Returns 0 on success and stores temperature in *temp_c.            */
/* Returns -1 on I2C error.                                            */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temp_c)
{
    char buf[2];
    int  rc;

    /*
     * STLM75: write 0x00 to the register pointer to read the
     * temperature register.  The sensor returns two bytes: MSB first.
     */
    rc = i2cWriteByte(handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByte failed (rc=%d)\n", rc);
        return -1;
    }

    /* Small delay so the sensor has time to prepare the response. */
    gpioDelay(1000);  /* 1 ms */

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);

    /*
     * STLM75: 12-bit two’s complement, left-justified in 16 bits.
     * Sign-extend from 12 bits to 16 bits.
     */
    if (raw & 0x0800) {
        raw |= 0xF000;
    }

    *temp_c = (float)raw / 16.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a temperature reading to the circular buffer.               */
/* ------------------------------------------------------------------ */
static void buffer_add(float temp_c, float buffer[], int *index, int *count)
{
    buffer[*index] = temp_c;
    *index = (*index + 1) % BUFFER_SIZE;
    if (*count < BUFFER_SIZE) {
        *count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute the running average of the temperature readings.          */
/* ------------------------------------------------------------------ */
static float buffer_average(const float buffer[], int count)
{
    if (count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < count; i++) {
        sum += buffer[i];
    }
    return sum / (float)count;
}

/* ------------------------------------------------------------------ */
/* Control the LED based on the average temperature.                    */
/* ------------------------------------------------------------------ */
static void control_led(float avg_temp)
{
    int level = (avg_temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n",
                LED_GPIO, level);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if pigpio is not initialized.    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float temperature_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    int   buffer_count = 0;
    float avg_temp;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                I2C_BUS, STLM75_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("STLM75 temperature monitor started.\n");
    printf("  I2C bus: %d  Address: 0x%02X  LED GPIO: %d\n",
           I2C_BUS, STLM75_ADDR, LED_GPIO);
    printf("  Threshold: %.1f °C  Polling: 1 s\n", TEMP_THRESHOLD);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        float temp_c;

        if (read_temperature(g_i2c_handle, &temp_c) == 0) {
            buffer_add(temp_c, temperature_buffer, &buffer_index, &buffer_count);
            avg_temp = buffer_average(temperature_buffer, buffer_count);
            control_led(avg_temp);
            printf("Temperature: %.2f °C  Average: %.2f °C\n",
                   temp_c, avg_temp);
        } else {
            fprintf(stderr, "Warning: temperature read failed; skipping cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(POLL_DELAY_US / 10);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

