code:
/*
 * SCD30 CO2, Temperature, Humidity Monitor for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SCD30 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   SCD30 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   SCD30 VDD -> 3.3V
 *   SCD30 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o scd30_monitor scd30_monitor.c -lpigpio -lrt
 * Run:   sudo ./scd30_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SCD30_ADDR     0x60
#define LOG_FILE       "air_quality.log"
#define SAMPLE_INTERVAL 5          /* seconds */
#define MEASUREMENT_DELAY_US 100000 /* 100 ms */

/* SCD30 Commands */
#define CMD_START_MEASUREMENT 0x36
#define CMD_READ_MEASUREMENT  0x2C
#define CMD_RESET            0xFE

/* SCD30 Registers */
#define REG_MEAS_STATUS     0x00
#define REG_MEAS_DATA      0x02
#define REG_RESET_STATUS    0x03

/* SCD30 Measurement Status Bits */
#define MEAS_DATA_READY    0x01
#define MEAS_MEAS_ERROR    0x02

/* SCD30 Reset Status Bits */
#define RESET_RESET_DONE   0x01

/* CO2 Ranges (ppm) */
#define CO2_LOW_THRESHOLD  800
#define CO2_HIGH_THRESHOLD 1200

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int  scd30_init(void);
static int  scd30_start_measurement(void);
static int  scd30_read_measurement(uint16_t *co2, float *temperature, float *humidity);
static int  scd30_reset(void);
static int  scd30_check_status(void);
static int  scd30_get_co2(uint16_t *co2);
static int  scd30_get_temperature(float *temperature);
static int  scd30_get_humidity(float *humidity);
static int  log_data(uint16_t co2, float temperature, float humidity);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Initializes the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_init(void) {
    /* Send reset command */
    if (i2cWriteByte(i2c_handle, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to send reset command to SCD30.\n");
        return -1;
    }

    /* Wait for reset to complete (max 100 ms) */
    gpioDelay(100000);

    /* Check reset status */
    int reset_status = i2cReadByteData(i2c_handle, REG_RESET_STATUS);
    if (reset_status < 0) {
        fprintf(stderr, "Error: Failed to read reset status from SCD30.\n");
        return -1;
    }

    if (!(reset_status & RESET_RESET_DONE)) {
        fprintf(stderr, "Error: SCD30 reset did not complete.\n");
        return -1;
    }

    return 0;
}

/*
 * Starts a measurement on the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_start_measurement(void) {
    if (i2cWriteByte(i2c_handle, CMD_START_MEASUREMENT) < 0) {
        fprintf(stderr, "Error: Failed to start measurement on SCD30.\n");
        return -1;
    }

    return 0;
}

/*
 * Reads measurement data from the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    char buffer[9];
    int bytes_read;

    /* Read 9 bytes: status, temperature, humidity, reserved, reserved */
    bytes_read = i2cReadI2CBlockData(i2c_handle, REG_MEAS_DATA, buffer, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error: Failed to read measurement data from SCD30 (read %d bytes).\n", bytes_read);
        return -1;
    }

    /* Check measurement status */
    int status = (buffer[0] << 8) | buffer[1];
    if (status & MEAS_MEAS_ERROR) {
        fprintf(stderr, "Error: Measurement error detected (status=0x%02X).\n", status);
        return -1;
    }
    if (!(status & MEAS_DATA_READY)) {
        fprintf(stderr, "Error: Measurement data not ready (status=0x%02X).\n", status);
        return -1;
    }

    /* Extract CO2 data (2 bytes, big-endian) */
    *co2 = ((uint16_t)(buffer[2] << 8)) | (uint8_t)buffer[3];

    /* Extract temperature data (2 bytes, big-endian) */
    int16_t temp_raw = ((int16_t)(buffer[4] << 8)) | (int8_t)buffer[5];
    *temperature = (float)temp_raw / 100.0f;

    /* Extract humidity data (2 bytes, big-endian) */
    int16_t humidity_raw = ((int16_t)(buffer[6] << 8)) | (int8_t)buffer[7];
    *humidity = (float)humidity_raw / 100.0f;

    return 0;
}

/*
 * Resets the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_reset(void) {
    if (i2cWriteByte(i2c_handle, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to send reset command to SCD30.\n");
        return -1;
    }

    gpioDelay(100000); /* Wait for reset to complete */

    int reset_status = i2cReadByteData(i2c_handle, REG_RESET_STATUS);
    if (reset_status < 0) {
        fprintf(stderr, "Error: Failed to read reset status from SCD30.\n");
        return -1;
    }

    if (!(reset_status & RESET_RESET_DONE)) {
        fprintf(stderr, "Error: SCD30 reset did not complete.\n");
        return -1;
    }

    return 0;
}

/*
 * Checks the measurement status of the SCD30 sensor.
 * Returns 0 if data is ready, -1 if an error occurred, 1 if data is not ready.
 */
static int scd30_check_status(void) {
    int status = i2cReadByteData(i2c_handle, REG_MEAS_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read measurement status from SCD30.\n");
        return -1;
    }

    if (status & MEAS_MEAS_ERROR) {
        fprintf(stderr, "Error: Measurement error detected (status=0x%02X).\n", status);
        return -1;
    }

    if (status & MEAS_DATA_READY) {
        return 0;
    }

    return 1;
}

/*
 * Gets the CO2 value from the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_get_co2(uint16_t *co2) {
    if (scd30_check_status() != 0) {
        return -1;
    }

    if (scd30_read_measurement(co2, NULL, NULL) != 0) {
        return -1;
    }

    return 0;
}

/*
 * Gets the temperature value from the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_get_temperature(float *temperature) {
    if (scd30_check_status() != 0) {
        return -1;
    }

    if (scd30_read_measurement(NULL, temperature, NULL) != 0) {
        return -1;
    }

    return 0;
}

/*
 * Gets the humidity value from the SCD30 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int scd30_get_humidity(float *humidity) {
    if (scd30_check_status() != 0) {
        return -1;
    }

    if (scd30_read_measurement(NULL, NULL, humidity) != 0) {
        return -1;
    }

    return 0;
}

/*
 * Logs the CO2, temperature, and humidity data to a file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(uint16_t co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get current time.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }

    return 0;
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/*
 * Cleans up resources before exiting.
 */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 0; /* Exit gracefully with return code 0 */
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C connection to SCD30 (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 0; /* Exit gracefully with return code 0 */
    }

    /* Initialize SCD30 sensor */
    if (scd30_init() != 0) {
        fprintf(stderr, "Error: SCD30 initialisation failed.\n");
        cleanup();
        return 0; /* Exit gracefully with return code 0 */
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 0; /* Exit gracefully with return code 0 */
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler.\n");
    }

    printf("SCD30 CO2 Monitor started. Logging to '%s' every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t co2;
        float temperature, humidity;

        /* Start measurement */
        if (scd30_start_measurement() != 0) {
            fprintf(stderr, "Warning: Failed to start measurement, retrying...\n");
            gpioDelay(MEASUREMENT_DELAY_US);
            continue;
        }

        /* Wait for measurement to complete */
        gpioDelay(MEASUREMENT_DELAY_US);

        /* Read data */
        if (scd30_get_co2(&co2) != 0) {
            fprintf(stderr, "Warning: Failed to read CO2 data, retrying...\n");
            continue;
        }

        if (scd30_get_temperature(&temperature) != 0) {
            fprintf(stderr, "Warning: Failed to read temperature data, retrying...\n");
            continue;
        }

        if (scd30_get_humidity(&humidity) != 0) {
            fprintf(stderr, "Warning: Failed to read humidity data, retrying...\n");
            continue;
        }

        /* Log data */
        if (log_data(co2, temperature, humidity) != 0) {
            fprintf(stderr, "Warning: Failed to log data, retrying...\n");
        }

        /* Ventilation control logic */
        if (co2 < CO2_LOW_THRESHOLD) {
            printf("CO2: %u ppm | Temperature: %.2f °C | Humidity: %.2f %%RH | Ventilation: OFF\n", co2, temperature, humidity);
        } else if (co2 < CO2_HIGH_THRESHOLD) {
            printf("CO2: %u ppm | Temperature: %.2f °C | Humidity: %.2f %%RH | Ventilation: LOW\n", co2, temperature, humidity);
        } else {
            printf("CO2: %u ppm | Temperature: %.2f °C | Humidity: %.2f %%RH | Ventilation: HIGH\n", co2, temperature, humidity);
        }

        /* Wait for next sample */
        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

