/*
 * SDP810-125Pa Differential Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM)
 *   SDP810 SCL  -> GPIO3 (BCM)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o sdp810_reader sdp810_reader.c -lgpiod -lm
 *
 * Run:
 *   ./sdp810_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x48
#define READ_INTERVAL  1          /* seconds between readings */
#define CONV_DELAY_US  45000      /* 45 ms conversion time */

/* SDP810 register addresses */
#define REG_MEASURE    0x00
#define REG_DATA       0x01
#define REG_SCALE_P    0x02
#define REG_SCALE_T    0x03
#define REG_CRC_P      0x04
#define REG_CRC_T      0x05
#define REG_CONFIG     0x06

/* Configuration register bits */
#define CFG_MEAS_TRIG  0x01
#define CFG_MEAS_MODE  0x02
#define CFG_MEAS_PRS   0x04
#define CFG_MEAS_T     0x08
#define CFG_MEAS_AUTO  0x10
#define CFG_MEAS_TRIG_P 0x20
#define CFG_MEAS_TRIG_T 0x40

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion polynomial 0x31, init 0xFF)            */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an SDP810 register                          */
/* ------------------------------------------------------------------ */
static int sdp810_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an SDP810 register                          */
/* ------------------------------------------------------------------ */
static int sdp810_read_reg(uint8_t reg, uint8_t *value)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes of measurement data (pressure, temperature, scale factors)*/
/* ------------------------------------------------------------------ */
static int sdp810_read_measurement(int16_t *pressure, int16_t *temperature,
                                  int16_t *scale_p, int16_t *scale_t)
{
    uint8_t data[9];

    if (sdp810_read_reg(REG_DATA, data) != 0)
        return -1;

    /* Validate CRC for pressure (bytes 0-1, CRC at byte 2) */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC at byte 5) */
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    /* Assemble signed 16-bit values */
    *pressure    = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (int16_t)((data[3] << 8) | data[4]);
    *scale_p     = (int16_t)((data[6] << 8) | data[7]);
    *scale_t     = (int16_t)((data[8] << 8) | data[9]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the result                          */
/* ------------------------------------------------------------------ */
static int sdp810_trigger_and_read(int16_t *pressure, int16_t *temperature,
                                  int16_t *scale_p, int16_t *scale_t)
{
    /* Trigger measurement by writing the MEASURE register */
    if (sdp810_write_reg(REG_MEASURE, CFG_MEAS_TRIG) != 0)
        return -1;

    /* Wait for conversion to complete */
    usleep(CONV_DELAY_US);

    return sdp810_read_measurement(pressure, temperature, scale_p, scale_t);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the SDP810 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access at 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading the CONFIG register */
    uint8_t config = 0;
    if (sdp810_read_reg(REG_CONFIG, &config) != 0) {
        fprintf(stderr, "SDP810 not responding at address 0x%02X\n", SDP810_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP810 detected (CONFIG=0x%02X)\n", config);
    printf("Reading differential pressure and temperature every %d seconds...\n",
           READ_INTERVAL);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        int16_t pressure, temperature, scale_p, scale_t;

        if (sdp810_trigger_and_read(&pressure, &temperature, &scale_p, &scale_t) == 0) {
            /* Convert raw values to physical units */
            double pressure_pa   = (double)pressure    * (double)scale_p;
            double temperature_c = (double)temperature * (double)scale_t / 100.0;

            /* Sanity-check scale factors (should not be zero) */
            if (scale_p == 0 || scale_t == 0) {
                fprintf(stderr, "Invalid scale factors (P=%d, T=%d)\n", scale_p, scale_t);
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                       pressure_pa, temperature_c);
            }
        } else {
            fprintf(stderr, "Failed to read measurement data\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

