#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_HUMID_REG   0x02
#define HDC1000_CONFIG_REG  0x01
#define HDC1000_MEAS_DELAY_MS 20
#define LOOP_DELAY_S        5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_init(int fd) {
    /*
     * Config register:
     *   Bit 15: DRDYn (data ready pin) active low
     *   Bits 14:12: TRES (temperature resolution) = 14-bit
     *   Bits 11:9:  HRES (humidity resolution)  = 14-bit
     *   Bit 8:    MODE (measurement mode) = 1 (continuous)
     *   Bits 7:5:  TCONV (temperature conversion time) = 001 (14.75 ms)
     *   Bits 4:2:  HCONV (humidity conversion time) = 001 (14.75 ms)
     *   Bit 1:    HEATER (heater on) = 0
     *   Bit 0:    RESET (reset) = 0
     * Result: 0x0000
     */
    if (i2c_write_reg8(fd, HDC1000_CONFIG_REG, 0x00) < 0) {
        return -1;
    }
    usleep(10000); /* 10 ms settle */
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;

    /* Trigger a 14-bit temperature and humidity conversion */
    if (i2c_write_reg8(fd, HDC1000_CONFIG_REG, 0x00) < 0) {
        return -1;
    }
    usleep(HDC1000_MEAS_DELAY_MS * 1000);

    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_temp) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, HDC1000_HUMID_REG, &raw_hum) < 0) {
        return -1;
    }

    /*
     * HDC1000 conversion formulas (14-bit resolution):
     *   Temperature: T = (raw_temp * 0.0625) - 40.0
     *   Humidity:    H = (raw_hum  * 0.0625) - 6.0
     */
    *temperature = ((float)raw_temp * 0.0625f) - 40.0f;
    *humidity    = ((float)raw_hum  * 0.0625f) - 6.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_i2c_fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized. Logging every %d seconds. Press Ctrl+C to exit.\n",
           LOOP_DELAY_S);

    while (g_running) {
        float temperature, humidity;

        if (hdc1000_read(g_i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < LOOP_DELAY_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

