        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: expected %zu bytes, got %zd: %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    if (i2c_write_byte(fd, TEMP_CMD) < 0) {
        return -1;
    }

    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = -45.0f + (175.0f * (float)raw / 65536.0f);
    return 0;
}

