/*
 * Raspberry Pi Zero W – TDK ICP-10101 Barometric Pressure Sensor
 *
 * Reads temperature and pressure every 5 seconds.  I2C bus 1, address 0x76.
 *
 * Build:  gcc -O2 -Wall -o icp10101 icp10101.c -lgpiod -lm
 * Run:    sudo ./icp10101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10101_ADDR  0x76

/*
 * ICP-10101 register addresses (from datasheet).
 * The sensor sends a 2-byte command word before each read.
 */
#define REG_MEASURE    0x00
#define REG_TEMP_MSB   0x01
#define REG_TEMP_LSB   0x02
#define REG_PRESS_MSB  0x03
#define REG_PRESS_LSB  0x04
#define REG_PRESS_XLSB 0x05

/*
 * Measurement command: 0x0000 (no averaging, no clock stretching).
 * The sensor returns 3 bytes: MSB, LSB, XLSB.
 */
#define MEASURE_CMD    0x0000

#define MEASURE_DELAY_US 7000   /* 7 ms measurement conversion time */
#define LOOP_DELAY_S     5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command word to the sensor.                         */
/* Returns 0 on success, -1 on error.                                 */
static int icp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes from the sensor.                                        */
/* Returns 0 on success, -1 on error.                                 */
static int icp_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the 3-byte result.                    */
/* Returns 0 on success and fills *temp_c and *press_pa.             */
/* Returns -1 on error.                                              */
static int icp_read_measurement(int fd, float *temp_c, float *press_pa)
{
    uint8_t data[3];

    if (icp_write_cmd(fd, MEASURE_CMD) != 0)
        return -1;

    usleep(MEASURE_DELAY_US);

    if (icp_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /*
     * The sensor returns 3 bytes: MSB, LSB, XLSB.
     * The 24-bit value is assembled from the 24-bit two's complement
     * in the 24-bit register.
     */
    uint32_t raw = ((uint32_t)data[0] << 16) |
                   ((uint32_t)data[1] <<  8) |
                   ((uint32_t)data[2]);

    /* Sign-extend the 24-bit value to 32 bits. */
    if (raw & 0x00800000)
        raw |= 0xFF000000;

    /* Temperature: 14-bit signed, 0.0625 °C per LSB. */
    int16_t temp_raw = (int16_t)(raw >> 18);
    *temp_c = (float)temp_raw * 0.0625f;

    /* Pressure: 16-bit signed, 0.0625 Pa per LSB. */
    int16_t press_raw = (int16_t)(raw >> 4);
    *press_pa = (float)press_raw * 0.0625f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s ", ts);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ICP10101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10101 sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, ICP10101_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float temp_c, press_pa;

        if (icp_read_measurement(g_i2c_fd, &temp_c, &press_pa) == 0) {
            print_timestamp();
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n",
                   temp_c, press_pa);
            fflush(stdout);
        } else {
            print_timestamp();
            fprintf(stderr, "Sensor read failed; sensor may be absent or "
                            "bus error.\n");
            fflush(stderr);
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < LOOP_DELAY_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

