#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x48
#define MEASURE_CMD 0x14
#define READ_CMD 0x2C
#define LOG_FILE "pressure_log.txt"
#define MEASURE_DELAY_MS 45
#define READ_DELAY_MS 10
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t cmd) {
    uint8_t buf[1] = {cmd};
    if (write(i2c_fd, buf, 1) != 1) {
        perror("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n != (ssize_t)len) {
        if (n < 0) {
            perror("I2C read failed");
        } else {
            fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        }
        return -1;
    }
    return 0;
}

static int read_sdp800(float *pressure, float *temperature) {
    uint8_t cmd = READ_CMD;
    uint8_t buf[9];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(cmd) < 0) {
            retries++;
            usleep(10000);
            continue;
        }

        usleep(READ_DELAY_MS * 1000);

        if (i2c_read_bytes(buf, sizeof(buf)) < 0) {
            retries++;
            usleep(10000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on pressure word\n");
            retries++;
            usleep(10000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch on temperature word\n");
            retries++;
            usleep(10000);
            continue;
        }
        if (crc8(&buf[6], 2) != buf[8]) {
            fprintf(stderr, "CRC mismatch on differential pressure word\n");
            retries++;
            usleep(10000);
            continue;
        }

        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
        int16_t raw_dp = (int16_t)((buf[6] << 8) | buf[7]);

        *pressure = (float)raw_pressure / 64.0f;
        *temperature = (float)raw_temperature / 16.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SDP800 after %d retries\n", MAX_RETRIES);
    return -1;
}

static int log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("SDP800 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;

        if (read_sdp800(&pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            if (log_data(pressure, temperature) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(MEASURE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

