#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x48
#define LOG_FILE "airflow_log.csv"
#define MEASUREMENT_DELAY_MS 8
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_byte(uint8_t byte) {
    if (write(i2c_fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len) {
    ssize_t bytes_read = read(i2c_fd, buf, len);
    if (bytes_read != (ssize_t)len) {
        fprintf(stderr, "I2C read error: expected %zu bytes, got %zd: %s\n",
                len, bytes_read, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sdp800(float *pressure) {
    uint8_t cmd = 0x36;
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(cmd) != 0) {
            retries++;
            usleep(10000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2c_read_bytes(buf, 3) != 0) {
            retries++;
            usleep(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on measurement\n");
            retries++;
            usleep(10000);
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *pressure = (float)raw / 65536.0f * 500.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read SDP800 after %d retries\n", MAX_RETRIES);
    return -1;
}

static int log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int initialize_log_file(void) {
    int file_exists = (access(LOG_FILE, F_OK) == 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (!file_exists) {
        if (fprintf(log_file, "Timestamp,Pressure (Pa)\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
            fclose(log_file);
            log_file = NULL;
            return -1;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush header to log file: %s\n", strerror(errno));
            fclose(log_file);
            log_file = NULL;
            return -1;
        }
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    if (initialize_log_file() != 0) {
        cleanup();
        return 1;
    }

    printf("SDP800 airflow monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_sdp800(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            } else {
                printf("Pressure: %.2f Pa\n", pressure);
            }
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

