#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90821_ADDR  0x5A
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define PRESSURE_MIN   200.0f
#define PRESSURE_MAX   250.0f
#define SAMPLE_PERIOD  1.0
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MLX90821_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int16_t raw;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int bytes_read = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
        if (bytes_read == 2) {
            raw = (int16_t)((buf[0] << 8) | buf[1]);
            *pressure_out = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed: got %d bytes, expected 2\n",
                attempt + 1, bytes_read);
        if (attempt < MAX_RETRIES - 1) {
            time_sleep(0.1);
        }
    }
    return -1;
}

static int log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    float pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error writing header: %s\n", strerror(errno));
            fclose(g_log_file);
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_file) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            fclose(g_log_file);
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("MLX90821 pressure logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_pressure(&pressure) == 0) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Pressure: %.2f kPa\n", pressure);
            }

            if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
                fprintf(stderr,
                        "Warning: pressure %.2f kPa outside safe range [%.0f, %.0f] kPa\n",
                        pressure, PRESSURE_MIN, PRESSURE_MAX);
            }
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries; reinitialising I2C.\n",
                    MAX_RETRIES);
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Reinitialisation failed; exiting.\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

