/*
 * HIH6130 Temperature & Humidity Logger for Raspberry Pi Zero W
 *
 * Reads temperature and humidity from a Honeywell HIH6130 sensor on the I2C bus
 * (bus 1, address 0x27).  Logs data to environmental_data.log with ISO-8601 timestamps
 * and rolls the file when it exceeds 1MB.
 *
 * Build:  gcc -O2 -Wall -o hih6130_logger hih6130_logger.c
 * Run:    sudo ./hih6130_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x27
#define LOG_FILE       "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576  /* 1MB */
#define READ_INTERVAL  5        /* seconds */
#define TRIGGER_DELAY  40       /* microseconds */

/* HIH6130 register addresses */
#define REG_TEMP_MSB   0x00
#define REG_HUM_MSB    0x01
#define REG_MEAS_CFG   0x02
#define REG_MEAS_TRIG  0x03
#define REG_STATUS     0x04
#define REG_INT_CFG    0x05

/* Measurement configuration bits */
#define MEAS_TRIG_TEMP  0x01
#define MEAS_TRIG_HUM   0x02
#define MEAS_TRIG_BOTH  (MEAS_TRIG_TEMP | MEAS_TRIG_HUM)
#define MEAS_MODE_CONT  0x00
#define MEAS_MODE_ONE   0x01
#define MEAS_MODE_AUTO  0x02
#define MEAS_MODE_MASK  0x03
#define MEAS_TRIG_MASK  0x07

/* Status bits */
#define STATUS_MEAS_RDY 0x01
#define STATUS_INT_EN   0x02

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_hih6130(int fd)
{
    uint8_t status;

    /* Verify sensor presence by reading the status register */
    if (i2c_read_reg8(fd, REG_STATUS, &status) != 0) {
        fprintf(stderr, "Failed to read HIH6130 status register.\n");
        return -1;
    }

    /*
     * HIH6130 returns 0x00 when the sensor is not present or the
     * measurement is not ready.  A non-zero status indicates an error.
     */
    if (status == 0x00) {
        fprintf(stderr, "HIH6130 not responding at address 0x%02X.\n",
                HIH6130_ADDR);
        return -1;
    }

    /*
     * Clear any pending interrupts by writing 0x00 to the interrupt
     * configuration register.
     */
    if (i2c_write_reg8(fd, REG_INT_CFG, 0x00) != 0) {
        fprintf(stderr, "Failed to clear HIH6130 interrupt configuration.\n");
        return -1;
    }

    /*
     * Set measurement mode to continuous conversion.
     * Bits [1:0] = 00 (continuous).
     */
    if (i2c_write_reg8(fd, REG_MEAS_CFG, MEAS_MODE_CONT) != 0) {
        fprintf(stderr, "Failed to set HIH6130 measurement mode.\n");
        return -1;
    }

    /*
     * Trigger a single measurement of temperature and humidity.
     * Bits [2:0] = 001 (temperature + humidity).
     */
    if (i2c_write_reg8(fd, REG_MEAS_TRIG, MEAS_TRIG_BOTH) != 0) {
        fprintf(stderr, "Failed to trigger HIH6130 measurement.\n");
        return -1;
    }

    /* Allow the first measurement to complete */
    usleep(TRIGGER_DELAY);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                   */
/* ------------------------------------------------------------------ */
static int read_hih6130(int fd, float *temperature, float *humidity)
{
    uint8_t status;
    uint16_t raw_temp, raw_hum;

    /*
     * Poll the status register until the measurement is ready.
     * Bit 0 of the status register is set when a new measurement is
     * ready.
     */
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg8(fd, REG_STATUS, &status) != 0) {
            return -1;
        }
        if (status & STATUS_MEAS_RDY) {
            break;
