    if (i2c_read_reg16(fd, REG_TEMP_MSB, &raw_temp) != 0) {
        return -1;
    }

    /* Read humidity (2 bytes, MSB first) */
    if (i2c_read_reg16(fd, REG_HUM_MSB, &raw_hum) != 0) {
        return -1;
    }

    /*
     * Validate sensor status bits.
     * Bits [7:4] = 0000 (reserved).
     * Bit 3    = 0 (measurement not ready).
     * Bit 2    = 0 (no overflow).
     * Bit 1    = 0 (no error).
     * Bit 0    = 1 (measurement ready).
     */
    if ((status & 0x0F) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }

    /*
     * Convert raw values to physical units.
     * Temperature: 14-bit signed, LSB = 0.01 °C.
     * Humidity:    14-bit signed, LSB = 0.01 %RH.
     */
    *temperature = (float)raw_temp * 0.01f;
    *humidity    = (float)raw_hum  * 0.01f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
