    /* Synchronization pulse ends with a low pulse */
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < SYNC_TICKS * TICK_US || pulse_width > (SYNC_TICKS + 1) * TICK_US) {
        return -2;
    }

    /* Read 4 data bits */
    *nibble = 0;
    for (i = 0; i < 4; i++) {
        /* Wait for the start of the high pulse */
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                return -1;
            }
        }

        /* Measure the high pulse width */
        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;

        /* Validate pulse width */
        if (pulse_width < MIN_PULSE_TICKS * TICK_US || pulse_width > MAX_PULSE_TICKS * TICK_US) {
            return -2;
        }

        /* Set bit based on pulse width */
        if (pulse_width > (MIN_PULSE_TICKS + 1) * TICK_US) {
            *nibble |= (1 << i);
        }
    }

    return 0;
}

/*
 * Parse the 16-bit SENT nibble into a 16-bit pressure value.
 * Returns 0 on success, -1 on out-of-range pressure, -2 on checksum mismatch.
 */
static int parse_pressure(uint16_t nibble, int16_t *pressure) {
    uint16_t status = (nibble >> 12) & 0x0F;
    uint16_t data = (nibble >> 4) & 0x0FFF;
    uint16_t checksum = nibble & 0x0F;

    /* Validate status nibble */
    if (status > 0x0F) {
        return -1;
    }

    /* Validate data nibbles (12-bit range) */
    if (data > 0x0FFF) {
        return -1;
    }

    /* Validate checksum */
    uint16_t expected_checksum = (status << 8) | data;
    if (expected_checksum != checksum) {
        return -2;
    }

    /* Convert 12-bit data to 16-bit signed pressure */
    *pressure = (int16_t)((data << 4) | (nibble >> 8));
    return 0;
}

static void log_pressure(FILE *fp, int16_t pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, (double)pressure);
    fflush(fp);
}

int main(void) {
    int16_t pressure;
    uint16_t nibble;
    int error_count = 0;
    int reading_count = 0;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO4 as input */
    gpioSetMode(SENT_GPIO, PI_INPUT);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 SENT Pressure Sensor Reader\n");
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main loop */
    while (running) {
        int ret = read_sent_nibble(SENT_GPIO, &nibble);

        if (ret == 0) {
            if (parse_pressure(nibble, &pressure) == 0) {
                log_pressure(log_file, pressure);
                reading_count++;
                error_count = 0;
            } else {
                fprintf(stderr, "Error: Invalid pressure data (nibble: 0x%04X)\n", nibble);
                error_count++;
            }
        } else if (ret == -1) {
            fprintf(stderr, "Error: Timeout reading SENT data\n");
            error_count++;
        } else {
            fprintf(stderr, "Error: Bus error reading SENT data\n");
            error_count++;
        }

        /* Check for sensor absence or bus errors */
        if (error_count >= MAX_READINGS) {
            fprintf(stderr, "Error: Too many consecutive readings failed. Sensor may be absent or bus error.\n");
            break;
        }

        gpioDelay(100000); /* 100 ms delay between readings */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

