/*
 * Raspberry Pi Zero W – TMP117 High Precision Temperature Sensor Monitor
 *
 * Reads the greenhouse temperature from an Adafruit TMP117 on the I2C bus
 * (bus 1, address 0x48) and logs it to a binary file.
 *
 * Build:  gcc -O2 -Wall -o greenhouse_monitor greenhouse_monitor.c
 * Run:    sudo ./greenhouse_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define LOG_FILE       "greenhouse_temps.dat"
#define SAMPLE_PERIOD  60          /* seconds between readings */

/* TMP117 register addresses */
#define REG_TEMP_H     0x00
#define REG_TEMP_L     0x01
#define REG_CONFIG     0x02
#define REG_DEVICE_ID  0x0F

/* Expected device ID for TMP117 */
#define TMP117_DEVICE_ID 0x54

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 initialization                                               */
/* ------------------------------------------------------------------ */
static int tmp117_init(int fd)
{
    uint8_t device_id = 0;

    /* Verify device ID */
    if (i2c_read_reg8(fd, REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Failed to read TMP117 device ID.\n");
        return -1;
    }
    if (device_id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X).\n",
                device_id, TMP117_DEVICE_ID);
        return -1;
    }
    printf("TMP117 detected (device ID 0x%02X).\n", device_id);

    /*
     * Config register (0x02):
     *   Bits [7:6] = 10  -> TMP117 in high-precision mode
     *   Bits [5:4] = 00  -> 12-bit resolution
     *   Bit  [3]   = 0   -> Continuous conversion mode
     *   Bit  [2]   = 0   -> No alert
     *   Bit  [1]   = 0   -> No shutdown
     *   Bit  [0]   = 0   -> No reset
     * Value: 0x00
     */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to write TMP117 config register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature (Celsius)                                         */
/* ------------------------------------------------------------------ */
static int tmp117_read_temperature(int fd, float *temperature)
{
    uint16_t raw = 0;

    /*
     * Trigger a single-shot conversion by writing 0x00 to the
     * config register.  The TMP117 will latch the conversion result
     * into the temperature registers after the conversion is complete.
     */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to trigger TMP117 conversion.\n");
        return -1;
    }

    /* Wait for conversion to complete (~10 ms at 12-bit resolution) */
    usleep(15000);

    /* Read the 16-bit temperature register (high byte first) */
    if (i2c_read_reg16(fd, REG_TEMP_H, &raw) != 0) {
        fprintf(stderr, "Failed to read TMP117 temperature.\n");
        return -1;
    }

    /*
     * TMP117 outputs 12-bit data left-justified in 16 bits.
     * The 12-bit value is extracted from the lower 4 bits of the
     * high byte and the 12-bit value is sign-extended to 16 bits.
     */
    int16_t signed_raw = (int16_t)((raw & 0x0FFF) | ((raw & 0xF000) << 4));

    /*
     * TMP117 in high-precision mode:
     *   12-bit resolution -> 0.0625 °C per LSB
     *   16-bit signed value -> 0.0625 °C per LSB
     */
    *temperature = (float)signed_raw * 0.0625f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_temperature(FILE *fp, float temperature)
{
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to log file: %s\n",
                strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access at 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize TMP117 */
    if (tmp117_init(g_i2c_fd) != 0) {
        fprintf(stderr, "TMP117 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in binary append mode */
    g_log_fp = fopen(LOG_FILE, "ab");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse temperature monitoring started. Logging to '%s'.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temperature = 0.0f;

        if (tmp117_read_temperature(g_i2c_fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            if (log_temperature(g_log_fp, temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature; continuing.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

