#define TMP117_CONFIG_OS_16S 0x11
#define TMP117_CONFIG_OS_32S 0x12
#define TMP117_CONFIG_OS_64S 0x13
#define TMP117_CONFIG_OS_128S 0x14
#define TMP117_CONFIG_OS_256S 0x15
#define TMP117_CONFIG_OS_512S 0x16
#define TMP117_CONFIG_OS_1024S 0x17
#define TMP117_CONFIG_OS_2048S 0x18
#define TMP117_CONFIG_OS_4096S 0x19
#define TMP117_CONFIG_OS_8192S 0x1A
#define TMP117_CONFIG_OS_16384S 0x1B
#define TMP117_CONFIG_OS_32768S 0x1C
#define TMP117_CONFIG_OS_65536S 0x1D
#define TMP117_CONFIG_OS_131072S 0x1E
#define TMP117_CONFIG_OS_262144S 0x1F
#define TMP117_CONFIG_OS_524288S 0x20
#define TMP117_CONFIG_OS_1048576S 0x21
#define TMP117_CONFIG_OS_2097152S 0x22
#define TMP117_CONFIG_OS_4194304S 0x23
#define TMP117_CONFIG_OS_8388608S 0x24
#define TMP117_CONFIG_OS_16777216S 0x25
#define TMP117_CONFIG_OS_33554432S 0x26
#define TMP117_CONFIG_OS_67108864S 0x27
#define TMP117_CONFIG_OS_134217728S 0x28
#define TMP117_CONFIG_OS_268435456S 0x29
#define TMP117_CONFIG_OS_536870912S 0x2A
#define TMP117_CONFIG_OS_1073741824S 0x2B
#define TMP117_CONFIG_OS_2147483648S 0x2C

#define TMP117_CONFIG_POLARITY_BIT 0x04
#define TMP117_CONFIG_POLARITY_MASK 0xFB
#define TMP117_CONFIG_POLARITY_ACTIVE_LOW 0x00
#define TMP117_CONFIG_POLARITY_ACTIVE_HIGH 0x04

#define TMP117_CONFIG_FAULT_BIT 0x02
#define TMP117_CONFIG_FAULT_MASK 0xFD
#define TMP117_CONFIG_FAULT_NORMAL 0x00
#define TMP117_CONFIG_FAULT_OPEN_CIRCUIT 0x02
#define TMP117_CONFIG_FAULT_SHORT_TO_GND 0x04
#define TMP117_CONFIG_FAULT_SHORT_TO_VCC 0x06

#define TMP117_CONFIG_OS_MASK 0x7F

#define TMP117_CONFIG_DEFAULT (TMP117_CONFIG_OS_128US | TMP117_CONFIG_POLARITY_ACTIVE_LOW | TMP117_CONFIG_FAULT_NORMAL)

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer temperature_buffer;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %d\n", TMP117_ADDR, I2C_BUS, i2c_handle);
        return -1;
    }
    return 0;
}

static int initialize_sensor(void) {
    int config = i2cReadByteData(i2c_handle, TMP117_REG_CONFIG);
    if (config < 0) {
        fprintf(stderr, "Error reading TMP117 configuration register: %d\n", config);
        return -1;
    }

    config &= ~TMP117_CONFIG_OS_MASK;
    config |= TMP117_CONFIG_OS_128US;
    config &= ~TMP117_CONFIG_POLARITY_MASK;
    config |= TMP117_CONFIG_POLARITY_ACTIVE_LOW;
    config &= ~TMP117_CONFIG_FAULT_MASK;
    config |= TMP117_CONFIG_FAULT_NORMAL;

    if (i2cWriteByteData(i2c_handle, TMP117_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing TMP117 configuration register\n");
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature) {
    int raw_temperature = i2cReadWordData(i2c_handle, TMP117_REG_TEMP);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading TMP117 temperature register: %d\n", raw_temperature);
        return -1;
    }

    int16_t signed_temperature = (int16_t)raw_temperature;
    *temperature = (float)signed_temperature / 16.0f;
    return 0;
}

static void add_to_buffer(float temperature) {
    time(&temperature_buffer.buffer[temperature_buffer.head].timestamp);
    temperature_buffer.buffer[temperature_buffer.head].temperature = temperature;
    temperature_buffer.head = (temperature_buffer.head + 1) % BUFFER_SIZE;
    if (temperature_buffer.count < BUFFER_SIZE) {
        temperature_buffer.count++;
    }
}

static void flush_buffer(void) {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature_log.dat for writing\n");
        return;
    }

    size_t written = fwrite(temperature_buffer.buffer, sizeof(TemperatureReading), temperature_buffer.count, fp);
    if (written != temperature_buffer.count) {
        fprintf(stderr, "Error writing to temperature_log.dat: wrote %zu of %d elements\n", written, temperature_buffer.count);
    }

    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    flush_buffer();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() != 0) {
        cleanup();
        gpioTerminate();
        return 1;
    }

    temperature_buffer.head = 0;
    temperature_buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");

    return 0;
}

