static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int shtc3_read_measurement(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x2C, 0x06};
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to SHTC3.\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    uint8_t data[6];
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read measurement data from SHTC3.\n");
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f || *humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: Measurement out of range: Temperature=%.2fC, Humidity=%.2f%%RH\n",
                *temperature, *humidity);
        return -1;
    }

    return 0;
}

