    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file '%s'.\n", filename);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file '%s'.\n", filename);
        return -1;
    }

    return 0;
}

