#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x48
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

/* Si7202 register addresses */
#define REG_TEMP_MSB 0x00
#define REG_TEMP_LSB 0x01
#define REG_SPEED_MSB 0x02
#define REG_SPEED_LSB 0x03
#define REG_CONFIG 0x04
#define REG_STATUS 0x05

/* Configuration register bits */
#define CONFIG_MODE_CONTINUOUS 0x00
#define CONFIG_TEMP_EN 0x01
#define CONFIG_SPEED_EN 0x02
#define CONFIG_INT_EN 0x04
#define CONFIG_INT_TEMP_EN 0x08
#define CONFIG_INT_SPEED_EN 0x10

/* Status register bits */
#define STATUS_INT_TEMP 0x01
#define STATUS_INT_SPEED 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SI7202_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /* Configure: continuous mode, enable temperature, speed, and interrupts */
    uint8_t config = CONFIG_MODE_CONTINUOUS | CONFIG_TEMP_EN | CONFIG_SPEED_EN |
                     CONFIG_INT_EN | CONFIG_INT_TEMP_EN | CONFIG_INT_SPEED_EN;
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *temperature, float *speed) {
    int temp_msb, temp_lsb, speed_msb, speed_lsb;

    /* Read temperature (2 bytes, big-endian) */
    temp_msb = i2cReadByteData(i2c_handle, REG_TEMP_MSB);
    if (temp_msb < 0) {
        fprintf(stderr, "Error reading temperature MSB: %s\n", strerror(errno));
        return -1;
    }
    temp_lsb = i2cReadByteData(i2c_handle, REG_TEMP_LSB);
    if (temp_lsb < 0) {
        fprintf(stderr, "Error reading temperature LSB: %s\n", strerror(errno));
        return -1;
    }
    *temperature = (float)((temp_msb << 8) | temp_lsb) / 100.0f;

    /* Read speed (2 bytes, big-endian) */
    speed_msb = i2cReadByteData(i2c_handle, REG_SPEED_MSB);
    if (speed_msb < 0) {
        fprintf(stderr, "Error reading speed MSB: %s\n", strerror(errno));
        return -1;
    }
    speed_lsb = i2cReadByteData(i2c_handle, REG_SPEED_LSB);
    if (speed_lsb < 0) {
        fprintf(stderr, "Error reading speed LSB: %s\n", strerror(errno));
        return -1;
    }
    *speed = (float)((speed_msb << 8) | speed_lsb) / 100.0f;

    return 0;
}

static int log_data(float temperature, float speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, speed) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, speed;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Speed (rpm)\n");
        fflush(log_file);
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rotational speed measurement started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        if (read_sensor_data(&temperature, &speed) == 0) {
            if (log_data(temperature, speed) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values...\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Logging failed for NaN values\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

