#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int16_t raw;

    if (i2cWriteByte(i2c_handle, TMP117_REG_TEMP) < 0) {
        fprintf(stderr, "Error writing register address 0x%02X\n", TMP117_REG_TEMP);
        return -1;
    }

    gpioDelay(1000);

    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 4;

    if (raw & 0x0800) {
        raw |= 0xF000;
    }

    *temperature = (float)raw / 16.0f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_temperature(&temperature) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read temperature after %d retries. Re-initializing I2C.\n", MAX_RETRIES);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            continue;
        }

        if (temperature < -40.0f || temperature > 125.0f) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
        } else {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        }

        gpioDelay(1000000);
    }

    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

