#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *flow_raw, uint16_t *temp_raw) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: expected 4 bytes, got %d\n", result);
        return -1;
    }

    *flow_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temp_raw = ((uint16_t)(uint8_t)buf[2] << 4) | ((uint8_t)buf[3] >> 4);
    return 0;
}

static float convert_flow(uint16_t raw) {
    return (float)raw * 0.001f;
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * 0.0625f - 40.0f;
}

static int log_data(float flow, float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.3f SLPM, %.2f °C\n", timestamp, flow, temp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t flow_raw = 0, temp_raw = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_sensor_data(&flow_raw, &temp_raw) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed, retrying...\n", attempt + 1);
            gpioDelay(100000);
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d attempts. Re-initializing I2C...\n", MAX_RETRIES);
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            gpioDelay(1000000);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            continue;
        }

        float flow = convert_flow(flow_raw);
        float temp = convert_temperature(temp_raw);

        if (log_data(flow, temp) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Flow: %.3f SLPM, Temperature: %.2f °C\n", flow, temp);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

