/*
 * DHT11 Temperature & Humidity Sensor Reader for Raspberry Pi Zero W
 * Uses the pigpio library for microsecond timing and GPIO control.
 *
 * Wiring:
 *   DHT11 VCC -> 3.3V (Pin 1)
 *   DHT11 GND -> GND  (Pin 9)
 *   DHT11 DATA -> GPIO4 (Pin 7, BCM)
 *
 * Build: gcc -Wall -Wextra -O2 -o dht11_reader dht11_reader.c -lpigpio -lrt
 * Run:   sudo ./dht11_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_START_LOW_US 18000
#define DHT11_START_HIGH_US 80
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_TIMEOUT_US 100000
#define DHT11_MAX_RETRIES 5
#define DHT11_READ_INTERVAL_S 2
#define DHT11_MAX_READ_ERRORS 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message, int status_code) {
    if (!log_file) return;

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    fprintf(log_file, "%s, ERROR, %s, Status: %d\n", buf, message, status_code);
    fflush(log_file);
}

static void log_reading(uint8_t humidity_int, uint8_t humidity_dec,
                        uint8_t temperature_int, uint8_t temperature_dec,
                        uint8_t checksum) {
    if (!log_file) return;

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    fprintf(log_file, "%s, OK, Humidity: %d.%d%%, Temperature: %d.%dC, Checksum: 0x%02X\n",
            buf, humidity_int, humidity_dec, temperature_int, temperature_dec, checksum);
    fflush(log_file);
}

/*
 * Read DHT11 data.
 * Returns 0 on success, -1 on timeout, -2 on checksum error, -3 on sensor absent.
 */
static int read_dht11(uint8_t *humidity_int, uint8_t *humidity_dec,
                      uint8_t *temperature_int, uint8_t *temperature_dec) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int bit_count = 0;
    int timeout_count = 0;
    int last_level = 1;

    /* --- Start signal: pull low for >= 18 ms, then release --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode to output", -1);
        return -1;
    }
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(DHT11_START_LOW_US);
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(DHT11_START_HIGH_US);

    /* --- Sensor response: 80 us low, 80 us high --- */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) {
        log_error("Failed to set GPIO mode to input", -1);
        return -1;
    }
    gpioDelay(DHT11_RESP_LOW_US);

    /* --- Switch to input with pull-up --- */
    if (gpioSetPullUpDown(DHT11_GPIO, PI_PUD_UP) < 0) {
        log_error("Failed to set pull-up on GPIO", -1);
        return -1;
    }

    /* --- Wait for sensor response: low then high --- */
    timeout_count = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1);
        timeout_count++;
        if (timeout_count > DHT11_TIMEOUT_US) {
            log_error("DHT11 response timeout (sensor absent or not responding)", -3);
            return -3;
        }
    }
    timeout_count = 0;
    while (gpioRead(DHT11_GPIO) == 0) {
        gpioDelay(1);
        timeout_count++;
        if (timeout_count > DHT11_TIMEOUT_US) {
            log_error("DHT11 response timeout (sensor absent or not responding)", -3);
            return -3;
        }
    }
    timeout_count = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1);
        timeout_count++;
        if (timeout_count > DHT11_TIMEOUT_US) {
            log_error("DHT11 response timeout (sensor absent or not responding)", -3);
            return -3;
        }
    }

    /* --- Read 40 data bits --- */
    for (int i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of low pulse) */
        timeout_count = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1);
            timeout_count++;
            if (timeout_count > DHT11_TIMEOUT_US) {
                log_error("DHT11 data bit timeout (start of high pulse)", -1);
                return -1;
            }
        }

        /* Measure high pulse width: ~26-28 us = '0', ~70 us = '1' */
        timeout_count = 0;
        int high_start = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1);
            timeout_count++;
            if (timeout_count > DHT11_TIMEOUT_US) {
                log_error("DHT11 data bit timeout (end of high pulse)", -1);
                return -1;
            }
        }
        int high_duration = gpioTick() - high_start;

        /* Store bit: ~26 us = '0', ~70 us = '1' */
        if (high_duration > 40) {
            data[byte_idx] |= (1 << (7 - bit_idx));
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        log_error("DHT11 checksum mismatch", -2);
        return -2;
    }

    /* --- Parse data --- */
    *humidity_int = data[0];
    *humidity_dec = data[1];
    *temperature_int = data[2];
    *temperature_dec = data[3];

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("dht11_readings.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("DHT11 sensor reader started. Press Ctrl+C to exit.\n");

    int read_errors = 0;

    while (running) {
        uint8_t humidity_int = 0, humidity_dec = 0;
        uint8_t temperature_int = 0, temperature_dec = 0;

        int result = read_dht11(&humidity_int, &humidity_dec,
                                &temperature_int, &temperature_dec);

        if (result == 0) {
            log_reading(humidity_int, humidity_dec,
                        temperature_int, temperature_dec,
                        humidity_int + humidity_dec + temperature_int + temperature_dec);
            read_errors = 0;
        } else {
            read_errors++;
            if (read_errors >= DHT11_MAX_READ_ERRORS) {
                log_error("Too many consecutive read errors, aborting", -1);
                break;
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < DHT11_READ_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

