/*
 * MLX90824 Pressure & Temperature Logger for Raspberry Pi 4 Model B
 *
 * Reads absolute pressure and temperature from a Melexis MLX90824 sensor
 * over the I2C bus every 2 seconds, logs the data to pressure_log.txt,
 * and reports errors to stderr.
 *
 * Wiring:
 *   MLX90824 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MLX90824 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MLX90824 VDD -> 3.3 V
 *   MLX90824 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mlx90824_logger mlx90824_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5A
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  2.0

/* MLX90824 register addresses (from datasheet) */
#define REG_PRESSURE_MSB 0x00
#define REG_TEMP_MSB     0x02
#define REG_CONFIG       0x04
#define REG_STATUS       0x06

/* Configuration register bits */
#define CONFIG_RESET     0x0001
#define CONFIG_MODE_CONT 0x0000
#define CONFIG_MODE_ONE  0x0002
#define CONFIG_ONE_SHOT 0x0004
#define CONFIG_INT_EN   0x0008
#define CONFIG_INT_POL  0x0010
#define CONFIG_INT_LVL  0x0020
#define CONFIG_INT_MASK 0x0040

/* Status register bits */
#define STATUS_INT_RAW   0x0001

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90824                 */
/* ------------------------------------------------------------------ */
static int read_register16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X) failed: rc=%d, errno=%d (%s)\n",
                reg, rc, errno, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit big-endian value to an MLX90824 register            */
/* ------------------------------------------------------------------ */
static int write_register16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%04X) failed: rc=%d, errno=%d (%s)\n",
                reg, value, rc, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure and temperature from the MLX90824                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *pressure, float *temperature)
{
    uint16_t raw_pressure, raw_temperature;

    /* Trigger a one-shot conversion */
    if (write_register16(handle, REG_CONFIG, CONFIG_RESET | CONFIG_MODE_ONE | CONFIG_ONE_SHOT) != 0)
        return -1;

    /* Wait for the conversion to complete (max ~1 ms at 100 kHz) */
    time_sleep(0.001);

    /* Read the raw 16-bit values */
    if (read_register16(handle, REG_PRESSURE_MSB, &raw_pressure) != 0)
        return -1;
    if (read_register16(handle, REG_TEMP_MSB, &raw_temperature) != 0)
        return -1;

    /* Convert raw values to physical units (from datasheet) */
    *pressure = (float)raw_pressure * 0.001f;   /* Pa */
    *temperature = (float)raw_temperature * 0.02f - 273.15f; /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a measurement with an ISO-8601 timestamp                         */
/* ------------------------------------------------------------------ */
static void log_measurement(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f Pa, %.2f °C\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
    } else {
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: rc=%d, errno=%d (%s)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle, errno, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("MLX90824 logger started. Logging to %s every %.1f s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* Main sampling loop */
    while (g_running) {
        float pressure, temperature;

        if (read_sensor(g_i2c_handle, &pressure, &temperature) == 0) {
            log_measurement(g_log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; logging error entry.\n");
            log_measurement(g_log_file, 0.0f, -999.0f);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 20 && g_running; i++) {
            time_sleep(0.1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
