#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define BUFFER_SIZE     60
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer temperature_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0f;
    }
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature from I2C device: %d\n", result);
        return -1;
    }
    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw_temp / 16.0f;
    return 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, float temperature) {
    cb->buffer[cb->head] = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

static void control_fan(float average_temperature) {
    int state = (average_temperature > TEMP_THRESHOLD_HIGH) ? 1 : 0;
    if (gpioWrite(FAN_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", FAN_GPIO);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", LM75B_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_circular_buffer(&temperature_buffer) != 0) {
        fprintf(stderr, "Error initializing circular buffer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            add_to_circular_buffer(&temperature_buffer, temperature);
            float average_temperature = calculate_average(&temperature_buffer);
            control_fan(average_temperature);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

