/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   SDP810 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o sdp810_logger sdp810_logger.c -lm
 *
 * Run:
 *   ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1.0          /* seconds between samples */
#define MEASURE_DELAY  0.045        /* SDP810 first-measurement settle */
#define MAX_RETRIES    3
#define PRESSURE_THRESHOLD 5.0       /* Pa */

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[1] = { 0x36 };   /* differential pressure, no averaging */
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (sensor absent or bus error).\n");
        return -1;
    }

    /* Wait for first conversion to complete */
    time_sleep(MEASURE_DELAY);

    /* Read 9 bytes: [MSB, LSB, CRC, MSB, LSB, CRC, MSB, LSB, CRC] */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] I2C read failed (sensor absent or bus error).\n");
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch.\n");
        return -2;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch.\n");
        return -2;
    }

    /* Assemble signed 16-bit values */
    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* Convert to physical units (Pa, °C) */
    *pressure    = (float)raw_pressure    * 0.0625f;   /* Pa per LSB */
    *temperature = (float)raw_temperature / 100.0f;   /* °C per LSB */

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\n[INFO] Signal received, shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main(void)
{
    int handle = -1;
    FILE *fp = NULL;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d).\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

