#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR   0x50
#define TEMP_REG       0x00
#define LED_PIN        17
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c) {
    uint8_t raw;
    if (i2c_read_reg8(fd, TEMP_REG, &raw) < 0)
        return -1;
    *temp_c = (float)raw / 2.0f;
    return 0;
}

static void control_led(struct gpiod_line *line, float temp_c) {
    int val = (temp_c > TEMP_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Failed to set LED GPIO value: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "stts2004-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp_c;
        if (read_temperature(i2c_fd, &temp_c) < 0) {
            fprintf(stderr, "Failed to read temperature after %d consecutive failures.\n", 10);
            break;
        }

        printf("Temperature: %.2f °C\n", temp_c);
        control_led(led_line, temp_c);

        for (int i = 0; i < POLL_INTERVAL && running; i++)
            sleep(1);
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

