/*
 * Si7021 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7021 SDA -> GPIO2 (BCM, bus 1)
 *   Si7021 SCL -> GPIO3 (BCM, bus 1)
 *   Si7021 VDD -> 3.3 V
 *   Si7021 GND -> GND
 *
 * Build: gcc -O2 -Wall -o si7021_logger si7021_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define MAX_RETRIES    3
#define MEASURE_DELAY  20          /* ms after issuing a no-hold command */

/* Si7021 commands (no register address prefix) */
#define CMD_MEASURE_RH_NO_HOLD   0xE5
#define CMD_MEASURE_TEMP_NO_HOLD 0xE3
#define CMD_READ_PREV_TEMP_RH    0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
/*
 * Write a single command byte to the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int si7021_write_cmd(uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByte(g_i2c_handle, cmd);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByte(0x%02X) failed (attempt %d/%d): %s\n",
                cmd, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/*
 * Read a 16-bit big-endian value from the Si7021.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int si7021_read_word(uint16_t *out)
{
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

/*
 * Read a single byte from the Si7021.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int si7021_read_byte(uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByte(g_i2c_handle);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadByte failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int si7021_init(void)
{
    /* Verify sensor presence by reading the electronic ID or firmware revision */
    uint8_t id = 0;
    if (si7021_read_byte(&id) != 0) {
        fprintf(stderr, "[ERROR] Si7021 not responding on I2C bus %d addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        return -1;
    }
    printf("[INFO] Si7021 detected (ID 0x%02X)\n", id);

    /*
     * Read the electronic ID (0xFA) and firmware revision (0xFC).
     * The Si7021 returns the ID in the first byte, the revision in the second.
     */
    uint8_t rev = 0;
    if (si7021_write_cmd(0xFA) != 0) {
        fprintf(stderr, "[ERROR] Failed to write electronic ID command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY);
    if (si7021_read_byte(&rev) != 0) {
        fprintf(stderr, "[ERROR] Failed to read electronic ID\n");
        return -1;
    }

    if (si7021_write_cmd(0xFC) != 0) {
        fprintf(stderr, "[ERROR] Failed to write firmware revision command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY);
    uint8_t rev_raw = 0;
    if (si7021_read_byte(&rev_raw) != 0) {
        fprintf(stderr, "[ERROR] Failed to read firmware revision\n");
        return -1;
    }

    printf("[INFO] Si7021 revision: %u.%u\n", rev, rev_raw);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor readings                                                    */
/* ------------------------------------------------------------------ */
static int si7021_read_temperature(float *temperature)
{
    if (si7021_write_cmd(CMD_MEASURE_TEMP_NO_HOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw = 0;
    if (si7021_read_word(&raw) != 0)
        return -1;

    /* Temperature: 14-bit, 900 °C offset, 1/16 °C LSB */
    *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int si7021_read_humidity(float *humidity)
{
    if (si7021_write_cmd(CMD_MEASURE_RH_NO_HOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw = 0;
    if (si7021_read_word(&raw) != 0)
        return -1;

    /* Humidity: 12-bit, 100 %RH offset, 1/16 %RH LSB */
    *humidity = (125.0f * (float)raw / 65536.0f) - 6.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(g_log_file);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n",
           timestamp, temperature, humidity);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si7021_init() != 0) {
        fprintf(stderr, "[FATAL] Si7021 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,temperature_c,humidity_pct\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* Main sampling loop */
    while (g_running) {
        float temperature = 0.0f;
        float humidity = 0.0f;

        if (si7021_read_temperature(&temperature) == 0 &&
            si7021_read_humidity(&humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; logging timestamped error.\n");
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "UNKNOWN");
            }
            fprintf(g_log_file, "%s,ERROR,Sensor read failed\n", ts);
            fflush(g_log_file);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

