/*
 * HVAC Air Duct Pressure Monitor — Raspberry Pi Zero W
 * Sensor : Sensirion SDP810-500Pa differential pressure sensor
 * Bus    : I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Library: pigpio (I2C)
 *
 * Build  : gcc -O2 -Wall -o hvac_monitor hvac_monitor.c -lpigpio -lrt
 * Run    : sudo ./hvac_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          1
#define I2C_ADDR         0x48          /* SDP810 default 7-bit I2C address */
#define LOG_FILE         "hvac_pressure_log.txt"
#define SAMPLE_PERIOD_S  1            /* seconds between samples */
#define MEASURE_DELAY_US 50000        /* 50 ms measurement settle time */

/* SDP810-500Pa command codes (16-bit, MSB first) */
#define CMD_MEASURE_MSB  0x10
#define CMD_MEASURE_LSB  0x50
#define CMD_READ_ID_MSB  0x00
#define CMD_READ_ID_LSB  0x01
#define CMD_READ_SCALE_MSB 0x00
#define CMD_READ_SCALE_LSB 0x03

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static uint8_t crc8(const uint8_t *data, int len);
static int  sdp810_read_measurement(int handle, float *pressure, float *temperature);
static int  sdp810_read_scale_factor(int handle, float *scale_factor);
static int  log_data(FILE *fp, float pressure, float temperature);
static void cleanup(void);

/* ----------------------------- CRC-8 (Sensirion polynomial 0x31, init 0xFF) */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Read measurement ----------------------------- */
static int sdp810_read_measurement(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { CMD_MEASURE_MSB, CMD_MEASURE_LSB };
    uint8_t buf[9];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (measurement command)\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(3)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] I2C read failed (measurement data)\n");
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 3) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale factor CRC mismatch\n");
        return -1;
    }

    /* Convert raw values (big-endian) */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_factor = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

/* ----------------------------- Read scale factor --------------------------- */
static int sdp810_read_scale_factor(int handle, float *scale_factor)
{
    uint8_t cmd[2] = { CMD_READ_SCALE_MSB, CMD_READ_SCALE_LSB };
    uint8_t buf[3];

    /* Send read scale factor command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (scale factor command)\n");
        return -1;
    }

    /* Read 3 bytes: scale factor(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "[ERROR] I2C read failed (scale factor data)\n");
        return -1;
    }

    /* Validate CRC */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Scale factor CRC mismatch\n");
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *scale_factor = (float)raw / 100.0f;

    return 0;
}

/* ----------------------------- Log data ---------------------------------- */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_Pa,temperature_C\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("HVAC Air Duct Pressure Monitor started.\n");
    printf("I2C bus %d, address 0x%02X, logging to '%s'. Press Ctrl+C to exit.\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;

        if (sdp810_read_measurement(g_i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing\n");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            }
        } else {
            fprintf(stderr, "[WARN] Measurement read failed; skipping sample\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

