#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SCD40_ADDR     0x60
#define CSV_DIR        "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define BUFFER_SIZE    100
#define READ_INTERVAL  5
#define LOG_INTERVAL   60

/* SCD40 commands */
#define CMD_START_PERIODIC_MEASUREMENT 0x10
#define CMD_STOP_PERIODIC_MEASUREMENT   0x11
#define CMD_READ_MEASUREMENT_DATA       0x20

/* SCD40 register addresses */
#define REG_MEASUREMENT_STATUS 0x00
#define REG_CO2_MSB           0x02
#define REG_CO2_LSB           0x03
#define REG_TEMP_MSB          0x04
#define REG_TEMP_LSB          0x05
#define REG_HUMIDITY_MSB      0x06
#define REG_HUMIDITY_LSB      0x07

/* CRC-8 parameters for Sensirion SCD40 (polynomial 0x31, init 0xFF) */
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT       0xFF

typedef struct {
    time_t timestamp;
    int    co2;
    float  temperature;
    float  humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static circular_buffer_t buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_scd40_data(int fd, int *co2, float *temperature, float *humidity) {
    uint8_t status;
    uint8_t data[9];

    /* Read measurement status */
    if (i2c_read_bytes(REG_MEASUREMENT_STATUS, &status, 1) < 0)
        return -1;

    if ((status & 0x03) != 0x03) {
        fprintf(stderr, "SCD40 measurement not ready (status=0x%02X)\n", status);
        return -1;
    }

    /* Read 9 bytes: CO2 MSB, CO2 LSB, CRC, Temp MSB, Temp LSB, CRC, Humidity MSB, Humidity LSB, CRC */
    if (i2c_read_bytes(REG_CO2_MSB, data, 9) < 0)
        return -1;

    /* Validate CRC for each 2-byte value */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on CO2 data\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC mismatch on humidity data\n");
        return -1;
    }

    *co2 = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, int co2, float temperature, float humidity) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head].timestamp = time(NULL);
    buf->data[buf->head].co2 = co2;
    buf->data[buf->head].temperature = temperature;
    buf->data[buf->head].humidity = humidity;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void *logging_thread(void *arg) {
    (void)arg;
    while (running) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%s/scd40_data_%04d%02d%02d_%02d%02d%02d.csv",
                 CSV_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        FILE *fp = fopen(filename, "w");
        if (!fp) {
            fprintf(stderr, "Failed to open CSV file for logging: %s\n", strerror(errno));
            sleep(LOG_INTERVAL);
            continue;
        }

        fprintf(fp, "Timestamp,CO2,Temperature(C),Humidity(%%)\n");

        pthread_mutex_lock(&buffer.mutex);
        int start = (buffer.count < BUFFER_SIZE) ? 0 : buffer.head;
        for (int i = 0; i < buffer.count; i++) {
            int idx = (start + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%d,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);

        fclose(fp);

        sleep(LOG_INTERVAL);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SCD40_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mkdir(CSV_DIR, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Failed to create CSV directory %s: %s\n", CSV_DIR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    buffer.head = 0;
    buffer.count = 0;

    if (i2c_write_byte(CMD_STOP_PERIODIC_MEASUREMENT, 0x00) < 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
        pthread_mutex_destroy(&buffer.mutex);
        close(i2c_fd);
        return 1;
    }
    usleep(10000); /* 10 ms settle time after stop */

    if (i2c_write_byte(CMD_START_PERIODIC_MEASUREMENT, 0x00) < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        pthread_mutex_destroy(&buffer.mutex);
        close(i2c_fd);
        return 1;
    }
    usleep(10000); /* 10 ms settle time after start */

    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create logging thread: %s\n", strerror(errno));
        i2c_write_byte(CMD_STOP_PERIODIC_MEASUREMENT, 0x00);
        pthread_mutex_destroy(&buffer.mutex);
        close(i2c_fd);
        return 1;
    }

    printf("SCD40 data acquisition started. Logging to %s every %d seconds.\n",
           CSV_DIR, READ_INTERVAL);

    while (running) {
        int co2;
        float temperature, humidity;

        if (read_scd40_data(i2c_fd, &co2, &temperature, &humidity) == 0) {
            add_to_buffer(&buffer, co2, temperature, humidity);
            printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n",
                   co2, temperature, humidity);
        } else {
            log_error("Failed to read SCD40 data");
        }

        sleep(READ_INTERVAL);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2c_write_byte(CMD_STOP_PERIODIC_MEASUREMENT, 0x00);
    pthread_join(logging_thread_id, NULL);

    pthread_mutex_lock(&buffer.mutex);
    int start = (buffer.count < BUFFER_SIZE) ? 0 : buffer.head;
    for (int i = 0; i < buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char filename[256];
        snprintf(filename, sizeof(filename), "%s/scd40_data_%04d%02d%02d_%02d%02d%02d.csv",
                 CSV_DIR, buffer.data[idx].timestamp,
                 buffer.data[idx].co2, buffer.data[idx].temperature,
                 buffer.data[idx].humidity);
        FILE *fp = fopen(filename, "w");
        if (fp) {
            fprintf(fp, "Timestamp,CO2,Temperature(C),Humidity(%%)\n");
            fprintf(fp, "%ld,%d,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to write final CSV file: %s\n", strerror(errno));
        }
    }
    pthread_mutex_unlock(&buffer.mutex);

    pthread_mutex_destroy(&buffer.mutex);
    if (i2c_fd >= 0)
        close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

