/*
 * Raspberry Pi 4 Model B – TDK ICP-10110 Pressure Sensor Logger
 *
 * Reads pressure and temperature from an ICP-10110 on the I2C bus 1
 * (GPIO2 = SDA, GPIO3 = SCL), logs each sample to environmental_data.txt,
 * and exits cleanly on SIGINT.
 *
 * Build:  gcc -O2 -Wall -o icp10110_logger icp10110_logger.c -lgpiod
 * Run:    sudo ./icp10110_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10110_ADDR  0x48          /* Default 7-bit I2C address */
#define LOG_FILE       "environmental_data.txt"
#define SAMPLE_PERIOD  5            /* seconds between samples */
#define SAMPLE_DELAY   10000        /* microseconds between triggers */

/*
 * ICP-10110 register addresses (16-bit, big-endian on the bus).
 * The sensor sends data MSB first, then LSB.
 */
#define REG_PRESSURE_MSB  0x00
#define REG_PRESSURE_LSB  0x01
#define REG_TEMP_MSB     0x02
#define REG_TEMP_LSB     0x03
#define REG_CONFIG       0x04
#define REG_INT_STATUS   0x05
#define REG_INT_ENABLE   0x06
#define REG_INT_CLEAR    0x07

/*
 * Configuration register bits (0x04).
 * Bit 0: 0 = continuous conversion, 1 = one-shot conversion.
 * Bit 1: 0 = normal mode, 1 = standby.
 * Bit 2: 0 = no interrupt, 1 = interrupt on conversion complete.
 * Bit 3: 0 = no interrupt, 1 = interrupt on conversion complete.
 * Bit 4: 0 = no interrupt, 1 = interrupt on conversion complete.
 * Bit 5: 0 = no interrupt, 1 = interrupt on conversion complete.
 * Bit 6: 0 = no interrupt, 1 = interrupt on conversion complete.
 * Bit 7: 0 = no interrupt, 1 = interrupt on conversion complete.
 */
#define CONFIG_CONTINUOUS 0x00
#define CONFIG_ONE_SHOT   0x01
#define CONFIG_STANDBY    0x02
#define CONFIG_INT_EN     0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_msb, uint16_t *value)
{
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, reg_msb, &msb) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_msb + 1, &lsb) < 0)
        return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_icp10110(int fd)
{
    uint8_t config;

    /* Verify sensor presence by reading the configuration register */
    if (i2c_read_reg8(fd, REG_CONFIG, &config) < 0) {
        fprintf(stderr, "ICP-10110 not responding at address 0x%02X\n",
                ICP10110_ADDR);
        return -1;
    }

    /*
     * Set continuous conversion mode, normal mode, and enable
     * interrupts on conversion complete.
     */
    if (i2c_write_reg8(fd, REG_CONFIG,
                       CONFIG_CONTINUOUS | CONFIG_STANDBY | CONFIG_INT_EN) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg8(fd, REG_INT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, float *pressure, float *temperature)
{
    uint16_t raw_pressure, raw_temperature;

    /* Trigger a one-shot conversion */
    if (i2c_write_reg8(fd, REG_CONFIG, CONFIG_ONE_SHOT) < 0)
        return -1;

    /* Wait for conversion to complete (max ~10 ms for continuous mode) */
    usleep(15000);

    /* Read the 16-bit results (MSB first) */
    if (i2c_read_reg16(fd, REG_PRESSURE_MSB, &raw_pressure) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_TEMP_MSB, &raw_temperature) < 0)
        return -1;

