/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 Barometric Pressure Sensor Monitor
 *
 * Reads six bytes from the ICP-10125 every second, verifies CRCs, and drives
 * a warning LED on GPIO17 (BCM) at 1 Hz or 5 Hz when the pressure falls below
 * 95 000 Pa.  Handles I2C errors and sensor-absent conditions.
 *
 * Build:  gcc -O2 -Wall -o icp10125_monitor icp10125_monitor.c -lpigpio -lrt
 * Run:    sudo ./icp10125_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define GPIO_LED       17
#define PRESSURE_THRESHOLD 95000.0f   /* Pa */
#define POLL_DELAY_US   1000000      /* 1 second */
#define LED_ON_US      500000       /* 500 ms */
#define LED_OFF_US     500000       /* 500 ms */
#define TRIGGER_DELAY_US 20000       /* 20 ms */

/* ICP-10125 register addresses */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB     0x02
#define REG_TEMP_LSB     0x03
#define REG_CRC_MSB      0x04
#define REG_CRC_LSB      0x05

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (polynomial 0x31, init 0xFF, no final XOR)        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 6-byte sensor frame from the ICP-10125                     */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, float *pressure, float *temperature)
{
    uint8_t buf[6];

    /* Write the register pointer to the pressure register */
    if (i2cWriteByte(fd, REG_PRESSURE_MSB) < 0) {
        fprintf(stderr, "Error: failed to set pressure register pointer\n");
        return -1;
    }

    /* Read 6 bytes: pressure MSB, pressure LSB, temp MSB, temp LSB, CRC MSB, CRC LSB */
    int bytes_read = i2cReadDevice(fd, (char *)buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: expected 6 bytes, got %d\n", bytes_read);
        return -1;
    }

    /* Verify CRC for pressure bytes */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }

    /* Verify CRC for temperature bytes */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure;
    *temperature = (float)raw_temperature / 10.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the warning LED based on pressure threshold                  */
/* ------------------------------------------------------------------ */
static void control_led(int gpio_pin, float pressure)
{
    if (pressure < PRESSURE_THRESHOLD) {
        /* Blink at 1 Hz */
        if (gpioWrite(gpio_pin, 1) < 0)
            fprintf(stderr, "Warning: failed to set GPIO %d high\n", gpio_pin);
        gpioDelay(LED_ON_US);
        if (gpioWrite(gpio_pin, 0) < 0)
            fprintf(stderr, "Warning: failed to set GPIO %d low\n", gpio_pin);
        gpioDelay(LED_OFF_US);
    } else {
        /* Blink at 5 Hz */
        if (gpioWrite(gpio_pin, 1) < 0)
            fprintf(stderr, "Warning: failed to set GPIO %d high\n", gpio_pin);
        gpioDelay(LED_ON_US);
        if (gpioWrite(gpio_pin, 0) < 0)
            fprintf(stderr, "Warning: failed to set GPIO %d low\n", gpio_pin);
        gpioDelay(LED_OFF_US);
        if (gpioWrite(gpio_pin, 1) < 0)
            fprintf(stderr, "Warning: failed to set GPIO %d high\n", gpio_pin);
        gpioDelay(LED_ON_US);
        if (gpioWrite(gpio_pin, 0) < 0)
            fprintf(stderr, "Warning: failed to set GPIO %d low\n", gpio_pin);
        gpioDelay(LED_OFF_US);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper – safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("ICP-10125 monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sensor_data(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
            control_led(GPIO_LED, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed – LED off\n");
            gpioWrite(GPIO_LED, 0);
        }

        /* Trigger delay between readings */
        gpioDelay(TRIGGER_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

