#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define TEMP_HIGH 30.0f
#define TEMP_LOW 28.0f
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define LOG_INTERVAL_US 2000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, TEMP_REG) < 0) {
            fprintf(stderr, "I2C write error (reg select): %d\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read error: %d\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *temperature = (float)raw / 100.0f;
        return 0;
    }

    return -1;
}

static void log_temperature(float temperature) {
    FILE *fp = fopen("temperature_log.txt", "a");
    if (!fp) {
        perror("Failed to open temperature_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
}

static void control_fan(float temperature) {
    static int fan_state = 0;

    if (temperature > TEMP_HIGH && fan_state == 0) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_state = 1;
            printf("Fan ON (temp: %.2f°C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_LOW && fan_state == 1) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_state = 0;
            printf("Fan OFF (temp: %.2f°C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

