#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0x2C14
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define MEASUREMENT_DELAY_US 10000

static int i2c_handle = -1;
static int server_socket = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht40(float *temperature, float *humidity) {
    unsigned char cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    unsigned char data[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", attempt + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read error (attempt %d): expected 6 bytes, got %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        unsigned int raw_humidity = (data[0] << 8) | data[1];
        unsigned int raw_temperature = (data[3] << 8) | data[4];

        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;
        *temperature = -46.85f + 175.72f * (float)raw_temperature / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d attempts\n", MAX_RETRIES);
    return -1;
}

static int create_server_socket(int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(sock);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(sock);
        return -1;
    }

    if (listen(sock, 3) < 0) {
        perror("listen");
        close(sock);
        return -1;
    }

    return sock;
}

static int handle_client(int client_socket) {
    float temperature, humidity;
    char response[512];

    if (read_sht40(&temperature, &humidity) != 0) {
        snprintf(response, sizeof(response), "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\n\r\nFailed to read SHT40 sensor");
    } else {
        snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature: %.2f C, Humidity: %.2f %%</h1></body></html>", temperature, humidity);
    }

    if (send(client_socket, response, strlen(response), 0) < 0) {
        perror("send");
    }

    close(client_socket);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, address 0x%02X: %s\n", I2C_BUS, SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_socket = create_server_socket(SERVER_PORT);
    if (server_socket < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHT40 HTTP server started on port %d. Press Ctrl+C to exit.\n", SERVER_PORT);

    while (!terminate) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);

        if (client_socket < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        handle_client(client_socket);
    }

    printf("\nShutting down...\n");

    if (server_socket >= 0) close(server_socket);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

