    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, address 0x%02X: %s\n", I2C_BUS, SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_socket = create_server_socket(SERVER_PORT);
    if (server_socket < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHT40 HTTP server started on port %d. Press Ctrl+C to exit.\n", SERVER_PORT);

    while (!terminate) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);

        if (client_socket < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        handle_client(client_socket);
    }

    printf("\nShutting down...\n");

    if (server_socket >= 0) close(server_socket);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

