#define TMP102_ADDR 0x48
#define TMP102_REG_TEMP 0x00
#define I2C_BUS 1
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, TMP102_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature from I2C device: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temp >>= 4;

    if (raw_temp & 0x800) {
        raw_temp |= 0xF000;
    }

    *temperature = (float)raw_temp / 16.0f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

