/*
 * HDC2010 Temperature & Humidity Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   HDC2010 SDA -> GPIO2 (I2C bus 1 SDA)
 *   HDC2010 SCL -> GPIO3 (I2C bus 1 SCL)
 *   HDC2010 VDD -> 3.3 V
 *   HDC2010 GND -> GND
 *
 * Build: gcc -O2 -Wall -o hdc2010_reader hdc2010_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ---- HDC2010 I2C address (ADDR pin tied to GND) ---- */
#define HDC2010_ADDR 0x40

/* ---- HDC2010 register addresses ---- */
#define REG_TEMP_LOW   0x00
#define REG_TEMP_HIGH  0x01
#define REG_HUM_LOW    0x02
#define REG_HUM_HIGH   0x03
#define REG_MEAS_CFG   0x0E

/* ---- Measurement configuration bits ---- */
#define MEAS_CFG_MEAS_TRIG 0x01   /* bit 0: start measurement */
#define MEAS_CFG_MEAS_MODE 0x02   /* bit 1: continuous measurement */
#define MEAS_CFG_MEAS_REP  0x04   /* bit 2: repeat measurement */
#define MEAS_CFG_MEAS_TRIG_VAL 0x01

/* ---- Measurement timeout (500 ms) ---- */
#define MEAS_TIMEOUT_US 500000

/* ---- Retry parameters ---- */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000   /* 100 ms */

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a single byte to an HDC2010 register ---- */
static int hdc2010_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ---- Read a single byte from an HDC2010 register ---- */
static int hdc2010_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Read temperature and humidity from the HDC2010 ---- */
static int hdc2010_read_temperature_humidity(int handle, float *temperature, float *humidity)
{
    uint8_t temp_low, temp_high, hum_low, hum_high;
    int retries = 0;

    /* Trigger a measurement by writing MEAS_CFG_MEAS_TRIG_VAL to MEAS_CFG */
    if (hdc2010_write_reg(handle, REG_MEAS_CFG, MEAS_CFG_MEAS_TRIG_VAL) < 0) {
        return -1;
    }

    /* Poll MEAS_CFG until bit 0 clears (data ready) or timeout */
    uint8_t cfg;
    do {
        if (hdc2010_read_reg(handle, REG_MEAS_CFG, &cfg) < 0) {
            return -1;
        }
        if (++retries > MAX_RETRIES) {
            fprintf(stderr, "[ERROR] Measurement timeout (sensor may be absent or bus error)\n");
            return -1;
        }
        usleep(RETRY_DELAY_US);
    } while (cfg & MEAS_CFG_MEAS_TRIG);

    /* Read temperature (2 bytes, big-endian) */
    if (hdc2010_read_reg(handle, REG_TEMP_LOW, &temp_low) < 0) {
        return -1;
    }
    if (hdc2010_read_reg(handle, REG_TEMP_HIGH, &temp_high) < 0) {
        return -1;
    }
    uint16_t raw_temp = ((uint16_t)temp_high << 8) | temp_low;
    *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);

    /* Read humidity (2 bytes, big-endian) */
    if (hdc2010_read_reg(handle, REG_HUM_LOW, &hum_low) < 0) {
        return -1;
    }
    if (hdc2010_read_reg(handle, REG_HUM_HIGH, &hum_high) < 0) {
        return -1;
    }
    uint16_t raw_hum = ((uint16_t)hum_high << 8) | hum_low;
    *humidity = (100.0f * (float)raw_hum / 65535.0f);

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HDC2010 address */
    g_i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                HDC2010_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("HDC2010 Temperature & Humidity Sensor Reader\n");
    printf("I2C bus 1, address 0x%02X. Press Ctrl+C to exit.\n\n", HDC2010_ADDR);

    /* Main loop */
    while (g_running) {
        float temperature, humidity;

        if (hdc2010_read_temperature_humidity(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }

        /* Sleep 5 seconds, checking g_running every 100 ms to allow prompt shutdown */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    /* Clean shutdown: call the pigpio API before exiting */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

