/*
 * Raspberry Pi 3 Model B+ - Sensirion SDP800-500Pa Differential Pressure Sensor
 *
 * Reads raw 16-bit pressure and temperature every 500 ms from the SDP800-500Pa
 * on I2C bus 1.  Uses the pigpio library for I2C communication.
 *
 * Wiring:
 *   SDP800-500Pa SDA -> GPIO 2 (I2C bus 1 SDA)
 *   SDP800-500Pa SCL -> GPIO 3 (I2C bus 1 SCL)
 *   SDP800-500Pa VDD -> 3.3 V
 *   SDP800-500Pa GND -> GND
 *
 * Build: gcc -Wall -o sdp800_reader sdp800_reader.c -lpigpio -lrt
 * Run:   sudo ./sdp800_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x48
#define MEASURE_DELAY_US 45000   /* 45 ms measurement time */
#define SAMPLE_PERIOD_US 500000 /* 500 ms between samples */

/* SDP800-500Pa command codes (from datasheet) */
#define CMD_MEASURE_DIFF_PRESSURE 0x14
#define CMD_READ_MEASUREMENT      0x2B

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion polynomial 0x31, init 0xFF)            */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == expected);
}

/* ------------------------------------------------------------------ */
/* Send a measurement command to the SDP800-500Pa                       */
/* ------------------------------------------------------------------ */
static int sdp800_send_command(uint8_t cmd)
{
    int rc = i2cWriteByte(g_i2c_handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly 6 bytes from the SDP800-500Pa                          */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int sdp800_read_measurement(uint16_t *pressure, uint16_t *temperature)
{
    uint8_t buf[6];

    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 6)\n", rc);
        return -1;
    }

    /* Validate CRC for pressure (bytes 0-1, CRC byte 2) */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the pigpio library and open the I2C bus                  */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP800_ADDR, g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources: close I2C handle and terminate pigpio            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize I2C and verify sensor presence */
    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Send measurement command */
        if (sdp800_send_command(CMD_MEASURE_DIFF_PRESSURE) != 0) {
            fprintf(stderr, "[WARN] Measurement command failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Wait for measurement to complete */
        gpioDelay(MEASURE_DELAY_US);

        /* Read measurement */
        uint16_t pressure, temperature;
        if (sdp800_read_measurement(&pressure, &temperature) != 0) {
            fprintf(stderr, "[WARN] Measurement read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Log data */
        printf("Pressure: %u Pa, Temperature: %u Pa\n", pressure, temperature);
        fflush(stdout);

        /* Wait for next sample */
