#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define TARGET_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_INTERVAL_US 1000000 // 1 second
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000 // 1000 steps

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define TARGET_TEMP 100.0
#define MAX_TEMP 150.0
#define MIN_TEMP 50.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold PID parameters
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDParameters;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

// Function prototypes
int read_thermocouple(int spi_handle);
double calculate_pid(double setpoint, double current_temperature, PIDState *pid_state, PIDParameters pid_parameters);
void control_relay(int gpio_pin, double duty_cycle);
void log_data(double temperature);
void load_target_profile(const char *filename, double *time_seconds, double *target_temperatures, int *num_points);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_thermocouple(int spi_handle) {
    unsigned char tx_buffer[4];
    unsigned char rx_buffer[4];

    // MAX6675 SPI protocol: 3 bytes of data, 1 byte of clocking
    tx_buffer[0] = 0x00; // Dummy byte for clocking
    tx_buffer[1] = 0x00; // Dummy byte for clocking
    tx_buffer[2] = 0x00; // Dummy byte for clocking

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 14-bit thermocouple temperature (bits 13-4 of rx_buffer[1])
    int raw_temperature = ((rx_buffer[1] & 0x3F) << 8) | rx_buffer[2];
    // Sign extend if negative
    if (raw_temperature & 0x2000) {
        raw_temperature |= 0xC000;
    }

    return raw_temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double current_temperature, PIDState *pid_state, PIDParameters pid_parameters) {
    double error = setpoint - current_temperature;
    pid_state->integral += error;
    double derivative = error - pid_state->previous_error;
    double output = pid_parameters.Kp * error + pid_parameters.Ki * pid_state->integral + pid_parameters.Kd * derivative;

    // Clamp output to avoid windup
    if (output > 1.0) output = 1.0;
    if (output < 0.0) output = 0.0;

    pid_state->previous_error = error;
    return output;
}

// Function to control the solid-state relay
void control_relay(int gpio_pin, double duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to log data to a file
void log_data(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load target temperature profile from a file
void load_target_profile(const char *filename, double *time_seconds, double *target_temperatures, int *num_points) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    *num_points = 0;
    while (fscanf(fp, "%lf,%lf\n", time_seconds + *num_points, target_temperatures + *num_points) == 2) {
        (*num_points)++;
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize PID state
    PIDState pid_state = {0.0, 0.0};
    PIDParameters pid_parameters = {KP, KI, KD};

    // Load target temperature profile
    double *time_seconds = NULL;
    double *target_temperatures = NULL;
    int num_points = 0;
    load_target_profile(TARGET_FILE, &time_seconds, &target_temperatures, &num_points);

    // Allocate memory for PID output
    double *pid_output = (double *)malloc(num_points * sizeof(double));
    if (pid_output == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main control loop
    while (!terminate) {
        // Read temperature from thermocouple
        int raw_temperature = read_thermocouple(spi_handle);
        if (raw_temperature < 0) {
            fprintf(stderr, "Error: Failed to read thermocouple, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert raw temperature to Celsius
        double temperature = (double)raw_temperature / 16.0;

        // Calculate PID output
        pid_output[0] = calculate_pid(TARGET_TEMP, temperature, &pid_state, pid_parameters);

        // Control relay based on PID output
        control_relay(RELAY_GPIO, pid_output[0]);

        // Log data
        log_data(temperature);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("Cleaning up...\n");
    free(pid_output);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

