#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/w1-gpio.h>
#include <pigpio.h>

#define DS18B20_BUS "/sys/bus/w1/devices/"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char path[256];
    char buf[256];
    int fd;
    int ret;

    snprintf(path, sizeof(path), "%s%s", DS18B20_BUS, "28-000004281022");

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    ret = read(fd, buf, sizeof(buf) - 1);
    if (ret < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    buf[ret] = '\0';

    if (strstr(buf, "NO") != NULL) {
        fprintf(stderr, "Sensor not present or bus error\n");
        return -1;
    }

