#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define AHT20_ADDR        0x3C
#define I2C_BUS           "/dev/i2c-1"
#define GPIO_CHIP         "gpiochip4"
#define DEHUMIDIFIER_PIN   17
#define HUMIDITY_HIGH     60.0f
#define HUMIDITY_LOW      55.0f
#define MEASUREMENT_DELAY_MS 80
#define POLL_INTERVAL_S   5
#define MAX_RETRIES       3
#define RETRY_DELAY_MS    10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(uint8_t byte) {
    if (write(i2c_fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_read_humidity(float *humidity) {
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(0x35) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2c_read_bytes(data, 6) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if ((data[0] & 0x03) != 0x03) {
            fprintf(stderr, "AHT20 measurement not ready (status=0x%02X)\n", data[0]);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        uint32_t raw_temp = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65536.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_humidity(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
    fflush(stdout);
}

static void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH) {
        if (gpiod_line_set_value(relay_line, 1) < 0) {
            fprintf(stderr, "Failed to activate dehumidifier: %s\n", strerror(errno));
        } else {
            printf("Dehumidifier activated\n");
        }
    } else if (humidity < HUMIDITY_LOW) {
        if (gpiod_line_set_value(relay_line, 0) < 0) {
            fprintf(stderr, "Failed to deactivate dehumidifier: %s\n", strerror(errno));
        } else {
            printf("Dehumidifier deactivated\n");
        }
    }
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, DEHUMIDIFIER_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DEHUMIDIFIER_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", DEHUMIDIFIER_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Dehumidifier control system started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(&humidity) == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity. Check sensor wiring and address.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

