#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTTP_SERVER_ADDR "api.example.com"
#define HTTP_SERVER_PORT 80
#define POLL_INTERVAL_SEC 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int http_sock = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t cmd) {
    if (write(i2c_fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *buf, size_t len) {
    ssize_t n = read(i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_htu21d(float *humidity) {
    uint8_t data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(0xE3) < 0) {
            retries++;
            sleep(1);
            continue;
        }
        usleep(15000);

        if (i2c_read_data(data, 3) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        if (crc8(data, 2) != data[2]) {
            syslog(LOG_ERR, "HTU21D CRC mismatch");
            retries++;
            sleep(1);
            continue;
        }

        uint16_t raw_humidity = (data[0] << 8) | data[1];
        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;
        return 0;
    }

    syslog(LOG_ERR, "HTU21D read failed after %d retries", MAX_RETRIES);
    return -1;
}

static int send_http_request(const char *json_data) {
    struct sockaddr_in servaddr;
    char request[512];

    http_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (http_sock < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(HTTP_SERVER_PORT);

    if (inet_pton(AF_INET, HTTP_SERVER_ADDR, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", HTTP_SERVER_ADDR);
        close(http_sock);
        http_sock = -1;
        return -1;
    }

    if (connect(http_sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection to server failed: %s", strerror(errno));
        close(http_sock);
        http_sock = -1;
        return -1;
    }

    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             HTTP_SERVER_ADDR, strlen(json_data), json_data);

    ssize_t sent = send(http_sock, request, strlen(request), 0);
    if (sent < 0 || (size_t)sent != strlen(request)) {
        syslog(LOG_ERR, "HTTP request send failed: %s", strerror(errno));
        close(http_sock);
        http_sock = -1;
        return -1;
    }

    char response[1024];
    ssize_t total = 0;
    while (total < sizeof(response) - 1) {
        ssize_t n = recv(http_sock, response + total, sizeof(response) - 1 - total, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "HTTP response receive failed: %s", strerror(errno));
            close(http_sock);
            http_sock = -1;
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "HTTP response received with 0 bytes");
            close(http_sock);
            http_sock = -1;
            return -1;
        }
        total += n;
    }
    response[total] = '\0';

    syslog(LOG_INFO, "HTTP response: %s", response);

    close(http_sock);
    http_sock = -1;
    return 0;
}

int main(void) {
    openlog("htu21d_http", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        closelog();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D HTTP sensor monitoring started");

    while (running) {
        float humidity;
        if (read_htu21d(&humidity) == 0) {
            char json_data[64];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);
            if (send_http_request(json_data) == 0) {
                syslog(LOG_INFO, "HTTP POST sent successfully: %s", json_data);
            } else {
                syslog(LOG_ERR, "HTTP POST failed");
            }
        } else {
            syslog(LOG_ERR, "Failed to read HTU21D sensor");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (http_sock >= 0) {
        close(http_sock);
        http_sock = -1;
    }
    closelog();
    return 0;
}

