#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x39
#define PIR_GPIO_LINE 17
#define PIR_CHIP "gpiochip4"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd_tmp117 = -1;
static int i2c_fd_aht20 = -1;
static struct gpiod_chip *pir_chip = NULL;
static struct gpiod_line *pir_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_temperature(float *temperature) {
    uint8_t data[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(i2c_fd_tmp117, 0x00, (uint16_t *)data) == 0) {
            *temperature = (float)((int16_t)data[0] << 8 | data[1]) / 16.0f;
            return 0;
        }
        fprintf(stderr, "TMP117 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_humidity(float *humidity) {
    uint8_t data[3];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(i2c_fd_aht20, 0x00, (uint16_t *)data) == 0) {
            uint16_t raw_humidity = ((uint16_t)data[0] << 8) | data[1];
            *humidity = (float)raw_humidity / 1048576.0f;
            return 0;
        }
        fprintf(stderr, "AHT20 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_pir_sensor(int *motion_detected) {
    int ret = gpiod_line_get_value(pir_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to read PIR sensor: %s\n", strerror(errno));
        return -1;
    }
    *motion_detected = ret;
    return 0;
}

static int log_data(float temperature, float humidity, int motion_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    char timestamp[32];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(filename, sizeof(filename), "logger_%Y%m%d.csv", timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_fd_tmp117 >= 0) {
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
    }
    if (i2c_fd_aht20 >= 0) {
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (pir_chip != NULL) {
        gpiod_chip_close(pir_chip);
        pir_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd_tmp117 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd_tmp117, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_reg8(i2c_fd_tmp117, 0x01, 0x00) < 0) {
        fprintf(stderr, "Failed to write to TMP117 config register\n");
        cleanup();
        return 1;
    }

    i2c_fd_aht20 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd_aht20, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    pir_chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (pir_chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", PIR_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(pir_chip, PIR_GPIO_LINE);
    if (pir_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;
        int motion_detected;

        if (read_temperature(&temperature) == 0 &&
            read_humidity(&humidity) == 0 &&
            read_pir_sensor(&motion_detected) == 0) {

            if (log_data(temperature, humidity, motion_detected) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

