        fprintf(stderr, "Failed to close file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_fd_tmp117 >= 0) {
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
    }
    if (i2c_fd_aht20 >= 0) {
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (pir_chip != NULL) {
        gpiod_chip_close(pir_chip);
        pir_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd_tmp117 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd_tmp117, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_reg8(i2c_fd_tmp117, 0x01, 0x00) < 0) {
        fprintf(stderr, "Failed to write to TMP117 config register\n");
        cleanup();
        return 1;
    }

    i2c_fd_aht20 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd_aht20, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    pir_chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (pir_chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", PIR_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(pir_chip, PIR_GPIO_LINE);
    if (pir_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;
        int motion_detected;

        if (read_temperature(&temperature) == 0 &&
            read_humidity(&humidity) == 0 &&
            read_pir_sensor(&motion_detected) == 0) {

            if (log_data(temperature, humidity, motion_detected) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

