#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27
#define PWM_RANGE  255
#define SAMPLE_US  500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(float *load)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *name = strtok(line, " ");
    if (!name) {
        fprintf(stderr, "Error parsing /proc/stat: invalid format\n");
        return -1;
    }

    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "%*s %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat: invalid format\n");
        return -1;
    }

    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    FILE *fp2 = fopen("/proc/stat", "r");
    if (!fp2) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (!fgets(line, sizeof(line), fp2)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp2);
        return -1;
    }
    fclose(fp2);

    name = strtok(line, " ");
    if (!name) {
        fprintf(stderr, "Error parsing /proc/stat: invalid format\n");
        return -1;
    }

    if (sscanf(line, "%*s %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat: invalid format\n");
        return -1;
    }

    unsigned long total_prev = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long total_curr = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    if (total_prev == 0) {
        *load = 0.0f;
        return 0;
    }

    *load = 100.0f * (float)(total_curr - total_prev) / (float)total_prev;
    return 0;
}

static int map_load_to_color(float load, int *r, int *g, int *b)
{
    if (load < 0.0f) load = 0.0f;
    if (load > 100.0f) load = 100.0f;

    if (load <= 50.0f) {
        *r = 0;
        *g = (int)(255.0f * (load / 50.0f));
        *b = 0;
    } else if (load <= 100.0f) {
        *r = (int)(255.0f * ((load - 50.0f) / 50.0f));
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = 0;
        *b = (int)(255.0f * ((load - 100.0f) / 100.0f));
    }

    if (*r > PWM_RANGE) *r = PWM_RANGE;
    if (*g > PWM_RANGE) *g = PWM_RANGE;
    if (*b > PWM_RANGE) *b = PWM_RANGE;

    return 0;
}

static int set_led_color(int r, int g, int b)
{
    if (gpioPWM(RED_PIN, r) < 0) {
        fprintf(stderr, "Error setting PWM on RED pin: %s\n", pigpio_error(r));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        fprintf(stderr, "Error setting PWM on GREEN pin: %s\n", pigpio_error(g));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        fprintf(stderr, "Error setting PWM on BLUE pin: %s\n", pigpio_error(b));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Turn off LED (all channels full off for common anode) */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting RED pin mode: %s\n", pigpio_error(RED_PIN));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GREEN pin mode: %s\n", pigpio_error(GREEN_PIN));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting BLUE pin mode: %s\n", pigpio_error(BLUE_PIN));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on RED pin: %s\n", pigpio_error(RED_PIN));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GREEN pin: %s\n", pigpio_error(GREEN_PIN));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on BLUE pin: %s\n", pigpio_error(BLUE_PIN));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float load;
    int r, g, b;

    while (g_running) {
        if (read_cpu_load(&load) < 0) {
            fprintf(stderr, "Error reading CPU load, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (map_load_to_color(load, &r, &g, &b) < 0) {
            fprintf(stderr, "Error mapping load to color, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Error setting LED color, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

