    if (!fp2) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (!fgets(line, sizeof(line), fp2)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp2);
        return -1;
    }
    fclose(fp2);

    name = strtok(line, " ");
    if (!name) {
        fprintf(stderr, "Error parsing /proc/stat: invalid format\n");
        return -1;
    }

    if (sscanf(line, "%*s %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat: invalid format\n");
        return -1;
    }

    unsigned long total_prev = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long total_curr = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    if (total_prev == 0) {
        *load = 0.0f;
        return 0;
    }

    *load = 100.0f * (float)(total_curr - total_prev) / (float)total_prev;
    return 0;
}

static int map_load_to_color(float load, int *r, int *g, int *b)
{
    if (load < 0.0f) load = 0.0f;
    if (load > 100.0f) load = 100.0f;

    if (load <= 50.0f) {
        *r = 0;
        *g = (int)(255.0f * (load / 50.0f));
        *b = 0;
    } else if (load <= 100.0f) {
        *r = (int)(255.0f * ((load - 50.0f) / 50.0f));
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = 0;
        *b = (int)(255.0f * ((load - 100.0f) / 100.0f));
    }

    if (*r > PWM_RANGE) *r = PWM_RANGE;
    if (*g > PWM_RANGE) *g = PWM_RANGE;
    if (*b > PWM_RANGE) *b = PWM_RANGE;

    return 0;
}

static int set_led_color(int r, int g, int b)
