    if (gpioPWM(RED_PIN, r) < 0) {
        fprintf(stderr, "Error setting PWM on RED pin: %s\n", pigpio_error(r));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        fprintf(stderr, "Error setting PWM on GREEN pin: %s\n", pigpio_error(g));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        fprintf(stderr, "Error setting PWM on BLUE pin: %s\n", pigpio_error(b));
        return -1;
    }
    return 0;
}

