    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting BLUE pin mode: %s\n", pigpio_error(BLUE_PIN));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on RED pin: %s\n", pigpio_error(RED_PIN));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GREEN pin: %s\n", pigpio_error(GREEN_PIN));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on BLUE pin: %s\n", pigpio_error(BLUE_PIN));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float load;
    int r, g, b;

    while (g_running) {
        if (read_cpu_load(&load) < 0) {
            fprintf(stderr, "Error reading CPU load, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (map_load_to_color(load, &r, &g, &b) < 0) {
            fprintf(stderr, "Error mapping load to color, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Error setting LED color, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

