#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read error (reg 0x%02X, len %u): %s\n", reg, len, strerror(errno));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C block read short: got %d, expected %u\n", rc, len);
        return -1;
    }
    return 0;
}

static int bmp280_init(int handle) {
    uint8_t chip_id;
    if (i2c_read_reg(handle, BMP280_REG_ID, &chip_id) < 0) return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) return -1;
    gpioDelay(2000);

    uint8_t calib[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, calib, 24) < 0) return -1;

    int32_t dig_T1 = (calib[1] << 8) | calib[0];
    int16_t dig_T2 = (calib[3] << 8) | calib[2];
    int16_t dig_T3 = (calib[5] << 8) | calib[4];
    int16_t dig_P1 = (calib[7] << 8) | calib[6];
    int16_t dig_P2 = (calib[9] << 8) | calib[8];
    int16_t dig_P3 = (calib[11] << 8) | calib[10];
    int16_t dig_P4 = (calib[13] << 8) | calib[12];
    int16_t dig_P5 = (calib[15] << 8) | calib[14];
    int16_t dig_P6 = (calib[17] << 8) | calib[16];
    int16_t dig_P7 = (calib[19] << 8) | calib[18];
    int16_t dig_P8 = (calib[21] << 8) | calib[20];
    int16_t dig_P9 = (calib[23] << 8) | calib[22];

    if (i2c_write_reg(handle, 0xF5, 0x27) < 0) return -1;
    if (i2c_write_reg(handle, 0xF4, 0xA0) < 0) return -1;

    return 0;
}

static int bmp280_read_raw(int handle, int32_t *raw_temp, int32_t *raw_press) {
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    gpioDelay(5000);

    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static int32_t compensate_temperature(int32_t raw_temp, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
