    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    return (uint32_t)(p >> 8);
}

static int send_udp_data(const char *data) {
    if (udp_socket < 0) return -1;
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid UDP address: %s\n", UDP_SERVER_IP);
        return -1;
    }
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "UDP send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (bmp280_init(i2c_handle) < 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP280 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw_temp, raw_press, t_fine;
        if (bmp280_read_raw(i2c_handle, &raw_temp, &raw_press) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
        } else {
            int32_t temp_centi = compensate_temperature(raw_temp, &t_fine);
            uint32_t press_pa = compensate_pressure(raw_press, t_fine);
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"pressure\": %u}", temp_centi / 100.0, press_pa);
            if (send_udp_data(json_data) < 0) {
                fprintf(stderr, "Failed to send UDP data\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

