#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      500000
#define SPI_FLAGS      0
#define FAN_GPIO       18
#define PWM_FREQUENCY  1000
#define PWM_RANGE      255
#define BUFFER_SIZE    20
#define TEMP_THRESHOLD 25.0f
#define TEMP_MIN       25.0f
#define TEMP_MAX       60.0f
#define TEMP_STEP      10.0f
#define SAMPLE_PERIOD  1.0

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} TemperatureData;

static TemperatureData temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int read_max31855(float *temperature) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4] = {0, 0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                   ((uint32_t)(uint8_t)rx_buf[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }

    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_THRESHOLD) {
        return 0;
    } else if (temperature < TEMP_MIN) {
        return (int)((temperature - TEMP_THRESHOLD) / (TEMP_MIN - TEMP_THRESHOLD) * 50.0f);
    } else if (temperature < TEMP_MAX) {
        return 50 + (int)((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * 150.0f);
    } else {
        return 200;
    }
}

static void set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty_cycle);
    }
}

static void add_to_buffer(time_t timestamp, float temperature, int pwm_duty) {
    temperature_buffer[buffer_index].timestamp = timestamp;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Temperature Data Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *timeinfo = localtime(&temperature_buffer[index].timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temp: %.2f C, PWM: %d\n", time_str, temperature_buffer[index].temperature, temperature_buffer[index].pwm_duty);
    }
    printf("--- End of Buffer ---\n\n");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(&temperature) == 0) {
            int pwm_duty = calculate_pwm_duty(temperature);
            set_fan_speed(pwm_duty);
            time_t now = time(NULL);
            add_to_buffer(now, temperature, pwm_duty);
            printf("Temperature: %.2f C, PWM: %d\n", temperature, pwm_duty);
        } else {
            fprintf(stderr, "Failed to read temperature from MAX31855\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    print_buffer();
    return EXIT_SUCCESS;
}

