#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int logging_active = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    ac1 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 1));
    ac2 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC2) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC2 + 1));
    ac3 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC3) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC3 + 1));
    ac4 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC4) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC4 + 1));
    ac5 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC5) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC5 + 1));
    ac6 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC6) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC6 + 1));
    b1 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_B1) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_B1 + 1));
    b2 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_B2) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_B2 + 1));
    mb = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_MB) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_MB + 1));
    mc = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_MC) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_MC + 1));
    md = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_MD) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_MD + 1));
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char cmd = 0x2E;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd = 0x34 + (OSS << 6);
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    char buf[3];
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) return -1;
    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    *up >>= (8 - OSS);
    return 0;
}

static int calculate_b5(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    *b5_out = x1 + x2;
    return 0;
}

static int calculate_temperature(int32_t ut, float *temp_out) {
    int32_t b5;
    if (calculate_b5(ut, &b5) != 0) return -1;
    *temp_out = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

static int calculate_pressure(int32_t up, int32_t ut, float *press_out) {
    int32_t b5;
    if (calculate_b5(ut, &b5) != 0) return -1;
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *press_out = p + ((x1 + x2 + 3791) >> 4);
    return 0;
}

static void log_data(float temp, float press) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, press);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_active = !logging_active;
    printf("Logging %s\n", logging_active ? "started" : "stopped");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    if (gpioSetISRFuncEx(2, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("BMP180 logging started. Press Ctrl+C to exit.\n");
    while (running) {
        if (logging_active) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) != 0 || read_raw_pressure(&up) != 0) {
                fprintf(stderr, "I2C read error\n");
            } else {
                float temp, press;
                if (calculate_temperature(ut, &temp) != 0 || calculate_pressure(up, ut, &press) != 0) {
                    fprintf(stderr, "Calculation error\n");
                } else {
                    log_data(temp, press);
                }
            }
        }
        gpioDelay(1000000);
    }
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

