#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 50000
#define DEVIATION_THRESHOLD_HPA 5.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

static PressureData pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int read_calibration_data(void);
static int read_raw_temperature(int32_t *ut);
static int read_raw_pressure(int32_t *up);
static float calculate_pressure(int32_t ut, int32_t up);
static float calculate_average_pressure(void);
static void check_pressure_deviation(float current_pressure);
static void signal_handler(int signal);
static void timer_callback(void *user_data);

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL);
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();

    printf("BMP180 monitoring stopped.\n");
    return EXIT_SUCCESS;
}

static int read_calibration_data(void) {
    ac1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    mb = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mc = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    md = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == 0 || ac1 == 0xFFFF || ac2 == 0 || ac2 == 0xFFFF || ac3 == 0 || ac3 == 0xFFFF ||
        ac4 == 0 || ac4 == 0xFFFF || ac5 == 0 || ac5 == 0xFFFF || ac6 == 0 || ac6 == 0xFFFF ||
        b1 == 0 || b1 == 0xFFFF || b2 == 0 || b2 == 0xFFFF || mb == 0 || mb == 0xFFFF ||
        mc == 0 || mc == 0xFFFF || md == 0 || md == 0xFFFF) {
        fprintf(stderr, "Invalid calibration data read\n");
        return -1;
    }

    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        return -1;
    }
    gpioDelay(5000);

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        return -1;
    }

    *ut = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34) != 0) {
        return -1;
    }
    gpioDelay(5000);

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        return -1;
    }

    *up = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p / 100.0f;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / buffer_count;
}

static void check_pressure_deviation(float current_pressure) {
    float average_pressure = calculate_average_pressure();
    float deviation = fabsf(current_pressure - average_pressure);
    if (deviation > DEVIATION_THRESHOLD_HPA) {
        time_t now = time(NULL);
        pressure_buffer[buffer_index].timestamp = now;
        pressure_buffer[buffer_index].pressure = current_pressure;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "ALERT: Pressure deviation exceeded threshold! Current: %.2f hPa, Average: %.2f hPa\n",
                current_pressure, average_pressure);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void timer_callback(void *user_data) {
