static int read_calibration_data(void) {
    ac1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    mb = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mc = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    md = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == 0 || ac1 == 0xFFFF || ac2 == 0 || ac2 == 0xFFFF || ac3 == 0 || ac3 == 0xFFFF ||
        ac4 == 0 || ac4 == 0xFFFF || ac5 == 0 || ac5 == 0xFFFF || ac6 == 0 || ac6 == 0xFFFF ||
        b1 == 0 || b1 == 0xFFFF || b2 == 0 || b2 == 0xFFFF || mb == 0 || mb == 0xFFFF ||
        mc == 0 || mc == 0xFFFF || md == 0 || md == 0xFFFF) {
        fprintf(stderr, "Invalid calibration data read\n");
        return -1;
    }

    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        return -1;
    }
    gpioDelay(5000);

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        return -1;
    }

    *ut = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34) != 0) {
        return -1;
    }
    gpioDelay(5000);

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        return -1;
    }

    *up = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p / 100.0f;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / buffer_count;
}

static void check_pressure_deviation(float current_pressure) {
    float average_pressure = calculate_average_pressure();
    float deviation = fabsf(current_pressure - average_pressure);
    if (deviation > DEVIATION_THRESHOLD_HPA) {
        time_t now = time(NULL);
        pressure_buffer[buffer_index].timestamp = now;
        pressure_buffer[buffer_index].pressure = current_pressure;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "ALERT: Pressure deviation exceeded threshold! Current: %.2f hPa, Average: %.2f hPa\n",
                current_pressure, average_pressure);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0 || read_raw_pressure(&up) != 0) {
        fprintf(stderr, "I2C read error, skipping sample\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    check_pressure_deviation(pressure);
}

