#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TEMPERATURE_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define LOG_FILE "fan_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temperature(void) {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli;
}

static int map_temperature_to_duty_cycle(float temperature) {
    if (temperature < TEMP_MIN) temperature = TEMP_MIN;
    if (temperature > TEMP_MAX) temperature = TEMP_MAX;

    float duty_cycle = (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * PWM_RANGE;
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    return (int)duty_cycle;
}

static int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("Error getting local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        fclose(log_file);
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        fclose(log_file);
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_cpu_temperature();
        if (temp_milli < 0) {
            fprintf(stderr, "Failed to read CPU temperature, skipping cycle\n");
        } else {
            float temperature = temp_milli / 1000.0;
            int duty_cycle = map_temperature_to_duty_cycle(temperature);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Fan control system stopped.\n");

    return EXIT_SUCCESS;
}

