#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_BUS        "/dev/i2c-1"
#define BMP280_I2C_ADDR_GND   0x76
#define BMP280_I2C_ADDR_ALT   0x77
#define BMP280_REG_ID         0xD0
#define BMP280_REG_RESET      0xE0
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_CONFIG     0xF5
#define BMP280_REG_PRESS_MSB  0xF7
#define BMP280_REG_TEMP_MSB   0xFA
#define BMP280_REG_CALIB      0x88

#define BMP280_CHIP_ID        0x60
#define BMP280_RESET_CMD      0xB6

#define LOG_FILE             "weather_data.txt"
#define SAMPLE_INTERVAL_SEC  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &chip_id) < 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        return -1;
    }
    usleep(2000);

    uint8_t config;
    if (i2c_read_reg8(fd, BMP280_REG_CONFIG, &config) < 0) {
        return -1;
    }
    config |= 0x04; /* t_sb = 500ms (001) */
    config |= 0x02; /* filter = off (001) */
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, config) < 0) {
        return -1;
    }

    uint8_t ctrl_meas;
    if (i2c_read_reg8(fd, BMP280_REG_CTRL_MEAS, &ctrl_meas) < 0) {
        return -1;
    }
    ctrl_meas |= 0x27; /* osrs_t = x1 (011), osrs_p = x1 (011), mode = forced (11) */
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        return -1;
    }

    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];
    if (i2c_read_burst(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        return -1;
    }
    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static int bmp280_compensate(int32_t raw_temp, int32_t raw_press,
                            const uint16_t *dig_T1, const int16_t *dig_T2, const int16_t *dig_T3,
                            const uint16_t *dig_P1, const int16_t *dig_P2, const int16_t *dig_P3,
                            const int16_t *dig_P4, const int16_t *dig_P5, const int16_t *dig_P6,
                            const int16_t *dig_P7, const int16_t *dig_P8, const int16_t *dig_P9,
                            double *temp_c, double *press_hpa) {
    double var1, var2, t_fine;
    var1 = ((double)raw_temp / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    var2 = (((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) *
            ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0)) * (double)dig_T3;
    t_fine = var1 + var2;
    *temp_c = t_fine / 5120.0;

    var1 = t_fine / 2.0 - 64000.0;
    var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)dig_P4 * 65536.0);
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) {
        return -1;
    }
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;

    *press_hpa = p / 100.0;
    return 0;
}

static int log_data(const char *filename, double temp_c, double press_hpa) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                timestamp, temp_c, press_hpa) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
