#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define ALERT_GPIO     18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

#define LM75_REG_TEMP  0x00
#define LM75_REG_CONF  0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alert_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t reg = LM75_REG_TEMP;
    uint8_t data[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw / 16.0f;
    return 0;
}

static void add_to_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

static float calculate_average(void) {
    float sum = 0.0f;
    int count = 0;

    pthread_mutex_lock(&buffer_mutex);
    count = buffer_count;
    for (int i = 0; i < count; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);

    if (count > 0) {
        return sum / count;
    }
    return 0.0f;
}

static void *alert_thread_func(void *arg) {
    (void)arg;
    while (running) {
        float avg = calculate_average();
        bool alert = (avg > TEMP_THRESHOLD);

        if (gpiod_line_set_value(alert_line, alert ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set alert GPIO: %s\n", strerror(errno));
        }
        sleep(1);
    }
    return NULL;
}

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
        alert_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_destroy(&buffer_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_fd, LM75_REG_CONF, 0x00) < 0) {
        fprintf(stderr, "Failed to configure LM75: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!alert_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALERT_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alert_line, "lm75_alert", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALERT_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pthread_t alert_thread;
    if (pthread_create(&alert_thread, NULL, alert_thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75 temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_fd, &temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Attempting re-initialization...\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            sleep(1);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %s\n", strerror(errno));
                break;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
