#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define ALERT_GPIO     18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

#define LM75_REG_TEMP  0x00
#define LM75_REG_CONF  0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alert_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t reg = LM75_REG_TEMP;
    uint8_t data[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw / 16.0f;
    return 0;
}

static void add_to_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

static float calculate_average(void) {
    float sum = 0.0f;
    int count = 0;

    pthread_mutex_lock(&buffer_mutex);
    count = buffer_count;
    for (int i = 0; i < count; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);

    if (count > 0) {
        return sum / count;
    }
    return 0.0f;
}

static void *alert_thread_func(void *arg) {
    (void)arg;
    while (running) {
        float avg = calculate_average();
        bool alert = (avg > TEMP_THRESHOLD);

        if (gpiod_line_set_value(alert_line, alert ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set alert GPIO: %s\n", strerror(errno));
