        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_fd, LM75_REG_CONF, 0x00) < 0) {
        fprintf(stderr, "Failed to configure LM75: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!alert_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALERT_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alert_line, "lm75_alert", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALERT_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pthread_t alert_thread;
    if (pthread_create(&alert_thread, NULL, alert_thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread: %s\n", strerror(errno));
