#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMPERATURE 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
} PIDConfig;

static PIDConfig pid_config = {25.0, 1.0, 0.1, 0.01};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int read_pt100(int spi_handle, float *temperature) {
    char tx[4] = {0x01, 0x80, 0x00, 0x00};
    char rx[4] = {0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        log_message("Error: SPI transfer failed");
        return -1;
    }

    uint32_t raw = ((uint32_t)(rx[0] & 0x03) << 16) | ((uint32_t)rx[1] << 8) | (uint32_t)rx[2];
    if (raw & 0x00010000) {
        log_message("Error: MAX31865 fault detected");
        return -1;
    }

    int16_t signed_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (signed_raw & 0x2000) {
        signed_raw |= 0xC000;
    }

    *temperature = (float)signed_raw * 0.25;
    return 0;
}

static float calculate_pid(float setpoint, float current_value, float *integral, float *previous_error, float dt) {
    float error = setpoint - current_value;
    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;
    float output = pid_config.kp * error + pid_config.ki * *integral + pid_config.kd * derivative;
    *previous_error = error;
    return output;
}

static void set_heater_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(gpio, duty_cycle);
}

static void cleanup(void) {
    set_heater_pwm(HEATER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_message("Program started");

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        log_message("Error: Failed to set heater GPIO mode");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        log_message("Error: Failed to set PWM frequency");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != PWM_RANGE) {
        log_message("Error: Failed to set PWM range");
        cleanup();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_message("Error: SPI open failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0, previous_error = 0.0;
    float dt = 0.1;

    while (running) {
        float temperature;
        if (read_pt100(spi_handle, &temperature) == 0) {
            float pid_output = calculate_pid(pid_config.target_temperature, temperature, &integral, &previous_error, dt);
            int duty_cycle = (int)(pid_output + 100.0);
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
            set_heater_pwm(HEATER_GPIO, duty_cycle);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Temperature: %.2f C, PID Output: %.2f, Duty Cycle: %d", temperature, pid_output, duty_cycle);
            log_message(log_message);
        } else {
            log_message("Error: Failed to read PT100 sensor");
            set_heater_pwm(HEATER_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

