    uint32_t x1_p = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_p = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_p = ((x1_p + x2_p) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3_p + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void log_breach(float temperature, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    if (read_calibration_data(i2c_fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int32_t ut, up, b5;
        if (read_raw_temperature(i2c_fd, &ut) < 0) {
            fprintf(stderr, "Error reading raw temperature\n");
            sleep(1);
            continue;
        }
        if (calculate_b5(ut, ac1, ac2, ac3, ac4, ac5, ac6, &b5) < 0) {
            fprintf(stderr, "Error calculating B5\n");
            sleep(1);
            continue;
        }
        float temperature = calculate_temperature(b5);
        if (read_raw_pressure(i2c_fd, &up) < 0) {
            fprintf(stderr, "Error reading raw pressure\n");
            sleep(1);
            continue;
        }
        float pressure = calculate_pressure(up, b5, ac1, ac2, ac3, ac4, ac5, ac6);

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            log_breach(temperature, pressure);
        }

        sleep(1);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    printf("Program terminated gracefully.\n");
    return 0;
}

