#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f
#define LOG_FILE "breach_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(10000);
            continue;
        }
        if (read(fd, buf, len) == len) return 0;
        usleep(10000);
    }
    return -1;
}

static int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, 0xAA, buf, 22) < 0) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    if (i2c_read_bytes(fd, 0xB0, buf, 22) < 0) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_byte(fd, 0xF4, 0x2E) < 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, 0xF6, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_byte(fd, 0xF4, 0x34) < 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, 0xF6, buf, 3) < 0) return -1;
    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int calculate_b5(int32_t ut, int16_t ac1, int16_t ac2, int16_t ac3, uint16_t ac4, uint16_t ac5, uint16_t ac6, int32_t *b5) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    *b5 = x1 + x2;
    return 0;
}

static float calculate_temperature(int32_t b5) {
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t b5, int16_t ac1, int16_t ac2, int16_t ac3, uint16_t ac4, uint16_t ac5, uint16_t ac6) {
    int32_t b6 = b5 - 4000;
