    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void log_breach(float temperature, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
