/*
 * BMP180 Temperature & Pressure Monitor for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - BMP180 on I2C bus 1, address 0x77
 *   - Cooling fan on GPIO18 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -o bmp180_monitor bmp180_monitor.c -lgpiod
 *
 * Run:
 *   sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP180_ADDR    0x77
#define FAN_GPIO       18
#define TEMP_THRESHOLD 30.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD_US 500000  /* 500 ms */

/* BMP180 registers */
#define BMP180_REG_CONTROL  0xF4
#define BMP180_REG_MSB      0xF6
#define BMP180_REG_LSB      0xF7
#define BMP180_REG_XLSB     0xF8
#define BMP180_REG_CAL_AC1  0xAA
#define BMP180_REG_CAL_AC2  0xAC
#define BMP180_REG_CAL_AC3  0xAE
#define BMP180_REG_CAL_AC4  0xB0
#define BMP180_REG_CAL_AC5  0xB2
#define BMP180_REG_CAL_AC6  0xB4
#define BMP180_REG_CAL_B1   0xB6
#define BMP180_REG_CAL_B2   0xB8
#define BMP180_REG_CAL_MB   0xBA
#define BMP180_REG_CAL_MC   0xBC
#define BMP180_REG_CAL_MD   0xBE

/* Calibration coefficients */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

/* Circular buffer entry */
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

/* Globals for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_fan_line = NULL;
static bmp180_cal_t g_cal;
static sensor_data_t g_buffer[BUFFER_SIZE];
static int g_buf_index = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 calibration                                                */
/* ------------------------------------------------------------------ */
static int bmp180_read_calibration(int fd, bmp180_cal_t *cal)
{
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, &cal->md) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 temperature (OSS=0)                                         */
/* ------------------------------------------------------------------ */
static int bmp180_read_temperature(int fd, int32_t *ut)
{
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);  /* 4.5 ms max conversion time */

    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 pressure (OSS=0)                                            */
/* ------------------------------------------------------------------ */
static int bmp180_read_pressure(int fd, int32_t *up)
{
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    usleep(5000);  /* 4.5 ms max conversion time */

    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (xlsb >> 4);
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 temperature + pressure (OSS=0)                              */
/* ------------------------------------------------------------------ */
static int bmp180_read_temperature_pressure(int fd, int32_t *ut, int32_t *up)
{
    if (bmp180_read_temperature(fd, ut) < 0) return -1;
    if (bmp180_read_pressure(fd, up) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 conversion (OSS=0)                                         */
/* ------------------------------------------------------------------ */
static int bmp180_compute(int32_t ut, int32_t up, const bmp180_cal_t *cal,
                          float *temperature, float *pressure)
{
    int32_t x1, x2, b5, b6, x3, b3, p;
    uint32_t b4, b7;

    x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    b5 = x1 + x2;
    *temperature = ((b5 + 8) >> 4) / 10.0f;

    b6 = b5 - 4000;
    x1 = ((int32_t)cal->b2 * (b6 * b6 >> 12)) >> 11;
    x2 = ((int32_t)cal->ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)cal->ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure = p + ((x1 + x2 + 3791) >> 4);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                    */
/* ------------------------------------------------------------------ */
static void buffer_add(sensor_data_t *data)
{
    g_buffer[g_buf_index] = *data;
    g_buf_index = (g_buf_index + 1) % BUFFER_SIZE;
}

static void buffer_print(void)
{
    printf("\n--- Sensor Data ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (g_buf_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temp: %.2f C, Pressure: %.2f Pa\n",
               ts, g_buffer[idx].temperature, g_buffer[idx].pressure);
    }
    printf("--- End of Data ---\n\n");
}

/* ------------------------------------------------------------------ */
/* Fan control via libgpiod                                           */
/* ------------------------------------------------------------------ */
static void fan_set(bool on)
{
    if (g_fan_line) {
        if (gpiod_line_set_value(g_fan_line, on ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set fan GPIO %d: %s\n",
                    FAN_GPIO, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Timer callback (fires every 500 ms)                                */
/* ------------------------------------------------------------------ */
static void timer_callback(void)
{
    int32_t ut, up;
    float temperature, pressure;

    if (bmp180_read_temperature_pressure(g_i2c_fd, &ut, &up) < 0) {
        fprintf(stderr, "BMP180 read error; skipping sample.\n");
        return;
    }

    if (bmp180_compute(ut, up, &g_cal, &temperature, &pressure) < 0) {
        fprintf(stderr, "BMP180 compute error; skipping sample.\n");
        return;
    }

    time_t now = time(NULL);
    sensor_data_t data = { .timestamp = now, .temperature = temperature, .pressure = pressure };
    buffer_add(&data);
    printf("[%ld] Temp: %.2f C, Pressure: %.2f Pa\n",
           (long)now, temperature, pressure);

    if (temperature > TEMP_THRESHOLD) {
        fan_set(true);
        printf("Temperature %.2f C exceeds threshold %.1f C; fan ON.\n",
               temperature, TEMP_THRESHOLD);
    } else {
        fan_set(false);
        printf("Temperature %.2f C within threshold %.1f C; fan OFF.\n",
               temperature, TEMP_THRESHOLD);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    fan_set(false);

    if (g_fan_line) {
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BMP180_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Read calibration */
    if (bmp180_read_calibration(g_i2c_fd, &g_cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request fan line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO);
    if (!g_fan_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                FAN_GPIO, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_fan_line, "bmp180_fan", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                FAN_GPIO, strerror(errno));
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(g_buffer, 0, sizeof(g_buffer));

    /* Initialize fan to OFF */
    fan_set(false);

    /* Start periodic timer */
    struct timespec ts = { .tv_sec = 0, .tv_nsec = SAMPLE_PERIOD_US * 1000 };
    if (timer_create(CLOCK_MONOTONIC, NULL, &g_timer) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (timer_settime(g_timer, 0, &ts, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        timer_delete(g_timer);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitor started. Press Ctrl+C to exit.\n");

    /* Main loop: wait for signal */
    while (g_running) {
        pause();
    }

    /* Cleanup */
    timer_delete(g_timer);
    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

