#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define INTERRUPT_PIN 27
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define DEBOUNCE_US 200000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int32_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;
static int32_t b5;
static int logging_enabled = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    ac1 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC1 + 1));
    ac2 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC2) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC2 + 1));
    ac3 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC3) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC3 + 1));
    ac4 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC4) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC4 + 1));
    ac5 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC5) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC5 + 1));
    ac6 = (uint16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC6) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_AC6 + 1));
    b1 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_B1) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_B1 + 1));
    b2 = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_B2) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_B2 + 1));
    mb = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_MB) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_MB + 1));
    mc = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_MC) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_MC + 1));
    md = (int16_t)((i2cReadByteData(i2c_handle, BMP180_REG_CAL_MD) << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_MD + 1));
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char cmd = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(5000);
    char buf[3];
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) return -1;
    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static double compute_pressure(int32_t up, int32_t ut) {
