#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define DEFAULT_TARGET_TEMP 25.0
#define SAFE_MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"
#define ERROR_TEMP -1000.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(rx[0] & 0x03) << 18) |
                   ((uint32_t)(rx[1] & 0xFF) << 10) |
                   ((uint32_t)(rx[2] & 0xFF) << 2)  |
                   ((uint32_t)(rx[3] & 0xC0) >> 6);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: open circuit\n");
        return -2;
    }
    if (raw & 0x00020000) {
        fprintf(stderr, "MAX31855 fault: short to ground\n");
        return -3;
    }
    if (raw & 0x00040000) {
        fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -4;
    }

    int16_t signed_temp = (int16_t)((raw >> 18) & 0x3FFF);
    if (signed_temp & 0x2000) {
        signed_temp |= 0xC000;
    }
    *temperature = (float)signed_temp * 0.25;
    return 0;
}

static float calculate_duty_cycle(float temperature, float target_temp) {
    if (temperature < target_temp) {
        return 0.0;
    }
    if (temperature > target_temp + 1.0) {
        return 100.0;
    }
    return (temperature - target_temp) / 1.0 * 100.0;
}

static void set_heater_duty_cycle(int gpio, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(gpio, pwm_value);
}

static void log_data(FILE *fp, float temperature, float duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioPWM(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float target_temp = DEFAULT_TARGET_TEMP;
    float temperature = ERROR_TEMP;
    float duty_cycle = 0.0;

    while (running) {
        temperature = ERROR_TEMP;
        int ret = read_max31855(spi_handle, &temperature);
        if (ret == 0) {
            duty_cycle = calculate_duty_cycle(temperature, target_temp);
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);
            log_data(log_file, temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature: %d\n", ret);
            set_heater_duty_cycle(HEATER_GPIO, 0.0);
            log_data(log_file, ERROR_TEMP, 0.0);
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

