#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define POLL_US    500000   /* 0.5 seconds */
#define PWM_RANGE  255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius.
 * Returns 0 on success, -1 on error.
 */
static int read_cpu_temp(float *temp_c)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[16];
    if (!fgets(buf, sizeof(buf), fp)) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        } else {
            fprintf(stderr, "Error reading %s: unexpected EOF\n", TEMP_FILE);
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    errno = 0;
    long millideg = strtol(buf, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error converting temperature: %s\n", strerror(errno));
        return -1;
    }

    *temp_c = (float)millideg / 1000.0f;
    return 0;
}

/*
 * Set PWM duty cycle for a given GPIO pin.
 * Returns 0 on success, -1 on error.
 */
static int set_pwm(int gpio, int duty)
