#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int last_state = 1;
    int timeout_count = 0;

    /* Send start signal: pull low for >= 1ms, then high for 20-40us */
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(2000); /* 2ms low */
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); /* 30us high */
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    /* Wait for sensor response: low for ~80us, then high for ~80us */
    timeout_count = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        if (++timeout_count > 100) return -1;
        gpioDelay(1);
    }
    timeout_count = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        if (++timeout_count > 100) return -1;
        gpioDelay(1);
    }
    timeout_count = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        if (++timeout_count > 100) return -1;
        gpioDelay(1);
    }

    /* Read 40 bits */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Wait for low-to-high transition (end of low pulse) */
        timeout_count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            if (++timeout_count > 100) return -1;
            gpioDelay(1);
        }

        /* Measure high pulse width: ~26-28us = '0', ~70us = '1' */
        timeout_count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            if (++timeout_count > 100) return -1;
            gpioDelay(1);
        }

        int pulse_width = timeout_count;
        if (pulse_width > 50) {
            data[byte_idx] |= (1 << (7 - bit_idx));
        }
        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    /* Validate checksum */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        return -2;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

static int send_http_request(float humidity, float temperature) {
    int sockfd = -1;
    struct sockaddr_in servaddr;
    char request[256];
    char response[1024];
    int ret = -1;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        goto cleanup;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection failed");
        goto cleanup;
    }

    snprintf(request, sizeof(request),
             "POST /api/humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: 32\r\n"
             "\r\n"
             "{\"humidity\": %.2f, \"temperature\": %.2f}",
             SERVER_IP, humidity, temperature);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        perror("Send failed");
        goto cleanup;
    }

    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        goto cleanup;
    }
    response[bytes_received] = '\0';

    if (strstr(response, "HTTP/1.1 200 OK") != NULL) {
        ret = 0;
    } else {
        fprintf(stderr, "HTTP request failed: %s\n", response);
    }

cleanup:
    if (sockfd >= 0) {
        close(sockfd);
    }
    return ret;
}

int main(void) {
    float humidity, temperature;
    int retries;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("DHT22 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_dht22(&humidity, &temperature) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "DHT22 read failed (attempt %d/%d), retrying...\n",
                        retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (success) {
            printf("Humidity: %.2f%%, Temperature: %.2f C\n", humidity, temperature);
            if (send_http_request(humidity, temperature) != 0) {
                fprintf(stderr, "HTTP request failed after %d retries\n", MAX_RETRIES);
            }
        } else {
            fprintf(stderr, "DHT22 read failed after %d retries\n", MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

