/*
 * BMP180 Pressure Logger for Raspberry Pi 4 Model B
 * Uses I2C bus 1, BMP180 at address 0x77, OSS=3, falling-edge interrupt on GPIO4.
 * Logs to pressure_log.txt every 2 seconds.
 *
 * Build: gcc -O2 -Wall -o bmp180_logger bmp180_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BMP180_ADDR        0x77
#define BMP180_REG_CONTROL  0xF4
#define BMP180_REG_MSB      0xF6
#define BMP180_REG_LSB      0xF7
#define BMP180_REG_XLSB     0xF8
#define BMP180_REG_CAL_AC1  0xAA
#define BMP180_REG_CAL_AC2  0xAC
#define BMP180_REG_CAL_AC3  0xAE
#define BMP180_REG_CAL_AC4  0xB0
#define BMP180_REG_CAL_AC5  0xB2
#define BMP180_REG_CAL_AC6  0xB4
#define BMP180_REG_CAL_B1   0xB6
#define BMP180_REG_CAL_B2   0xB8
#define BMP180_REG_CAL_MB   0xBA
#define BMP180_REG_CAL_MC   0xBC
#define BMP180_REG_CAL_MD   0xBE

#define OSS                 3
#define INTERRUPT_PIN       4
#define DEBOUNCE_US         200000
#define LOG_INTERVAL_S      2
#define CONVERSION_DELAY_US (26000 + (3 << (8 - OSS)))

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *int_line = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2c_read_block(BMP180_REG_CAL_AC1, buf, 22) < 0)
        return -1;

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    if (ac1 == 0 || ac1 == 0xFFFF || ac4 == 0 || ac4 == 0xFFFF) {
        fprintf(stderr, "Invalid calibration data (sensor absent or bus error)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2c_write_reg(BMP180_REG_CONTROL, 0x2E) < 0)
        return -1;
    usleep(CONVERSION_DELAY_US);

    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg(BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg(BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg(BMP180_REG_XLSB, &xlsb) < 0) return -1;

    *ut = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | xlsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2c_write_reg(BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0)
        return -1;
    usleep(CONVERSION_DELAY_US);

    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg(BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg(BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg(BMP180_REG_XLSB, &xlsb) < 0) return -1;

    *up = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | xlsb;
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (double)p / 100.0;
}

static void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file);
    printf("%s, %.2f hPa\n", timestamp, pressure);
}

static void interrupt_handler(void) {
    static uint32_t last_tick = 0;
    uint32_t now = gpiod_line_get_value_tick(int_line);
    if (now - last_tick < DEBOUNCE_US)
        return;
    last_tick = now;

    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0 || read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Interrupt read error, retrying...\n");
        return;
    }

    double pressure = calculate_pressure(up, ut);
    log_pressure(pressure);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (int_line) {
        gpiod_line_release(int_line);
        int_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (read_calibration_data() < 0) {
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }

    int_line = gpiod_chip_get_line(chip, INTERRUPT_PIN);
    if (!int_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(int_line, "bmp180_logger") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        cleanup();
        return 1;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("fopen pressure_log.txt");
        cleanup();
        return 1;
    }

    printf("BMP180 logger started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec ts = {LOG_INTERVAL_S, 0};
        nanosleep(&ts, NULL);

        if (log_file) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) < 0 || read_raw_pressure(&up) < 0) {
                fprintf(stderr, "Read error, skipping logging cycle\n");
                continue;
            }

            double pressure = calculate_pressure(up, ut);
            log_pressure(pressure);
        } else {
            printf("Logging disabled.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

