#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10
#define API_CALL_TIMEOUT_SEC 10

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-library's-api-call.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int counter = 0;
    int j = 0;

    /* Send start signal: pull low for >= 1 ms, then high for 20-40 us */
    if (gpioSetMode(DHT22_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output: %s", DHT22_PIN, strerror(errno));
        return -1;
    }
    gpioWrite(DHT22_PIN, PI_LOW);
    gpioDelay(2000); /* 2 ms low */
    gpioWrite(DHT22_PIN, PI_HIGH);
    gpioDelay(30);   /* 30 us high */
    gpioSetMode(DHT22_PIN, PI_INPUT);

    /* Wait for sensor response: low for ~80 us, then high for ~80 us */
    counter = 0;
    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (++counter > 100) {
            syslog(LOG_ERR, "DHT22 response timeout (sensor absent or wiring fault)");
            return -1;
        }
        gpioDelay(1);
    }
    counter = 0;
    while (gpioRead(DHT22_PIN) == PI_LOW) {
        if (++counter > 100) {
            syslog(LOG_ERR, "DHT22 response timeout (sensor absent or wiring fault)");
            return -1;
        }
        gpioDelay(1);
    }
    counter = 0;
    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (++counter > 100) {
            syslog(LOG_ERR, "DHT22 response timeout (sensor absent or wiring fault)");
            return -1;
        }
        gpioDelay(1);
    }

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        counter = 0;
        while (gpioRead(DHT22_PIN) == laststate) {
            if (++counter > 100) {
                syslog(LOG_ERR, "DHT22 data timeout (bit %d)", i);
                return -1;
            }
            gpioDelay(1);
        }
        laststate = gpioRead(DHT22_PIN);
        if (counter > 40) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    /* Checksum validation */
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum mismatch: calculated 0x%02X, received 0x%02X", checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

static int post_humidity(float humidity) {
