#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp_c) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int millideg;
    if (fscanf(fp, "%d", &millideg) != 1) {
        fprintf(stderr, "Error reading temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temp_c = (float)millideg / 1000.0f;
    return 0;
}

static int read_fan_state(int *state) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%d", state) != 1) {
        fprintf(stderr, "Error reading fan state from file %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file %s for writing: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to file %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int max_fan_state;
    if (read_fan_state(&max_fan_state) != 0) {
        fprintf(stderr, "Failed to read max fan state. Using default 3.\n");
        max_fan_state = 3;
    }

    if (max_fan_state < 0 || max_fan_state > 3) {
        fprintf(stderr, "Invalid fan state %d. Using default 3.\n", max_fan_state);
        max_fan_state = 3;
    }

    int current_fan_state = 0;
    int last_fan_state = -1;

    while (running) {
        float temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_fan_state;
        if (temperature < 45.0f) {
            new_fan_state = 0;
        } else if (temperature < 55.0f) {
            new_fan_state = 1;
        } else if (temperature < 65.0f) {
            new_fan_state = 2;
        } else {
            new_fan_state = 3;
        }

        if (new_fan_state != current_fan_state) {
            if (write_fan_state(new_fan_state) != 0) {
                fprintf(stderr, "Failed to write fan state to file %s. Retrying in %d seconds.\n", FAN_STATE_FILE, POLL_INTERVAL_SEC);
                sleep(POLL_INTERVAL_SEC);
                continue;
            }

            current_fan_state = new_fan_state;
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Fan speed set to state %d", current_fan_state);
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Failed to log fan speed change.\n");
            }
        }

        if (current_fan_state != last_fan_state) {
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Fan state changed to state %d", current_fan_state);
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Failed to log fan state change.\n");
            }
            last_fan_state = current_fan_state;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (current_fan_state != 0) {
        write_fan_state(0);
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Fan state set to state 0 on shutdown");
        log_event(log_message);
    }

    printf("Fan control program terminated gracefully.\n");
    return 0;
}

