#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define LOG_FILE "heater_log.txt"
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char buffer[4];
    int result = spiRead(handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & 0x00000001) fprintf(stderr, "open circuit ");
        if (raw & 0x00000002) fprintf(stderr, "short to GND ");
        if (raw & 0x00000004) fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) thermocouple_raw |= 0xC000;

    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static void set_heater_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(gpio, duty_cycle);
}

static void log_data(float temperature, int duty_cycle, float pid_output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Duty Cycle: %d%%, PID Output: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fclose(fp);
}

static float pid_control(float setpoint, float current_value, float *integral, float *previous_error, float *previous_derivative) {
    float error = setpoint - current_value;
    *integral += error;
    float derivative = error - *previous_error;
    float output = (*integral * 0.1) + (derivative * 0.01);
    *previous_error = error;
    *previous_derivative = derivative;
    return output;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_pwm(HEATER_GPIO, 0);

    float integral = 0.0, previous_error = 0.0, previous_derivative = 0.0;
    int failsafe_active = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("PID heater control started. Target: %.1f C\n", TARGET_TEMPERATURE);

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) != 0) {
            if (!failsafe_active) {
                fprintf(stderr, "Sensor read error, disabling heater\n");
