                set_heater_pwm(HEATER_GPIO, 0);
                failsafe_active = 1;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        failsafe_active = 0;

        int duty_cycle = (int)(pid_control(TARGET_TEMPERATURE, temperature, &integral, &previous_error, &previous_derivative) * 100.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        set_heater_pwm(HEATER_GPIO, duty_cycle);
        log_data(temperature, duty_cycle, pid_control(TARGET_TEMPERATURE, temperature, &integral, &previous_error, &previous_derivative));

        printf("Temperature: %.2f C, Duty Cycle: %d%%, PID Output: %.2f\n", temperature, duty_cycle, pid_control(TARGET_TEMPERATURE, temperature, &integral, &previous_error, &previous_derivative));

