#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define NUM_SENSORS 2
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static int i2c_handles[NUM_SENSORS];
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sensor(int handle, float *flow) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read == 3) {
            if (crc8(buf, 2) == buf[2]) {
                uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
                *flow = (float)raw / 65536.0f;
                return 0;
            } else {
                fprintf(stderr, "CRC mismatch on sensor %d\n", handle);
            }
        } else {
            fprintf(stderr, "I2C read error on sensor %d (got %d bytes, expected 3)\n", handle, bytes_read);
        }
        retries++;
        if (retries < MAX_RETRIES)
            gpioDelay(10000);
    }
    return -1;
}

static void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, 0x48 + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device for sensor %d: %d\n", i, i2c_handles[i]);
            for (int j = 0; j < i; j++)
                i2cClose(i2c_handles[j]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int valid1 = read_sensor(i2c_handles[0], &flow1);
        int valid2 = read_sensor(i2c_handles[1], &flow2);

        if (valid1 == 0 && valid2 == 0) {
            log_flow_data(flow1, flow2);
            printf("Flow1: %.4f, Flow2: %.4f\n", flow1, flow2);
        } else {
            fprintf(stderr, "Failed to read flow data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++)
        i2cClose(i2c_handles[i]);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

