            printf("Flow1: %.4f, Flow2: %.4f\n", flow1, flow2);
        } else {
            fprintf(stderr, "Failed to read flow data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++)
        i2cClose(i2c_handles[i]);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

