#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define ENCODER_A 17
#define ENCODER_B 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360
#define DEGREES_PER_PULSE (360.0 / PULSES_PER_REVOLUTION)

static volatile sig_atomic_t running = 1;
static volatile int encoder_a_state = 0;
static volatile int encoder_b_state = 0;
static volatile int encoder_position = 0;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(ENCODER_A, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", ENCODER_A);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ENCODER_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", ENCODER_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ENCODER_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", ENCODER_A);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ENCODER_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", ENCODER_B);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_encoder_states(void) {
    int a = gpioRead(ENCODER_A);
    int b = gpioRead(ENCODER_B);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error: Failed to read encoder states.\n");
        return -1;
    }

    return (a << 1) | b;
}

static void update_encoder_position(int new_state) {
    static int last_state = 0;
    int delta = new_state - last_state;

    if (delta == 1 || delta == -3) {
        encoder_position += DEGREES_PER_PULSE;
    } else if (delta == -1 || delta == 3) {
        encoder_position -= DEGREES_PER_PULSE;
    }

    if (encoder_position < 0) {
        encoder_position += 360.0;
    } else if (encoder_position >= 360.0) {
        encoder_position -= 360.0;
    }

    last_state = new_state;
}

static int log_encoder_position(double position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, position) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int new_state = read_encoder_states();
        if (new_state < 0) {
            break;
        }

        update_encoder_position(new_state);

        if (log_encoder_position(encoder_position) != 0) {
            break;
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

