#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define PULSES_PER_REVOLUTION 1

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_rpm(uint32_t pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses / PULSES_PER_REVOLUTION / interval_sec * 60.0;
}

static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return;
    }

    if (fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
    }
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", GPIO_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to register ISR on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        if (!running) break;

        uint32_t pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(pulses, (double)SAMPLE_INTERVAL_SEC);
        log_rpm(rpm);

        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

