    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    int last_level = -1;
    int edge_detected = 0;

    while (program_running) {
        int level = read_audio_level();
        if (level < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (level == 1 && last_level == 0) {
            edge_detected = 1;
        } else if (level == 0 && last_level == 1) {
            if (edge_detected) {
                if (log_event(1) != 0) {
                    fprintf(stderr, "Warning: Failed to log event.\n");
                }
                edge_detected = 0;
            }
        }

        last_level = level;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioWrite(GAIN_SELECT_PIN, 1);  /* Select 20 dB gain */
    gpioTerminate();
    printf("\nAudio monitoring stopped.\n");

    return EXIT_SUCCESS;
}

