/*
 * Raspberry Pi Zero W - SLF3S-4000B Liquid Flow Sensor Monitor
 *
 * Reads flow rate from the SLF3S-4000B via I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * and logs to flow_log.csv every 1000 ms.
 *
 * Build: gcc -O2 -Wall -o flow_monitor flow_monitor.c -lsensirion_i2c
 * Run:   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>
#include <sensirion_i2c.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000   /* 1 second */
#define MAX_RETRIES    3

/* SLF3S-4000B command codes (16-bit, MSB first) */
#define CMD_READ_FLOW  0x0001
#define CMD_RESET      0x0002

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %s\n",
                cmd, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %s\n", pigpio_error(rc));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int sensor_reset(int handle)
{
    if (i2c_write_cmd(handle, CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms reset settling time */
    return 0;
}

static int sensor_read_flow(int handle, float *flow_rate)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_READ_FLOW >> 8), (uint8_t)(CMD_READ_FLOW & 0xFF) };
    uint8_t data[3];

    if (i2c_write_cmd(handle, CMD_READ_FLOW) < 0)
        return -1;

    gpioDelay(10000); /* 10 ms conversion time */

    if (i2c_read_bytes(handle, data, 3) != 3)
        return -1;

    /* Validate CRC-8 */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on flow data\n");
        return -1;
    }

    /* Convert raw 16-bit value to flow rate (uL/min) */
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_write(float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Reset sensor */
    if (sensor_reset(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Sensor reset failed; check wiring and address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Monitoring SLF3S-4000B flow rate on I2C bus %d, addr 0x%02X...\n",
           I2C_BUS, I2C_ADDR);
    printf("Logging to %s every 1 s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float flow_rate = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sensor_read_flow(g_i2c_handle, &flow_rate) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (ok) {
            if (log_write(flow_rate) < 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing...\n");
            } else {
                printf("Flow rate: %.2f uL/min\n", flow_rate);
            }
        } else {
            fprintf(stderr, "[ERROR] All %d read attempts failed; skipping sample.\n",
                    MAX_RETRIES);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

