#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

/* MICS-VZ-89TE register addresses */
#define REG_MEASURE_CMD 0x00
#define REG_MEASURE_RESULT 0x01
#define REG_TVOC_MSB 0x02
#define REG_TVOC_LSB 0x03
#define REG_ECO2_MSB 0x04
#define REG_ECO2_LSB 0x05

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(uint8_t reg_msb, uint16_t *value) {
    uint8_t msb, lsb;
    if (i2c_read_reg(reg_msb, &msb) != 0) return -1;
    if (i2c_read_reg(reg_msb + 1, &lsb) != 0) return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_sensor_data(uint16_t *tvoc, uint16_t *eco2) {
    if (i2c_write_reg(REG_MEASURE_CMD, 0x01) != 0) return -1;
    gpioDelay(10000); /* 10 ms conversion time */

    uint8_t msb, lsb;
    if (i2c_read_reg(REG_MEASURE_RESULT, &msb) != 0) return -1;
    if (i2c_read_reg(REG_MEASURE_RESULT + 1, &lsb) != 0) return -1;
    uint16_t raw = ((uint16_t)msb << 8) | lsb;

    if (raw & 0x01) {
        fprintf(stderr, "Error: Sensor data not ready (bit 0 set)\n");
        return -1;
    }

    if (i2c_read_reg16(REG_TVOC_MSB, tvoc) != 0) return -1;
    if (i2c_read_reg16(REG_ECO2_MSB, eco2) != 0) return -1;

    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    if (tvoc == 0 || eco2 == 0) return 0.0f;

    float ratio = (float)eco2 / (float)tvoc;
    if (ratio < 0.5f) return 0.0f;
    if (ratio > 1.5f) return 100.0f;

    float iaq = 100.0f - (150.0f * (ratio - 0.5f));
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;

    return iaq;
}

static void log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d addr 0x%02X (err=%d)\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,IAQ (ppb),TVOC (ppb),eCO2 (ppm)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t tvoc = 0, eco2 = 0;

        if (read_sensor_data(&tvoc, &eco2) == 0) {
            float iaq = calculate_iaq(tvoc, eco2);
            log_data(iaq, tvoc, eco2);
            printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f ppb\n",
                   tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && !terminate; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

