/*
 * TTP223B capacitive touch sensor monitor for Raspberry Pi 5.
 *
 * Wiring:
 *   TTP223B OUT  -> GPIO17 (BCM, physical pin 11)
 *   TTP223B VCC  -> 3.3 V
 *   TTP223B GND  -> GND
 *
 * The TTP223B output is HIGH when touched and LOW when released.
 * We poll every 100 ms using CLOCK_MONOTONIC so the alert is
 * printed even if the program is interrupted by a signal.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp223_intrusion ttp223_intrusion.c
 */

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/gpiochip.h>
#include <sys/ioctl.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO controller on Pi 5 */
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_US 100000     /* 100 ms */
#define ALERT_TIMEOUT_S  5           /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_open_chip(void)
{
    int fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }
    return fd;
}

static int gpio_get_line_value(int fd, unsigned int offset)
{
    int value = ioctl(fd, GPIO_LINE_GET_VALUE, offset);
    if (value < 0) {
        fprintf(stderr, "ioctl(GPIO_LINE_GET_VALUE, offset=%u): %s\n",
                offset, strerror(errno));
        return -1;
    }
    return value;
}

static int gpio_set_line_value(int fd, unsigned int offset, int value)
{
    if (ioctl(fd, GPIO_LINE_SET_VALUE,
               (unsigned long)value) < 0) {
        fprintf(stderr, "ioctl(GPIO_LINE_SET_VALUE, offset=%u, value=%d): %s\n",
                offset, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    bool alert_active = false;
    struct timespec alert_start;
    struct timespec now;
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    fd = gpio_open_chip();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    /* Request the line as input with pull-up so the sensor reads HIGH
     * when idle and LOW when touched. */
    if (gpio_set_line_value(fd, GPIO_LINE_OFFSET, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO line %u HIGH for pull-up.\n",
                GPIO_LINE_OFFSET);
        goto cleanup;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &alert_start) != 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO%u (BCM)...\n",
           GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int value = gpio_get_line_value(fd, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Sensor read error; exiting.\n");
            ret = EXIT_FAILURE;
            break;
        }

        /* TTP223B output is HIGH when touched, LOW when released. */
        if (value == 1) {
            if (!alert_active) {
                if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                    fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
                alert_active = true;
                alert_start = now;
                printf("Intrusion detected! Touch detected on GPIO%u.\n",
                       GPIO_LINE_OFFSET);
                fflush(stdout);
            } else {
                if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                    fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
                long elapsed_s = (now.tv_sec  - alert_start.tv_sec)
                              + (now.tv_nsec - alert_start.tv_nsec) / 1000000000L;

                if (elapsed_s >= ALERT_TIMEOUT_S) {
                    printf("Intrusion alert cleared.\n");
                    fflush(stdout);
                    alert_active = false;
                }
            }
        } else {
            if (alert_active) {
                printf("Touch released on GPIO%u.\n", GPIO_LINE_OFFSET);
                fflush(stdout);
                alert_active = false;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (fd >= 0) {
        /* Ensure line is LOW before closing. */
