#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE (SAMPLE_RATE * NUM_CHANNELS * BITS_PER_SAMPLE / 8)
#define RAW_FILE "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(int *fd) {
    *fd = open(I2S_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SND_PCM_MODE_MASTER;
    if (ioctl(*fd, SNDCTL_DSP_SETMODE, &mode) < 0) {
        fprintf(stderr, "Error setting I2S mode: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(*fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting I2S channels: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(*fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting I2S sample rate: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    int bits = BITS_PER_SAMPLE;
    if (ioctl(*fd, SNDCTL_DSP_BITS_PER_SAMPLE, &bits) < 0) {
        fprintf(stderr, "Error setting I2S bits per sample: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*line, "inmp441_lr_select", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line = NULL;
        return -1;
    }

    return 0;
}

static int read_i2s_data(int fd, uint8_t *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)bytes_read != size) {
        fprintf(stderr, "Short read from I2S device: expected %zu bytes, got %zd\n", size, bytes_read);
        return -1;
    }
    return 0;
}

static int write_raw_data(const char *filename, const uint8_t *data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t written = fwrite(data, 1, size, fp);
    if (written != size) {
        fprintf(stderr, "Error writing to file %s: wrote %zu of %zu bytes\n", filename, written, size);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int i2s_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    uint8_t *buffer = NULL;
    int ret_code = 1;

    buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Error allocating memory for buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    if (init_i2s(&i2s_fd) < 0) {
        goto cleanup;
    }

    if (init_gpio(&gpio_chip, &gpio_line) < 0) {
        goto cleanup;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    while (running) {
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line low: %s\n", strerror(errno));
            goto cleanup;
        }

        if (read_i2s_data(i2s_fd, buffer, BUFFER_SIZE) < 0) {
            goto cleanup;
        }

        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line high: %s\n", strerror(errno));
            goto cleanup;
        }

        if (write_raw_data(RAW_FILE, buffer, BUFFER_SIZE) < 0) {
            goto cleanup;
        }
    }

    printf("\nAudio capture stopped.\n");
    ret_code = 0;

cleanup:
    if (buffer) {
        free(buffer);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2s_fd >= 0) {
        close(i2s_fd);
    }
    return ret_code;
}

