/*
 * Flame Sensor Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - SainSmart IR Flame Sensor Module (LM393 comparator with IR photodiode)
 *     DO  -> GPIO4  (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *   - Cooling Fan (hardware PWM)
 *     PWM -> GPIO18 (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *
 * Behavior:
 *   - Reads the digital output every 50 ms.
 *   - Debounces by waiting 50 ms before reading again.
 *   - When the sensor output goes LOW (flame detected), drives a 100 Hz
 *     PWM on GPIO18 for 500 ms, then stops PWM and logs the event.
 *   - Logs events to flame_log.txt with ISO-8601 timestamps.
 *   - Cleanly exits on SIGINT or SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define PWM_GPIO          18
#define PWM_FREQUENCY     100          /* Hz */
#define PWM_RANGE         100          /* duty cycle 0–100 */
#define DEBOUNCE_US       50000        /* 50 ms debounce */
#define FAN_RUN_US        500000       /* 500 ms fan run */
#define POLL_INTERVAL_US  50000        /* 50 ms poll interval */
#define MAX_READ_RETRIES  10           /* timeout after 10 attempts */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log_file) {
        fprintf(stderr, "Log file not open.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed.\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed.\n");
        return;
    }

    fprintf(g_log_file, "%s: %s\n", timestamp, event);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM */
    if (gpioInitialise() >= 0) {
        gpioPWM(PWM_GPIO, 0);
        gpioTerminate();
    }

    /* Reset GPIO pins */
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(PWM_GPIO, PI_INPUT);

    /* Close log file */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log file */
    g_log_file = fopen("flame_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening flame_log.txt");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    /* Configure flame sensor pin as input */
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    /* Configure PWM pin as output */
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    int last_flame_state = 1;   /* assume no flame at startup */
    int read_failures = 0;

    while (g_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d.\n", FLAME_SENSOR_GPIO);
            read_failures++;
            if (read_failures >= MAX_READ_RETRIES) {
                log_event("Error: Max read failures reached — sensor may be absent or disconnected");
                break;
            }
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        read_failures = 0;

        /* Detect flame: LOW = flame detected */
        if (sensor_value == 0 && last_flame_state != 0) {
            log_event("Flame detected");

            /* Start PWM fan */
            if (gpioPWM(PWM_GPIO, PWM_RANGE) < 0) {
                fprintf(stderr, "gpioPWM failed on GPIO%d.\n", PWM_GPIO);
                break;
            }

            /* Run fan for 500 ms */
            gpioDelay(FAN_RUN_US);

            /* Stop PWM fan */
            if (gpioPWM(PWM_GPIO, 0) < 0) {
                fprintf(stderr, "gpioPWM stop failed on GPIO%d.\n", PWM_GPIO);
                break;
            }

            log_event("Flame stopped");
        }

        last_flame_state = sensor_value;
        gpioDelay(DEBOUNCE_US);
    }

    log_event("Program shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

