/*
 * OPT3001 Ambient Light Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD -> 3.3 V
 *   OPT3001 GND -> GND
 *
 * Build: gcc -O2 -Wall -o opt3001_reader opt3001_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x48

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01

/* Config register bits */
#define CFG_OS_SINGLE  0x8000  /* Start a single conversion */
#define CFG_MUX_A0     0x0000  /* AIN0 vs GND */
#define CFG_RANGE_100 0x0000  /* Full-scale range: 100 mA */
#define CFG_MODE_CONT  0x0000  /* Continuous conversion mode */
#define CFG_DR_128    0x0000  /* 128 SPS */

#define LOG_FILE       "light_data.txt"
#define SAMPLE_MS      100
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register.                         */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int opt3001_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register.                        */
/* Returns 0 on success and stores the value in *out, -1 on error.      */
/* ------------------------------------------------------------------ */
static int opt3001_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the OPT3001 sensor.                                      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int opt3001_init(int fd)
{
    uint16_t config;

    /* Verify sensor presence by reading the config register */
    if (opt3001_read_reg16(fd, REG_CONFIG, &config) != 0) {
        fprintf(stderr, "OPT3001 not responding at address 0x%02X\n",
                OPT3001_ADDR);
        return -1;
    }

    /* Configure: start single conversion, AIN0 vs GND, 100 mA range,
       continuous mode, 128 SPS */
    if (opt3001_write_reg16(fd, REG_CONFIG,
                           CFG_OS_SINGLE | CFG_MUX_A0 | CFG_RANGE_100 |
                           CFG_MODE_CONT | CFG_DR_128) != 0) {
        return -1;
    }

    /* Allow first conversion to complete */
    usleep(10000);  /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read lux value from the OPT3001.                                    */
/* Returns 0 on success and stores the lux value in *lux, -1 on error.   */
/* ------------------------------------------------------------------ */
static int opt3001_read_lux(int fd, float *lux)
{
    uint16_t result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (opt3001_read_reg16(fd, REG_RESULT, &result) == 0) {
            /* Check OS bit (bit 15) to confirm conversion complete */
            if (result & 0x8000) {
                /* Convert 16-bit signed value to lux (100 mA range) */
                int16_t raw = (int16_t)result;
                *lux = (float)raw / 10.0f;
                return 0;
            } else {
                fprintf(stderr, "OPT3001 conversion not complete (OS=0)\n");
            }
        }
        retries++;
        usleep(10000);  /* 10 ms backoff before retry */
    }

    fprintf(stderr, "OPT3001 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to the log file.                   */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
