#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN   17
#define CENTER_PIN 18
#define RIGHT_PIN  27
#define POLL_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int left, center, right;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial sensor states */
    left   = gpioRead(LEFT_PIN);
    center = gpioRead(CENTER_PIN);
    right  = gpioRead(RIGHT_PIN);

    if (left < 0 || center < 0 || right < 0) {
        fprintf(stderr, "Error: failed to read sensor pins.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

    /* Main polling loop */
    while (g_running) {
        left   = gpioRead(LEFT_PIN);
        center = gpioRead(CENTER_PIN);
        right  = gpioRead(RIGHT_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: failed to read sensor pins during polling.\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        usleep(POLL_US);
    }

    /* Graceful shutdown: terminate pigpio library */
    gpioTerminate();
    printf("\npigpio terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

