/*
 * TTP226 8-channel touch sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TTP226 OUT1 -> GPIO2 (physical pin 3)
 *   TTP226 OUT2 -> GPIO3 (physical pin 5)
 *   TTP226 OUT3 -> GPIO4 (physical pin 7)
 *   TTP226 OUT4 -> GPIO5 (physical pin 29)
 *   TTP226 OUT5 -> GPIO6 (physical pin 31)
 *   TTP226 OUT6 -> GPIO7 (physical pin 33)
 *   TTP226 OUT7 -> GPIO8 (physical pin 35)
 *   TTP226 OUT8 -> GPIO9 (physical pin 37)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 *
 * Run:
 *   ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* TTP226 OUT1..OUT8 -> BCM GPIO2..GPIO9 */
static const unsigned int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        goto cleanup;
    }

    /* Get the GPIO lines for each channel */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as input with pull-down */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input_flags(lines[i], "ttp226-reader",
                                           GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int values[NUM_CHANNELS];
        int rc = gpiod_line_get_value(lines[0]);
        if (rc < 0) {
            fprintf(stderr, "Error reading GPIO line %u: %s\n",
                    touch_pins[0], strerror(errno));
            goto cleanup;
        }
        values[0] = rc;

        for (int i = 1; i < NUM_CHANNELS; i++) {
            rc = gpiod_line_get_value(lines[i]);
            if (rc < 0) {
                fprintf(stderr, "Error reading GPIO line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = rc;
        }

        printf("[%6u ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d\n",
               SAMPLE_INTERVAL_US / 1000,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

