#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring Hall effect sensors on GPIO%d and GPIO%d...\n", SENSOR1_PIN, SENSOR2_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SENSOR1_PIN);
            break;
        }
        if (s2 < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SENSOR2_PIN);
            break;
        }

        printf("Sensor 1: %s\n", s1 ? "HIGH" : "LOW");
        printf("Sensor 2: %s\n", s2 ? "HIGH" : "LOW");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

