/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TTP226 VCC  -> 3.3 V (Pin 1)
 *   TTP226 GND  -> GND  (Pin 9)
 *   TTP226 SDA  -> GPIO2 (Pin 3, physical pin 5)
 *   TTP226 SCL  -> GPIO3 (Pin 5, physical pin 7)
 *   TTP226 ADDR -> GND  (I2C address 0x5A)
 *
 * The TTP226 outputs are active-low: 0 = touched, 1 = not touched.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define CONSUMER_NAME   "ttp226-reader"

/* BCM GPIO pins mapped to TTP226 channels (physical pin numbering) */
static const unsigned int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read all eight channels in one go.
 * Returns 0 on success, -1 on failure.
 */
static int read_all_channels(struct gpiod_line *lines[NUM_CHANNELS], int values[NUM_CHANNELS])
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed on channel %d: %s\n",
                    i, strerror(errno));
            return -1;
        }
        values[i] = v;
    }
    return 0;
}

/*
 * Build an ISO-8601 timestamp string.
 * Returns 0 on success, -1 on failure.
 */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    char timestamp[32];
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
