/*
 * Raspberry Pi Zero W – Omron D7E-1 Tilt Sensor Monitor
 *
 * Wiring:
 *   Omron D7E-1 VCC  -> 3.3 V (Pin 1)
 *   Omron D7E-1 GND  -> GND  (Pin 9)
 *   Omron D7E-1 OUT  -> GPIO4 (Pin 7, BCM)
 *
 * The D7E-1 output is active-low: LOW = tilted, HIGH = not tilted.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        4          /* BCM pin 7 – D7E-1 OUT */
#define POLL_INTERVAL_US 100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the tilt sensor pin. Returns 0 (tilted) or 1 (not tilted),
 * or -1 on error.                                                  */
/* ------------------------------------------------------------------ */
static int read_tilt_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed (pigpio error %d).\n",
                gpio_pin, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Log the tilt state to stdout and the console.                     */
/* ------------------------------------------------------------------ */
static void log_tilt_state(int tilt_state)
{
    const char *state_str = (tilt_state == 0) ? "Tilted" : "Not Tilted";
    printf("Tilt state: %s\n", state_str);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with pull-up --- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n",
                GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d.\n", GPIO_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int tilt_state = read_tilt_sensor(GPIO_PIN);
        if (tilt_state < 0) {
            /* Error already reported; exit cleanly */
            break;
        }

        log_tilt_state(tilt_state);

        /* Sleep 100 ms, checking g_running every 10 ms for responsive shutdown */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(10000);  /* 10 ms */
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

