#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define GPIO_CHIP      "gpiochip4"
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define START_CMD      0x36
#define READ_CMD       0x24
#define MEAS_DELAY_MS  100
#define LOOP_DELAY_S   1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alarm_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t cmd = READ_CMD;
    uint8_t data[6];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 6) < 0)
        return -1;

    if (sensirion_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on flow rate data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *flow_rate = (float)raw / 65536.0f * 1000.0f;
    return 0;
}

static void log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(log_fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
    fflush(log_fp);
}

static void check_alarm(float avg_flow) {
    int val = (avg_flow < FLOW_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(alarm_line, val) < 0) {
        fprintf(stderr, "Failed to set alarm GPIO: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x48) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x48: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_cmd(i2c_fd, START_CMD) < 0) {
        fprintf(stderr, "Failed to start sensor\n");
        cleanup();
        return 1;
    }
    usleep(100000);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(alarm_line, "flow_monitor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow_rates[2] = {0.0f, 0.0f};
        int valid_count = 0;
        int error_count = 0;

        for (int i = 0; i < 2; i++) {
            float rate;
            if (read_flow_rate(i2c_fd, &rate) == 0) {
                flow_rates[i] = rate;
                valid_count++;
            } else {
                error_count++;
            }
        }

        if (valid_count == 0) {
            fprintf(stderr, "No valid sensor readings this cycle\n");
        } else {
            float avg_flow = 0.0f;
            for (int i = 0; i < valid_count; i++)
                avg_flow += flow_rates[i];
            avg_flow /= valid_count;
            log_flow_rate(avg_flow);
            check_alarm(avg_flow);
        }

        if (error_count > 0) {
            fprintf(stderr, "I2C communication error(s) occurred\n");
        }

        sleep(LOOP_DELAY_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

