#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM pin 7 */
#define BUFFER_SIZE     100
#define POLL_DELAY_US   50000      /* 50 ms */

/* KY-033 module output: LOW = obstacle detected, HIGH = clear */
#define OBSTACLE_DETECTED 0

typedef struct {
    time_t timestamp;
    bool   obstacle_detected;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call pigpio functions here. */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a new entry to the circular buffer.                         */
/* ------------------------------------------------------------------ */
static void add_to_buffer(time_t timestamp, bool obstacle_detected)
{
    sensor_buffer[buffer_index].timestamp         = timestamp;
    sensor_buffer[buffer_index].obstacle_detected = obstacle_detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ------------------------------------------------------------------ */
/* Dump the entire buffer in chronological order to stdout.           */
/* ------------------------------------------------------------------ */
static void dump_buffer(void)
{
    printf("\n--- Sensor Data Dump ( oldest first) ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts_str[32];
        struct tm tm_info;
        localtime_r(&sensor_buffer[idx].timestamp, &tm_info);
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Obstacle: %s\n",
               ts_str,
               sensor_buffer[idx].obstacle_detected ? "YES" : "NO");
    }
    printf("--- End of Dump ---\n\n");
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure the sensor pin.                    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the sensor value.                                             */
/* Returns 0 or 1 on success, -1 on read error.                       */
/* ------------------------------------------------------------------ */
static int read_sensor(void)
{
    int level = gpioRead(SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance sensor monitoring started.\n");
    printf("  Sensor pin : GPIO%d (BCM)\n", SENSOR_PIN);
    printf("  Buffer    : %d entries\n", BUFFER_SIZE);
    printf("  Poll delay : %d ms\n", POLL_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            /* Sensor read error — wait and retry */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        bool obstacle_detected = (sensor_value == OBSTACLE_DETECTED);

        time_t now = time(NULL);
        add_to_buffer(now, obstacle_detected);

        if (obstacle_detected) {
            printf("ALERT: Obstacle detected at %ld\n", (long)now);
            fflush(stdout);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    dump_buffer();
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

