/*
 * fan_health.c — Raspberry Pi 5 Bookworm OS — Omron D7S vibration sensor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM)  (pin 3)
 *   D7S SCL  -> GPIO3 (BCM)  (pin 5)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health   (I2C bus 1, sensor address 0x53)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53

/* D7S register addresses */
#define REG_MODE       0x00
#define REG_X_LSB      0x01
#define REG_X_MSB      0x02
#define REG_Y_LSB      0x03
#define REG_Y_MSB      0x04
#define REG_Z_LSB      0x05
#define REG_Z_MSB      0x06

/* Mode values */
#define MODE_ACTIVE    0x01
#define MODE_STANDBY   0x00

#define SAMPLE_PERIOD_MS 500
#define ACTIVE_TIMEOUT_S  1
#define POLL_DELAY_MS    10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a single byte to an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers. */
static int i2c_read_reg16(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* Switch the D7S to active mode and wait for it to become ready. */
static int d7s_activate(int fd)
{
    if (i2c_write_reg8(fd, REG_MODE, MODE_ACTIVE) < 0)
        return -1;

    /* Poll MODE register until it reads MODE_ACTIVE (0x01). */
    for (int i = 0; i < 100; i++) {
        uint8_t mode;
        if (i2c_read_reg8(fd, REG_MODE, &mode) < 0)
            return -1;
        if (mode == MODE_ACTIVE)
            return 0;
        usleep(10000); /* 10 ms */
    }

    fprintf(stderr, "D7S did not enter active mode within %d ms\n",
            ACTIVE_TIMEOUT_S * 100);
    return -1;
}

/* Read acceleration data and convert to g-force units. */
static int d7s_read_acceleration(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, REG_X_LSB, &raw_x) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, &raw_y) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, &raw_z) < 0)
        return -1;

    /* D7S outputs 16-bit signed values; sensitivity is 0.0001 g/LSB. */
    *x = (float)raw_x * 0.0001f;
    *y = (float)raw_y * 0.0001f;
    *z = (float)raw_z * 0.0001f;
    return 0;
}

/* Append a CSV row with an ISO-8601 timestamp. */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the D7S slave address */
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Activate the D7S sensor */
    if (d7s_activate(fd) < 0) {
        fprintf(stderr, "D7S activation failed; check wiring and address.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wait for the sensor to become active */
    printf("D7S sensor ready. Waiting %d s for first data sample...\n",
           ACTIVE_TIMEOUT_S);
    sleep(ACTIVE_TIMEOUT_S);

    /* Open the CSV file in append mode; write header only if file is empty */
    FILE *fp = fopen("fan_health.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Check if file is empty to write header */
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "timestamp,x_g,y_g,z_g\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Failed to flush CSV header: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    printf("Logging acceleration data to fan_health.csv (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (d7s_read_acceleration(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error — retrying next cycle\n");
        } else {
            if (log_data(fp, x, y, z) < 0) {
                fprintf(stderr, "Logging error — continuing\n");
            }
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

