/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170 SDA -> GPIO2 (I2C bus 1 SDA)
 *   TMAG5170 SCL -> GPIO3 (I2C bus 1 SCL)
 *   TMAG5170 VDD -> 3.3 V
 *   TMAG5170 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mag_logger mag_logger.c -ltmag5170
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>
#include <tmag5170.h>

#define I2C_BUS        1
#define I2C_ADDR       0x51
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000   /* 100 ms */

/* TMAG5170 register addresses */
#define REG_DEVICE_ID   0x00
#define REG_X_MSB      0x01
#define REG_X_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Y_LSB      0x04
#define REG_Z_MSB      0x05
#define REG_Z_LSB      0x06
#define REG_CTRL       0x07
#define REG_RANGE      0x08

/* CTRL register bits */
#define CTRL_MODE_CONT  0x01
#define CTRL_AXIS_XYZ   0x07
#define CTRL_RANGE_50MT 0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a TMAG5170 register                          */
/* ------------------------------------------------------------------ */
static int mag_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = tmag5170_write_reg(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed (rc=%d): %s\n",
                reg, rc, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a TMAG5170 register                          */
/* ------------------------------------------------------------------ */
static int mag_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = tmag5170_read_reg(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed (rc=%d): %s\n",
                reg, rc, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of magnetic data (X, Y, Z) in one burst                */
/* ------------------------------------------------------------------ */
static int mag_read_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    int rc = tmag5170_read_burst(handle, REG_X_MSB, (char *)buf, 6);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C burst read failed (rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }
