#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", SENSOR_PIN, strerror(errno));
            log_event("ERROR: Failed to read sensor");
            sleep(REINIT_DELAY_SEC);
            continue;
        }

        if (level == 1) {
            printf("ALERT: Water detected!\n");
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

