/*
 * MLX90217 RPM Logger for Raspberry Pi 4 Model B
 *
 * Reads the Hall-effect output of a Melexis MLX90217 sensor on BCM GPIO4
 * (physical pin 7) using pigpio's GPIO interrupt callback.
 *
 * Build: gcc -O2 -Wall -o rpm_logger rpm_logger.c -lpigpio -lrt
 * Run:   sudo ./rpm_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE_NAME     "rpm_log.txt"
#define SAMPLE_INTERVAL_S 1          /* seconds between samples */
#define PULSES_PER_REV    1000       /* typical pulses per revolution */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                       */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t      g_pulse_count = 0;
static FILE                 *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in callback          */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in pigpio thread                         */
/* ------------------------------------------------------------------ */

static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level == 1) {
        /* Rising edge: one pulse per revolution */
        g_pulse_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulse count and sample interval                    */
/* ------------------------------------------------------------------ */

static double calculate_rpm(uint32_t pulses, int interval_s)
{
    if (interval_s <= 0) {
        return 0.0;
    }
    return ((double)pulses / (double)interval_s) * 60.0;
}

/* ------------------------------------------------------------------ */
/* Log one sample with timestamp to file and stdout                    */
/* ------------------------------------------------------------------ */

static void log_rpm(double rpm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s %lf\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush on log file failed\n");
    }

    printf("%s %lf\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */

