 *
 * Reads the Hall-effect output of a Melexis MLX90217 sensor on BCM GPIO4
 * (physical pin 7) using pigpio's GPIO interrupt callback.
 *
 * Build: gcc -O2 -Wall -o rpm_logger rpm_logger.c -lpigpio -lrt
 * Run:   sudo ./rpm_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE_NAME     "rpm_log.txt"
#define SAMPLE_INTERVAL_S 1          /* seconds between samples */
#define PULSES_PER_REV    1000       /* typical pulses per revolution */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                       */
/* ------------------------------------------------------------------ */

