/* Log one sample with timestamp to file and stdout                    */
/* ------------------------------------------------------------------ */

static void log_rpm(double rpm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s %lf\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush on log file failed\n");
    }

