/*
 * Raspberry Pi Zero W – Dual MLX90217 Hall-Effect Sensor Quadrature Logger
 *
 * Wiring:
 *   Sensor A -> GPIO17 (BCM)  [90° electrical offset required]
 *   Sensor B -> GPIO27 (BCM)  [90° electrical offset required]
 *   VCC     -> 3.3 V
 *   GND     -> GND
 *
 * The MLX90217 outputs a 16-bit quadrature count on the DATA0/DATA1 pins.
 * The library provides edge-triggered alerts via the API call
 * mlx90217_register_alert_callback().  We maintain a quadrature state
 * machine in the ISR and the main thread, and log each event to a file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o quadrature_logger quadrature_logger.c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pthread.h>
#include <unistd.h>

#include <mlx90217.h>

/* ----------------------------- Configuration ----------------------------- */
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE_NAME "rotation_log.txt"
#define POLL_TIMEOUT_MS 100

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/*
 * Quadrature state machine.
 *   state[0] = previous A state (0 = low, 1 = high)
 *   state[1] = previous B state (0 = low, 1 = high)
 */
static volatile uint8_t g_quadrature_state[2] = {0, 0};

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  log_rotation_event(const char *direction);
static void quadrature_isr(int gpio, int level, uint32_t tick, void *userdata);
static void *main_loop(void *arg);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Log Rotation Event ------------------------- */
static int log_rotation_event(const char *direction)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];
    int ret;

    ret = clock_gettime(CLOCK_REALTIME, &ts);
    if (ret != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    pthread_mutex_lock(&g_log_mutex);

    ret = fprintf(g_log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000L, direction);
    if (ret < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    fflush(g_log_file);
    pthread_mutex_unlock(&g_log_mutex);

    return 0;
}

/* ----------------------------- Quadrature ISR ----------------------------- */
static void quadrature_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    (void)userdata;

    if (gpio != SENSOR_A_GPIO && gpio != SENSOR_B_GPIO) {
        return;
    }

    /*
     * The MLX90217 outputs a 16-bit quadrature count on the DATA0/DATA1 pins.
     * The library provides edge-triggered alerts, so we only need to
     * track the previous state to infer direction.
     */
    uint8_t current_state = (gpio == SENSOR_A_GPIO) ? (uint8_t)level : (uint8_t)(level ^ 1);

    if (gpio == SENSOR_A_GPIO) {
        g_quadrature_state[0] = current_state;
    } else {
        g_quadrature_state[1] = current_state;
    }

    /*
     * Quadrature state machine:
     *   state[0] = previous A state
     *   state[1] = previous B state
     *
     *   A rising edge  -> clockwise
     *   A falling edge -> counter-clockwise
     *   B rising edge  -> counter-clockwise
     *   B falling edge -> clockwise
     */
    if (g_quadrature_state[0] == 1 && g_quadrature_state[1] == 0) {
        if (log_rotation_event("Clockwise") != 0) {
            fprintf(stderr, "Failed to log clockwise event.\n");
        }
    } else if (g_quadrature_state[0] == 0 && g_quadrature_state[1] == 1) {
        if (log_rotation_event("Counter-Clockwise") != 0) {
            fprintf(stderr, "Failed to log counter-clockwise event.\n");
        }
    }
}

/* ----------------------------- Main Loop ---------------------------------- */
static void *main_loop(void *arg)
{
    (void)arg;

    /*
     * Register the ISR callback for both sensor GPIOs.
     * The MLX90217 library provides edge-triggered alerts, so we
     * register a callback for both rising and falling edges.
     */
    if (mlx90217_register_alert_callback(SENSOR_A_GPIO, MLX90217_ALERT_BOTH_EDGES,
                                         quadrature_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for GPIO %d: %s\n",
                SENSOR_A_GPIO, strerror(errno));
        return NULL;
    }

    if (mlx90217_register_alert_callback(SENSOR_B_GPIO, MLX90217_ALERT_BOTH_EDGES,
                                         quadrature_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for GPIO %d: %s\n",
                SENSOR_B_GPIO, strerror(errno));
        mlx90217_unregister_alert_callback(SENSOR_A_GPIO);
        return NULL;
    }

    printf("Monitoring quadrature sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_A_GPIO, SENSOR_B_GPIO);

    while (g_running) {
        /*
         * Sleep for POLL_TIMEOUT_MS, checking g_running every 100 ms.
         * If interrupted by a signal, wake up and check g_running.
         */
        struct timespec ts = {
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L
        };

        int ret = nanosleep(&ts, NULL);
        if (ret != 0 && errno != EINTR) {
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }
    }

    /*
     * Clean up: unregister callbacks and close the log file.
     */
    mlx90217_unregister_alert_callback(SENSOR_A_GPIO);
    mlx90217_unregister_alert_callback(SENSOR_B_GPIO);

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    pthread_mutex_unlock(&g_log_mutex);

    printf("\nProgram terminated gracefully.\n");
    return NULL;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize the MLX90217 library */
    if (mlx90217_init() != 0) {
        fprintf(stderr, "Failed to initialize MLX90217 library.\n");
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* Create the main loop thread */
    pthread_t main_thread;
    if (pthread_create(&main_thread, NULL, main_loop, NULL) != 0) {
        fprintf(stderr, "Failed to create main loop thread: %s\n", strerror(errno));
        mlx90217_terminate();
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* Wait for the main loop to finish */
    pthread_join(main_thread, NULL);

    /* Clean up resources */
    mlx90217_terminate();
    pthread_mutex_destroy(&g_log_mutex);

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    return EXIT_SUCCESS;
}

