    /* Open the log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize the MLX90217 library */
    if (mlx90217_init() != 0) {
        fprintf(stderr, "Failed to initialize MLX90217 library.\n");
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* Create the main loop thread */
    pthread_t main_thread;
    if (pthread_create(&main_thread, NULL, main_loop, NULL) != 0) {
        fprintf(stderr, "Failed to create main loop thread: %s\n", strerror(errno));
        mlx90217_terminate();
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* Wait for the main loop to finish */
    pthread_join(main_thread, NULL);

    /* Clean up resources */
    mlx90217_terminate();
    pthread_mutex_destroy(&g_log_mutex);

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    return EXIT_SUCCESS;
}

