        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "ttp223b-sensor") < 0) {
        syslog(LOG_ERR, "Failed to request sensor line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Monitoring TTP223B sensor on GPIO%d, LED on GPIO%d",
           SENSOR_PIN, LED_PIN);

    while (running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read sensor value: %s", strerror(errno));
            break;
        }

        if (val == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
                break;
            }
            syslog(LOG_INFO, "Touch detected on GPIO%d", SENSOR_PIN);
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
                break;
            }
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

