#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int debounce_ms(struct gpiod_line *line) {
    struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
    if (gpiod_line_event_wait(line, &ts) < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "Error waiting for debounce event: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO %d: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request output on GPIO %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        struct gpiod_line_event event;
        int val;

        if (gpiod_line_event_wait(touch_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L}) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error reading touch event: %s\n", strerror(errno));
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) continue;

        val = gpiod_line_get_value(led_line);
        if (val < 0) {
            fprintf(stderr, "Error reading LED state: %s\n", strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(led_line, val ? 0 : 1) < 0) {
            fprintf(stderr, "Error writing LED state: %s\n", strerror(errno));
            goto cleanup;
        }

        if (debounce_ms(touch_line) < 0) {
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) gpiod_line_release(touch_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

