        } else {
            if (gpioWrite(LED_2_PIN, 0) != 0)
                fprintf(stderr, "gpioWrite(GPIO%d, 0) failed\n", LED_2_PIN);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    print_log_buffer();

    return EXIT_SUCCESS;
}

