/*
 * TTP223B capacitive touch sensor monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   Sensor 1 -> GPIO4  (BCM)
 *   Sensor 2 -> GPIO17 (BCM)
 *   LED 1    -> GPIO27 (BCM)
 *   LED 2    -> GPIO22 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp223b_monitor ttp223b_monitor.c -lpigpio -lrt
 * Run:    sudo ./ttp223b_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SENSOR_1_PIN  4
#define SENSOR_2_PIN  17
#define LED_1_PIN     27
#define LED_2_PIN     22

#define DEBOUNCE_US   50000   /* 50 ms debounce window */
#define LOOP_DELAY_US 50000   /* 50 ms polling interval */
#define LOG_BUFFER_SIZE 100

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;

/*
 * Circular buffer entry.
 *   pin:  the GPIO pin that triggered the event
 *   ts:    the timestamp of the event (seconds since epoch)
 *   state: the new state of the sensor (0 = released, 1 = touched)
 */
typedef struct {
    int pin;
    time_t ts;
    int state;
} LogEntry;

static LogEntry g_log_buffer[LOG_BUFFER_SIZE];
static int      g_log_head = 0;   /* next write slot */
static int      g_log_count = 0;  /* number of entries in buffer */
static int      g_overflow = 0;   /* number of entries that would wrap */

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static void log_event(int pin, int state);
static void print_log_buffer(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Turn off LEDs before releasing pigpio resources */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(int pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    /*
     * If the buffer is full, overwrite the oldest entry.
     * This maintains a 100-entry circular buffer.
     */
    if (g_log_count == LOG_BUFFER_SIZE) {
        g_log_head = (g_log_head + 1) % LOG_BUFFER_SIZE;
        g_overflow++;
    }

    g_log_buffer[g_log_head].pin   = pin;
    g_log_buffer[g_log_head].ts    = now;
    g_log_buffer[g_log_head].state = state;

    g_log_head = (g_log_head + 1) % LOG_BUFFER_SIZE;
    if (g_log_count < LOG_BUFFER_SIZE)
        g_log_count++;
}

/* ----------------------------- Buffer dump -------------------------------- */
static void print_log_buffer(void)
{
    printf("\n--- Log Buffer (%d entries, %d overflow) ---\n",
           g_log_count, g_overflow);

    for (int i = 0; i < g_log_count; i++) {
        int idx = (g_log_head - g_log_count + i + LOG_BUFFER_SIZE) % LOG_BUFFER_SIZE;
        printf("  [%2d] pin=%-4d ts=%ld state=%d\n",
               i, g_log_buffer[idx].pin,
               (long)g_log_buffer[idx].ts,
               g_log_buffer[idx].state);
    }

    printf("--- End of Log Buffer ---\n");
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Ensure LEDs start off --- */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TTP223B touch sensor monitor started.\n");
    printf("  Sensor 1: GPIO%d | LED 1: GPIO%d\n", SENSOR_1_PIN, LED_1_PIN);
    printf("  Sensor 2: GPIO%d | LED 2: GPIO%d\n", SENSOR_2_PIN, LED_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "gpioRead(GPIO%d) failed: %s\n",
                    SENSOR_1_PIN, strerror(errno));
        } else if (s1 == 1) {
            if (gpioWrite(LED_1_PIN, 1) != 0)
                fprintf(stderr, "gpioWrite(GPIO%d, 1) failed\n", LED_1_PIN);
            log_event(SENSOR_1_PIN, 1);
        } else {
            if (gpioWrite(LED_1_PIN, 0) != 0)
                fprintf(stderr, "gpioWrite(GPIO%d, 0) failed\n", LED_1_PIN);
        }

        if (s2 < 0) {
            fprintf(stderr, "gpioRead(GPIO%d) failed: %s\n",
                    SENSOR_2_PIN, strerror(errno));
        } else if (s2 == 1) {
            if (gpioWrite(LED_2_PIN, 1) != 0)
                fprintf(stderr, "gpioWrite(GPIO%d, 1) failed\n", LED_2_PIN);
            log_event(SENSOR_2_PIN, 1);
        } else {
            if (gpioWrite(LED_2_PIN, 0) != 0)
                fprintf(stderr, "gpioWrite(GPIO%d, 0) failed\n", LED_2_PIN);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    print_log_buffer();

    return EXIT_SUCCESS;
}

