#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the Hall sensors (BCM numbering)
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Define the debounce time in microseconds
#define DEBOUNCE_TIME_US 5000

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables for the program
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int pin);
int calculate_rpm(int sensor1_state, int sensor2_state);
int log_data(int sensor1_state, int sensor2_state, int rpm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the GPIO pins using pigpio
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Enable pull-down resistors on the input pins (DRV5032FJDBZR outputs HIGH when no magnet is detected)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read the state of the Hall sensor
int read_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return state;
}

// Calculate the RPM based on the sensor states
int calculate_rpm(int sensor1_state, int sensor2_state) {
    // DRV5032FJDBZR outputs HIGH when a magnet is detected
    // We assume that the shaft is rotating clockwise when sensor1 is HIGH and sensor2 is LOW
    if (sensor1_state == 1 && sensor2_state == 0) {
        return 1000; // Example RPM value
    } else if (sensor1_state == 0 && sensor2_state == 1) {
        return -1000; // Example RPM value
    } else {
        return 0;
    }
}

// Log the data to a CSV file
int log_data(int sensor1_state, int sensor2_state, int rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_state, sensor2_state, rpm);
    fclose(fp);
    return 0;
}

int main(void) {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Shaft RPM Monitoring Started. Press Ctrl+C to exit.\n");

    // Variables to store the previous sensor states
    int sensor1_prev_state = 0;
    int sensor2_prev_state = 0;

    // Main loop
    while (program_running) {
        // Read the sensor states
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor states, exiting...\n");
            break;
        }

        // Debounce the sensor states
        gpioDelay(DEBOUNCE_TIME_US); // Wait for 5ms

        int sensor1_debounced_state = read_sensor(SENSOR1_PIN);
        int sensor2_debounced_state = read_sensor(SENSOR2_PIN);

        if (sensor1_debounced_state < 0 || sensor2_debounced_state < 0) {
            fprintf(stderr, "Error reading sensor states after debounce, exiting...\n");
            break;
        }

        // Calculate the RPM
        int rpm = calculate_rpm(sensor1_debounced_state, sensor2_debounced_state);

        // Log the data
        if (log_data(sensor1_debounced_state, sensor2_debounced_state, rpm) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Print the RPM to the console
        printf("RPM: %d\n", rpm);

        // Update the previous sensor states
        sensor1_prev_state = sensor1_debounced_state;
        sensor2_prev_state = sensor2_debounced_state;

        // Delay for 100ms to prevent excessive CPU usage
        gpioDelay(100000); // 100ms
    }

    // Cleanup GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

