#define REG_IRQ_MODE2 0x06
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_RATE 0x0A
#define REG_PS1_RATE 0x0B
#define REG_PS2_RATE 0x0C
#define REG_PS3_RATE 0x0D
#define REG_PS_LED21 0x0E
#define REG_PS_LED3 0x0F
#define REG_ALS_VIS_DATA0 0x14
#define REG_ALS_VIS_DATA1 0x15
#define REG_ALS_IR_DATA0 0x16
#define REG_ALS_IR_DATA1 0x17
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19
#define REG_PS2_DATA0 0x1A
#define REG_PS2_DATA1 0x1B
#define REG_PS3_DATA0 0x1C
#define REG_PS3_DATA1 0x1D
#define REG_COMMAND 0x1F

