static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int si1182_init(void) {
    uint8_t part_id, hw_rev, seq_id;

    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) return -1;
    if (i2c_read_reg(REG_HW_REV, &hw_rev) != 0) return -1;
    if (i2c_read_reg(REG_SEQ_ID, &seq_id) != 0) return -1;

