    if (i2c_write_reg(REG_HW_KEY, 0x17) != 0) return -1;
    if (i2c_write_reg(REG_MEAS_RATE0, 0x0A) != 0) return -1;
    if (i2c_write_reg(REG_MEAS_RATE1, 0x00) != 0) return -1;
