#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27
#define LOG_FILE      "bridge_integrity.log"
#define POLL_DELAY_US 100000  /* 100 ms */
#define ALARM_TIMEOUT_S 2

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not call pigpio functions here. */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped message to the log file.                       */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_message(const char *message)
{
    if (!log_file) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf()");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins.                          */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* Configure sensor pins as inputs with pull-down resistors. */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", SENSOR_1_GPIO);
        return -1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", SENSOR_2_GPIO);
        return -1;
    }

    /* Configure alarm pin as output and ensure it starts LOW. */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_GPIO);
        return -1;
    }
    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", ALARM_GPIO);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin. Returns 0 or 1 on success, -1 on error.         */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", gpio);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Activate the alarm (buzzer/LED).                                    */
/* ------------------------------------------------------------------ */
static void activate_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to activate alarm on GPIO%d.\n", ALARM_GPIO);
    }
}

/* ------------------------------------------------------------------ */
/* Deactivate the alarm (buzzer/LED).                                  */
/* ------------------------------------------------------------------ */
static void deactivate_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate alarm on GPIO%d.\n", ALARM_GPIO);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    deactivate_alarm();

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose()");
        }
        log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO. */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started.\n");
    printf("  Sensor 1: GPIO%d (BCM)\n", SENSOR_1_GPIO);
    printf("  Sensor 2: GPIO%d (BCM)\n", SENSOR_2_GPIO);
    printf("  Alarm:    GPIO%d (BCM)\n", ALARM_GPIO);
    printf("  Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int sensor1_active = 0;
    int sensor2_active = 0;
    int alarm_active = 0;

    while (running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — log and continue. */
            log_message("ERROR: sensor read failure — continuing.");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Log sensor readings. */
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Sensor 1: %d, Sensor 2: %d", s1, s2);
        log_message(msg);

        /* Tilt start event: both sensors HIGH for >= 1 s. */
        if (s1 == 1 && s2 == 1 && !sensor1_active) {
            sensor1_active = 1;
            sensor2_active = 1;
            log_message("Tilt start detected — alarm activated.");
            activate_alarm();
            alarm_active = 1;
        }

        /* Tilt threshold exceeded: both sensors HIGH for >= 2 s. */
        if (s1 == 1 && s2 == 1 && sensor1_active && sensor2_active) {
            if (!alarm_active) {
                log_message("Tilt threshold exceeded — alarm activated.");
                activate_alarm();
                alarm_active = 1;
            }
        } else {
            /* Tilt end event: both sensors LOW. */
            if (s1 == 0 && s2 == 0 && sensor1_active && sensor2_active) {
                sensor1_active = 0;
                sensor2_active = 0;
                log_message("Tilt end detected — alarm deactivated.");
                deactivate_alarm();
                alarm_active = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Bridge integrity monitoring stopped.\n");
    return EXIT_SUCCESS;
}

