/*
 * seismic.c — Raspberry Pi 3 Model B+
 *
 * Reads an Omron D7S-A0011 seismic sensor on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * and logs threshold-exceeding events to seismic_events.log.
 *
 * Build:  gcc -O2 -Wall -o seismic seismic.c -lthe driver library -lm -lrt
 * Run:    sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x48          /* D7S-A0011 default I2C address */

#define CTRL1          0x00          /* Control register 1 */
#define CTRL2          0x01          /* Control register 2 */
#define STATUS         0x02          /* Status register */
#define VIBRATION      0x03          /* Vibration data register */

#define CTRL1_PD       0x01          /* Power-down bit (bit 0) */
#define CTRL2_RESET    0x01          /* Software reset bit (bit 0) */
#define STATUS_RDY     0x01          /* Data ready bit (bit 0) */

#define VIBRATION_THRESHOLD 500.0f
#define ALERT_DURATION_MS  1000
#define POLL_INTERVAL_MS   100
#define MAX_RETRIES       3

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  d7s_init(int fd);
static int  d7s_read_vibration(int fd, float *magnitude);
static void log_event(FILE *fp, float magnitude);
static void trigger_alert(int fd);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- D7S initialization ------------------------ */

static int d7s_init(int fd)
{
    uint8_t status = 0;

    /* Verify sensor presence by reading STATUS register */
    if (i2c_read_reg8(fd, STATUS, &status) < 0) {
        fprintf(stderr, "D7S not responding at 0x%02X\n", D7S_ADDR);
        return -1;
    }

    /* Power down the sensor (clear PD bit) */
    if (i2c_write_reg8(fd, CTRL1, CTRL1_PD) < 0)
        return -1;

    /* Software reset (clear RESET bit) */
    if (i2c_write_reg8(fd, CTRL2, CTRL2_RESET) < 0)
        return -1;

    usleep(10000); /* 10 ms settle after reset */

    /* Clear any pending data */
    if (i2c_write_reg8(fd, CTRL1, 0x00) < 0)
        return -1;

    /* Enable vibration output (bit 0 = 1) */
    if (i2c_write_reg8(fd, CTRL2, 0x01) < 0)
        return -1;

    return 0;
}

/* ----------------------------- Read vibration --------------------------- */

static int d7s_read_vibration(int fd, float *magnitude)
{
    uint8_t status = 0;
    uint8_t raw = 0;
    int16_t  raw_signed;
    int      retries = 0;

    while (retries < MAX_RETRIES) {
        /* Read STATUS register to confirm data-ready */
        if (i2c_read_reg8(fd, STATUS, &status) < 0) {
            retries++;
            usleep(10000);
            continue;
        }

        if (status & STATUS_RDY) {
            /* Read 16-bit vibration data (big-endian) */
            if (i2c_read_reg8(fd, VIBRATION, &raw) < 0) {
                retries++;
                usleep(10000);
                continue;
            }
            raw_signed = (int16_t)((raw << 8) | raw);
            *magnitude = (float)raw_signed;
            return 0;
        }

        retries++;
        usleep(10000);
    }

    fprintf(stderr, "D7S read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_event(FILE *fp, float magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Vibration: %.2f\n", ts, magnitude);
    fflush(fp);
}

/* ----------------------------- Alert ------------------------------------ */

static void trigger_alert(int fd)
{
    printf("ALERT: Vibration threshold exceeded!\n");
    fflush(stdout);

    if (i2c_write_reg8(fd, CTRL1, 0x00) < 0) {
        fprintf(stderr, "Failed to clear CTRL1 after alert\n");
        return;
    }

    usleep(ALERT_DURATION_MS * 1000);

    if (i2c_write_reg8(fd, CTRL1, CTRL1_PD) < 0) {
        fprintf(stderr, "Failed to power down sensor after alert\n");
    }
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, CTRL1, CTRL1_PD);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    float magnitude = 0.0f;

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("seismic_events.log", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open seismic_events.log: %s\n",
                strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        if (d7s_read_vibration(g_i2c_fd, &magnitude) == 0) {
            if (magnitude > VIBRATION_THRESHOLD) {
                log_event(g_log_fp, magnitude);
                trigger_alert(g_i2c_fd);
            }
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

