/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on the GPIO bus (BCM 2, 3, 4, 17, 27)
 * and logs flame events to /var/log/flame_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS          5
#define LOG_FILE             "/var/log/flame_events.log"
#define DEBOUNCE_MS          50
#define POLL_INTERVAL_MS     1000
#define CHIP_NAME            "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int pin, int flame_detected)
{
    time_t rawtime;
    struct tm tm_utc;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed: %s", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame %s\n",
                timestamp, sensor_id, pin,
                flame_detected ? "Detected" : "Not Detected") < 0) {
        syslog(LOG_ERR, "fprintf to log failed: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose failed: %s", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    /* ---- Open syslog early ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               CHIP_NAME, strerror(errno));
        goto cleanup_syslog;
    }

    /* ---- Acquire and request each line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup_chip;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup_chip;
        }
    }

    syslog(LOG_INFO, "Flame monitoring started (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int prev_value = gpiod_line_get_value(lines[i]);
            if (prev_value < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Debounce: wait and re-read */
            usleep(DEBOUNCE_MS * 1000);

            int current_value = gpiod_line_get_value(lines[i]);
            if (current_value < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (prev_value == 1 && current_value == 0) {
                log_event(i, sensor_pins[i], 1);
            } else if (prev_value == 0 && current_value == 1) {
                log_event(i, sensor_pins[i], 0);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down flame monitoring");
    ret = EXIT_SUCCESS;

cleanup_chip:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

cleanup_syslog:
    closelog();
    return ret;
}

