#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x20
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    uint8_t config[2] = {0x00, 0x00};
    if (i2cWriteDevice(handle, (char *)config, 2) != 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 configuration.\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux) {
    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read VEML7700 data.\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux = (float)raw / 100.0f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid brightness value: %d\n", brightness);
        return -1;
    }
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

