        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux) {
    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read VEML7700 data.\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux = (float)raw / 100.0f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
