#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000
#define LOG_FILE "touch_log.txt"

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: Failed to set pull-down on GPIO %d.\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize LED state on GPIO %d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int channel) {
    if (channel < 1 || channel > NUM_CHANNELS) {
        fprintf(stderr, "Error: Invalid channel %d.\n", channel);
        return -1;
    }
    return gpioRead(sensor_pins[channel - 1]);
}

static void log_touch_event(int channel) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time.\n");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: Failed to convert time.\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file.\n");
    }
}

static void control_led(int any_touched) {
    if (gpioWrite(LED_PIN, any_touched ? 1 : 0) != 0) {
        fprintf(stderr, "Error: Failed to write to LED GPIO %d.\n", LED_PIN);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        last_state[i] = read_sensor(i + 1);
        if (last_state[i] < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (program_running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current = read_sensor(i + 1);
            if (current < 0) {
                continue;
            }

            if (current == 1 && last_state[i] == 0) {
                log_touch_event(i + 1);
                any_touched = 1;
            }
            last_state[i] = current;
        }

        control_led(any_touched);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

