#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define ALERT_DURATION_US 1000000 /* 1 second */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown (SIGINT / SIGTERM) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialize pigpio and configure GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", ALERT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure alert pin starts LOW */
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO%d to LOW.\n", ALERT_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read flame sensor digital output (0 = flame detected) */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO%d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return value;
}

/* Log a flame event with timestamp to file */
static int log_flame_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Flame detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush() failed on log file.\n");
    }

    return 0;
}

/* Activate alert pin for specified duration */
static int activate_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d HIGH.\n", ALERT_PIN);
        return -1;
    }

    gpioDelay(ALERT_DURATION_US);

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d LOW.\n", ALERT_PIN);
        return -1;
    }

    return 0;
}

/* Cleanup GPIO resources */
static void cleanup_gpio(void) {
    /* Ensure alert pin is LOW before terminating */
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) {
            /* Flame detected (digital output LOW) */
            if (log_flame_event() != 0) {
                fprintf(stderr, "Warning: Failed to log flame event.\n");
            }

            if (activate_alert() != 0) {
                fprintf(stderr, "Warning: Failed to activate alert.\n");
            }
        } else if (sensor_value < 0) {
            /* Sensor read error; log and continue */
            fprintf(stderr, "Warning: Sensor read error, continuing...\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    cleanup_gpio();

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: Failed to close log file: %s\n", strerror(errno));
        }
    }

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

