#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x48
#define FLOW_CMD 0x20
#define FLOW_DELAY_US 2000
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3
#define FLOW_MIN 0.0f
#define FLOW_MAX 100.0f
#define LOG_FILE "cooling_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t cmd = FLOW_CMD;
    uint8_t buf[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)&cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing command to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(FLOW_DELAY_US);

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: expected 3 bytes, got %d\n", result);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    uint8_t status = buf[2];

    if (raw_flow < 0 || raw_flow > 65535) {
        fprintf(stderr, "Invalid flow rate: %d\n", raw_flow);
        return -1;
    }

    *flow_rate = (float)raw_flow / 10.0f;
    return 0;
}

static void log_data(float flow_rate, uint8_t status, const char *status_str) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%u,%s\n", timestamp, flow_rate, status, status_str);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SLF3S-1300F flow rate. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float flow_rate = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_flow_rate(&flow_rate) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed, retrying...\n", attempt + 1);
            gpioDelay(100000);
        }

        if (success) {
            uint8_t status = 0;
            const char *status_str = "OK";

            if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
                status = 1;
                status_str = "INVALID";
            }

            log_data(flow_rate, status, status_str);
            printf("Flow Rate: %.2f ml/min, Status: %s\n", flow_rate, status_str);
        } else {
            fprintf(stderr, "Failed to read flow rate after %d attempts.\n", MAX_RETRIES);
            fprintf(log_file, "Timestamp,ERROR,0,I2C_READ_FAILURE\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

