                fprintf(stderr, "Warning: Failed to log event.\n");
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return ret;
}

