        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Touch detected, LED state: %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    int ret;
    int led_state = 0;
    int last_touch_state = 0;
    int fd;

    /* Set up signal handlers for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Cannot open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    /* Request the touch sensor line as input */
    ret = ioctl(fd, GPIO_LINE_REQUEST_INPUT, TOUCH_SENSOR_PIN);
    if (ret < 0) {
        fprintf(stderr, "Error: Cannot request GPIO line %d as input: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        close(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    /* Request the LED line as output, initially low */
    ret = ioctl(fd, GPIO_LINE_REQUEST_OUTPUT, LED_PIN, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Cannot request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        close(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int touch_value = ioctl(fd, GPIO_LINE_GET_VALUE, TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
            break;
        }

        /* Detect rising edge (touch detected) */
        if (touch_value == 1 && last_touch_state == 0) {
            led_state = !led_state;
            ret = ioctl(fd, GPIO_LINE_SET_VALUE, LED_PIN, led_state);
            if (ret < 0) {
                fprintf(stderr, "Error: Failed to set GPIO line %d: %s\n", LED_PIN, strerror(errno));
                break;
            }

            if (log_touch_event(led_state) != 0) {
                fprintf(stderr, "Error: Failed to log touch event\n");
            }
        }

        last_touch_state = touch_value;

        /* Poll for 1 second timeout */
        struct timespec ts = { .tv_sec = POLL_TIMEOUT_MS / 1000, .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L };
        ret = nanosleep(&ts, NULL);
        if (ret < 0 && errno != EINTR) {
            fprintf(stderr, "Error: nanosleep failed: %s\n", strerror(errno));
            break;
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    ret = ioctl(fd, GPIO_LINE_SET_VALUE, LED_PIN, 0);
    if (ret < 0) {
        fprintf(stderr, "Warning: Failed to turn off LED during cleanup: %s\n", strerror(errno));
    }
    close(fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

