/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    flame = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FLAME_SENSOR_LINE, strerror(errno));
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                BUZZER_LINE, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(flame, "flame_sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_input(flame): %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer): %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Log startup ---- */
    log_event("System started");

    int last_flame_state = 1;   /* assume no flame at startup */
    int buzzer_active = 0;

    /* ---- Main polling loop ---- */
    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame): %s\n",
                    strerror(errno));
            break;
        }

        /* Detect HIGH-to-LOW transition (LOW = flame detected) */
        if (val == 0 && last_flame_state == 1) {
            log_event("FLAME DETECTED");

            if (!buzzer_active) {
                if (gpiod_line_set_value(buzzer, 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(buzzer ON): %s\n",
                            strerror(errno));
                    break;
                }
                buzzer_active = 1;
            }

            /* Break 2 s into 100 ms slices so we can respond promptly */
            for (int i = 0; i < 20 && g_running; i++) {
                usleep(BUZZER_STEP_US);
            }

            if (gpiod_line_set_value(buzzer, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer OFF): %s\n",
                        strerror(errno));
                break;
            }
            buzzer_active = 0;
        }

        last_flame_state = val;
        usleep(POLL_INTERVAL_US);
    }

    /* ---- Log shutdown ---- */
    log_event("System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, flame, buzzer);
    return ret;
}

