/*
 * TTP223B capacitive touch sensor → LED toggle logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   TTP223B VCC  -> 3.3 V (pin 1)
 *   TTP223B GND  -> GND  (pin 9)
 *   TTP223B OUT -> GPIO4 (BCM, pin 7)  [active HIGH when touched]
 *   LED anode   -> GPIO17 (BCM, pin 11)
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define TOUCH_PIN      4
#define LED_PIN        17
#define LOG_FILE       "touch_log.txt"
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define DEBOUNCE_US    200000  /* 200 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Append a UTC ISO-8601 timestamp to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_touch_event(FILE *fp)
{
    time_t rawtime;
    struct tm tm_utc;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get touch line --- */
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Get LED line --- */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request touch line as input --- */
    if (gpiod_line_request_input(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "gpiod_line_request_input(touch) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Request LED line as output, initial value LOW --- */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(led) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("TTP223B touch sensor → LED toggle logger started.\n");
    printf("Touch GPIO%d (BCM), LED GPIO%d (BCM). Press Ctrl+C to exit.\n",
           TOUCH_PIN, LED_PIN);

    int led_state = 0;
    int last_touch_state = 1;   /* assume released (HIGH) at startup */

    while (g_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            fprintf(stderr, "gpiod_line_get_value(touch) failed: %s\n",
                    strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Detect rising edge: LOW -> HIGH (touch detected) */
        if (touch_value == 0 && last_touch_state == 1) {
            led_state = !led_state;

            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "gpiod_line_set_value(led) failed: %s\n",
                        strerror(errno));
            } else {
                printf("Touch detected! LED %s\n", led_state ? "ON" : "OFF");

                if (log_touch_event(log_fp) != 0) {
                    fprintf(stderr, "Warning: failed to log touch event.\n");
                }
            }

            usleep(DEBOUNCE_US);
        }

        last_touch_state = touch_value;
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off before releasing resources */
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    return ret;
}

