/*
 * TMAG5110A1 Hall-Effect Sensor Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1 latch is open-drain: the line is driven low when a
 * south pole is present (magnet present), and high when the magnet is
 * removed (magnet removed).  The library API reads the line as logic
 * level; the program polls every 100 ms and records state changes
 * with an ISO-8601 timestamp to magnet_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s - Sensor %d: %s\n",
                timestamp, sensor_id,
                state ? "Magnet Present" : "Magnet Removed") < 0) {
        perror("fprintf");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush");
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line,
                     int pin, const char *consumer)
{
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (*chip == NULL) {
        *chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (*chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, pin);
    if (*line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                pin, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input_flags(*line, consumer,
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                pin, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        *line = NULL;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose");
        }
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int prev_state1 = -1, prev_state2 = -1, prev_state3 = -1;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    if (init_gpio(&chip, &line1, SENSOR_1_PIN, "tmag5110a1-s1") != 0) {
        goto cleanup;
    }
    if (init_gpio(&chip, &line2, SENSOR_2_PIN, "tmag5110a1-s2") != 0) {
        goto cleanup;
    }
    if (init_gpio(&chip, &line3, SENSOR_3_PIN, "tmag5110a1-s3") != 0) {
        goto cleanup;
    }

    /* Read initial states without generating false transitions */
    int val1 = gpiod_line_get_value(line1);
    int val2 = gpiod_line_get_value(line2);
    int val3 = gpiod_line_get_value(line3);

    if (val1 < 0 || val2 < 0 || val3 < 0) {
        fprintf(stderr, "Initial GPIO read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    prev_state1 = val1;
    prev_state2 = val2;
    prev_state3 = val3;

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);
        int val3 = gpiod_line_get_value(line3);

        if (val1 < 0 || val2 < 0 || val3 < 0) {
            fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val1 != prev_state1) {
            log_event(1, val1);
            prev_state1 = val1;
        }
        if (val2 != prev_state2) {
            log_event(2, val2);
            prev_state2 = val2;
        }
        if (val3 != prev_state3) {
            log_event(3, val3);
            prev_state3 = val3;
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, line1);
    cleanup(chip, line2);
    cleanup(chip, line3);
    return ret;
}

