/*
 * touch_counter.c — TTP226 8-channel capacitive touch sensor → 8-bit binary counter
 * Board:  Raspberry Pi Zero W
 * Bus:    GPIO chip 0 (BCM numbering)
 * Pins:   TTP226 OUT1..OUT8 -> BCM 5..12
 *        8-bit counter driver -> BCM 17..24 (bit 0 = BCM 17, bit 7 = BCM 24)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE      "touch_log.txt"
#define POLL_MS       10
#define STABILIZE_MS  200

/* TTP226 OUT1..OUT8 -> BCM 5..12 */
static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

/* 8-bit counter driver: bit 0 = BCM 17, bit 7 = BCM 24 */
static const unsigned int counter_pins[8] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Append an ISO-8601 UTC timestamped touch event to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_touch_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Set all eight output pins to 0.
 * Returns 0 on success, -1 on failure.
 */
static int reset_outputs(struct gpiod_line_bulk *out_bulk)
{
    unsigned int vals[8] = {0};
    if (gpiod_line_bulk_set_values(out_bulk, vals) < 0) {
        fprintf(stderr, "Failed to reset output pins: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Set all eight output pins to the 8-bit value.
 * Returns 0 on success, -1 on failure.
 */
static int set_outputs(struct gpiod_line_bulk *out_bulk, unsigned int value)
{
    unsigned int vals[8];
    for (int i = 0; i < 8; i++) {
        vals[i] = (value >> i) & 1;
    }
    if (gpiod_line_bulk_set_values(out_bulk, vals) < 0) {
        fprintf(stderr, "Failed to set output pins: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk *touch_bulk = NULL;
    struct gpiod_line_bulk *out_bulk = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get touch input lines --- */
    touch_bulk = gpiod_chip_get_lines_by_numbers(chip, (unsigned int[]){5, 6, 7, 8, 9, 10, 11, 12});
    if (!touch_bulk) {
        fprintf(stderr, "Failed to get touch input lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_bulk_request_input(touch_bulk, "ttp226-touch") < 0) {
        fprintf(stderr, "Failed to request touch input lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Get output lines --- */
    out_bulk = gpiod_chip_get_lines_by_numbers(chip, (unsigned int[]){17, 18, 19, 20, 21, 22, 23, 24});
    if (!out_bulk) {
        fprintf(stderr, "Failed to get output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_bulk_request_output(out_bulk, "counter-driver", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Stabilize sensor --- */
    usleep(STABILIZE_MS * 1000);

    /* --- Main polling loop --- */
    int counter = 0;
    int last_state[NUM_CHANNELS];
    int first_read = 1;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        last_state[i] = gpiod_line_get_value(touch_bulk, touch_pins[i]);
        if (last_state[i] < 0) {
            fprintf(stderr, "Failed to read initial state of channel %d: %s\n",
                    i + 1, strerror(errno));
            goto cleanup;
        }
        if (first_read) {
            first_read = 0;
        }
    }

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(touch_bulk, touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading channel %d: %s\n",
                        i + 1, strerror(errno));
                continue;
            }

            /* Rising edge: idle 0 -> touched 3.3 V */
            if (val == 1 && last_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                if (set_outputs(out_bulk, counter) < 0) {
                    fprintf(stderr, "Warning: failed to set output for channel %d\n",
                            i + 1);
                }
                if (log_touch_event(i + 1, counter) < 0) {
                    fprintf(stderr, "Warning: failed to log touch event for channel %d\n",
                            i + 1);
                }
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            last_state[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

    if (reset_outputs(out_bulk) < 0) {
        fprintf(stderr, "Warning: failed to reset outputs during shutdown\n");
    }

cleanup:
    if (touch_bulk) {
        gpiod_line_bulk_release(touch_bulk);
    }
    if (out_bulk) {
        gpiod_line_bulk_release(out_bulk);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

