#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define LOG_FILE "tracking_log.csv"

static const int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Enable internal pull-down resistor so the line reads 0 when no obstacle */
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", sensor_pins[i]);
        }
    }

    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d (pigpio error %d).\n", pin, value);
        return -1;
    }
    /* KY-033 modules output is active-low: 0 = obstacle detected, 1 = no obstacle */
    return (value == 0) ? 1 : 0;
}

static int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush() failed on log file: %s\n", strerror(errno));
    }

    return 0;
}

int main(void) {
    FILE *fp = NULL;
    int ret_code = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header.\n");
            goto cleanup_file;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Warning: fflush() failed on header: %s\n", strerror(errno));
        }
    }

    printf("Tracking data started. Press Ctrl+C to stop.\n");

    /* Main polling loop */
    while (program_running) {
        int sensor1 = read_sensor(sensor_pins[0]);
        int sensor2 = read_sensor(sensor_pins[1]);
        int sensor3 = read_sensor(sensor_pins[2]);
        int sensor4 = read_sensor(sensor_pins[3]);

        if (sensor1 < 0 || sensor2 < 0 || sensor3 < 0 || sensor4 < 0) {
            fprintf(stderr, "Error: sensor read failed, skipping this sample.\n");
        } else {
            if (log_data(fp, sensor1, sensor2, sensor3, sensor4) != 0) {
                fprintf(stderr, "Error: logging failed, continuing.\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup_file:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Warning: fclose() failed: %s\n", strerror(errno));
        }
    }

cleanup_gpio:
    gpioTerminate();

    return ret_code;
}

