static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_tilt_event(int sensor_number) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void) {
    int ret;
    int prev_state17 = 1;
    int prev_state18 = 1;
    struct timespec last_event_time17 = {0, 0};
    struct timespec last_event_time18 = {0, 0};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN_18, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line17, "tilt_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input with pull-up: %s\n", GPIO_PIN_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line18, "tilt_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input with pull-up: %s\n", GPIO_PIN_18, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n", GPIO_PIN_17, strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val18 < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n", GPIO_PIN_18, strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (val17 == 0 && prev_state17 == 1) {
            if (difftime(now.tv_sec, last_event_time17.tv_sec) >= DEBOUNCE_MS / 1000.0) {
                if (log_tilt_event(1) == 0) {
                    printf("Sensor 1 tilted\n");
                }
                last_event_time17 = now;
            }
        }

        if (val18 == 0 && prev_state18 == 1) {
            if (difftime(now.tv_sec, last_event_time18.tv_sec) >= DEBOUNCE_MS / 1000.0) {
                if (log_tilt_event(2) == 0) {
                    printf("Sensor 2 tilted\n");
                }
                last_event_time18 = now;
            }
        }

        prev_state17 = val17;
        prev_state18 = val18;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

