#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN    22
#define LOG_FILE   "obstacle_log.csv"
#define POLL_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1 on success, -1 on error.        */
/* TCRT5000 modules are active-low: 0 = obstacle, 1 = clear.          */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV; returns 0 on success, -1 on error.          */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, int s1, int s2, int led)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if pigpio is not initialised.   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins ----------------------------------------- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR2_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    long pos = ftell(g_log);
    if (pos == 0) {
        fprintf(g_log, "timestamp,sensor1,sensor2,led_state\n");
        fflush(g_log);
    }

    printf("Obstacle avoidance system started.\n");
    printf("  Sensor1: GPIO%d  Sensor2: GPIO%d  LED: GPIO%d\n",
           SENSOR1_PIN, SENSOR2_PIN, LED_PIN);
    printf("  Logging to '%s' every 100 ms. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — keep LED off and wait before retry */
            gpioWrite(LED_PIN, 0);
            gpioDelay(POLL_US);
            continue;
        }

        /* TCRT5000 modules are active-low: 0 = obstacle, 1 = clear */
        int led = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, led) != 0) {
            fprintf(stderr, "gpioWrite(LED_PIN, %d) failed\n", led);
        }

        if (log_sample(g_log, s1, s2, led) != 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Obstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

