/*
 * ICS-40180 Analog MEMS Microphone Sampler for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ICS-40180 VDD  -> 3.3 V (Pin 1)
 *   ICS-40180 GND  -> GND  (Pin 9)
 *   ICS-40180 OUT  -> GPIO4 (BCM, Pin 7)  [digital input]
 *   LED anode     -> GPIO17 (BCM, Pin 11) [via ~330 Ω resistor]
 *   LED cathode   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mic_sampler mic_sampler.c -lpigpio -lrt
 *   sudo ./mic_sampler
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO          4
#define LED_GPIO          17
#define SAMPLE_PERIOD_US  125   /* 8 kHz polling */
#define LED_ON_US         100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s.%03ld] ", buf, ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure LED is off before releasing pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_GPIO %d as input.\n", MIC_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_GPIO %d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_GPIO %d to LOW.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICS-40180 Microphone Sampler running.\n");
    printf("  MIC_GPIO: %d (BCM)\n", MIC_GPIO);
    printf("  LED_GPIO: %d (BCM)\n", LED_GPIO);
    printf("  Sample period: %d us\n", SAMPLE_PERIOD_US);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int level = gpioRead(MIC_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on MIC_GPIO %d.\n", MIC_GPIO);
            break;
        }

        if (level == 1) {
            print_timestamp_ms();
            printf("Sound detected!\n");
            fflush(stdout);

            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED_GPIO, 1) failed.\n");
            }

            /*
             * gpioDelay is a busy-wait delay that blocks for the given
             * microseconds.  We use it here to keep the main loop responsive
             * to signals.  gpioDelay returns the actual number of microseconds
             * that the call took, which is checked to ensure the LED stays
             * on for the full 100 ms.
             */
            uint32_t elapsed = 0;
            while (elapsed < LED_ON_US && g_running) {
                elapsed += gpioDelay(SAMPLE_PERIOD_US);
            }

            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED_GPIO, 0) failed.\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

