#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define LEFT_PIN  2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() == -1) {
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        goto cleanup;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        perror("gpiod_chip_get_line(LEFT_PIN)");
        goto cleanup;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (!middle_line) {
        perror("gpiod_chip_get_line(MIDDLE_PIN)");
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        perror("gpiod_chip_get_line(RIGHT_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "keywish-3way-left") < 0) {
        perror("gpiod_line_request_input(left_line)");
        goto cleanup;
    }

    if (gpiod_line_request_input(middle_line, "keywish-3way-middle") < 0) {
        perror("gpiod_line_request_input(middle_line)");
        goto cleanup;
    }

    if (gpiod_line_request_input(right_line, "keywish-3way-right") < 0) {
        perror("gpiod_line_request_input(right_line)");
        goto cleanup;
    }

    printf("L:M:R: left middle right\n");

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0) {
            perror("gpiod_line_get_value(left_line)");
            goto cleanup;
