/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TP1 -> GPIO5  (BCM)
 *   TP2 -> GPIO6  (BCM)
 *   TP3 -> GPIO13 (BCM)
 *   TP4 -> GPIO19 (BCM)
 *   TP5 -> GPIO26 (BCM)
 *   TP6 -> GPIO12 (BCM)
 *   TP7 -> GPIO16 (BCM)
 *   TP8 -> GPIO20 (BCM)
 *
 * Build:
 *   gcc -o touch_poll touch_poll.c -lrt
 *
 * Run:
 *   ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 200000  /* 200 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one channel value from the TTP226.
 * Returns 0 on success (value stored in *out), -1 on error.
 */
static int read_channel(struct gpiod_line *line, int offset, int *out)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "[ERROR] gpiod_line_get_value(offset=%d) failed: %s\n",
                offset, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/*
 * Build a timestamp string in the form "[12.345s]".
 * Returns 0 on success, -1 on error.
 */
static int build_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        fprintf(stderr, "[ERROR] clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    double elapsed = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    if (snprintf(buf, len, "[%.3fs] ", elapsed) < 0) {
        fprintf(stderr, "[ERROR] snprintf failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int offsets[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "[ERROR] gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "[ERROR] gpiod_chip_get_line(offset=%d) failed: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "[ERROR] gpiod_line_request_input(offset=%d) failed: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        char ts[32];
        if (build_timestamp(ts, sizeof(ts)) != 0) {
            break;
        }

        int values[NUM_CHANNELS];
        int all_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (read_channel(lines[i], offsets[i], &values[i]) != 0) {
                all_ok = 0;
                break;
            }
        }

        if (all_ok) {
            printf("%sCH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
                   ts, values[0], values[1], values[2], values[3],
                   values[4], values[5], values[6], values[7]);
            fflush(stdout);
        } else {
            fprintf(stderr, "%s[ERROR] Failed to read all channels\n", ts);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

