#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255
#define STEPS      50
#define INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

static int random_hue(void)
{
    FILE *fp = fopen("/dev/urandom", "r");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %m");
        return 0;
    }
    uint8_t buf[3];
    if (fread(buf, 1, sizeof(buf), fp) != sizeof(buf)) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(fp);
        return 0;
    }
    fclose(fp);
    return (int)(((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2]) % 360;
}

static int linear_interpolate(int start, int end, int steps, int step)
{
    int delta = end - start;
    if (delta == 0) return start;
    return start + (delta * step) / steps;
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int start_hue = random_hue();
        int end_hue   = random_hue();

        syslog(LOG_INFO, "Starting fade from hue %d to hue %d", start_hue, end_hue);

        for (int step = 0; step < STEPS && g_running; step++) {
            int red   = linear_interpolate(0, 255, STEPS, step);
            int green = linear_interpolate(0, 255, STEPS, step);
            int blue  = linear_interpolate(0, 255, STEPS, step);

            if (set_led_color(red, green, blue) < 0) {
                syslog(LOG_ERR, "Failed to set LED color during fade");
                break;
            }

            gpioDelay(INTERVAL_S * 1000000);
        }

        if (!g_running) break;

        if (set_led_color(0, 0, 0) < 0) {
            syslog(LOG_ERR, "Failed to turn off LED during fade");
            break;
        }
    }

    syslog(LOG_INFO, "Shutting down");
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

