    usleep(3000);

    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) return -1;
    usleep(3000);

    return 0;
}

static int tcs34725_read_crgb(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

