    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "tcs34725-led", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    printf("TCS34725 ready. Polling every %d ms. Press Ctrl+C to exit.\n", POLL_DELAY_MS);

    while (running) {
        uint16_t c, r, g, b;
        if (tcs34725_read_crgb(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Sensor read error; re-initializing...\n");
            usleep(INIT_DELAY_MS * 1000);
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed; continuing to retry.\n");
            }
            continue;
        }

        printf("C=%5u  R=%5u  G=%5u  B=%5u\n", c, r, g, b);

        int led_val = (r > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_val) < 0) {
            perror("gpiod_line_set_value");
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

