/*
 * Raspberry Pi 4 Model B - BH1750 Ambient Light Sensor -> WS2812B LED Strip
 *
 * Reads ambient light from a BH1750 digital light sensor on I2C bus 1
 * (GPIO2 = SDA, GPIO3 = SCL), then maps the lux value to a logarithmic
 * brightness level for a 10-LED WS2812B strip on GPIO18 (PCM_CLK).
 *
 * Build: gcc -O2 -Wall -o light_strip light_strip.c -lpigpio -lrt
 * Run:   sudo ./light_strip
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x29
#define BH1750_CMD_OT_H 0x10   /* One-Time High Resolution Mode */
#define BH1750_CONV_MS 180     /* Conversion time for OT_H mode */
#define LED_COUNT      10
#define LED_GPIO       18
#define PWM_FREQ       1000    /* 1 kHz PWM frequency */
#define PWM_RANGE      1000    /* 1 kHz range */
#define MAX_LUX        1000.0f
#define MIN_LUX        0.0f
#define MIN_BRIGHTNESS 0.0f
#define MAX_BRIGHTNESS 1.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* BH1750 initialization                                              */
/* ------------------------------------------------------------------ */
static int bh1750_init(int handle)
{
    /* Power on the sensor by writing 0x01 to the power register */
    if (i2cWriteByteData(handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to power on BH1750 (sensor absent?)\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ambient light from BH1750                                        */
/* Returns lux value on success, or -1.0 on error.                    */
/* ------------------------------------------------------------------ */
static float bh1750_read_lux(int handle)
{
    /* Issue one-time high-resolution measurement command */
    if (i2cWriteByte(handle, BH1750_CMD_OT_H) < 0) {
        fprintf(stderr, "Error: Failed to write BH1750 command\n");
        return -1.0f;
    }

    /* Wait for conversion to complete (datasheet: max 180 ms) */
    gpioDelay(BH1750_CONV_MS * 1000);

    /* Read 2 bytes of data from the sensor */
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data (got %d bytes)\n",
                bytes_read);
        return -1.0f;
    }

    /* Convert raw data to lux (datasheet: 1 lux = 1.2 mg) */
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    float lux = (float)raw / 1.2f;

    /* Clamp lux to valid range */
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;

    return lux;
}

/* ------------------------------------------------------------------ */
/* Map lux value to brightness level (0.0 -> 1.0)                     */
/* ------------------------------------------------------------------ */
static float lux_to_brightness(float lux)
{
    if (lux <= MIN_LUX) return MIN_BRIGHTNESS;
    if (lux >= MAX_LUX) return MAX_BRIGHTNESS;
    return (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
}

/* ------------------------------------------------------------------ */
/* Generate WS2812B data for a single LED                             */
/* ------------------------------------------------------------------ */
static void led_set_color(uint8_t led_index, uint8_t r, uint8_t g, uint8_t b)
{
    /* WS2812B expects data in the following format:
     *   Byte 0: GRB data (low 2 bits of each color)
     *   Byte 1: GRB data (high 6 bits of each color)
     *   Byte 2: GRB data (low 2 bits of each color)
     *   Byte 3: GRB data (high 6 bits of each color)
     *   Byte 4: GRB data (low 2 bits of each color)
     *   Byte 5: GRB data (high 6 bits of each color)
     */
    uint8_t data[6];
    data[0] = (g & 0x3F) << 2;
    data[1] = ((g >> 6) & 0x3F) << 2;
    data[2] = (r & 0x3F) << 2;
    data[3] = ((r >> 6) & 0x3F) << 2;
    data[4] = (b & 0x3F) << 2;
    data[5] = ((b >> 6) & 0x3F) << 2;

    /* Send 24 bits of data for each LED */
    for (int i = 0; i < 6; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            gpioPWM(LED_GPIO, (data[i] >> bit) & 1);
            gpioDelay(1); /* ~1 us high pulse */
        }
    }

    /* Send 8 bits of zero data to latch the data */
    for (int i = 0; i < 8; i++) {
        gpioPWM(LED_GPIO, 0);
        gpioDelay(1);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    /* Set PWM frequency and range */
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    /* Open I2C bus to BH1750 */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize BH1750 sensor */
    if (bh1750_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BH1750 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Light strip control started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float lux = bh1750_read_lux(g_i2c_handle);

        if (lux < 0.0f) {
            fprintf(stderr, "Warning: Failed to read lux value, retrying...\n");
            gpioDelay(100000); /* 100 ms backoff before retry */
            continue;
        }

        float brightness = lux_to_brightness(lux);

        /* Map brightness to LED color values (0.0 -> 0xFF, 1.0 -> 0x00) */
        uint8_t r = (uint8_t)(brightness * 255.0f);
        uint8_t g = (uint8_t)((1.0f - brightness) * 255.0f);
        uint8_t b = 0;

        /* Set LED colors for all LEDs */
        for (int i = 0; i < LED_COUNT; i++) {
            led_set_color(i, r, g, b);
        }

        gpioDelay(10000); /* 10 ms delay between readings */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

