#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x29
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONTINUOUS_HIGH_RES 0x10
#define BH1750_CONV_TIME_US 180000

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8

#define NUM_LEDS 10
#define MAX_LIGHT_LEVEL 65535

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_POWER_ON, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_RESET, 0x07) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_POWER_ON, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH_RES, 0x10) < 0) return -1;
    return 0;
}

static int bh1750_read_light(int fd, uint16_t *light_level) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, 0x00, buf, 2) < 0) return -1;
    *light_level = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int apa102_send_frame(uint8_t *frame, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)frame,
        .rx_buf = 0,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void apa102_set_led(uint8_t *frame, int led_index, uint8_t brightness) {
    if (led_index < 0 || led_index >= NUM_LEDS) return;

    size_t offset = 4 + (led_index * 4);
    frame[offset] = brightness;
    frame[offset + 1] = 0;
    frame[offset + 2] = 0;
    frame[offset + 3] = 0;
}

static void apa102_all_off(uint8_t *frame) {
    for (int i = 0; i < NUM_LEDS; i++) {
        apa102_set_led(frame, i, 0);
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        apa102_all_off((uint8_t *)frame);
        apa102_send_frame((uint8_t *)frame, 4 + (NUM_LEDS * 4) + 4);
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    uint8_t *frame = malloc(4 + (NUM_LEDS * 4) + 4);
    if (!frame) {
        fprintf(stderr, "Failed to allocate frame buffer\n");
        cleanup();
        return 1;
    }

    printf("Starting light-to-LED mapping...\n");

    while (running) {
        uint16_t light_level = 0;
        if (bh1750_read_light(i2c_fd, &light_level) < 0) {
            fprintf(stderr, "Failed to read light level, retrying...\n");
            usleep(100000);
            continue;
        }

        if (light_level > MAX_LIGHT_LEVEL) light_level = MAX_LIGHT_LEVEL;

        uint8_t brightness = (uint8_t)((light_level * 255) / MAX_LIGHT_LEVEL);

        for (int i = 0; i < NUM_LEDS; i++) {
            apa102_set_led(frame, i, brightness);
        }

        if (apa102_send_frame(frame, 4 + (NUM_LEDS * 4) + 4) < 0) {
            fprintf(stderr, "Failed to send APA102 frame\n");
        }

        usleep(120000);
    }

    printf("\nShutting down...\n");
    cleanup();
    free(frame);
    return 0;
}

