#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100
#define CONVERSION_DELAY_MS 180

#define BH1750_ADDR_1 0x29
#define BH1750_ADDR_2 0x5C

static int i2c_handles[NUM_SENSORS];
static int spi_handle;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

static int init_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

static int read_light_level(int handle) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)raw;
}

static int average_light_levels(int handles[], int num_handles) {
    int sum = 0;
    int valid_count = 0;
    for (int i = 0; i < num_handles; i++) {
        int level = read_light_level(handles[i]);
        if (level >= 0) {
            sum += level;
            valid_count++;
        }
    }
    if (valid_count == 0) {
        return -1;
    }
    return sum / valid_count;
}

static void set_led_brightness(int spi_handle, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t data[4 * NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        data[4 * i] = 0xE0;
        data[4 * i + 1] = 0x00;
        data[4 * i + 2] = (uint8_t)brightness;
        data[4 * i + 3] = 0x00;
    }

    int result = spiWrite(spi_handle, (char *)data, sizeof(data));
    if (result != (int)sizeof(data)) {
        fprintf(stderr, "Error writing to SPI device: %d\n", result);
    }
}

static void fade_led_brightness(int spi_handle, int target_brightness) {
    int current_brightness = 0;
    int increment = (target_brightness > current_brightness) ? 1 : -1;
    int steps = (target_brightness > current_brightness) ? target_brightness - current_brightness : current_brightness - target_brightness;
    if (steps == 0) return;

    for (int i = 0; i < steps && !terminate; i++) {
        current_brightness += increment;
        set_led_brightness(spi_handle, current_brightness);
        gpioDelay(FADE_DURATION_MS * 1000);
    }
    set_led_brightness(spi_handle, target_brightness);
}

static void cleanup(void) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int addresses[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_1};
    int valid_sensors = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        int handle = init_i2c(I2C_BUS, addresses[i]);
        if (handle >= 0) {
            i2c_handles[i] = handle;
            valid_sensors++;
        }
    }

    if (valid_sensors == 0) {
        fprintf(stderr, "No valid BH1750 sensors found on I2C bus %d\n", I2C_BUS);
        cleanup();
        return 1;
    }

    spi_handle = init_spi(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
