/*
 * VEML7700 Ambient Light Sensor -> WS2812B LED Strip Brightness Controller
 * Board: Raspberry Pi 5
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * LED: WS2812B data line (GPIO18, BCM)
 *
 * Build: gcc -O2 -Wall -o veml7700_led veml7700_led.c -lpigpio -lrt
 * Run:   sudo ./veml7700_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x10
#define LED_GPIO       18
#define NUM_LEDS       10
#define RETRY_COUNT    3
#define RETRY_DELAY_US 100000  /* 100 ms */
#define LOOP_DELAY_US  200000  /* 200 ms */

/* VEML7700 register addresses */
#define VEML7700_REG_ALS_CONF  0x00
#define VEML7700_REG_ALS_DATA0 0x04
#define VEML7700_REG_ALS_DATA1 0x05

/* ALS_CONF: ALS_EN=1, ALS_SD=0 (power on), ALS_IT=0 (no interrupt) */
#define VEML7700_ALS_CONF_VAL 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(fd, buf, 2) != 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (i2cWriteDevice(fd, (char *)&reg, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(fd, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VEML7700 initialization                                             */
/* ------------------------------------------------------------------ */
static int veml7700_init(int fd)
{
    uint8_t conf;
    if (i2c_read_reg(fd, VEML7700_REG_ALS_CONF, &conf) != 0) {
        return -1;
    }
    if (conf != VEML7700_ALS_CONF_VAL) {
        fprintf(stderr, "VEML7700 not responding (CONF=0x%02X, expected 0x%02X)\n",
                conf, VEML7700_ALS_CONF_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ambient light (lux)                                           */
/* ------------------------------------------------------------------ */
static int veml7700_read_lux(int fd, float *lux_out)
{
    uint8_t data0, data1;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_read_reg(fd, VEML7700_REG_ALS_DATA0, &data0) != 0) {
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2c_read_reg(fd, VEML7700_REG_ALS_DATA1, &data1) != 0) {
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)data1 << 8) | data0;
        /*
         * VEML7700 datasheet: ALS_DATA0[15:0] = lux * 1.25
         * ALS_DATA1[15:0] = lux * 1.25
         */
        *lux_out = (float)raw * 1.25f;
        return 0;
    }

    fprintf(stderr, "VEML7700 read failed after %d retries\n", RETRY_COUNT);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Gamma correction (approximate)                                       */
/* ------------------------------------------------------------------ */
static uint8_t gamma_correct(uint8_t value)
{
    return (uint8_t)((float)value * 0.8f);
}

/* ------------------------------------------------------------------ */
/* WS2812B bit-banging (800 kHz)                                       */
/* ------------------------------------------------------------------ */
static void ws2812b_send(uint8_t *data, int num_leds)
{
    /*
     * WS2812B protocol: 800 kHz, 50 µs high/low pulse widths.
     * We use a simple threshold-based approach: each bit is 50 µs high
     * if the bit is 1, 50 µs low if 0.
     */
    for (int i = 0; i < num_leds; i++) {
        uint8_t byte = data[i];
        for (int bit = 7; bit >= 0; bit--) {
            gpioWrite(LED_GPIO, (byte >> bit) & 1);
            gpioDelay(50);  /* 50 µs high */
            gpioWrite(LED_GPIO, 0);
            gpioDelay(50);  /* 50 µs low */
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VEML7700 */
    if (veml7700_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VEML7700 ambient light sensor -> WS2812B LED strip\n");
    printf("Press Ctrl+C to exit.\n\n");

    uint8_t led_data[NUM_LEDS];

    while (g_running) {
        float lux;
        if (veml7700_read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Skipping cycle due to read error\n");
        } else {
            uint8_t brightness = gamma_correct((uint8_t)(lux / 10.0f));
            for (int i = 0; i < NUM_LEDS; i++) {
                led_data[i] = brightness;
            }
            ws2812b_send(led_data, NUM_LEDS);
            printf("Lux: %.2f, Brightness: %u\n", lux, brightness);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

