#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define SELF_TEST_COUNT 5
#define SELF_TEST_INTERVAL_US 100000
#define LED_BLINK_INTERVAL_US 500000
#define BUZZER_DURATION_US 200000
#define BUZZER_PATTERN_COUNT 3
#define BUZZER_PATTERN_DURATION_US 200000
#define BUZZER_PATTERN_DELAY_US 600000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void blink_led(int duration_us) {
    if (gpioWrite(LED_PIN, 1) < 0) {
        log_event("Error: Failed to set LED high");
        return;
    }
    gpioDelay(duration_us);
    if (gpioWrite(LED_PIN, 0) < 0) {
        log_event("Error: Failed to set LED low");
    }
}

static void blink_led_rapidly(int count, int duration_us) {
    for (int i = 0; i < count && running; i++) {
        blink_led(duration_us);
        if (i < count - 1) {
            gpioDelay(duration_us);
        }
    }
}

static void play_buzzer_pattern(int count, int duration_us) {
    for (int i = 0; i < count && running; i++) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("Error: Failed to set buzzer high");
            return;
        }
        gpioDelay(duration_us);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("Error: Failed to set buzzer low");
            return;
        }
        if (i < count - 1) {
            gpioDelay(duration_us);
        }
    }
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        log_event("Error: Failed to read flame sensor");
        return -1;
    }
    return value;
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        cleanup();
