#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>

#define BH1750_ADDR        0x29
#define BH1750_PWR_ON      0x01
#define BH1750_PWR_OFF     0x00
#define BH1750_CONT_HRES   0x10
#define BH1750_CONV_TIME_US 180000  /* 180 ms for high-resolution mode */
#define BUFFER_SIZE        60
#define LED_GPIO           17
#define I2C_BUS            "/dev/i2c-1"
#define SAMPLE_INTERVAL_S  1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_PWR_ON, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HRES, 0x10) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_word(fd, BH1750_CONT_HRES, &raw) < 0) return -1;
    *lux = (float)raw / 1.2f;
    return 0;
}

static void circular_buffer_add(float lux, float buffer[], int *index, int *count) {
    buffer[*index] = lux;
    *index = (*index + 1) % BUFFER_SIZE;
    if (*count < BUFFER_SIZE) *count++;
}

static float circular_buffer_average(float buffer[], int count) {
    if (count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < count; i++) sum += buffer[i];
    return sum / count;
}

static void set_led_frequency(float lux) {
    float freq = 0.5f + (lux / 1000.0f) * 4.0f;
    if (freq < 0.5f) freq = 0.5f;
    if (freq > 5.0f) freq = 5.0f;
    gpiod_line_set_value(led_line, 1);
    usleep((useconds_t)(1000000.0f / freq));
    gpiod_line_set_value(led_line, 0);
    usleep((useconds_t)(1000000.0f / freq));
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "bh1750_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            circular_buffer_add(lux, lux_buffer, &buffer_index, &buffer_count);
            float avg_lux = circular_buffer_average(lux_buffer, buffer_count);
            printf("Lux: %.2f, Average: %.2f\n", lux, avg_lux);
            set_led_frequency(avg_lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

