#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEG_A 1
#define SEG_B 2
#define SEG_C 4
#define SEG_D 8
#define SEG_E 16
#define SEG_F 32
#define SEG_G 64
#define SEG_DP 128

static const int segments[] = {SEG_A, SEG_B, SEG_C, SEG_D, SEG_E, SEG_F, SEG_G, SEG_DP};
static const int num_segments = 8;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void shift_out(int data) {
    for (int i = 0; i < 8; i++) {
        gpioWrite(CLOCK_PIN, 0);
        gpioWrite(DATA_PIN, (data >> i) & 1);
        gpioWrite(CLOCK_PIN, 1);
    }
}

static void latch_data(void) {
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1);
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1);
}

static void display_digit(int digit) {
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return;
    }

    int pattern = 0;
    switch (digit) {
        case 0: pattern = SEG_A | SEG_B | SEG_C | SEG_D | SEG_E | SEG_F; break;
        case 1: pattern = SEG_B | SEG_C; break;
        case 2: pattern = SEG_A | SEG_B | SEG_D | SEG_E | SEG_G; break;
        case 3: pattern = SEG_A | SEG_B | SEG_C | SEG_D | SEG_G; break;
        case 4: pattern = SEG_B | SEG_C | SEG_F | SEG_G; break;
        case 5: pattern = SEG_A | SEG_C | SEG_D | SEG_F | SEG_G; break;
        case 6: pattern = SEG_A | SEG_C | SEG_D | SEG_E | SEG_F | SEG_G; break;
        case 7: pattern = SEG_A | SEG_B | SEG_C; break;
        case 8: pattern = SEG_A | SEG_B | SEG_C | SEG_D | SEG_E | SEG_F | SEG_G; break;
        case 9: pattern = SEG_A | SEG_B | SEG_C | SEG_D | SEG_F | SEG_G; break;
        default:
            fprintf(stderr, "Invalid digit: %d\n", digit);
            return;
    }

    for (int i = 0; i < num_segments; i++) {
        gpioWrite(segments[i], (pattern >> i) & 1);
    }
    latch_data();
}

static void blink_digit(int digit, int on_ms, int off_ms) {
    while (running) {
        display_digit(digit);
        gpioDelay(on_ms * 1000);
        if (!running) break;
        display_digit(0);
        gpioDelay(off_ms * 1000);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
