#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN      17
#define BUTTON_PIN   18
#define CHIP_NAME    "gpiochip0"
#define BLINK_PERIOD_MS 2000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    /* Request the LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        goto cleanup;
    }

    /* Request the button line as input with pull-up */
    ret = gpiod_line_request_input_flags(button_line, "blink_button",
                                         GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags (button)");
        goto cleanup;
    }

    /* Request event detection on the button line */
    ret = gpiod_line_request_event_falling_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("gpiod_line_request_event_falling_edge_events (button)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d (period %d ms) while waiting for button press on GPIO%d.\n",
           LED_PIN, BLINK_PERIOD_MS, BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main blink loop */
    while (running) {
        /* Wait for a falling edge event with a 1-second timeout */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout — no event — loop back and check running flag */
            continue;
        }

        /* Event detected — read it to clear the queue */
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        /* Turn off the LED */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off)");
            break;
        }

        printf("Button pressed! LED stopped.\n");
        fflush(stdout);

        /* Stop blinking immediately */
        break;
    }

cleanup:
    /* Ensure LED is off on every exit path */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

