#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define LED_PIN      24
#define BUTTON_PIN   22
#define CHIP_NAME    "gpiochip0"
#define CONSUMER     "led-button"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(button_line, CONSUMER,
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to request line %d as input with pull-down: %s\n",
                BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    printf("LED blinking on GPIO%d (anode) and button on GPIO%d (pull-down).\n",
           LED_PIN, BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(button_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read button: %s\n", strerror(errno));
            goto cleanup;
        }

        if (val == 0) {
            /* Button pressed: blink LED */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
                goto cleanup;
            }
            usleep(500000);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                goto cleanup;
            }
            usleep(500000);
        } else {
            /* Button released: keep LED off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                goto cleanup;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line)
        gpiod_line_release(led_line);
    if (button_line)
        gpiod_line_release(button_line);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

