#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C address (SA0 tied to GND) */
#define LSM303_ADDR 0x19

/* LSM303DLHC register addresses */
#define LSM303_CTRL_REG1_A 0x20
#define LSM303_CTRL_REG4_A 0x23
#define LSM303_OUT_X_L_A 0x28

/* GPIO pin for impact interrupt (BCM numbering) */
#define IMPACT_GPIO 17

/* Default threshold in G */
#define DEFAULT_THRESHOLD 2.0f

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to initialize the LSM303DLHC accelerometer */
static int init_lsm303(int handle) {
    /*
     * CTRL_REG1_A: 0x57
     *   ODR[3:0] = 0101 (100 Hz)
     *   Zen = 0, Yen = 0, Xen = 1
     *   Normal mode, all axes enabled
     */
    if (i2cWriteByteData(handle, LSM303_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    /*
     * CTRL_REG4_A: 0x00
     *   FS[1:0] = 00 (±2g full scale)
     *   HR = 0, SIM = 0
     */
    if (i2cWriteByteData(handle, LSM303_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data from the LSM303DLHC */
static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];

    /* Read 6 bytes starting from OUT_X_L_A (0x28) */
    if (i2cReadI2CBlockData(handle, LSM303_OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Convert to G-force units (±2g full scale) */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

/* Function to calculate the total G-force magnitude */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Function to trigger the impact interrupt */
static void trigger_impact(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(50000); /* 50 ms in microseconds */
    gpioWrite(gpio_pin, 0);
}

/* Function to log the accelerometer data to a file */
static void log_data(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f, Magnitude: %.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);

    fclose(fp);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;

    /* Parse command-line arguments */
    if (argc > 1) {
        threshold = strtof(argv[1], NULL);
        if (threshold <= 0.0f) {
            fprintf(stderr, "Invalid threshold. Using default: %.2f G\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        } else {
            printf("Using threshold: %.2f G\n", threshold);
        }
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO17 as output */
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0);

    /* Open I2C bus 1 at LSM303DLHC address */
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the LSM303DLHC accelerometer */
    if (init_lsm303(i2c_handle) < 0) {
        fprintf(stderr, "LSM303DLHC initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Impact detection system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        float x, y, z, magnitude;

        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                trigger_impact(IMPACT_GPIO);
                log_data(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz polling rate) */
    }

    /* Clean up resources */
    printf("\nShutting down...\n");
    gpioWrite(IMPACT_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

