#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x52
#define LED_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_ALS_LSB 0x00
#define REG_ALS_MSB 0x01
#define REG_RED_LSB 0x02
#define REG_RED_MSB 0x03
#define REG_GREEN_LSB 0x04
#define REG_GREEN_MSB 0x05
#define REG_BLUE_LSB 0x06
#define REG_BLUE_MSB 0x07
#define REG_COMMAND 0x08
#define REG_CONFIG 0x09

#define CMD_RESET 0x01
#define CMD_START 0x02
#define CMD_STOP 0x03

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error selecting I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(uint8_t reg_lsb, uint16_t *value) {
    uint8_t lsb, msb;
    if (i2c_read_reg(reg_lsb, &lsb) != 0) return -1;
    if (i2c_read_reg(reg_lsb + 1, &msb) != 0) return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int initialize_adpd188bi(void) {
    if (i2c_write_reg(REG_COMMAND, CMD_RESET) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg(REG_COMMAND, CMD_START) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_reg16(REG_ALS_LSB, als) != 0) return -1;
    if (i2c_read_reg16(REG_RED_LSB, red) != 0) return -1;
    if (i2c_read_reg16(REG_GREEN_LSB, green) != 0) return -1;
    if (i2c_read_reg16(REG_BLUE_LSB, blue) != 0) return -1;
    return 0;
}

static void control_led(uint16_t als_value) {
    int duty_cycle = (als_value * PWM_RANGE) / 65535;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (duty_cycle < 0) duty_cycle = 0;
    gpioPWM(LED_GPIO, duty_cycle);
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg(REG_COMMAND, CMD_STOP);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_adpd188bi() != 0) {
        fprintf(stderr, "ADPD188BI initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t als, red, green, blue;

    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            control_led(als);
            log_data(als, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying in 100ms...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

