/*
 * Raspberry Pi Zero W - Adafruit FXOS8700CQ 6-Axis Accelerometer/Magnetometer Impact Logger
 *
 * Reads acceleration data from the FXOS8700CQ at 50 ms intervals, computes the
 * magnitude, and logs impact events to impact_log.txt.
 *
 * Wiring:
 *   FXOS8700CQ SDA -> GPIO2 (I2C bus 1 SDA)
 *   FXOS8700CQ SCL -> GPIO3 (I2C bus 1 SCL)
 *   FXOS8700CQ VCC -> 3.3 V
 *   FXOS8700CQ GND -> GND
 *
 * Build: gcc -O2 -Wall -o impact_logger impact_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700CQ I2C address ---- */
#define FXOS8700_ADDR 0x29

/* ---- FXOS8700CQ register addresses ---- */
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01
#define FXOS8700_M_OUT_X_MSB 0x04
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C

/* ---- Impact threshold ---- */
#define IMPACT_THRESHOLD 2.0f

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Function prototypes ---- */
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  fxos8700_init(int fd);
static int  fxos8700_read_acceleration(int fd, float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static int  log_impact(float x, float y, float z, float magnitude);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* FXOS8700CQ initialization                                          */
/* ------------------------------------------------------------------ */

static int fxos8700_init(int fd)
{
    uint8_t whoami = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, FXOS8700_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (whoami != 0xC7) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0xC7.\n",
                whoami);
        return -1;
    }

    /* Standby mode */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* ±2 g full-scale range, 800 Hz ODR */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG2, 0x00) != 0)
        return -1;

    /* Enable accelerometer and magnetometer axes */
    if (i2c_write_reg8(fd, FXOS8700_M_CTRL_REG1, 0x0C) != 0)
        return -1;

    /* Active mode */
    if (i2c_write_reg8(fd, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data                                             */
/* ------------------------------------------------------------------ */

static int fxos8700_read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t x_msb = 0, x_lsb = 0, y_msb = 0, y_lsb = 0, z_msb = 0, z_lsb = 0;

    if (i2c_read_reg8(fd, FXOS8700_OUT_X_MSB, &x_msb) != 0)
        return -1;
    if (i2c_read_reg8(fd, FXOS8700_OUT_X_MSB + 1, &x_lsb) != 0)
        return -1;
    if (i2c_read_reg8(fd, FXOS8700_OUT_X_MSB + 2, &y_msb) != 0)
        return -1;
    if (i2c_read_reg8(fd, FXOS8700_OUT_X_MSB + 3, &y_lsb) != 0)
        return -1;
    if (i2c_read_reg8(fd, FXOS8700_OUT_X_MSB + 4, &z_msb) != 0)
        return -1;
    if (i2c_read_reg8(fd, FXOS8700_OUT_X_MSB + 5, &z_lsb) != 0)
        return -1;

    int16_t raw_x = (int16_t)((x_msb << 8) | x_lsb);
    int16_t raw_y = (int16_t)((y_msb << 8) | y_lsb);
    int16_t raw_z = (int16_t)((z_msb << 8) | z_lsb);

    /* Convert to g (±2 g full-scale range) */
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Calculate magnitude of acceleration vector                          */
/* ------------------------------------------------------------------ */

static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log impact event to file                                           */
/* ------------------------------------------------------------------ */

static int log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening impact_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n",
                timestamp, x, y, z, magnitude) < 0) {
        fprintf(stderr, "Error writing to impact_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing impact_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put device in standby before closing */
        (void)i2c_write_reg8(g_i2c_fd, FXOS8700_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, FXOS8700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                FXOS8700_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos8700_init(g_i2c_fd) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700CQ initialized. Logging impact events to impact_log.txt.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float x = 0.0f, y = 0.0f, z = 0.0f;

        if (fxos8700_read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Failed to log impact event.\n");
                } else {
                    printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                }
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        usleep(50000); /* 50 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

