/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   GY-50 SDA -> GPIO2 (I2C bus 1 SDA)
 *   GY-50 SCL -> GPIO3 (I2C bus 1 SCL)
 *   GY-50 VDD -> 3.3 V
 *   GY-50 GND -> GND
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D Register Addresses ---- */
#define L3G4200D_WHO_AM_I      0x0F
#define L3G4200D_CTRL_REG1    0x20
#define L3G4200D_CTRL_REG4    0x23
#define L3G4200D_OUT_X_L      0x28

/* ---- Expected WHO_AM_I value ---- */
#define L3G4200D_WHO_AM_I_VAL 0xD3

/* ---- Calibration parameters ---- */
#define CALIBRATION_SAMPLES   100
#define CALIBRATION_PERIOD_US 50000  /* 50 ms -> 20 Hz */
#define CALIBRATION_DELAY_US  100000 /* 100 ms between samples */

/* ---- Threshold for alert (dps) ---- */
#define ALERT_THRESHOLD_DPS 50.0f

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ---- Function prototypes ---- */
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  init_gyro(int fd);
static int  read_gyro_data(int fd, float *x, float *y, float *z);
static void calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off);
static void log_data(FILE *fp, float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope initialization                                             */
/* ------------------------------------------------------------------ */

static int init_gyro(int fd)
{
    uint8_t who_am_i = 0;

    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL_REG1: ODR = 100 Hz (0x57), all axes enabled (0x07).
     * CTRL_REG4: FS = ±250 dps (0x00).
     */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x57) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope data read                                                 */
/* ------------------------------------------------------------------ */

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /*
     * L3G4200D outputs data in 12-bit left-justified format.
     * The 12-bit value is left-shifted by 4 to get the 16-bit signed
     * value.
     */
    *x = (float)raw_x / 8192.0f;
    *y = (float)raw_y / 8192.0f;
    *z = (float)raw_z / 8192.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                        */
/* ------------------------------------------------------------------ */

static void calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off)
{
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    int   samples = 0;

    printf("Calibrating gyroscope... Please keep the sensor stationary.\n");
    fflush(stdout);

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        float x, y, z;
        if (read_gyro_data(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Calibration read error at sample %d.\n", i);
            break;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        samples++;
        usleep(CALIBRATION_DELAY_US);
    }

    if (samples == 0) {
        fprintf(stderr, "Calibration failed: no valid samples collected.\n");
        *x_off = *y_off = *z_off = 0.0f;
        return;
    }

    *x_off = x_sum / (float)samples;
    *y_off = y_sum / (float)samples;
    *z_off = z_sum / (float)samples;

    printf("Calibration complete. Offsets: X=%.4f, Y=%.4f, Z=%.4f\n",
           *x_off, *y_off, *z_off);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    float x, y, z;

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the GY-50 slave address (0x68) */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x68) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (init_gyro(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Calibrate the gyroscope */
    calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off);

    /* Open the log file in append mode */
    g_log_file = fopen("gyro_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_dps,y_dps,z_dps\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyroscope data to gyro_log.txt at 20 Hz. Press Ctrl+C to stop.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) == 0) {
            x -= x_off;
            y -= y_off;
            z -= z_off;

            log_data(g_log_file, x, y, z);

            if (fabsf(x) > ALERT_THRESHOLD_DPS ||
                fabsf(y) > ALERT_THRESHOLD_DPS ||
                fabsf(z) > ALERT_THRESHOLD_DPS) {
                fprintf(stderr,
                        "ALERT: Gyroscope data exceeds threshold! X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n",
                        x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        usleep(CALIBRATION_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

