/*
 * Raspberry Pi Zero W – LSM303DLHC Compass
 *
 * Reads acceleration and magnetic data from a GY-51 LSM303DLHC on I2C bus 1
 * and computes a tilt-compensated heading.  Logs data to compass_log.txt.
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   LSM303DLHC SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o compass compass.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC I2C address (SA0 tied to GND) ---- */
#define LSM303_ADDR 0x18

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_CTRL_REG1_A 0x20
#define LSM303_CTRL_REG2_A 0x21
#define LSM303_CTRL_REG3_A 0x22
#define LSM303_CTRL_REG4_A 0x23
#define LSM303_CTRL_REG5_A 0x24
#define LSM303_CTRL_REG6_A 0x25
#define LSM303_OUT_X_L_A  0x28
#define LSM303_OUT_X_H_A  0x29
#define LSM303_OUT_Y_L_A  0x2A
#define LSM303_OUT_Y_H_A  0x2B
#define LSM303_OUT_Z_L_A  0x2C
#define LSM303_OUT_Z_H_A  0x2D

#define LSM303_CTRL_REG1_M 0x20
#define LSM303_CTRL_REG2_M 0x21
#define LSM303_CTRL_REG3_M 0x22
#define LSM303_CTRL_REG4_M 0x23
#define LSM303_CTRL_REG5_M 0x24
#define LSM303_CTRL_REG6_M 0x25
#define LSM303_OUT_X_L_M  0x28
#define LSM303_OUT_X_H_M  0x29
#define LSM303_OUT_Y_L_M  0x2A
#define LSM303_OUT_Y_H_M  0x2B
#define LSM303_OUT_Z_L_M  0x2C
#define LSM303_OUT_Z_H_M  0x2D

/* ---- Sensitivity scales ---- */
#define ACCEL_SENSITIVITY 0.000061f   /* +/- 2g  -> 0.000061 g/LSB */
#define MAG_SENSITIVITY  0.000014f   /* +/- 4 gauss -> 0.000014 gauss/LSB */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000      /* 100 ms */
#define LOG_FILE_NAME    "compass_log.txt"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303DLHC initialization                                           */
/* ------------------------------------------------------------------ */
static int init_lsm303(int fd)
{
    /* Accelerometer: 100 Hz ODR, all axes enabled */
    if (i2c_write_reg8(fd, LSM303_CTRL_REG1_A, 0x57) < 0)
        return -1;
    /* Acceleration: +/- 2g, high-resolution mode */
    if (i2c_write_reg8(fd, LSM303_CTRL_REG4_A, 0x00) < 0)
        return -1;
    /* Magnetometer: 80 Hz ODR, continuous conversion */
    if (i2c_write_reg8(fd, LSM303_CTRL_REG1_M, 0x70) < 0)
        return -1;
    /* Magnetometer: +/- 4 gauss, high-resolution mode */
    if (i2c_write_reg8(fd, LSM303_CTRL_REG2_M, 0x00) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data                                             */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_OUT_X_L_A | 0x80, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetometer data                                            */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_OUT_X_L_M | 0x80, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading (degrees)                                  */
/* ------------------------------------------------------------------ */
static float calculate_heading(float ax, float ay, float az,
                              float mx, float my, float mz)
{
    float roll  = atan2f(ay, az) * 180.0f / M_PI;
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / M_PI;

    float hx = mx * cosf(pitch * M_PI / 180.0f) + mz * sinf(pitch * M_PI / 180.0f);
    float hy = mx * sinf(roll  * M_PI / 180.0f) * sinf(pitch * M_PI / 180.0f) +
               my * cosf(roll  * M_PI / 180.0f) -
               mz * sinf(roll  * M_PI / 180.0f) * cosf(pitch * M_PI / 180.0f);

    float heading = atan2f(hy, hx) * 180.0f / M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float heading, float ax, float ay, float az,
                    float mx, float my, float mz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, heading, ax, ay, az, mx, my, mz) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM303_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lsm303(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,Heading,AccelX,AccelY,AccelZ,MagX,MagY,MagZ\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Failed to flush CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Compass logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(g_i2c_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
        } else if (read_magnetometer(g_i2c_fd, &mx, &my, &mz) < 0) {
            fprintf(stderr, "Error reading magnetometer data\n");
        } else {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            if (log_data(fp, heading, ax, ay, az, mx, my, mz) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

