/*
 * Raspberry Pi 4 Model B - Dual IMP23ABSU Ultrasonic MEMS Microphone Logger
 *
 * Wiring:
 *   IMP23ABSU SDA -> GPIO2 (I2C bus 1 SDA)
 *   IMP23ABSU SCL -> GPIO3 (I2C bus 1 SCL)
 *   IMP23ABSU VDD -> 3.3 V
 *   IMP23ABSU GND -> GND
 *
 * Build: gcc -O2 -Wall -o audio_logger audio_logger.c -lgpiod -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define IMP23ABSU_ADDR  0x50
#define SAMPLE_PERIOD_US 10000   /* 10 ms */
#define LOG_FILE       "audio_log.dat"

/* IMP23ABSU register addresses */
#define REG_AUDIO_DATA_MSB 0x00
#define REG_AUDIO_DATA_LSB 0x01
#define REG_AUDIO_DATA_MSB_ALT 0x02
#define REG_AUDIO_DATA_LSB_ALT 0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* IMP23ABSU audio sample acquisition                                  */
/* ------------------------------------------------------------------ */
static int read_audio_sample(int fd, int16_t *sample)
{
    if (i2c_read_reg16(fd, REG_AUDIO_DATA_MSB, sample) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(struct timespec *ts)
{
    clock_gettime(CLOCK_REALTIME, ts);
}

/* ------------------------------------------------------------------ */
/* TDOA calculation                                                    */
/* ------------------------------------------------------------------ */
static double calculate_tdoa(const struct timespec *ts1,
                             const struct timespec *ts2)
{
    double diff_sec  = (double)(ts2->tv_sec  - ts1->tv_sec);
    double diff_nsec = (double)(ts2->tv_nsec - ts1->tv_nsec);
    return diff_sec + diff_nsec / 1e9;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const struct timespec *ts1,
                     const struct timespec *ts2, int16_t s1, int16_t s2,
                     double tdoa)
{
    if (fprintf(fp, "%ld.%09ld,%d,%d,%.6f\n",
                (long)ts1->tv_sec, ts1->tv_nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, IMP23ABSU_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                IMP23ABSU_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        struct timespec ts1, ts2;
        int16_t s1 = 0, s2 = 0;
        int ok1 = 0, ok2 = 0;

        /* Read sample from sensor 1 */
        if (read_audio_sample(g_i2c_fd, &s1) == 0)
            ok1 = 1;

        /* Read sample from sensor 2 */
        if (ok1) {
            if (read_audio_sample(g_i2c_fd, &s2) == 0)
                ok2 = 1;
        }

        /* If both samples were read successfully, calculate TDOA */
        if (ok1 && ok2) {
            get_timestamp(&ts1);
            get_timestamp(&ts2);
            double tdoa = calculate_tdoa(&ts1, &ts2);

            if (log_data(g_log_fp, &ts1, &ts2, s1, s2, tdoa) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        }

        /* Sleep for the sample period, checking g_running every 100 ms */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

