        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, IMP23ABSU_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                IMP23ABSU_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        struct timespec ts1, ts2;
        int16_t s1 = 0, s2 = 0;
        int ok1 = 0, ok2 = 0;

        /* Read sample from sensor 1 */
        if (read_audio_sample(g_i2c_fd, &s1) == 0)
            ok1 = 1;

        /* Read sample from sensor 2 */
        if (ok1) {
            if (read_audio_sample(g_i2c_fd, &s2) == 0)
                ok2 = 1;
        }

        /* If both samples were read successfully, calculate TDOA */
        if (ok1 && ok2) {
            get_timestamp(&ts1);
            get_timestamp(&ts2);
            double tdoa = calculate_tdoa(&ts1, &ts2);

            if (log_data(g_log_fp, &ts1, &ts2, s1, s2, tdoa) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        }

        /* Sleep for the sample period, checking g_running every 100 ms */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

