#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define GYRO_SCALE 0.02f
#define ACCEL_SCALE 0.00025f
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, int16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    *value = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_register(0x00, &raw_x) < 0) return -1;
    if (read_register(0x02, &raw_y) < 0) return -1;
    if (read_register(0x04, &raw_z) < 0) return -1;

    *gyro_x = (float)raw_x * GYRO_SCALE;
    *gyro_y = (float)raw_y * GYRO_SCALE;
    *gyro_z = (float)raw_z * GYRO_SCALE;
    return 0;
}

static int read_accel_data(float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_register(0x06, &raw_x) < 0) return -1;
    if (read_register(0x08, &raw_y) < 0) return -1;
    if (read_register(0x0A, &raw_z) < 0) return -1;

    *accel_x = (float)raw_x * ACCEL_SCALE;
    *accel_y = (float)raw_y * ACCEL_SCALE;
    *accel_z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    printf("ADIS16448 IMU Data Acquisition\n");
    printf("SPI: %s, Mode: %d, Bits: %d, Speed: %d Hz\n", SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data.\n");
        } else if (read_accel_data(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data.\n");
        } else {
            printf("Gyro: X=%.3f Y=%.3f Z=%.3f, Accel: X=%.3f Y=%.3f Z=%.3f\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nCleaning up and exiting...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

