#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define SAMPLE_INTERVAL_US 100000
#define STALL_DELAY_US 40

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(uint16_t reg, int16_t *value) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = (reg >> 8) & 0xFF;
    tx_buf[1] = reg & 0xFF;
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%04X\n", reg);
        return -1;
    }

    *value = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    return 0;
}

static int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    return read_register(0x00, gyro_x) ||
           read_register(0x02, gyro_y) ||
           read_register(0x04, gyro_z);
}

static int read_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    return read_register(0x06, accel_x) ||
           read_register(0x08, accel_y) ||
           read_register(0x0A, accel_z);
}

static void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z,
                         int16_t accel_x, int16_t accel_y, int16_t accel_z,
                         float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps,
                         float *accel_x_g, float *accel_y_g, float *accel_z_g) {
    *gyro_x_dps = (float)gyro_x * 0.05f;
    *gyro_y_dps = (float)gyro_y * 0.05f;
    *gyro_z_dps = (float)gyro_z * 0.05f;
    *accel_x_g = (float)accel_x * 0.00025f;
    *accel_y_g = (float)accel_y * 0.00025f;
    *accel_z_g = (float)accel_z * 0.00025f;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d: %d\n", SPI_CHANNEL, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU Data Acquisition\n");
    printf("SPI Channel: %d, Speed: %d Hz, Mode: 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("Press Ctrl+C to exit\n");

    while (running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        if (read_accel_data(&accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            break;
        }

        float gyro_x_dps, gyro_y_dps, gyro_z_dps;
        float accel_x_g, accel_y_g, accel_z_g;

        convert_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z,
                     &gyro_x_dps, &gyro_y_dps, &gyro_z_dps,
                     &accel_x_g, &accel_y_g, &accel_z_g);

        printf("Gyro: X=%.2f Y=%.2f Z=%.2f deg/s | Accel: X=%.4f Y=%.4f Z=%.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accel_x_g, accel_y_g, accel_z_g);

        usleep(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

