/*
 * MPU-6886 6-Axis IMU Reader for Raspberry Pi 4 Model B
 * Uses standard Linux I2C ioctl() calls (no wiringPi).
 *
 * Wiring:
 *   MPU-6886 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   MPU-6886 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   MPU-6886 VDD -> 3.3 V
 *   MPU-6886 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mpu6886_reader mpu6886_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6886 register addresses ---- */
#define MPU6886_ADDR          0x68
#define MPU6886_PWR_MGMT_1    0x6B
#define MPU6886_ACCEL_XOUT_H  0x3B
#define MPU6886_GYRO_XOUT_H   0x43

/* ---- I2C bus ---- */
#define I2C_BUS              "/dev/i2c-1"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an MPU-6886 register                          */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mpu6886_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an MPU-6886 register                          */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mpu6886_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from two consecutive registers        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mpu6886_read_s16(int fd, uint8_t reg_h, int16_t *out)
{
    uint8_t lo, hi;

    if (mpu6886_read_reg(fd, reg_h, &hi) != 0)
        return -1;
    if (mpu6886_read_reg(fd, reg_h + 1, &lo) != 0)
        return -1;

    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6886: wake up, set sample rate, disable sleep       */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mpu6886_init(int fd)
{
    /* Wake up the device (clear sleep bit) */
    if (mpu6886_write_reg(fd, MPU6886_PWR_MGMT_1, 0x00) != 0)
        return -1;

    /* Sample rate divider = 1 kHz / (1 + 7) = 125 Hz */
    if (mpu6886_write_reg(fd, MPU6886_PWR_MGMT_1, 0x07) != 0)
        return -1;

    /* Disable sleep mode (bit 6 = 0) */
    if (mpu6886_write_reg(fd, MPU6886_PWR_MGMT_1, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw accelerometer and gyroscope data with retries               */
/* Returns 0 on success, -1 on persistent failure.                    */
/* ------------------------------------------------------------------ */
static int read_raw_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *gx, int16_t *gy, int16_t *gz)
{
    int retries = 3;

    while (retries > 0) {
        if (mpu6886_read_s16(fd, MPU6886_ACCEL_XOUT_H, ax) == 0 &&
            mpu6886_read_s16(fd, MPU6886_ACCEL_XOUT_H + 2, ay) == 0 &&
            mpu6886_read_s16(fd, MPU6886_ACCEL_XOUT_H + 4, az) == 0 &&
            mpu6886_read_s16(fd, MPU6886_GYRO_XOUT_H, gx) == 0 &&
            mpu6886_read_s16(fd, MPU6886_GYRO_XOUT_H + 2, gy) == 0 &&
            mpu6886_read_s16(fd, MPU6886_GYRO_XOUT_H + 4, gz) == 0) {
            return 0;
        }
        retries--;
        if (retries > 0) {
            fprintf(stderr, "Read failed, retrying (%d left)...\n", retries);
            usleep(10000); /* 10 ms backoff */
        }
    }

    fprintf(stderr, "Failed to read raw data after multiple retries.\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6886 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6886 */
    if (mpu6886_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MPU-6886 at address 0x%02X.\n",
                MPU6886_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized successfully at address 0x%02X.\n",
           MPU6886_ADDR);
    printf("Reading accelerometer and gyroscope data every 50 ms...\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        if (read_raw_data(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel X: %6d, Y: %6d, Z: %6d  |  Gyro X: %6d, Y: %6d, Z: %6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
        }

        usleep(50000); /* 50 ms */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

