/*
 * ADXL345 Impact Detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADXL345 SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADXL345 VCC -> 3.3 V
 *   ADXL345 GND -> GND
 *   Red LED anode -> GPIO17 (BCM), cathode -> GND
 *
 * Build: gcc -O2 -Wall -o impact_detect impact_detect.c -lpigpio -lrt
 * Run:   sudo ./impact_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDRESS          0x53
#define ADXL345_DEVID_AD          0x00
#define ADXL345_DEVID_MST          0x01
#define ADXL345_BW_RATE           0x2C
#define ADXL345_POWER_CTL         0x2D
#define ADXL345_DATA_FORMAT       0x31
#define ADXL345_DATAX0            0x32
#define ADXL345_DATA_FORMAT_FULL_RES 0x0B  /* full resolution, ±2g, right-justified */
#define ADXL345_EXPECTED_DEVID    0xE5

/* ---- GPIO and timing ---- */
#define LED_GPIO                 17
#define THRESHOLD_G              2.5f
#define POLL_DELAY_US            10000   /* 10 ms */
#define LED_ON_TIME_US           500000  /* 500 ms */
#define LOG_FILE_NAME            "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register                          */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register                          */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read multiple bytes starting at a register                          */
/* ------------------------------------------------------------------ */
static int adxl_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData short read: got %d, expected %u\n",
                rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify device identity                                              */
/* ------------------------------------------------------------------ */
static int verify_device(void)
{
    uint8_t devid = 0;
    if (adxl_read_reg(ADXL345_DEVID_AD, &devid) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVID_AD register — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_EXPECTED_DEVID) {
        fprintf(stderr, "[ERROR] DEVID_AD mismatch: got 0x%02X, expected 0x%02X.\n",
                devid, ADXL345_EXPECTED_DEVID);
        return -1;
    }
    printf("[INFO] ADXL345 detected (DEVID_AD = 0x%02X).\n", devid);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345                                             */
/* ------------------------------------------------------------------ */
static int init_adxl345(void)
{
    /* Standby mode first so we can configure */
    if (adxl_write_reg(ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Set data rate to 100 Hz (0x0A) */
    if (adxl_write_reg(ADXL345_BW_RATE, 0x0A) != 0)
        return -1;

    /* Set full resolution, ±2g, right-justified */
    if (adxl_write_reg(ADXL345_DATA_FORMAT, ADXL345_DATA_FORMAT_FULL_RES) != 0)
        return -1;

    /* Enter measurement mode */
    if (adxl_write_reg(ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (X, Y, Z) in g                               */
/* ------------------------------------------------------------------ */
static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (adxl_read_burst(ADXL345_DATAX0, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* ±2g full resolution: 256 LSB/g */
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute total acceleration magnitude in g                            */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log impact event to file                                           */
/* ------------------------------------------------------------------ */
static int log_impact(float magnitude, float x, float y, float z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("[ERROR] time()");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("[ERROR] localtime_r()");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
                timestamp, magnitude, x, y, z) < 0) {
        perror("[ERROR] fprintf()");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("[ERROR] fflush()");
        return -1;
    }

    printf("[INFO] Impact logged: %s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
           timestamp, magnitude, x, y, z);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus 1 at ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ADXL345_ADDRESS, i2c_handle);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (verify_device() != 0) {
        fprintf(stderr, "[FATAL] ADXL345 verification failed — check wiring and address.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (init_adxl345() != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Impact detection started. Threshold: %.1f g. Press Ctrl+C to exit.\n",
           THRESHOLD_G);

    /* Main polling loop */
    while (!terminate) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "[WARN] Read error — continuing.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > THRESHOLD_G) {
            printf("[ALERT] Impact detected! Magnitude: %.2f g\n", magnitude);
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);

            if (log_impact(magnitude, x, y, z) != 0) {
                fprintf(stderr, "[WARN] Logging failed for impact event.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

