#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MMA8451Q I2C address (SA0 tied to GND) */
#define MMA8451Q_ADDR 0x1D

/* MMA8451Q registers */
#define MMA8451Q_STATUS 0x00
#define MMA8451Q_OUT_X_MSB 0x01
#define MMA8451Q_OUT_X_LSB 0x02
#define MMA8451Q_OUT_Y_MSB 0x03
#define MMA8451Q_OUT_Y_LSB 0x04
#define MMA8451Q_OUT_Z_MSB 0x05
#define MMA8451Q_OUT_Z_LSB 0x06
#define MMA8451Q_XYZ_DATA_CFG 0x0E
#define MMA8451Q_CTRL_REG1 0x2A
#define MMA8451Q_CTRL_REG2 0x2B
#define MMA8451Q_ID 0x0D

/* Expected device ID */
#define MMA8451Q_ID_VALUE 0x48

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Threshold in g (±2g range) */
#define THRESHOLD 2.0f

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 100000

/* LED on-time in microseconds */
#define LED_ON_TIME_US 500000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize MMA8451Q sensor */
static int init_mma8451q(int handle) {
    int id;

    /* Read device ID */
    id = i2cReadByteData(handle, MMA8451Q_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading MMA8451Q ID register: %d\n", id);
        return -1;
    }
    if (id != MMA8451Q_ID_VALUE) {
        fprintf(stderr, "MMA8451Q ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, MMA8451Q_ID_VALUE);
        return -1;
    }

    /* Standby mode */
    if (i2cWriteByteData(handle, MMA8451Q_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby)\n");
        return -1;
    }

    /* Set range to ±2g (0x00) */
    if (i2cWriteByteData(handle, MMA8451Q_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG\n");
        return -1;
    }

    /* Enable all axes, 800 Hz ODR */
    if (i2cWriteByteData(handle, MMA8451Q_CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active)\n");
        return -1;
    }

    return 0;
}

/* Read acceleration data from MMA8451Q */
static int read_mma8451q(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    /* Read 6 bytes starting from OUT_X_MSB */
    if (i2cReadI2CBlockData(handle, MMA8451Q_OUT_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data block\n");
        return -1;
    }

