#define MMA8451Q_OUT_Y_MSB 0x03
#define MMA8451Q_OUT_Y_LSB 0x04
#define MMA8451Q_OUT_Z_MSB 0x05
#define MMA8451Q_OUT_Z_LSB 0x06
