#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x52
#define CSV_FILE "magnetic_field_log.csv"
#define SAMPLE_INTERVAL_SEC 1

/* TMAG5273 register addresses */
#define TMAG5273_REG_X_MSB 0x00
#define TMAG5273_REG_X_LSB 0x01
#define TMAG5273_REG_Y_MSB 0x02
#define TMAG5273_REG_Y_LSB 0x03
#define TMAG5273_REG_Z_MSB 0x04
#define TMAG5273_REG_Z_LSB 0x05
#define TMAG5273_REG_STATUS 0x06
#define TMAG5273_REG_CONFIG 0x07

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_msb, int16_t *value) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, reg_msb, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_msb + 1, &lsb) < 0) return -1;
    *value = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_magnetic_field(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t status;
    if (i2c_read_reg8(fd, TMAG5273_REG_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) {
        fprintf(stderr, "TMAG5273 not ready (status=0x%02X)\n", status);
        return -1;
    }
    if (i2c_read_reg16(fd, TMAG5273_REG_X_MSB, x) < 0) return -1;
    if (i2c_read_reg16(fd, TMAG5273_REG_Y_MSB, y) < 0) return -1;
    if (i2c_read_reg16(fd, TMAG5273_REG_Z_MSB, z) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMAG5273_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    /* Verify sensor presence by reading the status register */
    uint8_t status;
    if (i2c_read_reg8(i2c_fd, TMAG5273_REG_STATUS, &status) < 0) {
        fprintf(stderr, "TMAG5273 not responding at address 0x%02X\n", TMAG5273_ADDR);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int initialize_csv(void) {
    csv_fp = fopen(CSV_FILE, "a");
    if (csv_fp == NULL) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }
    /* Check if file is empty to write header */
    fseek(csv_fp, 0, SEEK_END);
    long file_size = ftell(csv_fp);
    if (file_size == 0) {
        if (fprintf(csv_fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(csv_fp);
            csv_fp = NULL;
            return -1;
        }
        if (fflush(csv_fp) != 0) {
            fprintf(stderr, "Failed to flush CSV header: %s\n", strerror(errno));
            fclose(csv_fp);
            csv_fp = NULL;
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_fp != NULL) {
        fclose(csv_fp);
        csv_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_i2c() < 0) {
        return 1;
    }

    if (initialize_csv() < 0) {
        cleanup();
        return 1;
    }

    printf("TMAG5273 magnetic field logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetic_field(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(csv_fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read magnetic field data, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

