/*
 * freefall_monitor.c — Raspberry Pi 4 Model B
 *
 * Reads the SparkFun ADXL345 accelerometer via I2C (/dev/i2c-1)
 * and detects free-fall events on GPIO17 (BCM) via an interrupt.
 * Logs acceleration samples to freefall_log.csv while free-fall is active.
 *
 * Build:  gcc -O2 -Wall -Wextra -o freefall_monitor freefall_monitor.c
 * Run:    sudo ./freefall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_I2C_BUS        "/dev/i2c-1"
#define ADXL345_I2C_ADDR       0x53
#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_REG_INT_MAP    0x2F
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30

#define ADXL345_DEVID_EXPECTED 0xE5

/* ---- GPIO constants ---- */
#define GPIO_CHIP_NAME        "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LINE_OFFSET      17

/* ---- Free-fall threshold ---- */
#define FREEFALL_THRESHOLD_X  100
#define FREEFALL_THRESHOLD_Y  100
#define FREEFALL_THRESHOLD_Z  100

/* ---- Timing ---- */
#define POLL_TIMEOUT_MS       100
#define SAMPLE_INTERVAL_US    100000   /* 100 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_reg(fd, ADXL345_REG_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby mode */
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x00) < 0)
        return -1;

    /* Data format: full resolution, +/- 2g range */
    if (i2c_write_reg(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Interrupt mapping: INT1 mapped to free-fall */
    if (i2c_write_reg(fd, ADXL345_REG_INT_MAP, 0x01) < 0)
        return -1;

    /* Enable free-fall interrupt (bit 3 = INT_FREE_FALL) */
    if (i2c_write_reg(fd, ADXL345_REG_INT_ENABLE, 0x08) < 0)
        return -1;

    /* Clear any pending interrupt */
    if (i2c_write_reg(fd, ADXL345_REG_INT_SOURCE, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(ts_str + strlen(ts_str), sizeof(ts_str) - strlen(ts_str),
             ".%03ld", ts.tv_nsec / 1000000L);

    if (fprintf(fp, "%s,%d,%d,%d\n", ts_str, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(ADXL345_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", ADXL345_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request line for interrupt */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Cannot request rising edge events on GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("freefall_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open freefall_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("Free-fall monitoring started. Press Ctrl+C to exit.\n");

    /* Main event loop */
    while (g_running) {
        struct timespec ts_poll = { 0, POLL_TIMEOUT_MS * 1000000L };
        int ret = gpiod_line_event_wait(g_line, &ts_poll);

        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0)
            continue; /* timeout, no event */

        struct gpiod_line_event event;
        if (gpiod_line_event_read(g_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        int16_t x, y, z;
        if (adxl345_read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read acceleration during free-fall event\n");
            continue;
        }

        if (abs(x) > FREEFALL_THRESHOLD_X ||
            abs(y) > FREEFALL_THRESHOLD_Y ||
            abs(z) > FREEFALL_THRESHOLD_Z) {
            continue; /* not a free-fall sample */
        }

        log_data(g_log_fp, x, y, z);
        printf("Free-fall detected! X=%d Y=%d Z=%d\n", x, y, z);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

