/*
 * LSM6DSR Fall Detection Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO2 (BCM)
 *   LSM6DSR SCL -> GPIO3 (BCM)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build: gcc -O2 -Wall -o lsm6dsr_fall lsm6dsr_fall.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR I2C address (SA0 tied to GND) ---- */
#define LSM6DSR_ADDR 0x6B

/* ---- LSM6DSR register addresses ---- */
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

/* ---- Expected WHO_AM_I value ---- */
#define LSM6DSR_WHO_AM_I_VAL 0x6A

/* ---- Fall detection thresholds ---- */
#define FREEFALL_THRESHOLD_G 0.2f
#define IMPACT_THRESHOLD_G 2.5f
#define IMPACT_WINDOW_SEC 1.0f

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 10000  /* 104 Hz */
#define LOG_FILE "motion_log.txt"

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM6DSR initialization ---- */
static int lsm6dsr_init(int fd)
{
    uint8_t who_am_i = 0;

    if (i2c_read_reg8(fd, LSM6DSR_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* Accelerometer: ±2 g, 104 Hz ODR */
    if (i2c_write_reg8(fd, LSM6DSR_CTRL1_XL, 0x60) < 0) {
        return -1;
    }

    /* Gyroscope: ±250 dps, 104 Hz ODR */
    if (i2c_write_reg8(fd, LSM6DSR_CTRL2_G, 0x60) < 0) {
        return -1;
    }

    return 0;
}

/* ---- Read accelerometer and gyroscope data ---- */
static int lsm6dsr_read_data(int fd, float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz)
{
    uint8_t buf[14];

    if (i2c_read_burst(fd, LSM6DSR_OUTX_L_XL | 0x80, buf, sizeof(buf)) < 0) {
        return -1;
    }

    int16_t raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_az = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_gx = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_gy = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_gz = (int16_t)((buf[11] << 8) | buf[10]);

    /* Accelerometer: 16384 LSB/g, sensitivity ±2 g -> 16384 * 0.061 = 1048.576 g */
    *ax = (float)raw_ax * 0.061f;
    *ay = (float)raw_ay * 0.061f;
    *az = (float)raw_az * 0.061f;

    /* Gyroscope: 131 LSB/dps, sensitivity ±250 dps -> 131 * 0.0875 = 112.5 dps */
    *gx = (float)raw_gx * 0.0875f;
    *gy = (float)raw_gy * 0.0875f;
    *gz = (float)raw_gz * 0.0875f;

    return 0;
}

/* ---- Fall detection state machine ---- */
static void detect_fall(float ax, float ay, float az, float gx, float gy, float gz)
{
    static int fall_state = 0;
    static time_t fall_start_time = 0;
    static bool impact_active = false;

    float magnitude = sqrtf(ax * ax + ay * ay + az * az);

    switch (fall_state) {
        case 0:
            if (magnitude < FREEFALL_THRESHOLD_G) {
                fall_state = 1;
                fall_start_time = time(NULL);
            }
            break;

        case 1:
            if (magnitude > IMPACT_THRESHOLD_G) {
                fall_state = 0;
            } else if (time(NULL) - fall_start_time >= IMPACT_WINDOW_SEC) {
                fall_state = 2;
                impact_active = true;
            }
            break;

        case 2:
            if (magnitude < FREEFALL_THRESHOLD_G) {
                fall_state = 0;
            } else if (impact_active) {
                fall_state = 3;
            }
            break;

        case 3:
            if (magnitude > IMPACT_THRESHOLD_G) {
                fall_state = 0;
            }
            break;

        default:
            fall_state = 0;
            break;
    }

    if (impact_active) {
        printf("Impact detected!\n");
        impact_active = false;
    }
}

/* ---- Logging ---- */
static void log_data(float ax, float ay, float az, float gx, float gy, float gz)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, ax, ay, az, gx, gy, gz) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM6DSR_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (lsm6dsr_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    float ax, ay, az, gx, gy, gz;

    while (g_running) {
        if (lsm6dsr_read_data(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
            detect_fall(ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

