#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define WHO_AM_I_REG      0x00
#define WHO_AM_I_VAL      0x16
#define GYRO_XOUT_L_REG   0x02
#define GYRO_XOUT_H_REG   0x03
#define GYRO_YOUT_L_REG   0x04
#define GYRO_YOUT_H_REG   0x05
#define GYRO_ZOUT_L_REG   0x06
#define GYRO_ZOUT_H_REG   0x07

/* SPI Configuration */
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0x0003  /* Mode 3: CPOL=1, CPHA=1 */

/* Global Variables */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function Prototypes */
static int spi_read_register(uint8_t reg, uint8_t *value);
static int spi_write_register(uint8_t reg, uint8_t value);
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
static double convert_to_degrees(int16_t raw_value);
static int log_data(double x, double y, double z);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Reads a single byte from an ADIS16266 register.
 * Returns 0 on success, -1 on failure.
 */
static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Build the SPI message for a read command:
     * Byte 0: Write command (0x80 | reg)
     * Byte 1: Dummy byte (0x00)
     */
    tx_buf[0] = (char)(0x80 | reg);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

/*
 * Writes a single byte to an ADIS16266 register.
 * Returns 0 on success, -1 on failure.
 */
static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Build the SPI message for a write command:
     * Byte 0: Write command (0x40 | reg)
     * Byte 1: Data byte
     */
    tx_buf[0] = (char)(0x40 | reg);
    tx_buf[1] = (char)value;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

/*
 * Reads the X, Y, and Z angular rates from the ADIS16266.
 * Returns 0 on success, -1 on failure.
 */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (spi_read_register(GYRO_XOUT_L_REG, &x_l) != 0) return -1;
    if (spi_read_register(GYRO_XOUT_H_REG, &x_h) != 0) return -1;
    if (spi_read_register(GYRO_YOUT_L_REG, &y_l) != 0) return -1;
    if (spi_read_register(GYRO_YOUT_H_REG, &y_h) != 0) return -1;
    if (spi_read_register(GYRO_ZOUT_L_REG, &z_l) != 0) return -1;
    if (spi_read_register(GYRO_ZOUT_H_REG, &z_h) != 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

/*
 * Converts raw gyroscope data to degrees per second.
 * The ADIS16266 outputs 16-bit signed values, with a scale factor of 0.0305 deg/sec/LSB.
 */
static double convert_to_degrees(int16_t raw_value) {
    return (double)raw_value * 0.0305;
}

/*
 * Logs the X, Y, and Z angular rates to a CSV file.
 * Returns 0 on success, -1 on failure.
 */
