static void signal_handler(int signal);
static void cleanup(void);

/*
 * Reads a single byte from an ADIS16266 register.
 * Returns 0 on success, -1 on failure.
 */
static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Build the SPI message for a read command:
     * Byte 0: Write command (0x80 | reg)
     * Byte 1: Dummy byte (0x00)
     */
    tx_buf[0] = (char)(0x80 | reg);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
