 * Writes a single byte to an ADIS16266 register.
 * Returns 0 on success, -1 on failure.
 */
static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Build the SPI message for a write command:
     * Byte 0: Write command (0x40 | reg)
     * Byte 1: Data byte
     */
    tx_buf[0] = (char)(0x40 | reg);
    tx_buf[1] = (char)value;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

