/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Reads angular velocity data from the GY-50 L3G4200D gyroscope on I2C bus 1
 * every 10 ms, converts the raw values using the 8.75 mdps/LSB sensitivity
 * (divide by 114.285), and appends timestamped records to gyro_log.csv.
 *
 * Wiring:
 *   GY-50 SDA -> GPIO 2 (I2C1 SDA)
 *   GY-50 SCL -> GPIO 3 (I2C1 SCL)
 *   GY-50 VDD -> 3.3 V
 *   GY-50 GND -> GND
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c -lgpiod -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D Register Addresses ---- */
#define L3G4200D_WHO_AM_I      0x0F
#define L3G4200D_CTRL_REG1     0x20
#define L3G4200D_CTRL_REG4     0x23
#define L3G4200D_OUT_X_L       0x28

/* ---- L3G4200D WHO_AM_I Value ---- */
#define L3G4200D_WHO_AM_I_VAL  0xD3

/* ---- Sensitivity: 8.75 mdps/LSB (divide by 114.285) ---- */
#define L3G4200D_SENSITIVITY   114.285f

/* ---- I2C Bus ---- */
#define I2C_BUS "/dev/i2c-1"

/* ---- Sampling Interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 10000

/* ---- Global Variables ---- */
static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

/* ---- Function Prototypes ---- */
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t value);
static int  i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
static int  init_l3g4200d(int fd);
static int  read_gyro_data(int fd, float *x, float *y, float *z);
static int  log_data(FILE *fp, float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/*
 * Write a single byte to an I2C register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an I2C register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Initialize the L3G4200D gyroscope.
 * Returns 0 on success, -1 on failure.
 */
static int init_l3g4200d(int fd) {
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (i2c_read_reg(fd, L3G4200D_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X.\n",
                L3G4200D_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    /* Wake up the device (clear sleep bit) */
    if (i2c_write_reg(fd, L3G4200D_CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to wake up L3G4200D.\n");
        return -1;
    }

    /* Set data rate to 100 Hz (ODR = 100 Hz) and enable all axes */
    if (i2c_write_reg(fd, L3G4200D_CTRL_REG1, 0x80) != 0) {
        fprintf(stderr, "Failed to set data rate.\n");
        return -1;
    }

    /* Set full-scale range to +/- 250 dps (FS = 250 dps) */
    if (i2c_write_reg(fd, L3G4200D_CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to set full-scale range.\n");
        return -1;
    }

    return 0;
}

/*
 * Read raw angular velocity data from the L3G4200D.
 * Returns 0 on success, -1 on failure.
 */
static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];

    /* Read 6 bytes starting from OUT_X_L (0x28) */
    if (write(fd, &L3G4200D_OUT_X_L, 1) != 1) {
        fprintf(stderr, "Error writing register address for data read: %s\n",
                strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* Convert to angular velocity (dps) */
    *x = (float)raw_x / L3G4200D_SENSITIVITY;
    *y = (float)raw_y / L3G4200D_SENSITIVITY;
    *z = (float)raw_z / L3G4200D_SENSITIVITY;

    return 0;
}

/*
 * Log data to the CSV file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%09ld,%.4f,%.4f,%.4f\n",
                timestamp, ts.tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Cleanup resources.
 */
static void cleanup(void) {
    if (i2c_fd >= 0) {
        /* Put the device into standby mode before closing */
        i2c_write_reg(i2c_fd, L3G4200D_CTRL_REG1, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    float x, y, z;

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, 0x68) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x68: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the L3G4200D */
    if (init_l3g4200d(i2c_fd) != 0) {
        fprintf(stderr, "L3G4200D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the header row if the file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data, retrying...\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Gyroscope data logging stopped.\n");

    return EXIT_SUCCESS;
}

