#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown (Ctrl+C) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialize the pigpio library and configure the flame sensor GPIO */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-up resistor so the line reads HIGH when no flame */
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read the flame sensor digital output (active-LOW: LOW = flame detected) */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: Invalid GPIO%d read.\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

/* Log a flame event with a timestamp to the log file */
static void log_flame_event(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return;
    }

    if (log_file != NULL) {
        if (flame_detected == 0) {
            fprintf(log_file, "%s – Flame detected: YES\n", timestamp);
        } else {
            fprintf(log_file, "%s – Flame detected: NO\n", timestamp);
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

/* Print a flame detection message to the console */
static void print_flame_detection(int flame_detected) {
    if (flame_detected == 0) {
        printf("FLAME DETECTED!\n");
    } else {
        printf("No flame detected.\n");
    }
}

int main(void) {
    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    /* Main polling loop */
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            log_flame_event(flame_detected);
            print_flame_detection(flame_detected);
        } else {
            /* Sensor read error – log the error line */
            log_flame_event(-1);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean up resources */
    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

