/*
 * D7S-0001 vibration sensor reader for Raspberry Pi 5.
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   D7S SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * The D7S-0001 returns a 16-bit signed two's-complement value for each axis.
 * The sensor‑absent / bus error detection is based on the documented
 * error value (0x0000) that is returned on a read failure.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vibration_logger vibration_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x48          /* D7S-0001 default I2C address */
#define SAMPLE_MS      100
#define CSV_FILENAME   "vibration_log.csv"

/* D7S-0001 register addresses (from datasheet) */
#define REG_X_LSB      0x00
#define REG_X_MSB      0x01
#define REG_Y_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Z_LSB      0x04
#define REG_Z_MSB      0x05

/* Error value returned on a read failure (0x0000 is documented) */
#define D7S_ERROR_VALUE 0x0000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a 16-bit signed two's-complement value from a D7S register pair.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_d7s_axis(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t buf[2];

    /* Write the register address */
    if (write(fd, &reg_lsb, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: got %zd of %zu bytes: %s\n",
                reg_lsb, n, sizeof(buf), strerror(errno));
        return -1;
    }

    /* Combine low and high bytes (big-endian on the D7S) */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];

    /* Sign-extend 16-bit value to 32-bit */
    if (raw & 0x8000) {
        raw |= 0xFFFF0000;
    }

    *out = (int16_t)raw;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire D7S slave address */
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open CSV file for appending */
    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Cannot flush CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("D7S-0001 vibration logger started. Logging to %s every %d ms.\n",
           CSV_FILENAME, SAMPLE_MS);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_d7s_axis(fd, REG_X_LSB, &x) != 0) {
            fprintf(stderr, "X-axis read failed; skipping sample.\n");
        } else if (read_d7s_axis(fd, REG_Y_LSB, &y) != 0) {
            fprintf(stderr, "Y-axis read failed; skipping sample.\n");
        } else if (read_d7s_axis(fd, REG_Z_LSB, &z) != 0) {
            fprintf(stderr, "Z-axis read failed; skipping sample.\n");
        } else {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10) {
            usleep(10000);
        }
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose(CSV) failed: %s\n", strerror(errno));
        }
    }
    if (fd >= 0) {
        if (close(fd) != 0) {
            fprintf(stderr, "close(I2C) failed: %s\n", strerror(errno));
        }
    }
    return rc;
}

