#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_timestamped_state(FILE *fp, int sensor_pin, int value) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s - Sensor on GPIO%d: %s\n", timestamp, sensor_pin, value ? "HIGH" : "LOW") < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor1_line = NULL;
    struct gpiod_line *sensor2_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (sensor1_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (sensor2_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(sensor1_line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input with pull-up: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(sensor2_line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input with pull-up: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        if (log_timestamped_state(log_file, SENSOR1_PIN, sensor1_value) != 0) {
            break;
        }
        if (log_timestamped_state(log_file, SENSOR2_PIN, sensor2_value) != 0) {
            break;
        }

        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("Halt: Both sensors HIGH - Conveyor halted.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (sensor1_line != NULL) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line != NULL) {
        gpiod_line_release(sensor2_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Conveyor monitoring stopped.\n");
    return ret;
}

