#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MMA8452Q_ADDR        0x1D
#define MMA8452Q_WHO_AM_I     0x0D
#define MMA8452Q_WHO_AM_I_VAL 0x48
#define MMA8452Q_CTRL_REG1   0x2A
#define MMA8452Q_OUT_X_MSB   0x01
#define I2C_BUS             "/dev/i2c-1"
#define LOG_FILE            "fall_log.txt"
#define TILT_THRESHOLD      45.0f
#define LOOP_DELAY_US       10000  /* 10 ms -> 100 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x00) < 0)
        return -1;

    /* Data rate = 100 Hz (0x0A = 1000 Hz / 100) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x0A) < 0)
        return -1;

    /* Active mode */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x08) < 0)
        return -1;

    return 0;
}

static int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_OUT_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static float calculate_tilt(int16_t x, int16_t y, int16_t z)
{
    float x_norm = (float)x / 4096.0f;
    float y_norm = (float)y / 4096.0f;
    float z_norm = (float)z / 4096.0f;
    float tilt_x = atan2f(y_norm, z_norm) * 180.0f / M_PI;
    float tilt_y = atan2f(-x_norm, z_norm) * 180.0f / M_PI;
    return sqrtf(tilt_x * tilt_x + tilt_y * tilt_y);
}

static void log_fall_event(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MMA8452Q initialized. Monitoring for tilt (threshold %.1f deg)...\n",
           TILT_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error; continuing...\n");
            usleep(LOOP_DELAY_US);
            continue;
        }

        float tilt = calculate_tilt(x, y, z);

        if (tilt > TILT_THRESHOLD) {
            printf("Tilt detected! Tilt: %.2f deg\n", tilt);
            log_fall_event(g_log_fp, x, y, z);
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

