/*
 * LIS3MDL Magnetometer Reader for Raspberry Pi 3 Model B+
 *
 * Reads calibrated magnetic field data from an Adafruit LIS3MDL
 * over I2C at a rate of 10 Hz, applies the fixed offset and scale
 * calibration constants, and writes each X, Y, Z sample to a
 * single file named magnetic_log.txt.  Metal detector alerts are
 * printed to stderr whenever the total field magnitude exceeds 800 mG.
 *
 * Wiring:
 *   LIS3MDL SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   LIS3MDL SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   LIS3MDL VDD -> 3.3 V
 *   LIS3MDL GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o lis3mdl_reader lis3mdl_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL register addresses ---- */
#define LIS3MDL_REG_CTRL_REG1   0x20
#define LIS3MDL_REG_CTRL_REG4   0x23
#define LIS3MDL_REG_OUT_X_L     0x28
#define LIS3MDL_REG_OUT_X_H     0x29
#define LIS3MDL_REG_OUT_Y_L     0x2A
#define LIS3MDL_REG_OUT_Y_H     0x2B
#define LIS3MDL_REG_OUT_Z_L     0x2C
#define LIS3MDL_REG_OUT_Z_H     0x2D

/* ---- Calibration constants ---- */
#define OFFSET_X_MG   0.0f
#define OFFSET_Y_MG   0.0f
#define OFFSET_Z_MG   0.0f

#define SCALE_X_MG_PER_LSB 0.146f   /* ±4 gauss sensitivity */
#define SCALE_Y_MG_PER_LSB 0.146f
#define SCALE_Z_MG_PER_LSB 0.146f

/* ---- Metal detector threshold ---- */
#define METAL_THRESHOLD_MG 800.0f

/* ---- I2C bus device ---- */
#define I2C_BUS "/dev/i2c-1"

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 100000  /* 10 Hz */

/* ---- Retry parameters ---- */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000   /* 100 ms */

/* ---- Globals for signal handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LIS3MDL initialization                                              */
/* ------------------------------------------------------------------ */
static int lis3mdl_init(int fd)
{
    /*
     * CTRL_REG1: ODR = 10 Hz (0100), Z-axis enable (0001), Y-axis enable
     * (0001), X-axis enable (0001) -> 0x45
     */
    if (i2c_write_reg8(fd, LIS3MDL_REG_CTRL_REG1, 0x45) < 0)
        return -1;

    /*
     * CTRL_REG4: Full-scale selection = ±4 gauss (0000), high-resolution
     * mode (0000) -> 0x00
     */
    if (i2c_write_reg8(fd, LIS3MDL_REG_CTRL_REG4, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated magnetic field data                                 */
/* ------------------------------------------------------------------ */
static int lis3mdl_read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_burst(fd, LIS3MDL_REG_OUT_X_L, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * SCALE_X_MG_PER_LSB + OFFSET_X_MG;
    *y = (float)raw_y * SCALE_Y_MG_PER_LSB + OFFSET_Y_MG;
    *z = (float)raw_z * SCALE_Z_MG_PER_LSB + OFFSET_Z_MG;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Metal detector alert                                                */
/* ------------------------------------------------------------------ */
static void check_metal_detector(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD_MG) {
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(stderr,
                "[ALERT] Metal detected at %s! Total field: %.2f mG\n",
                ts, magnitude);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire exclusive access to the LIS3MDL */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x3D) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the LIS3MDL */
    if (lis3mdl_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed after %d retries.\n",
                MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file once */
    g_log_file = fopen("magnetic_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LIS3MDL magnetic field reader started. Logging to magnetic_log.txt\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (lis3mdl_read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read magnetic field data. Retrying...\n");
            for (int attempt = 1; attempt <= MAX_RETRIES && g_running; attempt++) {
                usleep(RETRY_DELAY_US);
                if (lis3mdl_read_magnetometer(g_i2c_fd, &x, &y, &z) == 0)
                    break;
                fprintf(stderr, "Retry %d/%d failed.\n", attempt, MAX_RETRIES);
            }
            if (!g_running)
                break;
            continue;
        }

        check_metal_detector(x, y, z);

        if (fprintf(g_log_file, "%.2f,%.2f,%.2f\n", x, y, z) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n",
                    strerror(errno));
            break;
        }
        fflush(g_log_file);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

