                "[ALERT] Metal detected at %s! Total field: %.2f mG\n",
                ts, magnitude);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire exclusive access to the LIS3MDL */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x3D) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the LIS3MDL */
    if (lis3mdl_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed after %d retries.\n",
                MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file once */
    g_log_file = fopen("magnetic_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LIS3MDL magnetic field reader started. Logging to magnetic_log.txt\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (lis3mdl_read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read magnetic field data. Retrying...\n");
            for (int attempt = 1; attempt <= MAX_RETRIES && g_running; attempt++) {
                usleep(RETRY_DELAY_US);
                if (lis3mdl_read_magnetometer(g_i2c_fd, &x, &y, &z) == 0)
                    break;
                fprintf(stderr, "Retry %d/%d failed.\n", attempt, MAX_RETRIES);
            }
            if (!g_running)
                break;
            continue;
        }

        check_metal_detector(x, y, z);

        if (fprintf(g_log_file, "%.2f,%.2f,%.2f\n", x, y, z) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n",
                    strerror(errno));
            break;
        }
        fflush(g_log_file);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

