/*
 * ADXL354B Vibration Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B CS  -> GPIO8  (BCM)  (SPI0 CE0)
 *   ADXL354B SDO -> GPIO9  (BCM)  (SPI0 MISO)
 *   ADXL354B SDA -> GPIO10 (BCM)  (SPI0 MOSI)
 *   ADXL354B SCL -> GPIO11 (BCM)  (SPI0 SCLK)
 *   ADXL354B VDD -> 3.3V
 *   ADXL354B GND -> GND
 *
 * Build: gcc -O2 -Wall -o adxl354b_monitor adxl354b_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADXL354B Register Map ---- */
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_DEVID_MST  0x01
#define ADXL354B_REG_PARTID     0x02
#define ADXL354B_REG_RESET      0x1F
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_DATA_FORMAT 0x31
#define ADXL354B_REG_DATAX0     0x32

/* ---- ADXL354B Expected Values ---- */
#define ADXL354B_DEVID_AD_EXPECTED 0xE5
#define ADXL354B_DEVID_MST_EXPECTED 0x00
#define ADXL354B_PARTID_EXPECTED   0x35

/* ---- SPI Configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

/* ---- Timing ---- */
#define RESET_DELAY_US  1000U      /* 1 ms */
#define STABLE_DELAY_US  10000U     /* 10 ms */
#define SAMPLE_DELAY_US 100000U    /* 100 ms */
#define MAX_RETRIES     3

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_file = NULL;

/* ---- Signal Handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- SPI Transfer Helper ---- */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- SPI Read 1 Byte ---- */
static int spi_read_byte(uint8_t reg, uint8_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *value = rx[1];
    return 0;
}

/* ---- SPI Write 1 Byte ---- */
static int spi_write_byte(uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    return 0;
}

/* ---- SPI Read N Bytes ---- */
static int spi_read_bytes(uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t tx[len + 1];
    uint8_t rx[len + 1];

    tx[0] = (uint8_t)(reg | 0x80);
    memset(&tx[1], 0x00, len);

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    memcpy(buf, &rx[1], len);
    return 0;
}

/* ---- ADXL354B Initialization ---- */
static int adxl354b_init(void)
{
    uint8_t partid = 0;

    /* Verify device identity */
    if (spi_read_byte(ADXL354B_REG_PARTID, &partid) < 0) {
        fprintf(stderr, "Failed to read PARTID register\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID_EXPECTED) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n",
                partid, ADXL354B_PARTID_EXPECTED);
        return -1;
    }

    /* Reset device */
    if (spi_write_byte(ADXL354B_REG_RESET, 0x52) < 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    usleep(RESET_DELAY_US);

    /* Clear RUN bit in POWER_CTL to enter standby */
    if (spi_write_byte(ADXL354B_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Failed to clear RUN bit in POWER_CTL\n");
        return -1;
    }
    usleep(10000); /* 10 ms stabilization */

    /* Verify STABLE bit in POWER_CTL (bit 3) */
    uint8_t power_ctl = 0;
    for (int i = 0; i < 10; i++) {
        if (spi_read_byte(ADXL354B_REG_POWER_CTL, &power_ctl) < 0) {
            fprintf(stderr, "Failed to read POWER_CTL during stable check\n");
            return -1;
        }
        if (power_ctl & 0x08)
            break;
        usleep(10000);
    }
    if (!(power_ctl & 0x08)) {
        fprintf(stderr, "ADXL354B not stable after reset\n");
        return -1;
    }

    /* Set RUN bit in POWER_CTL to start data acquisition */
    if (spi_write_byte(ADXL354B_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to set RUN bit in POWER_CTL\n");
        return -1;
    }
    usleep(10000);

    return 0;
}

/* ---- Read 20-bit signed acceleration data ---- */
static int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (spi_read_bytes(ADXL354B_REG_DATAX0, buf, sizeof(buf)) < 0)
        return -1;

    /* ADXL354B outputs 20-bit data left-justified in 16 bits */
    *x = (int16_t)(((uint16_t)buf[1] << 8) | buf[0]) >> 4;
    *y = (int16_t)(((uint16_t)buf[3] << 8) | buf[2]) >> 4;
    *z = (int16_t)(((uint16_t)buf[5] << 8) | buf[4]) >> 4;

    return 0;
}

/* ---- Log Data ---- */
static void log_data(int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, X: %d, Y: %d, Z: %d\n",
            timestamp, x, y, z);
    fflush(g_log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        /* Put device in standby before closing */
        (void)spi_write_byte(ADXL354B_REG_POWER_CTL, 0x00);
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL354B */
    if (adxl354b_init() < 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("vibration_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open vibration_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL354B vibration monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (adxl354b_read_acceleration(&x, &y, &z) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "SPI read attempt %d failed, retrying...\n", attempt + 1);
            usleep(10000);
        }

        if (success) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration after %d attempts\n", MAX_RETRIES);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

