/* Read a 16-bit register from the ADIS16362 */
static int adis16362_read_register(uint8_t reg, uint16_t *value) {
    char tx_buf[3];
    char rx_buf[3];
    int result;

    /* Build the SPI message for a read:
     * Byte 0: Address byte (MSB = 1 for read)
     * Byte 1: Dummy byte (clocks out data)
     * Byte 2: Dummy byte (clocks out data)
     */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X (returned %d)\n", reg, result);
        return -1;
    }

    /* Extract the 16-bit value from the response */
    *value = ((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1];

    return 0;
}

/* Write a 16-bit value to a register in the ADIS16362 */
static int adis16362_write_register(uint8_t reg, uint16_t value) {
    char tx_buf[3];
