     */
    tx_buf[0] = (char)(reg & 0x7F);
    tx_buf[1] = (char)((value >> 8) & 0xFF);
    tx_buf[2] = (char)(value & 0xFF);

    result = spiWrite(spi_handle, tx_buf, 3);
