/*
 * KY-032 IR Obstacle Avoidance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (pin 1)
 *   GND         -> GND  (pin 9)
 *
 * The KY-032 module outputs a logic 0 when an obstacle is detected,
 * a logic 1 when the sensor is clear.  This program polls both sensors
 * at 100 ms intervals and logs the detection status to the console.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o ky032_reader ky032_reader.c -lgpiod
 *
 * Run:
 *   ./ky032_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read both KY-032 sensors in a single bulk read.
 * Returns 0 on success, -1 on error.
 * On success, *s1 and *s2 are set to the active-low sensor states.
 */
static int read_ky032(struct gpiod_line *s1, struct gpiod_line *s2, int *s1_val, int *s2_val)
{
    int v1 = gpiod_line_get_value(s1);
    int v2 = gpiod_line_get_value(s2);

    if (v1 < 0) {
        fprintf(stderr, "Error reading GPIO%d: %s\n", SENSOR1_PIN, strerror(errno));
        return -1;
    }
    if (v2 < 0) {
        fprintf(stderr, "Error reading GPIO%d: %s\n", SENSOR2_PIN, strerror(errno));
        return -1;
    }

    *s1_val = v1;
    *s2_val = v2;
    return 0;
}

static void log_sensor_data(int s1_val, int s2_val)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    printf("[%s] Sensor 1: %s, Sensor 2: %s\n",
           timestamp,
           s1_val ? "Obstacle Detected" : "Path Clear",
           s2_val ? "Obstacle Detected" : "Path Clear");
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL;
    struct gpiod_line *s2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 Model B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines for both sensors */
    s1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (s1 == NULL) {
        fprintf(stderr, "Error getting GPIO%d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    s2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (s2 == NULL) {
        fprintf(stderr, "Error getting GPIO%d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as inputs */
    if (gpiod_line_request_input(s1, "ky032-s1") < 0) {
        fprintf(stderr, "Error requesting GPIO%d as input: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s2, "ky032-s2") < 0) {
        fprintf(stderr, "Error requesting GPIO%d as input: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 IR Obstacle Avoidance Sensor Reader started.\n");
    printf("Sensor 1: GPIO%d | Sensor 2: GPIO%d | Poll Interval: 100 ms\n",
           SENSOR1_PIN, SENSOR2_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int s1_val = 0, s2_val = 0;

        if (read_ky032(s1, s2, &s1_val, &s2_val) == 0) {
            log_sensor_data(s1_val, s2_val);
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (s1 != NULL) {
        gpiod_line_release(s1);
    }
    if (s2 != NULL) {
        gpiod_line_release(s2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

