code:
/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 VDD  -> 3.3 V (Pin 1)
 *   ADIS16266 GND  -> GND  (Pin 9)
 *   ADIS16266 SCLK -> GPIO11 (SPI0 SCLK, Pin 23)
 *   ADIS16266 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   ADIS16266 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   ADIS16266 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *
 * SPI Mode 3:
 *   ADIS16266 CS   -> GPIO8  (CE0)
 *   ADIS16266 SCLK -> GPIO11 (SCLK)
 *   ADIS16266 DOUT -> GPIO9  (MISO)
 *   ADIS16266 DIN  -> GPIO10 (MOSI)
 *
 * Build: gcc -O2 -Wall -o adis16266_reader adis16266_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3
#define SPI_DELAY_USEC  0

#define ADIS16266_REG_XGYRO_OUT  0x00
#define ADIS16266_REG_YGYRO_OUT  0x02
#define ADIS16266_REG_ZGYRO_OUT  0x04
#define ADIS16266_REG_GLOB_CMD   0x06
#define ADIS16266_REG_GLOB_STAT  0x08
#define ADIS16266_REG_XGYRO_CFG  0x0A
#define ADIS16266_REG_YGYRO_CFG  0x0C
#define ADIS16266_REG_ZGYRO_CFG  0x0E
#define ADIS16266_REG_XGYRO_SMPL 0x10
#define ADIS16266_REG_YGYRO_SMPL 0x12
#define ADIS16266_REG_ZGYRO_SMPL 0x14
#define ADIS16266_REG_XGYRO_OFS 0x16
#define ADIS16266_REG_YGYRO_OFS 0x18
#define ADIS16266_REG_ZGYRO_OFS 0x1A

#define ADIS16266_GLOB_CMD_RESET  0x01
#define ADIS16266_GLOB_STAT_RESET 0x01

#define GYRO_SCALE_FACTOR 0.02f  /* deg/sec per LSB */
#define SAMPLE_PERIOD_US  100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to an ADIS16266 register.
 * The ADIS16266 expects the MSB of the address byte to be set.
 */
static int adis16266_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), value };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_USEC,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an ADIS16266 register.
 */
static int adis16266_read_reg(uint8_t reg, uint8_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_USEC,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = rx[1];
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 */
static int adis16266_read_reg16(uint8_t reg, int16_t *value)
{
    uint8_t lo, hi;

    if (adis16266_read_reg(reg, &lo) < 0)
        return -1;
    if (adis16266_read_reg(reg + 1, &hi) < 0)
        return -1;

    *value = (int16_t)((hi << 8) | lo);
    return 0;
}

static int adis16266_init(void)
{
    uint8_t status = 0;

    /* Verify device presence by reading the GLOB_STAT register */
    if (adis16266_read_reg(ADIS16266_REG_GLOB_STAT, &status) < 0) {
        fprintf(stderr, "Failed to read GLOB_STAT - sensor may be absent.\n");
        return -1;
    }

    /* Reset the device */
    if (adis16266_write_reg(ADIS16266_REG_GLOB_CMD, ADIS16266_GLOB_CMD_RESET) < 0)
        return -1;

    /* Allow reset to complete */
    usleep(10000);

    /* Verify reset by reading GLOB_STAT again */
    if (adis16266_read_reg(ADIS16266_REG_GLOB_STAT, &status) < 0)
        return -1;

    if ((status & ADIS16266_GLOB_STAT_RESET) == 0) {
        fprintf(stderr, "ADIS16266 reset did not complete.\n");
        return -1;
    }

    /* Configure gyroscope output data rate (100 Hz) */
    if (adis16266_write_reg(ADIS16266_REG_XGYRO_SMPL, 0x00) < 0)
        return -1;
    if (adis16266_write_reg(ADIS16266_REG_YGYRO_SMPL, 0x00) < 0)
        return -1;
    if (adis16266_write_reg(ADIS16266_REG_ZGYRO_SMPL, 0x00) < 0)
        return -1;

    /* Configure gyroscope full-scale range (+/- 250 deg/sec) */
    if (adis16266_write_reg(ADIS16266_REG_XGYRO_CFG, 0x00) < 0)
        return -1;
    if (adis16266_write_reg(ADIS16266_REG_YGYRO_CFG, 0x00) < 0)
        return -1;
    if (adis16266_write_reg(ADIS16266_REG_ZGYRO_CFG, 0x00) < 0)
        return -1;

    return 0;
}

static int adis16266_read_gyro(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg16(ADIS16266_REG_XGYRO_OUT, &raw_x) < 0)
        return -1;
    if (adis16266_read_reg16(ADIS16266_REG_YGYRO_OUT, &raw_y) < 0)
        return -1;
    if (adis16266_read_reg16(ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0)
        return -1;

    *x = (float)raw_x * GYRO_SCALE_FACTOR;
    *y = (float)raw_y * GYRO_SCALE_FACTOR;
    *z = (float)raw_z * GYRO_SCALE_FACTOR;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (adis16266_init() < 0) {
        fprintf(stderr, "ADIS16266 initialization failed.\n");
        goto cleanup;
    }

    printf("ADIS16266 initialized. Reading gyroscope data every 100 ms...\n");

    while (g_running) {
        float x, y, z;

        if (adis16266_read_gyro(&x, &y, &z) == 0) {
            printf("X: %.3f deg/s, Y: %.3f deg/s, Z: %.3f deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_SUCCESS;
}

