/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * Uses the Linux I2C-dev character device interface (no wiringPi).
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   LSM6DSR SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o lsm6dsr_reader lsm6dsr_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR register addresses ---- */
#define LSM6DSR_WHO_AM_I      0x0F
#define LSM6DSR_WHO_AM_I_VAL   0x69

#define LSM6DSR_CTRL1_XL      0x10
#define LSM6DSR_CTRL2_G       0x11
#define LSM6DSR_OUTX_L_G      0x22
#define LSM6DSR_OUTX_L_XL     0x28

#define LSM6DSR_CTRL3_C       0x12
#define LSM6DSR_OUTX_L_C      0x24

/* ---- I2C device path ---- */
#define I2C_BUS "/dev/i2c-1"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a burst of bytes starting at `reg` into `buf`. Returns 0 on success,
 * -1 on error. */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lsm6dsr(int fd)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, LSM6DSR_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL1_XL: ODR_XL = 100 Hz (0x60), FS_XL = +/- 2g (0x00)
     * CTRL2_G:  ODR_G  = 100 Hz (0x60), FS_G  = +/- 245 dps (0x00)
     */
    if (i2c_write_reg8(fd, LSM6DSR_CTRL1_XL, 0x60) != 0) return -1;
    if (i2c_write_reg8(fd, LSM6DSR_CTRL2_G, 0x60) != 0) return -1;

    /*
     * CTRL3_C:  BDU = 1 (block data update), IF_INC = 1 (auto-increment)
     */
    if (i2c_write_reg8(fd, LSM6DSR_CTRL3_C, 0x80) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz)
{
    uint8_t raw[12];

    /* Read accelerometer (6 bytes: XL, XH, YL, YH, ZL, ZH) */
    if (i2c_read_burst(fd, LSM6DSR_OUTX_L_XL, raw, sizeof(raw)) != 0)
        return -1;

    int16_t ax_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ay_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t az_raw = (int16_t)((raw[5] << 8) | raw[4]);

    /* Read gyroscope (6 bytes: XL, XH, YL, YH, ZL, ZH) */
    if (i2c_read_burst(fd, LSM6DSR_OUTX_L_G, raw, sizeof(raw)) != 0)
        return -1;

    int16_t gx_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t gy_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t gz_raw = (int16_t)((raw[5] << 8) | raw[4]);

    /* Convert to g and degrees/second */
    *ax = (float)ax_raw / 32768.0f * 2.0f;
    *ay = (float)ay_raw / 32768.0f * 2.0f;
    *az = (float)az_raw / 32768.0f * 2.0f;
    *gx = (float)gx_raw / 32768.0f * 245.0f;
    *gy = (float)gy_raw / 32768.0f * 245.0f;
    *gz = (float)gz_raw / 32768.0f * 245.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the LSM6DSR slave address (SA0 tied to GND) */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x6A) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x6A: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the LSM6DSR */
    if (init_lsm6dsr(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Reading data every 100 ms (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_sensor_data(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%.3f, %.3f, %.3f, %.3f, %.3f, %.3f\n",
                   ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }

        /* Sleep 100 ms (interruptible by signals) */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 };
        nanosleep(&ts, NULL);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

