/*
 * FXOS8700 12-byte block reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   FXOS8700 SDA -> GPIO2 (BCM)
 *   FXOS8700 SCL -> GPIO3 (BCM)
 *   FXOS8700 VDD -> 3.3 V
 *   FXOS8700 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o fxos8700 fxos8700.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700 register addresses ---- */
#define FXOS8700_ADDRESS          0x29
#define FXOS8700_REG_STATUS       0x00
#define FXOS8700_REG_OUT_X_MSB    0x01
#define FXOS8700_REG_M_OUT_X_MSB  0x04

/* ---- Expected device ID ---- */
#define FXOS8700_ID               0xC7

/* ---- Global state for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an FXOS8700 register. Returns 0 on success, -1 on error. */
static int fxos8700_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an FXOS8700 register. Returns 0 on success, -1 on error. */
static int fxos8700_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 12-byte block from the FXOS8700. Returns 0 on success, -1 on error. */
static int fxos8700_read_block(int fd, uint8_t *buf, size_t len)
{
    if (write(fd, FXOS8700_REG_OUT_X_MSB, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select) failed: %s\n",
                strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C block read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse 14-bit left-aligned accelerometer data from the block. */
static int parse_accel(const uint8_t *block, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t raw_x = ((uint16_t)block[0] << 8) | block[1];
    uint16_t raw_y = ((uint16_t)block[2] << 8) | block[3];
    uint16_t raw_z = ((uint16_t)block[4] << 8) | block[5];

    /* FXOS8700 outputs 14-bit left-aligned data; shift right 2 to get
     * the 14-bit value. */
    *x = (int16_t)((raw_x >> 2) & 0x3FFF);
    *y = (int16_t)((raw_y >> 2) & 0x3FFF);
    *z = (int16_t)((raw_z >> 2) & 0x3FFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse 16-bit magnetometer data from the block. */
static int parse_mag(const uint8_t *block, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t raw_x = ((uint16_t)block[6] << 8) | block[7];
    uint16_t raw_y = ((uint16_t)block[8] << 8) | block[9];
    uint16_t raw_z = ((uint16_t)block[10] << 8) | block[11];

    /* FXOS8700 magnetometer outputs 16-bit left-aligned data; shift right 2
     * to get the 16-bit value. */
    *x = (int16_t)((raw_x >> 2) & 0x3FFF);
    *y = (int16_t)((raw_y >> 2) & 0x3FFF);
    *z = (int16_t)((raw_z >> 2) & 0x3FFF);
    return 0;
}

