#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_init(int handle) {
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 to standby mode.\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 data format.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 to measurement mode.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data.\n");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_norm = (double)x / 32768.0;
    double y_norm = (double)y / 32768.0;
    double z_norm = (double)z / 32768.0;
    double pitch = atan2(y_norm, sqrt(x_norm * x_norm + z_norm * z_norm)) * 180.0 / M_PI;
    double roll = atan2(-x_norm, sqrt(y_norm * y_norm + z_norm * z_norm)) * 180.0 / M_PI;
    return pitch;
}

static int log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", ADXL345_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            double tilt_angle = calculate_tilt_angle(x, y, z);
            if (tilt_angle > ADXL345_TILT_THRESHOLD) {
                if (log_tilt_event(tilt_angle) < 0) {
                    fprintf(stderr, "Warning: Failed to log tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

