        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s] ", buffer);
}

int main(int argc, char *argv[]) {
    int threshold = 0;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum number of high readings per window\n");
        return EXIT_FAILURE;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d (code %d)\n", GPIO_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO%d (code %d)\n", GPIO_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (threshold: %d)\n", GPIO_PIN, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int high_count = 0;
        int samples = 0;
        int error = 0;

        for (int i = 0; i < WINDOW_SECONDS * 10 && running; i++) {
            int level = gpioRead(GPIO_PIN);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed for GPIO%d (code %d)\n", GPIO_PIN, level);
                error = 1;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            samples++;
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (error) {
            gpioDelay(PAUSE_SECONDS * 1000000);
            continue;
        }

        if (high_count > threshold) {
            print_timestamp();
            printf("ALERT: %d high readings in %d seconds (threshold: %d)\n",
                   high_count, WINDOW_SECONDS, threshold);
        } else {
            print_timestamp();
            printf("Status: %d high readings in %d seconds (threshold: %d)\n",
                   high_count, WINDOW_SECONDS, threshold);
        }

        gpioDelay(PAUSE_SECONDS * 1000000);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

