#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define LOCK_DURATION_SEC 5
#define LOG_FILE "access_log.txt"
#define MIN_CODE 100000
#define MAX_CODE 999999
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int generate_code(void)
{
    int code = rand() % (MAX_CODE - MIN_CODE + 1) + MIN_CODE;
    return code;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%06d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int code = generate_code();
        printf("Access code: %06d\n", code);

        char input[16];
        int input_len = 0;

        while (program_running) {
            int c = getchar();
            if (c == EOF) {
                fprintf(stderr, "Error reading input: %s\n", strerror(errno));
                break;
            }

            if (c == '\n') {
                input[input_len] = '\0';
                break;
            }

            if (input_len < sizeof(input) - 1) {
                input[input_len++] = (char)c;
            } else {
                fprintf(stderr, "Input too long, please enter a six-digit code.\n");
                input_len = 0;
            }
        }

        if (!program_running) {
            break;
        }

        if (input_len == 0) {
            printf("Invalid input, please enter a six-digit code.\n");
            continue;
        }

        if (input_len != 6) {
            printf("Invalid input length, please enter a six-digit code.\n");
            continue;
        }

        int entered_code = atoi(input);
        if (entered_code < MIN_CODE || entered_code > MAX_CODE) {
            printf("Invalid code range, please enter a six-digit code.\n");
            continue;
        }

        if (entered_code == code) {
            printf("Access granted!\n");

            if (gpiod_line_set_value(line_a, 1) < 0) {
                fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", DOOR_A_PIN, strerror(errno));
                goto cleanup;
            }
            if (gpiod_line_set_value(line_b, 1) < 0) {
                fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", DOOR_B_PIN, strerror(errno));
                goto cleanup;
            }

            sleep(LOCK_DURATION_SEC);

            if (gpiod_line_set_value(line_a, 0) < 0) {
                fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", DOOR_A_PIN, strerror(errno));
                goto cleanup;
            }
            if (gpiod_line_set_value(line_b, 0) < 0) {
                fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", DOOR_B_PIN, strerror(errno));
                goto cleanup;
            }

            if (log_access(code) < 0) {
                fprintf(stderr, "Warning: failed to log access.\n");
            }
        } else {
            printf("Access denied!\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line_a) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Door access control system stopped.\n");
    return ret;
}

