#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x29
#define BH1750_PWR_ON 0x01
#define BH1750_PWR_OFF 0x00
#define BH1750_CONT_HRES 0x10
#define BH1750_CONV_TIME_US 180000
#define LOG_FILE "light_log.txt"
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        return -1;
    }
    if (write(fd, &BH1750_PWR_ON, 1) != 1) {
        fprintf(stderr, "Error: Failed to power on BH1750: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

int bh1750_read_lux(int fd, float *lux) {
    uint8_t cmd = BH1750_CONT_HRES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_US);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2;
    return 0;
}

int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (bh1750_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: BH1750 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("BH1750 initialized. Logging to %s every 5 seconds. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read lux value.\n");
        }
        sleep(5);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        write(i2c_fd, &BH1750_PWR_OFF, 1);
        close(i2c_fd);
    }
    return 0;
}

