#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C address (SA0 tied to GND) */
#define LSM303_ADDR 0x1C

/* LSM303DLHC magnetometer registers */
#define LSM303_MAG_CTRL_REG1 0x20
#define LSM303_MAG_CTRL_REG2 0x21
#define LSM303_MAG_CTRL_REG3 0x22
#define LSM303_MAG_CTRL_REG4 0x23
#define LSM303_MAG_CTRL_REG5 0x24
#define LSM303_MAG_CTRL_REG6 0x25
#define LSM303_MAG_OUT_X_L  0x03

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS "/dev/i2c-1"

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize I2C communication */
static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    /* Configure magnetometer: continuous conversion mode, high performance */
    uint8_t ctrl_reg1 = 0x01; /* OM=11 (high performance), MD=00 (continuous) */
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to magnetometer CTRL_REG1");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* Read magnetometer data (6 bytes starting at OUT_X_L) */
static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    /* Write register address to read */
    if (write(i2c_fd, &LSM303_MAG_OUT_X_L, 1) != 1) {
        perror("Failed to write magnetometer register address");
        return -1;
    }

    /* Read 6 bytes of data */
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read magnetometer data");
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *z = (int16_t)((buffer[3] << 8) | buffer[2]);
    *y = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Calculate Z-axis field magnitude */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf((float)(x * x + y * y + z * z));
}

/* Set LED brightness using hardware PWM */
static void set_led_brightness(float magnitude) {
    int duty_cycle = (int)(magnitude * 100.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    if (gpioPWM(LED_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Warning: Failed to set PWM duty cycle\n");
    }
}

/* Cleanup resources */
static void cleanup(void) {
    /* Stop PWM */
    gpioPWM(LED_PIN, 0);

    /* Close I2C file descriptor */
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 100 (0-100) */
    if (gpioSetPWMrange(LED_PIN, 100) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("magnetometer_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
