/*
 * HMC5883L Magnetometer Hard-Iron Offset Calculator
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Library: pigpio (modern, actively maintained)
 *
 * Reads raw magnetometer data, computes a running average of the last 100
 * samples, and applies the offsets to each new reading.  Prints the
 * offset-corrected X, Y, and Z components every 500 ms.
 *
 * Build:  gcc -O2 -Wall -o hmc5883l_offset hmc5883l_offset.c -lpigpio -lrt
 * Run:    sudo ./hmc5883l_offset
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- HMC5883L I2C address (SA0 tied to GND) ---- */
#define HMC5883L_ADDR 0x1E

/* ---- HMC5883L register addresses ---- */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

/* ---- Configuration values ---- */
#define CONFIG_A_VALUE 0x70   /* 8-average, 15 Hz, normal measurement */
#define CONFIG_B_VALUE 0x20   /* Gain 1.3 Gauss */
#define MODE_CONTINUOUS 0x00  /* Continuous measurement mode */

/* ---- Running-average buffer size ---- */
#define BUFFER_SIZE 100

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 500000

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a single byte to an HMC5883L register ---- */
static int hmc5883l_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

/* ---- Read a single byte from an HMC5883L register ---- */
static int hmc5883l_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Initialize the HMC5883L magnetometer ---- */
static int hmc5883l_init(int handle)
{
    /* Configure CONFIG_A: 8-average, 15 Hz, normal measurement */
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_A, CONFIG_A_VALUE) < 0)
        return -1;

    /* Configure CONFIG_B: Gain 1.3 Gauss */
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_B, CONFIG_B_VALUE) < 0)
        return -1;

    /* Set continuous measurement mode */
    if (hmc5883l_write_reg(handle, HMC5883L_MODE, MODE_CONTINUOUS) < 0)
        return -1;

    return 0;
}

/* ---- Read raw magnetometer data (X, Y, Z) ---- */
static int hmc5883l_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;

    if (hmc5883l_read_reg(handle, HMC5883L_DATA_X_MSB, &x_msb) < 0)
        return -1;
    if (hmc5883l_read_reg(handle, HMC5883L_DATA_X_LSB, &x_lsb) < 0)
        return -1;
    if (hmc5883l_read_reg(handle, HMC5883L_DATA_Z_MSB, &z_msb) < 0)
        return -1;
    if (hmc5883l_read_reg(handle, HMC5883L_DATA_Z_LSB, &z_lsb) < 0)
        return -1;
    if (hmc5883l_read_reg(handle, HMC5883L_DATA_Y_MSB, &y_msb) < 0)
        return -1;
    if (hmc5883l_read_reg(handle, HMC5883L_DATA_Y_LSB, &y_lsb) < 0)
        return -1;

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);

    return 0;
}

/* ---- Compute running average of the last BUFFER_SIZE samples ---- */
static void running_average(const int16_t *samples, int count,
                            int16_t *sum, int16_t *sum_sq)
{
    *sum = 0;
    *sum_sq = 0;
    for (int i = 0; i < count; i++) {
        *sum += samples[i];
        *sum_sq += (int16_t)(samples[i] * samples[i]);
    }
}

/* ---- Apply hard-iron offsets to a raw reading ---- */
static void apply_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                          int16_t offset_x, int16_t offset_y, int16_t offset_z,
                          int16_t *corrected_x, int16_t *corrected_y,
                          int16_t *corrected_z)
{
    *corrected_x = raw_x - offset_x;
    *corrected_y = raw_y - offset_y;
    *corrected_z = raw_z - offset_z;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    g_i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the magnetometer */
    if (hmc5883l_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: HMC5883L initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Running-average state */
    int16_t raw_samples[BUFFER_SIZE];
    int16_t offset_x = 0, offset_y = 0, offset_z = 0;
    int16_t sum_x = 0, sum_y = 0, sum_z = 0;
    int16_t sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    int sample_count = 0;

    printf("HMC5883L Hard-Iron Offset Calculator\n");
    printf("Sampling every %d ms. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (hmc5883l_read_raw(g_i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            /* Update running average */
            raw_samples[sample_count] = raw_x;
            raw_samples[(sample_count + 1) % BUFFER_SIZE] = raw_y;
            raw_samples[(sample_count + 2) % BUFFER_SIZE] = raw_z;

            if (sample_count < BUFFER_SIZE) {
                sample_count++;
            } else {
                running_average(raw_samples, BUFFER_SIZE, &sum_x, &sum_sq_x);
                running_average(raw_samples, BUFFER_SIZE, &sum_y, &sum_sq_y);
                running_average(raw_samples, BUFFER_SIZE, &sum_z, &sum_sq_z);

                /* Compute offsets (simple average) */
                offset_x = (int16_t)(sum_x / BUFFER_SIZE);
                offset_y = (int16_t)(sum_y / BUFFER_SIZE);
                offset_z = (int16_t)(sum_z / BUFFER_SIZE);
            }

            /* Apply offsets to the raw reading */
            int16_t corrected_x, corrected_y, corrected_z;
            apply_offsets(raw_x, raw_y, raw_z, offset_x, offset_y, offset_z,
                          &corrected_x, &corrected_y, &corrected_z);

            /* Print the offset-corrected data */
            printf("X: %6d  Y: %6d  Z: %6d  Offset X: %6d  Y: %6d  Z: %6d\n",
                   corrected_x, corrected_y, corrected_z,
                   offset_x, offset_y, offset_z);
        } else {
            fprintf(stderr, "Warning: I2C read error, skipping sample.\n");
        }

        /* Wait for the next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

