/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration data at ~10 ms intervals, stores the
 * last 64 samples in a circular buffer, and dumps the last 10 samples
 * on a rising edge of BCM GPIO 23 (physical pin 16).
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    sudo ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register addresses ---- */
#define LSM303D_ADDR          0x19
#define LSM303D_WHO_AM_I      0x0F
#define LSM303D_WHO_AM_I_VAL  0x33
#define LSM303D_CTRL_REG1    0x20
#define LSM303D_CTRL_REG4    0x23
#define LSM303D_INT1_CFG     0x30
#define LSM303D_OUT_X_L      0x28

/* ---- Sensitivity (0.061 mg/LSB) ---- */
#define ACCEL_SENSITIVITY_MG  0.061f

/* ---- Circular buffer ---- */
#define BUFFER_SIZE 64

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D initialization ---- */
static int lsm303d_init(int fd)
{
    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &whoami) < 0)
        return -1;
    if (whoami != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR=100 Hz (0x57), all axes enabled (0x07) */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x57) < 0)
        return -1;

    /* CTRL_REG4: full-scale = +/- 2g (0x00) */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1_CFG: active-high, no latched, 2000 mg threshold, no duration */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Circular buffer ---- */
static void cb_init(circular_buffer_t *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(circular_buffer_t *cb, float x, float y, float z)
{
    cb->samples[cb->head].x = x;
    cb->samples[cb->head].y = y;
    cb->samples[cb->head].z = z;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void cb_dump_last_10(const circular_buffer_t *cb)
{
    if (cb->count < 10) {
        fprintf(stderr, "Buffer too small (%d samples)\n", cb->count);
        return;
    }
    int start = (cb->head - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    printf("\n--- Last 10 samples (%d total) ---\n", cb->count);
    for (int i = 0; i < 10; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%d] X=%.2f Y=%.2f Z=%.2f  mg\n",
               i, cb->samples[idx].x * ACCEL_SENSITIVITY_MG,
               cb->samples[idx].y * ACCEL_SENSITIVITY_MG,
               cb->samples[idx].z * ACCEL_SENSITIVITY_MG);
    }
    printf("-------------------------------------\n");
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line (BCM 23, physical pin 16) */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, 23);
    if (!g_int1_line) {
        fprintf(stderr, "gpiod_chip_get_line(23) failed: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM303D monitor started. INT1=BCM23 (physical pin 16). Ctrl+C to exit.\n");

    circular_buffer_t cb;
    cb_init(&cb);

    while (g_running) {
        /* Poll for rising edge on INT1 */
        int ret = gpiod_line_event_wait(g_int1_line, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0)
            continue; /* timeout, no event */

        /* Read 6 bytes of acceleration data (X, Y, Z, then X, Y, Z again) */
        uint8_t raw[6];
        if (i2c_read_burst(g_i2c_fd, LSM303D_OUT_X_L, raw, sizeof(raw)) < 0) {
            fprintf(stderr, "Warning: failed to read acceleration data, skipping sample\n");
            continue;
        }

        int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
        int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
        int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

        float x_g = (float)x_raw * ACCEL_SENSITIVITY_MG / 1000.0f;
        float y_g = (float)y_raw * ACCEL_SENSITIVITY_MG / 1000.0f;
        float z_g = (float)z_raw * ACCEL_SENSITIVITY_MG / 1000.0f;

        cb_add(&cb, x_g, y_g, z_g);

        if (cb.count >= BUFFER_SIZE) {
            cb_dump_last_10(&cb);
            cb.count = 0;
        }

        printf("X=%.2f Y=%.2f Z=%.2f  mg\n", x_g * 1000.0f, y_g * 1000.0f, z_g * 1000.0f);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    /* Disable accelerometer (clear CTRL_REG1) */
    if (g_i2c_fd >= 0) {
        uint8_t ctrl1 = 0x00;
        if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, ctrl1) < 0)
            fprintf(stderr, "Warning: failed to disable accelerometer\n");
    }

    if (g_int1_line)
        gpiod_line_release(g_int1_line);
    if (g_chip)
        gpiod_chip_close(g_chip);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

