#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define UART_PORT_0 "/dev/serial0"
#define UART_PORT_1 "/dev/serial1"
#define LOCK_GPIO_0 17
#define LOCK_GPIO_1 27
#define CODE_LENGTH 6
#define CODE_EXPECTED "123456"
#define LOCK_DURATION_SEC 2
#define READ_TIMEOUT_SEC 5
#define BAUD_RATE B9600

static volatile sig_atomic_t running = 1;
static int uart_handle_0 = -1;
static int uart_handle_1 = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_uart(const char *port, int baud_rate) {
    int handle = serOpen(port, baud_rate, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, pigpio_error(handle));
        return -1;
    }
    return handle;
}

static int initialize_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio);
        return -1;
    }
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d LOW\n", gpio);
        return -1;
    }
    return 0;
}

static int read_code(int handle, char *code, int max_length) {
    int timeout = READ_TIMEOUT_SEC * 1000;
    int total_read = 0;
    time_t start = time(NULL);

    while (total_read < max_length && running) {
        char buffer[256];
        int bytes_read = serRead(handle, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            for (int i = 0; i < bytes_read; i++) {
                if (buffer[i] >= '0' && buffer[i] <= '9') {
                    code[total_read++] = buffer[i];
                } else if (buffer[i] == '\r' || buffer[i] == '\n') {
                    code[total_read] = '\0';
                    return total_read;
                } else {
                    code[total_read++] = '\0';
                    return -1;
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART: %s\n", pigpio_error(bytes_read));
            return -1;
        } else {
            if (time(NULL) - start >= timeout) {
                fprintf(stderr, "Timeout reading from UART\n");
                return -1;
            }
            gpioDelay(10000);
        }
    }
    return total_read;
}

static int check_code(const char *code) {
    if (strcmp(code, CODE_EXPECTED) == 0) {
        return 0;
    }
    fprintf(stderr, "Invalid code: %s (expected %s)\n", code, CODE_EXPECTED);
    return -1;
}

static int control_lock(int gpio, int duration_sec) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error activating lock on GPIO %d\n", gpio);
        return -1;
    }
    time_sleep(duration_sec);
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error deactivating lock on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioWrite(LOCK_GPIO_0, 0);
        gpioWrite(LOCK_GPIO_1, 0);
        serClose(uart_handle_0);
        serClose(uart_handle_1);
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (initialize_gpio(LOCK_GPIO_0) != 0 || initialize_gpio(LOCK_GPIO_1) != 0) {
        cleanup();
        return 1;
    }

    uart_handle_0 = initialize_uart(UART_PORT_0, BAUD_RATE);
    if (uart_handle_0 < 0) {
        cleanup();
        return 1;
    }

    uart_handle_1 = initialize_uart(UART_PORT_1, BAUD_RATE);
    if (uart_handle_1 < 0) {
        cleanup();
        return 1;
    }

    printf("Dual-factor door lock authentication started. Press Ctrl+C to exit.\n");

    while (running) {
        char code_0[CODE_LENGTH + 1];
        char code_1[CODE_LENGTH + 1];

        int code_len_0 = read_code(uart_handle_0, code_0, CODE_LENGTH);
        if (code_len_0 < 0) {
            gpioDelay(100000);
            continue;
        }

        int code_len_1 = read_code(uart_handle_1, code_1, CODE_LENGTH);
        if (code_len_1 < 0) {
            gpioDelay(100000);
            continue;
        }

        if (code_len_0 == CODE_LENGTH && code_len_1 == CODE_LENGTH) {
            if (check_code(code_0) == 0 && check_code(code_1) == 0) {
                printf("Codes matched: %s, %s\n", code_0, code_1);
                if (control_lock(LOCK_GPIO_0, LOCK_DURATION_SEC) != 0 ||
                    control_lock(LOCK_GPIO_1, LOCK_DURATION_SEC) != 0) {
                    fprintf(stderr, "Failed to control lock relays\n");
                }
            }
        } else {
            fprintf(stderr, "Code lengths mismatch: got %d from port 0, %d from port 1\n",
                    code_len_0, code_len_1);
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

