/*
 * PIR Motion Detector with Door Strike Relay
 * Board:  Raspberry Pi 4 Model B
 * Sensor: HC-SR501 PIR on physical GPIO4 (BCM)
 * Relay:  Active-high door strike relay on physical GPIO17 (BCM)
 * API:    libgpiod (modern GPIO character-device API)
 *
 * Build:  gcc -O2 -Wall -Wextra -o pir_door pir_door.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN          4
#define RELAY_PIN        17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define RELAY_ON_US      1000000 /* 1 s   */
#define FAILSAFE_TIMEOUT  10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("pir_door", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    /* Get the PIR line */
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line (GPIO%d): %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Get the relay line */
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line (GPIO%d): %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request PIR line as input */
    if (gpiod_line_request_input(pir_line, "pir_door") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    /* Request relay line as output, initial value LOW */
    if (gpiod_line_request_output(relay_line, "pir_door", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "PIR door monitoring started.");
    syslog(LOG_INFO, "PIR sensor on GPIO%d, relay on GPIO%d.", PIR_PIN, RELAY_PIN);

    time_t last_motion_time = 0;
    int relay_active = 0;

    while (g_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (pir_value == 1) {
            time_t current_time = time(NULL);

            if (current_time - last_motion_time >= FAILSAFE_TIMEOUT) {
                /* Failsafe: de-energize relay and log warning */
                if (relay_active) {
                    gpiod_line_set_value(relay_line, 0);
                    relay_active = 0;
                    log_event(LOG_WARNING, "Failsafe: PIR signal remains HIGH for too long, de-energizing relay.");
                }

                /* Log shutdown event */
                log_event(LOG_WARNING, "Failsafe: PIR signal remains HIGH for too long, shutting down.");
                break;
            }

            if (!relay_active) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to activate relay: %s", strerror(errno));
                } else {
                    relay_active = 1;
                    log_event(LOG_INFO, "Relay activated (door strike).");
                }
            }

            last_motion_time = current_time;
        } else {
            /* PIR de-energized or no motion */
            if (relay_active) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to deactivate relay: %s", strerror(errno));
                } else {
                    relay_active = 0;
                    log_event(LOG_INFO, "Relay deactivated (motion stopped).");
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown: ensure relay is de-energized and release lines */
    if (relay_active) {
        gpiod_line_set_value(relay_line, 0);
    }

    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    log_event(LOG_INFO, "PIR door monitoring stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    closelog();
    return ret;
}

