    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line (GPIO%d): %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request PIR line as input */
    if (gpiod_line_request_input(pir_line, "pir_door") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    /* Request relay line as output, initial value LOW */
    if (gpiod_line_request_output(relay_line, "pir_door", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "PIR door monitoring started.");
    syslog(LOG_INFO, "PIR sensor on GPIO%d, relay on GPIO%d.", PIR_PIN, RELAY_PIN);

    time_t last_motion_time = 0;
    int relay_active = 0;

    while (g_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (pir_value == 1) {
            time_t current_time = time(NULL);

            if (current_time - last_motion_time >= FAILSAFE_TIMEOUT) {
                /* Failsafe: de-energize relay and log warning */
                if (relay_active) {
                    gpiod_line_set_value(relay_line, 0);
                    relay_active = 0;
                    log_event(LOG_WARNING, "Failsafe: PIR signal remains HIGH for too long, de-energizing relay.");
                }

                /* Log shutdown event */
                log_event(LOG_WARNING, "Failsafe: PIR signal remains HIGH for too long, shutting down.");
                break;
            }

            if (!relay_active) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to activate relay: %s", strerror(errno));
                } else {
                    relay_active = 1;
                    log_event(LOG_INFO, "Relay activated (door strike).");
                }
            }

            last_motion_time = current_time;
        } else {
            /* PIR de-energized or no motion */
            if (relay_active) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to deactivate relay: %s", strerror(errno));
                } else {
                    relay_active = 0;
                    log_event(LOG_INFO, "Relay deactivated (motion stopped).");
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown: ensure relay is de-energized and release lines */
    if (relay_active) {
        gpiod_line_set_value(relay_line, 0);
    }

    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    log_event(LOG_INFO, "PIR door monitoring stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    closelog();
    return ret;
}

