#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define TIMER_ID 0
#define TIMER_INTERVAL_SEC 60
#define RELAY_DURATION_SEC 300
#define PAUSE_DURATION_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    syslog(LOG_INFO, "Timer fired, activating relays");

    if (gpioWrite(RELAY1_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write to relay1 pin");
        return;
    }
    if (gpioWrite(RELAY2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write to relay2 pin");
        gpioWrite(RELAY1_PIN, 1);
        return;
    }
    if (gpioWrite(RELAY3_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write to relay3 pin");
        gpioWrite(RELAY1_PIN, 1);
        gpioWrite(RELAY2_PIN, 1);
        return;
    }
    if (gpioWrite(RELAY4_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write to relay4 pin");
        gpioWrite(RELAY1_PIN, 1);
        gpioWrite(RELAY2_PIN, 1);
        gpioWrite(RELAY3_PIN, 1);
        return;
    }

    syslog(LOG_INFO, "Relays activated");

    for (int i = 0; i < RELAY_DURATION_SEC / TIMER_INTERVAL_SEC && running; i++) {
        sleep(TIMER_INTERVAL_SEC);
    }

    if (!running) {
        syslog(LOG_INFO, "Interrupted during relay activation");
        return;
    }

    if (gpioWrite(RELAY1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to write to relay1 pin");
        return;
    }
    if (gpioWrite(RELAY2_PIN, 1) != 0) {
