        gpioWrite(RELAY1_PIN, 1);
        return;
    }
    if (gpioWrite(RELAY3_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to write to relay3 pin");
        gpioWrite(RELAY1_PIN, 1);
        gpioWrite(RELAY2_PIN, 1);
        return;
    }
    if (gpioWrite(RELAY4_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to write to relay4 pin");
        gpioWrite(RELAY1_PIN, 1);
        gpioWrite(RELAY2_PIN, 1);
        gpioWrite(RELAY3_PIN, 1);
        return;
    }

    syslog(LOG_INFO, "Relays deactivated");

    for (int i = 0; i < PAUSE_DURATION_SEC / TIMER_INTERVAL_SEC && running; i++) {
        sleep(TIMER_INTERVAL_SEC);
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
