        syslog(LOG_ERR, "Failed to set relay2 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay3 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay4 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to initialize relay1 pin to HIGH");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY2_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to initialize relay2 pin to HIGH");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY3_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to initialize relay3 pin to HIGH");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY4_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to initialize relay4 pin to HIGH");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL_SEC, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started");

    while (running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");

    gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL_SEC, NULL, NULL);

    if (gpioWrite(RELAY1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay1 pin");
    }
    if (gpioWrite(RELAY2_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay2 pin");
    }
    if (gpioWrite(RELAY3_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay3 pin");
    }
    if (gpioWrite(RELAY4_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay4 pin");
    }

    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

