/*
 * MPU6050 Acceleration Sampler for Raspberry Pi 4 Model B
 * Uses the Linux kernel driver interface (/sys/kernel/mpu6050_accel/latest)
 * to sample acceleration data at a steady 100 Hz.
 *
 * Build: gcc -O2 -Wall -Wextra -o mpu6050_sampler mpu6050_sampler.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define ACCEL_SCALE    16384.0f   /* +/- 2g range */
#define SAMPLE_PERIOD_NS 100000000L  /* 100 Hz */

#define ACCEL_PATH     "/sys/kernel/mpu6050_accel/latest"
#define ACCEL_BUF_SIZE 1024

/* MPU6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an MPU6050 register */
static int mpu6050_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an MPU6050 register */
static int mpu6050_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read 6 bytes starting at ACCEL_XOUT_H (0x3B) and store as raw 16-bit values */
static int mpu6050_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){ MPU6050_REG_ACCEL_XOUT_H }, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x3B) failed: %s\n",
                strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read 6 bytes from ACCEL failed: %s\n",
                strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Read the latest acceleration sample from the driver library */
static int read_accel_from_driver(int16_t *x, int16_t *y, int16_t *z)
{
    FILE *fp = fopen(ACCEL_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", ACCEL_PATH, strerror(errno));
        return -1;
    }

    char line[ACCEL_BUF_SIZE];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Failed to read from %s: %s\n", ACCEL_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Expected format: "x=12345,y=67890,z=34567" */
    char *endptr = NULL;
    long rx = strtol(line, &endptr, 10);
    long ry = strtol(endptr + 2, &endptr, 10);
    long rz = strtol(endptr + 2, &endptr, 10);

    if (endptr == line || *endptr != '\0') {
        fprintf(stderr, "Invalid format in %s\n", ACCEL_PATH);
        return -1;
    }

    *x = (int16_t)rx;
    *y = (int16_t)ry;
    *z = (int16_t)rz;
    return 0;
}

/* Circular buffer structure */
typedef struct {
    int16_t x[ACCEL_BUF_SIZE];
    int16_t y[ACCEL_BUF_SIZE];
    int16_t z[ACCEL_BUF_SIZE];
    int head;
    int count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, int16_t x, int16_t y, int16_t z)
{
    cb->x[cb->head] = x;
    cb->y[cb->head] = y;
    cb->z[cb->head] = z;
    cb->head = (cb->head + 1) % ACCEL_BUF_SIZE;
    if (cb->count < ACCEL_BUF_SIZE)
        cb->count++;
}

/* Signal handler for the timer */
static void timer_handler(int sig, siginfo_t *si, void *uc)
{
    (void)sig;
    (void)si;
    (void)uc;

    int16_t x, y, z;

    if (read_accel_from_driver(&x, &y, &z) == 0) {
        cb_add(&g_cb, x, y, z);
    } else {
        /* Fallback: read from MPU6050 */
        if (mpu6050_read_accel(g_i2c_fd, &x, &y, &z) == 0) {
            cb_add(&g_cb, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data; using zeros.\n");
            cb_add(&g_cb, 0, 0, 0);
        }
    }
}

int main(void)
{
    int i2c_fd = -1;
    struct sigaction sa;
    struct sigevent sev;
    struct itimerspec its;
    CircularBuffer g_cb;

    /* Initialize circular buffer */
    cb_init(&g_cb);

    /* Set up signal handlers for clean shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading WHO_AM_I register */
    uint8_t whoami = 0;
    if (mpu6050_read_reg(i2c_fd, MPU6050_REG_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "MPU6050 not detected at address 0x%02X.\n", MPU6050_ADDR);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    printf("MPU6050 detected (WHO_AM_I = 0x%02X).\n", whoami);

    /* Configure MPU6050: sample rate divider = 7 (1 kHz / (1 + 7)) = 125 Hz */
    if (mpu6050_write_reg(i2c_fd, MPU6050_REG_SMPLRT_DIV, 7) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* DLPF_CFG = 0 (no delay) */
    if (mpu6050_write_reg(i2c_fd, MPU6050_REG_CONFIG, 0x00) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Gyro full scale range = 250 deg/s */
    if (mpu6050_write_reg(i2c_fd, MPU6050_REG_GYRO_CONFIG, 0x00) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Accel full scale range = +/- 2g */
    if (mpu6050_write_reg(i2c_fd, MPU6050_REG_ACCEL_CONFIG, 0x00) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the timer */
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &sev;

    if (timer_create(CLOCK_MONOTONIC, &sev, &its.it_timer) == -1) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;

    if (timer_settime(its.it_timer, 0, &its, NULL) == -1) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        timer_delete(its.it_timer);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Sampling at 100 Hz. Press Ctrl+C to stop.\n");

    /* Main loop: wait for timer signal */
    while (g_running) {
        pause();
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    timer_delete(its.it_timer);
    close(i2c_fd);

    printf("Data saved to %s\n", ACCEL_PATH);
    return EXIT_SUCCESS;
}

