#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define NUM_RELAYS 4
#define INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int pin, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO%d to %d: %s\n", pin, state, strerror(errno));
        return -1;
    }
    return 0;
}

static int toggle_relay(struct gpiod_line *line, int pin) {
    int current = gpiod_line_get_value(line);
    if (current < 0) {
        fprintf(stderr, "Error reading GPIO%d: %s\n", pin, strerror(errno));
        return -1;
    }
    return set_relay(line, pin, !current);
}

static int toggle_all_relays(struct gpiod_line *lines[NUM_RELAYS], int pins[NUM_RELAYS]) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (toggle_relay(lines[i], pins[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

static int sleep_interval(int seconds) {
    struct timespec ts = {
        .tv_sec = seconds,
        .tv_nsec = 0
    };
    while (nanosleep(&ts, &ts) < 0 && errno == EINTR && running) {
        /* Retry on interruption */
    }
    return (errno == EINTR) ? -1 : 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS] = {NULL};
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Raspberry Pi 3 Model B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get and request each relay line as output, initially low */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO%d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "relay-toggle", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO%d as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (toggle_all_relays(lines, pins) < 0) {
            fprintf(stderr, "Error toggling relays. Exiting.\n");
            goto cleanup;
        }

        if (sleep_interval(INTERVAL_SEC) < 0) {
            if (!running) {
                break;
            }
            fprintf(stderr, "Error sleeping. Exiting.\n");
            goto cleanup;
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure all relays are off before releasing resources */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

