#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define RELAY_DURATION_US 3000000 /* 3 seconds */
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: Sound event detected!\n", timestamp) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sound sensor pin as input */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially low */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    int relay_active = 0;
    uint32_t last_trigger_tick = 0;

    while (running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);
        if (sound_detected < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_detected == 1) {
            uint32_t now = gpioTick();

            /* Debounce: ignore triggers within 100 ms of the last one */
            if (now - last_trigger_tick < 100000) {
                continue;
            }
            last_trigger_tick = now;

            /* Cooldown: prevent retriggering while relay is active */
            if (relay_active) {
                continue;
            }

            /* Activate relay */
            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate relay on GPIO%d\n", RELAY_PIN);
                break;
            }
            relay_active = 1;

            printf("Sound event detected! Activating relay for 3 seconds.\n");

            /* Wait for relay duration, checking running flag every 100 ms */
            uint32_t start_tick = gpioTick();
            while (running && (gpioTick() - start_tick) < RELAY_DURATION_US) {
                gpioDelay(POLL_INTERVAL_US);
            }

            /* Deactivate relay */
            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay on GPIO%d\n", RELAY_PIN);
                break;
            }
            relay_active = 0;

            /* Log the event */
            if (log_event(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");

    return EXIT_SUCCESS;
}

