#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43

// Circular Buffer Size
#define BUFFER_SIZE 100

// Angular Velocity Threshold
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Global Variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular Buffer Structure
typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function Prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_angular_velocity(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void add_to_circular_buffer(CircularBuffer *buffer, float data);
void check_threshold(CircularBuffer *buffer, float threshold);
void signal_handler(int signal);
void cleanup(void);

// Circular Buffer Initialization
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Signal Handler for Graceful Shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup Function
void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// I2C Initialization Function
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// MPU-6050 Initialization Function
int init_mpu6050(void) {
    uint8_t buffer[2];

    // Wake up the MPU-6050 (clear sleep bit)
    buffer[0] = PWR_MGMT_1;
    buffer[1] = 0x00;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1 register");
        return -1;
    }
    usleep(100000); // Wait 100ms for the sensor to stabilize

    return 0;
}

// Function to Read Gyroscope Data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[6];

    // Read 6 bytes of data starting from GYRO_XOUT_H (0x43)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes (little-endian)
    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to Calculate Angular Velocity
float calculate_angular_velocity(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    // Convert raw data to degrees per second (Sensitivity: 131 LSB/degree/second)
    float x_rate = (float)gyro_x / 131.0;
    float y_rate = (float)gyro_y / 131.0;
    float z_rate = (float)gyro_z / 131.0;

    // Calculate the magnitude of the angular velocity vector
    float magnitude = sqrt(x_rate * x_rate + y_rate * y_rate + z_rate * z_rate);

    return magnitude;
}

// Function to Add Data to the Circular Buffer
void add_to_circular_buffer(CircularBuffer *buffer, float data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to Check the Angular Velocity Threshold
void check_threshold(CircularBuffer *buffer, float threshold) {
    if (buffer->count == BUFFER_SIZE) {
        // Calculate the average angular velocity
        float sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer->data[i];
        }
        float average = sum / BUFFER_SIZE;

        // Check if the average angular velocity exceeds the threshold
        if (fabs(average) > threshold) {
            printf("Threshold exceeded! Average Angular Velocity: %.2f degrees/second\n", average);
        }
    }
}

int main(void) {
    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Create Circular Buffer
    CircularBuffer gyro_buffer;
    init_circular_buffer(&gyro_buffer);

    // Main Loop
    int16_t gyro_x, gyro_y, gyro_z;
    float angular_velocity;

    while (program_running) {
        // Read Gyroscope Data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate Angular Velocity
            angular_velocity = calculate_angular_velocity(gyro_x, gyro_y, gyro_z);

            // Add Data to the Circular Buffer
            add_to_circular_buffer(&gyro_buffer, angular_velocity);

            // Check the Angular Velocity Threshold
            check_threshold(&gyro_buffer, ANGULAR_VELOCITY_THRESHOLD);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        usleep(10000); // Delay for 10ms (100Hz sampling rate)
    }

    // Cleanup
    cleanup();

    return 0;
}

