/*
 * CO2 Monitor for Raspberry Pi 3 Model B+
 * Sensor: MH-Z19B via UART (9600 baud, TXD=GPIO14, RXD=GPIO15)
 * API:   Writes JSON objects to co2_log.json and co2_error.log
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/ioctl.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_TIMEOUT_MS  1000
#define SAMPLE_INTERVAL_S 5
#define RESPONSE_LEN      9
#define CMD_LEN          9

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART setup                                                         */
/* ------------------------------------------------------------------ */
static int uart_init(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag  = CS8 | CLOCAL | CREAD;
    tty.c_iflag  = IGNPAR;
    tty.c_oflag  = 0;
    tty.c_lflag  = 0;
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;  /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes from the UART with timeout                       */
/* ------------------------------------------------------------------ */
static int uart_read_exact(int fd, uint8_t *buf, size_t n, int timeout_ms)
{
    size_t total = 0;
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor disconnected?)\n");
            return -1;
        }
        total += (size_t)r;

        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L +
                          (now.tv_nsec - start.tv_nsec) / 1000000L;
        if (elapsed_ms >= timeout_ms) {
            fprintf(stderr, "read: timeout (%zu/%zu bytes)\n", total, n);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send the 9-byte command sequence to the MH-Z19B                      */
/* ------------------------------------------------------------------ */
static int send_command(int fd)
{
    uint8_t cmd[CMD_LEN] = {
        0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };
    ssize_t w = write(fd, cmd, CMD_LEN);
    if (w != (ssize_t)CMD_LEN) {
        fprintf(stderr, "write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse the 9-byte response: ppm_raw (2 bytes), checksum (1 byte)      */
/* ------------------------------------------------------------------ */
static int parse_response(const uint8_t *buf, uint16_t *ppm_raw)
{
    if (buf[0] != 0x01 || buf[1] != 0x84 || buf[2] != 0x00) {
        fprintf(stderr, "checksum mismatch: 0x%02X 0x%02X 0x%02X\n",
                buf[0], buf[1], buf[2]);
        return -1;
    }
    *ppm_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a JSON object to the log file                                */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint64_t timestamp, uint16_t ppm, int error)
{
    char ts_str[32];
    struct tm tm_info;
    localtime_r(&timestamp, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(fp, "{\"timestamp\": \"%s\", \"ppm\": %u, \"error\": %d}\n",
                ts_str, ppm, error) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append an error message to the error log file                        */
/* ------------------------------------------------------------------ */
static int log_error(FILE *fp, const char *msg)
{
    char ts_str[32];
    struct tm tm_info;
    time_t now = time(NULL);
    localtime_r(&now, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(fp, "{\"timestamp\": \"%s\", \"message\": \"%s\"}\n",
                ts_str, msg) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
