#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define GPIO_PIN 17

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hmc5883l(int handle, double *heading) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error reading HMC5883L data block\n");
        return -1;
    }
    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t y = (int16_t)((buf[4] << 8) | buf[5]);
    *heading = atan2((double)y, (double)x) * 180.0 / M_PI;
    return 0;
}

static void compensate_heading(double raw_heading, double *compensated_heading) {
    *compensated_heading = raw_heading - 90.0;
    if (*compensated_heading < 0.0) *compensated_heading += 360.0;
    if (*compensated_heading > 360.0) *compensated_heading -= 360.0;
}

static void add_to_buffer(double heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_deviation(double compensated_heading) {
    double deviation = fabs(compensated_heading - TARGET_HEADING);
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L CONFIG_A\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to HMC5883L CONFIG_B\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L MODE\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HMC5883L heading monitor started. Target: %.1f degrees, Threshold: %.1f degrees\n",
           TARGET_HEADING, DEVIATION_THRESHOLD);

    while (running) {
        double raw_heading;
        if (read_hmc5883l(i2c_handle, &raw_heading) == 0) {
            double compensated_heading;
            compensate_heading(raw_heading, &compensated_heading);
            add_to_buffer(compensated_heading);
            check_deviation(compensated_heading);
            printf("Raw: %.2f, Compensated: %.2f, Deviation: %.2f\n",
                   raw_heading, compensated_heading, fabs(compensated_heading - TARGET_HEADING));
        } else {
            fprintf(stderr, "Failed to read heading, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

