#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 255

#define DISTANCE_THRESHOLD 50.0
#define MIN_DISTANCE 10.0
#define MAX_DISTANCE 100.0
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int in1, int in2, int in3, int in4, int duty_cycle) {
    if (duty_cycle < PWM_DUTY_CYCLE_MIN) duty_cycle = PWM_DUTY_CYCLE_MIN;
    if (duty_cycle > PWM_DUTY_CYCLE_MAX) duty_cycle = PWM_DUTY_CYCLE_MAX;

    if (gpioPWM(in1, duty_cycle) < 0) return -1;
    if (gpioPWM(in2, 0) < 0) return -1;
    if (gpioPWM(in3, duty_cycle) < 0) return -1;
    if (gpioPWM(in4, 0) < 0) return -1;
    return 0;
}

static int set_motor_stop(int in1, int in2, int in3, int in4) {
    if (gpioPWM(in1, 0) < 0) return -1;
    if (gpioPWM(in2, 0) < 0) return -1;
    if (gpioPWM(in3, 0) < 0) return -1;
    if (gpioPWM(in4, 0) < 0) return -1;
    return 0;
}

static int read_distance(int pin) {
    int distance = gpioRead(pin);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance sensor on GPIO %d\n", pin);
        return -1;
    }
    return distance;
}

static int calculate_pwm_duty_cycle(float distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    float proportion = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    int duty_cycle = (int)(proportion * PWM_DUTY_CYCLE_MAX);
    return duty_cycle;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance_pin> <motor_b_distance_pin>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int motor_a_distance_pin = atoi(argv[1]);
    int motor_b_distance_pin = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_IN1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_IN3);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_A_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR_A_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR_B_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance_a = read_distance(motor_a_distance_pin);
        int distance_b = read_distance(motor_b_distance_pin);

        if (distance_a < 0 || distance_b < 0) {
            fprintf(stderr, "Error reading distance, stopping motors\n");
            set_motor_stop(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int duty_cycle_a = calculate_pwm_duty_cycle(distance_a);
        int duty_cycle_b = calculate_pwm_duty_cycle(distance_b);

        if (distance_a < DISTANCE_THRESHOLD) {
            if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, duty_cycle_a) < 0) {
                fprintf(stderr, "Error setting motor A speed\n");
            }
            if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_A_IN1, MOTOR_A_IN2, duty_cycle_b) < 0) {
                fprintf(stderr, "Error setting motor B speed\n");
            }
        } else {
            if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 0) < 0) {
                fprintf(stderr, "Error stopping motor A\n");
            }
            if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_A_IN1, MOTOR_A_IN2, 0) < 0) {
                fprintf(stderr, "Error stopping motor B\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_motor_stop(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
    printf("Motor control stopped.\n");

    return EXIT_SUCCESS;
}

