            }
        } else {
            if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 0) < 0) {
                fprintf(stderr, "Error stopping motor A\n");
            }
            if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_A_IN1, MOTOR_A_IN2, 0) < 0) {
