    set_motor_stop(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
    printf("Motor control stopped.\n");

    return EXIT_SUCCESS;
}

