#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <math.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Solar panel PWM control
#define PWM_CHIP "/sys/class/pwm/pwmchip2"
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000000L // 1 second
#define PWM_DUTY_NS 500000000L     // 50% duty cycle

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int set_solar_panel_angle(int angle);
int log_data(float pitch, float roll, int angle);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    // Turn off PWM
    FILE *pwm_file = fopen(PWM_CHIP "/pwm0/enable", "w");
    if (pwm_file != NULL) {
        fprintf(pwm_file, "0");
        fclose(pwm_file);
    }
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize MPU-6050 sensor
int init_mpu6050(void) {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); // Wait 100ms for sensor to stabilize

    return 0;
}

// Read raw accelerometer and gyroscope data from MPU-6050
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buf[14];
    if (read(i2c_fd, buf, 14) != 14) {
        fprintf(stderr, "Failed to read MPU-6050 data: %s\n", strerror(errno));
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Calculate pitch angle from accelerometer data
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    // Convert raw accelerometer data to g-force units
    float accel_x_g = (float)accel_x / 16384.0f;
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    // Calculate pitch angle using atan2 function
    float pitch = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;

    return pitch;
}

// Calculate roll angle from accelerometer data
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    // Convert raw accelerometer data to g-force units
    float accel_x_g = (float)accel_x / 16384.0f;
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    // Calculate roll angle using atan2 function
    float roll = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;

    return roll;
}

// Set solar panel angle using PWM
int set_solar_panel_angle(int angle) {
    // Validate angle value
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle value: %d\n", angle);
        return -1;
    }

    // Calculate duty cycle based on angle
    long duty_ns = (long)((float)angle / 180.0f * PWM_DUTY_NS);

    // Open PWM control file
    FILE *pwm_file = fopen(PWM_CHIP "/pwm0/duty_cycle", "w");
    if (pwm_file == NULL) {
        fprintf(stderr, "Failed to open PWM duty cycle file: %s\n", strerror(errno));
        return -1;
    }

    // Write duty cycle to file
    if (fprintf(pwm_file, "%ld", duty_ns) < 0) {
        fprintf(stderr, "Failed to write to PWM duty cycle file: %s\n", strerror(errno));
        fclose(pwm_file);
        return -1;
    }

    fclose(pwm_file);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, angle) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    fclose(log_file);
    log_file = NULL;

    return 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Set PWM chip and channel
    FILE *pwm_export = fopen(PWM_CHIP "/export", "w");
    if (pwm_export == NULL) {
        fprintf(stderr, "Failed to export PWM channel: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (fprintf(pwm_export, "%d", PWM_CHANNEL) < 0) {
        fprintf(stderr, "Failed to write to PWM export file: %s\n", strerror(errno));
        fclose(pwm_export);
        cleanup();
        return 1;
    }

    fclose(pwm_export);

    // Set PWM period
    FILE *pwm_period = fopen(PWM_CHIP "/pwm0/period", "w");
    if (pwm_period == NULL) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (fprintf(pwm_period, "%ld", PWM_PERIOD_NS) < 0) {
        fprintf(stderr, "Failed to write to PWM period file: %s\n", strerror(errno));
        fclose(pwm_period);
        cleanup();
        return 1;
    }

    fclose(pwm_period);

    // Enable PWM
    FILE *pwm_enable = fopen(PWM_CHIP "/pwm0/enable", "w");
    if (pwm_enable == NULL) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (fprintf(pwm_enable, "1") < 0) {
        fprintf(stderr, "Failed to write to PWM enable file: %s\n", strerror(errno));
        fclose(pwm_enable);
        cleanup();
        return 1;
    }

    fclose(pwm_enable);

    // Main loop
    while (program_running) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
        float pitch, roll;
        int angle;

        // Read sensor data with exponential backoff
        int retries = 3;
        int success = 0;
        while (retries > 0 && !success) {
            if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
                success = 1;
            } else {
                retries--;
                if (retries > 0) {
                    usleep(100000); // Wait 100ms before retrying
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
            continue;
        }

        // Calculate pitch and roll angles
        pitch = calculate_pitch(accel_x, accel_y, accel_z);
        roll = calculate_roll(accel_x, accel_y, accel_z);

        // Set solar panel angle based on pitch and roll angles
        angle = (int)(pitch + roll);
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;

        if (set_solar_panel_angle(angle) != 0) {
            fprintf(stderr, "Failed to set solar panel angle.\n");
        }

        // Log data
        if (log_data(pitch, roll, angle) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        usleep(100000); // Delay for 100ms
    }

    // Cleanup
    cleanup();

    return 0;
}

