float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    // Convert raw accelerometer data to g-force units
    float accel_x_g = (float)accel_x / 16384.0f;
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    // Calculate pitch angle using atan2 function
    float pitch = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;

    return pitch;
}

// Calculate roll angle from accelerometer data
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    // Convert raw accelerometer data to g-force units
    float accel_x_g = (float)accel_x / 16384.0f;
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    // Calculate roll angle using atan2 function
    float roll = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;

    return roll;
}

// Set solar panel angle using PWM
int set_solar_panel_angle(int angle) {
    // Validate angle value
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle value: %d\n", angle);
        return -1;
    }

    // Calculate duty cycle based on angle
    long duty_ns = (long)((float)angle / 180.0f * PWM_DUTY_NS);

    // Open PWM control file
    FILE *pwm_file = fopen(PWM_CHIP "/pwm0/duty_cycle", "w");
    if (pwm_file == NULL) {
        fprintf(stderr, "Failed to open PWM duty cycle file: %s\n", strerror(errno));
        return -1;
    }

    // Write duty cycle to file
    if (fprintf(pwm_file, "%ld", duty_ns) < 0) {
        fprintf(stderr, "Failed to write to PWM duty cycle file: %s\n", strerror(errno));
        fclose(pwm_file);
        return -1;
    }

    fclose(pwm_file);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, angle) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    fclose(log_file);
    log_file = NULL;

    return 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
