#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define FADE_DURATION_MS 1800000
#define PWM_RANGE 100
#define PWM_STEP_DELAY_US 10000

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) != PWM_FREQUENCY) {
            fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != PWM_RANGE) {
            fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: Failed to initialize PWM on GPIO %d to 0.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static int read_schedule_file(const char *filename, int *schedule_data) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int line_number = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        line_number++;

        if (line_number > NUM_RELAYS) {
            fprintf(stderr, "Warning: Schedule file contains more than %d lines. Skipping extra lines.\n", NUM_RELAYS);
            break;
        }

        char *token = strtok(line, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Invalid format in schedule file on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        char *endptr;
        long hour = strtol(token, &endptr, 10);
        if (endptr == token || *endptr != ':' || hour < 0 || hour > 23) {
            fprintf(stderr, "Error: Invalid hour value on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Invalid format in schedule file on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        long minute = strtol(token, &endptr, 10);
        if (endptr == token || *endptr != ':' || minute < 0 || minute > 59) {
            fprintf(stderr, "Error: Invalid minute value on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Invalid format in schedule file on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        long relay_number = strtol(token, &endptr, 10);
        if (endptr == token || relay_number < 1 || relay_number > NUM_RELAYS) {
            fprintf(stderr, "Error: Invalid relay number on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Invalid format in schedule file on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        int on_off = strtol(token, &endptr, 10);
        if (endptr == token || on_off != 0 && on_off != 1) {
            fprintf(stderr, "Error: Invalid on/off value on line %d.\n", line_number);
            fclose(fp);
            return -1;
        }

        schedule_data[line_number - 1] = (int)(on_off * 100);
    }

    fclose(fp);
    return 0;
}

static int set_relay_state(int relay_number, int state) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) {
        fprintf(stderr, "Error: Invalid relay number %d.\n", relay_number);
        return -1;
    }
    if (state != 0 && state != 1) {
        fprintf(stderr, "Error: Invalid state %d for relay %d.\n", state, relay_number);
        return -1;
    }

    if (gpioPWM(relay_pins[relay_number - 1], state) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d to %d.\n", relay_pins[relay_number - 1], state);
        return -1;
    }
    return 0;
}

static int calculate_fade_step(int current_state, int target_state, int step_size) {
    if (current_state == target_state) {
        return 0;
    }
    if (current_state > target_state) {
        return -step_size;
    }
    return step_size;
}

static void perform_fade(int relay_number, int target_state) {
    int current_state = gpioGetPWMdutycycle(relay_pins[relay_number - 1]);
    if (current_state < 0) {
        fprintf(stderr, "Error: Failed to read current PWM duty cycle on GPIO %d.\n", relay_pins[relay_number - 1]);
        return;
    }

    int step_size = (target_state > current_state) ? 1 : -1;
    int fade_steps = (target_state > current_state) ? (target_state - current_state) : (current_state - target_state);

    for (int i = 0; i < fade_steps && program_running; i++) {
        current_state += step_size;
        if (current_state < 0) current_state = 0;
        if (current_state > PWM_RANGE) current_state = PWM_RANGE;

        if (gpioPWM(relay_pins[relay_number - 1], current_state) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", relay_pins[relay_number - 1]);
            return;
        }

        gpioDelay(PWM_STEP_DELAY_US);
    }

    if (set_relay_state(relay_number, target_state) != 0) {
        fprintf(stderr, "Error: Failed to set relay %d to target state %d.\n", relay_number, target_state);
    }
}

static void check_schedule(int *schedule_data) {
    time_t rawtime;
    struct tm *timeinfo;
    int current_hour, current_minute;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }

    current_hour = timeinfo->tm_hour;
    current_minute = timeinfo->tm_min;

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (schedule_data[i] != 0) {
            int target_state = (schedule_data[i] == 100) ? 1 : 0;
            int current_state = gpioGetPWMdutycycle(relay_pins[i]);

            if (current_state < 0) {
                fprintf(stderr, "Error: Failed to read current PWM duty cycle on GPIO %d.\n", relay_pins[i]);
                continue;
            }

            if (current_state != target_state) {
                perform_fade(i + 1, target_state);
            }
        }
    }
}

int main(void) {
    int schedule_data[NUM_RELAYS];

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (read_schedule_file("lighting_schedule.txt", schedule_data) != 0) {
        fprintf(stderr, "Error: Failed to read schedule file. Using default schedule.\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            schedule_data[i] = 0;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        check_schedule(schedule_data);
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");

    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(i + 1, 0);
    }

    gpioTerminate();
    printf("Smart Home Lighting System stopped.\n");

    return EXIT_SUCCESS;
}

