#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize BUZZER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
        return -1;
    }
    return 0;
}

static int read_echo_pulse(uint32_t *start_tick, uint32_t *end_tick) {
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or not responding).\n");
            return -1;
        }
    }

    *start_tick = gpioTick();

    timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout (sensor stuck high).\n");
            return -1;
        }
    }

    *end_tick = gpioTick();

    return 0;
}

static float calculate_distance(uint32_t start_tick, uint32_t end_tick) {
    uint32_t pulse_us = end_tick - start_tick;
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static int map_distance_to_frequency(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float normalized = (distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int frequency = (int)(MIN_FREQUENCY_HZ + normalized * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));

    if (frequency < MIN_FREQUENCY_HZ) frequency = MIN_FREQUENCY_HZ;
    if (frequency > MAX_FREQUENCY_HZ) frequency = MAX_FREQUENCY_HZ;

    return frequency;
}

static int set_buzzer_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY_HZ || frequency > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Warning: frequency %d Hz out of valid range [%d, %d].\n",
                frequency, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
        return -1;
    }

    int period_us = 1000000 / frequency;
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency %d Hz.\n", frequency);
        return -1;
    }
    if (gpioSetPWMrange(BUZZER_PIN, period_us) != 0) {
        fprintf(stderr, "Error: failed to set PWM range %d us.\n", period_us);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, period_us / 2) != 0) {
        fprintf(stderr, "Error: failed to start PWM on BUZZER_PIN.\n");
        return -1;
    }
    return 0;
}

static void stop_buzzer(void) {
    gpioPWM(BUZZER_PIN, 0);
}

static void cleanup(void) {
    stop_buzzer();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t start_tick, end_tick;

        if (trigger_sensor() != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (read_echo_pulse(&start_tick, &end_tick) != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = calculate_distance(start_tick, end_tick);
        int frequency = map_distance_to_frequency(distance);

        if (set_buzzer_frequency(frequency) != 0) {
            fprintf(stderr, "Error: failed to set buzzer frequency.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

