#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) goto fail;
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) goto fail;
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) goto fail;

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0) goto fail;
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) goto fail;
    if (gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) goto fail;

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) goto fail;
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) goto fail;
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) goto fail;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto fail;
    }

    while (running) {
        double t = (double)clock() / CLOCKS_PER_SEC;
        double v = 0.5 + 0.5 * sin(2.0 * M_PI * t);
        int r = (int)(v * 255.0);
        int g = (int)(v * 255.0);
        int b = (int)(v * 255.0);
        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Warning: failed to set LED color.\n");
        }
        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;

fail:
    cleanup();
    return EXIT_FAILURE;
}

