    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data, continuing...\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

