/*
 * SW‑420 Vibration Sensor Monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SW‑420 VCC  -> 3.3 V (Pin 1)
 *   SW‑420 GND  -> GND  (Pin 9)
 *   SW‑420 OUT  -> GPIO17 (BCM, Pin 11)
 *
 * The SW‑420 module outputs HIGH when a vibration event is detected.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vibration_monitor vibration_monitor.c -lgpiod
 *
 * Run:
 *   ./vibration_monitor [poll_timeout_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17          /* BCM 17, physical pin 11 */
#define LOG_FILE_NAME       "vibration_events.log"
#define DEFAULT_POLL_MS    1000
#define WINDOW_SIZE         5
#define EARTHQUAKE_THRESHOLD 3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *fp, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Vibration: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) == EOF) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(fileno(fp)) == -1) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int poll_timeout_ms = DEFAULT_POLL_MS;
    int ret = EXIT_FAILURE;

    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Request the GPIO line for both rising and falling edge events.
     * The SW‑420 module drives the line HIGH when a vibration event
     * is detected.  We use the libgpiod API to read the line value
     * and act on the event.  The SW‑420 module has a built-in pull-up
     * so the line reads HIGH when idle and LOW when a vibration
     * event is detected.  We request both rising and falling edges
     * so we can detect both rising and falling edges.
     */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup_log;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* Request both rising and falling edge events */
    if (gpiod_line_request_both_edges_events(line, "vibration_monitor") < 0) {
        fprintf(stderr, "Error requesting edge events on GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    printf("Monitoring SW‑420 vibration sensor on GPIO%d (poll %d ms).\n",
           GPIO_LINE_OFFSET, poll_timeout_ms);
    printf("Press Ctrl+C to exit.\n");

    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;
    int last_value = -1;   /* force initial read */

    while (g_running) {
        /*
         * gpiod_line_event_wait blocks up to poll_timeout_ms.
         * If the event is ready, it returns 0; if the timeout elapses,
         * it returns -1; if an error occurs, it returns -1.
         */
        int event_ret = gpiod_line_event_wait(line,
            (struct timespec){ .tv_sec = poll_timeout_ms / 1000,
                              .tv_nsec = (poll_timeout_ms % 1000) * 1000000L });

        if (event_ret < 0) {
            if (errno == EINTR) {
                continue;   /* interrupted by signal */
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n",
                    strerror(errno));
            break;
        }

        if (event_ret == 0) {
            /* Timeout — no event within poll_timeout_ms */
            continue;
        }

        /* Event detected — read it to confirm */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n",
                    strerror(errno));
            break;
        }

        int value = event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;

        /* Update sliding window */
        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_count < WINDOW_SIZE) {
            window_count++;
        }

        /* Detect earthquake: 3 or more HIGH events in the window */
        if (window_count >= EARTHQUAKE_THRESHOLD &&
            (value == 1 && last_value == 1)) {
            printf("EARTHQUAKE ALERT!\n");
            fflush(stdout);

            if (log_event(fp, value) != 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            }
        }

        last_value = value;
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);
cleanup_log:
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }

    return ret;
}

