/*
 * LSM303DLHC Magnetometer Compass Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (physical pin 3, I2C bus 1)
 *   LSM303DLHC SCL -> GPIO3 (physical pin 5, I2C bus 1)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build: gcc -O2 -Wall -o mag_compass mag_compass.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303_ADDR    0x1D          /* 7-bit I2C address (SA0 tied to GND) */

/* LSM303DLHC register addresses */
#define LSM303_CTRL_REG1 0x20
#define LSM303_CTRL_REG4 0x23
#define LSM303_OUT_X_L   0x28

/* Hard-iron calibration offsets (example values; replace with your calibration data) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

/* Sensitivity scale factor for +/- 2 gauss range (1 mg/LSB) */
#define SENSITIVITY 0.001f

/* Sampling interval in microseconds (1 second) */
#define SAMPLE_INTERVAL_US 1000000

/* Global resources for signal-handler cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd of %zu)\n",
                reg, strerror(errno), n, sizeof(buf));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303DLHC magnetometer                                             */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];

    /*
     * LSM303DLHC magnetometer outputs 6 bytes in a single burst read.
     * The first two bytes are the X-axis data (little-endian), the
     * next two bytes are the Y-axis data, and the last two bytes are
     * the Z-axis data.
     */
    if (i2c_read_burst(fd, LSM303_OUT_X_L | 0x80, buf, sizeof(buf)) != 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /*
     * LSM303DLHC magnetometer outputs +/- 2 gauss range.
     * The raw data is in LSB units.  To convert to g, we divide by
     * the sensitivity scale factor.
     */
    *x = (float)raw_x * SENSITIVITY;
    *y = (float)raw_y * SENSITIVITY;
    *z = (float)raw_z * SENSITIVITY;

    /*
     * LSM303DLHC magnetometer outputs data in a right-justified
     * 16-bit two's complement format.  If the data is negative,
     * we need to sign-extend it to 32 bits.
     */
    if (*x < 0.0f) {
        *x += 65536.0f;
    }
    if (*y < 0.0f) {
        *y += 65536.0f;
    }
    if (*z < 0.0f) {
        *z += 65536.0f;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compass direction mapping                                            */
/* ------------------------------------------------------------------ */
static const char *compass_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f) {
        return "N";
    } else if (heading >= 22.5f && heading < 67.5f) {
        return "NE";
    } else if (heading >= 67.5f && heading < 112.5f) {
        return "E";
    } else if (heading >= 112.5f && heading < 157.5f) {
        return "SE";
    } else if (heading >= 157.5f && heading < 202.5f) {
        return "S";
    } else if (heading >= 202.5f && heading < 247.5f) {
        return "SW";
    } else if (heading >= 247.5f && heading < 292.5f) {
        return "W";
    } else {
        return "NW";
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z, float heading)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

