        fprintf(stderr, "Error initializing relay pin %d to OFF\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioWrite(RELAY_PIN, 0);

    if (log_relay_state(0) != 0) {
        fprintf(stderr, "Warning: failed to log final relay state\n");
    }

    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

