/*
 * watering.c — Raspberry Pi Zero W automated plant watering system
 *
 * Hardware:
 *   - Two SG90 servo motors (valve on GPIO17, nozzle on GPIO18)
 *   - Valve servo: physical pin 11 (BCM), pulse width 90 degrees (1500 us)
 *   - Nozzle servo: physical pin 12 (BCM), pulse width 0 degrees (500 us)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lthe driver library -lrt
 *
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#include <the/servo.h>

/* ----------------------------- Configuration ----------------------------- */

#define VALVE_SERVO_PIN      17
#define NOZZLE_SERVO_PIN     18

#define VALVE_OPEN_PULSE_US  1500   /* 90 degrees */
#define VALVE_CLOSE_PULSE_US 500    /* 0 degrees   */

#define NOZZLE_MIN_PULSE_US  500    /* 0 degrees   */
#define NOZZLE_MAX_PULSE_US  2500   /* 180 degrees */

#define MOISTURE_THRESHOLD  50

#define SERVO_OPEN_DELAY_S  2
#define SERVO_HOLD_S        5
#define SERVO_SETTLE_S       2
#define SERVO_SETTLE_US      100000 /* 100 ms */

#define LOOP_DELAY_S        1
#define MAX_RETRIES         3
#define RETRY_DELAY_US      100000 /* 100 ms */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }
}

/* --------------------------- Servo helpers ----------------------------- */

/*
 * Open the valve servo.
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    int rc = servo_set_pulse_width(VALVE_SERVO_PIN, VALVE_OPEN_PULSE_US);
    if (rc != 0) {
        fprintf(stderr, "Error: servo_set_pulse_width(valve, %d) failed: %s\n",
                VALVE_OPEN_PULSE_US, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Close the valve servo.
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    int rc = servo_set_pulse_width(VALVE_SERVO_PIN, VALVE_CLOSE_PULSE_US);
    if (rc != 0) {
        fprintf(stderr, "Error: servo_set_pulse_width(valve, %d) failed: %s\n",
                VALVE_CLOSE_PULSE_US, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Set the nozzle servo to the given angle (0–180).
 * Returns 0 on success, -1 on failure.
 */
static int set_nozzle_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: invalid nozzle angle %d (must be 0–180)\n", angle);
        return -1;
    }

    int pulse_us = NOZZLE_MIN_PULSE_US +
                   (int)((float)angle / 180.0f * (float)(NOZZLE_MAX_PULSE_US - NOZZLE_MIN_PULSE_US));

    int rc = servo_set_pulse_width(NOZZLE_SERVO_PIN, pulse_us);
    if (rc != 0) {
        fprintf(stderr, "Error: servo_set_pulse_width(nozzle, %d) failed: %s\n",
                pulse_us, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Stop the servo by setting the pulse width to 0.
 * Returns 0 on success, -1 on failure.
 */
static int stop_servo(void)
{
    int rc = servo_set_pulse_width(NOZZLE_SERVO_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "Error: servo_set_pulse_width(nozzle, 0) failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Watering cycle ----------------------------- */

static void water_plant(void)
{
    printf("Watering plant...\n");

    if (open_valve() != 0) {
        fprintf(stderr, "Warning: valve open failed — aborting cycle\n");
        return;
    }

    for (int angle = 0; angle <= 180 && g_running; angle += 45) {
        if (set_nozzle_angle(angle) != 0) {
            fprintf(stderr, "Warning: nozzle position %d failed — skipping step\n", angle);
            continue;
        }

        printf("Nozzle at angle %d°\n", angle);

        /* Hold the spray for SERVO_HOLD_S seconds */
        for (int i = 0; i < SERVO_HOLD_S && g_running; i++) {
            sleep(1);
        }

        if (!g_running) {
            break;
        }
    }

    if (close_valve() != 0) {
        fprintf(stderr, "Warning: valve close failed — critical warning\n");
    }

    printf("Plant watered.\n");
}

/* ------------------------------- Main ----------------------------------- */

int main(void)
{
    install_signal_handlers();

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = 20; /* Simulated soil moisture (0–100) */

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture level low (%d%%). Watering cycle skipped.\n", moisture);
        } else {
            water_plant();
        }

        /*
         * Sleep LOOP_DELAY_S seconds, but wake early on signal.
         * If g_running is cleared, the loop exits cleanly.
         */
        for (int i = 0; i < LOOP_DELAY_S && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown: stop both servos and release resources */
    stop_servo();
    servo_cleanup();

    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

