#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEP_DELAY_US 3000
#define STEPS_PER_ROTATION 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_step(int step) {
    switch (step) {
        case 0: return gpioWrite(IN1, 1) && gpioWrite(IN2, 0) && gpioWrite(IN3, 0) && gpioWrite(IN4, 0);
        case 1: return gpioWrite(IN1, 0) && gpioWrite(IN2, 1) && gpioWrite(IN3, 0) && gpioWrite(IN4, 0);
        case 2: return gpioWrite(IN1, 0) && gpioWrite(IN2, 0) && gpioWrite(IN3, 1) && gpioWrite(IN4, 0);
        case 3: return gpioWrite(IN1, 0) && gpioWrite(IN2, 0) && gpioWrite(IN3, 0) && gpioWrite(IN4, 1);
        default: return -1;
    }
}

static int deenergize_coils(void) {
    return gpioWrite(IN1, 0) && gpioWrite(IN2, 0) && gpioWrite(IN3, 0) && gpioWrite(IN4, 0);
}

static int rotate_motor(int steps, int direction) {
    int step_count = (direction == 1) ? steps : -steps;
    int step = 0;
    int ret;

    for (int i = 0; i < abs(step_count) && running; i++) {
        step += direction;
        if (step > 3) step = 0;
        if (step < 0) step = 3;

        ret = set_step(step);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioWrite failed for step %d\n", step);
            return -1;
        }

        gpioDelay(STEP_DELAY_US);
    }

    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    return rotate_motor(STEPS_PER_ROTATION, 1);
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    return rotate_motor(STEPS_PER_ROTATION, -1);
}

int main(void) {
    int lock_pressed = 0;
    int unlock_pressed = 0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    signal(SIGINT, signal_handler);

    printf("Door control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state == 0 && !lock_pressed) {
            lock_pressed = 1;
            ret = lock_door();
            if (ret != 0) {
                fprintf(stderr, "Error: Failed to lock door\n");
            }
        } else if (lock_state == 1) {
            lock_pressed = 0;
        }

        if (unlock_state == 0 && !unlock_pressed) {
            unlock_pressed = 1;
            ret = unlock_door();
            if (ret != 0) {
                fprintf(stderr, "Error: Failed to unlock door\n");
            }
        } else if (unlock_state == 1) {
            unlock_pressed = 0;
        }

        gpioDelay(10000);
    }

    deenergize_coils();
    gpioTerminate();
    printf("Door control system stopped.\n");
    return EXIT_SUCCESS;
}

