/*
 * VL53L1X Distance Sensor Reader with Relay Control
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: VL53L1X (default I2C address 0x29)
 * Relay:  GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ---- VL53L1X I2C default address ---- */
#define VL53L1X_DEFAULT_ADDR 0x29

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

/* ---- Relay GPIO pin (BCM) ---- */
#define RELAY_GPIO 18

/* ---- Distance threshold (cm) ---- */
#define DISTANCE_THRESHOLD 50.0f

/* ---- Polling interval (microseconds) ---- */
#define POLL_INTERVAL_US 100000

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, do not block in a signal handler  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address (big-endian on the bus)            */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address (big-endian on the bus)            */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    char data_buf[1];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address (big-endian on the bus)            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16_u16(int handle, uint16_t reg, uint16_t *value)
{
    uint8_t lo, hi;

    if (vl53l1x_read_reg16(handle, reg, &lo) != 0)
        return -1;
    if (vl53l1x_read_reg16(handle, reg + 1, &hi) != 0)
        return -1;

    *value = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L1X sensor                                      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from the VL53L1X sensor                              */
/* Returns distance in mm on success, -1 on error.                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint16_t distance;

    /* Check for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    if (vl53l1x_read_reg16_u16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &distance) != 0)
        return -1;

    if ((distance & 0x01) == 0) {
        /* Data not ready yet — wait and retry */
        gpioDelay(10000); /* 10 ms */
        return -1;
    }

    /* Read 16-bit distance value */
    if (vl53l1x_read_reg16_u16(handle, VL53L1X_REG_RESULT_DISTANCE, &distance) != 0)
        return -1;

    return (int)distance;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if resources are already freed */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output, initially LOW */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Open I2C bus 1 at the VL53L1X default address */
    g_i2c_handle = i2cOpen(1, VL53L1X_DEFAULT_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                VL53L1X_DEFAULT_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("VL53L1X distance sensor reader started. Press Ctrl+C to exit.\n");
    printf("Threshold: %.1f cm | Relay GPIO: %d\n", DISTANCE_THRESHOLD, RELAY_GPIO);

    /* Main polling loop */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance <= (int)(DISTANCE_THRESHOLD * 10.0f)) {
                gpioWrite(RELAY_GPIO, 1);
                printf("  Relay ON  (distance <= %.1f cm)\n", DISTANCE_THRESHOLD);
            } else {
                gpioWrite(RELAY_GPIO, 0);
                printf("  Relay OFF (distance > %.1f cm)\n", DISTANCE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "[ERROR] Failed to read distance from VL53L1X\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

