#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define POLL_INTERVAL_SEC 60
#define WATERING_DURATION_SEC 5
#define CYCLE_DURATION_SEC 86400

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static const char *log_file = "watering_log.txt";

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_watering_cycle(void) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", log_file, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time to local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering-system", 1) < 0) {
            fprintf(stderr, "Error requesting GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    time_t last_cycle_start = 0;

    while (program_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            break;
        }

        if (last_cycle_start == 0 || difftime(now, last_cycle_start) >= CYCLE_DURATION_SEC) {
            printf("Starting watering cycle...\n");

            for (int i = 0; i < NUM_RELAYS; i++) {
                if (gpiod_line_set_value(lines[i], 0) < 0) {
                    fprintf(stderr, "Error activating relay %d: %s\n", i, strerror(errno));
                    goto cleanup;
                }
            }

            sleep(WATERING_DURATION_SEC);

            for (int i = 0; i < NUM_RELAYS; i++) {
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    fprintf(stderr, "Error deactivating relay %d: %s\n", i, strerror(errno));
                    goto cleanup;
                }
            }

            if (log_watering_cycle() == -1) {
                fprintf(stderr, "Warning: failed to log watering cycle\n");
            }

            last_cycle_start = now;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Plant watering system stopped.\n");
    return ret;
}

