#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define STEP_DELAY_US 1000000
#define TOTAL_STEPS 30 * 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

static int setup_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int set_relay_intensity(int pin, int intensity) {
    if (gpioPWM(pin, intensity) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);
    gpioSetMode(RELAY1_PIN, PI_INPUT);
    gpioSetMode(RELAY2_PIN, PI_INPUT);
    gpioSetMode(RELAY3_PIN, PI_INPUT);
    gpioSetMode(RELAY4_PIN, PI_INPUT);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (setup_gpio(RELAY1_PIN) != 0 ||
        setup_gpio(RELAY2_PIN) != 0 ||
        setup_gpio(RELAY3_PIN) != 0 ||
        setup_gpio(RELAY4_PIN) != 0) {
        cleanup_gpio();
        gpioTerminate();
        return 1;
    }

    log_event("Smart lighting sunrise started");

    for (int step = 0; step < TOTAL_STEPS && running; step++) {
        int intensity = (step * 255) / TOTAL_STEPS;
        if (set_relay_intensity(RELAY1_PIN, intensity) != 0 ||
            set_relay_intensity(RELAY2_PIN, intensity) != 0 ||
            set_relay_intensity(RELAY3_PIN, intensity) != 0 ||
            set_relay_intensity(RELAY4_PIN, intensity) != 0) {
            log_event("Error setting relay intensity");
            break;
        }
        gpioDelay(STEP_DELAY_US);
    }

    log_event("Smart lighting sunrise stopped");
    cleanup_gpio();
    gpioTerminate();
    return 0;
}

