#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define ACCEL_XOUT_H 0x3B

/* LED GPIO pin (BCM) */
#define LED_PIN 17

/* Angular velocity threshold in degrees per second */
#define THRESHOLD 250.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Re-initialization retries */
#define MAX_RETRIES 3

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer structure */
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* Function prototypes */
static int initialize_i2c(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
static void check_threshold(float x, float y, float z, CircularBuffer *buffer);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize the I2C interface */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* Read gyroscope data from the MPU-6050 */
static int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    /* Convert to degrees per second (131 LSB/deg/s) */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

/* Check if any axis exceeds the threshold and control the LED */
static void check_threshold(float x, float y, float z, CircularBuffer *buffer) {
    bool exceeded = (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD);
    gpioWrite(LED_PIN, exceeded ? 1 : 0);

    if (exceeded) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        printf("[%s] Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n",
               timestamp, x, y, z);
        add_to_buffer(buffer, x, y, z);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Circular buffer */
    CircularBuffer buffer;
    buffer.head = 0;
    buffer.count = 0;

    float x, y, z;
    int retries = 0;

    printf("MPU-6050 Gyroscope Monitoring Started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            check_threshold(x, y, z, &buffer);
            retries = 0;
        } else {
            retries++;
            fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);

            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, re-initializing I2C...\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(100000); /* 100 ms delay before retry */

                if (initialize_i2c() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting.\n");
                    break;
                }
                retries = 0;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

