#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_0
#define CS_LINE_OFFSET  8U
#define CS_CHIP         "/dev/gpiochip0"
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_US 10000U
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_chip *g_cs_chip = NULL;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = {0x80, 0x7B, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[7] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, sizeof(tx)) == 0) {
            *x = (int16_t)((rx[2] << 8) | rx[1]);
            *y = (int16_t)((rx[4] << 8) | rx[3]);
            *z = (int16_t)((rx[6] << 8) | rx[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%09ld,%d,%d,%d\n", timestamp, ts.tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_cs_chip) {
        gpiod_chip_close(g_cs_chip);
        g_cs_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_chip = gpiod_chip_open(CS_CHIP);
    if (!g_cs_chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CS_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(g_cs_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line %u: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU9250 Gyroscope Data Logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data after %d retries, continuing...\n", MAX_RETRIES);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

