#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define GYRO_THRESHOLD 200.0f
#define WARNING_DURATION_MS 500
#define SAMPLE_INTERVAL_US 10000

#define MPU6050_REG_SMPLRT_DIV 0x19
#define MPU6050_REG_CONFIG 0x1A
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1 0x6B

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        return -1;
    }
    return 0;
}

static int spi_read_burst(uint8_t reg, uint8_t *data, uint32_t len) {
    char tx[7] = { (char)(reg | 0x80), 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };
    char rx[7] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 7) != 7) {
        return -1;
    }
    for (uint32_t i = 0; i < len; i++) {
        data[i] = (uint8_t)rx[i + 1];
    }
    return 0;
}

static int init_mpu6050(void) {
    uint8_t who_am_i = 0;
    if (spi_read_register(MPU6050_REG_PWR_MGMT_1, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (expected 0x68, got 0x%02X)\n", who_am_i);
        return -1;
    }

    if (spi_write_register(MPU6050_REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to wake up MPU6050\n");
        return -1;
    }
    gpioDelay(100000);

    if (spi_write_register(MPU6050_REG_SMPLRT_DIV, 7) != 0) {
        fprintf(stderr, "Error: Failed to set sample rate divider\n");
        return -1;
    }

    if (spi_write_register(MPU6050_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set DLPF configuration\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t data[6];
    if (spi_read_burst(MPU6050_REG_GYRO_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Error: Failed to read gyroscope data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_z = (int16_t)((data[4] << 8) | data[5]);

    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    time(&gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > GYRO_THRESHOLD || fabsf(y) > GYRO_THRESHOLD || fabsf(z) > GYRO_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(WARNING_DURATION_MS * 1000);
        gpioWrite(LED_GPIO, 0);
    }
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&gyro_buffer[index].timestamp);
        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f,%.2f\n", timestamp_str, gyro_buffer[index].x, gyro_buffer[index].y, gyro_buffer[index].z);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    while (running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

