#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Function to initialize the MPU-6050 */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

/* Function to read raw accelerometer data from the MPU-6050 */
static int read_raw_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to read raw gyroscope data from the MPU-6050 */
static int read_raw_gyro(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to convert raw accelerometer data to g-force units */
static void convert_accel(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *gx, float *gy, float *gz) {
    /* Sensitivity scale factor for +/- 2g range (131 LSB/g) */
    const float ACCEL_SCALE = 131.0f;
    *gx = (float)raw_x / ACCEL_SCALE;
    *gy = (float)raw_y / ACCEL_SCALE;
    *gz = (float)raw_z / ACCEL_SCALE;
}

/* Function to convert raw gyroscope data to degrees per second */
static void convert_gyro(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *gx, float *gy, float *gz) {
    /* Sensitivity scale factor for +/- 250 degrees/sec range (131 LSB/deg/s) */
    const float GYRO_SCALE = 131.0f;
    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;
}

/* Function to calculate roll and pitch angles from accelerometer data */
static void calculate_roll_pitch(float gx, float gy, float gz, float *roll, float *pitch) {
    /* Roll: atan2(gy, gz) in radians */
    *roll = atan2f(gy, gz);
    /* Pitch: atan2(-gx, sqrt(gy^2 + gz^2)) in radians */
    *pitch = atan2f(-gx, sqrtf(gy * gy + gz * gz));
}

/* Function to log data to a file in CSV format */
static void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open tilt_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Function to control the LED based on tilt thresholds */
static void control_led(float roll, float pitch) {
    int led_state = 0;
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        led_state = 1;
    }
    gpioWrite(LED_PIN, led_state);
}

int main() {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Initialize the MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_ax, raw_ay, raw_az, raw_gx, raw_gy, raw_gz;
        float gx, gy, gz, roll, pitch;

        /* Read raw accelerometer data */
        if (read_raw_accel(i2c_handle, &raw_ax, &raw_ay, &raw_az) < 0) {
            fprintf(stderr, "Warning: Failed to read accelerometer data, skipping cycle\n");
        } else {
            /* Read raw gyroscope data */
            if (read_raw_gyro(i2c_handle, &raw_gx, &raw_gy, &raw_gz) < 0) {
                fprintf(stderr, "Warning: Failed to read gyroscope data, skipping cycle\n");
            } else {
                /* Convert raw data to g-force units */
                convert_accel(raw_ax, raw_ay, raw_az, &gx, &gy, &gz);
                /* Convert raw data to degrees per second */
                convert_gyro(raw_gx, raw_gy, raw_gz, &gx, &gy, &gz);

                /* Calculate roll and pitch angles */
                calculate_roll_pitch(gx, gy, gz, &roll, &pitch);

                /* Log data to file */
                log_data(roll, pitch);

                /* Control the LED */
                control_led(roll, pitch);

                /* Print roll and pitch angles to the console */
                printf("Roll: %.2f degrees, Pitch: %.2f degrees\n", roll, pitch);
            }
        }

        /* Delay for the specified sampling interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nCleaning up and exiting...\n");
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

