#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define SI1145_ADDR 0x45
#define I2C_BUS "/dev/i2c-1"
#define LED_GPIO 17
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_si1145(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_vis_data0, als_vis_data1, ps1_data0, ps1_data1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg8(fd, 0x22, &als_vis_data0) < 0) return -1;
        if (i2c_read_reg8(fd, 0x23, &als_vis_data1) < 0) return -1;
        if (i2c_read_reg8(fd, 0x24, &ps1_data0) < 0) return -1;
        if (i2c_read_reg8(fd, 0x25, &ps1_data1) < 0) return -1;

        *ambient_light = ((uint16_t)als_vis_data1 << 8) | als_vis_data0;
        *proximity = ((uint16_t)ps1_data1 << 8) | ps1_data0;
        return 0;
    }

    fprintf(stderr, "Failed to read Si1145 after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

static void control_led(uint16_t proximity) {
    if (proximity > 100) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg8(i2c_fd, 0x07, 0x01) < 0) {
        fprintf(stderr, "Failed to wake Si1145\n");
        close(i2c_fd);
        return 1;
    }
    usleep(10000);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Si1145 biometric sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient_light, proximity;

        if (read_si1145(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_fp, ambient_light, proximity);
            control_led(proximity);
            printf("AmbientLight: %u, Proximity: %u\n", ambient_light, proximity);
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

