#define ADXRS290_REG_Y_AXIS_RATE 0x02
#define ADXRS290_REG_X_AXIS_CONFIG 0x04
#define ADXRS290_REG_Y_AXIS_CONFIG 0x06
#define ADXRS290_REG_X_AXIS_STATUS 0x08
#define ADXRS290_REG_Y_AXIS_STATUS 0x0A
#define ADXRS290_REG_X_AXIS_DATA 0x0C
#define ADXRS290_REG_Y_AXIS_DATA 0x0E

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
