#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define LOG_FILE "seismic_events.txt"
#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level == 1) {
        static uint32_t last_trigger_tick = 0;
        uint32_t elapsed = tick - last_trigger_tick;
        if (elapsed >= SEISMIC_THRESHOLD_MS * 1000) {
            last_trigger_tick = tick;
            if (gpioWrite(ALERT_GPIO, 1) == 0) {
                gpioDelay(ALERT_DURATION_MS * 1000);
                gpioWrite(ALERT_GPIO, 0);
            }
        }
    }
}

static void log_seismic_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Seismic event detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", ALERT_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR1_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Error: Failed to set alert callback for GPIO%d\n", SENSOR1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR2_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Error: Failed to set alert callback for GPIO%d\n", SENSOR2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

