#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0       /* Mode 0, active-low CE */
#define LED_GPIO       17
#define THRESHOLD      20.0f
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD_US 100000 /* 100 ms */

/* ADXRS290 register addresses (MSB = 1 for read) */
#define ADXRS290_REG_XGYRO_OUT_L 0x00
#define ADXRS290_REG_YGYRO_OUT_L 0x01
#define ADXRS290_REG_ZGYRO_OUT_L 0x02
#define ADXRS290_REG_XGYRO_OUT_H 0x03
#define ADXRS290_REG_YGYRO_OUT_H 0x04
#define ADXRS290_REG_ZGYRO_OUT_H 0x05
#define ADXRS290_REG_STATUS     0x06
#define ADXRS290_REG_CTRL       0x07
#define ADXRS290_REG_TEMP_OUT_L 0x08
#define ADXRS290_REG_TEMP_OUT_H 0x09

/* CTRL register bits */
#define CTRL_MODE_GYRO_ONLY 0x01

/* Status register bits */
#define STATUS_GYRO_READY 0x01

typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    uint8_t status = 0;
    uint8_t x_l = 0, x_h = 0, y_l = 0, y_h = 0, z_l = 0, z_h = 0;

    if (spi_read_register(ADXRS290_REG_STATUS, &status) != 0) {
        return -1;
    }
    if (!(status & STATUS_GYRO_READY)) {
        return -2; /* Gyro not ready yet */
    }

    if (spi_read_register(ADXRS290_REG_XGYRO_OUT_L, &x_l) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_XGYRO_OUT_H, &x_h) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_YGYRO_OUT_L, &y_l) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_YGYRO_OUT_H, &y_h) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_ZGYRO_OUT_L, &z_l) != 0) return -1;
    if (spi_read_register(ADXRS290_REG_ZGYRO_OUT_H, &z_h) != 0) return -1;

    int16_t x_raw = (int16_t)((x_h << 8) | x_l);
    int16_t y_raw = (int16_t)((y_h << 8) | y_l);
    int16_t z_raw = (int16_t)((z_h << 8) | z_l);

    /* ADXRS290 outputs 16-bit signed values; sensitivity is 125 °/s/LSB */
    *x_rate = (float)x_raw / 125.0f;
    *y_rate = (float)y_raw / 125.0f;
    *z_rate = (float)z_raw / 125.0f;

    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    memset(cb, 0, sizeof(*cb));
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(circular_buffer_t *cb, gyro_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static void buffer_get_latest(circular_buffer_t *cb, gyro_data_t *data) {
    pthread_mutex_lock(&cb->mutex);
    int idx = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *data = cb->data[idx];
    pthread_mutex_unlock(&cb->mutex);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&gyro_buffer);

    if (spi_write_register(ADXRS290_REG_CTRL, CTRL_MODE_GYRO_ONLY) != 0) {
        fprintf(stderr, "Failed to configure ADXRS290\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float x_rate, y_rate, z_rate;
        int ret = read_gyro_data(&x_rate, &y_rate, &z_rate);

        if (ret == 0) {
            struct timespec ts;
            if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
                perror("clock_gettime");
                break;
            }

            gyro_data_t data = { .timestamp = ts, .x_rate = x_rate, .y_rate = y_rate, .z_rate = z_rate };
            buffer_add(&gyro_buffer, data);

            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n",
                   x_rate, y_rate, z_rate);

            if (fabsf(x_rate) > THRESHOLD || fabsf(y_rate) > THRESHOLD || fabsf(z_rate) > THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else if (ret == -2) {
            /* Gyro not ready yet; keep LED off */
            gpioWrite(LED_GPIO, 0);
        } else {
            fprintf(stderr, "Error reading gyro data\n");
            gpioWrite(LED_GPIO, 0);
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

