#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_lamp_brightness(int pin, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE) {
        duty_cycle = MIN_DUTY_CYCLE;
    }
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO%d.\n", pin);
    }
}

static void turn_off_all_lamps(void) {
    set_lamp_brightness(LAMP1_PIN, 0);
    set_lamp_brightness(LAMP2_PIN, 0);
    set_lamp_brightness(LAMP3_PIN, 0);
}

static void cleanup(void) {
    turn_off_all_lamps();
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  Total duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started.\n");
    printf("Lamp 1: GPIO%d | Lamp 2: GPIO%d | Lamp 3: GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("Total duration: %d seconds\n", duration);
    printf("Press Ctrl+C to exit.\n");

    int elapsed_seconds = 0;
    while (program_running && elapsed_seconds < duration) {
        int duty_cycle = (int)((float)elapsed_seconds / duration * MAX_DUTY_CYCLE);
        set_lamp_brightness(LAMP1_PIN, duty_cycle);
        set_lamp_brightness(LAMP2_PIN, duty_cycle);
        set_lamp_brightness(LAMP3_PIN, duty_cycle);

        printf("Lamp 1: %d%% | Lamp 2: %d%% | Lamp 3: %d%% | Elapsed: %d/%d seconds\n",
               duty_cycle, duty_cycle, duty_cycle, elapsed_seconds, duration);

        sleep(1);
        elapsed_seconds++;
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Smart Sunset Simulator stopped.\n");

    return EXIT_SUCCESS;
}

