#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_MS     10000
#define YELLOW_MS  2000
#define GREEN_MS   10000
#define YELLOW_MS  3000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int set_all(struct gpiod_line *lines[], int val)
{
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(lines[i], val) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed on GPIO%d\n",
                    i + 1);
            return -1;
        }
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO%d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "traffic-light", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO%d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        if (set_all(lines, 0) < 0) goto cleanup;
        printf("Red\n");
        fflush(stdout);
        if (!running) break;
        if (gpiod_line_set_value(lines[RED_PIN], 1) < 0) goto cleanup;
        usleep(RED_MS * 1000);
        if (!running) break;

        if (set_all(lines, 0) < 0) goto cleanup;
        printf("Red + Yellow\n");
        fflush(stdout);
        if (!running) break;
        if (gpiod_line_set_value(lines[RED_PIN], 1) < 0) goto cleanup;
        if (gpiod_line_set_value(lines[YELLOW_PIN], 1) < 0) goto cleanup;
        usleep(YELLOW_MS * 1000);
        if (!running) break;

        if (set_all(lines, 0) < 0) goto cleanup;
        printf("Green\n");
        fflush(stdout);
        if (!running) break;
        if (gpiod_line_set_value(lines[GREEN_PIN], 1) < 0) goto cleanup;
        usleep(GREEN_MS * 1000);
        if (!running) break;

        if (set_all(lines, 0) < 0) goto cleanup;
        printf("Yellow\n");
        fflush(stdout);
        if (!running) break;
        if (gpiod_line_set_value(lines[YELLOW_PIN], 1) < 0) goto cleanup;
        usleep(YELLOW_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    return rc;
}

