#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_US 100000
#define POLL_DELAY_US 10000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        char buffer[128];
        snprintf(buffer, sizeof(buffer), "I2C write failed to register 0x%02X: %d", reg, result);
        log_error(buffer);
    }
    return result;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        char buffer[128];
        snprintf(buffer, sizeof(buffer), "I2C read failed from register 0x%02X: %d", reg, result);
        log_error(buffer);
    } else {
        *value = (uint8_t)result;
    }
    return result;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write_reg(MPR121_E0TTH, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t low_byte, high_byte;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &low_byte) < 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &high_byte) < 0) return -1;
    *touch_status = ((uint16_t)high_byte << 8) | low_byte;
    return 0;
}

static void toggle_relay(void) {
    int current_state = gpioRead(RELAY_GPIO);
    if (current_state < 0) {
        log_error("Failed to read relay GPIO state");
        return;
    }
    if (gpioWrite(RELAY_GPIO, !current_state) < 0) {
        log_error("Failed to write relay GPIO");
    } else {
        char buffer[128];
        snprintf(buffer, sizeof(buffer), "Relay toggled to %s", current_state ? "OFF" : "ON");
        log_error(buffer);
    }
}

int main(void) {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t previous_touch_status = 0;
    uint32_t last_debounce_time = 0;

    while (program_running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            log_error("Failed to read touch status");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t new_touch_status = touch_status & 0x01;
        uint32_t current_time = gpioTick();

        if (new_touch_status && (current_time - last_debounce_time) > DEBOUNCE_DELAY_US) {
            toggle_relay();
            last_debounce_time = current_time;
        }

        previous_touch_status = new_touch_status;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

