        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            log_error("Failed to read touch status");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t new_touch_status = touch_status & 0x01;
        uint32_t current_time = gpioTick();

        if (new_touch_status && (current_time - last_debounce_time) > DEBOUNCE_DELAY_US) {
            toggle_relay();
            last_debounce_time = current_time;
        }

        previous_touch_status = new_touch_status;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

