#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A pins (BCM)
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B pins (BCM)
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable pins (BCM)
#define ENABLE_A 24
#define ENABLE_B 25

// PID parameters
#define KP 1.0
#define KI 0.0
#define KD 0.0
#define I_LIMIT 100.0

// Tilt error range
#define TILT_ERROR_MIN -10.0
#define TILT_ERROR_MAX 10.0

// Distance threshold for obstacle avoidance
#define OBSTACLE_THRESHOLD 20.0

// PWM range
#define PWM_RANGE 255

// Simulation parameters
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

// Log file name
#define LOG_FILE "balance_log.txt"

// Global variables
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void stop_motors(void);
float calculate_tilt_error(void);
float calculate_distance(void);
void pid_control(float tilt_error, float *integral, float *previous_error, float *derivative);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize GPIO pins using pigpio
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set motor A pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);

    // Set motor B pins as outputs
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as outputs
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);

    // Enable PWM on enable pins
    gpioSetPWMrange(ENABLE_A, PWM_RANGE);
    gpioSetPWMrange(ENABLE_B, PWM_RANGE);

    // Ensure motors are stopped initially
    stop_motors();

    return 0;
}

// Set motor speeds using PWM
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
    if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
    if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
    if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

    // Motor A forward
    if (motor_a_speed >= 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENABLE_A, motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENABLE_A, -motor_a_speed);
    }

    // Motor B forward
    if (motor_b_speed >= 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENABLE_B, motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENABLE_B, -motor_b_speed);
    }
}

// Stop all motors
void stop_motors(void) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENABLE_A, 0);
    gpioPWM(ENABLE_B, 0);
}

// Calculate tilt error from simulated sensor data
float calculate_tilt_error(void) {
    return (float)(rand() % 201) - 100.0;
}

// Calculate distance from simulated sensor data
float calculate_distance(void) {
    return (float)(rand() % 381) + MIN_DISTANCE;
}

// PID control loop
void pid_control(float tilt_error, float *integral, float *previous_error, float *derivative) {
    float error = tilt_error;
    *integral += error;
    if (*integral > I_LIMIT) *integral = I_LIMIT;
    if (*integral < -I_LIMIT) *integral = -I_LIMIT;

