        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;
    }

    set_motor_speed(motor_a_speed, motor_b_speed);
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    // Seed random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // PID variables
    float integral = 0.0;
    float previous_error = 0.0;
