#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */
#define POLL_DELAY_US 10000     /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down on the touch sensor pin (TTP223 has its own pull-up) */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
    }

    /* Ensure relay starts in the OFF state (active-high relay) */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_detected = (gpioRead(TOUCH_SENSOR_PIN) == 1);

        if (touch_detected) {
            printf("Touch detected!\n");

            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate relay.\n");
                break;
            }

            /* Debounce delay */
            gpioDelay(DEBOUNCE_DELAY_US);

            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate relay.\n");
                break;
            }

            /* Poll for additional touch events to avoid immediate re-triggering */
            while (running && (gpioRead(TOUCH_SENSOR_PIN) == 1)) {
                gpioDelay(POLL_DELAY_US);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    printf("Touch sensor monitoring stopped.\n");

    return EXIT_SUCCESS;
}

