/*
 * mood_light.c — Raspberry Pi 3 Model B+ mood light controller
 *
 * Captures audio from ALSA at 8000 Hz, computes the RMS amplitude of each
 * buffer, and drives a common-cathode RGB LED via software PWM on GPIO17,
 * GPIO18, and GPIO27 (BCM).
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lasound
 *
 * ALSA is optional; the program simulates audio input with a sine
 * wave amplitude so the mood light still cycles through colors.
 */

#include <stdio.h>
