#define DEFAULT_SENSITIVITY 1.0
#define DEFAULT_COLOR_RED   128
#define DEFAULT_COLOR_GREEN 128
#define DEFAULT_COLOR_BLUE  128

#define PWM_PERIOD_US      10000   /* 10 ms */
#define PWM_STEPS          100
#define PWM_DUTY_MAX       255

#define SAMPLE_RATE_MIN    1000
#define SAMPLE_RATE_MAX    192000
#define PERIOD_SIZE_MIN    1
#define PERIOD_SIZE_MAX    1024

