#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ENABLE_PON_AEN 0x03

#define TCS34725_ATIME_154MS 0x02
#define TCS34725_ID_VALUE 0x44

static int i2c_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int tcs34725_write_byte(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)(reg | TCS34725_COMMAND_BIT), (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int tcs34725_read_byte(uint8_t reg, uint8_t *value) {
    char buf[1] = {(char)(reg | TCS34725_COMMAND_BIT)};
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int tcs34725_read_word(uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(i2c_handle, (char *)(reg | TCS34725_COMMAND_BIT), 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading 2 bytes from register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

