#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 50400

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        // Sunrise phase
        for (int i = 0; i < SUNRISE_DURATION && program_running; i++) {
            gpioWrite(RELAY1_PIN, 0);
            gpioWrite(RELAY2_PIN, 0);
            gpioWrite(RELAY3_PIN, 0);
            gpioWrite(RELAY4_PIN, 0);
            time_sleep(1.0);
        }
        if (!program_running) break;

        // Daytime phase
        for (int i = 0; i < DAYTIME_DURATION && program_running; i++) {
            gpioWrite(RELAY1_PIN, 1);
            gpioWrite(RELAY2_PIN, 1);
            gpioWrite(RELAY3_PIN, 1);
            gpioWrite(RELAY4_PIN, 1);
            time_sleep(1.0);
        }
        if (!program_running) break;

        // Sunset phase
        for (int i = 0; i < SUNSET_DURATION && program_running; i++) {
            gpioWrite(RELAY1_PIN, 0);
            gpioWrite(RELAY2_PIN, 0);
            gpioWrite(RELAY3_PIN, 0);
            gpioWrite(RELAY4_PIN, 0);
            time_sleep(1.0);
        }
        if (!program_running) break;

        // Nighttime phase
        for (int i = 0; i < NIGHTTIME_DURATION && program_running; i++) {
            gpioWrite(RELAY1_PIN, 1);
            gpioWrite(RELAY2_PIN, 1);
            gpioWrite(RELAY3_PIN, 1);
            gpioWrite(RELAY4_PIN, 1);
            time_sleep(1.0);
        }
        if (!program_running) break;
    }

    // Cleanup
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);
    gpioTerminate();
    return 0;
}

