#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define MAX_FILENAME_LEN 64

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int generate_filename(char *filename, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(filename, len, "%Y%m%d_%H%M%S.h264", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed to format filename\n");
        return -1;
    }

    return 0;
}

static int capture_video(const char *filename) {
    char command[512];
    int ret;

    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d000", filename, VIDEO_DURATION_SEC * 1000);

    ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid: %s\n", strerror(errno));
        return -1;
    }

    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n", WIFEXITED(ret) ? WEXITSTATUS(ret) : -1);
        return -1;
    }

    return 0;
}

static int log_motion_event(const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed to format timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s Motion detected on GPIO %d: %s\n", timestamp, GPIO_PIN, filename) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush() failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void) {
    int last_state = 1; /* Assume no motion at startup (active-low sensor) */
    int last_trigger_time = 0;
    char filename[MAX_FILENAME_LEN];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up resistor so the line reads HIGH when no motion is detected */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-up on GPIO %d\n", GPIO_PIN);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d\n", GPIO_PIN);
            break;
        }

        /* KY-033 is active-low: LOW means motion detected */
        if (current_state == 0 && last_state == 1) {
            int now = gpioTick();
            if (now - last_trigger_time >= DEBOUNCE_MS * 1000) {
                last_trigger_time = now;

                if (generate_filename(filename, sizeof(filename)) == 0) {
                    printf("Motion detected! Capturing video: %s\n", filename);

                    if (capture_video(filename) == 0) {
                        printf("Video captured successfully.\n");

                        if (log_motion_event(filename) != 0) {
                            fprintf(stderr, "Warning: Failed to log motion event.\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Failed to capture video.\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to generate filename.\n");
                }
            }
        }

        last_state = current_state;
        gpioDelay(10000); /* 10 ms polling interval */
    }

    /* Clean shutdown */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    printf("Motion detection stopped.\n");

    return EXIT_SUCCESS;
}

