/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43

/* Sensitivity scale factor for +/- 250 degrees/sec range */
#define GYRO_SCALE 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Log file name */
#define LOG_FILE "gyro_log.csv"

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the MPU-6050 sensor */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050 (I2C write failed)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for stabilization */

    /* Set gyroscope to +/- 250 degrees/sec range */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyro range (I2C write failed)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for stabilization */

    return 0;
}

/* Read raw gyroscope data from the MPU-6050 */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyro data (I2C block read failed)\n");
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Convert raw gyroscope data to degrees per second */
static float convert_to_degps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

/* Log data to a CSV file */
static int log_data(FILE *fp, float x_degps, float y_degps, float z_degps) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: Failed to get timestamp\n");
        return -1;
    }

