#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static int control_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d to %d.\n", pin, state);
        return -1;
    }
    return 0;
}

static void log_data(int moisture, int relay1, int relay2, int relay3, int relay4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp, moisture,
                relay1 ? "ON" : "OFF",
                relay2 ? "ON" : "OFF",
                relay3 ? "ON" : "OFF",
                relay4 ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

static void cleanup(void) {
    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_moisture_sensor();
        int relay1 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        if (control_relay(RELAY_1_PIN, relay1) != 0 ||
            control_relay(RELAY_2_PIN, relay2) != 0 ||
            control_relay(RELAY_3_PIN, relay3) != 0 ||
            control_relay(RELAY_4_PIN, relay4) != 0) {
            fprintf(stderr, "Error: relay control failed.\n");
            break;
        }

        log_data(moisture, relay1, relay2, relay3, relay4);

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

