/*
 * Free-fall detection for Raspberry Pi 3 Model B+ using an Analog Devices ADXL345.
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADXL345 SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADXL345 VCC -> 3.3 V
 *   ADXL345 GND -> GND
 *   Alarm LED   -> GPIO27 (BCM) via 330 Ω resistor to GND
 *
 * Build:  gcc -O2 -Wall -o freefall freefall.c -lpigpio -lrt
 * Run:    sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDRESS          0x53
#define ADXL345_REG_DEVID         0x00
#define ADXL345_REG_POWER_CTL     0x2D
#define ADXL345_REG_DATA_FORMAT   0x31
#define ADXL345_REG_DATAX0        0x32

#define ADXL345_DEVID_EXPECTED    0xE5
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_DATA_FORMAT_FULL_RES 0x08

/* ---- Free-fall parameters ---- */
#define FREEFALL_THRESHOLD_G      0.2f
#define FREEFALL_DURATION_SEC     0.5f
#define ALARM_DURATION_SEC        5.0f
#define POLL_INTERVAL_US         100000   /* 100 ms */
#define CONFIRM_DELAY_US          500000   /* 0.5 s  */

/* ---- GPIO ---- */
#define ALARM_GPIO                27

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put device into standby before closing */
        if (i2cWriteByteData(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x00) < 0)
            fprintf(stderr, "[WARN] Failed to put ADXL345 into standby during cleanup\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    int devid = i2cReadByteData(handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "[ERROR] Failed to read DEVID register (pigpio error %d)\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected DEVID 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby first so we can configure */
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set POWER_CTL to standby\n");
        return -1;
    }

    /* Full resolution, +/- 2g range, 100 Hz data rate */
    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FORMAT,
                        ADXL345_DATA_FORMAT_FULL_RES) < 0) {
        fprintf(stderr, "[ERROR] Failed to set DATA_FORMAT\n");
        return -1;
    }

    /* Measurement mode */
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL,
                        ADXL345_POWER_CTL_MEASURE) < 0) {
        fprintf(stderr, "[ERROR] Failed to set POWER_CTL to measure mode\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "[ERROR] Failed to read 6-byte acceleration block\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* ADXL345 outputs 16-bit signed values; full resolution range is +/- 2g */
    *x = (float)raw_x / 32768.0f * 2.0f;
    *y = (float)raw_y / 32768.0f * 2.0f;
    *z = (float)raw_z / 32768.0f * 2.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
static bool is_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD_G &&
            fabsf(y) < FREEFALL_THRESHOLD_G &&
            fabsf(z) < FREEFALL_THRESHOLD_G);
}

/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        perror("[ERROR] fopen(freefall.log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "<unknown-time>,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure alarm GPIO --- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* --- Open I2C bus 1 at ADXL345 address --- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(1, 0x%02X) failed: pigpio error %d\n",
                ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize ADXL345 --- */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction");
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "[WARN] Read error — continuing\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (is_freefall(x, y, z)) {
            printf("Freefall detected! Logging to freefall.log...\n");
            log_freefall(x, y, z);

            /* Ensure alarm is asserted for the full duration */
            gpioWrite(ALARM_GPIO, 1);
            time_sleep(ALARM_DURATION_SEC);
            gpioWrite(ALARM_GPIO, 0);

            /* Confirm the freefall by reading again after a short delay */
            gpioDelay(CONFIRM_DELAY_US);
            if (read_acceleration(g_i2c_handle, &x, &y, &z) < 0) {
                fprintf(stderr, "[WARN] Confirm read error — continuing\n");
                continue;
            }
            if (is_freefall(x, y, z)) {
                printf("Freefall confirmed! Logging to freefall.log...\n");
                log_freefall(x, y, z);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

