/*
 * HC-SR04 Ultrasonic Distance Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   TRIG -> GPIO4 (BCM)
 *   ECHO -> GPIO18 (BCM)
 *
 * Build: gcc -O2 -Wall -o hcsr04_logger hcsr04_logger.c -lpigpio -lrt
 * Run:   sudo ./hcsr04_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      4
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  100000   /* 100 ms max echo wait */
#define MAX_PULSE_US     23200    /* ~4 m round-trip */
#define CYCLE_DELAY_US   200000   /* 200 ms between trigger cycles */

#define LOG_FILE_NAME    "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between callbacks and main thread                       */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen   = false;
static volatile bool     g_pulse_ready = false;
static volatile bool     g_running     = true;

static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callbacks (runs in pigpio thread)                       */
/* ------------------------------------------------------------------ */

static void echo_rising_edge(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)level;

    if (tick == 0) {
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen   = false;
        g_pulse_ready = false;
        return;
    }

    if (g_start_tick == 0) {
        g_start_tick = tick;
        g_echo_seen   = false;
        g_pulse_ready = false;
    }
}

static void echo_falling_edge(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)level;

    if (tick == 0) {
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen   = false;
        g_pulse_ready = false;
        return;
    }

    if (g_start_tick != 0) {
        g_end_tick   = tick;
        g_echo_seen   = true;
        g_pulse_ready = true;
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Returns the elapsed microseconds between two 32-bit tick counters.
 * Handles 32-bit tick wraparound (approximately every ~71.6 minutes).
 */
static uint32_t tick_diff_us(uint32_t start, uint32_t end)
{
    return end - start;
}

/*
 * Returns the distance in cm, or -1.0 on error.
 * Handles invalid pulse widths (0, too long, or timeout).
 */
static double calculate_distance(uint32_t pulse_us)
{
    if (pulse_us == 0) {
        return -1.0;
    }
    if (pulse_us > MAX_PULSE_US) {
        return -1.0;
    }
    if (!g_echo_seen) {
        return -1.0;
    }
    if (!g_pulse_ready) {
        return -1.0;
    }

    /* speed of sound ~343 m/s => distance = (pulse_us * 343) / 2 / 1e6 */
    return (double)pulse_us * 343.0 / 2.0 / 1000000.0;
}

/*
 * Logs a timestamped distance reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_distance(double distance)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s.%09ld,%.2f\n", timestamp, ts.tv_nsec, distance) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install alert callbacks --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_rising_edge) != 0) {
        fprintf(stderr, "Error: failed to set rising-edge alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(ECHO_PIN, echo_falling_edge) != 0) {
        fprintf(stderr, "Error: failed to set falling-edge alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp_ns,distance_cm\n");
        fflush(fp);
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(fp);
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");
    printf("Logging to %s\n", LOG_FILE_NAME);

    /* --- Main loop --- */
    while (g_running) {
        /* Reset state before triggering */
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen   = false;
        g_pulse_ready = false;

        /* 10 µs trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Warning: failed to set TRIGGER_PIN high.\n");
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Warning: failed to set TRIGGER_PIN low.\n");
        }

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout (no response within %d µs).\n",
                    ECHO_TIMEOUT_US);
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }

        if (!g_pulse_ready) {
            fprintf(stderr, "Warning: invalid pulse width (%u µs).\n",
                    tick_diff_us(g_start_tick, g_end_tick));
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }

        /* Calculate distance */
        double distance = calculate_distance(tick_diff_us(g_start_tick, g_end_tick));

        if (distance < 0.0) {
            fprintf(stderr, "Warning: invalid distance calculation.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: failed to log distance.\n");
            }
        }

        gpioDelay(CYCLE_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");

    /* Cancel callbacks */
    gpioSetAlertFunc(ECHO_PIN, NULL);

    /* Close log file */
    if (fclose(fp) != 0) {
        perror("fclose");
    }

    /* Terminate pigpio */
    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

