#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define BUZZER_GPIO 17
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define MAX_RETRIES 3
#define BUZZER_DURATION_MS 1000

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_lis3dh(void) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00);
        if (result == 0) break;
        fprintf(stderr, "Error writing CTRL_REG1 (attempt %d): %d\n", retries + 1, result);
        retries++;
        gpioDelay(10000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize LIS3DH after %d retries\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result == 0) break;
        fprintf(stderr, "Error writing CTRL_REG4 (attempt %d): %d\n", retries + 1, result);
        retries++;
        gpioDelay(10000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize LIS3DH after %d retries\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (result == 6) break;
        fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", retries + 1, result);
        retries++;
        gpioDelay(10000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to read acceleration after %d retries\n", MAX_RETRIES);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(BUZZER_DURATION_MS * 1000);
    gpioWrite(BUZZER_GPIO, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (freefall_threshold <= 0.0f) {
            fprintf(stderr, "Invalid freefall threshold: %s\n", argv[1]);
            return 1;
        }
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
        if (impact_threshold <= 0.0f) {
            fprintf(stderr, "Invalid impact threshold: %s\n", argv[2]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Freefall detection started. Thresholds: freefall=%.2f g, impact=%.2f g\n", freefall_threshold, impact_threshold);

    while (running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold) {
            printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer();
        } else if (magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

