#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_DURATION_US 2000000
#define NO_LINE_THRESHOLD 5

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return value;
}

static int log_sensor_data(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    return 0;
}

static int check_line_following(int left, int center, int right) {
    if (center == 1) {
        return 1;
    }
    if (left == 0) {
        return -1;
    }
    if (right == 0) {
        return 1;
    }
    return 0;
}

static void control_motor(int direction) {
    (void)direction;
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Error turning on alert pin\n");
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off alert pin\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set left sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set center sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set right sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int no_line_count = 0;

    while (program_running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_sensor_data(left, center, right) != 0) {
            fprintf(stderr, "Failed to log sensor data\n");
        }

        int line_following = check_line_following(left, center, right);

        if (line_following == 1) {
            control_motor(1);
        } else if (line_following == -1) {
            control_motor(-1);
        } else {
            control_motor(0);
        }

        if (center == 1) {
            no_line_count = 0;
        } else {
            no_line_count++;
            if (no_line_count >= NO_LINE_THRESHOLD) {
                trigger_alert();
                no_line_count = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

