/*
 * Si7210 Hall Effect Sensor Monitor with Relay Control
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Silicon Labs Si7210 (I2C address 0x48)
 * Relay:  GPIO17 (BCM, active high)
 *
 * Build:  gcc -O2 -Wall -o si7210_monitor si7210_monitor.c -lpigpio -lrt
 * Run:    sudo ./si7210_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          1
#define SI7210_ADDR      0x48
#define RELAY_GPIO       17
#define THRESHOLD_MT     5.0f
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define MAX_RETRIES      50
#define POLL_DELAY_US    1000     /* 1 ms  */

/* Si7210 register addresses (from Si7210 datasheet) */
#define REG_HALL_EFFECT  0x00
#define REG_CONFIG      0x01
#define REG_MODE        0x02
#define REG_INT_CONFIG   0x03
#define REG_INT_STATUS   0x04
#define REG_INT_CLEAR    0x05

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_hall_effect(float *field_mt);
static int  set_relay(int state);
static int  log_event(float field_mt, int relay_state);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */

/*
 * Write a single byte to a Si7210 register.
 * Returns 0 on success, -1 on failure.
 */
static int si7210_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/*
 * Read a single byte from a Si7210 register.
 * Returns the byte value (0-255) on success, -1 on failure.
 */
static int si7210_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/*
 * Initialize the I2C bus and open the Si7210 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7210_ADDR, g_i2c_handle);
        return -1;
    }

    /*
     * Verify the sensor is present by reading the HALL_EFFECT register.
     * The Si7210 returns 0x00 on success, any other value indicates an error.
     */
    int status = si7210_read_reg(REG_HALL_EFFECT);
    if (status < 0) {
        fprintf(stderr, "[ERROR] Si7210 not responding at address 0x%02X\n",
                SI7210_ADDR);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (status != 0x00) {
        fprintf(stderr, "[ERROR] Si7210 not responding (status=0x%02X)\n", status);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /*
     * Configure the Si7210:
     *   CONFIG[7:6] = 00 (normal operation)
     *   CONFIG[5:4] = 00 (hall-effect mode)
     *   CONFIG[3:2] = 00 (no filter)
     *   CONFIG[1:0] = 00 (no interrupt)
     *   => 0x00
     */
    if (si7210_write_reg(REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to configure Si7210\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /*
     * Set the mode to normal operation.
     * MODE[1:0] = 00 (normal operation)
     * => 0x00
     */
    if (si7210_write_reg(REG_MODE, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set Si7210 mode\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /*
     * Clear any pending interrupts.
     * INT_CLEAR[7:0] = 0x00
     */
    if (si7210_write_reg(REG_INT_CLEAR, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to clear Si7210 interrupts\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- Sensor read ------------------------------- */

/*
 * Read the magnetic field strength from the Si7210.
 * Returns 0 on success, -1 on failure.
 */
static int read_hall_effect(float *field_mt)
{
    int raw = si7210_read_reg(REG_HALL_EFFECT);
    if (raw < 0) {
        return -1;
    }

    /*
     * The Si7210 returns a 16-bit value in the range 0-65535.
     * The Hall-effect output is proportional to the magnetic field strength.
     * A higher raw value indicates a stronger magnetic field.
     * We convert to mT by multiplying by 0.001 (100 µT per LSB).
     */
    *field_mt = (float)raw * 0.001f;
    return 0;
}

/* ----------------------------- Relay control ----------------------------- */

/*
 * Set the relay state.
 * Returns 0 on success, -1 on failure.
 */
static int set_relay(int state)
{
    int rc = gpioWrite(RELAY_GPIO, state);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed: %d\n",
                RELAY_GPIO, state, rc);
        return -1;
    }
    return 0;
}

/* ----------------------------- Event logging ----------------------------- */

/*
 * Append a timestamped event entry to magnetic_events.txt.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(float field_mt, int relay_state)
{
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        perror("[ERROR] fopen(magnetic_events.txt)");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("[ERROR] time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("[ERROR] localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Field: %.3f mT, Relay: %s\n",
                timestamp, field_mt, relay_state ? "ON" : "OFF") < 0) {
        perror("[ERROR] fprintf(magnetic_events.txt)");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose(magnetic_events.txt)");
        return -1;
    }

    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output, initially low */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "[FATAL] gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() < 0) {
        fprintf(stderr, "[FATAL] I2C initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Si7210 Hall Effect Monitor started.\n");
    printf("  I2C bus: %d, sensor addr: 0x%02X, relay GPIO: %d\n",
           I2C_BUS, SI7210_ADDR, RELAY_GPIO);
    printf("  Threshold: %.1f mT, sample period: %d ms\n",
           THRESHOLD_MT, SAMPLE_PERIOD_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;

    while (g_running) {
        float field_mt = 0.0f;

        if (read_hall_effect(&field_mt) < 0) {
            fprintf(stderr, "[ERROR] Failed to read Hall effect data\n");
            /* Deactivate relay on read failure */
            if (set_relay(0) < 0) {
                fprintf(stderr, "[ERROR] Failed to deactivate relay on read failure\n");
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Field: %.3f mT\n", field_mt);

        if (field_mt > THRESHOLD_MT) {
            relay_state = !relay_state;
            if (set_relay(relay_state) < 0) {
                fprintf(stderr, "[ERROR] Failed to set relay state\n");
            }
            if (log_event(field_mt, relay_state) < 0) {
                fprintf(stderr, "[ERROR] Failed to log event\n");
            }
        } else {
            /* Log only when the field exceeds the threshold */
            if (log_event(field_mt, relay_state) < 0) {
                fprintf(stderr, "[ERROR] Failed to log event\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Si7210 Hall Effect Monitor stopped.\n");
    return EXIT_SUCCESS;
}

