#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static int control_relay(int gpio, const char *command) {
    if (strcmp(command, "ON") == 0) {
        if (gpioWrite(gpio, 1) == 0) {
            log_event("Relay turned ON");
            return 0;
        }
        log_event("Failed to turn relay ON");
        return -1;
    } else if (strcmp(command, "OFF") == 0) {
        if (gpioWrite(gpio, 0) == 0) {
            log_event("Relay turned OFF");
            return 0;
        }
        log_event("Failed to turn relay OFF");
        return -1;
    }
    log_event("Invalid command received");
    return -1;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return 1;
    }

    log_event("Listening for connections...");

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept failed");
            break;
        }

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            perror("recv failed");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (bytes_received == 0) {
            log_event("Client disconnected");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        buffer[bytes_received] = '\0';
        char *command = strtok(buffer, "\r\n");
        if (!command) {
            log_event("Invalid command received (no newline)");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        command = strtok(NULL, "\r\n");
        if (command) {
            log_event("Invalid command received (extra data)");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        command = strtok(command, " \t\r\n");
        if (!command) {
            log_event("Invalid command received (no command)");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        command = strupr(command);
        if (control_relay(RELAY_GPIO, command) != 0) {
            log_event("Relay control failed");
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

