/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F Liquid Flow Monitor
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Sensor 1 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Sensor 2 SDA -> GPIO 5 (I2C bus 1 SDA)
 *   Sensor 2 SCL -> GPIO 6 (I2C bus 1 SCL)
 *   Relay IN   -> GPIO 18 (BCM, active-high)
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS        "/dev/i2c-1"
#define GPIO_CHIP      "gpiochip0"
#define RELAY_LINE     18          /* BCM 18 */
#define FLOW_THRESHOLD 5.0f       /* ml/min */
#define POLL_DELAY_MS  100
#define LOG_FILE       "flow_log.txt"

/* SLF3S-1300F I2C addresses (from datasheet) */
#define SENSOR1_ADDR   0x48
#define SENSOR2_ADDR   0x49

/* SLF3S-1300F commands (from datasheet) */
#define CMD_START_MEAS 0x36
#define CMD_READ_MEAS  0x2E

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;

static int  g_i2c_fd1 = -1;
static int  g_i2c_fd2 = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_flow_rate(int fd, float *out_ml_min);
static bool check_flow_rate(float rate);
static void log_flow_rate(float rate1, float rate2);
static void control_relay(float rate1, float rate2);

/* ----------------------------- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---------------- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[I2C] write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[I2C] read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor read ------------------------------- */
static int read_flow_rate(int fd, float *out_ml_min)
{
    uint8_t cmd = CMD_READ_MEAS;
    uint8_t buf[3];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* Datasheet: conversion takes ~15 ms; wait 20 ms for safety */
    usleep(20000);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRC over the two data bytes */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[Sensor] CRC mismatch on read\n");
        return -1;
    }

    /* SLF3S-1300F returns 16-bit signed value, little-endian */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_ml_min = (float)raw / 1000.0f;
    return 0;
}

/* ----------------------------- Flow rate validation ------------------------- */
static bool check_flow_rate(float rate)
{
    return (rate >= 0.0f && rate <= FLOW_THRESHOLD);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_flow_rate(float rate1, float rate2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s.%03ld, %.2f, %.2f\n", tbuf, ts.tv_nsec / 1000000L, rate1, rate2);
    } else {
        fprintf(fp, "<timestamp-error>, %.2f, %.2f\n", rate1, rate2);
    }

    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(float rate1, float rate2)
{
    int val = (check_flow_rate(rate1) && check_flow_rate(rate2)) ? 1 : 0;
    if (gpiod_line_set_value(g_relay, val) < 0) {
        fprintf(stderr, "[GPIO] set_value(%d) failed: %s\n", val, strerror(errno));
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_relay) {
        gpiod_line_set_value(g_relay, 0);   /* de-energize relay */
        gpiod_line_release(g_relay);
        g_relay = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd1 >= 0) {
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
    }
    if (g_i2c_fd2 >= 0) {
        close(g_i2c_fd2);
        g_i2c_fd2 = -1;
    }
    printf("Cleanup complete.\n");
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring flow sensors. Press Ctrl+C to exit.\n");

    while (g_running) {
        float rate1 = 0.0f, rate2 = 0.0f;
        bool ok1 = (read_flow_rate(g_i2c_fd1, &rate1) == 0);
        bool ok2 = (read_flow_rate(g_i2c_fd2, &rate2) == 0);

        if (ok1 && ok2) {
            log_flow_rate(rate1, rate2);
            control_relay(rate1, rate2);
        } else {
            fprintf(stderr, "Sensor read error — relay state unchanged.\n");
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

/* ----------------------------- I2C initialization ------------------------- */
static int init_i2c(void)
{
    g_i2c_fd1 = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd1 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SENSOR1_ADDR, strerror(errno));
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }

    /* Verify sensor presence by issuing a dummy read */
    uint8_t dummy;
    if (i2c_read_bytes(g_i2c_fd1, &dummy, 1) < 0) {
        fprintf(stderr, "Sensor 1 at 0x%02X not responding.\n", SENSOR1_ADDR);
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }

    g_i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd2 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }

    if (ioctl(g_i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SENSOR2_ADDR, strerror(errno));
        close(g_i2c_fd2);
        g_i2c_fd2 = -1;
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }

    /* Verify sensor presence by issuing a dummy read */
    if (i2c_read_bytes(g_i2c_fd2, &dummy, 1) < 0) {
        fprintf(stderr, "Sensor 2 at 0x%02X not responding.\n", SENSOR2_ADDR);
        close(g_i2c_fd2);
        g_i2c_fd2 = -1;
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }

    /* Start continuous measurement on both sensors */
    if (i2c_write_cmd(g_i2c_fd1, CMD_START_MEAS) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 1.\n");
        close(g_i2c_fd2);
        g_i2c_fd2 = -1;
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }
    if (i2c_write_cmd(g_i2c_fd2, CMD_START_MEAS) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2.\n");
        close(g_i2c_fd2);
        g_i2c_fd2 = -1;
        close(g_i2c_fd1);
        g_i2c_fd1 = -1;
        return -1;
    }

    printf("I2C initialized: %s (0x%02X) and %s (0x%02X).\n",
           I2C_BUS, SENSOR1_ADDR, I2C_BUS, SENSOR2_ADDR);
    return 0;
}

/* ----------------------------- GPIO initialization ------------------------- */
static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_relay = gpiod_chip_get_line(g_chip, RELAY_LINE);
    if (!g_relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", RELAY_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_relay, "flow_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                RELAY_LINE, strerror(errno));
        gpiod_line_release(g_relay);
        g_relay = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    printf("GPIO initialized: %s line %d (BCM).\n", GPIO_CHIP, RELAY_LINE);
    return 0;
}

