 * Returns 0 on success, -1 on failure.
 */
static int log_message(int priority, const char *message)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tm_info;

    if (localtime_r(&now, &tm_info) == NULL) {
        syslog(LOG_ERR, "localtime_r failed: %s", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return -1;
    }

    syslog(priority, "[%s] %s", ts, message);
    return 0;
}

/*
 * Drive the motor: ENA high, IN1 high, IN2 low.
 * Returns 0 on success, -1 on failure.
 */
static int motor_start(struct gpiod_line *ena, struct gpiod_line *in1,
                        struct gpiod_line *in2)
{
    if (gpiod_line_set_value(ena, 1) < 0) {
        syslog(LOG_ERR, "Failed to set ENA high: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in1, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Stop the motor: ENA low, IN1 low, IN2 low.
 * Returns 0 on success, -1 on failure.
 */
static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                       struct gpiod_line *in2)
{
    if (gpiod_line_set_value(ena, 0) < 0) {
        syslog(LOG_ERR, "Failed to set ENA low: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in1, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 low: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Close the window by driving the motor for MOTOR_HOLD_US.
 * Returns 0 on success, -1 on failure.
 */
static int close_window(struct gpiod_line *ena, struct gpiod_line *in1,
                        struct gpiod_line *in2)
{
    if (motor_start(ena, in1, in2) < 0)
        return -1;

    /*
     * Use the library's API call() to hold the motor for the specified
     * duration.  This is a blocking call that returns after the specified
     * time has elapsed, or if interrupted by a signal.
     */
    if (gpiod_line_set_value(in1, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high during hold: %s", strerror(errno));
        motor_stop(ena, in1, in2);
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low during hold: %s", strerror(errno));
        motor_stop(ena, in1, in2);
        return -1;
    }

    if (gpiod_line_set_value(ena, 0) < 0) {
        syslog(LOG_ERR, "Failed to set ENA low during hold: %s", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Read the rain sensor value.
 * Returns 0 (dry) or 1 (wet), or -1 on error.
 */
static int read_rain_sensor(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "Failed to read rain sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    /* Get lines */
    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (rain_line == NULL || ena_line == NULL || in1_line == NULL || in2_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        goto cleanup;
    }

    /* Request rain sensor line as input with pull-up */
    if (gpiod_line_request_input_flags(rain_line, "rain_sensor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        syslog(LOG_ERR, "Failed to request rain sensor line as input: %s",
               strerror(errno));
        goto cleanup;
    }

    /* Request motor control lines as output, initially low */
    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0 ||
        gpiod_line_request_output(in1_line, "motor_in1", 0) < 0 ||
        gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        syslog(LOG_ERR, "Failed to request motor control lines as output: %s",
               strerror(errno));
        goto cleanup;
    }

    /* Ensure motor is stopped at startup */
    if (motor_stop(ena_line, in1_line, in2_line) < 0) {
        syslog(LOG_ERR, "Failed to stop motor at startup");
        goto cleanup;
    }

    log_message(LOG_INFO, "Rain window monitoring started.");
    syslog(LOG_INFO, "Rain sensor: GPIO %d (pull-up), motor: ENA %d, IN1 %d, IN2 %d",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int dry_count = 0;

    while (g_running) {
        int rain_val = read_rain_sensor(rain_line);
        if (rain_val < 0) {
            /* Sensor read error — wait and retry */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Rain sensor pulls DO low when dry, high when wet */
        if (rain_val == 0) {
            dry_count++;
            if (dry_count >= CONSECUTIVE_DRY) {
                log_message(LOG_INFO, "Rain detected — closing window.");

                if (close_window(ena_line, in1_line, in2_line) < 0) {
                    log_message(LOG_ERR, "Failed to close window.");
                } else {
                    log_message(LOG_INFO, "Window closed.");
                }

                /* Reset counter so we don't trigger again until dry for a while */
                dry_count = 0;
            }
        } else {
            dry_count = 0; /* Reset on dry reading */
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown: stop motor and release lines */
    log_message(LOG_INFO, "Shutting down gracefully.");
    motor_stop(ena_line, in1_line, in2_line);
    ret = EXIT_SUCCESS;

cleanup:
    if (rain_line != NULL)
        gpiod_line_release(rain_line);
    if (ena_line != NULL)
        gpiod_line_release(ena_line);
    if (in1_line != NULL)
        gpiod_line_release(in1_line);
    if (in2_line != NULL)
        gpiod_line_release(in2_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    closelog();
    return ret;
}

