/*
 * Door-lock actuator controller for Raspberry Pi using pigpio.
 *
 * Wiring:
 *   Servo signal  -> GPIO 18 (physical pin 12, BCM)
 *   Lock button   -> GPIO 21 (BCM)  [internal pull-up enabled]
 *   Unlock button -> GPIO 22 (BCM)  [internal pull-up enabled]
 *
 * Build:  gcc -O2 -Wall -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000   /* 2000 µs  -> 100 % duty cycle */
#define UNLOCK_PULSE_US 1000   /* 1000 µs -> 50 % duty cycle  */
#define DEBOUNCE_US    200000 /* 200 ms  -> 200 ms debounce window */
#define POLL_DELAY_US  10000  /* 10 ms  -> 10 ms poll interval      */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly.             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Stop the servo and release pigpio resources.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo pulses (pulse width 0) */
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Warning: gpioServo(stop) failed\n");
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Lock the door.                                                     */
/* ------------------------------------------------------------------ */
static int lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);

    if (gpioServo(SERVO_PIN, LOCK_PULSE_US) != 0) {
        fprintf(stderr, "Error: gpioServo(lock) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Unlock the door.                                                    */
/* ------------------------------------------------------------------ */
static int unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);

    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_US) != 0) {
        fprintf(stderr, "Error: gpioServo(unlock) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Shutdown the system.                                               */
/* ------------------------------------------------------------------ */
static int shutdown_system(void)
{
    printf("Shutting down...\n");
    fflush(stdout);

    /* Stop servo pulses (pulse width 0) */
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioServo(shutdown) failed\n");
        return -1;
    }

    /* Final API call to ensure servo is stopped */
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioServo(shutdown final) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up resistors so the buttons read HIGH
       when idle (button pressed -> pin goes LOW) */
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure servo starts in a safe state */
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioServo(init) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door-lock controller started.\n");
    printf("  Servo: GPIO %d\n", SERVO_PIN);
    printf("  Lock:  GPIO %d (internal pull-up)\n", LOCK_BUTTON);
    printf("  Unlock: GPIO %d (internal pull-up)\n", UNLOCK_BUTTON);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int lock_pressed  = (gpioRead(LOCK_BUTTON)  == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        /* Debounce: wait for button release plus debounce window */
        if (lock_pressed) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 1) {
                lock_door();
            }
        }

        if (unlock_pressed) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 1) {
                unlock_door();
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    fflush(stdout);

    if (shutdown_system() != 0) {
        fprintf(stderr, "Warning: shutdown_system() failed\n");
    }

    printf("Door-lock controller stopped.\n");
    fflush(stdout);

    cleanup();
    return EXIT_SUCCESS;
}

