#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define DEBOUNCE_MS 200

#define MHD_R 0x2B
#define NHD_R 0x2C
#define NCL_R 0x2D
#define FDL_R 0x2E
#define MHD_F 0x2F
#define NHD_F 0x30
#define NCL_F 0x31
#define FDL_F 0x32
#define ELECONFIG 0x5E
#define DEBOUNCE 0x5B
#define FFI 0x5C
#define SFI 0x5D
#define CDT 0x5E
#define ECR 0x5E
#define AUTOCONFIG 0x7B
#define TOUCHSTATUS_L 0x00
#define TOUCHSTATUS_H 0x01
#define ELECTRODE_0 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    uint8_t touch_status;
    int retries = 10;

    // Soft reset
    if (i2c_write_reg(ECR, 0x63) < 0) return -1;
    usleep(10000);

    // Baseline filtering
    if (i2c_write_reg(MHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg(NHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg(NCL_R, 0x00) < 0) return -1;
    if (i2c_write_reg(FDL_R, 0x00) < 0) return -1;
    if (i2c_write_reg(MHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg(NHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg(NCL_F, 0x00) < 0) return -1;
    if (i2c_write_reg(FDL_F, 0x00) < 0) return -1;

    // Debounce
    if (i2c_write_reg(DEBOUNCE, 0x00) < 0) return -1;

    // FFI
    if (i2c_write_reg(FFI, 0x01) < 0) return -1;

    // SFI
    if (i2c_write_reg(SFI, 0x00) < 0) return -1;

    // CDT
    if (i2c_write_reg(CDT, 0x00) < 0) return -1;

    // ELECONFIG
    if (i2c_write_reg(ELECONFIG, 0x0C) < 0) return -1;

    // Auto-config
    if (i2c_write_reg(AUTOCONFIG, 0x0B) < 0) return -1;

    // Enable 12 electrodes
    if (i2c_write_reg(ECR, 0x8C) < 0) return -1;

    // Wait for auto-config to complete
    do {
        if (i2c_read_reg(ECR, &touch_status) < 0) return -1;
        if (touch_status & 0x01) break;
        usleep(1000);
        retries--;
    } while (retries > 0);

    if (retries == 0) {
        fprintf(stderr, "Auto-config timeout\n");
        return -1;
    }

    return 0;
}

static int mpr121_read_touch_status(uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_reg(TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_reg(TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open GPIO chip and get relay line
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RELAY_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "mpr121_relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", RELAY_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPR121 relay control started. Press Ctrl+C to exit.\n");

    bool relay_state = false;
    uint16_t touch_status = 0;
    int last_touch_state = 0;

    while (running) {
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status, retrying...\n");
            usleep(100000);
            continue;
        }

        int current_touch_state = (touch_status & (1 << ELECTRODE_0)) ? 1 : 0;

        if (current_touch_state && !last_touch_state) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay_line, relay_state ? 1 : 0) < 0) {
                fprintf(stderr, "Failed to set relay state: %s\n", strerror(errno));
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            usleep(DEBOUNCE_MS * 1000);
        }

        last_touch_state = current_touch_state;
        usleep(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

