#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 12000  /* 12 ms for 0 degrees, 24000 for 180 degrees */
#define LOG_FILE "security.log"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message, ...) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    va_list args;
    va_start(args, message);
    fprintf(log_file, "%s: ", timestamp);
    vfprintf(log_file, message, args);
    va_end(args);
    fputc('\n', log_file);
    fflush(log_file);
    syslog(LOG_INFO, "%s: ", timestamp);
    va_start(args, message);
    vsyslog(LOG_INFO, message, args);
    va_end(args);
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_event("Error: Invalid servo angle %d (must be 0-180)", angle);
        return -1;
    }
    int pulse_width = PWM_DUTY_CYCLE + (angle * (PWM_RANGE - PWM_DUTY_CYCLE) / 180);
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        log_event("Error: gpioServo failed for pin %d", SERVO_PIN);
        return -1;
    }
    log_event("Servo angle set to %d degrees (pulse width %d us)", angle, pulse_width);
    return 0;
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_event("Error: gpioRead failed for pin %d", PIR_PIN);
        return -1;
    }
    log_event("PIR sensor value: %d", value);
    return value;
}

static int send_response(int client_fd, const char *message) {
    ssize_t bytes_sent = send(client_fd, message, strlen(message), 0);
    if (bytes_sent < 0) {
        log_event("Error: send failed: %s", strerror(errno));
        return -1;
    }
    if ((size_t)bytes_sent != strlen(message)) {
        log_event("Warning: send truncated: %zd bytes sent, expected %zu", bytes_sent, strlen(message));
        return -1;
    }
    return 0;
}

static int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_event("Error: recv failed: %s", strerror(errno));
        return -1;
    }
    if (bytes_received == 0) {
        log_event("Client disconnected");
        return 0;
    }
    buffer[bytes_received] = '\0';
    log_event("Received command: %s", buffer);

    char *token = strtok(buffer, " \r\n");
    if (!token) {
        log_event("Error: Invalid command format");
        send_response(client_fd, "Error: Invalid command format\n");
        return -1;
    }

    if (strcmp(token, "the") == 0) {
        token = strtok(NULL, " \r\n");
        if (!token) {
            log_event("Error: Missing library name");
            send_response(client_fd, "Error: Missing library name\n");
            return -1;
        }
        if (strcmp(token, "library's") == 0) {
            token = strtok(NULL, " \r\n");
            if (!token) {
                log_event("Error: Missing API call");
                send_response(client_fd, "Error: Missing API call\n");
                return -1;
            }
            int angle = atoi(token);
            if (set_servo_angle(angle) != 0) {
                send_response(client_fd, "Error: Failed to set servo angle\n");
                return -1;
            }
            send_response(client_fd, "OK\n");
            return 0;
        }
    } else if (strcmp(token, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            send_response(client_fd, "Error: Failed to read PIR sensor\n");
            return -1;
        }
        char response[64];
        snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
        send_response(client_fd, response);
        return 0;
    } else {
        log_event("Error: Unknown command: %s", token);
        send_response(client_fd, "Error: Unknown command\n");
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Error opening log file %s: %s", LOG_FILE, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        log_event("Error: Failed to set servo pin %d as output", SERVO_PIN);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_event("Error: Failed to set PIR pin %d as input", PIR_PIN);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_event("Error: Failed to register SIGINT handler: %s", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event("Error: Failed to register SIGTERM handler: %s", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Error: socket creation failed: %s", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("Error: setsockopt failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Error: bind failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        log_event("Error: listen failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Security system started on port %d", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (running) {
                log_event("Error: accept failed: %s", strerror(errno));
            }
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        log_event("Client connected from %s:%d", client_ip, ntohs(client_address.sin_port));

        if (handle_client(client_fd) != 0) {
            log_event("Error handling client");
        }

        close(client_fd);
    }

    log_event("Security system shutting down");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    closelog();
    return EXIT_SUCCESS;
}

