#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BH1750_ADDR          0x29
#define BH1750_PWR_ON        0x01
#define BH1750_PWR_OFF       0x00
#define BH1750_CONT_HRES     0x10
#define BH1750_MEAS_MS       120
#define RELAY_GPIO           23
#define LUX_THRESHOLD        150.0f
#define SAMPLE_INTERVAL_S    2
#define LOG_FILE             "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByteData(handle, BH1750_PWR_ON, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to power off BH1750 (sensor absent or bus error).\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    if (i2cWriteByteData(handle, BH1750_PWR_ON, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to power on BH1750.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BH1750_CONT_HRES, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set BH1750 measurement mode.\n");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out) {
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: I2C read failed (rc=%d).\n", rc);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

static void control_relay(int gpio, float lux) {
    if (lux < LUX_THRESHOLD) {
        if (gpioWrite(gpio, 1) < 0) {
            fprintf(stderr, "Warning: Failed to activate relay on GPIO%d.\n", gpio);
        }
    } else {
        if (gpioWrite(gpio, 0) < 0) {
            fprintf(stderr, "Warning: Failed to deactivate relay on GPIO%d.\n", gpio);
        }
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
