        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);
            control_relay(RELAY_GPIO, lux);
