#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <getopt.h>
#include <pigpio.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 25

#define DEFAULT_THRESHOLD 1000.0f
#define DEFAULT_SCALE 1.0f
#define DEFAULT_DURATION 200
#define MAX_RETRIES 3
#define READ_DELAY_US 1000
#define TARE_DELAY_US 1000000
#define POLL_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static float scale_factor = DEFAULT_SCALE;
static int duration_ms = DEFAULT_DURATION;
static float threshold = DEFAULT_THRESHOLD;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set HX711 DOUT pin %d as input", HX711_DOUT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set HX711 SCK pin %d as output", HX711_SCK_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin %d as output", SOLENOID_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise solenoid pin %d LOW", SOLENOID_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_hx711(long *out_value) {
    long value = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
            syslog(LOG_ERR, "Failed to set HX711 SCK LOW (attempt %d)", retries + 1);
            retries++;
            gpioDelay(READ_DELAY_US);
            continue;
        }

        gpioDelay(1);

        for (int i = 0; i < 24; i++) {
            if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to set HX711 SCK HIGH (attempt %d)", retries + 1);
                retries++;
                gpioDelay(READ_DELAY_US);
                continue;
            }
            gpioDelay(1);

            value <<= 1;
            if (gpioRead(HX711_DOUT_PIN) == 1) {
                value |= 1;
            }

            if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to set HX711 SCK LOW (attempt %d)", retries + 1);
                retries++;
                gpioDelay(READ_DELAY_US);
                continue;
            }
            gpioDelay(1);
        }

        if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
            syslog(LOG_ERR, "Failed to set HX711 SCK HIGH (attempt %d)", retries + 1);
            retries++;
            gpioDelay(READ_DELAY_US);
            continue;
        }
        gpioDelay(1);

        if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
            syslog(LOG_ERR, "Failed to set HX711 SCK LOW (attempt %d)", retries + 1);
            retries++;
            gpioDelay(READ_DELAY_US);
            continue;
        }
        gpioDelay(1);

        value ^= 0x800000;

        if (value & 0x800000) {
            value |= ~0xFFFFFF;
        }

        *out_value = value;
        return 0;
    }

    syslog(LOG_ERR, "Failed to read HX711 after %d retries", MAX_RETRIES);
    return -1;
}

static float calculate_weight(long raw_value) {
    return (float)raw_value / scale_factor;
}

static void activate_solenoid(int duration_ms) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to activate solenoid");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to deactivate solenoid");
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up GPIO and terminating pigpio");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "s:d:t:")) != -1) {
        switch (opt) {
            case 's':
                scale_factor = strtof(optarg, NULL);
                if (scale_factor <= 0.0f) {
                    fprintf(stderr, "Invalid scale factor: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            case 'd':
                duration_ms = atoi(optarg);
                if (duration_ms <= 0) {
                    fprintf(stderr, "Invalid duration: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale_factor] [-d duration_ms] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitoring (scale=%.2f, duration=%dms, threshold=%.2f)",
           scale_factor, duration_ms, threshold);

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    long tare_sum = 0;
    int tare_count = 0;

    syslog(LOG_INFO, "Starting tare procedure (averaging 10 readings)");
    for (int i = 0; i < 10; i++) {
        long raw;
        if (read_hx711(&raw) != 0) {
            syslog(LOG_ERR, "Tare read failed, retrying...");
            gpioDelay(TARE_DELAY_US);
            continue;
        }
        tare_sum += raw;
        tare_count++;
        gpioDelay(TARE_DELAY_US);
    }

    if (tare_count == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        cleanup();
        return EXIT_FAILURE;
    }

    long tare_value = tare_sum / tare_count;
    syslog(LOG_INFO, "Tare complete: average raw value = %ld", tare_value);

    while (running) {
        long raw_sum = 0;
        int valid_readings = 0;

        for (int i = 0; i < 5 && running; i++) {
            long raw;
            if (read_hx711(&raw) != 0) {
                syslog(LOG_ERR, "Read failed, retrying...");
                gpioDelay(READ_DELAY_US);
                continue;
            }
            raw_sum += raw;
            valid_readings++;
            gpioDelay(READ_DELAY_US);
        }

        if (valid_readings == 0) {
            syslog(LOG_ERR, "All readings failed, skipping cycle");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        long raw_average = raw_sum / valid_readings;
        float weight = calculate_weight(raw_average - tare_value);

        syslog(LOG_INFO, "Raw: %ld, Average: %ld, Weight: %.2f g", raw_average, raw_average - tare_value, weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight %.2f g exceeds threshold %.2f g, activating solenoid", weight, threshold);
            activate_solenoid(duration_ms);
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

