/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Controls a relay module on GPIO17 (BCM 17, physical pin 11) via MQTT.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lmosquitto
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>

#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS  "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID     "relay_controller_1"
#define MQTT_TOPIC         "home/lights/control"
#define GPIO_PIN           17
#define GPIO_CHIP          "gpiochip4"   /* BCM GPIO on Pi 4 */
#define KEEP_ALIVE_SEC    60
#define RECONNECT_DELAY_S  5
#define LOOP_DELAY_US      100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    int rc = gpioInitialise();
    if (rc < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed (rc=%d): %s",
               rc, strerror(errno));
        return -1;
    }

    rc = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed (rc=%d): %s",
               GPIO_PIN, rc, strerror(errno));
        gpioTerminate();
        return -1;
    }

    rc = gpioWrite(GPIO_PIN, 0);   /* relay OFF at startup */
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed (rc=%d): %s",
               GPIO_PIN, rc, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure relay is OFF before terminating */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);

        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic %s: %s",
                   MQTT_TOPIC, mosquitto_strerror(mosquitto_errno(mosq)));
        } else {
            syslog(LOG_INFO, "Subscribed to topic %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == 0) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_ERR, "MQTT disconnected with error: %s",
               mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message received on topic %s",
               message->topic);
        return;
    }

    /* NUL-terminate payload for string comparison */
    char payload[256];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        syslog(LOG_INFO, "Received ON command on topic %s", message->topic);
        if (gpioWrite(GPIO_PIN, 1) < 0) {
            syslog(LOG_ERR, "gpioWrite(%d, 1) failed: %s",
                   GPIO_PIN, strerror(errno));
        } else {
            syslog(LOG_INFO, "Relay ON (GPIO%d)", GPIO_PIN);
        }
    } else if (strcmp(payload, "OFF") == 0) {
        syslog(LOG_INFO, "Received OFF command on topic %s", message->topic);
        if (gpioWrite(GPIO_PIN, 0) < 0) {
            syslog(LOG_ERR, "gpioWrite(%d, 0) failed: %s",
                   GPIO_PIN, strerror(errno));
        } else {
            syslog(LOG_INFO, "Relay OFF (GPIO%d)", GPIO_PIN);
        }
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' received on topic %s",
               payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT client                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new() failed: %s", strerror(errno));
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO%d, %s:%d)",
           GPIO_PIN, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, KEEP_ALIVE_SEC, LOOP_DELAY_US);

        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop() failed: %s",
                   mosquitto_strerror(rc));

            /* Attempt to reconnect after a brief delay */
            sleep(RECONNECT_DELAY_S);

            if (g_mosq) {
                mosquitto_disconnect(g_mosq);
                mosquitto_destroy(g_mosq);
                g_mosq = NULL;
            }

            if (mqtt_init() != 0) {
                syslog(LOG_ERR, "MQTT re-initialization failed; will retry");
            }
        }
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down relay controller");
    gpio_cleanup();
    mqtt_cleanup();
    closelog();

    return EXIT_SUCCESS;
}

