#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_PULSE_WIDTH 1000
#define SERVO2_PULSE_WIDTH 1500
#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

#define PWM_FREQUENCY 50
#define PWM_RANGE 255
#define SERVO_HOLD_TIME 3

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int pulse_widths[] = {SERVO1_PULSE_WIDTH, SERVO2_PULSE_WIDTH, SERVO3_PULSE_WIDTH, SERVO4_PULSE_WIDTH, SERVO5_PULSE_WIDTH};

    for (int i = 0; i < 5; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioPWM(pins[i], pulse_widths[i]) != 0) {
            fprintf(stderr, "Error: Failed to set PWM pulse width on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Servo %d: Pulse width set to %d µs\n", i + 1, pulse_widths[i]);

        sleep(SERVO_HOLD_TIME);
    }

    gpioPWM(0, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");

    return EXIT_SUCCESS;
}

