/*
 * Closed-loop DC motor speed control for a miniature vehicle using
 * quadrature encoders and a DRV8833 H-bridge on the Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   Encoder A phase A -> GPIO 4  (BCM)
 *   Encoder A phase B -> GPIO 5  (BCM)
 *   Encoder B phase A -> GPIO 6  (BCM)
 *   Encoder B phase B -> GPIO 12 (BCM)
 *   Motor A PWM     -> GPIO 17 (BCM)
 *   Motor A dir     -> GPIO 18 (BCM)
 *   Motor B PWM     -> GPIO 22 (BCM)
 *   Motor B dir     -> GPIO 23 (BCM)
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM   17
#define MOTOR_A_DIR   18
#define MOTOR_B_PWM   22
#define MOTOR_B_DIR   23

#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

/* ---- Motor parameters ---- */
#define PWM_FREQUENCY  10000   /* Hz — DRV8833 requires 10 kHz */
#define PWM_RANGE      255     /* 8-bit resolution */
#define TICKS_PER_REV  64      /* quadrature encoder: 64 ticks per revolution */
#define ENCODER_COUNTS_PER_REV 1 /* single count per rising edge */
#define TARGET_RPM     50.0
#define LOOP_DELAY_US  100000  /* 100 ms */
#define STALL_TIMEOUT_SEC 2

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_encoder_a_count = 0;
static volatile int32_t g_encoder_b_count = 0;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_speed(int motor_id, double rpm);
static void stop_motors(void);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR for quadrature encoder A phase A                                  */
/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        g_encoder_a_count++;
    } else if (level == 0) {
        g_encoder_a_count--;
    }
}

/* ------------------------------------------------------------------ */
/* ISR for quadrature encoder B phase A                                  */
/* ------------------------------------------------------------------ */
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        g_encoder_b_count++;
    } else if (level == 0) {
        g_encoder_b_count--;
    }
}

/* ------------------------------------------------------------------ */
/* Set motor speed using PI control with anti-windup clamping        */
/* ------------------------------------------------------------------ */
static void set_motor_speed(int motor_id, double rpm)
{
    double error = TARGET_RPM - rpm;
    double integral = integral + error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;

    int pwm_duty = (int)(output + 0.5);
    if (pwm_duty < 0)   pwm_duty = 0;
    if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

    if (motor_id == 1) {
        gpioPWM(MOTOR_A_PWM, pwm_duty);
        gpioWrite(MOTOR_A_DIR, (pwm_duty > 0) ? 1 : 0);
    } else if (motor_id == 2) {
        gpioPWM(MOTOR_B_PWM, pwm_duty);
        gpioWrite(MOTOR_B_DIR, (pwm_duty > 0) ? 1 : 0);
    } else {
        fprintf(stderr, "Error: invalid motor ID %d\n", motor_id);
        return;
    }

    printf("Motor %d: RPM = %.2f, PWM = %d\n", motor_id, rpm, pwm_duty);
}

/* ------------------------------------------------------------------ */
/* Stop both motors                                                   */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
