#define PWM_FREQUENCY  10000   /* Hz — DRV8833 requires 10 kHz */
#define PWM_RANGE      255     /* 8-bit resolution */
#define TICKS_PER_REV  64      /* quadrature encoder: 64 ticks per revolution */
#define ENCODER_COUNTS_PER_REV 1 /* single count per rising edge */
#define TARGET_RPM     50.0
#define LOOP_DELAY_US  100000  /* 100 ms */
#define STALL_TIMEOUT_SEC 2

