#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x29
#define BH1750_PWR_ON 0x01
#define BH1750_PWR_OFF 0x00
#define BH1750_CONT_HRES 0x10
#define BH1750_MEAS_TIME_US 180000
#define RELAY_GPIO 17
#define LUX_LOW 50.0f
#define LUX_HIGH 200.0f
#define POLL_INTERVAL_US 5000000
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    uint8_t cmd = BH1750_CONT_HRES;
    if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(BH1750_MEAS_TIME_US);
    uint8_t buf[2];
    if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to relay GPIO %d\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (init_log() != 0) {
        cleanup();
        return 1;
    }

    int relay_state = 0;
    int relay_active = 0;

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            log_data(lux, relay_state);
            if (lux < LUX_LOW && !relay_active) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    relay_active = 1;
                    printf("Relay activated (Lux = %.2f)\n", lux);
                }
            } else if (lux > LUX_HIGH && relay_active) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    relay_active = 0;
                    printf("Relay deactivated (Lux = %.2f)\n", lux);
                }
            }
        } else {
            fprintf(stderr, "Error reading lux, logging and turning off relay\n");
            if (control_relay(0) == 0) {
                relay_state = 0;
                relay_active = 0;
            }
            log_data(-1.0f, relay_state);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

