    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (init_log() != 0) {
        cleanup();
        return 1;
    }

    int relay_state = 0;
    int relay_active = 0;

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            log_data(lux, relay_state);
            if (lux < LUX_LOW && !relay_active) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    relay_active = 1;
                    printf("Relay activated (Lux = %.2f)\n", lux);
                }
            } else if (lux > LUX_HIGH && relay_active) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    relay_active = 0;
                    printf("Relay deactivated (Lux = %.2f)\n", lux);
                }
            }
        } else {
            fprintf(stderr, "Error reading lux, logging and turning off relay\n");
            if (control_relay(0) == 0) {
                relay_state = 0;
                relay_active = 0;
            }
            log_data(-1.0f, relay_state);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

