    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input */
    ret = gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) failed (code %d)\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially OFF */
    ret = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (ret != 0) {
