    if (ret != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_GPIO, 0) failed (code %d)\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-toggled relay control started. Touch sensor on GPIO %d, relay on GPIO %d.\n",
           TOUCH_SENSOR_GPIO, RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_GPIO) failed (code %d)\n", touch_state);
            break;
        }

        /* Detect rising edge (touch detected) */
        if (touch_state == 1 && last_touch_state == 0) {
            /* Debounce: wait for sensor to stabilize */
            gpioDelay(DEBOUNCE_DELAY_US);

            touch_state = gpioRead(TOUCH_SENSOR_GPIO);
            if (touch_state < 0) {
