                break;
            }

            if (touch_state == 1) {
                relay_state = !relay_state;

                ret = gpioWrite(RELAY_GPIO, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: gpioWrite(RELAY_GPIO, %d) failed (code %d)\n", relay_state, ret);
                    break;
                }

                if (log_event(relay_state) != 0) {
                    break;
                }

                /* Wait for sensor to release before allowing next toggle */
                while (running) {
                    touch_state = gpioRead(TOUCH_SENSOR_GPIO);
                    if (touch_state < 0) {
                        fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_GPIO) failed during wait (code %d)\n", touch_state);
                        break;
