        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

