#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_MS 1000
#define SAMPLE_INTERVAL_S 1
#define FLOW_THRESHOLD_LPM_HIGH 5.0
#define FLOW_THRESHOLD_LPM_LOW 4.5

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flow_line = NULL;
static struct gpiod_line *solenoid_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 1);
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }
    if (flow_line) {
        gpiod_line_release(flow_line);
        flow_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
}

static void flow_sensor_isr(void *context) {
    (void)context;
    struct gpiod_line *line = (struct gpiod_line *)context;
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        log_event("Error reading flow sensor");
        return;
    }
    if (val == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flow_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!flow_line) {
        fprintf(stderr, "Failed to get flow sensor line %d: %s\n", FLOW_SENSOR_PIN, strerror(errno));
        return -1;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        fprintf(stderr, "Failed to get solenoid line %d: %s\n", SOLENOID_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(flow_line, "water_flow") < 0) {
        fprintf(stderr, "Failed to request flow sensor line as input: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(solenoid_line, "water_flow", 1) < 0) {
        fprintf(stderr, "Failed to request solenoid line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void calculate_lpm(float *lpm_out) {
    pthread_mutex_lock(&pulse_mutex);
    uint32_t pulses = pulse_count;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);

    float seconds = (float)SAMPLE_INTERVAL_S;
    float liters = (float)pulses / 60.0f;
    *lpm_out = liters / seconds;
}

static void control_solenoid(float lpm) {
    static int solenoid_state = 1;
    static uint32_t last_change_tick = 0;

    uint32_t now = gpiod_line_get_value(solenoid_line);
    if (now < 0) {
        log_event("Error reading solenoid state");
        return;
    }

    if (now != solenoid_state) {
        if (now == 0) {
            if (lpm > FLOW_THRESHOLD_LPM_HIGH) {
                if (solenoid_state == 1) {
                    if (gpiod_line_set_value(solenoid_line, 0) < 0) {
                        log_event("Error setting solenoid LOW");
                    } else {
                        solenoid_state = 0;
                        log_event("Solenoid turned OFF (flow exceeded threshold)");
                    }
                }
            } else {
                if (solenoid_state == 0) {
                    if (gpiod_line_set_value(solenoid_line, 1) < 0) {
                        log_event("Error setting solenoid HIGH");
                    } else {
                        solenoid_state = 1;
                        log_event("Solenoid turned ON (flow within threshold)");
                    }
                }
            }
        } else {
            if (lpm < FLOW_THRESHOLD_LPM_LOW) {
                if (solenoid_state == 0) {
                    if (gpiod_line_set_value(solenoid_line, 1) < 0) {
                        log_event("Error setting solenoid HIGH");
                    } else {
                        solenoid_state = 1;
                        log_event("Solenoid turned ON (flow below threshold)");
                    }
                }
            } else {
                if (solenoid_state == 1) {
                    if (gpiod_line_set_value(solenoid_line, 0) < 0) {
                        log_event("Error setting solenoid LOW");
                    } else {
                        solenoid_state = 0;
                        log_event("Solenoid turned OFF (flow within hysteresis)");
                    }
                }
            }
        }
        last_change_tick = gpiod_line_get_value(solenoid_line);
    }

    if (solenoid_state == 1 && (gpiod_line_get_value(solenoid_line) == 0 || last_change_tick == 0)) {
        if (gpiod_line_set_value(solenoid_line, 1) < 0) {
            log_event("Error setting solenoid HIGH on startup");
        } else {
            solenoid_state = 1;
            log_event("Solenoid turned ON on startup");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(flow_line, "water_flow") < 0) {
        fprintf(stderr, "Failed to request rising edge events on flow sensor: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_set_debounce_ms(flow_line, DEBOUNCE_MS) < 0) {
        fprintf(stderr, "Failed to set debounce on flow sensor: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_event("Water flow monitoring started");

    while (running) {
        float lpm;
        calculate_lpm(&lpm);
        control_solenoid(lpm);
        sleep(SAMPLE_INTERVAL_S);
    }

    log_event("Water flow monitoring stopped");
    cleanup();
    return 0;
}

