#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVER_PORT 12345
#define LOG_FILE "dispensing_log.json"
#define CONFIG_FILE "config.ini"
#define MAX_WEIGHT_GRAMS 1000.0
#define MIN_WEIGHT_GRAMS 2000.0
#define HX711_TIMEOUT_US 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_SETTLE_DELAY_US 1000000
#define DISPENSE_DELAY_US 1000000
#define CALIBRATION_FACTOR_DEFAULT 1000.0
#define CALIBRATION_FACTOR_MIN 100.0
#define CALIBRATION_FACTOR_MAX 10000.0

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = CALIBRATION_FACTOR_DEFAULT;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *factor) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            char *endptr;
            double val = strtod(value, &endptr);
            if (endptr == value || *endptr != '\0' || val <= CALIBRATION_FACTOR_MIN || val >= CALIBRATION_FACTOR_MAX) {
                fprintf(stderr, "Warning: Invalid calibration_factor value: %s\n", value);
                fclose(fp);
                return -1;
            }
            *factor = val;
        }
    }
    fclose(fp);
    return 0;
}

static int write_config(const char *filename, double factor) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open config file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "calibration_factor=%.2f\n", factor);
    fclose(fp);
    return 0;
}

static int read_calibration_factor(void) {
    if (read_config(CONFIG_FILE, &calibration_factor) != 0) {
        fprintf(stderr, "Using default calibration factor: %.2f\n", calibration_factor);
        return -1;
    }
    printf("Calibration factor: %.2f\n", calibration_factor);
    return 0;
}

static int write_calibration_factor(double factor) {
    if (write_config(CONFIG_FILE, factor) != 0) {
        fprintf(stderr, "Failed to write calibration factor\n");
        return -1;
    }
    calibration_factor = factor;
    printf("Calibration factor set to: %.2f\n", calibration_factor);
    return 0;
}

static int hx711_init(void) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set HX711_DATA_PIN mode\n");
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set HX711_SCK_PIN mode\n");
        return -1;
    }
    gpioWrite(HX711_SCK_PIN, 0);
    return 0;
}

static int hx711_read_raw(long *raw) {
    long value = 0;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data pin stuck HIGH (sensor absent or not ready)\n");
            return -1;
        }
        gpioDelay(1);
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        value = (value << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }
    *raw = value;
    return 0;
}

static double hx711_convert_to_grams(long raw) {
    return (double)raw / calibration_factor;
}

static int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width %d (must be %d-%d us)\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

static int dispense_ingredient(double weight_grams) {
    int pulse_width = (int)(((weight_grams - MIN_WEIGHT_GRAMS) / (MAX_WEIGHT_GRAMS - MIN_WEIGHT_GRAMS)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    if (set_servo_pulse_width(pulse_width) != 0) {
        return -1;
    }
    gpioDelay(DISPENSE_DELAY_US);
    if (set_servo_pulse_width(SERVO_MIN_PULSE_WIDTH) != 0) {
        return -1;
    }
    gpioDelay(SERVO_SETTLE_DELAY_US);
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message ? error_message : "");
    fclose(fp);
    return 0;
}

static int handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        fprintf(stderr, "Error: recv failed: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_received == 0) {
        fprintf(stderr, "Client disconnected\n");
        return -1;
    }
    buffer[bytes_received] = '\0';
    printf("Received: %s\n", buffer);

    char *endptr;
    double target_weight = strtod(buffer, &endptr);
    if (endptr == buffer || *endptr != '\0') {
        fprintf(stderr, "Error: Invalid target weight format\n");
        char error_message[] = "Invalid target weight format";
        log_dispensing_event(0.0, 0.0, error_message);
        send(client_fd, error_message, strlen(error_message), 0);
        return -1;
    }

    long raw;
    if (hx711_read_raw(&raw) != 0) {
        char error_message[] = "HX711 read failed";
        log_dispensing_event(target_weight, 0.0, error_message);
        send(client_fd, error_message, strlen(error_message), 0);
        return -1;
    }

    double actual_weight = hx711_convert_to_grams(raw);
    printf("Target: %.2f g, Actual: %.2f g\n", target_weight, actual_weight);

    if (dispense_ingredient(target_weight) != 0) {
        char error_message[] = "Dispense failed";
        log_dispensing_event(target_weight, actual_weight, error_message);
        send(client_fd, error_message, strlen(error_message), 0);
        return -1;
    }

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Dispensing: Target=%.2f g, Actual=%.2f g", target_weight, actual_weight);
    log_dispensing_event(target_weight, actual_weight, log_message);

    char response[128];
    snprintf(response, sizeof(response), "Dispensing complete: Target=%.2f g, Actual=%.2f g", target_weight, actual_weight);
    send(client_fd, response, strlen(response), 0);
    return 0;
}

static int setup_server(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        fprintf(stderr, "Error: socket failed: %s\n", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Warning: setsockopt failed: %s\n", strerror(errno));
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: bind failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        fprintf(stderr, "Error: listen failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    printf("Listening on 127.0.0.1:%d\n", SERVER_PORT);
    return fd;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (hx711_init() != 0) {
        gpioTerminate();
        return 1;
    }

    if (read_calibration_factor() != 0) {
        if (write_calibration_factor(CALIBRATION_FACTOR_DEFAULT) != 0) {
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    server_fd = setup_server();
    if (server_fd < 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Error: accept failed: %s\n", strerror(errno));
            continue;
        }
        printf("Client connected\n");
        handle_client(client_fd);
        close(client_fd);
        client_fd = -1;
    }

    if (server_fd >= 0) close(server_fd);
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly\n");
    return 0;
}

