#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define PWM_FREQ 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define STEP_ANGLE 10
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int set_servo_angle(struct gpiod_line *line, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / MAX_ANGLE;
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set line high: %s\n", strerror(errno));
        return -1;
    }
    usleep(pulse_width);
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set line low: %s\n", strerror(errno));
        return -1;
    }
    usleep(20000 - pulse_width);
    return 0;
}

static void restore_terminal(void) {
    struct termios old;
    tcgetattr(STDIN_FILENO, &old);
    old.c_lflag &= ~(ICANON | ECHO);
    old.c_cc[VMIN] = 0;
    old.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &old);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int angle = 90;
    int ret;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "servo_control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    restore_terminal();

    printf("Servo control started. Press '+' to increase angle, '-' to decrease angle, 'q' to quit.\n");

    while (keep_running) {
        int c = getchar();
        if (c == EOF) {
            if (feof(stdin)) break;
            perror("getchar");
            break;
        }
        if (c == 'q') break;
        if (c == '+') {
            angle += STEP_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
        } else if (c == '-') {
            angle -= STEP_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
        }
        if (set_servo_angle(line, angle) < 0) {
            break;
        }
        printf("Angle: %d\n", angle);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    restore_terminal();
    return EXIT_SUCCESS;
}

