/*
 * Conveyor belt RPM monitor using an A3144 Hall-effect sensor on a
 * Raspberry Pi 3 Model B+ using pigpio.
 *
 * Wiring:
 *   A3144 VCC  -> 3.3 V (pin 1)
 *   A3144 GND  -> GND  (pin 9)
 *   A3144 OUT  -> GPIO17 (pin 11, BCM) with internal pull-up enabled
 *
 * The two-pole magnet on the motor shaft generates one pulse per revolution.
 *
 * Build:  gcc -O2 -Wall -Wextra -o conveyor_rpm conveyor_rpm.c -lpigpio -lrt
 * Run:    sudo ./conveyor_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

#define GPIO_PIN          17          /* BCM 17, physical pin 11 */
#define DEBOUNCE_US       2000        /* 2 ms debounce window */
#define SAMPLE_INTERVAL_S 5          /* seconds between RPM samples */
#define LOG_FILE          "motor_rpm.log"

/* ------------------------------------------------------------------ */
/* Shared state between signal handler and main loop                 */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t      g_last_tick = 0;   /* monotonic tick of last edge */
static volatile uint32_t      g_pulse_count = 0; /* monotonic pulse count */
static FILE                 *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Monotonic tick (microseconds since boot)                          */
/* ------------------------------------------------------------------ */
static uint32_t monotonic_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (uint32_t)(ts.tv_sec * 1000000UL + ts.tv_nsec / 1000UL);
}

/* ------------------------------------------------------------------ */
/* Edge-triggered callback (runs in pigpio thread)                     */
/* ------------------------------------------------------------------ */
static void hall_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        /* Only act on rising edges (magnet on the motor shaft) */
        return;
    }

    uint32_t diff = tick - g_last_tick;   /* handles 32-bit wrap */
    if (diff < DEBOUNCE_US) {
        return;                       /* within debounce window */
    }

    g_last_tick = tick;
    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Compute RPM from monotonic pulse count                              */
/* ------------------------------------------------------------------ */
static double calculate_rpm(uint32_t pulses, uint32_t interval_us)
{
    if (interval_us == 0) {
        return 0.0;
    }
    return (double)pulses * 60000000.0 / (double)interval_us;
}

/* ------------------------------------------------------------------ */
/* Log one CSV line with timestamp and RPM                              */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
