/*
 * TTP223 capacitive touch sensor → 5 V active-HIGH relay toggle.
 * Board:  Raspberry Pi 5 (BCM numbering)
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   TTP223 VCC  -> 3.3 V (Pin 1)
 *   TTP223 GND  -> GND  (Pin 9)
 *   TTP223 OUT -> BCM GPIO4 (Pin 7)
 *   Relay IN  -> BCM GPIO17 (Pin 11) via 330 Ω resistor
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define RELAY_HOLD_US    1000000 /* 1 s  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int relay_set(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", pin, state);
        return -1;
    }
    return 0;
}

static int relay_off(int pin)
{
    return relay_set(pin, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins ----------------------------------------- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF */
    if (relay_off(RELAY_PIN) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ------------------------------------ */
    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started.\n");
    printf("  Touch sensor : BCM GPIO%d\n", TOUCH_SENSOR_PIN);
    printf("  Relay       : BCM GPIO%d\n", RELAY_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop ------------------------------------------ */
    bool relay_active = false;
    uint32_t relay_off_tick = 0;

    while (g_running) {
        int touch_level = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_level < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_level == 1) {
            /* Rising edge: touch detected */
            if (!relay_active) {
                if (relay_on(RELAY_PIN) != 0) {
                    break;
                }
                relay_active = true;
                relay_off_tick = gpioTick();
            }
        } else {
            /* Falling edge: touch released */
            if (relay_active) {
                relay_off(RELAY_PIN);
                relay_active = false;
            }
        }

        /* Check if relay should be held for the configured hold time */
        if (relay_active) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - relay_off_tick; /* wraps correctly */
            if (elapsed >= RELAY_HOLD_US) {
                relay_off(RELAY_PIN);
                relay_active = false;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");

    /* Ensure relay is OFF before releasing pigpio */
    relay_off(RELAY_PIN);

    /* Release pigpio resources */
    gpioTerminate();

    printf("Touch sensor relay control stopped.\n");
    return EXIT_SUCCESS;
}

