#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

#define DEFAULT_TARGET_FLOW 1.0
#define MIN_TARGET_FLOW 0.0
#define MAX_TARGET_FLOW 10.0

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        uint32_t diff = tick - last_pulse_tick;
        if (diff > 0) {
            pulse_count += diff;
        }
        last_pulse_tick = tick;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d high.\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int set_valve_position(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(VALVE_PWM_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }
    return 0;
}

static double calculate_flow_rate(uint32_t pulse_count, uint32_t elapsed_us) {
    if (elapsed_us == 0) return 0.0;
    double pulses_per_second = (double)pulse_count / (double)elapsed_us * 1000000.0;
    return pulses_per_second * 60.0 / 1000000.0;
}

static int log_data(double flow_rate, int valve_position) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    long timestamp_ms = (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

    if (fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    set_valve_position(0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    double target_flow = DEFAULT_TARGET_FLOW;

    if (argc > 1) {
        char *endptr = NULL;
        target_flow = strtod(argv[1], &endptr);
        if (endptr == argv[1] || *endptr != '\0' || target_flow < MIN_TARGET_FLOW || target_flow > MAX_TARGET_FLOW) {
            fprintf(stderr, "Error: target flow rate must be between %.1f and %.1f L/min.\n", MIN_TARGET_FLOW, MAX_TARGET_FLOW);
            return EXIT_FAILURE;
        }
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open flow_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Closed-loop proportional solenoid valve control started.\n");
    printf("Target flow rate: %.1f L/min\n", target_flow);
