    uint32_t last_log_tick = gpioTick();

    while (running) {
        uint32_t current_tick = gpioTick();
        uint32_t elapsed_us = current_tick - last_log_tick;

        if (elapsed_us >= SAMPLE_INTERVAL_US) {
            uint32_t pulses = pulse_count;
            pulse_count = 0;

            double flow_rate = calculate_flow_rate(pulses, elapsed_us);
            int valve_position = (int)(target_flow * 255.0 / MAX_TARGET_FLOW);

            if (set_valve_position(valve_position) != 0) {
                fprintf(stderr, "Warning: failed to set valve position.\n");
            }

            if (log_data(flow_rate, valve_position) != 0) {
