/*
 * door_access.c — Two-factor door access control for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Lock 1  -> YM‑180 VCC  -> 3.3 V (Pin 1)
 *   Lock 1  -> YM‑180 GND  -> GND  (Pin 9)
 *   Lock 1  -> YM‑180 IN   -> GPIO17 (Pin 11)
 *   Lock 2  -> YM‑180 VCC  -> 3.3 V (Pin 1)
 *   Lock 2  -> YM‑180 GND  -> GND  (Pin 9)
 *   Lock 2  -> YM‑180 IN   -> GPIO27 (Pin 13)
 *   Button -> GPIO22 (Pin 37) — active-low, internal pull-up
 *   RFID   -> SPI0 CE0 (GPIO8), 100 kHz, 8-bit, MSB first
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ----------------------------- Configuration ----------------------------- */

#define LOCK_1_PIN  17
#define LOCK_2_PIN  27
#define BUTTON_PIN  22

#define SPI_DEVICE   "/dev/spidev0.0"
#define SPI_SPEED_HZ 100000U
#define SPI_BITS     8
#define SPI_MODE     SPI_MODE_0

#define LOG_FILE     "/var/log/door_access.log"

#define LOCK_DURATION_SEC 5
#define POLL_INTERVAL_US  10000U   /* 10 ms */
#define DEBOUNCE_MS      50
#define MAX_SPI_RETRIES  4

/* 10-byte valid tag (example, replace with your 10-byte RFID ID) */
static const uint8_t VALID_TAG[10] = {
    0x01, 0x02, 0x03, 0x04, 0x05,
    0x06, 0x07, 0x08, 0x09, 0x0A
};

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log    = NULL;
static int                   g_spi_fd = -1;
static struct gpiod_chip    *g_chip   = NULL;
static struct gpiod_line    *g_lock1  = NULL;
static struct gpiod_line    *g_lock2  = NULL;
static struct gpiod_line    *g_button = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void  log_event(const char *msg);
static void  cleanup(void);
static void  signal_handler(int sig);
static int   init_spi(void);
static int   init_gpio(void);
static int   read_rfid(uint8_t *tag);
static int   control_locks(int engaged);
static int   button_pressed(void);

/* ----------------------------- Logging ----------------------------------- */

static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(g_log, "%s %s\n", ts, msg);
    fflush(g_log);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_lock1) {
        gpiod_line_set_value(g_lock1, 1);   /* engaged (HIGH) */
        gpiod_line_release(g_lock1);
        g_lock1 = NULL;
    }
    if (g_lock2) {
        gpiod_line_set_value(g_lock2, 1);
        gpiod_line_release(g_lock2);
        g_lock2 = NULL;
    }
    if (g_button) {
        gpiod_line_release(g_button);
        g_button = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log) {
        log_event("Program terminated.");
        fclose(g_log);
        g_log = NULL;
    }
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI init ---------------------------------- */

static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- GPIO init ---------------------------------- */

static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return -1;
    }

    g_lock1 = gpiod_chip_get_line(g_chip, LOCK_1_PIN);
    if (!g_lock1) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", LOCK_1_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_lock1, "door_access", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output(lock1) failed: %s\n", strerror(errno));
        return -1;
    }

    g_lock2 = gpiod_chip_get_line(g_chip, LOCK_2_PIN);
    if (!g_lock2) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", LOCK_2_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_lock2, "door_access", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output(lock2) failed: %s\n", strerror(errno));
        return -1;
    }

    g_button = gpiod_chip_get_line(g_chip, BUTTON_PIN);
    if (!g_button) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", BUTTON_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input_flags(g_button, "door_access",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "gpiod_line_request_input_flags(button) failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- RFID read ---------------------------------- */

/*
 * YLI YM-180 SPI protocol (3-byte transfer, MSB first):
 *   Byte 0: 0x01
 *   Byte 1: 0x80 | (tag_length << 4)
 *   Byte 2: tag_length data bytes (10 bytes max)
 *
 * Returns 0 on success (tag copied to *tag), -1 on failure.
 */
static int read_rfid(uint8_t *tag)
{
    uint8_t tx[3] = { 0x01, 0x80, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "SPI_IOC_MESSAGE failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }

        /* YLI YM-180 returns 3 bytes: [0x01, 0x80 | (len << 4), data] */
        if (rx[0] != 0x01 || rx[1] != 0x80) {
            fprintf(stderr, "SPI response header mismatch (attempt %d)\n", attempt + 1);
            usleep(10000);
            continue;
        }

        int tag_len = (rx[1] >> 4) & 0x0F;
        if (tag_len < 1 || tag_len > 10) {
            fprintf(stderr, "Invalid tag length %d (attempt %d)\n", tag_len, attempt + 1);
            usleep(10000);
            continue;
        }

        if (read(g_spi_fd, tag, tag_len) != tag_len) {
            fprintf(stderr, "SPI read failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }

        /* All-zero response: no tag present */
        if (memcmp(tag, VALID_TAG, sizeof(VALID_TAG)) == 0) {
            fprintf(stderr, "No tag detected (attempt %d)\n", attempt + 1);
            usleep(10000);
            continue;
        }

        return 0;
    }

    return -1;
}

/* ----------------------------- Lock control -------------------------------- */

static int control_locks(int engaged)
{
    if (gpiod_line_set_value(g_lock1, engaged ? 0 : 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(lock1, %d) failed: %s\n",
                engaged ? 0 : 1, strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(g_lock2, engaged ? 0 : 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(lock2, %d) failed: %s\n",
                engaged ? 0 : 1, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Button press -------------------------------- */

static int button_pressed(void)
{
    int v = gpiod_line_get_value(g_button);
    if (v < 0) {
        fprintf(stderr, "gpiod_line_get_value(button) failed: %s\n", strerror(errno));
        return 0;
    }
    return (v == 0);   /* active-low */
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    int engaged = 1;   /* engaged (HIGH) at startup */

    while (g_running) {
        if (button_pressed()) {
            log_event("Button pressed — engaging locks.");
            if (control_locks(1) < 0) {
                log_event("Failed to engage locks.");
            } else {
                log_event("Locks engaged.");
                engaged = 1;
            }

            /* Debounce: wait for button release or timeout */
            for (int i = 0; i < DEBOUNCE_MS * 10 && g_running; i++) {
                usleep(10000);
            }

            if (g_running && button_pressed()) {
                log_event("Button pressed again — disengaging locks.");
                if (control_locks(0) < 0) {
                    log_event("Failed to disengage locks.");
                } else {
                    log_event("Locks disengaged.");
                    engaged = 0;
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown: force locks to engaged (HIGH) */
    if (g_lock1) gpiod_line_set_value(g_lock1, 1);
    if (g_lock2) gpiod_line_set_value(g_lock2, 1);
    cleanup();
    return EXIT_SUCCESS;
}

