static struct gpiod_line *encoder1_b_line = NULL;
static struct gpiod_line *encoder2_a_line = NULL;
static struct gpiod_line *encoder2_b_line = NULL;
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
