    if (gpiod_line_request_both_edges_events(encoder1_a_line, "encoder1_a") < 0 ||
        gpiod_line_request_both_edges_events(encoder2_a_line, "encoder2_a") < 0) {
        fprintf(stderr, "Failed to request encoder edge events: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void set_motor_speed(int motor, int speed) {
    if (speed > 100) speed = 100;
    if (speed < -100) speed = -100;

    int duty_ns = (int)(((long)speed * PWM_DUTY_NS) / 100);
    if (duty_ns < 0) duty_ns = 0;
    if (duty_ns > PWM_DUTY_NS) duty_ns = PWM_DUTY_NS;

    if (motor == 1) {
        if (gpiod_line_set_value(motor1_in1_line, speed > 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor1 IN1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_in2_line, speed < 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor1 IN2: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_ena_line, 1) < 0)
            fprintf(stderr, "Failed to enable Motor1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_enb_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor2: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_in3_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor2 IN3: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_in4_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor2 IN4: %s\n", strerror(errno));
    } else if (motor == 2) {
        if (gpiod_line_set_value(motor2_in3_line, speed > 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor2 IN3: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_in4_line, speed < 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor2 IN4: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_enb_line, 1) < 0)
            fprintf(stderr, "Failed to enable Motor2: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_ena_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_in1_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor1 IN1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_in2_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor1 IN2: %s\n", strerror(errno));
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }

    struct timespec duty_ts = {0, duty_ns};
    nanosleep(&duty_ts, NULL);
}

static void stop_motors(void) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

static void cleanup_gpio(void) {
    if (motor1_ena_line) gpiod_line_release(motor1_ena_line);
