static void *encoder_thread1(void *arg) {
    (void)arg;
    struct gpiod_line *line = encoder1_a_line;
    int last_a = 0, last_b = 0;
    int count = 0;

    while (running) {
        int a = gpiod_line_get_value(line);
        if (a < 0) {
            fprintf(stderr, "Failed to read Encoder1 A: %s\n", strerror(errno));
            break;
        }

        int b = gpiod_line_get_value(encoder1_b_line);
        if (b < 0) {
            fprintf(stderr, "Failed to read Encoder1 B: %s\n", strerror(errno));
            break;
        }

        /* Quadrature decoding: A=1, B=1 -> +1, A=1, B=0 -> -1, A=0, B=1 -> +1, A=0, B=0 -> -1 */
        int direction = (a == 1 && b == 1) ? 1 :
                       (a == 1 && b == 0) ? -1 :
                       (a == 0 && b == 1) ? 1 :
                       (a == 0 && b == 0) ? -1 : 0;

        if (direction != 0) {
            pthread_mutex_lock(&encoder1_mutex);
            count += direction;
            pthread_mutex_unlock(&encoder1_mutex);
        }

        last_a = a;
        last_b = b;
        struct timespec sleep_ts = {0, 10000000L}; /* 10 ms */
        nanosleep(&sleep_ts, NULL);
    }

    return NULL;
}

