        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup_gpio();
        return 1;
    }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Motor1_Speed_RPM,Motor2_Speed_RPM,P,I,D,PID_Output\n");
        fflush(log_file);
    }

    pthread_t encoder_thread1_id, encoder_thread2_id;
    if (pthread_create(&encoder_thread1_id, NULL, encoder_thread1, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }
    if (pthread_create(&encoder_thread2_id, NULL, encoder_thread2, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        running = 0;
        pthread_join(encoder_thread1_id, NULL);
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }

    double motor1_speed = 0.0, motor2_speed = 0.0;
    double p = 0.0, i = 0.0, d = 0.0;
    double pid_output = 0.0;

    while (running) {
        struct timespec sample_ts = {0, SAMPLE_PERIOD_NS};
        nanosleep(&sample_ts, NULL);

        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_copy = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_copy = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        double encoder1_rpm = (double)encoder1_count_copy / 6.0;
        double encoder2_rpm = (double)encoder2_count_copy / 6.0;

        double motor1_rpm = encoder1_rpm;
        double motor2_rpm = encoder2_rpm;

        if (motor1_rpm > MAX_SPEED_RPM) motor1_rpm = MAX_SPEED_RPM;
        if (motor1_rpm < MIN_SPEED_RPM) motor1_rpm = MIN_SPEED_RPM;
        if (motor2_rpm > MAX_SPEED_RPM) motor2_rpm = MAX_SPEED_RPM;
        if (motor2_rpm < MIN_SPEED_RPM) motor2_rpm = MIN_SPEED_RPM;

