        p = target_speed - motor1_rpm;
        i += p;
        if (i > MAX_PID_OUTPUT) i = MAX_PID_OUTPUT;
        if (i < MIN_PID_OUTPUT) i = MIN_PID_OUTPUT;

        d = p - (p - d);
        pid_output = p + i + d;

        if (pid_output > MAX_PID_OUTPUT) pid_output = MAX_PID_OUTPUT;
        if (pid_output < MIN_PID_OUTPUT) pid_output = MIN_PID_OUTPUT;

        motor1_speed = pid_output;
        motor2_speed = pid_output;

        set_motor_speed(1, (int)motor1_speed);
        set_motor_speed(2, (int)motor2_speed);

        log_data(motor1_speed, motor2_speed, p, i, d, pid_output);
    }

    stop_motors();
    running = 0;

    pthread_join(encoder_thread1_id, NULL);
    pthread_join(encoder_thread2_id, NULL);

    fclose(log_file);
    cleanup_gpio();

    printf("Program terminated gracefully.\n");
    return 0;
}

