#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19
#define PWM_PERIOD_NS 1000000000L  /* 100 ms */
#define PWM_DUTY_NS 50000000L      /* 50% of period */
#define PWM_FREQ_HZ 100
#define SAMPLE_PERIOD_NS 100000000L /* 100 ms */
#define TARGET_SPEED_RPM 60.0
#define MAX_SPEED_RPM 100.0
#define MIN_SPEED_RPM 0.0
#define MAX_PID_OUTPUT 100.0
#define MIN_PID_OUTPUT -100.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor1_ena_line = NULL;
static struct gpiod_line *motor1_in1_line = NULL;
static struct gpiod_line *motor1_in2_line = NULL;
static struct gpiod_line *motor2_enb_line = NULL;
static struct gpiod_line *motor2_in3_line = NULL;
static struct gpiod_line *motor2_in4_line = NULL;
static struct gpiod_line *encoder1_a_line = NULL;
static struct gpiod_line *encoder1_b_line = NULL;
static struct gpiod_line *encoder2_a_line = NULL;
static struct gpiod_line *encoder2_b_line = NULL;
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int encoder1_count = 0;
static volatile int encoder2_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    motor1_ena_line = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1_line = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2_line = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb_line = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3_line = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4_line = gpiod_chip_get_line(chip, MOTOR2_IN4);
    encoder1_a_line = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_b_line = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_a_line = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_b_line = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor1_ena_line || !motor1_in1_line || !motor1_in2_line ||
        !motor2_enb_line || !motor2_in3_line || !motor2_in4_line ||
        !encoder1_a_line || !encoder1_b_line || !encoder2_a_line || !encoder2_b_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(motor1_ena_line, "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(motor1_in1_line, "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(motor1_in2_line, "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(motor2_enb_line, "motor2_enb", 0) < 0 ||
        gpiod_line_request_output(motor2_in3_line, "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(motor2_in4_line, "motor2_in4", 0) < 0) {
        fprintf(stderr, "Failed to request motor lines as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(encoder1_a_line, "encoder1_a") < 0 ||
        gpiod_line_request_input(encoder1_b_line, "encoder1_b") < 0 ||
        gpiod_line_request_input(encoder2_a_line, "encoder2_a") < 0 ||
        gpiod_line_request_input(encoder2_b_line, "encoder2_b") < 0) {
        fprintf(stderr, "Failed to request encoder lines as input: %s\n", strerror(errno));
        return -1;
    }

    /* Enable both edges on A pins for quadrature decoding */
    if (gpiod_line_request_both_edges_events(encoder1_a_line, "encoder1_a") < 0 ||
        gpiod_line_request_both_edges_events(encoder2_a_line, "encoder2_a") < 0) {
        fprintf(stderr, "Failed to request encoder edge events: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void set_motor_speed(int motor, int speed) {
    if (speed > 100) speed = 100;
    if (speed < -100) speed = -100;

    int duty_ns = (int)(((long)speed * PWM_DUTY_NS) / 100);
    if (duty_ns < 0) duty_ns = 0;
    if (duty_ns > PWM_DUTY_NS) duty_ns = PWM_DUTY_NS;

    if (motor == 1) {
        if (gpiod_line_set_value(motor1_in1_line, speed > 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor1 IN1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_in2_line, speed < 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor1 IN2: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_ena_line, 1) < 0)
            fprintf(stderr, "Failed to enable Motor1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_enb_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor2: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_in3_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor2 IN3: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_in4_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor2 IN4: %s\n", strerror(errno));
    } else if (motor == 2) {
        if (gpiod_line_set_value(motor2_in3_line, speed > 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor2 IN3: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_in4_line, speed < 0 ? 1 : 0) < 0)
            fprintf(stderr, "Failed to set Motor2 IN4: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor2_enb_line, 1) < 0)
            fprintf(stderr, "Failed to enable Motor2: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_ena_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_in1_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor1 IN1: %s\n", strerror(errno));
        if (gpiod_line_set_value(motor1_in2_line, 0) < 0)
            fprintf(stderr, "Failed to disable Motor1 IN2: %s\n", strerror(errno));
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }

    struct timespec duty_ts = {0, duty_ns};
    nanosleep(&duty_ts, NULL);
}

static void stop_motors(void) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

static void cleanup_gpio(void) {
    if (motor1_ena_line) gpiod_line_release(motor1_ena_line);
    if (motor1_in1_line) gpiod_line_release(motor1_in1_line);
    if (motor1_in2_line) gpiod_line_release(motor1_in2_line);
    if (motor2_enb_line) gpiod_line_release(motor2_enb_line);
    if (motor2_in3_line) gpiod_line_release(motor2_in3_line);
    if (motor2_in4_line) gpiod_line_release(motor2_in4_line);
    if (encoder1_a_line) gpiod_line_release(encoder1_a_line);
    if (encoder1_b_line) gpiod_line_release(encoder1_b_line);
    if (encoder2_a_line) gpiod_line_release(encoder2_a_line);
    if (encoder2_b_line) gpiod_line_release(encoder2_b_line);
    if (chip) gpiod_chip_close(chip);
}

static void log_data(double motor1_speed, double motor2_speed,
                     double p, double i, double d,
                     double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_speed, motor2_speed, p, i, d, pid_output);
    fflush(log_file);
}

static void *encoder_thread1(void *arg) {
    (void)arg;
    struct gpiod_line *line = encoder1_a_line;
    int last_a = 0, last_b = 0;
    int count = 0;

    while (running) {
        int a = gpiod_line_get_value(line);
        if (a < 0) {
            fprintf(stderr, "Failed to read Encoder1 A: %s\n", strerror(errno));
            break;
        }

        int b = gpiod_line_get_value(encoder1_b_line);
        if (b < 0) {
            fprintf(stderr, "Failed to read Encoder1 B: %s\n", strerror(errno));
            break;
        }

        /* Quadrature decoding: A=1, B=1 -> +1, A=1, B=0 -> -1, A=0, B=1 -> +1, A=0, B=0 -> -1 */
        int direction = (a == 1 && b == 1) ? 1 :
                       (a == 1 && b == 0) ? -1 :
                       (a == 0 && b == 1) ? 1 :
                       (a == 0 && b == 0) ? -1 : 0;

        if (direction != 0) {
            pthread_mutex_lock(&encoder1_mutex);
            count += direction;
            pthread_mutex_unlock(&encoder1_mutex);
        }

        last_a = a;
        last_b = b;
        struct timespec sleep_ts = {0, 10000000L}; /* 10 ms */
        nanosleep(&sleep_ts, NULL);
    }

    return NULL;
}

static void *encoder_thread2(void *arg) {
    (void)arg;
    struct gpiod_line *line = encoder2_a_line;
    int last_a = 0, last_b = 0;
    int count = 0;

    while (running) {
        int a = gpiod_line_get_value(line);
        if (a < 0) {
            fprintf(stderr, "Failed to read Encoder2 A: %s\n", strerror(errno));
            break;
        }

        int b = gpiod_line_get_value(encoder2_b_line);
        if (b < 0) {
            fprintf(stderr, "Failed to read Encoder2 B: %s\n", strerror(errno));
            break;
        }

        /* Quadrature decoding: A=1, B=1 -> +1, A=1, B=0 -> -1, A=0, B=1 -> +1, A=0, B=0 -> -1 */
        int direction = (a == 1 && b == 1) ? 1 :
                       (a == 1 && b == 0) ? -1 :
                       (a == 0 && b == 1) ? 1 :
                       (a == 0 && b == 0) ? -1 : 0;

        if (direction != 0) {
            pthread_mutex_lock(&encoder2_mutex);
            count += direction;
            pthread_mutex_unlock(&encoder2_mutex);
        }

        last_a = a;
        last_b = b;
        struct timespec sleep_ts = {0, 10000000L}; /* 10 ms */
        nanosleep(&sleep_ts, NULL);
    }

    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup_gpio();
        return 1;
    }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Motor1_Speed_RPM,Motor2_Speed_RPM,P,I,D,PID_Output\n");
        fflush(log_file);
    }

    pthread_t encoder_thread1_id, encoder_thread2_id;
    if (pthread_create(&encoder_thread1_id, NULL, encoder_thread1, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }
    if (pthread_create(&encoder_thread2_id, NULL, encoder_thread2, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        running = 0;
        pthread_join(encoder_thread1_id, NULL);
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }

    double motor1_speed = 0.0, motor2_speed = 0.0;
    double p = 0.0, i = 0.0, d = 0.0;
    double pid_output = 0.0;

    while (running) {
        struct timespec sample_ts = {0, SAMPLE_PERIOD_NS};
        nanosleep(&sample_ts, NULL);

        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_copy = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_copy = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        double encoder1_rpm = (double)encoder1_count_copy / 6.0;
        double encoder2_rpm = (double)encoder2_count_copy / 6.0;

        double motor1_rpm = encoder1_rpm;
        double motor2_rpm = encoder2_rpm;

        if (motor1_rpm > MAX_SPEED_RPM) motor1_rpm = MAX_SPEED_RPM;
        if (motor1_rpm < MIN_SPEED_RPM) motor1_rpm = MIN_SPEED_RPM;
        if (motor2_rpm > MAX_SPEED_RPM) motor2_rpm = MAX_SPEED_RPM;
        if (motor2_rpm < MIN_SPEED_RPM) motor2_rpm = MIN_SPEED_RPM;

        double target_speed = TARGET_SPEED_RPM;

        p = target_speed - motor1_rpm;
        i += p;
        if (i > MAX_PID_OUTPUT) i = MAX_PID_OUTPUT;
        if (i < MIN_PID_OUTPUT) i = MIN_PID_OUTPUT;

        d = p - (p - d);
        pid_output = p + i + d;

        if (pid_output > MAX_PID_OUTPUT) pid_output = MAX_PID_OUTPUT;
        if (pid_output < MIN_PID_OUTPUT) pid_output = MIN_PID_OUTPUT;

        motor1_speed = pid_output;
        motor2_speed = pid_output;

        set_motor_speed(1, (int)motor1_speed);
        set_motor_speed(2, (int)motor2_speed);

        log_data(motor1_speed, motor2_speed, p, i, d, pid_output);
    }

    stop_motors();
    running = 0;

    pthread_join(encoder_thread1_id, NULL);
    pthread_join(encoder_thread2_id, NULL);

    fclose(log_file);
    cleanup_gpio();

    printf("Program terminated gracefully.\n");
    return 0;
}

