#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18
#define LOG_FILE "valve_log.txt"
#define CHIP_NAME "gpiochip4"
#define CONSUMER "water_distribution"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_valve(struct gpiod_line *line, int gpio_pin, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    if (log_event("Valve activated") < 0) {
        fprintf(stderr, "Failed to log valve activation event\n");
    }

    usleep(duration_ms * 1000);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    if (log_event("Valve deactivated") < 0) {
        fprintf(stderr, "Failed to log valve deactivation event\n");
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE_1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE_1_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE_2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE_2_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", VALVE_1_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve2_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", VALVE_2_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (activate_valve(valve1_line, VALVE_1_GPIO, 500) < 0) {
            fprintf(stderr, "Valve 1 activation failed, exiting\n");
            break;
        }
        if (!program_running) break;

        if (log_event("500ms pause") < 0) {
            fprintf(stderr, "Failed to log pause event\n");
        }

        if (!program_running) break;

        if (activate_valve(valve2_line, VALVE_2_GPIO, 1000) < 0) {
            fprintf(stderr, "Valve 2 activation failed, exiting\n");
            break;
        }
        if (!program_running) break;

        if (log_event("1000ms pause") < 0) {
            fprintf(stderr, "Failed to log pause event\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

