#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_FILTER_CONFIG 0x5B
#define MPR121_CHARGE_CONFIG 0x5C
#define MPR121_ELECTRODE_CURRENT 0x5D
#define MPR121_TOUCH_TH_0 0x41
#define MPR121_RELEASE_TH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value) {
    char buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) != 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) != 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) != 0) return -1;

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) != 0) return -1;
    if (mpr121_write_reg(MPR121_FILTER_CONFIG, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_CHARGE_CONFIG, 0x10) != 0) return -1;
    if (mpr121_write_reg(MPR121_ELECTRODE_CURRENT, 0x0A) != 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_TOUCH_TH_0 + (i * 2), 0x0F) != 0) return -1;
        if (mpr121_write_reg(MPR121_RELEASE_TH_0 + (i * 2), 0x0A) != 0) return -1;
    }

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) != 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x20) != 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x00) != 0) return -1;

    if (mpr121_write_reg(MPR121_SOFTRESET, 0x00) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int mpr121_read_touch_status(uint16_t *touch_status) {
    uint8_t low, high;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &low) != 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &high) != 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

