#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15
#define STEP_DELAY_MS 100
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int generate_random_pattern(int *pattern, int *num_steps) {
    int num_steps_generated = 0;
    int duration;

    srand((unsigned int)time(NULL));

    while (num_steps_generated < MIN_STEPS || num_steps_generated > MAX_STEPS) {
        num_steps_generated = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
    }

    *num_steps = num_steps_generated;

    for (int i = 0; i < num_steps_generated; i++) {
        duration = (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1)) + MIN_STEP_DURATION_MS;
        pattern[i] = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        gpioDelay(duration * 1000);
    }

    return 0;
}

static int play_pattern(const int *pattern, int num_steps) {
    for (int i = 0; i < num_steps && running; i++) {
        if (gpioPWM(MOTOR1_GPIO, pattern[i]) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", MOTOR1_GPIO);
            return -1;
        }
        if (gpioPWM(MOTOR2_GPIO, pattern[i]) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", MOTOR2_GPIO);
            return -1;
        }
        gpioDelay(STEP_DELAY_MS * 1000);
    }
    return 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

int main(void) {
    int *pattern = NULL;
    int num_steps = 0;
    int ret_code = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    pattern = (int *)malloc(MAX_STEPS * sizeof(int));
    if (pattern == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for pattern array.\n");
        cleanup();
        return 1;
    }

    printf("Haptic feedback pattern generator started. Press Ctrl+C to exit.\n");

    while (running) {
        if (generate_random_pattern(pattern, &num_steps) != 0) {
            fprintf(stderr, "Error: Failed to generate random pattern.\n");
            ret_code = 1;
            break;
        }

        if (play_pattern(pattern, num_steps) != 0) {
            fprintf(stderr, "Error: Failed to play pattern.\n");
            ret_code = 1;
            break;
        }
    }

    free(pattern);
    cleanup();

    if (ret_code == 0) {
        printf("Haptic feedback pattern generator stopped.\n");
    }

    return ret_code;
}

