#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_TIMEOUT_US 500000
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static double scale = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    long value = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    while (gpioRead(data_pin) == 1) {
        if (++timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data low\n");
            return -1;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(data_pin)) {
            value |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = value;
    return 0;
}

static double calculate_weight(long raw_value) {
    return (double)raw_value / scale + offset;
}

static int load_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open calibration file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data format in '%s'\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int save_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open calibration file '%s' for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%.6f %.6f\n", scale, offset) < 0) {
        fprintf(stderr, "Error: Failed to write calibration data to '%s': %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin) {
    long sum = 0;
    int valid_readings = 0;
    int timeout = 0;

    printf("Starting calibration...\n");

    while (valid_readings < CALIBRATION_SAMPLES && running) {
        long raw_value;
        if (read_hx711(data_pin, clock_pin, &raw_value) == 0) {
            sum += raw_value;
            valid_readings++;
        } else {
            fprintf(stderr, "Calibration read failed, skipping sample\n");
        }

        if (++timeout > CALIBRATION_TIMEOUT_US) {
            fprintf(stderr, "Calibration timeout, aborting\n");
            return -1;
        }
        gpioDelay(1000);
    }

    if (!running) {
        fprintf(stderr, "Calibration interrupted by signal\n");
        return -1;
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Calibration failed: No valid readings obtained\n");
        return -1;
    }

    offset = (double)sum / valid_readings;
    printf("Calibration complete. Offset: %.6f\n", offset);
    return 0;
}

static void log_weight(double weight) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file);
}

static void control_solenoid(double weight) {
    if (weight > 10.0) {
        gpioWrite(SOLENOID_PIN, 1);
        printf("Solenoid engaged (weight: %.2f kg)\n", weight);
    } else {
        gpioWrite(SOLENOID_PIN, 0);
        printf("Solenoid disengaged (weight: %.2f kg)\n", weight);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SOLENOID_PIN, 0);

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        if (load_calibration_data(CALIBRATION_FILE) != 0) {
            fprintf(stderr, "Using default calibration values\n");
            scale = DEFAULT_SCALE;
            offset = DEFAULT_OFFSET;
        }
        fclose(calibration_file);
    } else {
        fprintf(stderr, "Using default calibration values\n");
        scale = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN) != 0) {
        fprintf(stderr, "Calibration failed, using default values\n");
        scale = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) == 0) {
            double weight = calculate_weight(raw_value);
            log_weight(weight);
            control_solenoid(weight);
        } else {
            fprintf(stderr, "Failed to read HX711 sensor, skipping iteration\n");
        }
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();

    if (save_calibration_data(CALIBRATION_FILE) != 0) {
        fprintf(stderr, "Warning: Failed to save calibration data\n");
    }

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

