#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 4
#define MOTOR_IN1_GPIO 17
#define MOTOR_IN2_GPIO 18
#define MOTOR_PWM_GPIO 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_DURATION_US 5000000
#define CHECK_INTERVAL_US 60000000
#define POST_CLOSE_INTERVAL_US 60000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor GPIO %d as input", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 GPIO %d as output", MOTOR_IN1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 GPIO %d as output", MOTOR_IN2_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_PWM_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor PWM GPIO %d as output", MOTOR_PWM_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GPIO %d", MOTOR_PWM_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_PWM_GPIO, 255) != 255) {
        syslog(LOG_ERR, "Failed to set PWM range on GPIO %d", MOTOR_PWM_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int value = gpioRead(RAIN_SENSOR_GPIO);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor GPIO %d", RAIN_SENSOR_GPIO);
            return -1;
        }

        if (value == 0) {
            low_count++;
        }

        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }

    return (low_count >= 3) ? 1 : 0;
}

static void control_motor(int direction) {
    if (direction == 1) {
        gpioWrite(MOTOR_IN1_GPIO, 1);
        gpioWrite(MOTOR_IN2_GPIO, 0);
    } else if (direction == 0) {
        gpioWrite(MOTOR_IN1_GPIO, 0);
        gpioWrite(MOTOR_IN2_GPIO, 1);
    } else {
        gpioWrite(MOTOR_IN1_GPIO, 0);
        gpioWrite(MOTOR_IN2_GPIO, 0);
    }

    if (gpioPWM(MOTOR_PWM_GPIO, PWM_DUTY_CYCLE) != 0) {
        syslog(LOG_ERR, "Failed to start PWM on motor GPIO %d", MOTOR_PWM_GPIO);
    }
}

static void stop_motor(void) {
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioPWM(MOTOR_PWM_GPIO, 0);
}

static void log_event(const char *message) {
    if (log_file == NULL) {
        syslog(LOG_ERR, "Log file is not open");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    stop_motor();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/window_control.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 1) {
            log_event("Rain detected");
            control_motor(1);
            gpioDelay(MOTOR_RUN_DURATION_US);
            stop_motor();
            log_event("Window closed");
        } else if (rain_detected == 0) {
            log_event("Rain stopped");
        } else {
            log_event("Error reading rain sensor");
        }

        gpioDelay(CHECK_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

