#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0f
#define LOCK_DURATION_SEC 5
#define SAMPLE_INTERVAL_SEC 1
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int read_hx711(int dt_pin, int sck_pin, int32_t *out_value) {
    uint32_t start_tick = gpioTick();
    while (gpioRead(dt_pin) == 1) {
        if ((gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            log_event("HX711 timeout waiting for data line to go low");
            return -1;
        }
        gpioDelay(10);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(dt_pin)) {
            value |= 1;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = value;
    return 0;
}

static float calculate_weight(int32_t raw_value) {
    return (float)raw_value / 1000.0f;
}

static void activate_solenoid(int pin, int duration_sec) {
    if (gpioWrite(pin, 1) != 0) {
        log_event("Failed to activate solenoid lock");
        return;
    }
    log_event("Solenoid lock activated");
    sleep(duration_sec);
    if (gpioWrite(pin, 0) != 0) {
        log_event("Failed to deactivate solenoid lock");
    }
    log_event("Solenoid lock deactivated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("stock_events.txt", "a");
    if (!log_file) {
        perror("Failed to open stock_events.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) != 0) {
        log_event("Failed to set HX711 DT pin mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set HX711 SCK pin mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set solenoid pin mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Failed to initialize solenoid pin state");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (running) {
        int32_t raw_value;
        if (read_hx711(HX711_DT_PIN, HX711_SCK_PIN, &raw_value) != 0) {
            log_event("HX711 read error");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float weight = calculate_weight(raw_value);
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Weight: %.2f g", weight);
        log_event(log_msg);

        if (weight < WEIGHT_THRESHOLD) {
            activate_solenoid(SOLENOID_PIN, LOCK_DURATION_SEC);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    log_event("Program terminated");
    gpioWrite(SOLENOID_PIN, 0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

