        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = (int32_t)value;
    return 0;
}

static int calibrate_hx711(float known_weight) {
    int32_t raw_value = 0;
    int32_t zero_value = 0;
    int32_t count = 0;

    printf("Calibrating HX711...\n");
    printf("Place known weight on load cell (in grams) and press Enter: ");
    fflush(stdout);
    if (getchar() == '\n') {
        if (read_hx711(&zero_value) != 0) {
            fprintf(stderr, "Failed to read zero value\n");
            return -1;
        }
        printf("Zero value: %d\n", zero_value);
    } else {
        fprintf(stderr, "Calibration cancelled\n");
        return -1;
    }

    printf("Place known weight on load cell (in grams) and press Enter: ");
    fflush(stdout);
    if (getchar() == '\n') {
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Failed to read raw value\n");
            return -1;
        }
        printf("Raw value: %d\n", raw_value);
    } else {
        fprintf(stderr, "Calibration cancelled\n");
        return -1;
    }

    float calibration_factor = (float)(raw_value - zero_value) / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);

    if (calibration_file != NULL) {
        if (fprintf(calibration_file, "%.6f\n", calibration_factor) < 0) {
            fprintf(stderr, "Failed to write calibration factor to file\n");
            return -1;
        }
        if (fflush(calibration_file) != 0) {
            fprintf(stderr, "Failed to flush calibration file\n");
            return -1;
        }
    } else {
        fprintf(stderr, "Calibration file is not open\n");
        return -1;
    }

    printf("Calibration complete. Calibration factor saved to %s\n", CALIBRATION_FILE);
    return 0;
}

static float read_weight(float calibration_factor) {
    int32_t raw_value = 0;
    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Failed to read HX711 data\n");
        return -1.0f;
    }
    return (float)raw_value / calibration_factor;
}

static void log_security_event(float weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (security_log_file != NULL) {
        if (fprintf(security_log_file, "%s, Weight: %.2f kg\n", timestamp, weight) < 0) {
            fprintf(stderr, "Failed to write to security log file\n");
        }
        if (fflush(security_log_file) != 0) {
            fprintf(stderr, "Failed to flush security log file\n");
        }
    } else {
        fprintf(stderr, "Security log file is not open\n");
    }
}

static void unlock_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid pin high\n");
        return;
    }
    gpioDelay(SOLENOID_LOCK_DURATION_US);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set solenoid pin low\n");
    }
}

static void cleanup(void) {
    if (hx711_handle >= 0) {
        gpioTerminate();
        hx711_handle = -1;
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
        calibration_file = NULL;
    }
    if (security_log_file != NULL) {
        fclose(security_log_file);
        security_log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set HX711 data pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set HX711 clock pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize solenoid pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Failed to open calibration file for writing\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Calibration file created. Enter known weight (in grams): ");
        fflush(stdout);
        float known_weight;
        if (scanf("%f", &known_weight) != 1) {
            fprintf(stderr, "Invalid input for known weight\n");
            fclose(calibration_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (calibrate_hx711(known_weight) != 0) {
            fprintf(stderr, "Calibration failed\n");
            fclose(calibration_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fclose(calibration_file);
        calibration_file = NULL;
    } else {
        float calibration_factor;
        if (fscanf(calibration_file, "%f", &calibration_factor) != 1) {
            fprintf(stderr, "Failed to read calibration factor from file\n");
            fclose(calibration_file);
            calibration_file = NULL;
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fclose(calibration_file);
        calibration_file = NULL;
    }

    security_log_file = fopen(SECURITY_LOG_FILE, "a");
    if (security_log_file == NULL) {
        fprintf(stderr, "Failed to open security log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float weight = read_weight(calibration_factor);
        if (weight < 0.0f) {
            fprintf(stderr, "Failed to read weight, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Threshold exceeded! Unlocking solenoid door.\n");
            log_security_event(weight);
            unlock_solenoid();
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

