#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize GPIO pins and open log file */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure buzzer is off initially */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise buzzer pin %d to LOW\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Activate buzzer for specified duration, then turn off */
static void activate_buzzer(int duration_us) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate buzzer on pin %d\n", BUZZER_PIN);
        return;
    }
    usleep(duration_us);
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate buzzer on pin %d\n", BUZZER_PIN);
    }
}

/* Log motion event with timestamp to file */
static void log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        return;
    }

    if (fprintf(log_file, "%s - Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
    }
}

/* Cleanup GPIO resources and close log file */
static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure buzzer is off before terminating */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Error: Failed to read PIR pin %d\n", PIR_PIN);
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            log_motion_event();
            activate_buzzer(BUZZER_DURATION_US);
        }

        usleep(100000);  /* 100 ms polling interval */
    }

    cleanup();
    printf("Motion detection system stopped.\n");
    return EXIT_SUCCESS;
}

