/*
 * watering_system.c — Raspberry Pi 3 Model B+
 *
 * Reads watering duration from watering.conf (duration=<seconds>) and
 * activates a Parker Hannifin Series 9 General Purpose Miniature Solenoid
 * Valve (12 V, 1.6 W) on GPIO18 (BCM) via an external N-channel MOSFET or
 * relay module.  Validates duration range 1–3600 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering_system watering_system.c -lpigpio -lrt
 * Run:    sudo ./watering_system
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define VALVE_GPIO          18          /* BCM pin connected to solenoid valve */
#define CONFIG_FILE         "watering.conf"
#define MAX_DURATION_SEC    3600
#define MIN_DURATION_SEC    1
#define POLL_INTERVAL_US    100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration file parsing                                           */
/* ------------------------------------------------------------------ */
static int parse_duration(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("fopen(" CONFIG_FILE ")");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: %s is empty or contains no duration line.\n",
                filename);
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline */
    size_t len = strlen(line);
    if (len > 0 && line[len - 1] == '\n') {
        line[len - 1] = '\0';
    }

    /* Strip leading whitespace */
    while (len > 0 && line[0] == ' ') {
        memmove(line, line + 1, len);
        len--;
    }

    /* Strip trailing whitespace */
    while (len > 0 && line[len - 1] == ' ') {
        line[len - 1] = '\0';
        len--;
    }

    /* Trim trailing '=' */
    while (len > 0 && line[len - 1] == '=') {
        line[len - 1] = '\0';
        len--;
    }

    /* Trim leading '=' */
    while (len > 0 && line[0] == '=') {
        memmove(line, line + 1, len);
        len--;
    }

    /* Trim whitespace around duration */
    while (len > 0 && line[0] == ' ') {
        memmove(line, line + 1, len);
        len--;
    }
    while (len > 0 && line[len - 1] == ' ') {
        line[len - 1] = '\0';
        len--;
    }

    if (len == 0) {
        fprintf(stderr, "Error: duration line is empty after trimming.\n");
        return -1;
    }

    char *endptr = NULL;
    long val = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != '\0') {
        fprintf(stderr, "Error: invalid duration format in %s.\n", filename);
        return -1;
    }

    if (val < MIN_DURATION_SEC || val > MAX_DURATION_SEC) {
        fprintf(stderr, "Error: duration %ld out of range [%d, %d].\n",
                val, MIN_DURATION_SEC, MAX_DURATION_SEC);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", VALVE_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Start with valve off (active-low: 0 = valve off) */
    if (gpioWrite(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", VALVE_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure valve is off before releasing */
    gpioWrite(VALVE_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Valve control                                                       */
/* ------------------------------------------------------------------ */
static int activate_valve(void)
{
    if (gpioWrite(VALVE_GPIO, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed.\n", VALVE_GPIO);
        return -1;
    }
    printf("Valve ON (GPIO%d)\n", VALVE_GPIO);
    return 0;
}

static int deactivate_valve(void)
{
    if (gpioWrite(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", VALVE_GPIO);
        return -1;
    }
    printf("Valve OFF (GPIO%d)\n", VALVE_GPIO);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int duration = 0;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Watering system started.  Reading %s for watering duration...\n",
           CONFIG_FILE);

    if (parse_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Error: failed to parse watering duration. Exiting.\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    while (g_running) {
        if (activate_valve() != 0) {
            fprintf(stderr, "Error: failed to activate valve. Exiting.\n");
            break;
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < duration && g_running; i++) {
            gpioDelay(POLL_INTERVAL_US);
        }

        if (!g_running) {
            break;
        }

        if (deactivate_valve() != 0) {
            fprintf(stderr, "Error: failed to deactivate valve. Exiting.\n");
            break;
        }

        /* Print status every 10 seconds */
        if (duration > 10 && (duration % 10) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            if (localtime_r(&now, &tm_info) != NULL) {
                char time_str[32];
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("[%s] Watering cycle complete.\n", time_str);
            } else {
                printf("[unknown time] Watering cycle complete.\n");
            }
        }
    }

    /* Ensure valve is off on exit */
    deactivate_valve();
    cleanup_gpio();

    printf("Watering system stopped.\n");
    return EXIT_SUCCESS;
}

