#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* GPIO pin definitions (BCM numbering) */
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_LEFT_PWM_PIN 22
#define MOTOR_RIGHT_PWM_PIN 23
#define MOTOR_LEFT_DIR_PIN 24
#define MOTOR_RIGHT_DIR_PIN 25

/* PWM parameters */
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

/* Control parameters */
#define BASE_SPEED 150
#define TURN_SPEED 100
#define SAMPLE_INTERVAL_US 10000  /* 10 ms */

/* Global state */
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_gpio(void);
static int read_sensor(int pin);
static int calculate_motor_speeds(int left_sensor, int middle_sensor, int right_sensor);
static void set_motor_speeds(int left_speed, int right_speed);
static void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    /* Stop motors */
    set_motor_speeds(0, 0);

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* Initialize GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    /* Configure sensor pins as inputs with pull-up resistors */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Configure motor PWM pins as outputs */
    if (gpioSetMode(MOTOR_LEFT_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", MOTOR_LEFT_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_RIGHT_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", MOTOR_RIGHT_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_LEFT_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", MOTOR_LEFT_DIR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_RIGHT_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", MOTOR_RIGHT_DIR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_LEFT_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", MOTOR_LEFT_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_RIGHT_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", MOTOR_RIGHT_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_LEFT_PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d\n", MOTOR_LEFT_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_RIGHT_PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d\n", MOTOR_RIGHT_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    /* Initialize motor directions to forward */
    if (gpioWrite(MOTOR_LEFT_DIR_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set initial direction on GPIO%d\n", MOTOR_LEFT_DIR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(MOTOR_RIGHT_DIR_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set initial direction on GPIO%d\n", MOTOR_RIGHT_DIR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Initialize motor speeds to 0 */
    if (gpioPWM(MOTOR_LEFT_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize PWM on GPIO%d\n", MOTOR_LEFT_PWM_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(MOTOR_RIGHT_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize PWM on GPIO%d\n", MOTOR_RIGHT_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read sensor value (active-low: 0 = low, 1 = high) */
static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO%d\n", pin);
        return -1;
    }
    return value;
}

/* Calculate motor speeds based on sensor readings */
static int calculate_motor_speeds(int left_sensor, int middle_sensor, int right_sensor) {
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;

    /* Turn right when only the right sensor is low */
    if (right_sensor == 0) {
        right_speed = TURN_SPEED;
        left_speed = BASE_SPEED / 2;
    }

    /* Turn left when only the left sensor is low */
    if (left_sensor == 0) {
        left_speed = TURN_SPEED;
        right_speed = BASE_SPEED / 2;
    }

    /* Stop when no sensor is low */
    if (left_sensor == 1 && right_sensor == 1 && middle_sensor == 1) {
        left_speed = 0;
        right_speed = 0;
    }

    return left_speed, right_speed;
}

/* Set motor speeds using PWM */
static void set_motor_speeds(int left_speed, int right_speed) {
    if (left_speed >= 0) {
        if (gpioPWM(MOTOR_LEFT_PWM_PIN, left_speed) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO%d\n", MOTOR_LEFT_PWM_PIN);
        }
        if (gpioWrite(MOTOR_LEFT_DIR_PIN, 1) != 0) {
            fprintf(stderr, "Error: Failed to set direction on GPIO%d\n", MOTOR_LEFT_DIR_PIN);
        }
    } else {
        if (gpioPWM(MOTOR_LEFT_PWM_PIN, -left_speed) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO%d\n", MOTOR_LEFT_PWM_PIN);
        }
        if (gpioWrite(MOTOR_LEFT_DIR_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to set direction on GPIO%d\n", MOTOR_LEFT_DIR_PIN);
        }
    }

    if (right_speed >= 0) {
        if (gpioPWM(MOTOR_RIGHT_PWM_PIN, right_speed) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO%d\n", MOTOR_RIGHT_PWM_PIN);
        }
        if (gpioWrite(MOTOR_RIGHT_DIR_PIN, 1) != 0) {
            fprintf(stderr, "Error: Failed to set direction on GPIO%d\n", MOTOR_RIGHT_DIR_PIN);
        }
    } else {
        if (gpioPWM(MOTOR_RIGHT_PWM_PIN, -right_speed) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO%d\n", MOTOR_RIGHT_PWM_PIN);
