#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x29
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime failed");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static int read_lux(float *lux_out) {
    uint8_t buf[2];
    int result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        log_message("Error reading from BH1750 sensor");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_message("Error writing to relay GPIO");
    } else {
        char message[64];
        snprintf(message, sizeof(message), "Relay set to %s", state ? "ON" : "OFF");
        log_message(message);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing relay GPIO state\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Grow light control system started");

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            char message[64];
            snprintf(message, sizeof(message), "Lux: %.2f", lux);
            log_message(message);

            if (lux < LUX_THRESHOLD) {
                control_relay(1);
            } else {
                control_relay(0);
            }
        } else {
            log_message("Error reading lux value, skipping relay control");
        }

        gpioDelay(MEASUREMENT_DELAY_US);
    }

    log_message("Grow light control system stopped");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

