#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_LOCK_PULSE_WIDTH 1000
#define SERVO_UNLOCK_PULSE_WIDTH 2000

#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d, pulse width %d\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
