        fprintf(stderr, "Error: gpioWrite failed to stop motor on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_cleanup(void) {
    if (safe_stop_motor(MOTOR1_PIN) < 0) return -1;
    if (safe_stop_motor(MOTOR2_PIN) < 0) return -1;
    gpioTerminate();
    return 0;
}

