#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <zmq.h>
#include <gpiod.h>

#define SOUND_SENSOR_GPIO_LINE 17
#define ALARM_LED_GPIO_LINE 27
#define ALARM_DURATION_MS 1000
#define POLL_INTERVAL_MS 10
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sound_line, struct gpiod_line **alarm_line) {
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        *chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!*chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    *sound_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_GPIO_LINE);
    if (!*sound_line) {
        perror("gpiod_chip_get_line(sound)");
        return -1;
    }

    *alarm_line = gpiod_chip_get_line(*chip, ALARM_LED_GPIO_LINE);
    if (!*alarm_line) {
        perror("gpiod_chip_get_line(alarm)");
        return -1;
    }

    if (gpiod_line_request_input(*sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        return -1;
    }

    if (gpiod_line_request_output(*alarm_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(alarm)");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *sound_line, struct gpiod_line *alarm_line) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int setup_zmq(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return -1;
    }

    void *socket = zmq_socket(context, ZMQ_REP);
    if (!socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_bind(socket, "tcp://*:5555");
    if (rc != 0) {
        perror("zmq_bind");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }

    return 0;
}

static void cleanup_zmq(void *socket, void *context) {
    if (socket) {
        zmq_close(socket);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

static int read_sound_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return val;
}

static int trigger_alarm(struct gpiod_line *alarm_line) {
    if (gpiod_line_set_value(alarm_line, 1) < 0) {
        perror("gpiod_line_set_value(alarm ON)");
        return -1;
    }

    struct timespec ts = {
        .tv_sec = ALARM_DURATION_MS / 1000,
        .tv_nsec = (ALARM_DURATION_MS % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);

    if (gpiod_line_set_value(alarm_line, 0) < 0) {
        perror("gpiod_line_set_value(alarm OFF)");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode started. Polling GPIO%d every %d ms.\n", SOUND_SENSOR_GPIO_LINE, POLL_INTERVAL_MS);
    } else if (strcmp(mode, "alarm_node") == 0) {
        printf("Alarm node mode started. Listening on tcp://*:5555 for SOUND_ALERTS.\n");
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *alarm_line = NULL;

    if (setup_gpio(&chip, &sound_line, &alarm_line) != 0) {
        cleanup_gpio(chip, sound_line, alarm_line);
        return EXIT_FAILURE;
    }

    void *zmq_context = NULL;
    void *zmq_socket = NULL;

    if (setup_zmq() != 0) {
        cleanup_gpio(chip, sound_line, alarm_line);
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "alarm_node") == 0) {
        zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            perror("zmq_ctx_new");
            cleanup_zmq(zmq_socket, zmq_context);
            cleanup_gpio(chip, sound_line, alarm_line);
            return EXIT_FAILURE;
        }

        zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_socket) {
            perror("zmq_socket");
            zmq_ctx_destroy(zmq_context);
            cleanup_zmq(zmq_socket, zmq_context);
            cleanup_gpio(chip, sound_line, alarm_line);
            return EXIT_FAILURE;
        }

        int rc = zmq_connect(zmq_socket, "tcp://localhost:5555");
        if (rc != 0) {
            perror("zmq_connect");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_zmq(zmq_socket, zmq_context);
            cleanup_gpio(chip, sound_line, alarm_line);
            return EXIT_FAILURE;
        }

        rc = zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (rc != 0) {
            perror("zmq_setsockopt(SUBSCRIBE)");
            zmq_close(zmq_socket);
            zmq_ctx_destroy(zmq_context);
            cleanup_zmq(zmq_socket, zmq_context);
            cleanup_gpio(chip, sound_line, alarm_line);
            return EXIT_FAILURE;
        }

        printf("Alarm node connected to tcp://localhost:5555. Waiting for SOUND_ALERTS...\n");
    }

    while (running) {
        if (strcmp(mode, "sound_sensor") == 0) {
            int sound_val = read_sound_sensor(sound_line);
            if (sound_val < 0) {
                fprintf(stderr, "Error reading sound sensor.\n");
                break;
            }

            if (sound_val == 0) {
                printf("Sound detected! Triggering alarm.\n");
                if (trigger_alarm(alarm_line) != 0) {
                    fprintf(stderr, "Error triggering alarm.\n");
                    break;
                }

                if (strcmp(mode, "alarm_node") == 0) {
                    char msg[16];
                    snprintf(msg, sizeof(msg), "Sound detected!");
                    int rc = zmq_send(zmq_socket, msg, strlen(msg), 0);
                    if (rc != 0) {
                        perror("zmq_send");
                        break;
                    }
                }
            }
        } else if (strcmp(mode, "alarm_node") == 0) {
            char buffer[256];
            int bytes_received = zmq_recv(zmq_socket, buffer, sizeof(buffer) - 1, 0);
            if (bytes_received > 0) {
                buffer[bytes_received] = '\0';
                printf("Received: %s\n", buffer);
            } else if (bytes_received == -1) {
                if (errno == EINTR) {
                    continue;
                }
                perror("zmq_recv");
                break;
            }
        }

        struct timespec ts = {
            .tv_sec = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");

    if (strcmp(mode, "alarm_node") == 0) {
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
    }

    cleanup_zmq(zmq_socket, zmq_context);
    cleanup_gpio(chip, sound_line, alarm_line);

    return EXIT_SUCCESS;
}

