#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define NEC_FRAME_SIZE 32
#define PULSE_BUFFER_SIZE 1024
#define NEC_TIMEOUT_US 100000
#define NEC_BIT_TIMEOUT_US 5000
#define NEC_MIN_SPACE_US 4000
#define NEC_MAX_SPACE_US 16000
#define NEC_MIN_MARK_US 560
#define NEC_MAX_MARK_US 2250
#define NEC_MIN_SPACE_MARK_RATIO 0.5
#define NEC_MAX_SPACE_MARK_RATIO 2.0
#define NEC_MIN_BIT_MARK_RATIO 0.5
#define NEC_MAX_BIT_MARK_RATIO 2.0
#define NEC_MIN_BIT_SPACE_RATIO 0.5
#define NEC_MAX_BIT_SPACE_RATIO 2.0
#define NEC_INVERTED_ADDRESS 0xFFFFFFFF

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static uint32_t pulse_buffer[PULSE_BUFFER_SIZE];
static int pulse_buffer_index = 0;
static int pulse_buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        if (pulse_buffer_index < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_buffer_index++] = tick;
            pulse_buffer_count++;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow, resetting");
            pulse_buffer_index = 0;
            pulse_buffer_count = 0;
        }
    }
}

static int decode_nec(uint32_t *pulses, int count, uint32_t *command) {
    if (count < 34) {
        syslog(LOG_ERR, "Insufficient pulses for NEC frame: %d", count);
        return -1;
    }

    if (pulses[0] < NEC_MIN_MARK_US || pulses[0] > NEC_MAX_MARK_US) {
        syslog(LOG_ERR, "Invalid NEC mark: %u us", pulses[0]);
        return -1;
    }

    if (pulses[1] < NEC_MIN_SPACE_US || pulses[1] > NEC_MAX_SPACE_US) {
        syslog(LOG_ERR, "Invalid NEC space: %u us", pulses[1]);
        return -1;
    }

    uint32_t address = 0;
    uint32_t command_bits = 0;
    int bit_index = 0;

    for (int i = 2; i < count; i++) {
        if (i % 2 == 0) {
            if (pulses[i] < NEC_MIN_SPACE_US || pulses[i] > NEC_MAX_SPACE_US) {
                syslog(LOG_ERR, "Invalid NEC space mark: %u us", pulses[i]);
                return -1;
            }
            if (pulses[i] < NEC_MIN_BIT_SPACE_RATIO * pulses[i - 1] ||
                pulses[i] > NEC_MAX_BIT_SPACE_RATIO * pulses[i - 1]) {
                syslog(LOG_ERR, "Invalid NEC bit space: %u us", pulses[i]);
                return -1;
            }
            if (pulses[i] < NEC_MIN_BIT_MARK_RATIO * pulses[i - 2] ||
                pulses[i] > NEC_MAX_BIT_MARK_RATIO * pulses[i - 2]) {
                syslog(LOG_ERR, "Invalid NEC bit mark: %u us", pulses[i]);
                return -1;
            }
            command_bits <<= 1;
        } else {
            if (pulses[i] < NEC_MIN_MARK_US || pulses[i] > NEC_MAX_MARK_US) {
                syslog(LOG_ERR, "Invalid NEC mark: %u us", pulses[i]);
                return -1;
            }
            if (pulses[i] < NEC_MIN_SPACE_MARK_RATIO * pulses[i - 1] ||
                pulses[i] > NEC_MAX_SPACE_MARK_RATIO * pulses[i - 1]) {
                syslog(LOG_ERR, "Invalid NEC space mark: %u us", pulses[i]);
                return -1;
            }
            if (pulses[i] < NEC_MIN_BIT_MARK_RATIO * pulses[i - 2] ||
                pulses[i] > NEC_MAX_BIT_MARK_RATIO * pulses[i - 2]) {
                syslog(LOG_ERR, "Invalid NEC bit mark: %u us", pulses[i]);
                return -1;
            }
            command_bits |= 1;
        }
        bit_index++;
        if (bit_index == 32) {
            break;
        }
    }

    if (bit_index != 32) {
        syslog(LOG_ERR, "Incomplete NEC frame: %d bits decoded", bit_index);
        return -1;
    }

    *command = command_bits;
    return 0;
}

static int validate_nec_command(uint32_t command) {
    uint32_t inverted = ~command;
    if (inverted == NEC_INVERTED_ADDRESS) {
        syslog(LOG_INFO, "NEC command validated: 0x%08X (inverted)", command);
        return 0;
    }
    syslog(LOG_WARNING, "NEC command invalid: 0x%08X (expected 0x%08X)", command, NEC_INVERTED_ADDRESS);
    return -1;
}

static void publish_mqtt(uint32_t command) {
    char payload[64];
    int len = snprintf(payload, sizeof(payload), "{\"command\":0x%08X}", command);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Failed to format MQTT payload");
        return;
    }

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, len, payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    } else {
        syslog(LOG_INFO, "Published MQTT message: %s", payload);
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_WARNING, "Failed to set pull-up on GPIO %d", IR_GPIO);
    }

    if (gpioSetAlertFunc(IR_GPIO, pulse_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d, MQTT broker %s:%d, topic %s", IR_GPIO, MQTT_BROKER, MQTT_PORT, MQTT_TOPIC);

    while (running) {
        if (pulse_buffer_count >= NEC_FRAME_SIZE) {
            uint32_t command = 0;
            if (decode_nec(pulse_buffer, pulse_buffer_count, &command) == 0) {
                if (validate_nec_command(command) == 0) {
                    publish_mqtt(command);
                }
            }
            pulse_buffer_index = 0;
            pulse_buffer_count = 0;
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down IR decoder");
    cleanup();
    return EXIT_SUCCESS;
}

