#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_1 0x29
#define BH1750_ADDR_2 0x2A
#define BH1750_ADDR_3 0x2B
#define BH1750_ADDR_4 0x2C
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_US 180000
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t terminate = 0;
static int i2c_fds[NUM_SENSORS] = {-1, -1, -1, -1};
static int udp_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_open(int addr) {
