/*
 * airflow_monitor.c — Raspberry Pi Zero W
 *
 * Reads a Honeywell AWM7300V mass airflow sensor via I2C (/dev/i2c-1)
 * and logs flow rate (SLPM) to airflow_log.txt once per second.
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_monitor airflow_monitor.c
 * Run:    ./airflow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "airflow_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

/* AWM7300V register addresses (from datasheet) */
#define AWM7300V_REG_STATUS  0x00
#define AWM7300V_REG_DATA    0x01

/* Expected device ID for AWM7300V */
#define AWM7300V_DEVICE_ID   0x7300

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd of %zu)\n",
                reg, strerror(errno), n, sizeof(buf));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint8_t device_id = 0;

    /* Read device ID to confirm sensor is present */
    if (i2c_read_reg16(fd, AWM7300V_REG_DATA, &device_id) == -1) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", I2C_BUS);
        return -1;
    }

    if (device_id != AWM7300V_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n",
                device_id, AWM7300V_DEVICE_ID);
        return -1;
    }

    printf("AWM7300V detected (device ID: 0x%04X)\n", device_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Flow rate conversion                                                */
/* ------------------------------------------------------------------ */
static float convert_to_slpm(uint16_t raw_flow)
{
    /*
     * AWM7300V: 14-bit flow value is left-justified in the 16-bit
     * data word.  The first two bytes contain the 14-bit value,
     * shifted right by 2 to get the 14-bit value.
     */
    uint16_t flow_value = (raw_flow >> 2) & 0x3FFF;

    /*
     * Conversion factor: 14-bit resolution -> 0.01 SLPM per LSB.
     * The AWM7300V datasheet specifies a typical range of 0.01–0.1 SLPM.
     * For this example, we use a linear mapping between 0 and 100 SLPM.
     */
    return (float)flow_value * 0.01f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        perror("fprintf()");
        return -1;
    }

    if (fflush(fp) == EOF) {
        perror("fflush()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers first so cleanup is safe even if init fails */
    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire exclusive access to the slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_DEVICE_ID) == -1) {
        fprintf(stderr, "Failed to acquire I2C bus access (0x%02X): %s\n",
                AWM7300V_DEVICE_ID, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_sensor(g_i2c_fd) == -1) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging flow rate to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        uint16_t raw_flow = 0;
        int read_ok = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; attempt++) {
            if (i2c_read_reg16(g_i2c_fd, AWM7300V_REG_DATA, &raw_flow) == 0) {
                read_ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES) {
                fprintf(stderr, "I2C read attempt %d/%d failed; retrying in %d ms...\n",
                        attempt, MAX_RETRIES, RETRY_DELAY_MS);
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read flow rate after %d attempts.\n",
                    MAX_RETRIES);
            /* Brief pause before retrying to avoid tight error loop */
            sleep(1);
            continue;
        }

        float flow_rate = convert_to_slpm(raw_flow);

        if (log_flow_rate(g_log_fp, flow_rate) == -1) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep for the sample period, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

