#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define DEFAULT_I2C_ADDRESS 0x48
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MAX_READ_BYTES 6

#define REG_X_AXIS_LSB 0x00
#define REG_X_AXIS_MSB 0x01
#define REG_Y_AXIS_LSB 0x02
#define REG_Y_AXIS_MSB 0x03
#define REG_Z_AXIS_LSB 0x04
#define REG_Z_AXIS_MSB 0x05
#define REG_STATUS 0x06
#define REG_CONFIG 0x07

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[MAX_READ_BYTES];
    if (i2c_read_regs(fd, REG_X_AXIS_LSB, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: Failed to read acceleration data (I2C read failed).\n");
        return -1;
    }
    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)x_raw / 1000.0f;
    *y = (float)y_raw / 1000.0f;
    *z = (float)z_raw / 1000.0f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,ERROR,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d,ERROR,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
}

static void cleanup(void) {
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (error_log_file) {
        fflush(error_log_file);
        fclose(error_log_file);
        error_log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    if (i2c_address < 0x03 || i2c_address > 0x77) {
        fprintf(stderr, "Error: Invalid I2C address 0x%02X (must be 0x03-0x77).\n", i2c_address);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", i2c_address, strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_reg(i2c_fd, REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to configure sensor (I2C write failed).\n");
        cleanup();
        return 1;
    }

    csv_file = fopen(filename, "a");
    if (!csv_file) {
        fprintf(stderr, "Error: Failed to open CSV file %s: %s\n", filename, strerror(errno));
        cleanup();
        return 1;
    }

    error_log_file = fopen("seismic_error.log", "a");
    if (!error_log_file) {
        fprintf(stderr, "Error: Failed to open error log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic sensor data logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            log_data(csv_file, x, y, z);
        } else {
            log_error(error_log_file, "Failed to read acceleration data.");
        }
        sleep(interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

