#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x29
#define BH1750_PWR_ON 0x01
#define BH1750_PWR_OFF 0x00
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_US 180000
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_PWR_ON, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES, 0x01) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, BH1750_PWR_ON, 0x01) < 0) {
            retries++;
            usleep(10000);
            continue;
        }
        usleep(BH1750_CONV_TIME_US);
        if (i2c_write_byte(fd, BH1750_PWR_ON, 0x00) < 0) {
            retries++;
            usleep(10000);
            continue;
        }
        if (i2c_read_bytes(fd, 0x00, buf, 2) < 0) {
            retries++;
            usleep(10000);
            continue;
        }
        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *lux = (float)raw / 1.2f;
        return 0;
    }
    return -1;
}

static int send_multicast(float lux) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Failed to format lux value\n");
        return -1;
    }

    if (sendto(sock_fd, buffer, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Failed to send multicast: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int ttl = 1;
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Failed to set multicast TTL: %s\n", strerror(errno));
        close(sock_fd);
        close(i2c_fd);
        return 1;
    }

    printf("Starting BH1750 light sensor multicast broadcast...\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send multicast\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        } else {
            fprintf(stderr, "Failed to read lux value after %d retries\n", MAX_RETRIES);
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (sock_fd >= 0) close(sock_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

