#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B921600
#define CSV_FILE "radar_data.csv"
#define BUFFER_SIZE 4096
#define MAGIC_WORD_SIZE 8
#define FRAME_HEADER_SIZE 8
#define TLV_HEADER_SIZE 8
#define MAX_OBJECTS 100

#pragma pack(push, 1)
typedef struct {
    uint8_t magic_word[MAGIC_WORD_SIZE];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_num;
    uint32_t chirp_num;
    uint32_t frame_len;
    uint32_t num_detected_obj_x;
    uint32_t num_tlvs_x;
    uint32_t subframe_num_x;
    uint32_t chirp_num_x;
    uint32_t frame_len_x;
} __attribute__((packed)) FrameHeader;

typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) TLVHeader;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
    uint16_t range_idx_x;
    uint16_t doppler_idx_x;
    uint16_t peak_val_x;
    uint16_t x_x;
    uint16_t y_x;
    uint16_t z_x;
} __attribute__((packed)) DetectedObject;
#pragma pack(pop)

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(const uint8_t *buf, size_t len) {
    for (size_t i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) {
            return (int)i;
        }
    }
    return -1;
}

static int process_frame(const uint8_t *frame, size_t frame_len) {
    if (frame_len < FRAME_HEADER_SIZE) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }

    const FrameHeader *header = (const FrameHeader *)frame;
    if (header->total_packet_len < FRAME_HEADER_SIZE ||
        header->total_packet_len > BUFFER_SIZE) {
        fprintf(stderr, "Invalid total packet length: %u\n", header->total_packet_len);
        return -1;
    }

    if (frame_len < header->total_packet_len) {
        fprintf(stderr, "Frame truncated, expected %u bytes, got %zu\n",
                header->total_packet_len, frame_len);
        return -1;
    }

    size_t offset = FRAME_HEADER_SIZE;
    for (uint32_t i = 0; i < header->num_tlvs; i++) {
        if (offset + TLV_HEADER_SIZE > frame_len) {
            fprintf(stderr, "TLV header out of bounds\n");
            return -1;
        }

        const TLVHeader *tlv = (const TLVHeader *)(frame + offset);
        offset += TLV_HEADER_SIZE;

        if (offset + tlv->length > frame_len) {
            fprintf(stderr, "TLV payload out of bounds\n");
            return -1;
        }

        if (tlv->type == 1) {
            if (tlv->length < sizeof(DetectedObject)) {
                fprintf(stderr, "DetectedObject TLV too short\n");
                return -1;
            }

            const DetectedObject *obj = (const DetectedObject *)(frame + offset);
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(csv_file, "%s,%u,%.3f,%.3f\n",
                    timestamp, obj->range_idx,
                    (float)obj->range_idx / 100.0f,
                    (float)obj->doppler_idx / 100.0f);
            fflush(csv_file);
        }

        offset += tlv->length;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        close(uart_fd);
        return 1;
    }

    uint8_t buffer[BUFFER_SIZE];
    size_t buffer_len = 0;

    while (running) {
        if (buffer_len < MAGIC_WORD_SIZE) {
            if (read_exact(uart_fd, buffer + buffer_len, MAGIC_WORD_SIZE - buffer_len) != 0) {
                break;
            }
            buffer_len += MAGIC_WORD_SIZE - buffer_len;
            continue;
        }

        int magic_idx = find_magic_word(buffer, buffer_len);
        if (magic_idx < 0) {
            if (buffer_len >= BUFFER_SIZE) {
                memmove(buffer, buffer + buffer_len - MAGIC_WORD_SIZE, MAGIC_WORD_SIZE);
                buffer_len = MAGIC_WORD_SIZE;
            }
            continue;
        }

        if (magic_idx > 0) {
            memmove(buffer, buffer + magic_idx, buffer_len - magic_idx);
            buffer_len -= magic_idx;
        }

        if (buffer_len < FRAME_HEADER_SIZE) {
            continue;
        }

        const FrameHeader *header = (const FrameHeader *)buffer;
        if (header->total_packet_len > BUFFER_SIZE) {
            fprintf(stderr, "Frame length %u exceeds buffer, discarding\n", header->total_packet_len);
            memmove(buffer, buffer + 1, buffer_len - 1);
            buffer_len--;
            continue;
        }

        if (buffer_len < header->total_packet_len) {
            if (read_exact(uart_fd, buffer + buffer_len, header->total_packet_len - buffer_len) != 0) {
                break;
            }
            buffer_len += header->total_packet_len - buffer_len;
            continue;
        }

        if (process_frame(buffer, header->total_packet_len) != 0) {
            memmove(buffer, buffer + 1, buffer_len - 1);
            buffer_len--;
            continue;
        }

        memmove(buffer, buffer + header->total_packet_len, buffer_len - header->total_packet_len);
        buffer_len -= header->total_packet_len;
    }

    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }

    return 0;
}

