/*
 * AWR1642 mmWave radar range-detection reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   AWR1642 TXD  -> GPIO14 (BCM)
 *   AWR1642 RXD  -> GPIO15 (BCM)
 *   AWR1642 GND  -> GND
 *   AWR1642 VDD  -> 3.3 V
 *
 * UART: /dev/serial0, 115200 8N1, 0.5 s inter-byte timeout, 2 s select timeout.
 *
 * Build: gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c
 */

