#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNPAR | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_lflag &= ~(ECHO | ECHOE | ISIG);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;  /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int send_uart_message(int fd, const char *message) {
    size_t len = strlen(message);
    ssize_t written = write(fd, message, len);
    if (written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)written != len) {
        fprintf(stderr, "Partial write to UART: %zd of %zu bytes\n", written, len);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Monitoring KY-033 sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int left_state = gpioRead(LEFT_SENSOR_PIN);
        int middle_state = gpioRead(MIDDLE_SENSOR_PIN);
        int right_state = gpioRead(RIGHT_SENSOR_PIN);

        if (left_state < 0 || middle_state < 0 || right_state < 0) {
            fprintf(stderr, "Error reading sensor states\n");
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo != NULL) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            } else {
                snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
            }

            printf("[%s] Left: %d, Middle: %d, Right: %d\n",
                   timestamp, left_state, middle_state, right_state);

            if (left_state == 0 && middle_state == 0 && right_state == 0) {
                if (send_uart_message(uart_fd, "EMERGENCY STOP!\n") != 0) {
                    fprintf(stderr, "Failed to send emergency stop message\n");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

